#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Execution {
    pub stdout: String,
    pub stdout_bytes: Vec<u8>,
    pub stderr: String,
    pub exit_code: i32,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RunOptions {
    pub max_execution_steps: Option<usize>,
    pub trace_includes: bool,
    pub request_time: Option<i64>,
    pub query_string: Option<String>,
    pub cookie_header: Option<String>,
    pub upload_files: Option<String>,
    pub request_body: Option<String>,
    pub request_method: Option<String>,
    pub content_type: Option<String>,
}

pub fn run_program(program: &Program) -> CompileResult<Execution> {
    run_program_with_optional_source_file(program, None, RunOptions::default())
}

pub fn run_program_with_source_file(
    program: &Program,
    source_file: impl Into<String>,
) -> CompileResult<Execution> {
    run_program_with_optional_source_file(program, Some(source_file.into()), RunOptions::default())
}

pub fn run_program_with_options(
    program: &Program,
    options: RunOptions,
) -> CompileResult<Execution> {
    run_program_with_optional_source_file(program, None, options)
}

pub fn run_program_with_source_file_and_options(
    program: &Program,
    source_file: impl Into<String>,
    options: RunOptions,
) -> CompileResult<Execution> {
    run_program_with_optional_source_file(program, Some(source_file.into()), options)
}

fn run_program_with_optional_source_file(
    program: &Program,
    source_file: Option<String>,
    options: RunOptions,
) -> CompileResult<Execution> {
    let startup_diagnostics = magic_method_startup_diagnostics(program, source_file.as_deref());
    if let Some(execution) = startup_diagnostics.fatal_execution() {
        return Ok(execution);
    }

    let mut interpreter = match Interpreter::from_program(program, source_file.clone(), options) {
        Ok(interpreter) => interpreter,
        Err(error) => {
            if let Some(execution) =
                append_offset_read_startup_fatal_execution(&error, source_file.as_deref())
            {
                return Ok(execution);
            }
            if let Some(execution) =
                php_token_final_constructor_override_execution(&error, source_file.as_deref())
            {
                return Ok(execution);
            }
            if let Some(mut execution) =
                class_registration_startup_fatal_execution(&error, source_file.as_deref())
            {
                startup_diagnostics.prepend_warnings_to_execution(&mut execution);
                return Ok(execution);
            }
            return Err(error);
        }
    };
    let mut execution = interpreter.run(program)?;
    startup_diagnostics.prepend_warnings_to_execution(&mut execution);
    Ok(execution)
}

fn php_token_final_constructor_override_execution(
    error: &Diagnostic,
    source_file: Option<&str>,
) -> Option<Execution> {
    let method = error
        .message
        .strip_prefix("unsupported class inheritance for ")
        .and_then(|message| message.split_once(": cannot override final method "))
        .map(|(_, method)| method)
        .filter(|method| *method == "PhpToken::__construct()")
        .filter(|_| error.phase == Phase::Runtime)?;
    let file = source_file
        .map(str::to_string)
        .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
        .unwrap_or_else(|| "Command line code".to_string());
    Some(Execution {
        stdout: String::new(),
        stdout_bytes: Vec::new(),
        stderr: format!(
            "Fatal error: Cannot override final method {method} in {file} on line {}",
            error.line
        ),
        exit_code: 255,
    })
}

fn class_registration_startup_fatal_execution(
    error: &Diagnostic,
    source_file: Option<&str>,
) -> Option<Execution> {
    let message = class_registration_startup_fatal_message(error)?;
    let file = source_file
        .map(str::to_string)
        .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
        .unwrap_or_else(|| "Command line code".to_string());
    Some(Execution {
        stdout: String::new(),
        stdout_bytes: Vec::new(),
        stderr: format!("Fatal error: {message} in {file} on line {}", error.line),
        exit_code: 255,
    })
}

fn append_offset_read_startup_fatal_execution(
    error: &Diagnostic,
    source_file: Option<&str>,
) -> Option<Execution> {
    let message = fatal_append_offset_read_message(error)?;
    let file = source_file
        .map(str::to_string)
        .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
        .unwrap_or_else(|| "Command line code".to_string());
    Some(Execution {
        stdout: String::new(),
        stdout_bytes: Vec::new(),
        stderr: format!("Fatal error: {message} in {file} on line {}", error.line),
        exit_code: 255,
    })
}

fn class_registration_startup_fatal_message(error: &Diagnostic) -> Option<String> {
    if error.phase != Phase::Runtime {
        return None;
    }

    let (class_name, reason) = error
        .message
        .strip_prefix("unsupported class inheritance for ")
        .and_then(|message| message.split_once(": "))?;

    if let Some(declaration) = reason.strip_prefix("declaration of ") {
        return Some(format!("Declaration of {declaration}"));
    }

    if let Some(message) = reason.strip_prefix("modifier diagnostic: ") {
        return Some(message.to_string());
    }

    if let Some(message) = reason.strip_prefix("could not check compatibility between ") {
        return Some(format!("Could not check compatibility between {message}"));
    }

    if let Some((class, interface)) = reason
        .strip_prefix("class ")
        .and_then(|reason| reason.split_once(" cannot extend interface "))
    {
        return Some(format!("Class {class} cannot extend interface {interface}"));
    }

    for prefix in ["class ", "interface "] {
        if let Some((class_like, interface)) = reason
            .strip_prefix(prefix)
            .and_then(|reason| reason.split_once(" cannot implement non-interface "))
        {
            return Some(format!(
                "{class_like} cannot implement {interface} - it is not an interface"
            ));
        }
    }

    if let Some((interface, implemented)) = reason
        .strip_prefix("interface ")
        .and_then(|reason| reason.split_once(" cannot implement previously implemented interface "))
    {
        return Some(format!(
            "Interface {interface} cannot implement previously implemented interface {implemented}"
        ));
    }

    if let Some((method, interface)) = reason
        .strip_prefix("method ")
        .and_then(|reason| reason.split_once(" must be public to satisfy interface method "))
    {
        let (interface_name, _) = interface.split_once("::")?;
        return Some(format!(
            "Access level to {method} must be public (as in class {interface_name})"
        ));
    }

    if let Some(message) = class_method_visibility_startup_fatal_message(reason) {
        return Some(message);
    }

    if let Some((missing_count, missing_methods)) =
        class_missing_interface_methods_from_startup_reason(class_name, reason)
    {
        let method_word = if missing_count == 1 {
            "method"
        } else {
            "methods"
        };
        let remaining_word = if missing_count == 1 {
            "method"
        } else {
            "methods"
        };
        return Some(format!(
            "Class {class_name} contains {missing_count} abstract {method_word} and must therefore be declared abstract or implement the remaining {remaining_word} ({missing_methods})"
        ));
    }

    let missing = reason.strip_prefix(&format!(
        "concrete class {class_name} must implement abstract method "
    ))?;
    let method = missing.strip_suffix("()")?;
    let (declaring_class, method_name) = method.split_once("::")?;
    if !declaring_class.eq_ignore_ascii_case(class_name) {
        return None;
    }

    Some(format!(
        "Class {class_name} declares abstract method {method_name}() and must therefore be declared abstract"
    ))
}

fn class_method_visibility_startup_fatal_message(reason: &str) -> Option<String> {
    let (method, parent) = reason
        .strip_prefix("method ")
        .and_then(|reason| reason.split_once(" cannot reduce visibility of inherited "))?;
    let (visibility, parent_method) = parent.split_once(" method ")?;
    let (parent_class, _) = parent_method.split_once("::")?;
    let suffix = if visibility == "protected" {
        " or weaker"
    } else {
        ""
    };
    Some(format!(
        "Access level to {method} must be {visibility} (as in class {parent_class}){suffix}"
    ))
}

fn class_missing_interface_methods_from_startup_reason<'a>(
    class_name: &str,
    reason: &'a str,
) -> Option<(usize, String)> {
    let missing = reason
        .strip_prefix(&format!(
            "concrete class {class_name} must implement interface method "
        ))
        .or_else(|| {
            reason.strip_prefix(&format!(
                "concrete class {class_name} must implement interface methods "
            ))
        })?;
    let mut method_list = Vec::new();
    for method in missing.split(", ") {
        let method = method.strip_suffix("()")?;
        let (interface_name, method_name) = method.split_once("::")?;
        if interface_name.contains("::")
            || method_name.contains("::")
            || method_name
                .chars()
                .any(|ch| ch.is_whitespace() || matches!(ch, '(' | ')' | ';'))
        {
            return None;
        }
        method_list.push(method);
    }
    if method_list.is_empty() {
        return None;
    }
    let count = method_list.len();
    Some((count, method_list.join(", ")))
}

pub fn class_metadata(program: &Program) -> CompileResult<PhpClassTable> {
    Interpreter::from_program(program, None, RunOptions::default())
        .map(|interpreter| interpreter.classes)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScopedArrayCallableKind {
    SelfScope,
    ParentScope,
}

impl ScopedArrayCallableKind {
    fn label(self) -> &'static str {
        match self {
            Self::SelfScope => "self",
            Self::ParentScope => "parent",
        }
    }
}

