    fn spl_fixed_array_size_argument(
        &mut self,
        method_name: &str,
        args: &[Value],
        span: Span,
    ) -> CompileResult<usize> {
        match args.first() {
            Some(Value::Null) => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "SplFixedArray::{method_name}(): Passing null to parameter #1 ($size) of type int is deprecated"
                    ),
                    span,
                )?;
                Ok(0)
            }
            Some(Value::Int(value)) if *value >= 0 => Ok(*value as usize),
            Some(Value::Int(_)) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFixedArray::{method_name}()"),
                    format!(
                        "SplFixedArray::{method_name}(): Argument #1 ($size) must be greater than or equal to 0"
                    ),
                ),
            )),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFixedArray::{method_name}()"),
                    format!(
                        "SplFixedArray::{method_name}(): Argument #1 ($size) must be of type int, {} given",
                        php_type_error_given(other)
                    ),
                ),
            )),
            None => Ok(0),
        }
    }

    fn spl_fixed_array_numeric_string_index(value: &str) -> Option<i64> {
        if value.is_empty() {
            return None;
        }
        let digits = value
            .strip_prefix('-')
            .or_else(|| value.strip_prefix('+'))
            .unwrap_or(value);
        if digits.is_empty() || !digits.as_bytes().iter().all(u8::is_ascii_digit) {
            return None;
        }
        value.parse::<i64>().ok()
    }

    fn spl_fixed_array_index_value(
        method_name: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<i64> {
        match value {
            Value::Int(value) => Ok(*value),
            Value::String(value) => {
                Self::spl_fixed_array_numeric_string_index(value).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("SplFixedArray::{method_name}()"),
                            "Cannot access offset of type string on SplFixedArray",
                        ),
                    )
                })
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFixedArray::{method_name}()"),
                    format!(
                        "Cannot access offset of type {} on SplFixedArray",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn spl_fixed_array_index_in_range(
        method_name: &str,
        index: i64,
        len: usize,
        span: Span,
    ) -> CompileResult<usize> {
        if index < 0 || index as usize >= len {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFixedArray::{method_name}()"),
                    "Index invalid or out of range",
                ),
            ));
        }
        Ok(index as usize)
    }

    fn spl_fixed_array_values_to_array(values: &[Value]) -> PhpArray {
        let mut array = PhpArray::new();
        for (index, value) in values.iter().enumerate() {
            array.insert(ArrayKey::Int(index as i64), value.clone());
        }
        array
    }

    fn create_spl_fixed_array_object_with_values(
        &mut self,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id("SplFixedArray")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("SplFixedArray")))?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("SplFixedArray class id should resolve to class metadata");
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.apply_instance_property_defaults(&object, class_id, span)?;
        self.spl_fixed_arrays
            .insert(object.id(), SplFixedArrayState { values, cursor: 0 });
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn call_spl_fixed_array_static_method_with_values(
        &mut self,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "fromarray" => {
                if !(args.len() == 1 || args.len() == 2) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFixedArray::fromArray()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let source = match args.first() {
                    Some(Value::Array(array)) => array,
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplFixedArray::fromArray()",
                                format!(
                                    "SplFixedArray::fromArray(): Argument #1 ($array) must be of type array, {} given",
                                    other.type_name()
                                ),
                            ),
                        ));
                    }
                    None => unreachable!("arity checked"),
                };
                let preserve_keys = args.get(1).map_or(true, Value::is_truthy);
                let values = if preserve_keys {
                    let mut max_index: Option<usize> = None;
                    for entry in source.entries() {
                        let ArrayKey::Int(index) = &entry.key else {
                            return Err(runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    "SplFixedArray::fromArray()",
                                    "array must contain only positive integer keys",
                                ),
                            ));
                        };
                        if *index < 0 {
                            return Err(runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    "SplFixedArray::fromArray()",
                                    "array must contain only positive integer keys",
                                ),
                            ));
                        }
                        max_index =
                            Some(max_index.map_or(*index as usize, |max| max.max(*index as usize)));
                    }
                    let mut values = vec![Value::Null; max_index.map_or(0, |index| index + 1)];
                    for entry in source.entries() {
                        if let ArrayKey::Int(index) = &entry.key {
                            values[*index as usize] = entry.value_cloned();
                        }
                    }
                    values
                } else {
                    source
                        .entries()
                        .iter()
                        .map(ArrayEntry::value_cloned)
                        .collect()
                };
                self.create_spl_fixed_array_object_with_values(values, span)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("SplFixedArray::{method_name}()")),
            )),
        }
    }

    fn call_spl_fixed_array_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFixedArray::__construct()",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let size = self.spl_fixed_array_size_argument("__construct", &args, span)?;
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.values = vec![Value::Null; size];
                state.cursor = 0;
                Ok(Value::Null)
            }
            "count" | "getsize" => {
                expect_arity(&format!("SplFixedArray::{method_name}"), &args, 0, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                Ok(Value::Int(state.values.len() as i64))
            }
            "setsize" => {
                expect_arity("SplFixedArray::setSize", &args, 1, span)?;
                let size = self.spl_fixed_array_size_argument("setSize", &args, span)?;
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.values.resize(size, Value::Null);
                if state.cursor > state.values.len() {
                    state.cursor = state.values.len();
                }
                Ok(Value::Null)
            }
            "offsetexists" => {
                expect_arity("SplFixedArray::offsetExists", &args, 1, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                let index = Self::spl_fixed_array_index_value(
                    "offsetExists",
                    args.first().expect("arity checked"),
                    span,
                )?;
                Ok(Value::Bool(
                    index >= 0
                        && state
                            .values
                            .get(index as usize)
                            .is_some_and(|value| !matches!(value, Value::Null)),
                ))
            }
            "offsetget" => {
                expect_arity("SplFixedArray::offsetGet", &args, 1, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                let index = Self::spl_fixed_array_index_value(
                    "offsetGet",
                    args.first().expect("arity checked"),
                    span,
                )?;
                let index = Self::spl_fixed_array_index_in_range(
                    "offsetGet",
                    index,
                    state.values.len(),
                    span,
                )?;
                Ok(state.values[index].clone())
            }
            "offsetset" => {
                if args.len() != 2 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFixedArray::offsetSet()",
                            ArityExpectation::Exactly(2),
                            args.len(),
                        ),
                    ));
                }
                if matches!(args.first(), Some(Value::Null)) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFixedArray::offsetSet()",
                            "[] operator not supported for SplFixedArray",
                        ),
                    ));
                }
                let state_len = self
                    .spl_fixed_array_state(&object, method_name, span)?
                    .values
                    .len();
                let index = Self::spl_fixed_array_index_value(
                    "offsetSet",
                    args.first().expect("arity checked"),
                    span,
                )?;
                let index =
                    Self::spl_fixed_array_index_in_range("offsetSet", index, state_len, span)?;
                let value = args.get(1).cloned().unwrap_or(Value::Null);
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.values[index] = value;
                Ok(Value::Null)
            }
            "offsetunset" => {
                expect_arity("SplFixedArray::offsetUnset", &args, 1, span)?;
                let state_len = self
                    .spl_fixed_array_state(&object, method_name, span)?
                    .values
                    .len();
                let index = Self::spl_fixed_array_index_value(
                    "offsetUnset",
                    args.first().expect("arity checked"),
                    span,
                )?;
                let index =
                    Self::spl_fixed_array_index_in_range("offsetUnset", index, state_len, span)?;
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.values[index] = Value::Null;
                Ok(Value::Null)
            }
            "rewind" => {
                expect_arity("SplFixedArray::rewind", &args, 0, span)?;
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.cursor = 0;
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("SplFixedArray::valid", &args, 0, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                Ok(Value::Bool(state.cursor < state.values.len()))
            }
            "key" => {
                expect_arity("SplFixedArray::key", &args, 0, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                Ok(Value::Int(state.cursor as i64))
            }
            "current" => {
                expect_arity("SplFixedArray::current", &args, 0, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                Ok(state
                    .values
                    .get(state.cursor)
                    .cloned()
                    .unwrap_or(Value::Null))
            }
            "next" => {
                expect_arity("SplFixedArray::next", &args, 0, span)?;
                let state = self.spl_fixed_array_state_mut(&object, method_name, span)?;
                state.cursor = state.cursor.saturating_add(1);
                Ok(Value::Null)
            }
            "toarray" => {
                expect_arity("SplFixedArray::toArray", &args, 0, span)?;
                let state = self.spl_fixed_array_state(&object, method_name, span)?;
                Ok(Value::Array(Self::spl_fixed_array_values_to_array(
                    &state.values,
                )))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("SplFixedArray::{method_name}()")),
            )),
        }
    }

    fn call_spl_fixed_array_offset_unset_with_caller_scope(
        &mut self,
        object: PhpObject,
        args: Vec<Value>,
        span: Span,
        caller_scope: &SymbolTable,
    ) -> CompileResult<Value> {
        expect_arity("SplFixedArray::offsetUnset", &args, 1, span)?;
        let state_len = self
            .spl_fixed_array_state(&object, "offsetUnset", span)?
            .values
            .len();
        let index = Self::spl_fixed_array_index_value(
            "offsetUnset",
            args.first().expect("arity checked"),
            span,
        )?;
        let index = Self::spl_fixed_array_index_in_range("offsetUnset", index, state_len, span)?;
        let released = {
            let state = self.spl_fixed_array_state_mut(&object, "offsetUnset", span)?;
            std::mem::replace(&mut state.values[index], Value::Null)
        };
        self.finalize_released_value(Some(released), caller_scope)?;
        Ok(Value::Null)
    }

    fn array_object_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&BoundedArrayObjectState> {
        self.array_objects.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{}::{method_name}()", object.class_name()),
                    "missing ArrayObject/ArrayIterator runtime state",
                ),
            )
        })
    }

    fn array_object_inherited_flags(&self, storage: &Value) -> Option<i64> {
        let Value::Object(object) = storage else {
            return None;
        };
        if !self.is_array_object_storage_object(object) {
            return None;
        }
        self.array_objects
            .get(&object.id())
            .map(|state| state.flags)
    }

    fn array_object_inherited_iterator_class(&self, storage: &Value) -> Option<String> {
        let Value::Object(object) = storage else {
            return None;
        };
        if !self.is_array_object_storage_object(object) {
            return None;
        }
        self.array_objects
            .get(&object.id())
            .map(|state| state.iterator_class.clone())
    }

    fn validate_array_object_iterator_class(
        &self,
        class_name: &str,
        iterator_class: &str,
        span: Span,
    ) -> CompileResult<String> {
        let normalized = iterator_class.strip_prefix('\\').unwrap_or(iterator_class);
        let valid = self
            .classes
            .lookup_class_id(normalized)
            .is_some_and(|class_id| self.is_array_iterator_class_id(class_id));
        if valid {
            return Ok(normalized.to_string());
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{class_name}::__construct()"),
                format!(
                    "Argument #3 ($iteratorClass) must be a class name derived from ArrayIterator, {iterator_class} given"
                ),
            ),
        ))
    }

    fn array_object_constructor_storage(
        &mut self,
        class_name: &str,
        args: &[Value],
        span: Span,
    ) -> CompileResult<(Value, i64, String)> {
        if args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::__construct()"),
                    format!(
                        "{class_name}::__construct() expects at most 3 arguments, {} given",
                        args.len()
                    ),
                ),
            ));
        }

        let storage = match args.first() {
            Some(Value::Array(array)) => Value::Array(array.clone()),
            Some(Value::Object(object)) => Value::Object(object.clone()),
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{class_name}::__construct()"),
                        format!(
                            "{class_name}::__construct(): Argument #1 ($array) must be of type array|object, {} given",
                            other.type_name()
                        ),
                    ),
                ));
            }
            None => Value::Array(PhpArray::new()),
        };

        let flags = match args.get(1) {
            Some(Value::Int(flags)) => *flags,
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{class_name}::__construct()"),
                        format!(
                            "{class_name}::__construct(): Argument #2 ($flags) must be of type int, {} given",
                            other.type_name()
                        ),
                    ),
                ));
            }
            None => self.array_object_inherited_flags(&storage).unwrap_or(0),
        };

        let iterator_class = match args.get(2) {
            Some(Value::String(name)) if !name.is_empty() => {
                self.validate_array_object_iterator_class(class_name, name, span)?
            }
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{class_name}::__construct()"),
                        format!(
                            "{class_name}::__construct(): Argument #3 ($iteratorClass) must be of type string, {} given",
                            other.type_name()
                        ),
                    ),
                ));
            }
            None => self
                .array_object_inherited_iterator_class(&storage)
                .unwrap_or_else(|| "ArrayIterator".to_string()),
        };

        if matches!(storage, Value::Object(_)) {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!(
                    "{class_name}::__construct(): Using an object as a backing array for {class_name} is deprecated, as it allows violating class constraints and invariants"
                ),
                span,
            )?;
        }

        Ok((storage, flags, iterator_class))
    }

    fn insert_object_property_snapshot(
        properties: &mut PhpArray,
        key: ArrayKey,
        property: &ObjectProperty,
    ) {
        if let Some(reference) = property
            .existing_reference_cell()
            .expect("initialized property reference snapshot should not fail")
        {
            properties.insert_reference(key, reference);
        } else {
            properties.insert(key, property.value_cloned());
        }
    }

    fn is_array_object_core_storage_property(
        object: &PhpObject,
        property: &ObjectProperty,
    ) -> bool {
        (object.is_instance_of_class_name("ArrayObject")
            || object.is_instance_of_class_name("ArrayIterator"))
            && property.name() == "storage"
            && property.visibility() == Visibility::Private
            && (property
                .declaring_class_name()
                .eq_ignore_ascii_case("ArrayObject")
                || property
                    .declaring_class_name()
                    .eq_ignore_ascii_case("ArrayIterator"))
    }

    fn public_object_properties_array(object: &PhpObject) -> PhpArray {
        let mut array = PhpArray::new();
        for property in dateperiod_ordered_object_properties(object, object.properties()) {
            if property.visibility() == Visibility::Public
                && property.is_initialized()
                && !property.is_unset()
            {
                Self::insert_object_property_snapshot(
                    &mut array,
                    ArrayKey::String(property.name().to_string()),
                    &property,
                );
            }
        }
        array
    }

    fn initialized_mangled_properties_array_for_object(object: &PhpObject) -> PhpArray {
        let mut array = PhpArray::new();
        for property in dateperiod_ordered_object_properties(object, object.properties()) {
            if property.is_initialized() && !property.is_unset() {
                let key = ArrayKey::String(property.mangled_name());
                if let Some(reference) = property
                    .existing_reference_cell()
                    .expect("initialized property reference snapshot should not fail")
                {
                    array.insert_reference(key, reference);
                } else {
                    array.insert(key, property.value_cloned());
                }
            }
        }
        array
    }

    fn array_object_storage_to_array(
        &self,
        storage: &Value,
        method_name: &str,
        span: Span,
    ) -> CompileResult<PhpArray> {
        match storage {
            Value::Array(array) => Ok(array.clone()),
            Value::Object(object) if self.is_array_object_storage_object(object) => {
                let state = self.array_object_state(object, method_name, span)?;
                self.array_object_storage_to_array(&state.storage, method_name, span)
            }
            Value::Object(object) => Ok(Self::public_object_properties_array(object)),
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("ArrayObject::{method_name}()"),
                    format!(
                        "ArrayObject storage must be array or object in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn array_object_entry_at_cursor(
        &self,
        state: &BoundedArrayObjectState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<Option<ArrayEntry>> {
        let array = self.array_object_storage_to_array(&state.storage, method_name, span)?;
        Ok(array.entries().get(state.cursor).cloned())
    }

    fn array_object_key_to_property_name(key: &ArrayKey) -> String {
        match key {
            ArrayKey::Int(value) => value.to_string(),
            ArrayKey::String(value) => value.clone(),
        }
    }

    fn array_object_read_storage_key(
        &self,
        storage: &Value,
        key: &ArrayKey,
        method_name: &str,
        span: Span,
    ) -> CompileResult<Option<Value>> {
        match storage {
            Value::Array(array) => Ok(array.get_cloned(key.clone())),
            Value::Object(object) if self.is_array_object_storage_object(object) => {
                let state = self.array_object_state(object, method_name, span)?;
                self.array_object_read_storage_key(&state.storage, key, method_name, span)
            }
            Value::Object(object) => {
                Ok(object
                    .read_current_public_property(&Self::array_object_key_to_property_name(key)))
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("ArrayObject::{method_name}()"),
                    format!(
                        "ArrayObject storage must be array or object in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn array_object_array_as_props_enabled(&self, object: &PhpObject) -> bool {
        self.array_objects.get(&object.id()).is_some_and(|state| {
            state.flags & ARRAY_OBJECT_ARRAY_AS_PROPS == ARRAY_OBJECT_ARRAY_AS_PROPS
        })
    }

    fn array_object_property_should_use_storage(
        &self,
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        span: Span,
    ) -> CompileResult<bool> {
        if !self.array_object_array_as_props_enabled(object) {
            return Ok(false);
        }

        match object.property_visibility_from_context(
            property,
            current_class_id,
            protected_class_ids,
        ) {
            Ok(_) => object
                .is_unset_property_from_context(property, current_class_id, protected_class_ids)
                .map_err(|error| runtime_error(span, error)),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => Ok(true),
            Err(error) => Err(runtime_error(span, error)),
        }
    }

    fn emit_array_object_dynamic_property_deprecation_if_needed(
        &mut self,
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        span: Span,
    ) -> CompileResult<()> {
        if !self.is_array_object_storage_object(object)
            || self.array_object_array_as_props_enabled(object)
            || object.has_declared_dynamic_properties_allowance()
        {
            return Ok(());
        }

        match object.property_visibility_from_context(
            property,
            current_class_id,
            protected_class_ids,
        ) {
            Ok(_) => Ok(()),
            Err(error) if Self::is_undefined_property_error(&error) => self
                .emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "Creation of dynamic property {}::${property} is deprecated",
                        object.class_name()
                    ),
                    span,
                ),
            Err(_) => Ok(()),
        }
    }

    fn emit_date_object_dynamic_property_deprecation_if_needed(
        &mut self,
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        span: Span,
    ) -> CompileResult<()> {
        if !(object.is_instance_of_class_name("DateTime")
            || object.is_instance_of_class_name("DateTimeImmutable")
            || object.is_instance_of_class_name("DateTimeZone"))
        {
            return Ok(());
        }

        match object.property_visibility_from_context(
            property,
            current_class_id,
            protected_class_ids,
        ) {
            Ok(_) => Ok(()),
            Err(error) if Self::is_undefined_property_error(&error) => self
                .emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "Creation of dynamic property {}::${property} is deprecated",
                        object.class_name()
                    ),
                    span,
                ),
            Err(_) => Ok(()),
        }
    }

    fn array_object_read_property_from_storage(
        &mut self,
        object: &PhpObject,
        property: &str,
        span: Span,
    ) -> CompileResult<Value> {
        let key = ArrayKey::String(property.to_string());
        let state = self.array_object_state(object, "ARRAY_AS_PROPS", span)?;
        match self.array_object_read_storage_key(&state.storage, &key, "ARRAY_AS_PROPS", span)? {
            Some(value) => Ok(value),
            None => {
                self.emit_display_warning(
                    format!("Undefined array key {}", key.diagnostic_key()),
                    span,
                )?;
                Ok(Value::Null)
            }
        }
    }

    fn array_object_property_storage_is_set(
        &self,
        object: &PhpObject,
        property: &str,
        span: Span,
    ) -> CompileResult<bool> {
        let key = ArrayKey::String(property.to_string());
        let state = self.array_object_state(object, "ARRAY_AS_PROPS", span)?;
        Ok(self
            .array_object_read_storage_key(&state.storage, &key, "ARRAY_AS_PROPS", span)?
            .is_some_and(|value| !matches!(value, Value::Null)))
    }

    fn array_object_write_property_to_storage(
        &mut self,
        object: &PhpObject,
        property: &str,
        value: Value,
        span: Span,
    ) -> CompileResult<()> {
        self.ensure_array_object_not_sorting(object, "ARRAY_AS_PROPS", span)?;
        let mut state = self
            .array_object_state(object, "ARRAY_AS_PROPS", span)?
            .clone();
        self.array_object_write_storage_key(
            &mut state.storage,
            Some(ArrayKey::String(property.to_string())),
            value,
            object.class_name(),
            "ARRAY_AS_PROPS",
            span,
        )?;
        self.sync_array_object_properties(object, &state, span)?;
        self.array_objects.insert(object.id(), state);
        Ok(())
    }

    fn array_object_unset_property_from_storage(
        &mut self,
        object: &PhpObject,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.ensure_array_object_not_sorting(object, "ARRAY_AS_PROPS", span)?;
        let mut state = self
            .array_object_state(object, "ARRAY_AS_PROPS", span)?
            .clone();
        self.array_object_unset_storage_key(
            &mut state.storage,
            &ArrayKey::String(property.to_string()),
            object.class_name(),
            "ARRAY_AS_PROPS",
            span,
        )?;
        self.sync_array_object_properties(object, &state, span)?;
        self.array_objects.insert(object.id(), state);
        Ok(())
    }

    fn array_object_offset_key(
        method_name: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<ArrayKey> {
        ArrayKey::from_value(value).map_err(|error| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("ArrayObject::{method_name}()"),
                    error.message(),
                ),
            )
        })
    }

    fn array_object_write_storage_key(
        &mut self,
        storage: &mut Value,
        key: Option<ArrayKey>,
        value: Value,
        class_name: &str,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        match storage {
            Value::Array(array) => {
                if let Some(key) = key {
                    array.insert(key, value);
                } else {
                    array
                        .append(value)
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(())
            }
            Value::Object(object) if self.is_array_object_storage_object(object) => {
                let mut state = self.array_object_state(object, method_name, span)?.clone();
                self.array_object_write_storage_key(
                    &mut state.storage,
                    key,
                    value,
                    class_name,
                    method_name,
                    span,
                )?;
                self.sync_array_object_properties(object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(())
            }
            Value::Object(object) => {
                let key = key.ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("{class_name}::{method_name}()"),
                            format!(
                                "Cannot append properties to objects, use {class_name}::offsetSet() instead"
                            ),
                        ),
                    )
                })?;
                object.write_forced_public_property(
                    &Self::array_object_key_to_property_name(&key),
                    value,
                );
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    format!(
                        "ArrayObject storage must be array or object in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn array_object_unset_storage_key(
        &mut self,
        storage: &mut Value,
        key: &ArrayKey,
        class_name: &str,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        match storage {
            Value::Array(array) => {
                array.remove(key.clone());
                Ok(())
            }
            Value::Object(object) if self.is_array_object_storage_object(object) => {
                let mut state = self.array_object_state(object, method_name, span)?.clone();
                self.array_object_unset_storage_key(
                    &mut state.storage,
                    key,
                    class_name,
                    method_name,
                    span,
                )?;
                self.sync_array_object_properties(object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(())
            }
            Value::Object(object) => {
                object.unset_forced_public_property(&Self::array_object_key_to_property_name(key));
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    format!(
                        "ArrayObject storage must be array or object in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn sync_array_object_properties(
        &self,
        object: &PhpObject,
        state: &BoundedArrayObjectState,
        span: Span,
    ) -> CompileResult<()> {
        let class_id = self
            .array_object_storage_declaring_class_id(object)
            .ok_or_else(|| {
                runtime_error(span, RuntimeError::undefined_class(object.class_name()))
            })?;
        object
            .write_property_from_context(
                "storage",
                state.storage.clone(),
                Some(class_id),
                &[class_id],
            )
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn sync_array_object_object_properties(
        &self,
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        if let Some(state) = self.array_objects.get(&object.id()) {
            self.sync_array_object_properties(object, state, span)?;
        }
        Ok(())
    }

    fn create_array_iterator_object_with_storage(
        &mut self,
        storage: Value,
        flags: i64,
        iterator_class: String,
        span: Span,
    ) -> CompileResult<Value> {
        let declared_iterator_class = iterator_class.strip_prefix('\\').unwrap_or(&iterator_class);
        let class_id = self
            .classes
            .lookup_class_id(declared_iterator_class)
            .ok_or_else(|| {
                runtime_error(span, RuntimeError::undefined_class(declared_iterator_class))
            })?;
        if !self.is_array_iterator_class_id(class_id) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ArrayObject::getIterator()",
                    format!(
                        "iterator class must be ArrayIterator or a subclass, {declared_iterator_class} given"
                    ),
                ),
            ));
        }
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("iterator class id should resolve to class metadata");
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.apply_instance_property_defaults(&object, class_id, span)?;
        let state = BoundedArrayObjectState {
            storage,
            flags,
            iterator_class,
            cursor: 0,
        };
        self.sync_array_object_properties(&object, &state, span)?;
        self.array_objects.insert(object.id(), state);
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn array_object_sort_flag<'a>(
        class_name: &str,
        method_name: &str,
        args: &'a [Value],
        span: Span,
    ) -> CompileResult<Option<&'a Value>> {
        if args.len() > 1 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    format!("{class_name}::{method_name}()"),
                    ArityExpectation::Between { min: 0, max: 1 },
                    args.len(),
                ),
            ));
        }
        if let Some(flag @ Value::Int(_)) = args.first() {
            Ok(Some(flag))
        } else if let Some(other) = args.first() {
            Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    format!(
                        "Argument #1 ($flags) must be of type int, {} given",
                        other.type_name()
                    ),
                ),
            ))
        } else {
            Ok(None)
        }
    }

    fn array_object_expect_no_args(
        class_name: &str,
        method_name: &str,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        if args.is_empty() {
            return Ok(());
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{class_name}::{method_name}()"),
                format!(
                    "{class_name}::{method_name}() expects exactly 0 arguments, {} given",
                    args.len()
                ),
            ),
        ))
    }

    fn array_object_expect_exact_args(
        class_name: &str,
        method_name: &str,
        args: &[Value],
        expected: usize,
        span: Span,
    ) -> CompileResult<()> {
        if args.len() == expected {
            return Ok(());
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{class_name}::{method_name}()"),
                format!(
                    "{class_name}::{method_name}() expects exactly {expected} argument{}, {} given",
                    if expected == 1 { "" } else { "s" },
                    args.len()
                ),
            ),
        ))
    }

    fn disabled_functions_contains(&self, function_name: &str) -> bool {
        if matches!(function_name.to_ascii_lowercase().as_str(), "exit" | "die") {
            return false;
        }
        self.disable_functions_ini_contains(function_name)
    }

    fn disable_functions_ini_contains(&self, function_name: &str) -> bool {
        self.ini_value("disable_functions").is_some_and(|value| {
            value
                .split(|ch: char| ch == ',' || ch.is_ascii_whitespace())
                .filter(|part| !part.is_empty())
                .any(|part| part.eq_ignore_ascii_case(function_name))
        })
    }

    fn ensure_array_object_sort_enabled(
        &self,
        class_name: &str,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        if !self.disabled_functions_contains(method_name) {
            return Ok(());
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{class_name}::{method_name}()"),
                format!("Cannot call method {method_name} when function {method_name} is disabled"),
            ),
        ))
    }

    fn ensure_array_object_not_sorting(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        if !self.sorting_array_objects.contains(&object.id()) {
            return Ok(());
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{}::{method_name}()", object.class_name()),
                "Modification of ArrayObject during sorting is prohibited",
            ),
        ))
    }

    fn sort_array_object_storage_with_user_comparator(
        &mut self,
        storage: &mut Value,
        operation: UserArraySortOperation,
        callback: &Value,
        class_name: &str,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        match storage {
            Value::Array(array) => {
                self.sort_array_with_user_comparator(array, operation, callback, span)
            }
            Value::Object(storage_object) if !self.is_array_object_storage_object(storage_object) => {
                let mut array = Self::public_object_properties_array(storage_object);
                self.sort_array_with_user_comparator(&mut array, operation, callback, span)?;
                storage_object
                    .replace_public_properties_from_array(&array)
                    .map_err(|error| runtime_error(span, error))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "sorting nested ArrayObject-backed storage is not implemented in the current subset",
                ),
            )),
        }
    }

    fn call_array_object_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let class_name = if self.is_array_iterator_class_id(object.class_id()) {
            "ArrayIterator"
        } else {
            "ArrayObject"
        };
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                let (storage, flags, iterator_class) =
                    self.array_object_constructor_storage(class_name, &args, span)?;
                let state = BoundedArrayObjectState {
                    storage,
                    flags,
                    iterator_class,
                    cursor: 0,
                };
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "count" => {
                expect_arity(&format!("{class_name}::count"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::Int(
                    self.array_object_storage_to_array(&state.storage, method_name, span)?
                        .len() as i64,
                ))
            }
            "getarraycopy" => {
                expect_arity("ArrayObject::getArrayCopy", &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::Array(self.array_object_storage_to_array(
                    &state.storage,
                    method_name,
                    span,
                )?))
            }
            "exchangearray" => {
                expect_arity("ArrayObject::exchangeArray", &args, 1, span)?;
                let replacement = match args.first().expect("arity checked") {
                    Value::Array(array) => Value::Array(array.clone()),
                    Value::Object(object) => Value::Object(object.clone()),
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ArrayObject::exchangeArray()",
                                format!(
                                    "ArrayObject::exchangeArray(): Argument #1 ($array) must be of type array|object, {} given",
                                    other.type_name()
                                ),
                            ),
                        ));
                    }
                };
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                let old = self.array_object_storage_to_array(&state.storage, method_name, span)?;
                state.storage = replacement;
                state.cursor = 0;
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Array(old))
            }
            "getflags" => {
                expect_arity(&format!("{class_name}::getFlags"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::Int(state.flags))
            }
            "setflags" => {
                expect_arity(&format!("{class_name}::setFlags"), &args, 1, span)?;
                let flags = match args.first() {
                    Some(Value::Int(flags)) => *flags,
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("{class_name}::setFlags()"),
                                format!(
                                    "{class_name}::setFlags(): Argument #1 ($flags) must be of type int, {} given",
                                    other.type_name()
                                ),
                            ),
                        ));
                    }
                    None => 0,
                };
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                state.flags = flags;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "getiteratorclass" => {
                expect_arity(&format!("{class_name}::getIteratorClass"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::String(state.iterator_class.clone()))
            }
            "setiteratorclass" => {
                expect_arity(&format!("{class_name}::setIteratorClass"), &args, 1, span)?;
                let iterator_class = match args.first() {
                    Some(Value::String(name)) if !name.is_empty() => {
                        self.validate_array_object_iterator_class(class_name, name, span)?
                    }
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("{class_name}::setIteratorClass()"),
                                format!(
                                    "{class_name}::setIteratorClass(): Argument #1 ($iteratorClass) must be of type string, {} given",
                                    other.type_name()
                                ),
                            ),
                        ));
                    }
                    None => "ArrayIterator".to_string(),
                };
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                state.iterator_class = iterator_class;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "getiterator" => {
                expect_arity("ArrayObject::getIterator", &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?.clone();
                self.create_array_iterator_object_with_storage(
                    Value::Object(object.clone()),
                    state.flags,
                    state.iterator_class,
                    span,
                )
            }
            "offsetexists" => {
                expect_arity(&format!("{class_name}::offsetExists"), &args, 1, span)?;
                let key = Self::array_object_offset_key(
                    "offsetExists",
                    args.first().expect("arity checked"),
                    span,
                )?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    self.array_object_read_storage_key(&state.storage, &key, method_name, span)?
                        .is_some(),
                ))
            }
            "offsetget" => {
                expect_arity(&format!("{class_name}::offsetGet"), &args, 1, span)?;
                let key = Self::array_object_offset_key(
                    "offsetGet",
                    args.first().expect("arity checked"),
                    span,
                )?;
                let state = self.array_object_state(&object, method_name, span)?;
                match self.array_object_read_storage_key(&state.storage, &key, method_name, span)? {
                    Some(value) => Ok(value),
                    None => {
                        self.emit_display_warning(
                            format!("Undefined array key {}", key.diagnostic_key()),
                            span,
                        )?;
                        Ok(Value::Null)
                    }
                }
            }
            "offsetset" => {
                if args.len() != 2 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            format!("{class_name}::offsetSet()"),
                            ArityExpectation::Exactly(2),
                            args.len(),
                        ),
                    ));
                }
                let key = if matches!(args.first(), Some(Value::Null)) {
                    None
                } else {
                    Some(Self::array_object_offset_key(
                        "offsetSet",
                        args.first().expect("arity checked"),
                        span,
                    )?)
                };
                let value = args.get(1).cloned().unwrap_or(Value::Null);
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                self.array_object_write_storage_key(
                    &mut state.storage,
                    key,
                    value,
                    class_name,
                    method_name,
                    span,
                )?;
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "append" => {
                expect_arity(&format!("{class_name}::append"), &args, 1, span)?;
                let value = args.first().cloned().unwrap_or(Value::Null);
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                self.array_object_write_storage_key(
                    &mut state.storage,
                    None,
                    value,
                    class_name,
                    method_name,
                    span,
                )?;
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "offsetunset" => {
                expect_arity(&format!("{class_name}::offsetUnset"), &args, 1, span)?;
                let key = Self::array_object_offset_key(
                    "offsetUnset",
                    args.first().expect("arity checked"),
                    span,
                )?;
                self.ensure_array_object_not_sorting(&object, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                self.array_object_unset_storage_key(
                    &mut state.storage,
                    &key,
                    class_name,
                    method_name,
                    span,
                )?;
                if state.cursor
                    > self
                        .array_object_storage_to_array(&state.storage, method_name, span)?
                        .len()
                {
                    state.cursor = self
                        .array_object_storage_to_array(&state.storage, method_name, span)?
                        .len();
                }
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "rewind" => {
                expect_arity(&format!("{class_name}::rewind"), &args, 0, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                state.cursor = 0;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity(&format!("{class_name}::valid"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    state.cursor
                        < self
                            .array_object_storage_to_array(&state.storage, method_name, span)?
                            .len(),
                ))
            }
            "current" => {
                expect_arity(&format!("{class_name}::current"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(self
                    .array_object_entry_at_cursor(state, method_name, span)?
                    .map(|entry| entry.value_cloned())
                    .unwrap_or(Value::Null))
            }
            "key" => {
                expect_arity(&format!("{class_name}::key"), &args, 0, span)?;
                let state = self.array_object_state(&object, method_name, span)?;
                Ok(self
                    .array_object_entry_at_cursor(state, method_name, span)?
                    .map(|entry| value_from_array_key(&entry.key))
                    .unwrap_or(Value::Null))
            }
            "next" => {
                expect_arity(&format!("{class_name}::next"), &args, 0, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                state.cursor = state.cursor.saturating_add(1);
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "seek" => {
                expect_arity(&format!("{class_name}::seek"), &args, 1, span)?;
                let position = match args.first() {
                    Some(Value::Int(position)) => *position,
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("{class_name}::seek()"),
                                format!("position must be int, got {}", other.type_name()),
                            ),
                        ));
                    }
                    None => 0,
                };
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                let len = self
                    .array_object_storage_to_array(&state.storage, method_name, span)?
                    .len();
                if position < 0 || position as usize >= len {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("{class_name}::seek()"),
                            format!("Seek position {position} is out of range"),
                        ),
                    ));
                }
                state.cursor = position as usize;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Null)
            }
            "asort" | "ksort" | "natsort" | "natcasesort" => {
                let operation = match method_name.to_ascii_lowercase().as_str() {
                    "asort" => PhpArraySortOperation::Asort,
                    "ksort" => PhpArraySortOperation::Ksort,
                    "natsort" => {
                        Self::array_object_expect_no_args(class_name, "natsort", &args, span)?;
                        PhpArraySortOperation::Natsort
                    }
                    "natcasesort" => {
                        Self::array_object_expect_no_args(class_name, "natcasesort", &args, span)?;
                        PhpArraySortOperation::Natcasesort
                    }
                    _ => unreachable!("sort method matched"),
                };
                let flag = if matches!(
                    operation,
                    PhpArraySortOperation::Asort | PhpArraySortOperation::Ksort
                ) {
                    Self::array_object_sort_flag(class_name, method_name, &args, span)?
                } else {
                    None
                };
                self.ensure_array_object_sort_enabled(class_name, method_name, span)?;
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                match &mut state.storage {
                    Value::Array(array) => {
                        array
                            .sort_for_php_builtin(operation, flag)
                            .map_err(|error| runtime_error(span, error))?;
                    }
                    Value::Object(storage_object)
                        if !self.is_array_object_storage_object(storage_object) =>
                    {
                        let mut array = Self::public_object_properties_array(storage_object);
                        array
                            .sort_for_php_builtin(operation, flag)
                            .map_err(|error| runtime_error(span, error))?;
                        storage_object
                            .replace_public_properties_from_array(&array)
                            .map_err(|error| runtime_error(span, error))?;
                    }
                    _ => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("{class_name}::{method_name}()"),
                                "sorting nested ArrayObject-backed storage is not implemented in the current subset",
                            ),
                        ));
                    }
                }
                state.cursor = 0;
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Bool(true))
            }
            "uasort" | "uksort" => {
                Self::array_object_expect_exact_args(class_name, method_name, &args, 1, span)?;
                self.ensure_array_object_sort_enabled(class_name, method_name, span)?;
                let operation = match method_name.to_ascii_lowercase().as_str() {
                    "uasort" => UserArraySortOperation::Uasort,
                    "uksort" => UserArraySortOperation::Uksort,
                    _ => unreachable!("user sort method matched"),
                };
                let callback = args.first().cloned().unwrap_or(Value::Null);
                let mut state = self.array_object_state(&object, method_name, span)?.clone();
                self.sorting_array_objects.insert(object.id());
                let result = self.sort_array_object_storage_with_user_comparator(
                    &mut state.storage,
                    operation,
                    &callback,
                    class_name,
                    method_name,
                    span,
                );
                self.sorting_array_objects.remove(&object.id());
                result?;
                state.cursor = 0;
                self.sync_array_object_properties(&object, &state, span)?;
                self.array_objects.insert(object.id(), state);
                Ok(Value::Bool(true))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("{class_name}::{method_name}()")),
            )),
        }
    }

    fn call_array_object_method_with_values_and_uncaught_frame(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let callable = format!("{}->{method_name}", object.class_name());
        let result =
            self.call_array_object_method_with_values(object, method_name, args.clone(), span);
        if let Err(error) = &result {
            self.record_pending_uncaught_internal_call_frame(callable, span, &args, error);
        }
        result
    }

    fn by_reference_foreach_variable_root(
        &mut self,
        name: &str,
        scope: &SymbolTable,
        span: Span,
    ) -> CompileResult<ForeachArrayRoot> {
        match scope.read_static(name, span)? {
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "Iterator") =>
            {
                Err(runtime_error(
                    span,
                    RuntimeError::invalid_foreach(
                        "An iterator cannot be used with foreach by reference",
                    ),
                ))
            }
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "IteratorAggregate") =>
            {
                let iterator =
                    self.call_required_iterator_method(object, "getIterator", span)?;
                match iterator {
                    Value::Object(iterator)
                        if self
                            .classes
                            .implements_interface(iterator.class_id(), "Iterator") =>
                    {
                        Err(runtime_error(
                            span,
                            RuntimeError::invalid_foreach(
                                "An iterator cannot be used with foreach by reference",
                            ),
                        ))
                    }
                    Value::Object(iterator) if self.is_traversable_object(&iterator) => {
                        Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "foreach",
                                "SPL Traversable object by-reference iteration is not implemented in the current subset",
                            ),
                        ))
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(format!(
                            "IteratorAggregate::getIterator() must return a Traversable object for by-reference foreach in PHP, got {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            Value::Object(object) if self.is_traversable_object(&object) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "foreach",
                    "Traversable object by-reference iteration is not implemented in the current subset",
                ),
            )),
            Value::Object(_) => Ok(ForeachArrayRoot::ObjectProperties {
                object: name.to_string(),
            }),
            _ => Ok(ForeachArrayRoot::Static {
                name: name.to_string(),
                keys: Vec::new(),
            }),
        }
    }

    fn foreach_object_property_alias_root(
        &self,
        object_name: &str,
        property: &str,
        scope: &SymbolTable,
        span: Span,
    ) -> CompileResult<ArrayOffsetAliasRoot> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let visibility = match object.property_visibility_from_context(
            property,
            current_class_id,
            &protected_class_ids,
        ) {
            Ok(visibility) => visibility,
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {
                object
                    .bind_dynamic_public_property_reference_cell(property)
                    .map_err(|_| runtime_error(span, error))?;
                Visibility::Public
            }
            Err(error) => return Err(runtime_error(span, error)),
        };

        Ok(if visibility == Visibility::Public {
            ArrayOffsetAliasRoot::PublicObjectProperty {
                object: object_name.to_string(),
                property: property.to_string(),
            }
        } else {
            ArrayOffsetAliasRoot::ContextObjectProperty {
                object: object_name.to_string(),
                property: property.to_string(),
                current_class_id,
                protected_class_ids,
            }
        })
    }

    fn this_object_property_alias_root(
        &self,
        property: &str,
        scope: &SymbolTable,
        span: Span,
    ) -> CompileResult<ArrayOffsetAliasRoot> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static("this", span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let visibility = match object.property_visibility_from_context(
            property,
            current_class_id,
            &protected_class_ids,
        ) {
            Ok(visibility) => visibility,
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {
                object
                    .bind_dynamic_public_property_reference_cell(property)
                    .map_err(|_| runtime_error(span, error))?;
                Visibility::Public
            }
            Err(error) => return Err(runtime_error(span, error)),
        };

        Ok(if visibility == Visibility::Public {
            ArrayOffsetAliasRoot::PublicObjectProperty {
                object: "this".to_string(),
                property: property.to_string(),
            }
        } else {
            ArrayOffsetAliasRoot::ContextObjectProperty {
                object: "this".to_string(),
                property: property.to_string(),
                current_class_id,
                protected_class_ids,
            }
        })
    }

    fn non_direct_foreach_object_property_alias_root(
        &mut self,
        target: &Expr,
        property: &str,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<ArrayOffsetAliasRoot> {
        let (_, root) =
            self.non_direct_object_property_alias_root_with_temp(target, property, scope, span)?;
        Ok(root)
    }

    fn non_direct_object_property_alias_root_with_temp(
        &mut self,
        target: &Expr,
        property: &str,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<(String, ArrayOffsetAliasRoot)> {
        let temp_name = self.non_direct_object_holder_temp(target, property, scope, span)?;
        let root = self.context_object_property_alias_root(&temp_name, property, span, scope)?;
        Ok((temp_name, root))
    }

    fn non_direct_object_holder_temp(
        &mut self,
        target: &Expr,
        property: &str,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<String> {
        let source_snapshot = scope.public_array_copy_source_snapshot();
        let target_value = self.evaluate(target, scope)?;
        scope.restore_unchanged_public_array_copy_sources(source_snapshot);
        let object = match target_value {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let temp_name = self.next_foreach_temporary_array_name();
        scope.write_static(&temp_name, Value::Object(object));
        Ok(temp_name)
    }

    fn non_direct_foreach_object_property_array_root(
        &mut self,
        target: &Expr,
        property: &str,
        keys: Vec<ArrayKey>,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<ForeachArrayRoot> {
        let target_value = self.evaluate(target, scope)?;
        let object = match target_value {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let temp_name = self.next_foreach_temporary_array_name();
        scope.write_static(&temp_name, Value::Object(object));
        if let Some((alias, _)) = self
            .evaluate_object_property_array_access_reference_source_alias(
                &temp_name,
                property,
                keys.clone(),
                span,
                scope,
            )?
        {
            return Ok(ForeachArrayRoot::Alias {
                root: alias.root,
                keys: alias.keys,
            });
        }

        let root = self.foreach_object_property_alias_root(&temp_name, property, scope, span)?;
        Ok(ForeachArrayRoot::Alias { root, keys })
    }

    fn by_reference_foreach_root(
        &mut self,
        iterable: &Expr,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<ForeachArrayRoot> {
        match iterable {
            Expr::Variable(name, _) => self.by_reference_foreach_variable_root(name, scope, span),
            Expr::Index { target, index, .. } => {
                if let Some((name, indices)) =
                    Self::collect_direct_variable_array_index_path(target, index)
                {
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(self.evaluate_array_key(index, scope)?);
                    }

                    if let Some((alias, _)) = self
                        .evaluate_direct_array_access_reference_source_alias(
                            name,
                            keys.clone(),
                            span,
                            scope,
                        )?
                    {
                        return Ok(ForeachArrayRoot::Alias {
                            root: alias.root,
                            keys: alias.keys,
                        });
                    }

                    if name == "GLOBALS" {
                        let (global_name, keys) =
                            SymbolTable::split_globals_reference_path(keys, span)?;
                        return Ok(ForeachArrayRoot::Global {
                            name: global_name,
                            keys,
                        });
                    }

                    return Ok(ForeachArrayRoot::Static {
                        name: name.to_string(),
                        keys,
                    });
                }

                if let Some((object_name, property, indices)) =
                    Self::collect_direct_object_property_array_index_path(target, index)
                {
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(self.evaluate_array_key(index, scope)?);
                    }
                    if let Some((alias, _)) = self
                        .evaluate_object_property_array_access_reference_source_alias(
                            object_name,
                            property,
                            keys.clone(),
                            span,
                            scope,
                        )?
                    {
                        return Ok(ForeachArrayRoot::Alias {
                            root: alias.root,
                            keys: alias.keys,
                        });
                    }
                    let root =
                        self.foreach_object_property_alias_root(object_name, property, scope, span)?;
                    return Ok(ForeachArrayRoot::Alias { root, keys });
                }

                if let Some((object_name, property, indices)) =
                    Self::collect_direct_dynamic_object_property_array_index_path(target, index)
                {
                    let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(self.evaluate_array_key(index, scope)?);
                    }
                    if let Some((alias, _)) = self
                        .evaluate_object_property_array_access_reference_source_alias(
                            object_name,
                            &property,
                            keys.clone(),
                            span,
                            scope,
                        )?
                    {
                        return Ok(ForeachArrayRoot::Alias {
                            root: alias.root,
                            keys: alias.keys,
                        });
                    }
                    let root = self.foreach_object_property_alias_root(
                        object_name,
                        &property,
                        scope,
                        span,
                    )?;
                    return Ok(ForeachArrayRoot::Alias { root, keys });
                }

                if let Some((holder, property, indices)) =
                    Self::collect_object_property_array_index_path(target, index)
                {
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(self.evaluate_array_key(index, scope)?);
                    }
                    return self.non_direct_foreach_object_property_array_root(
                        holder, property, keys, scope, span,
                    );
                }

                if let Some((holder, property, indices)) =
                    Self::collect_dynamic_object_property_array_index_path(target, index)
                {
                    let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(self.evaluate_array_key(index, scope)?);
                    }
                    return self.non_direct_foreach_object_property_array_root(
                        holder, &property, keys, scope, span,
                    );
                }

                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "foreach",
                        "by-reference iteration currently requires a direct array variable, direct array-offset path, direct object-property array path, string-keyed $GLOBALS path, or temporary array expression",
                    ),
                ))
            }
            Expr::Property {
                target, property, ..
            } => {
                let root = if let Expr::Variable(object_name, _) = target.as_ref() {
                    self.foreach_object_property_alias_root(object_name, property, scope, span)?
                } else {
                    self.non_direct_foreach_object_property_alias_root(
                        target, property, scope, span,
                    )?
                };
                Ok(ForeachArrayRoot::Alias {
                    root,
                    keys: Vec::new(),
                })
            }
            Expr::DynamicProperty {
                target,
                property,
                ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                    let root = self.non_direct_foreach_object_property_alias_root(
                        target, &property, scope, span,
                    )?;
                    return Ok(ForeachArrayRoot::Alias {
                        root,
                        keys: Vec::new(),
                    });
                };
                let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                let root =
                    self.foreach_object_property_alias_root(object_name, &property, scope, span)?;
                Ok(ForeachArrayRoot::Alias {
                    root,
                    keys: Vec::new(),
                })
            }
            Expr::Call { name, .. }
                if self.direct_function_call_returns_by_reference(name)
                    || name.eq_ignore_ascii_case("call_user_func_array") =>
            {
                self.by_reference_foreach_reference_return_root(iterable, scope, span)
            }
            Expr::MethodCall { .. }
            | Expr::DynamicMethodCall { .. }
            | Expr::StaticMethodCall { .. }
            | Expr::SelfMethodCall { .. }
            | Expr::ParentMethodCall { .. }
            | Expr::LateStaticMethodCall { .. }
            | Expr::ObjectStaticMethodCall { .. } => {
                self.by_reference_foreach_reference_return_root(iterable, scope, span)
            }
            expr if self.is_temporary_by_reference_foreach_iterable(expr) => {
                let value = self.evaluate(expr, scope)?;
                let Value::Array(array) = value else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(format!(
                            "can only iterate arrays in the current subset, got {}",
                            value.type_name()
                        )),
                    ));
                };
                let temp_name = self.next_foreach_temporary_array_name();
                scope.write_static(&temp_name, Value::Array(array));
                Ok(ForeachArrayRoot::Static {
                    name: temp_name,
                    keys: Vec::new(),
                })
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "foreach",
                    "by-reference iteration currently requires a direct array variable, direct array-offset path, direct object-property array path, string-keyed $GLOBALS path, or temporary array expression",
                ),
            )),
        }
    }

    fn read_foreach_root_array(
        root: &ForeachArrayRoot,
        scope: &SymbolTable,
        span: Span,
    ) -> CompileResult<PhpArray> {
        let (_name, keys, value) = match root {
            ForeachArrayRoot::Static { name, keys } => {
                let value = scope.read_static(name, span)?;
                (name.as_str(), keys.as_slice(), value)
            }
            ForeachArrayRoot::Global { name, keys } => {
                let Some(value) = scope.read_global_name(name) else {
                    return Err(runtime_error(span, RuntimeError::undefined_variable(name)));
                };
                (name.as_str(), keys.as_slice(), value)
            }
            ForeachArrayRoot::Alias { root, keys } => {
                let alias = ArrayOffsetAlias {
                    root: root.clone(),
                    keys: Vec::new(),
                };
                let value = scope
                    .read_alias_root_value(&alias, span)?
                    .unwrap_or(Value::Null);
                ("", keys.as_slice(), value)
            }
            ForeachArrayRoot::Aliases { aliases } => {
                let Some(alias) = aliases.first() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(
                            "can only iterate arrays in the current subset, got null".to_string(),
                        ),
                    ));
                };
                let root_alias = ArrayOffsetAlias {
                    root: alias.root.clone(),
                    keys: Vec::new(),
                };
                let value = scope
                    .read_alias_root_value(&root_alias, span)?
                    .unwrap_or(Value::Null);
                ("", alias.keys.as_slice(), value)
            }
            ForeachArrayRoot::ObjectProperties { object } => {
                let value = scope.read_static(object, span)?;
                let Value::Object(object) = value else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(format!(
                            "can only iterate arrays or ordinary public-property objects in the current subset, got {}",
                            value.type_name()
                        )),
                    ));
                };
                return Ok(Self::public_object_properties_as_foreach_array(&object));
            }
        };

        let value = if keys.is_empty() {
            value
        } else {
            Self::array_path_value(&value, keys).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::invalid_foreach(
                        "can only iterate arrays in the current subset, got null".to_string(),
                    ),
                )
            })?
        };

        match value {
            Value::Array(array) => Ok(array),
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_foreach(format!(
                    "can only iterate arrays in the current subset, got {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn active_foreach_reference_for_slot(
        root: &ForeachArrayRoot,
        value_name: &str,
        key: &ArrayKey,
        position: usize,
        scope: &SymbolTable,
        span: Span,
    ) -> CompileResult<ActiveForeachReference> {
        let array = Self::read_foreach_root_array(root, scope, span)?;
        let slot_id = array
            .entries()
            .iter()
            .find(|entry| entry.key == *key)
            .map(|entry| entry.slot().cell_id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::undefined_array_key(key.diagnostic_key()),
                )
            })?;
        Ok(ActiveForeachReference {
            root: root.clone(),
            value_name: value_name.to_string(),
            key: key.clone(),
            position,
            slot_id,
            next_position_override: None,
        })
    }

    fn foreach_current_position_after_body(
        array: &PhpArray,
        entry_key: &ArrayKey,
        active: Option<&ActiveForeachReference>,
    ) -> Option<ForeachCurrentPosition> {
        if let Some(active) = active {
            let by_slot = array
                .entries()
                .iter()
                .enumerate()
                .find(|(_, entry)| entry.slot().cell_id() == active.slot_id)
                .map(|(position, entry)| ForeachCurrentPosition {
                    position,
                    key: entry.key.clone(),
                    matched_slot: true,
                });
            if by_slot.is_some() || active.next_position_override.is_some() {
                return by_slot;
            }
        }

        array
            .entries()
            .iter()
            .enumerate()
            .find(|(_, entry)| entry.key == *entry_key)
            .map(|(position, entry)| ForeachCurrentPosition {
                position,
                key: entry.key.clone(),
                matched_slot: false,
            })
    }

    fn foreach_next_position_after_body(
        previous_position: usize,
        current_position: Option<&ForeachCurrentPosition>,
        active: Option<&ActiveForeachReference>,
    ) -> usize {
        if let Some(next_position) = active.and_then(|active| active.next_position_override) {
            return next_position;
        }

        match (active, current_position) {
            (Some(_), Some(current_position))
                if !current_position.matched_slot
                    && current_position.position > previous_position =>
            {
                previous_position
            }
            (Some(_), Some(current_position)) => current_position.position.saturating_add(1),
            (None, Some(current_position)) if current_position.position > previous_position => {
                previous_position
            }
            (None, Some(current_position)) => current_position.position.saturating_add(1),
            (_, None) => previous_position,
        }
    }

    fn write_foreach_value_target(
        &mut self,
        target: &ForeachValueTarget,
        assigned_value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match target {
            ForeachValueTarget::Variable { name, .. } => {
                scope.write_static(name, assigned_value);
                Ok(())
            }
            ForeachValueTarget::ArrayIndex {
                name,
                indices,
                span,
            } => {
                let keys = indices
                    .iter()
                    .map(|index| self.evaluate_array_key(index, scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                if name == "GLOBALS" {
                    self.write_global_nested_array_assignment(&keys, assigned_value, *span, scope)
                } else {
                    self.write_nested_array_assignment(name, &keys, assigned_value, *span, scope)
                }
            }
            ForeachValueTarget::List { items, span } => {
                let array = match assigned_value {
                    Value::Array(array) => Some(array),
                    Value::Null => None,
                    other => {
                        self.emit_display_warning(
                            format!("Cannot use {} as array", other.type_name()),
                            *span,
                        )?;
                        None
                    }
                };

                for (index, item) in items.iter().enumerate() {
                    let Some(target) = item.target.as_ref() else {
                        continue;
                    };
                    let key = Self::foreach_list_item_key(item.key.as_ref(), index);
                    let element = array
                        .as_ref()
                        .and_then(|array| array.get_cloned(key))
                        .unwrap_or(Value::Null);
                    self.write_foreach_value_target(target, element, *span, scope)?;
                }

                Ok(())
            }
            ForeachValueTarget::InvalidListKey { .. }
            | ForeachValueTarget::InvalidReferenceKey { .. } => Ok(()),
            ForeachValueTarget::Property {
                object, property, ..
            } => self.write_foreach_object_property_target(
                object,
                property,
                assigned_value,
                span,
                scope,
            ),
            ForeachValueTarget::DynamicProperty {
                object, property, ..
            } => {
                let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
                self.write_foreach_object_property_target(
                    object,
                    &property_name,
                    assigned_value,
                    span,
                    scope,
                )
            }
            ForeachValueTarget::ObjectPropertyArrayIndex {
                object,
                property,
                indices,
                span,
            } => {
                let keys = indices
                    .iter()
                    .map(|index| self.evaluate_array_key(index, scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.write_object_property_nested_array_assignment(
                    object,
                    property,
                    &keys,
                    assigned_value,
                    *span,
                    scope,
                )
            }
            ForeachValueTarget::DynamicObjectPropertyArrayIndex {
                object,
                property,
                indices,
                span,
            } => {
                let property_name = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let keys = indices
                    .iter()
                    .map(|index| self.evaluate_array_key(index, scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.write_object_property_nested_array_assignment(
                    object,
                    &property_name,
                    &keys,
                    assigned_value,
                    *span,
                    scope,
                )
            }
        }
    }

    fn write_foreach_key_target(
        &mut self,
        target: &Option<ForeachValueTarget>,
        assigned_value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        if let Some(target) = target {
            self.write_foreach_value_target(target, assigned_value, span, scope)?;
        }
        Ok(())
    }

    fn foreach_list_item_key(key: Option<&ForeachListKey>, positional_index: usize) -> ArrayKey {
        match key {
            Some(ForeachListKey::Int(value)) => ArrayKey::Int(*value),
            Some(ForeachListKey::String(value)) => ArrayKey::String(value.clone()),
            None => ArrayKey::Int(positional_index as i64),
        }
    }

    fn foreach_value_target_fatal(target: &ForeachValueTarget) -> Option<(&'static str, Span)> {
        match target {
            ForeachValueTarget::Variable { name, span } if name.eq_ignore_ascii_case("this") => {
                Some(("Cannot re-assign $this", *span))
            }
            ForeachValueTarget::InvalidListKey { span } => {
                Some(("Cannot use list as key element", *span))
            }
            ForeachValueTarget::InvalidReferenceKey { span } => {
                Some(("Key element cannot be a reference", *span))
            }
            ForeachValueTarget::List { items, span } if items.is_empty() => {
                Some(("Cannot use empty list", *span))
            }
            ForeachValueTarget::List { items, .. } => items
                .iter()
                .filter_map(|item| item.target.as_ref())
                .find_map(Self::foreach_value_target_fatal),
            ForeachValueTarget::Variable { .. }
            | ForeachValueTarget::ArrayIndex { .. }
            | ForeachValueTarget::Property { .. }
            | ForeachValueTarget::DynamicProperty { .. }
            | ForeachValueTarget::ObjectPropertyArrayIndex { .. }
            | ForeachValueTarget::DynamicObjectPropertyArrayIndex { .. } => None,
        }
    }

    fn write_foreach_object_property_target(
        &mut self,
        object_name: &str,
        property: &str,
        assigned_value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot write property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.write_property_from_context(
            property,
            assigned_value.clone(),
            current_class_id,
            &protected_class_ids,
        ) {
            Ok(()) => Ok(()),
            Err(error) if Self::is_undefined_property_error(&error) => match self
                .call_magic_instance_method_with_values_and_caller_scope(
                    object,
                    "__set",
                    vec![Value::String(property.to_string()), assigned_value],
                    span,
                    scope,
                )? {
                Some(_) => Ok(()),
                None => Err(runtime_error(span, error)),
            },
            Err(error) => Err(runtime_error(span, error)),
        }
    }

    fn bind_foreach_value_target_reference_to_key(
        &mut self,
        target: &ForeachValueTarget,
        root: &ForeachArrayRoot,
        key: &ArrayKey,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match target {
            ForeachValueTarget::Variable { name, .. } => {
                bind_foreach_reference_to_key(scope, name, root, key, span)
            }
            ForeachValueTarget::List { .. }
            | ForeachValueTarget::ArrayIndex { .. }
            | ForeachValueTarget::ObjectPropertyArrayIndex { .. }
            | ForeachValueTarget::DynamicObjectPropertyArrayIndex { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "foreach",
                    "by-reference array-offset and destructuring loop targets are not implemented",
                ),
            )),
            ForeachValueTarget::InvalidListKey { .. }
            | ForeachValueTarget::InvalidReferenceKey { .. } => Ok(()),
            ForeachValueTarget::Property {
                object, property, ..
            } => {
                let reference = foreach_reference_cell_for_key(scope, root, key, span)?;
                self.bind_foreach_object_property_reference_cell(
                    object, property, reference, span, scope,
                )
            }
            ForeachValueTarget::DynamicProperty {
                object, property, ..
            } => {
                let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
                let reference = foreach_reference_cell_for_key(scope, root, key, span)?;
                self.bind_foreach_object_property_reference_cell(
                    object,
                    &property_name,
                    reference,
                    span,
                    scope,
                )
            }
        }
    }

    fn bind_foreach_object_property_reference_cell(
        &mut self,
        object_name: &str,
        property: &str,
        reference: VariableCell,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot write property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.bind_property_reference_cell_to_context(
            property,
            reference.clone(),
            current_class_id,
            &protected_class_ids,
        ) {
            Ok(()) => Ok(()),
            Err(error) if matches!(error.kind(), RuntimeErrorKind::UndefinedProperty { .. }) => {
                object
                    .write_property_from_context(
                        property,
                        Value::Null,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .bind_property_reference_cell_to_context(
                        property,
                        reference,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))
            }
            Err(error) => Err(runtime_error(span, error)),
        }
    }

    fn evaluate_foreach_iterable(
        &mut self,
        iterable: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match iterable {
            Expr::Variable(name, span)
                if name != "GLOBALS"
                    && !(name.eq_ignore_ascii_case("this")
                        && scope.read_named("this").is_none()) =>
            {
                if let Some(value) = scope.read_named(name) {
                    Ok(value)
                } else {
                    self.emit_undefined_variable_warning(name, *span)?;
                    Ok(Value::Null)
                }
            }
            _ => self.evaluate(iterable, scope),
        }
    }

    fn emit_foreach_non_iterable_warning(
        &mut self,
        type_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(
            format!("foreach() argument must be of type array|object, {type_name} given"),
            span,
        )
    }

    fn execute_foreach_by_value_iterable(
        &mut self,
        iterable: Value,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        match iterable {
            Value::Array(array) => self.execute_foreach_array_by_value(
                array, key, value, body, span, scope,
            ),
            Value::Object(object) if self.is_spl_fixed_array_object(&object) => {
                self.execute_foreach_spl_fixed_array_by_value(
                    object, key, value, body, span, scope,
                )
            }
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "Iterator") =>
            {
                self.execute_foreach_iterator_by_value(object, key, value, body, span, scope)
            }
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "IteratorAggregate") =>
            {
                let iterator =
                    self.call_required_iterator_method(object, "getIterator", span)?;
                match iterator {
                    Value::Object(iterator)
                        if self
                            .classes
                            .implements_interface(iterator.class_id(), "Iterator") =>
                    {
                        let flow = self.execute_foreach_iterator_by_value(
                            iterator.clone(),
                            key,
                            value,
                            body,
                            span,
                            scope,
                        )?;
                        self.retire_unrooted_temporary_object_handle(&iterator, scope)?;
                        Ok(flow)
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(format!(
                            "IteratorAggregate::getIterator() must return an Iterator object in the current subset, got {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            Value::Object(object) if !self.is_traversable_object(&object) => {
                self.execute_foreach_public_object_by_value(object, key, value, body, span, scope)
            }
            Value::Null => {
                self.emit_foreach_non_iterable_warning("null", span)?;
                Ok(Flow::Normal)
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_foreach(format!(
                    "can only iterate arrays, ordinary public-property objects, or bounded Iterator objects in the current subset, got {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_foreach_array_by_value(
        &mut self,
        array: PhpArray,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        for entry in array.entries() {
            self.tick(span)?;
            self.write_foreach_key_target(key, value_from_array_key(&entry.key), span, scope)?;
            self.write_foreach_value_target(value, entry.value_cloned(), span, scope)?;
            match self.execute_statements(body, scope)? {
                Flow::Normal => {}
                Flow::Continue { depth, .. } if depth <= 1 => {}
                Flow::Continue { depth, span } => {
                    return Ok(Flow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                Flow::Break { depth, .. } if depth <= 1 => break,
                Flow::Break { depth, span } => {
                    return Ok(Flow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (Flow::Return(_)
                | Flow::Goto { .. }
                | Flow::Throw { .. }
                | Flow::Exit(_)) => {
                    return Ok(flow);
                }
            }
        }

        Ok(Flow::Normal)
    }

    fn execute_foreach_spl_fixed_array_by_value(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let mut cursor = 0_usize;
        loop {
            let current = {
                let state = self.spl_fixed_array_state(&object, "foreach", span)?;
                let Some(current) = state.values.get(cursor) else {
                    break;
                };
                current.clone()
            };

            self.tick(span)?;
            self.write_foreach_key_target(key, Value::Int(cursor as i64), span, scope)?;
            self.write_foreach_value_target(value, current, span, scope)?;

            match self.execute_statements(body, scope)? {
                Flow::Normal => {
                    cursor = cursor.saturating_add(1);
                }
                Flow::Continue { depth, .. } if depth <= 1 => {
                    cursor = cursor.saturating_add(1);
                }
                Flow::Continue { depth, span } => {
                    return Ok(Flow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                Flow::Break { depth, .. } if depth <= 1 => break,
                Flow::Break { depth, span } => {
                    return Ok(Flow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (Flow::Return(_)
                | Flow::Goto { .. }
                | Flow::Throw { .. }
                | Flow::Exit(_)) => {
                    return Ok(flow);
                }
            }
        }

        Ok(Flow::Normal)
    }

    fn execute_foreach_public_object_by_value(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let properties: Vec<(String, String)> = object
            .initialized_visible_properties(current_class_id, &protected_class_ids)
            .into_iter()
            .map(|property| {
                (
                    property.name().to_string(),
                    property.object_iteration_name(),
                )
            })
            .collect();

        for (property, iteration_name) in properties {
            self.tick(span)?;
            self.write_foreach_key_target(key, Value::String(iteration_name), span, scope)?;
            self.write_foreach_value_target(
                value,
                object.read_property_from_context(
                    &property,
                    current_class_id,
                    &protected_class_ids,
                )?,
                span,
                scope,
            )?;
            match self.execute_statements(body, scope)? {
                Flow::Normal => {}
                Flow::Continue { depth, .. } if depth <= 1 => {}
                Flow::Continue { depth, span } => {
                    return Ok(Flow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                Flow::Break { depth, .. } if depth <= 1 => break,
                Flow::Break { depth, span } => {
                    return Ok(Flow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (Flow::Return(_)
                | Flow::Goto { .. }
                | Flow::Throw { .. }
                | Flow::Exit(_)) => {
                    return Ok(flow);
                }
            }
        }

        Ok(Flow::Normal)
    }

    fn call_required_iterator_current_method_with_array_copy_source(
        &mut self,
        object: PhpObject,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if object.class_name().eq_ignore_ascii_case("Generator") {
            return self
                .call_generator_method_with_values(object, "current", Vec::new(), span)
                .map(|value| (value, None));
        }
        let method_name = "current";
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), method_name)
        else {
            return Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            ));
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible_for_receiver(
            Some(object.class_id()),
            class_id,
            &class_name,
            method_name,
            visibility,
            span,
        )?;

        if self.resolved_method_is_core_array_object(class_id) {
            return self
                .call_array_object_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            return self
                .call_spl_object_storage_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_fixed_array(class_id) {
            return self
                .call_spl_fixed_array_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(class_id) {
            return self
                .call_spl_doubly_linked_list_method_with_values(
                    object,
                    method_name,
                    Vec::new(),
                    span,
                )
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_directory_iterator(class_id) {
            return self
                .call_spl_directory_iterator_method_with_values(
                    object,
                    method_name,
                    Vec::new(),
                    span,
                )
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(class_id) {
            return self
                .call_spl_recursive_iterator_iterator_method_with_values(
                    object,
                    method_name,
                    Vec::new(),
                    span,
                )
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_file_info(class_id) {
            return self
                .call_spl_file_info_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_file_object(class_id) {
            return self
                .call_spl_file_object_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(class_id) {
            return self
                .call_spl_iterator_wrapper_method_with_values(object, method_name, Vec::new(), span)
                .map(|value| (value, None));
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        if function.returns_by_reference {
            ensure_user_function_arity(function, 0, span)?;
            ensure_supported_reference_return_function_metadata(function, span)?;
            self.ensure_user_function_call_depth(function, span)?;

            let called_class_id = object.class_id();
            let binding = self
                .call_reference_return_function_with_checked_values_for_reference_assignment(
                    function,
                    Vec::new(),
                    Some(object),
                    Some(class_id),
                    Some(called_class_id),
                    Vec::new(),
                    caller_scope,
                )?;
            let source = Self::public_object_property_array_copy_source_from_reference_binding(
                &binding,
                caller_scope,
            );
            let value = match binding {
                ReferenceReturnBinding::Cell(cell) => cell.value_cloned(),
                ReferenceReturnBinding::ArrayOffset(alias) => caller_scope
                    .read_array_offset_alias(&alias)
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::invalid_array_access(
                                "cannot read Iterator::current() reference-return array result"
                                    .to_string(),
                            ),
                        )
                    })?,
                ReferenceReturnBinding::ArrayOffsets(aliases) => {
                    let alias = aliases.first().ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::invalid_array_access(
                                "cannot read empty Iterator::current() reference-return array result"
                                    .to_string(),
                            ),
                        )
                    })?;
                    caller_scope.read_array_offset_alias(alias).ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::invalid_array_access(
                                "cannot read Iterator::current() reference-return array result"
                                    .to_string(),
                            ),
                        )
                    })?
                }
            };
            return Ok((value, source));
        }
        ensure_user_function_arity(function, 0, span)?;
        ensure_supported_function_metadata(function, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        self.function_context
            .push(self.function_context_name(function));
        self.class_context.push(class_id);
        self.called_class_context.push(called_class_id);
        let mut local_scope = SymbolTable::new_child(self.global_symbols.clone());
        local_scope.write_static("this", Value::Object(object));

        self.call_depth += 1;
        self.active_static_locals.push(Vec::new());
        self.active_symbol_roots.push(local_scope.symbols.clone());
        let active_function_arguments =
            Self::active_function_call_arguments_for_func_get(function, &[], &[], &local_scope);
        self.active_function_call_arguments
            .push(active_function_arguments);
        let flow = self.with_strict_types_scope(function.strict_types, |this| {
            this.execute_statements_with_array_copy_return_source(&function.body, &mut local_scope)
        });
        self.active_function_call_arguments.pop();
        let static_names = self.active_static_locals.pop().unwrap_or_default();
        let function_key = function.name.to_ascii_lowercase();
        for name in static_names {
            if let Some(value) = local_scope.read_named(&name) {
                self.static_locals
                    .insert((function_key.clone(), name), value.clone());
            }
        }
        self.active_symbol_roots.pop();
        self.call_depth -= 1;
        self.function_context.pop();
        self.class_context.pop();
        self.called_class_context.pop();

        let (flow, source) = flow?;
        match flow {
            Flow::Normal => Ok((Value::Null, None)),
            Flow::Break { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
            )),
            Flow::Continue { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("continue cannot be used outside a loop"),
            )),
            Flow::Return(value) => Ok((value, source)),
            Flow::Throw { object, span } => Err(self.uncaught_throw_error(&object, span)),
            Flow::Exit(_) => Ok((Value::Null, None)),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn execute_statements_with_array_copy_return_source(
        &mut self,
        statements: &[Stmt],
        scope: &mut SymbolTable,
    ) -> CompileResult<(Flow, Option<ArrayCopySource>)> {
        let flow = self.execute_array_copy_return_statement_list(statements, scope)?;
        self.array_copy_return_body_flow_result(flow)
    }

    fn array_copy_return_body_flow_result(
        &self,
        flow: ArrayCopyReturnBodyFlow,
    ) -> CompileResult<(Flow, Option<ArrayCopySource>)> {
        match flow {
            ArrayCopyReturnBodyFlow::Normal => Ok((Flow::Normal, None)),
            ArrayCopyReturnBodyFlow::Break { depth, span } => {
                Ok((Flow::Break { depth, span }, None))
            }
            ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                Ok((Flow::Continue { depth, span }, None))
            }
            ArrayCopyReturnBodyFlow::Return { value, source } => Ok((Flow::Return(value), source)),
            ArrayCopyReturnBodyFlow::Exit(code) => Ok((Flow::Exit(code), None)),
            ArrayCopyReturnBodyFlow::Goto { label, span } => Ok((Flow::Goto { label, span }, None)),
            ArrayCopyReturnBodyFlow::Throw { object, span } => {
                Err(self.uncaught_throw_error(&object, span))
            }
        }
    }

    fn execute_array_copy_return_statement_list(
        &mut self,
        statements: &[Stmt],
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        let mut labels = HashMap::new();
        for (index, stmt) in statements.iter().enumerate() {
            if let Stmt::Label { name, .. } = stmt {
                labels.insert(name.clone(), index);
            }
        }

        let mut index = 0;
        while index < statements.len() {
            let stmt = &statements[index];
            let flow = self.execute_array_copy_return_statement(stmt, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {}
                ArrayCopyReturnBodyFlow::Goto { label, span } => {
                    let Some(target) = labels.get(&label) else {
                        return Ok(ArrayCopyReturnBodyFlow::Goto { label, span });
                    };
                    index = *target;
                    continue;
                }
                flow @ (ArrayCopyReturnBodyFlow::Break { .. }
                | ArrayCopyReturnBodyFlow::Continue { .. }
                | ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
            if let Some(code) = self.exit_signal {
                return Ok(ArrayCopyReturnBodyFlow::Exit(code));
            }
            index += 1;
        }
        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn execute_array_copy_return_statement(
        &mut self,
        stmt: &Stmt,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        match stmt {
            Stmt::Return { value, span } => {
                self.tick(stmt.span())?;
                self.last_return_span = Some(*span);
                let (flow, source) =
                    self.return_flow_with_array_copy_source(value.as_ref(), scope)?;
                let Flow::Return(value) = flow else {
                    unreachable!("return_flow_with_array_copy_source always returns Flow::Return")
                };
                return Ok(ArrayCopyReturnBodyFlow::Return { value, source });
            }
            Stmt::If {
                condition,
                then_branch,
                else_branch,
                ..
            } => {
                self.tick(stmt.span())?;
                let branch = if self.evaluate(condition, scope)?.is_truthy() {
                    then_branch
                } else {
                    else_branch
                };
                return self.execute_array_copy_return_statement_list(branch, scope);
            }
            Stmt::While {
                condition,
                body,
                span,
            } => {
                self.tick(stmt.span())?;
                loop {
                    self.tick(*span)?;
                    if !self.evaluate(condition, scope)?.is_truthy() {
                        break;
                    }
                    let flow = self.execute_array_copy_return_statement_list(body, scope)?;
                    match flow {
                        ArrayCopyReturnBodyFlow::Normal => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                        ArrayCopyReturnBodyFlow::Break { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                        | ArrayCopyReturnBodyFlow::Goto { .. }
                        | ArrayCopyReturnBodyFlow::Exit(_)
                        | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
                    }
                }
                return Ok(ArrayCopyReturnBodyFlow::Normal);
            }
            Stmt::DoWhile {
                body,
                condition,
                span,
            } => {
                self.tick(stmt.span())?;
                loop {
                    self.tick(*span)?;
                    let flow = self.execute_array_copy_return_statement_list(body, scope)?;
                    match flow {
                        ArrayCopyReturnBodyFlow::Normal => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                        ArrayCopyReturnBodyFlow::Break { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                        | ArrayCopyReturnBodyFlow::Goto { .. }
                        | ArrayCopyReturnBodyFlow::Exit(_)
                        | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
                    }

                    if !self.evaluate(condition, scope)?.is_truthy() {
                        break;
                    }
                }
                return Ok(ArrayCopyReturnBodyFlow::Normal);
            }
            Stmt::For {
                initializers,
                conditions,
                increments,
                body,
                span,
            } => {
                self.tick(stmt.span())?;
                for initializer in initializers {
                    self.execute_for_action(initializer, scope)?;
                }

                loop {
                    self.tick(*span)?;
                    if !conditions.is_empty() {
                        let mut keep_running = true;
                        for condition in conditions {
                            keep_running = self.evaluate(condition, scope)?.is_truthy();
                        }
                        if !keep_running {
                            break;
                        }
                    }

                    let flow = self.execute_array_copy_return_statement_list(body, scope)?;
                    match flow {
                        ArrayCopyReturnBodyFlow::Normal => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                        ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                        ArrayCopyReturnBodyFlow::Break { depth, span } => {
                            return Ok(ArrayCopyReturnBodyFlow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                        | ArrayCopyReturnBodyFlow::Goto { .. }
                        | ArrayCopyReturnBodyFlow::Exit(_)
                        | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
                    }

                    for increment in increments {
                        self.execute_for_action(increment, scope)?;
                    }
                }

                return Ok(ArrayCopyReturnBodyFlow::Normal);
            }
            Stmt::Switch { value, cases, .. } => {
                self.tick(stmt.span())?;
                return self.execute_array_copy_return_switch(value, cases, scope);
            }
            Stmt::Foreach {
                iterable,
                key,
                value,
                by_reference,
                body,
                span,
            } => {
                self.tick(stmt.span())?;
                if *by_reference {
                    return self.execute_foreach_by_reference_with_array_copy_return_source(
                        iterable, key, value, body, *span, scope,
                    );
                }
                let iterable = self.evaluate_foreach_iterable(iterable, scope)?;
                return self.execute_foreach_by_value_iterable_with_array_copy_return_source(
                    iterable, key, value, body, *span, scope,
                );
            }
            Stmt::Throw { expr, span } => {
                self.tick(stmt.span())?;
                let object = self.throwable_object_from_expr(expr, *span, scope)?;
                return Ok(ArrayCopyReturnBodyFlow::Throw {
                    object,
                    span: *span,
                });
            }
            Stmt::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                self.tick(stmt.span())?;
                let try_flow = match self.execute_array_copy_return_statement_list(body, scope) {
                    Ok(flow) => flow,
                    Err(error) if catchable_php_error_message(&error).is_some() => {
                        match self.execute_catchable_php_error_array_copy_return_catch_flow(
                            &error, catches, scope,
                        )? {
                            Some(flow) => flow,
                            None => return Err(error),
                        }
                    }
                    Err(error) => return Err(error),
                };
                let try_flow = match try_flow {
                    ArrayCopyReturnBodyFlow::Throw { object, span } => {
                        self.execute_array_copy_return_catch_flow(object, span, catches, scope)?
                    }
                    flow => flow,
                };
                if let Some(finally_body) = finally_body {
                    let finally_flow =
                        self.execute_array_copy_return_statement_list(finally_body, scope)?;
                    if !matches!(finally_flow, ArrayCopyReturnBodyFlow::Normal) {
                        return Ok(finally_flow);
                    }
                }
                return Ok(try_flow);
            }
            Stmt::ReferenceAssign {
                target:
                    target @ AssignTarget::Variable {
                        name: target_name, ..
                    },
                source,
                span,
            } => {
                self.execute_reference_assignment(target, source, *span, scope)?;
                if matches!(scope.read_named(target_name), Some(Value::Array(_))) {
                    if let Some(source) =
                        self.array_copy_source_for_reference_assignment_source(source, scope)
                    {
                        scope.record_public_object_property_array_copy_source(target_name, source);
                    }
                }
                return Ok(ArrayCopyReturnBodyFlow::Normal);
            }
            _ => {}
        }

        match self.execute_statement(stmt, scope)? {
            Flow::Normal => Ok(ArrayCopyReturnBodyFlow::Normal),
            Flow::Break { depth, span } => Ok(ArrayCopyReturnBodyFlow::Break { depth, span }),
            Flow::Continue { depth, span } => Ok(ArrayCopyReturnBodyFlow::Continue { depth, span }),
            Flow::Return(value) => Ok(ArrayCopyReturnBodyFlow::Return {
                value,
                source: None,
            }),
            Flow::Throw { object, span } => Ok(ArrayCopyReturnBodyFlow::Throw { object, span }),
            Flow::Exit(code) => Ok(ArrayCopyReturnBodyFlow::Exit(code)),
            Flow::Goto { label, span } => Ok(ArrayCopyReturnBodyFlow::Goto { label, span }),
        }
    }

    fn execute_array_copy_return_catch_flow(
        &mut self,
        object: PhpObject,
        span: Span,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        for catch in catches {
            if !self.catch_matches_thrown_object(&object, catch)? {
                continue;
            }
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(object));
            }
            return self.execute_array_copy_return_statement_list(&catch.body, scope);
        }

        Ok(ArrayCopyReturnBodyFlow::Throw { object, span })
    }

    fn execute_catchable_php_error_array_copy_return_catch_flow(
        &mut self,
        error: &Diagnostic,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ArrayCopyReturnBodyFlow>> {
        let Some((error_class_name, error_message)) =
            self.catchable_php_error_class_and_message_with_pending_call_site(error)
        else {
            return Ok(None);
        };
        let Some(error_class_id) = self.classes.lookup_class_id(error_class_name) else {
            return Ok(None);
        };
        let error_object =
            self.create_core_error_object(error_message, error_class_id, error.line)?;
        for catch in catches {
            if !self.catch_matches_class(error_class_id, catch)? {
                continue;
            }
            self.clear_pending_uncaught_call_frames();
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(error_object.clone()));
            }
            return self
                .execute_array_copy_return_statement_list(&catch.body, scope)
                .map(Some);
        }
        Ok(None)
    }

    fn execute_foreach_by_reference_with_array_copy_return_source(
        &mut self,
        iterable: &Expr,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        let root = self.by_reference_foreach_root(iterable, scope, span)?;
        Self::read_foreach_root_array(&root, scope, span)?;
        let mut position = 0usize;
        let mut lingering_reference_key = None;

        loop {
            let array = Self::read_foreach_root_array(&root, scope, span)?;
            let Some(entry) = array.entries().get(position) else {
                break;
            };
            let entry_key = entry.key.clone();
            self.tick(span)?;

            self.write_foreach_key_target(key, value_from_array_key(&entry_key), span, scope)?;
            self.bind_foreach_value_target_reference_to_key(value, &root, &entry_key, span, scope)?;
            if let Some(value_name) = value.variable_name() {
                let active = Self::active_foreach_reference_for_slot(
                    &root, value_name, &entry_key, position, scope, span,
                )?;
                self.active_foreach_references.push(active);
            }
            let flow_result = self.execute_array_copy_return_statement_list(body, scope);
            let active = if value.variable_name().is_some() {
                self.active_foreach_references.pop()
            } else {
                None
            };
            let flow = flow_result?;

            let array = Self::read_foreach_root_array(&root, scope, span)?;
            let current_position =
                Self::foreach_current_position_after_body(&array, &entry_key, active.as_ref());
            lingering_reference_key = if let (Some(value_name), Some(current_position)) =
                (value.variable_name(), current_position.as_ref())
            {
                foreach_value_still_bound_to_key(scope, &root, value_name, &current_position.key)
                    .then(|| current_position.key.clone())
            } else {
                None
            };
            position = Self::foreach_next_position_after_body(
                position,
                current_position.as_ref(),
                active.as_ref(),
            );

            match flow {
                ArrayCopyReturnBodyFlow::Normal => {}
                ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                ArrayCopyReturnBodyFlow::Continue {
                    depth,
                    span: flow_span,
                } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span: flow_span,
                    });
                }
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ArrayCopyReturnBodyFlow::Break {
                    depth,
                    span: flow_span,
                } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span: flow_span,
                    });
                }
                ArrayCopyReturnBodyFlow::Goto {
                    label,
                    span: flow_span,
                } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(ArrayCopyReturnBodyFlow::Goto {
                        label,
                        span: flow_span,
                    });
                }
                flow @ ArrayCopyReturnBodyFlow::Throw { .. } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(flow);
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)) => {
                    return Ok(flow);
                }
            }
        }

        if let Some(value_name) = value.variable_name() {
            bind_foreach_lingering_reference(
                scope,
                value_name,
                &root,
                lingering_reference_key,
                span,
            )?;
        }
        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn execute_foreach_by_value_iterable_with_array_copy_return_source(
        &mut self,
        iterable: Value,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        match iterable {
            Value::Array(array) => self.execute_foreach_array_by_value_with_array_copy_return_source(
                array, key, value, body, span, scope,
            ),
            Value::Object(object) if self.is_spl_fixed_array_object(&object) => self
                .execute_foreach_spl_fixed_array_by_value_with_array_copy_return_source(
                    object, key, value, body, span, scope,
                ),
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "Iterator") =>
            {
                self.execute_foreach_iterator_by_value_with_array_copy_return_source(
                    object, key, value, body, span, scope,
                )
            }
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "IteratorAggregate") =>
            {
                let iterator = self.call_required_iterator_method(object, "getIterator", span)?;
                match iterator {
                    Value::Object(iterator)
                        if self
                            .classes
                            .implements_interface(iterator.class_id(), "Iterator") =>
                    {
                        let flow = self
                            .execute_foreach_iterator_by_value_with_array_copy_return_source(
                                iterator.clone(),
                                key,
                                value,
                                body,
                                span,
                                scope,
                            )?;
                        self.retire_unrooted_temporary_object_handle(&iterator, scope)?;
                        Ok(flow)
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_foreach(format!(
                            "IteratorAggregate::getIterator() must return an Iterator object in the current subset, got {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            Value::Object(object) if !self.is_traversable_object(&object) => {
                self.execute_foreach_public_object_by_value_with_array_copy_return_source(
                    object, key, value, body, span, scope,
                )
            }
            Value::Null => {
                self.emit_foreach_non_iterable_warning("null", span)?;
                Ok(ArrayCopyReturnBodyFlow::Normal)
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_foreach(format!(
                    "can only iterate arrays, ordinary public-property objects, or bounded Iterator objects in the current subset, got {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_foreach_array_by_value_with_array_copy_return_source(
        &mut self,
        array: PhpArray,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        for entry in array.entries() {
            self.tick(span)?;
            self.write_foreach_key_target(key, value_from_array_key(&entry.key), span, scope)?;
            self.write_foreach_value_target(value, entry.value_cloned(), span, scope)?;
            let flow = self.execute_array_copy_return_statement_list(body, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {}
                ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ArrayCopyReturnBodyFlow::Break { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Goto { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
        }

        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn execute_foreach_public_object_by_value_with_array_copy_return_source(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let properties: Vec<(String, String)> = object
            .initialized_visible_properties(current_class_id, &protected_class_ids)
            .into_iter()
            .map(|property| {
                (
                    property.name().to_string(),
                    property.object_iteration_name(),
                )
            })
            .collect();

        for (property, iteration_name) in properties {
            self.tick(span)?;
            self.write_foreach_key_target(key, Value::String(iteration_name), span, scope)?;
            self.write_foreach_value_target(
                value,
                object.read_property_from_context(
                    &property,
                    current_class_id,
                    &protected_class_ids,
                )?,
                span,
                scope,
            )?;
            let flow = self.execute_array_copy_return_statement_list(body, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {}
                ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ArrayCopyReturnBodyFlow::Break { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Goto { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
        }

        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn execute_foreach_spl_fixed_array_by_value_with_array_copy_return_source(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        let mut cursor = 0_usize;
        loop {
            let current = {
                let state = self.spl_fixed_array_state(&object, "foreach", span)?;
                let Some(current) = state.values.get(cursor) else {
                    break;
                };
                current.clone()
            };

            self.tick(span)?;
            self.write_foreach_key_target(key, Value::Int(cursor as i64), span, scope)?;
            self.write_foreach_value_target(value, current, span, scope)?;

            let flow = self.execute_array_copy_return_statement_list(body, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {
                    cursor = cursor.saturating_add(1);
                }
                ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {
                    cursor = cursor.saturating_add(1);
                }
                ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ArrayCopyReturnBodyFlow::Break { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Goto { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
        }

        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn execute_foreach_iterator_by_value_with_array_copy_return_source(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        self.call_required_iterator_method(object.clone(), "rewind", span)?;

        loop {
            if !self
                .call_required_iterator_method(object.clone(), "valid", span)?
                .is_truthy()
            {
                break;
            }

            self.tick(span)?;
            let (current, array_copy_source) = self
                .call_required_iterator_current_method_with_array_copy_source(
                    object.clone(),
                    span,
                    scope,
                )?;
            let iterator_key = self.call_required_iterator_method(object.clone(), "key", span)?;
            self.write_foreach_key_target(key, iterator_key, span, scope)?;
            let target_is_alias = value
                .variable_name()
                .is_some_and(|name| scope.is_array_offset_alias_name(name));
            let current_is_array = matches!(current, Value::Array(_));
            self.write_foreach_value_target(value, current, span, scope)?;
            if !target_is_alias && current_is_array {
                if let Some(source) = array_copy_source {
                    if let Some(name) = value.variable_name() {
                        scope.mirror_array_copy_source_aliases_from_copy(name, &source);
                        scope.record_public_object_property_array_copy_source(name, source);
                    }
                }
            }

            let flow = self.execute_array_copy_return_statement_list(body, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {
                    self.call_required_iterator_method(object.clone(), "next", span)?;
                }
                ArrayCopyReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {
                    self.call_required_iterator_method(object.clone(), "next", span)?;
                }
                ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ArrayCopyReturnBodyFlow::Break { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Goto { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
        }

        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn evaluate_value_with_array_copy_source(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        match expr {
            Expr::Variable(_, _) => {
                let value = self.evaluate(expr, scope)?;
                let source = if matches!(value, Value::Array(_)) {
                    self.public_object_property_array_copy_source_for_value_expr(expr, scope)
                } else {
                    None
                };
                Ok((value, source))
            }
            Expr::Index {
                target,
                index,
                span,
            } => self.evaluate_array_index_with_array_copy_source(target, index, *span, scope),
            Expr::Property {
                target,
                property,
                span,
            } => self.evaluate_property_read_with_array_copy_source(target, property, *span, scope),
            Expr::DynamicProperty {
                target,
                property,
                span,
            } => self.evaluate_dynamic_property_read_with_array_copy_source(
                target, property, *span, scope,
            ),
            Expr::MethodCall {
                target,
                method,
                args,
                span,
            } => {
                self.call_instance_method_with_array_copy_source(target, method, args, *span, scope)
            }
            Expr::DynamicMethodCall {
                target,
                method,
                args,
                span,
            } => self.call_dynamic_instance_method_with_array_copy_source(
                target, method, args, *span, scope,
            ),
            Expr::Call { name, args, span } => {
                self.call_function_with_array_copy_source(name, args, *span, scope)
            }
            Expr::DynamicCall { callee, args, span } => {
                self.call_dynamic_function_with_array_copy_source(callee, args, *span, scope)
            }
            Expr::Ternary {
                condition,
                if_true,
                if_false,
                ..
            } => {
                if self.evaluate(condition, scope)?.is_truthy() {
                    self.evaluate_value_with_array_copy_source(if_true, scope)
                } else {
                    self.evaluate_value_with_array_copy_source(if_false, scope)
                }
            }
            Expr::ShortTernary {
                condition,
                if_false,
                ..
            } => {
                let (condition_value, condition_source) =
                    self.evaluate_value_with_array_copy_source(condition, scope)?;
                if condition_value.is_truthy() {
                    let source = if matches!(condition_value, Value::Array(_)) {
                        condition_source.or_else(|| {
                            self.public_object_property_array_copy_source_for_value_expr(
                                condition, scope,
                            )
                        })
                    } else {
                        None
                    };
                    Ok((condition_value, source))
                } else {
                    self.evaluate_value_with_array_copy_source(if_false, scope)
                }
            }
            Expr::Binary {
                left,
                op,
                right,
                span,
            } if matches!(op, BinaryOp::NullCoalesce) => {
                self.evaluate_null_coalescing_with_array_copy_source(left, right, *span, scope)
            }
            Expr::ErrorControl { expr, .. } => self.with_error_control_suppression(|this| {
                this.evaluate_value_with_array_copy_source(expr, scope)
            }),
            Expr::Cast { kind, expr, span } => {
                let (value, source) = self.evaluate_value_with_array_copy_source(expr, scope)?;
                let value = self.apply_cast(*kind, value, *span)?;
                let source = if matches!(*kind, CastKind::Array) && matches!(value, Value::Array(_))
                {
                    source
                } else {
                    None
                };
                Ok((value, source))
            }
            Expr::Assign { target, expr, .. } => {
                let value = self.evaluate_assignment(target, expr, scope)?;
                let source =
                    self.array_copy_source_for_assignment_target_result(target, &value, scope);
                Ok((value, source))
            }
            Expr::NullCoalesceAssign { target, expr, .. } => {
                let value = self.evaluate_null_coalesce_assignment(target, expr, scope)?;
                let source =
                    self.array_copy_source_for_assignment_target_result(target, &value, scope);
                Ok((value, source))
            }
            _ => Ok((self.evaluate(expr, scope)?, None)),
        }
    }

    fn evaluate_by_value_call_argument_with_array_copy_source(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        match expr {
            Expr::Variable(name, span) => {
                if name == "GLOBALS"
                    || (name.eq_ignore_ascii_case("this") && scope.read_named("this").is_none())
                {
                    return self.evaluate_value_with_array_copy_source(expr, scope);
                }

                let Some(value) = scope.read_named(name) else {
                    self.emit_undefined_variable_warning(name, *span)?;
                    return Ok((Value::Null, None));
                };
                let source = if matches!(value, Value::Array(_)) {
                    self.public_object_property_array_copy_source_for_value_expr(expr, scope)
                } else {
                    None
                };
                Ok((value, source))
            }
            Expr::Index {
                target,
                index,
                span,
            } => self.evaluate_by_value_call_argument_array_index_with_array_copy_source(
                target, index, *span, scope,
            ),
            _ => self.evaluate_value_with_array_copy_source(expr, scope),
        }
    }

    fn evaluate_by_value_call_argument_array_index_with_array_copy_source(
        &mut self,
        target: &Expr,
        index: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if matches!(target, Expr::Variable(name, _) if name == "GLOBALS") {
            return self.evaluate_array_index_with_array_copy_source(target, index, span, scope);
        }

        if let Some(result) =
            self.evaluate_expression_array_index_with_array_copy_source(target, index, span, scope)?
        {
            return Ok(result);
        }

        if let Some(result) =
            self.evaluate_direct_variable_non_array_index_fast_path(target, index, span, scope)?
        {
            return Ok(result);
        }

        let (target_value, target_copy_source) =
            self.evaluate_by_value_call_argument_with_array_copy_source(target, scope)?;

        match target_value {
            Value::Array(array) => {
                let key = self.evaluate_array_offset_key(index, scope)?;
                let Some(value) = array.get_cloned(key.clone()) else {
                    self.emit_display_warning(
                        format!("Undefined array key {}", key.diagnostic_key()),
                        span,
                    )?;
                    return Ok((Value::Null, None));
                };
                let source = if matches!(value, Value::Array(_)) {
                    self.array_literal_copy_source_for_index_expr(target, index, scope)
                        .or_else(|| {
                            self.object_property_array_copy_source_for_index_expr(
                                target, index, scope,
                            )
                        })
                        .or_else(|| {
                            target_copy_source.map(|mut source| {
                                source.keys.push(key);
                                source.include_exact_path = false;
                                source
                            })
                        })
                } else {
                    None
                };
                let value = scope.value_with_object_property_aliases_from_array_copy(
                    value,
                    source.clone(),
                    false,
                );
                Ok((value, source))
            }
            Value::String(value) => {
                let (offset, display_key) = self.evaluate_string_offset_index(index, scope)?;
                let value = self.read_ascii_string_offset_at(&value, offset, &display_key, span)?;
                Ok((value, None))
            }
            Value::Object(object) => {
                if !self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess")
                {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "Cannot use object of type {} as array",
                            object.class_name()
                        )),
                    ));
                }
                let (offset_arg, copy_source_key) =
                    self.array_access_offset_arg_for_object_index(&object, index, scope)?;
                let (value, executed_source) = self
                    .call_array_access_offset_get_with_array_copy_source(
                        object.clone(),
                        offset_arg,
                        span,
                        scope,
                    )?;
                let source = if matches!(value, Value::Array(_)) {
                    executed_source.or_else(|| {
                        copy_source_key.and_then(|key| {
                            self.array_access_array_copy_source_for_object(object, key, span)
                        })
                    })
                } else {
                    None
                };
                let value = scope.value_with_object_property_aliases_from_array_copy(
                    value,
                    source.clone(),
                    false,
                );
                Ok((value, source))
            }
            other => {
                let _ = self.evaluate(index, scope)?;
                self.emit_display_warning(
                    format!(
                        "Trying to access array offset on {}",
                        Self::array_offset_read_warning_container(&other)
                    ),
                    span,
                )?;
                Ok((Value::Null, None))
            }
        }
    }

    fn evaluate_direct_variable_non_array_index_fast_path(
        &mut self,
        target: &Expr,
        index: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<(Value, Option<ArrayCopySource>)>> {
        let Expr::Variable(name, _) = target else {
            return Ok(None);
        };
        if name == "GLOBALS" {
            return Ok(None);
        }
        let Some(key) = Self::non_diagnostic_side_effect_free_array_key(index, scope) else {
            return Ok(None);
        };
        let Some(value) = scope.read_direct_array_offset_cloned(name, &key) else {
            return Ok(None);
        };
        let Some(value) = value else {
            self.emit_display_warning(
                format!("Undefined array key {}", key.diagnostic_key()),
                span,
            )?;
            return Ok(Some((Value::Null, None)));
        };
        if matches!(value, Value::Array(_)) {
            return Ok(None);
        }

        Ok(Some((value, None)))
    }

    fn non_diagnostic_side_effect_free_array_key(
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<ArrayKey> {
        match Self::side_effect_free_value(expr, scope)? {
            Value::Int(value) => Some(ArrayKey::Int(value)),
            Value::Bool(value) => Some(ArrayKey::Int(i64::from(value))),
            Value::String(value) => ArrayKey::from_value(&Value::String(value)).ok(),
            Value::BinaryString(value) => ArrayKey::from_value(&Value::BinaryString(value)).ok(),
            _ => None,
        }
    }

    fn array_offset_read_warning_container(value: &Value) -> String {
        match value {
            Value::Bool(true) => "true".to_string(),
            Value::Bool(false) => "false".to_string(),
            _ => value.type_name().to_string(),
        }
    }

    fn offset_access_type_name(value: &Value) -> String {
        match value {
            Value::Object(object) => object.class_name().to_string(),
            _ => value.type_name().to_string(),
        }
    }

    fn array_copy_source_for_assignment_target_result(
        &self,
        target: &AssignTarget,
        value: &Value,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        if !matches!(value, Value::Array(_)) {
            return None;
        }

        match target {
            AssignTarget::Variable { name, .. } => {
                scope.public_or_dirty_object_property_array_copy_source_for_static(name)
            }
            _ => None,
        }
    }

    fn array_copy_source_preserved_after_nested_write(
        scope: &SymbolTable,
        name: &str,
        keys: &[ArrayKey],
    ) -> Option<ArrayCopySource> {
        let source = Self::array_copy_source_before_nested_write(scope, name)?;
        (!Self::copied_array_write_replaces_live_alias_parent(scope, name, keys)).then_some(source)
    }

    fn array_copy_source_before_nested_write(
        scope: &SymbolTable,
        name: &str,
    ) -> Option<ArrayCopySource> {
        scope
            .public_or_dirty_object_property_array_copy_source_for_static(name)
            .or_else(|| {
                scope
                    .array_offset_aliases_for_name(name)
                    .and_then(|aliases| {
                        scope.public_object_property_array_copy_source_for_alias_group(&aliases)
                    })
            })
    }

    fn copied_array_write_replaces_live_alias_parent(
        scope: &SymbolTable,
        name: &str,
        keys: &[ArrayKey],
    ) -> bool {
        if scope
            .public_or_dirty_object_property_array_copy_source_for_static(name)
            .is_none()
        {
            return false;
        }

        let root = ArrayOffsetAliasRoot::StaticArray {
            name: name.to_string(),
        };
        scope
            .array_offset_aliases
            .values()
            .flat_map(|aliases| aliases.iter())
            .any(|alias| {
                alias.root == root && alias.keys.starts_with(keys) && alias.keys.len() > keys.len()
            })
    }

    fn array_literal_copy_source_for_index_expr(
        &self,
        target: &Expr,
        index: &Expr,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        let (source_name, indices) = Self::collect_direct_variable_array_index_path(target, index)?;
        let mut keys = Vec::with_capacity(indices.len());
        for index in indices {
            keys.push(Self::side_effect_free_array_key(index, scope)?);
        }
        scope.array_literal_copy_source_for_static_path(source_name, &keys)
    }

    fn object_property_array_copy_source_for_index_expr(
        &self,
        target: &Expr,
        index: &Expr,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        if let Some((object_name, property, indices)) =
            Self::collect_direct_object_property_array_index_path(target, index)
        {
            let Value::Object(object) = scope.read_named(object_name)? else {
                return None;
            };
            let mut keys = Vec::with_capacity(indices.len());
            for index in indices {
                keys.push(Self::side_effect_free_array_key(index, scope)?);
            }
            return scope.object_property_array_copy_source_for_path(&object, property, &keys);
        }

        let (object_name, property_expr, indices) =
            Self::collect_direct_dynamic_object_property_array_index_path(target, index)?;
        let Value::Object(object) = scope.read_named(object_name)? else {
            return None;
        };
        let property = Self::side_effect_free_value(property_expr, scope)?;
        let property = match property {
            Value::String(value) => value,
            Value::Int(value) => value.to_string(),
            _ => return None,
        };
        let mut keys = Vec::with_capacity(indices.len());
        for index in indices {
            keys.push(Self::side_effect_free_array_key(index, scope)?);
        }
        scope.object_property_array_copy_source_for_path(&object, &property, &keys)
    }

    fn return_flow_with_array_copy_source(
        &mut self,
        value: Option<&Expr>,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Flow, Option<ArrayCopySource>)> {
        let Some(expr) = value else {
            return Ok((Flow::Return(Value::Null), None));
        };
        if let Expr::Array { items, span } = expr {
            let (value, references, copy_sources) =
                self.evaluate_array_for_direct_assignment(items, *span, scope)?;
            let value = self.value_with_assignment_reference_cells(
                value,
                expr,
                &references,
                &copy_sources,
                scope,
                *span,
            )?;
            return Ok((Flow::Return(value), None));
        }
        let (value, array_copy_source) = self.evaluate_value_with_array_copy_source(expr, scope)?;
        let fallback_source = if array_copy_source.is_none() && matches!(value, Value::Array(_)) {
            self.public_object_property_array_copy_source_for_value_expr(expr, scope)
        } else {
            None
        };
        let fallback_source_was_dirty = fallback_source
            .as_ref()
            .is_some_and(|source| scope.array_copy_source_was_dirtied(source));
        let value = if array_copy_source.is_none() {
            self.value_with_local_array_aliases_for_expr(value, expr, scope, true)
        } else {
            value
        };
        if let (Expr::Variable(name, _), Some(source)) = (expr, fallback_source.clone()) {
            scope.record_public_object_property_array_copy_source(name, source);
            if fallback_source_was_dirty {
                scope.mark_public_object_property_array_copy_source_dirty(name);
            }
        }
        let source = if matches!(value, Value::Array(_)) {
            array_copy_source.or(fallback_source)
        } else {
            None
        };
        Ok((Flow::Return(value), source))
    }

    fn value_with_local_array_aliases_for_expr(
        &mut self,
        value: Value,
        expr: &Expr,
        scope: &mut SymbolTable,
        promote_missing_reference_cells: bool,
    ) -> Value {
        if !matches!(value, Value::Array(_)) {
            return value;
        }

        let Some((source_name, source_keys)) =
            self.local_array_alias_source_path_for_expr(expr, scope)
        else {
            return value;
        };
        scope.value_with_static_array_aliases_from_copy(
            value,
            &source_name,
            &source_keys,
            promote_missing_reference_cells,
        )
    }

    fn local_array_alias_source_path_for_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<(String, Vec<ArrayKey>)> {
        match expr {
            Expr::Variable(name, _) => scope
                .array_offset_aliases
                .values()
                .flat_map(|aliases| aliases.iter())
                .any(|alias| {
                    matches!(
                        &alias.root,
                        ArrayOffsetAliasRoot::StaticArray { name: root_name }
                            if root_name == name
                    )
                })
                .then(|| (name.clone(), Vec::new())),
            Expr::Index { target, index, .. } => {
                let (source_name, indices) =
                    Self::collect_direct_variable_array_index_path(target, index)?;
                let mut keys = Vec::with_capacity(indices.len());
                for index in indices {
                    keys.push(Self::side_effect_free_array_key(index, scope)?);
                }
                scope
                    .array_offset_aliases
                    .values()
                    .flat_map(|aliases| aliases.iter())
                    .any(|alias| {
                        matches!(
                            &alias.root,
                            ArrayOffsetAliasRoot::StaticArray { name }
                                if name == source_name && alias.keys.starts_with(&keys)
                        )
                    })
                    .then(|| (source_name.to_string(), keys))
            }
            _ => None,
        }
    }

    fn value_with_assignment_reference_cells(
        &mut self,
        mut value: Value,
        expr: &Expr,
        array_literal_references: &[ArrayLiteralReferenceElement],
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<Value> {
        if !matches!(value, Value::Array(_)) {
            return Ok(value);
        }

        value = self.value_with_local_array_aliases_for_expr(value, expr, scope, true);
        for (keys, source) in array_literal_copy_sources {
            value = scope
                .value_with_array_copy_source_aliases_from_copy_to_path(value, keys, source, true);
        }
        self.value_with_array_literal_reference_cells(value, array_literal_references, scope, span)
    }

    fn evaluate_assignment_value_with_reference_metadata(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(
        Value,
        Vec<ArrayLiteralReferenceElement>,
        Vec<(Vec<ArrayKey>, ArrayCopySource)>,
    )> {
        match expr {
            Expr::Array { items, span } => {
                self.evaluate_array_for_direct_assignment(items, *span, scope)
            }
            _ => {
                let (value, source) = self.evaluate_value_with_array_copy_source(expr, scope)?;
                let value_is_array = matches!(value, Value::Array(_));
                let value = scope.value_with_object_property_aliases_from_array_copy(
                    value,
                    source.clone(),
                    true,
                );
                let copy_sources = if value_is_array {
                    let mut copy_sources = source
                        .map(|source| vec![(Vec::new(), source)])
                        .unwrap_or_default();
                    if let Expr::Variable(name, _) = expr {
                        if let Some(paths) = scope.array_literal_copy_source_paths.get(name) {
                            copy_sources.extend(paths.iter().cloned());
                        }
                    }
                    copy_sources
                } else {
                    Vec::new()
                };
                Ok((value, Vec::new(), copy_sources))
            }
        }
    }

    fn indexed_array_copy_source_bindings_for_argument(
        arg_index: usize,
        copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
    ) -> Vec<IndexedArrayCopySourceBinding> {
        Self::indexed_array_copy_source_bindings_for_argument_with_prefix(
            arg_index,
            &[],
            copy_sources,
        )
    }

    fn indexed_array_copy_source_bindings_for_argument_with_prefix(
        arg_index: usize,
        prefix: &[ArrayKey],
        copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
    ) -> Vec<IndexedArrayCopySourceBinding> {
        copy_sources
            .iter()
            .map(|(keys, source)| {
                let mut target_keys = prefix.to_vec();
                target_keys.extend(keys.iter().cloned());
                (arg_index, target_keys, source.clone())
            })
            .collect()
    }

    fn array_copy_source_bindings_for_indexed_args(
        function: &FunctionDecl,
        indexed_bindings: Vec<IndexedArrayCopySourceBinding>,
    ) -> Vec<ArrayCopySourceBinding> {
        indexed_bindings
            .into_iter()
            .filter_map(|(index, keys, source)| {
                function
                    .params
                    .get(index)
                    .map(|param| (param.name.clone(), keys, source))
            })
            .collect()
    }

    fn value_with_array_literal_reference_cells(
        &mut self,
        value: Value,
        references: &[ArrayLiteralReferenceElement],
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<Value> {
        if references.is_empty() {
            return Ok(value);
        }
        let Value::Array(mut array) = value else {
            return Ok(value);
        };

        for reference in references {
            match reference {
                ArrayLiteralReferenceElement::Variable { keys, source_name } => {
                    let Some(reference) = scope.reference_cell_for_static_source(source_name)
                    else {
                        return Err(runtime_error(
                            span,
                            RuntimeError::undefined_variable(source_name),
                        ));
                    };
                    SymbolTable::write_nested_array_offset_alias_reference(
                        &mut array, keys, reference,
                    );
                }
                ArrayLiteralReferenceElement::Alias {
                    keys,
                    source_alias,
                    value,
                } => {
                    let aliases = vec![source_alias.clone()];
                    let reference = scope
                        .reference_cell_for_array_offset_alias_group(&aliases)
                        .or_else(|| {
                            let _ = scope.materialize_array_offset_alias(source_alias, span);
                            scope
                                .read_array_offset_alias_reference_cell(source_alias)
                                .or_else(|| {
                                    let source_value = scope
                                        .read_array_offset_alias(source_alias)
                                        .unwrap_or_else(|| value.clone());
                                    let reference = PhpReferenceCell::new(source_value);
                                    scope
                                        .write_array_offset_alias_reference(
                                            source_alias,
                                            reference.clone(),
                                        )
                                        .then_some(reference)
                                })
                        });
                    let Some(reference) = reference else {
                        return Err(runtime_error(
                            span,
                            RuntimeError::invalid_array_access(
                                "cannot bind array literal reference element".to_string(),
                            ),
                        ));
                    };
                    SymbolTable::write_nested_array_offset_alias_reference(
                        &mut array, keys, reference,
                    );
                }
                ArrayLiteralReferenceElement::CopiedArray { keys, source_name } => {
                    let source = ArrayCopySource::alias_path(
                        ArrayOffsetAliasRoot::StaticArray {
                            name: source_name.clone(),
                        },
                        Vec::new(),
                        false,
                    );
                    let value = scope.value_with_array_copy_source_aliases_from_copy_to_path(
                        Value::Array(array),
                        keys,
                        &source,
                        true,
                    );
                    let Value::Array(updated) = value else {
                        unreachable!("array copy source rehydration preserves array root")
                    };
                    array = updated;
                }
            }
        }

        Ok(Value::Array(array))
    }

    fn execute_array_copy_return_switch(
        &mut self,
        value: &Expr,
        cases: &[SwitchCase],
        scope: &mut SymbolTable,
    ) -> CompileResult<ArrayCopyReturnBodyFlow> {
        let switch_value = self.evaluate(value, scope)?;
        let mut default_index = None;
        let mut matched_index = None;

        for (index, case) in cases.iter().enumerate() {
            let Some(condition) = &case.condition else {
                if default_index.is_none() {
                    default_index = Some(index);
                }
                continue;
            };

            let case_value = self.evaluate(condition, scope)?;
            let matched = switch_value
                .php_cmp_checked(&case_value, Comparison::Eq)
                .map_err(|error| runtime_error(condition.span(), error))?;
            if matched {
                matched_index = Some(index);
                break;
            }
        }

        let Some(mut index) = matched_index.or(default_index) else {
            return Ok(ArrayCopyReturnBodyFlow::Normal);
        };

        while index < cases.len() {
            let flow = self.execute_array_copy_return_statement_list(&cases[index].body, scope)?;
            match flow {
                ArrayCopyReturnBodyFlow::Normal => {}
                ArrayCopyReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                    return Ok(ArrayCopyReturnBodyFlow::Normal);
                }
                ArrayCopyReturnBodyFlow::Break { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                ArrayCopyReturnBodyFlow::Continue { depth, span } if depth <= 1 => {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control(
                            "continue inside switch is not implemented; use break for switch cases in the current subset",
                        ),
                    ));
                }
                ArrayCopyReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ArrayCopyReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ArrayCopyReturnBodyFlow::Return { .. }
                | ArrayCopyReturnBodyFlow::Goto { .. }
                | ArrayCopyReturnBodyFlow::Exit(_)
                | ArrayCopyReturnBodyFlow::Throw { .. }) => return Ok(flow),
            }
            index += 1;
        }

        Ok(ArrayCopyReturnBodyFlow::Normal)
    }

    fn public_object_property_array_copy_source_for_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        match expr {
            Expr::Property {
                target, property, ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    return None;
                };
                let Value::Object(object) = scope.read_named(object_name)? else {
                    return None;
                };
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                object
                    .read_property_from_context(property, current_class_id, &protected_class_ids)
                    .ok()?;
                Some(ArrayCopySource::object_property(
                    object,
                    property.clone(),
                    Vec::new(),
                    true,
                ))
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    return None;
                };
                let Value::Object(object) = scope.read_named(object_name)? else {
                    return None;
                };
                let property = Self::side_effect_free_value(property, scope)?;
                let property = match property {
                    Value::String(value) => value,
                    Value::Int(value) => value.to_string(),
                    _ => return None,
                };
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                object
                    .read_property_from_context(&property, current_class_id, &protected_class_ids)
                    .ok()?;
                Some(ArrayCopySource::object_property(
                    object,
                    property,
                    Vec::new(),
                    true,
                ))
            }
            Expr::Index {
                target,
                index,
                span,
            } => {
                if let Some((source_name, indices)) =
                    Self::collect_direct_variable_array_index_path(target, index)
                {
                    let mut keys = Vec::with_capacity(indices.len());
                    for index in indices {
                        keys.push(Self::side_effect_free_array_key(index, scope)?);
                    }
                    if source_name == "GLOBALS" {
                        let (global_name, keys) =
                            SymbolTable::split_globals_reference_path(keys, *span).ok()?;
                        return Some(ArrayCopySource::alias_path(
                            ArrayOffsetAliasRoot::GlobalArray { name: global_name },
                            keys,
                            false,
                        ));
                    }
                    if scope.global_symbols.is_some()
                        && (scope.imported_globals.contains(source_name)
                            || is_auto_global_name(source_name))
                    {
                        return Some(ArrayCopySource::alias_path(
                            ArrayOffsetAliasRoot::GlobalArray {
                                name: source_name.to_string(),
                            },
                            keys,
                            false,
                        ));
                    }
                    return None;
                }

                let (object_name, property, indices) =
                    if let Some((object_name, property, indices)) =
                        Self::collect_direct_object_property_array_index_path(target, index)
                    {
                        (object_name, property.to_string(), indices)
                    } else {
                        let (object_name, property, indices) =
                            Self::collect_direct_dynamic_object_property_array_index_path(
                                target, index,
                            )?;
                        let property = Self::side_effect_free_value(property, scope)?;
                        let property = match property {
                            Value::String(value) => value,
                            Value::Int(value) => value.to_string(),
                            _ => return None,
                        };
                        (object_name, property, indices)
                    };
                let Value::Object(object) = scope.read_named(object_name)? else {
                    return None;
                };
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                object
                    .read_property_from_context(&property, current_class_id, &protected_class_ids)
                    .ok()?;
                let mut keys = Vec::with_capacity(indices.len());
                for index in indices {
                    keys.push(Self::side_effect_free_array_key(index, scope)?);
                }
                Some(ArrayCopySource::object_property(
                    object, property, keys, false,
                ))
            }
            _ => None,
        }
    }

    fn array_copy_source_for_reference_assignment_source(
        &self,
        source: &ReferenceSource,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        match source {
            ReferenceSource::Property { expr, .. } => {
                let (object_name, property, include_exact_path) = match expr {
                    Expr::Property {
                        target, property, ..
                    } => {
                        let Expr::Variable(object_name, _) = target.as_ref() else {
                            return None;
                        };
                        (object_name.as_str(), property.clone(), true)
                    }
                    Expr::DynamicProperty {
                        target, property, ..
                    } => {
                        let Expr::Variable(object_name, _) = target.as_ref() else {
                            return None;
                        };
                        let property = Self::side_effect_free_value(property, scope)?;
                        let property = match property {
                            Value::String(value) => value,
                            Value::Int(value) => value.to_string(),
                            _ => return None,
                        };
                        (object_name.as_str(), property, true)
                    }
                    _ => return None,
                };
                self.array_copy_source_for_object_property_path(
                    object_name,
                    property,
                    Vec::new(),
                    include_exact_path,
                    scope,
                )
            }
            ReferenceSource::ObjectPropertyArrayIndex {
                object,
                property,
                index,
                ..
            } => {
                let key = Self::side_effect_free_array_key(index, scope)?;
                self.array_copy_source_for_object_property_path(
                    object,
                    property.clone(),
                    vec![key],
                    false,
                    scope,
                )
            }
            ReferenceSource::DynamicObjectPropertyArrayIndex {
                object,
                property,
                index,
                ..
            } => {
                let property = Self::side_effect_free_value(property, scope)?;
                let property = match property {
                    Value::String(value) => value,
                    Value::Int(value) => value.to_string(),
                    _ => return None,
                };
                let key = Self::side_effect_free_array_key(index, scope)?;
                self.array_copy_source_for_object_property_path(
                    object,
                    property,
                    vec![key],
                    false,
                    scope,
                )
            }
            ReferenceSource::ObjectPropertyNestedArrayIndex {
                object,
                property,
                indices,
                ..
            } => {
                let mut keys = Vec::with_capacity(indices.len());
                for index in indices {
                    keys.push(Self::side_effect_free_array_key(index, scope)?);
                }
                self.array_copy_source_for_object_property_path(
                    object,
                    property.clone(),
                    keys,
                    false,
                    scope,
                )
            }
            ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
                object,
                property,
                indices,
                ..
            } => {
                let property = Self::side_effect_free_value(property, scope)?;
                let property = match property {
                    Value::String(value) => value,
                    Value::Int(value) => value.to_string(),
                    _ => return None,
                };
                let mut keys = Vec::with_capacity(indices.len());
                for index in indices {
                    keys.push(Self::side_effect_free_array_key(index, scope)?);
                }
                self.array_copy_source_for_object_property_path(
                    object, property, keys, false, scope,
                )
            }
            _ => None,
        }
    }

    fn array_copy_source_for_object_property_path(
        &self,
        object_name: &str,
        property: String,
        keys: Vec<ArrayKey>,
        include_exact_path: bool,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        let Value::Object(object) = scope.read_named(object_name)? else {
            return None;
        };
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        object
            .read_property_from_context(&property, current_class_id, &protected_class_ids)
            .ok()?;
        Some(ArrayCopySource::object_property(
            object,
            property,
            keys,
            include_exact_path,
        ))
    }

    fn public_object_property_array_copy_source_for_value_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        if let Expr::Variable(name, _) = expr {
            return scope
                .public_or_dirty_object_property_array_copy_source_for_static(name)
                .or_else(|| {
                    scope
                        .array_offset_aliases_for_name(name)
                        .and_then(|aliases| {
                            scope.public_object_property_array_copy_source_for_alias_group(&aliases)
                        })
                })
                .or_else(|| {
                    (scope.global_symbols.is_some()
                        && (scope.imported_globals.contains(name) || is_auto_global_name(name)))
                    .then(|| {
                        ArrayCopySource::alias_path(
                            ArrayOffsetAliasRoot::GlobalArray { name: name.clone() },
                            Vec::new(),
                            true,
                        )
                    })
                });
        }
        self.public_object_property_array_copy_source_for_expr(expr, scope)
    }

    fn public_object_property_array_copy_source_from_reference_binding(
        binding: &ReferenceReturnBinding,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        let alias = match binding {
            ReferenceReturnBinding::ArrayOffset(alias) => alias,
            ReferenceReturnBinding::ArrayOffsets(aliases) => aliases.first()?,
            ReferenceReturnBinding::Cell(cell) => {
                return matches!(cell.value_cloned(), Value::Array(_))
                    .then(|| ArrayCopySource::runtime_cell(cell.clone(), Vec::new(), true));
            }
        };
        match &alias.root {
            ArrayOffsetAliasRoot::PublicObjectProperty { object, property }
            | ArrayOffsetAliasRoot::ContextObjectProperty {
                object, property, ..
            } => {
                let Value::Object(object) = scope.read_named(object)? else {
                    return None;
                };
                Some(ArrayCopySource::object_property(
                    object,
                    property.clone(),
                    alias.keys.clone(),
                    false,
                ))
            }
            ArrayOffsetAliasRoot::GlobalArray { .. } => Some(ArrayCopySource::alias_path(
                alias.root.clone(),
                alias.keys.clone(),
                false,
            )),
            ArrayOffsetAliasRoot::StaticArray { .. } => None,
        }
    }

    fn array_access_array_copy_source_for_direct_variable_index(
        &self,
        object_name: &str,
        indices: &[&Expr],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        let keys = Self::side_effect_free_array_keys(indices, scope)?;
        self.array_access_array_copy_source_for_direct_variable_keys(
            object_name,
            &keys,
            span,
            scope,
        )
    }

    fn array_access_array_copy_source_for_direct_variable_keys(
        &self,
        object_name: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        self.array_access_array_copy_source_for_direct_variable_keys_with_terminal_ref(
            object_name,
            keys,
            span,
            scope,
        )
        .map(|(source, _)| source)
    }

    fn array_access_array_copy_source_for_direct_variable_keys_with_terminal_ref(
        &self,
        object_name: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<(ArrayCopySource, bool)> {
        let Value::Object(object) = scope.read_named(object_name)? else {
            return None;
        };
        self.array_access_array_copy_source_for_object_path_with_terminal_ref(object, keys, span)
    }

    fn array_access_array_copy_source_for_object_property_index(
        &self,
        object_name: &str,
        property: &str,
        indices: &[&Expr],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        let keys = Self::side_effect_free_array_keys(indices, scope)?;
        self.array_access_array_copy_source_for_object_property_keys(
            object_name,
            property,
            &keys,
            span,
            scope,
        )
    }

    fn array_access_array_copy_source_for_object_property_keys(
        &self,
        object_name: &str,
        property: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<ArrayCopySource> {
        self.array_access_array_copy_source_for_object_property_keys_with_terminal_ref(
            object_name,
            property,
            keys,
            span,
            scope,
        )
        .map(|(source, _)| source)
    }

    fn array_access_array_copy_source_for_object_property_keys_with_terminal_ref(
        &self,
        object_name: &str,
        property: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &SymbolTable,
    ) -> Option<(ArrayCopySource, bool)> {
        let Value::Object(holder) = scope.read_named(object_name)? else {
            return None;
        };
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let Value::Object(object) = holder
            .read_property_from_context(property, current_class_id, &protected_class_ids)
            .ok()?
        else {
            return None;
        };
        self.array_access_array_copy_source_for_object_path_with_terminal_ref(object, keys, span)
    }

    fn array_access_array_copy_source_for_object(
        &self,
        object: PhpObject,
        key: ArrayKey,
        span: Span,
    ) -> Option<ArrayCopySource> {
        self.array_access_array_copy_source_for_object_path(object, &[key], span)
    }

    fn array_access_array_copy_source_for_object_path(
        &self,
        object: PhpObject,
        keys: &[ArrayKey],
        span: Span,
    ) -> Option<ArrayCopySource> {
        self.array_access_array_copy_source_for_object_path_with_terminal_ref(object, keys, span)
            .map(|(source, _)| source)
    }

    fn array_access_array_copy_source_for_object_path_with_terminal_ref(
        &self,
        object: PhpObject,
        keys: &[ArrayKey],
        span: Span,
    ) -> Option<(ArrayCopySource, bool)> {
        let (first_key, rest_keys) = keys.split_first()?;
        let (return_target, class_id, returns_by_reference) =
            self.array_access_offset_get_target_for_object(&object, span)?;
        let target_keys =
            Self::array_access_offset_get_reference_keys(&return_target, &[first_key.clone()]);

        if rest_keys.is_empty() {
            return Some((
                ArrayCopySource::object_property(
                    object,
                    return_target.property,
                    target_keys,
                    false,
                ),
                returns_by_reference,
            ));
        }

        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        let property_value = object
            .read_property_from_context(
                &return_target.property,
                Some(class_id),
                &protected_class_ids,
            )
            .ok()?;
        let Value::Object(nested_object) = Self::array_path_value(&property_value, &target_keys)?
        else {
            return None;
        };
        if !self
            .classes
            .implements_interface(nested_object.class_id(), "ArrayAccess")
        {
            return None;
        }
        self.array_access_array_copy_source_for_object_path_with_terminal_ref(
            nested_object,
            rest_keys,
            span,
        )
    }

    fn array_access_offset_get_target_for_object(
        &self,
        object: &PhpObject,
        span: Span,
    ) -> Option<(ArrayAccessOffsetGetReferenceTarget, ClassId, bool)> {
        if !self
            .classes
            .implements_interface(object.class_id(), "ArrayAccess")
        {
            return None;
        }
        let (class_id, class_name, resolved_method_name, visibility, is_static) =
            self.resolve_instance_method(object.class_id(), "offsetGet")?;
        if is_static || visibility != Visibility::Public {
            return None;
        }
        let function = self
            .method_function(class_id, &class_name, &resolved_method_name, span)
            .ok()?;
        let function = function.as_ref();
        if function.params.len() != 1 {
            return None;
        }
        let return_target = self
            .array_access_offset_get_reference_target(function, span)
            .ok()?;
        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        object
            .property_visibility_from_context(
                &return_target.property,
                Some(class_id),
                &protected_class_ids,
            )
            .ok()?;
        Some((return_target, class_id, function.returns_by_reference))
    }

    fn side_effect_free_array_keys(
        indices: &[&Expr],
        scope: &SymbolTable,
    ) -> Option<Vec<ArrayKey>> {
        let mut keys = Vec::with_capacity(indices.len());
        for index in indices {
            keys.push(Self::side_effect_free_array_key(index, scope)?);
        }
        Some(keys)
    }

    fn side_effect_free_array_key(expr: &Expr, scope: &SymbolTable) -> Option<ArrayKey> {
        let value = Self::side_effect_free_value(expr, scope)?;
        ArrayKey::from_value(&value).ok()
    }

    fn side_effect_free_value(expr: &Expr, scope: &SymbolTable) -> Option<Value> {
        Some(match expr {
            Expr::Null(_) => Value::Null,
            Expr::Bool(value, _) => Value::Bool(*value),
            Expr::Int(value, _) => Value::Int(*value),
            Expr::Float(value, _) => Value::Float(*value),
            Expr::String(value, _) => php_string_literal_value(value),
            Expr::Variable(name, _) => scope.read_named(name)?,
            Expr::Property {
                target, property, ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    return None;
                };
                let Value::Object(object) = scope.read_named(object_name)? else {
                    return None;
                };
                object.read_public_property(property).ok()?
            }
            Expr::Index { target, index, .. } => {
                let Value::Array(array) = Self::side_effect_free_value(target, scope)? else {
                    return None;
                };
                let key = Self::side_effect_free_array_key(index, scope)?;
                array.get_cloned(key)?
            }
            _ => return None,
        })
    }

    fn call_required_iterator_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<Value> {
        if object.class_name().eq_ignore_ascii_case("Generator") {
            return self.call_generator_method_with_values(object, method_name, Vec::new(), span);
        }

        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), method_name)
        else {
            return Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            ));
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static Iterator methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, method_name, visibility, span)?;

        if self.resolved_method_is_core_array_object(class_id) {
            return self.call_array_object_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            return self.call_spl_object_storage_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_fixed_array(class_id) {
            return self.call_spl_fixed_array_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(class_id) {
            return self.call_spl_doubly_linked_list_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_directory_iterator(class_id) {
            return self.call_spl_directory_iterator_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(class_id) {
            return self.call_spl_recursive_iterator_iterator_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_file_info(class_id) {
            return self.call_spl_file_info_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_file_object(class_id) {
            return self.call_spl_file_object_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(class_id) {
            return self.call_spl_iterator_wrapper_method_with_values(
                object,
                method_name,
                Vec::new(),
                span,
            );
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity(function, 0, span)?;
        ensure_supported_function_signature(function, 0, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        self.call_user_function_with_this(
            function,
            object,
            Vec::new(),
            Some(class_id),
            Some(called_class_id),
        )
    }

    fn spl_iterator_wrapper_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&SplIteratorWrapperState> {
        self.spl_iterator_wrappers.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{}::{method_name}()", object.class_name()),
                    "missing SPL iterator wrapper runtime state",
                ),
            )
        })
    }

    fn spl_iterator_wrapper_inner_argument(
        &self,
        function: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let Value::Object(object) = value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #1 ($iterator) must be of type Iterator, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        };
        if !self
            .classes
            .implements_interface(object.class_id(), "Iterator")
        {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #1 ($iterator) must be of type Iterator, {} given",
                        object.class_name()
                    ),
                ),
            ));
        }
        Ok(object.clone())
    }

    fn spl_iterator_iterator_inner_argument(
        &mut self,
        function: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let Value::Object(object) = value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #1 ($iterator) must be of type Traversable, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        };
        if self
            .classes
            .implements_interface(object.class_id(), "Iterator")
        {
            return Ok(object.clone());
        }
        if self
            .classes
            .implements_interface(object.class_id(), "IteratorAggregate")
        {
            return match self.call_required_iterator_method(object.clone(), "getIterator", span)? {
                Value::Object(iterator)
                    if self
                        .classes
                        .implements_interface(iterator.class_id(), "Iterator") =>
                {
                    Ok(iterator)
                }
                Value::Object(iterator) => Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        format!(
                            "IteratorAggregate::getIterator() must return an Iterator object in the current subset, got {}",
                            iterator.class_name()
                        ),
                    ),
                )),
                other => Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        format!(
                            "IteratorAggregate::getIterator() must return a Traversable object for IteratorIterator, got {}",
                            other.type_name()
                        ),
                    ),
                )),
            };
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "Argument #1 ($iterator) must be of type Traversable, {} given",
                    object.class_name()
                ),
            ),
        ))
    }

    fn initialize_iterator_iterator(
        &mut self,
        object: &PhpObject,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        expect_arity("IteratorIterator::__construct", args, 1, span)?;
        let inner = self.spl_iterator_iterator_inner_argument(
            "IteratorIterator::__construct()",
            &args[0],
            span,
        )?;
        self.spl_iterator_wrappers
            .insert(object.id(), SplIteratorWrapperState::Forward { inner });
        Ok(())
    }

    fn initialize_no_rewind_iterator(
        &mut self,
        object: &PhpObject,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        expect_arity("NoRewindIterator::__construct", args, 1, span)?;
        let inner = self.spl_iterator_wrapper_inner_argument(
            "NoRewindIterator::__construct()",
            &args[0],
            span,
        )?;
        self.spl_iterator_wrappers.insert(
            object.id(),
            SplIteratorWrapperState::NoRewind {
                inner,
                current: None,
            },
        );
        Ok(())
    }

    fn spl_limit_iterator_bound_argument(
        function: &str,
        position: usize,
        name: &str,
        value: Option<&Value>,
        default: i64,
        minimum: i64,
        span: Span,
    ) -> CompileResult<i64> {
        let Some(value) = value else {
            return Ok(default);
        };
        let bound = php_internal_int_argument(function, position, name, value, span)?;
        if bound < minimum {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "{function}: Argument #{position} (${name}) must be greater than or equal to {minimum}"
                    ),
                ),
            ));
        }
        Ok(bound)
    }

    fn spl_limit_iterator_offset_out_of_range(offset: i64, span: Span) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "LimitIterator::rewind()",
                format!("Seek position {offset} is out of range"),
            ),
        )
    }

    fn spl_iterator_valid_bool(&mut self, inner: PhpObject, span: Span) -> CompileResult<bool> {
        Ok(self
            .call_required_iterator_method(inner, "valid", span)?
            .is_truthy())
    }

    fn advance_limit_iterator_to_offset(
        &mut self,
        inner: PhpObject,
        offset: i64,
        span: Span,
    ) -> CompileResult<()> {
        let mut advanced = 0_i64;
        while advanced < offset {
            if !self.spl_iterator_valid_bool(inner.clone(), span)? {
                return Err(Self::spl_limit_iterator_offset_out_of_range(offset, span));
            }
            self.call_required_iterator_method(inner.clone(), "next", span)?;
            advanced = advanced.saturating_add(1);
        }
        Ok(())
    }

    fn initialize_infinite_iterator(
        &mut self,
        object: &PhpObject,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        expect_arity("InfiniteIterator::__construct", args, 1, span)?;
        let inner = self.spl_iterator_wrapper_inner_argument(
            "InfiniteIterator::__construct()",
            &args[0],
            span,
        )?;
        self.spl_iterator_wrappers.insert(
            object.id(),
            SplIteratorWrapperState::Infinite {
                inner,
                valid_after_next: None,
            },
        );
        Ok(())
    }

    fn initialize_limit_iterator(
        &mut self,
        object: &PhpObject,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        if !(1..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "LimitIterator::__construct()",
                    ArityExpectation::Between { min: 1, max: 3 },
                    args.len(),
                ),
            ));
        }
        let inner = self.spl_iterator_wrapper_inner_argument(
            "LimitIterator::__construct()",
            &args[0],
            span,
        )?;
        let offset = Self::spl_limit_iterator_bound_argument(
            "LimitIterator::__construct()",
            2,
            "offset",
            args.get(1),
            0,
            0,
            span,
        )?;
        let limit = Self::spl_limit_iterator_bound_argument(
            "LimitIterator::__construct()",
            3,
            "limit",
            args.get(2),
            -1,
            -1,
            span,
        )?;
        self.spl_iterator_wrappers.insert(
            object.id(),
            SplIteratorWrapperState::Limit {
                inner,
                offset,
                limit,
                position: 0,
            },
        );
        Ok(())
    }

    fn call_spl_iterator_wrapper_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let method = method_name.to_ascii_lowercase();
        if self.is_spl_empty_iterator_class_id(object.class_id()) {
            return match method.as_str() {
                "rewind" | "next" => {
                    expect_arity(&format!("EmptyIterator::{method_name}"), &args, 0, span)?;
                    Ok(Value::Null)
                }
                "valid" => {
                    expect_arity("EmptyIterator::valid", &args, 0, span)?;
                    Ok(Value::Bool(false))
                }
                "current" => {
                    expect_arity("EmptyIterator::current", &args, 0, span)?;
                    Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "EmptyIterator::current()",
                            "Cannot access value of an EmptyIterator",
                        ),
                    ))
                }
                "key" => {
                    expect_arity("EmptyIterator::key", &args, 0, span)?;
                    Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "EmptyIterator::key()",
                            "Cannot access key of an EmptyIterator",
                        ),
                    ))
                }
                _ => Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!(
                        "{}::{method_name}()",
                        object.class_name()
                    )),
                )),
            };
        }

        if self.is_spl_iterator_iterator_class_id(object.class_id()) {
            return match method.as_str() {
                "__construct" => {
                    self.initialize_iterator_iterator(&object, &args, span)?;
                    Ok(Value::Null)
                }
                "rewind" | "valid" | "current" | "key" | "next" => {
                    expect_arity(&format!("IteratorIterator::{method_name}"), &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Forward { inner } => inner.clone(),
                        SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Infinite { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner, method_name, span)
                }
                "getinneriterator" => {
                    expect_arity("IteratorIterator::getInnerIterator", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Forward { inner } => inner.clone(),
                        SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Infinite { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    Ok(Value::Object(inner))
                }
                _ => Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!(
                        "{}::{method_name}()",
                        object.class_name()
                    )),
                )),
            };
        }

        if self.is_spl_no_rewind_iterator_class_id(object.class_id()) {
            return match method.as_str() {
                "__construct" => {
                    self.initialize_no_rewind_iterator(&object, &args, span)?;
                    Ok(Value::Null)
                }
                "rewind" => {
                    expect_arity("NoRewindIterator::rewind", &args, 0, span)?;
                    Ok(Value::Null)
                }
                "valid" | "current" | "key" | "next" => {
                    expect_arity(&format!("NoRewindIterator::{method_name}"), &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::NoRewind { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::Infinite { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    match method.as_str() {
                        "current" => {
                            if let Some(current) = self
                                .spl_iterator_wrappers
                                .get(&object.id())
                                .and_then(|state| match state {
                                    SplIteratorWrapperState::NoRewind { current, .. } => {
                                        current.clone()
                                    }
                                    _ => None,
                                })
                            {
                                return Ok(current);
                            }
                            let current =
                                self.call_required_iterator_method(inner, method_name, span)?;
                            if let Some(SplIteratorWrapperState::NoRewind {
                                current: cached, ..
                            }) = self.spl_iterator_wrappers.get_mut(&object.id())
                            {
                                *cached = Some(current.clone());
                            }
                            Ok(current)
                        }
                        "next" => {
                            if let Some(SplIteratorWrapperState::NoRewind { current, .. }) =
                                self.spl_iterator_wrappers.get_mut(&object.id())
                            {
                                *current = None;
                            }
                            self.call_required_iterator_method(inner, method_name, span)
                        }
                        _ => self.call_required_iterator_method(inner, method_name, span),
                    }
                }
                "getinneriterator" => {
                    expect_arity("NoRewindIterator::getInnerIterator", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::NoRewind { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::Infinite { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    Ok(Value::Object(inner))
                }
                _ => Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!(
                        "{}::{method_name}()",
                        object.class_name()
                    )),
                )),
            };
        }

        if self.is_spl_infinite_iterator_class_id(object.class_id()) {
            return match method.as_str() {
                "__construct" => {
                    self.initialize_infinite_iterator(&object, &args, span)?;
                    Ok(Value::Null)
                }
                "rewind" => {
                    expect_arity("InfiniteIterator::rewind", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Infinite { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner, "rewind", span)?;
                    if let Some(SplIteratorWrapperState::Infinite {
                        valid_after_next, ..
                    }) = self.spl_iterator_wrappers.get_mut(&object.id())
                    {
                        *valid_after_next = None;
                    }
                    Ok(Value::Null)
                }
                "valid" => {
                    expect_arity("InfiniteIterator::valid", &args, 0, span)?;
                    let (inner, valid_after_next) = match self
                        .spl_iterator_wrappers
                        .get_mut(&object.id())
                        .ok_or_else(|| {
                            runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    "InfiniteIterator::valid()",
                                    "missing SPL iterator wrapper runtime state",
                                ),
                            )
                        })? {
                        SplIteratorWrapperState::Infinite {
                            inner,
                            valid_after_next,
                        } => (inner.clone(), valid_after_next.take()),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    if let Some(true) = valid_after_next {
                        return Ok(Value::Bool(true));
                    }
                    Ok(Value::Bool(self.spl_iterator_valid_bool(inner, span)?))
                }
                "current" | "key" => {
                    expect_arity(&format!("InfiniteIterator::{method_name}"), &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Infinite { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner, method_name, span)
                }
                "next" => {
                    expect_arity("InfiniteIterator::next", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Infinite { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner.clone(), "next", span)?;
                    if self.spl_iterator_valid_bool(inner.clone(), span)? {
                        if let Some(SplIteratorWrapperState::Infinite {
                            valid_after_next, ..
                        }) = self.spl_iterator_wrappers.get_mut(&object.id())
                        {
                            *valid_after_next = Some(true);
                        }
                    } else {
                        self.call_required_iterator_method(inner, "rewind", span)?;
                        if let Some(SplIteratorWrapperState::Infinite {
                            valid_after_next, ..
                        }) = self.spl_iterator_wrappers.get_mut(&object.id())
                        {
                            *valid_after_next = None;
                        }
                    }
                    Ok(Value::Null)
                }
                "getinneriterator" => {
                    expect_arity("InfiniteIterator::getInnerIterator", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Infinite { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Limit { .. } => unreachable!(),
                    };
                    Ok(Value::Object(inner))
                }
                _ => Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!(
                        "{}::{method_name}()",
                        object.class_name()
                    )),
                )),
            };
        }

        if self.is_spl_limit_iterator_class_id(object.class_id()) {
            return match method.as_str() {
                "__construct" => {
                    self.initialize_limit_iterator(&object, &args, span)?;
                    Ok(Value::Null)
                }
                "rewind" => {
                    expect_arity("LimitIterator::rewind", &args, 0, span)?;
                    let (inner, offset) =
                        match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                            SplIteratorWrapperState::Limit { inner, offset, .. } => {
                                (inner.clone(), *offset)
                            }
                            SplIteratorWrapperState::Forward { .. }
                            | SplIteratorWrapperState::NoRewind { .. }
                            | SplIteratorWrapperState::Infinite { .. } => unreachable!(),
                        };
                    self.call_required_iterator_method(inner.clone(), "rewind", span)?;
                    self.advance_limit_iterator_to_offset(inner, offset, span)?;
                    if let Some(SplIteratorWrapperState::Limit { position, .. }) =
                        self.spl_iterator_wrappers.get_mut(&object.id())
                    {
                        *position = 0;
                    }
                    Ok(Value::Null)
                }
                "valid" => {
                    expect_arity("LimitIterator::valid", &args, 0, span)?;
                    let (inner, limit, position) =
                        match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                            SplIteratorWrapperState::Limit {
                                inner,
                                limit,
                                position,
                                ..
                            } => (inner.clone(), *limit, *position),
                            SplIteratorWrapperState::Forward { .. }
                            | SplIteratorWrapperState::NoRewind { .. }
                            | SplIteratorWrapperState::Infinite { .. } => unreachable!(),
                        };
                    if limit >= 0 && position >= limit {
                        return Ok(Value::Bool(false));
                    }
                    Ok(Value::Bool(self.spl_iterator_valid_bool(inner, span)?))
                }
                "current" | "key" => {
                    expect_arity(&format!("LimitIterator::{method_name}"), &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Limit { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Infinite { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner, method_name, span)
                }
                "next" => {
                    expect_arity("LimitIterator::next", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Limit { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Infinite { .. } => unreachable!(),
                    };
                    self.call_required_iterator_method(inner, "next", span)?;
                    if let Some(SplIteratorWrapperState::Limit { position, .. }) =
                        self.spl_iterator_wrappers.get_mut(&object.id())
                    {
                        *position = position.saturating_add(1);
                    }
                    Ok(Value::Null)
                }
                "getinneriterator" => {
                    expect_arity("LimitIterator::getInnerIterator", &args, 0, span)?;
                    let inner = match self.spl_iterator_wrapper_state(&object, method_name, span)? {
                        SplIteratorWrapperState::Limit { inner, .. } => inner.clone(),
                        SplIteratorWrapperState::Forward { .. }
                        | SplIteratorWrapperState::NoRewind { .. }
                        | SplIteratorWrapperState::Infinite { .. } => unreachable!(),
                    };
                    Ok(Value::Object(inner))
                }
                _ => Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!(
                        "{}::{method_name}()",
                        object.class_name()
                    )),
                )),
            };
        }

        Err(runtime_error(
            span,
            RuntimeError::undefined_function(format!("{}::{method_name}()", object.class_name())),
        ))
    }

    fn spl_file_info_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&SplFileInfoState> {
        self.spl_file_infos.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileInfo::{method_name}()"),
                    "missing SplFileInfo runtime state",
                ),
            )
        })
    }

    fn spl_file_info_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut SplFileInfoState> {
        self.spl_file_infos.get_mut(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileInfo::{method_name}()"),
                    "missing SplFileInfo runtime state",
                ),
            )
        })
    }

    fn spl_file_info_metadata_method_name(method_name: &str) -> Option<&'static str> {
        match method_name.to_ascii_lowercase().as_str() {
            "getgroup" => Some("SplFileInfo::getGroup"),
            "getinode" => Some("SplFileInfo::getInode"),
            "getlinktarget" => Some("SplFileInfo::getLinkTarget"),
            "getowner" => Some("SplFileInfo::getOwner"),
            "getperms" => Some("SplFileInfo::getPerms"),
            "getsize" => Some("SplFileInfo::getSize"),
            "isdir" => Some("SplFileInfo::isDir"),
            "isfile" => Some("SplFileInfo::isFile"),
            "islink" => Some("SplFileInfo::isLink"),
            _ => None,
        }
    }

    fn spl_file_info_metadata(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<fs::Metadata> {
        let function = Self::spl_file_info_metadata_method_name(method_name)
            .expect("metadata method name was already selected");
        let path = self
            .spl_file_info_state(object, method_name, span)?
            .path
            .clone();
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "stream wrappers are not supported in the current subset",
                ),
            ));
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            &path,
            &filesystem_path,
            span,
        )? {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("{function}(): stat failed for {path}"),
                ),
            ));
        }
        let Some(metadata) = self.cached_filesystem_metadata(&filesystem_path, true) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("{function}(): stat failed for {path}"),
                ),
            ));
        };
        if trailing_separator_requires_directory(&path) && !metadata.is_dir() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("{function}(): stat failed for {path}"),
                ),
            ));
        }
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        Ok(metadata)
    }

    fn spl_file_info_filesystem_path(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<(String, PathBuf)> {
        let function = Self::spl_file_info_metadata_method_name(method_name)
            .expect("metadata method name was already selected");
        let path = self
            .spl_file_info_state(object, method_name, span)?
            .path
            .clone();
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "stream wrappers are not supported in the current subset",
                ),
            ));
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            &path,
            &filesystem_path,
            span,
        )? {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("{function}(): stat failed for {path}"),
                ),
            ));
        }
        Ok((path, filesystem_path))
    }

    fn spl_file_info_class_argument(
        &self,
        function: &str,
        parameter_name: &'static str,
        base_class: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        let class_name = match value {
            Value::String(class_name) => class_name,
            Value::BinaryString(bytes) => {
                let class_name = tree_walk_binary_string_utf8(bytes, parameter_name, span)?;
                let normalized = class_name.strip_prefix('\\').unwrap_or(class_name);
                let valid = self
                    .classes
                    .lookup_class_id(normalized)
                    .is_some_and(|class_id| {
                        self.classes
                            .lookup_class_id(base_class)
                            .is_some_and(|base_id| {
                                class_id == base_id
                                    || self.classes.is_subclass_of(class_id, base_id)
                            })
                    });
                if valid {
                    return Ok(normalized.to_string());
                }
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!(
                            "{function}(): Argument #1 (${parameter_name}) must be a class name derived from {base_class}, {class_name} given"
                        ),
                    ),
                ));
            }
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!(
                            "{function}(): Argument #1 (${parameter_name}) must be of type string, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        let normalized = class_name.strip_prefix('\\').unwrap_or(class_name);
        let valid = self
            .classes
            .lookup_class_id(normalized)
            .is_some_and(|class_id| {
                self.classes
                    .lookup_class_id(base_class)
                    .is_some_and(|base_id| {
                        class_id == base_id || self.classes.is_subclass_of(class_id, base_id)
                    })
            });
        if valid {
            return Ok(normalized.to_string());
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{function}()"),
                format!(
                    "{function}(): Argument #1 (${parameter_name}) must be a class name derived from {base_class}, {class_name} given"
                ),
            ),
        ))
    }

    fn spl_file_info_path_extension(path: &str) -> String {
        let basename = Self::spl_file_info_path_basename(path);
        if basename == "." || basename == ".." {
            return String::new();
        }
        basename
            .rsplit_once('.')
            .map(|(_, extension)| extension.to_string())
            .unwrap_or_default()
    }

    fn spl_file_info_path_basename(path: &str) -> String {
        let trimmed = path.trim_end_matches(|ch| ch == '/' || ch == '\\');
        let path = if trimmed.is_empty() { path } else { trimmed };
        path.rsplit(|ch| ch == '/' || ch == '\\')
            .next()
            .unwrap_or(path)
            .to_string()
    }

    fn spl_file_info_basename_with_suffix(path: &str, suffix: Option<&str>) -> String {
        let basename = Self::spl_file_info_path_basename(path);
        let Some(suffix) = suffix else {
            return basename;
        };
        if suffix.is_empty()
            || suffix.contains('/')
            || suffix.contains('\\')
            || suffix.len() >= basename.len()
        {
            return basename;
        }
        basename
            .strip_suffix(suffix)
            .unwrap_or(&basename)
            .to_string()
    }

    fn spl_file_info_path_without_trailing_separators(path: &str) -> String {
        let trimmed = path.trim_end_matches(|ch| ch == '/' || ch == '\\');
        if trimmed.is_empty() {
            path.to_string()
        } else {
            trimmed.to_string()
        }
    }

    fn spl_file_info_debug_info_array(state: &SplFileInfoState) -> PhpArray {
        let mut properties = PhpArray::new();
        properties.insert("\0SplFileInfo\0pathName", Value::String(state.path.clone()));
        properties.insert(
            "\0SplFileInfo\0fileName",
            Value::String(Self::spl_file_info_path_basename(&state.path)),
        );
        properties
    }

    fn spl_file_info_parent_path(path: &str) -> String {
        let parent = Path::new(path).parent();
        parent
            .and_then(|parent| {
                let parent = parent.to_string_lossy();
                if parent.is_empty() {
                    None
                } else {
                    Some(parent.to_string())
                }
            })
            .unwrap_or_else(|| ".".to_string())
    }

    fn create_spl_file_info_object_for_class(
        &mut self,
        class_name: &str,
        path: String,
        span: Span,
    ) -> CompileResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(class_name)))?;
        if !self.is_spl_file_info_class_id(class_id) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileInfo",
                    format!("class must be SplFileInfo or a subclass, {class_name} given"),
                ),
            ));
        }
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("SplFileInfo class id should resolve to class metadata");
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.apply_instance_property_defaults(&object, class_id, span)?;
        self.spl_file_infos.insert(
            object.id(),
            SplFileInfoState {
                path,
                ..SplFileInfoState::default()
            },
        );
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn create_spl_file_object_for_class(
        &mut self,
        class_name: &str,
        constructor_args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(class_name)))?;
        if !self.is_spl_file_object_class_id(class_id) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject",
                    format!("class must be SplFileObject or a subclass, {class_name} given"),
                ),
            ));
        }
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("SplFileObject class id should resolve to class metadata");
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.apply_instance_property_defaults(&object, class_id, span)?;
        self.spl_file_infos
            .insert(object.id(), SplFileInfoState::default());
        self.initialize_spl_file_object(&object, &constructor_args, span)?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn call_spl_file_info_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                expect_arity("SplFileInfo::__construct", &args, 1, span)?;
                let path =
                    self.filesystem_filename_argument("SplFileInfo::__construct", &args[0], span)?;
                self.spl_file_info_state_mut(&object, "__construct", span)?
                    .path = path;
                Ok(Value::Null)
            }
            "__tostring" => {
                expect_arity("SplFileInfo::__toString", &args, 0, span)?;
                let path = self
                    .spl_file_info_state(&object, method_name, span)?
                    .path
                    .clone();
                Ok(Value::String(path))
            }
            "getgroup" => {
                expect_arity("SplFileInfo::getGroup", &args, 0, span)?;
                let metadata = self.spl_file_info_metadata(&object, method_name, span)?;
                Ok(Value::Int(filesystem_group_value(&metadata)))
            }
            "getinode" => {
                expect_arity("SplFileInfo::getInode", &args, 0, span)?;
                let metadata = self.spl_file_info_metadata(&object, method_name, span)?;
                Ok(Value::Int(filesystem_inode_value(&metadata)))
            }
            "getowner" => {
                expect_arity("SplFileInfo::getOwner", &args, 0, span)?;
                let metadata = self.spl_file_info_metadata(&object, method_name, span)?;
                Ok(Value::Int(filesystem_owner_value(&metadata)))
            }
            "getperms" => {
                expect_arity("SplFileInfo::getPerms", &args, 0, span)?;
                let metadata = self.spl_file_info_metadata(&object, method_name, span)?;
                Ok(Value::Int(filesystem_mode_bits(&metadata)))
            }
            "getsize" => {
                expect_arity("SplFileInfo::getSize", &args, 0, span)?;
                let metadata = self.spl_file_info_metadata(&object, method_name, span)?;
                Ok(Value::Int(metadata.len() as i64))
            }
            "isdir" => {
                expect_arity("SplFileInfo::isDir", &args, 0, span)?;
                let (_path, filesystem_path) =
                    self.spl_file_info_filesystem_path(&object, method_name, span)?;
                Ok(Value::Bool(
                    self.cached_filesystem_metadata(&filesystem_path, true)
                        .map(|metadata| metadata.is_dir())
                        .unwrap_or(false),
                ))
            }
            "isfile" => {
                expect_arity("SplFileInfo::isFile", &args, 0, span)?;
                let (_path, filesystem_path) =
                    self.spl_file_info_filesystem_path(&object, method_name, span)?;
                Ok(Value::Bool(
                    self.cached_filesystem_metadata(&filesystem_path, true)
                        .map(|metadata| metadata.is_file())
                        .unwrap_or(false),
                ))
            }
            "islink" => {
                expect_arity("SplFileInfo::isLink", &args, 0, span)?;
                let (_path, filesystem_path) =
                    self.spl_file_info_filesystem_path(&object, method_name, span)?;
                Ok(Value::Bool(
                    self.cached_filesystem_metadata(&filesystem_path, false)
                        .map(|metadata| metadata.file_type().is_symlink())
                        .unwrap_or(false),
                ))
            }
            "getlinktarget" => {
                expect_arity("SplFileInfo::getLinkTarget", &args, 0, span)?;
                let (path, filesystem_path) =
                    self.spl_file_info_filesystem_path(&object, method_name, span)?;
                let target = fs::read_link(&filesystem_path).map_err(|_| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileInfo::getLinkTarget()",
                            format!("SplFileInfo::getLinkTarget(): readlink failed for {path}"),
                        ),
                    )
                })?;
                let target = target.into_os_string().into_string().map_err(|_| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileInfo::getLinkTarget()",
                            "link target must be valid UTF-8 in the current subset",
                        ),
                    )
                })?;
                Ok(Value::String(target))
            }
            "getextension" => {
                expect_arity("SplFileInfo::getExtension", &args, 0, span)?;
                let path = self
                    .spl_file_info_state(&object, method_name, span)?
                    .path
                    .clone();
                Ok(Value::String(Self::spl_file_info_path_extension(&path)))
            }
            "getbasename" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileInfo::getBasename",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let suffix = match args.first() {
                    Some(Value::String(suffix)) => Some(suffix.as_str()),
                    Some(Value::BinaryString(bytes)) => {
                        Some(tree_walk_binary_string_utf8(bytes, "suffix", span)?)
                    }
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplFileInfo::getBasename()",
                                format!(
                                    "Argument #1 ($suffix) must be of type string, {} given",
                                    php_type_error_given(other)
                                ),
                            ),
                        ));
                    }
                    None => None,
                };
                let path = self
                    .spl_file_info_state(&object, method_name, span)?
                    .path
                    .clone();
                Ok(Value::String(Self::spl_file_info_basename_with_suffix(
                    &path, suffix,
                )))
            }
            "getfilename" => {
                expect_arity("SplFileInfo::getFilename", &args, 0, span)?;
                let path = self
                    .spl_file_info_state(&object, method_name, span)?
                    .path
                    .clone();
                Ok(Value::String(Self::spl_file_info_path_basename(&path)))
            }
            "__debuginfo" => {
                expect_arity("SplFileInfo::__debugInfo", &args, 0, span)?;
                let state = self
                    .spl_file_info_state(&object, method_name, span)?
                    .clone();
                Ok(Value::Array(Self::spl_file_info_debug_info_array(&state)))
            }
            "setfileclass" => {
                expect_arity("SplFileInfo::setFileClass", &args, 1, span)?;
                let class_name = self.spl_file_info_class_argument(
                    "SplFileInfo::setFileClass",
                    "class",
                    "SplFileObject",
                    &args[0],
                    span,
                )?;
                self.spl_file_info_state_mut(&object, method_name, span)?
                    .file_class = class_name;
                Ok(Value::Null)
            }
            "setinfoclass" => {
                expect_arity("SplFileInfo::setInfoClass", &args, 1, span)?;
                let class_name = self.spl_file_info_class_argument(
                    "SplFileInfo::setInfoClass",
                    "class",
                    "SplFileInfo",
                    &args[0],
                    span,
                )?;
                self.spl_file_info_state_mut(&object, method_name, span)?
                    .info_class = class_name;
                Ok(Value::Null)
            }
            "getfileinfo" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileInfo::getFileInfo",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let state = self
                    .spl_file_info_state(&object, method_name, span)?
                    .clone();
                let class_name = if let Some(value) = args.first() {
                    self.spl_file_info_class_argument(
                        "SplFileInfo::getFileInfo",
                        "class",
                        "SplFileInfo",
                        value,
                        span,
                    )?
                } else {
                    state.info_class
                };
                let path = Self::spl_file_info_path_without_trailing_separators(&state.path);
                self.create_spl_file_info_object_for_class(&class_name, path, span)
            }
            "getpathinfo" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileInfo::getPathInfo",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let state = self
                    .spl_file_info_state(&object, method_name, span)?
                    .clone();
                let class_name = if let Some(value) = args.first() {
                    self.spl_file_info_class_argument(
                        "SplFileInfo::getPathInfo",
                        "class",
                        "SplFileInfo",
                        value,
                        span,
                    )?
                } else {
                    state.info_class
                };
                let parent_path = Self::spl_file_info_parent_path(&state.path);
                self.create_spl_file_info_object_for_class(&class_name, parent_path, span)
            }
            "openfile" => {
                if args.len() > 3 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileInfo::openFile",
                            ArityExpectation::Between { min: 0, max: 3 },
                            args.len(),
                        ),
                    ));
                }
                let state = self
                    .spl_file_info_state(&object, method_name, span)?
                    .clone();
                let mut constructor_args = Vec::with_capacity(args.len() + 1);
                constructor_args.push(Value::String(state.path));
                constructor_args.extend(args);
                self.create_spl_file_object_for_class(&state.file_class, constructor_args, span)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn spl_directory_iterator_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&DirectoryIteratorState> {
        self.spl_directory_iterators
            .get(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("DirectoryIterator::{method_name}()"),
                        "missing DirectoryIterator runtime state",
                    ),
                )
            })
    }

    fn spl_directory_iterator_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut DirectoryIteratorState> {
        self.spl_directory_iterators
            .get_mut(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("DirectoryIterator::{method_name}()"),
                        "missing DirectoryIterator runtime state",
                    ),
                )
            })
    }

    fn spl_directory_iterator_initialized_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&DirectoryIteratorState> {
        let state = self.spl_directory_iterator_state(object, method_name, span)?;
        if state.initialized {
            Ok(state)
        } else {
            Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("DirectoryIterator::{method_name}()"),
                    "Object not initialized",
                ),
            ))
        }
    }

    fn spl_directory_iterator_directory_argument(
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        let path = match value {
            Value::String(path) => path.clone(),
            Value::BinaryString(bytes) => {
                tree_walk_binary_string_utf8(bytes, "filesystem path", span)?.to_string()
            }
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => value.echo_string(),
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "DirectoryIterator::__construct()",
                        format!(
                            "DirectoryIterator::__construct(): Argument #1 ($directory) must be of type string, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        if path.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "DirectoryIterator::__construct()",
                    "DirectoryIterator::__construct(): Argument #1 ($directory) must not be empty",
                ),
            ));
        }
        if path.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "DirectoryIterator::__construct()",
                    "DirectoryIterator::__construct(): Argument #1 ($directory) must not contain any null bytes",
                ),
            ));
        }
        Ok(path)
    }

    fn spl_directory_iterator_entries(
        function: &str,
        directory_path: &Path,
        span: Span,
    ) -> CompileResult<Vec<String>> {
        let mut entries = vec![".".to_string(), "..".to_string()];
        let read_dir = fs::read_dir(directory_path).map_err(|error| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("{function}(): Failed to open directory: {error}"),
                ),
            )
        })?;
        let mut host_entries = Vec::new();
        for entry in read_dir {
            let entry = entry.map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!("local directory entry read failed: {error}"),
                    ),
                )
            })?;
            let Some(name) = entry.file_name().to_str().map(str::to_string) else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        "non-UTF-8 directory entries are not supported in the current subset",
                    ),
                ));
            };
            host_entries.push(name);
        }
        host_entries.sort();
        entries.extend(host_entries);
        Ok(entries)
    }

    fn spl_directory_iterator_current_entry<'a>(
        state: &'a DirectoryIteratorState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&'a str> {
        state
            .entries
            .get(state.cursor)
            .map(String::as_str)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("DirectoryIterator::{method_name}()"),
                        "DirectoryIterator cursor is not valid",
                    ),
                )
            })
    }

    fn spl_directory_iterator_entry_is_dot(entry: &str) -> bool {
        entry == "." || entry == ".."
    }

    fn spl_directory_iterator_skip_dots_enabled(state: &DirectoryIteratorState) -> bool {
        state.flags & SPL_FILESYSTEM_SKIP_DOTS != 0
    }

    fn spl_directory_iterator_advance_past_dots(state: &mut DirectoryIteratorState) {
        if !Self::spl_directory_iterator_skip_dots_enabled(state) {
            return;
        }
        while state
            .entries
            .get(state.cursor)
            .is_some_and(|entry| Self::spl_directory_iterator_entry_is_dot(entry))
        {
            state.cursor += 1;
        }
    }

    fn spl_directory_iterator_current_filesystem_path(
        state: &DirectoryIteratorState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<PathBuf> {
        let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
        Ok(state.filesystem_path.join(entry))
    }

    fn spl_directory_iterator_current_path_string(
        state: &DirectoryIteratorState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<String> {
        let path = Self::spl_directory_iterator_current_filesystem_path(state, method_name, span)?;
        Ok(path.to_string_lossy().to_string())
    }

    fn spl_directory_iterator_current_metadata(
        &self,
        state: &DirectoryIteratorState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<fs::Metadata> {
        let path = Self::spl_directory_iterator_current_filesystem_path(state, method_name, span)?;
        fs::metadata(&path).map_err(|_| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("DirectoryIterator::{method_name}()"),
                    format!(
                        "DirectoryIterator::{method_name}(): stat failed for {}",
                        path.display()
                    ),
                ),
            )
        })
    }

    fn call_spl_directory_iterator_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                expect_arity("DirectoryIterator::__construct", &args, 1, span)?;
                let path = Self::spl_directory_iterator_directory_argument(&args[0], span)?;
                let filesystem_path = self.resolve_local_filesystem_operation_path(
                    "DirectoryIterator::__construct",
                    &path,
                    false,
                    span,
                )?;
                if !self.enforce_bounded_open_basedir(
                    "DirectoryIterator::__construct()",
                    &path,
                    &filesystem_path,
                    span,
                )? {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DirectoryIterator::__construct()",
                            format!("DirectoryIterator::__construct({path}): Failed to open directory: Permission denied"),
                        ),
                    ));
                }
                let metadata = fs::metadata(&filesystem_path).map_err(|error| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DirectoryIterator::__construct()",
                            format!(
                                "DirectoryIterator::__construct({path}): Failed to open directory: {}",
                                Self::filesystem_io_warning_message(&error)
                            ),
                        ),
                    )
                })?;
                if !metadata.is_dir() {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DirectoryIterator::__construct()",
                            format!("DirectoryIterator::__construct({path}): Failed to open directory: Not a directory"),
                        ),
                    ));
                }
                let entries = Self::spl_directory_iterator_entries(
                    "DirectoryIterator::__construct",
                    &filesystem_path,
                    span,
                )?;
                if let Some(info_state) = self.spl_file_infos.get_mut(&object.id()) {
                    info_state.path = path;
                }
                let state = self.spl_directory_iterator_state_mut(&object, "__construct", span)?;
                *state = DirectoryIteratorState {
                    filesystem_path,
                    entries,
                    cursor: 0,
                    initialized: true,
                    flags: 0,
                };
                Ok(Value::Null)
            }
            "current" => {
                expect_arity("DirectoryIterator::current", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                if state.cursor < state.entries.len() {
                    if self.is_spl_filesystem_iterator_class_id(object.class_id()) {
                        match state.flags & SPL_FILESYSTEM_CURRENT_MODE_MASK {
                            SPL_FILESYSTEM_CURRENT_AS_SELF => Ok(Value::Object(object)),
                            SPL_FILESYSTEM_CURRENT_AS_PATHNAME => Ok(Value::String(
                                Self::spl_directory_iterator_current_path_string(
                                    state,
                                    method_name,
                                    span,
                                )?,
                            )),
                            _ => {
                                let path = Self::spl_directory_iterator_current_path_string(
                                    state,
                                    method_name,
                                    span,
                                )?;
                                self.create_spl_file_info_object_for_class(
                                    "SplFileInfo",
                                    path,
                                    span,
                                )
                            }
                        }
                    } else {
                        Ok(Value::Object(object))
                    }
                } else {
                    Ok(Value::Bool(false))
                }
            }
            "key" => {
                expect_arity("DirectoryIterator::key", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                if self.is_spl_filesystem_iterator_class_id(object.class_id()) {
                    if state.flags & SPL_FILESYSTEM_KEY_MODE_MASK == SPL_FILESYSTEM_KEY_AS_FILENAME
                    {
                        let entry =
                            Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                        Ok(Value::String(entry.to_string()))
                    } else {
                        Ok(Value::String(
                            Self::spl_directory_iterator_current_path_string(
                                state,
                                method_name,
                                span,
                            )?,
                        ))
                    }
                } else {
                    Ok(Value::Int(state.cursor as i64))
                }
            }
            "next" => {
                expect_arity("DirectoryIterator::next", &args, 0, span)?;
                let state = self.spl_directory_iterator_state_mut(&object, method_name, span)?;
                if !state.initialized {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DirectoryIterator::next()",
                            "Object not initialized",
                        ),
                    ));
                }
                state.cursor = state.cursor.saturating_add(1);
                Self::spl_directory_iterator_advance_past_dots(state);
                Ok(Value::Null)
            }
            "rewind" => {
                expect_arity("DirectoryIterator::rewind", &args, 0, span)?;
                let state = self.spl_directory_iterator_state_mut(&object, method_name, span)?;
                if !state.initialized {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DirectoryIterator::rewind()",
                            "Object not initialized",
                        ),
                    ));
                }
                state.cursor = 0;
                Self::spl_directory_iterator_advance_past_dots(state);
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("DirectoryIterator::valid", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                Ok(Value::Bool(state.cursor < state.entries.len()))
            }
            "getfilename" => {
                expect_arity("DirectoryIterator::getFilename", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                Ok(Value::String(
                    Self::spl_directory_iterator_current_entry(state, method_name, span)?
                        .to_string(),
                ))
            }
            "getbasename" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DirectoryIterator::getBasename",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let suffix = match args.first() {
                    Some(Value::String(suffix)) => Some(suffix.as_str()),
                    Some(Value::BinaryString(bytes)) => {
                        Some(tree_walk_binary_string_utf8(bytes, "suffix", span)?)
                    }
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DirectoryIterator::getBasename()",
                                format!(
                                    "Argument #1 ($suffix) must be of type string, {} given",
                                    php_type_error_given(other)
                                ),
                            ),
                        ));
                    }
                    None => None,
                };
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                Ok(Value::String(Self::spl_file_info_basename_with_suffix(
                    entry, suffix,
                )))
            }
            "getextension" => {
                expect_arity("DirectoryIterator::getExtension", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                Ok(Value::String(Self::spl_file_info_path_extension(entry)))
            }
            "isdot" => {
                expect_arity("DirectoryIterator::isDot", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                Ok(Value::Bool(Self::spl_directory_iterator_entry_is_dot(
                    entry,
                )))
            }
            "isfile" => {
                expect_arity("DirectoryIterator::isFile", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let metadata =
                    self.spl_directory_iterator_current_metadata(state, method_name, span)?;
                Ok(Value::Bool(metadata.is_file()))
            }
            "getgroup" => {
                expect_arity("DirectoryIterator::getGroup", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let metadata =
                    self.spl_directory_iterator_current_metadata(state, method_name, span)?;
                Ok(Value::Int(filesystem_group_value(&metadata)))
            }
            "getinode" => {
                expect_arity("DirectoryIterator::getInode", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let metadata =
                    self.spl_directory_iterator_current_metadata(state, method_name, span)?;
                Ok(Value::Int(filesystem_inode_value(&metadata)))
            }
            "getowner" => {
                expect_arity("DirectoryIterator::getOwner", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let metadata =
                    self.spl_directory_iterator_current_metadata(state, method_name, span)?;
                Ok(Value::Int(filesystem_owner_value(&metadata)))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn call_spl_filesystem_iterator_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                if args.is_empty() || args.len() > 2 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "FilesystemIterator::__construct",
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let path = Self::spl_directory_iterator_directory_argument(&args[0], span)?;
                let flags = match args.get(1) {
                    Some(value) => php_internal_int_argument(
                        "FilesystemIterator::__construct()",
                        2,
                        "flags",
                        value,
                        span,
                    )?,
                    None => SPL_FILESYSTEM_SKIP_DOTS,
                } & SPL_FILESYSTEM_FLAGS_MASK;
                let filesystem_path = self.resolve_local_filesystem_operation_path(
                    "FilesystemIterator::__construct",
                    &path,
                    false,
                    span,
                )?;
                if !self.enforce_bounded_open_basedir(
                    "FilesystemIterator::__construct()",
                    &path,
                    &filesystem_path,
                    span,
                )? {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "FilesystemIterator::__construct()",
                            format!("FilesystemIterator::__construct({path}): Failed to open directory: Permission denied"),
                        ),
                    ));
                }
                let metadata = fs::metadata(&filesystem_path).map_err(|error| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "FilesystemIterator::__construct()",
                            format!(
                                "FilesystemIterator::__construct({path}): Failed to open directory: {}",
                                Self::filesystem_io_warning_message(&error)
                            ),
                        ),
                    )
                })?;
                if !metadata.is_dir() {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "FilesystemIterator::__construct()",
                            format!("FilesystemIterator::__construct({path}): Failed to open directory: Not a directory"),
                        ),
                    ));
                }
                let entries = Self::spl_directory_iterator_entries(
                    "FilesystemIterator::__construct",
                    &filesystem_path,
                    span,
                )?;
                if let Some(info_state) = self.spl_file_infos.get_mut(&object.id()) {
                    info_state.path = path;
                }
                let state = self.spl_directory_iterator_state_mut(&object, "__construct", span)?;
                *state = DirectoryIteratorState {
                    filesystem_path,
                    entries,
                    cursor: 0,
                    initialized: true,
                    flags,
                };
                Self::spl_directory_iterator_advance_past_dots(state);
                Ok(Value::Null)
            }
            "getflags" => {
                expect_arity("FilesystemIterator::getFlags", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                Ok(Value::Int(state.flags))
            }
            "setflags" => {
                expect_arity("FilesystemIterator::setFlags", &args, 1, span)?;
                let flags = php_internal_int_argument(
                    "FilesystemIterator::setFlags()",
                    1,
                    "flags",
                    &args[0],
                    span,
                )? & SPL_FILESYSTEM_FLAGS_MASK;
                let state = self.spl_directory_iterator_state_mut(&object, method_name, span)?;
                if !state.initialized {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "FilesystemIterator::setFlags()",
                            "Object not initialized",
                        ),
                    ));
                }
                state.flags = flags;
                Self::spl_directory_iterator_advance_past_dots(state);
                Ok(Value::Null)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn spl_recursive_iterator_iterator_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&RecursiveIteratorIteratorState> {
        self.spl_recursive_iterator_iterators
            .get(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("RecursiveIteratorIterator::{method_name}()"),
                        "missing RecursiveIteratorIterator runtime state",
                    ),
                )
            })
    }

    fn spl_recursive_iterator_iterator_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut RecursiveIteratorIteratorState> {
        self.spl_recursive_iterator_iterators
            .get_mut(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("RecursiveIteratorIterator::{method_name}()"),
                        "missing RecursiveIteratorIterator runtime state",
                    ),
                )
            })
    }

    fn spl_recursive_join_path(left: &str, right: &str) -> String {
        if left.is_empty() {
            right.to_string()
        } else {
            Path::new(left).join(right).to_string_lossy().to_string()
        }
    }

    fn spl_recursive_directory_iteration_entries(
        root: &Path,
        include_root_entries: bool,
        flags: i64,
        span: Span,
    ) -> CompileResult<Vec<RecursiveDirectoryIterationEntry>> {
        let mut entries = Vec::new();
        Self::spl_recursive_directory_collect_entries(
            root,
            "",
            include_root_entries,
            flags,
            &mut entries,
            span,
        )?;
        Ok(entries)
    }

    fn spl_recursive_directory_collect_entries(
        directory: &Path,
        relative_directory: &str,
        include_directory_entries: bool,
        flags: i64,
        entries: &mut Vec<RecursiveDirectoryIterationEntry>,
        span: Span,
    ) -> CompileResult<()> {
        if include_directory_entries {
            for name in [".", ".."] {
                entries.push(RecursiveDirectoryIterationEntry {
                    sub_path: relative_directory.to_string(),
                    sub_pathname: Self::spl_recursive_join_path(relative_directory, name),
                });
            }
        }

        let read_dir = fs::read_dir(directory).map_err(|error| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "RecursiveIteratorIterator::__construct()",
                    format!("recursive directory read failed: {error}"),
                ),
            )
        })?;
        let mut host_entries = Vec::new();
        for entry in read_dir {
            let entry = entry.map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "RecursiveIteratorIterator::__construct()",
                        format!("recursive directory entry read failed: {error}"),
                    ),
                )
            })?;
            let Some(name) = entry.file_name().to_str().map(str::to_string) else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "RecursiveIteratorIterator::__construct()",
                        "non-UTF-8 directory entries are not supported in the current subset",
                    ),
                ));
            };
            host_entries.push(name);
        }
        host_entries.sort();

        for name in host_entries {
            let filesystem_path = directory.join(&name);
            let relative_path = Self::spl_recursive_join_path(relative_directory, &name);
            let symlink_metadata = fs::symlink_metadata(&filesystem_path).map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "RecursiveIteratorIterator::__construct()",
                        format!("recursive directory metadata read failed: {error}"),
                    ),
                )
            })?;
            let is_symlink = symlink_metadata.file_type().is_symlink();
            let is_directory = if is_symlink {
                flags & SPL_FILESYSTEM_FOLLOW_SYMLINKS != 0
                    && fs::metadata(&filesystem_path)
                        .map(|metadata| metadata.is_dir())
                        .unwrap_or(false)
            } else {
                symlink_metadata.is_dir()
            };
            if is_directory {
                Self::spl_recursive_directory_collect_entries(
                    &filesystem_path,
                    &relative_path,
                    true,
                    flags,
                    entries,
                    span,
                )?;
            } else {
                entries.push(RecursiveDirectoryIterationEntry {
                    sub_path: relative_directory.to_string(),
                    sub_pathname: relative_path,
                });
            }
        }
        Ok(())
    }

    fn spl_recursive_iterator_active_entries(
        state: &RecursiveIteratorIteratorState,
    ) -> &[RecursiveDirectoryIterationEntry] {
        if state.rewound {
            &state.rewound_entries
        } else {
            &state.initial_entries
        }
    }

    fn spl_recursive_iterator_current_entry<'a>(
        state: &'a RecursiveIteratorIteratorState,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&'a RecursiveDirectoryIterationEntry> {
        Self::spl_recursive_iterator_active_entries(state)
            .get(state.cursor)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("RecursiveIteratorIterator::{method_name}()"),
                        "RecursiveIteratorIterator cursor is not valid",
                    ),
                )
            })
    }

    fn call_spl_recursive_directory_iterator_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "haschildren" => {
                expect_arity("RecursiveDirectoryIterator::hasChildren", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                if Self::spl_directory_iterator_entry_is_dot(entry) {
                    return Ok(Value::Bool(false));
                }
                let path =
                    Self::spl_directory_iterator_current_filesystem_path(state, method_name, span)?;
                let symlink_metadata = match fs::symlink_metadata(&path) {
                    Ok(metadata) => metadata,
                    Err(_) => return Ok(Value::Bool(false)),
                };
                let is_symlink = symlink_metadata.file_type().is_symlink();
                let is_directory = if is_symlink {
                    state.flags & SPL_FILESYSTEM_FOLLOW_SYMLINKS != 0
                        && fs::metadata(&path)
                            .map(|metadata| metadata.is_dir())
                            .unwrap_or(false)
                } else {
                    symlink_metadata.is_dir()
                };
                Ok(Value::Bool(is_directory))
            }
            "getsubpath" => {
                expect_arity("RecursiveDirectoryIterator::getSubPath", &args, 0, span)?;
                Ok(Value::String(String::new()))
            }
            "getsubpathname" => {
                expect_arity("RecursiveDirectoryIterator::getSubPathname", &args, 0, span)?;
                let state =
                    self.spl_directory_iterator_initialized_state(&object, method_name, span)?;
                let entry = Self::spl_directory_iterator_current_entry(state, method_name, span)?;
                Ok(Value::String(entry.to_string()))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn call_spl_recursive_iterator_iterator_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                expect_arity("RecursiveIteratorIterator::__construct", &args, 1, span)?;
                let iterator = match &args[0] {
                    Value::Object(iterator)
                        if self
                            .is_spl_recursive_directory_iterator_class_id(iterator.class_id()) =>
                    {
                        iterator.clone()
                    }
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "RecursiveIteratorIterator::__construct()",
                                format!(
                                    "Argument #1 ($iterator) must be RecursiveDirectoryIterator in the current subset, {} given",
                                    php_type_error_given(other)
                                ),
                            ),
                        ));
                    }
                };
                let directory_state = self
                    .spl_directory_iterator_initialized_state(&iterator, "__construct", span)?
                    .clone();
                let initial_entries = Self::spl_recursive_directory_iteration_entries(
                    &directory_state.filesystem_path,
                    false,
                    directory_state.flags,
                    span,
                )?;
                let rewound_entries = Self::spl_recursive_directory_iteration_entries(
                    &directory_state.filesystem_path,
                    true,
                    directory_state.flags,
                    span,
                )?;
                self.spl_recursive_iterator_iterators.insert(
                    object.id(),
                    RecursiveIteratorIteratorState {
                        initial_entries,
                        rewound_entries,
                        cursor: 0,
                        rewound: false,
                    },
                );
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("RecursiveIteratorIterator::valid", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    state.cursor < Self::spl_recursive_iterator_active_entries(state).len(),
                ))
            }
            "next" => {
                expect_arity("RecursiveIteratorIterator::next", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state_mut(&object, method_name, span)?;
                state.cursor = state.cursor.saturating_add(1);
                Ok(Value::Null)
            }
            "rewind" => {
                expect_arity("RecursiveIteratorIterator::rewind", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state_mut(&object, method_name, span)?;
                state.cursor = 0;
                state.rewound = true;
                Ok(Value::Null)
            }
            "getsubpath" => {
                expect_arity("RecursiveIteratorIterator::getSubPath", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state(&object, method_name, span)?;
                let entry = Self::spl_recursive_iterator_current_entry(state, method_name, span)?;
                Ok(Value::String(entry.sub_path.clone()))
            }
            "getsubpathname" => {
                expect_arity("RecursiveIteratorIterator::getSubPathname", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state(&object, method_name, span)?;
                let entry = Self::spl_recursive_iterator_current_entry(state, method_name, span)?;
                Ok(Value::String(entry.sub_pathname.clone()))
            }
            "current" => {
                expect_arity("RecursiveIteratorIterator::current", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state(&object, method_name, span)?;
                let Some(entry) =
                    Self::spl_recursive_iterator_active_entries(state).get(state.cursor)
                else {
                    return Ok(Value::Bool(false));
                };
                Ok(Value::String(entry.sub_pathname.clone()))
            }
            "key" => {
                expect_arity("RecursiveIteratorIterator::key", &args, 0, span)?;
                let state =
                    self.spl_recursive_iterator_iterator_state(&object, method_name, span)?;
                Ok(Value::Int(state.cursor as i64))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn spl_file_object_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&SplFileObjectState> {
        self.spl_file_objects.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileObject::{method_name}()"),
                    "missing SplFileObject runtime state",
                ),
            )
        })
    }

    fn evaluate_spl_file_object_method_arguments(
        &mut self,
        method_name: &str,
        args: &[Expr],
        _span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Vec<Value>> {
        let csv_control_method = matches!(
            method_name.to_ascii_lowercase().as_str(),
            "setcsvcontrol" | "fgetcsv"
        );
        let uses_named_or_spread = args.iter().any(|arg| {
            matches!(
                arg,
                Expr::NamedArgument { .. } | Expr::SpreadArgument { .. }
            )
        });
        if !csv_control_method || !uses_named_or_spread {
            return args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>();
        }

        let mut values: Vec<Option<Value>> = vec![None, None, None];
        let mut positional_index = 0_usize;
        for arg in args {
            match arg {
                Expr::NamedArgument { name, expr, span } => {
                    let Some(index) =
                        Self::spl_file_object_method_parameter_index(method_name, name)
                    else {
                        return Err(runtime_error(
                            *span,
                            RuntimeError::unsupported_call(
                                format!("SplFileObject::{method_name}()"),
                                format!(
                                    "named argument ${name} does not match a supported SplFileObject::{method_name}() parameter in the current subset"
                                ),
                            ),
                        ));
                    };
                    if values[index].is_some() || index < positional_index {
                        return Err(runtime_error(
                            *span,
                            RuntimeError::unsupported_call(
                                format!("SplFileObject::{method_name}()"),
                                format!("Named parameter ${name} overwrites previous argument"),
                            ),
                        ));
                    }
                    values[index] =
                        Some(self.evaluate_by_value_argument_with_cow_source(expr, caller_scope)?);
                }
                Expr::SpreadArgument { span, .. } => {
                    return Err(runtime_error(
                        *span,
                        RuntimeError::unsupported_call(
                            format!("SplFileObject::{method_name}()"),
                            format!(
                                "argument unpacking is not implemented for SplFileObject::{method_name}() in the current subset"
                            ),
                        ),
                    ));
                }
                expr => {
                    if positional_index >= values.len() || values[positional_index].is_some() {
                        return Err(runtime_error(
                            expr.span(),
                            RuntimeError::arity_mismatch(
                                format!("SplFileObject::{method_name}()"),
                                ArityExpectation::Between { min: 0, max: 3 },
                                args.len(),
                            ),
                        ));
                    }
                    values[positional_index] =
                        Some(self.evaluate_by_value_argument_with_cow_source(expr, caller_scope)?);
                    positional_index += 1;
                }
            }
        }

        Ok(vec![
            values[0]
                .take()
                .unwrap_or_else(|| Value::String(",".to_string())),
            values[1]
                .take()
                .unwrap_or_else(|| Value::String("\"".to_string())),
            values[2]
                .take()
                .unwrap_or_else(|| Value::String("\\".to_string())),
        ])
    }

    fn spl_file_object_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut SplFileObjectState> {
        self.spl_file_objects.get_mut(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileObject::{method_name}()"),
                    "missing SplFileObject runtime state",
                ),
            )
        })
    }

    fn spl_file_object_split_lines(contents: &str) -> Vec<String> {
        contents
            .split_inclusive('\n')
            .map(ToString::to_string)
            .collect()
    }

    fn spl_file_object_cursor_for_byte_position(contents: &str, byte_position: usize) -> usize {
        let position = utf8_boundary_at_or_before(contents, byte_position.min(contents.len()));
        contents[..position]
            .as_bytes()
            .iter()
            .filter(|byte| **byte == b'\n')
            .count()
    }

    fn spl_file_object_byte_position_for_cursor(state: &SplFileObjectState) -> usize {
        state
            .lines
            .iter()
            .take(state.cursor)
            .map(String::len)
            .sum::<usize>()
            .min(state.contents.len())
    }

    fn spl_file_object_sync_cursor_from_byte_position(state: &mut SplFileObjectState) {
        state.byte_position = utf8_boundary_at_or_before(
            &state.contents,
            state.byte_position.min(state.contents.len()),
        );
        state.cursor =
            Self::spl_file_object_cursor_for_byte_position(&state.contents, state.byte_position);
    }

    fn spl_file_object_sync_byte_position_from_cursor(state: &mut SplFileObjectState) {
        state.byte_position = Self::spl_file_object_byte_position_for_cursor(state);
    }

    fn spl_file_object_stream_id(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<i64> {
        self.spl_file_object_state(object, method_name, span)?
            .stream_id
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("SplFileObject::{method_name}()"),
                        "missing SplFileObject stream state",
                    ),
                )
            })
    }

    fn spl_file_object_refresh_from_stream(
        &mut self,
        object_id: i64,
        stream_id: i64,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        let (filesystem_path, position) = {
            let stream = self.streams.get_mut(&stream_id).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("SplFileObject::{method_name}()"),
                        "SplFileObject stream is closed",
                    ),
                )
            })?;
            match stream {
                StreamResource::File(stream) => {
                    if stream.writable {
                        stream.file.flush().map_err(|error| {
                            runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    format!("SplFileObject::{method_name}()"),
                                    format!("local file stream flush failed: {error}"),
                                ),
                            )
                        })?;
                    }
                    let position = stream.file.stream_position().map_err(|error| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("SplFileObject::{method_name}()"),
                                format!("local file stream position failed: {error}"),
                            ),
                        )
                    })?;
                    (stream.filesystem_path.clone(), position)
                }
                StreamResource::Memory(_) => {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("SplFileObject::{method_name}()"),
                            "SplFileObject memory streams are not implemented in this subset",
                        ),
                    ));
                }
            }
        };
        let contents = fs::read_to_string(&filesystem_path).map_err(|error| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileObject::{method_name}()"),
                    format!("local file stream read failed: {error}"),
                ),
            )
        })?;
        let state = self.spl_file_objects.get_mut(&object_id).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplFileObject::{method_name}()"),
                    "missing SplFileObject runtime state",
                ),
            )
        })?;
        state.contents = contents;
        state.lines = Self::spl_file_object_split_lines(&state.contents);
        state.byte_position = (position as usize).min(state.contents.len());
        Self::spl_file_object_sync_cursor_from_byte_position(state);
        Ok(())
    }

    fn spl_file_object_apply_max_line_len(state: &SplFileObjectState, line: &str) -> String {
        if state.max_line_len == 0 {
            return line.to_string();
        }
        let end = utf8_boundary_at_or_before(line, state.max_line_len.min(line.len()));
        line[..end].to_string()
    }

    fn spl_file_object_line_string(state: &SplFileObjectState, line: &str) -> String {
        let line = if state.flags & SPL_FILE_OBJECT_DROP_NEW_LINE != 0 {
            csv_record_without_line_ending(line).to_string()
        } else {
            line.to_string()
        };
        Self::spl_file_object_apply_max_line_len(state, &line)
    }

    fn spl_file_object_csv_array_from_line(
        line: &str,
        delimiter: char,
        enclosure: char,
        escape: Option<char>,
    ) -> Value {
        let fields = parse_bounded_csv_record(line, delimiter, enclosure, escape);
        let mut array = PhpArray::new();
        if fields.len() == 1
            && fields[0].is_empty()
            && csv_record_without_line_ending(line).is_empty()
        {
            array.insert(0_i64, Value::Null);
        } else {
            for (index, field) in fields.into_iter().enumerate() {
                array.insert(index as i64, Value::String(field));
            }
        }
        Value::Array(array)
    }

    fn spl_file_object_current_value(state: &SplFileObjectState) -> Value {
        let Some(line) = state.lines.get(state.cursor) else {
            return Value::Bool(false);
        };
        if state.flags & SPL_FILE_OBJECT_READ_CSV != 0 {
            return Self::spl_file_object_csv_array_from_line(
                line,
                state.csv_separator,
                state.csv_enclosure,
                state.csv_escape,
            );
        }
        Value::String(Self::spl_file_object_line_string(state, line))
    }

    fn spl_file_object_csv_control_array(state: &SplFileObjectState) -> Value {
        let mut array = PhpArray::new();
        array.insert(0_i64, Value::String(state.csv_separator.to_string()));
        array.insert(1_i64, Value::String(state.csv_enclosure.to_string()));
        array.insert(
            2_i64,
            Value::String(
                state
                    .csv_escape
                    .map(|escape| escape.to_string())
                    .unwrap_or_default(),
            ),
        );
        Value::Array(array)
    }

    fn spl_file_object_bool_argument(
        function: &str,
        position: usize,
        name: &'static str,
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<bool> {
        match value {
            Some(Value::Null) | None => Ok(false),
            Some(Value::Bool(flag)) => Ok(*flag),
            Some(Value::Int(flag)) => Ok(*flag != 0),
            Some(Value::Float(flag)) => Ok(*flag != 0.0),
            Some(Value::String(flag)) => Ok(Value::String(flag.clone()).is_truthy()),
            Some(Value::BinaryString(bytes)) => {
                let flag = tree_walk_binary_string_utf8(bytes, name, span)?;
                Ok(Value::String(flag.to_string()).is_truthy())
            }
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #{position} (${name}) must be of type bool, {} given",
                        php_type_error_given(other)
                    ),
                ),
            )),
        }
    }

    fn spl_file_object_constructor_mode(
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            None => Ok("r".to_string()),
            Some(Value::String(mode)) => Ok(mode.clone()),
            Some(Value::BinaryString(bytes)) => {
                Ok(tree_walk_binary_string_utf8(bytes, "SplFileObject mode", span)?.to_string())
            }
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject::__construct()",
                    format!(
                        "Argument #2 ($mode) must be of type string, {} given",
                        php_type_error_given(other)
                    ),
                ),
            )),
        }
    }

    fn initialize_spl_file_object(
        &mut self,
        object: &PhpObject,
        args: &[Value],
        span: Span,
    ) -> CompileResult<()> {
        if !(1..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "SplFileObject::__construct()",
                    ArityExpectation::Between { min: 1, max: 4 },
                    args.len(),
                ),
            ));
        }

        let path =
            self.filesystem_filename_argument("SplFileObject::__construct", &args[0], span)?;
        if let Some(info_state) = self.spl_file_infos.get_mut(&object.id()) {
            info_state.path = path.clone();
        }
        let mode = Self::spl_file_object_constructor_mode(args.get(1), span)?;
        let Some(stream_mode) = parse_stream_mode(&mode) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject::__construct()",
                    format!("mode {mode:?} is not supported in the current SplFileObject subset"),
                ),
            ));
        };
        let use_include_path = Self::spl_file_object_bool_argument(
            "SplFileObject::__construct()",
            3,
            "useIncludePath",
            args.get(2),
            span,
        )?;
        if let Some(context) = args.get(3) {
            self.expect_optional_stream_context_resource(
                "SplFileObject::__construct",
                context,
                span,
            )?;
        }
        if !self.ensure_stream_wrapper_can_open_path("SplFileObject::__construct()", &path, span)? {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject::__construct()",
                    format!("Cannot open file {path}"),
                ),
            ));
        }

        let filesystem_path = if let Some(file_url_path) = bounded_local_file_url_path(&path) {
            file_url_path.map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call("SplFileObject::__construct()", message),
                )
            })?
        } else if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject::__construct()",
                    "only local file:// URLs and local file paths are supported in the current SplFileObject subset",
                ),
            ));
        } else {
            self.resolve_file_get_contents_path(&path, use_include_path)
        };

        if !self.enforce_bounded_open_basedir(
            "SplFileObject::__construct()",
            &path,
            &filesystem_path,
            span,
        )? {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SplFileObject::__construct()",
                    format!("Cannot open file {path}"),
                ),
            ));
        }

        let realpath_entry = self.bounded_realpath_entry_for_local_path(&filesystem_path);
        let existed_before_open = filesystem_path.exists();
        let file = fs::OpenOptions::new()
            .read(stream_mode.readable)
            .write(stream_mode.writable)
            .create(stream_mode.create)
            .create_new(stream_mode.create_new)
            .truncate(stream_mode.truncate)
            .open(&filesystem_path)
            .map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "SplFileObject::__construct()",
                        format!(
                            "Cannot open file {path}: {}",
                            php_filesystem_open_error_message(&error)
                        ),
                    ),
                )
            })?;
        if let Some((resolved, metadata)) = realpath_entry {
            self.cache_realpath_entry(resolved, &metadata);
        }
        if stream_mode.create && !existed_before_open {
            self.set_bounded_unix_permissions(
                &filesystem_path,
                self.effective_umask_mode(0o666),
                "SplFileObject::__construct",
                span,
            )?;
        }
        if stream_mode.truncate || stream_mode.create || stream_mode.create_new {
            self.clear_stat_cache_filesystem_path_aliases(&filesystem_path);
        }
        let stream_id = self.next_resource_id;
        self.next_resource_id += 1;
        let mut stream = FileStream {
            file,
            readable: stream_mode.readable,
            writable: stream_mode.writable,
            append: stream_mode.append,
            eof: false,
            metadata_unread_bytes: 0,
            uri: path.to_string(),
            filesystem_path: filesystem_path.clone(),
            read_filter_rot13: false,
            metadata_mode: mode,
        };
        if stream.append {
            stream.file.seek(SeekFrom::Start(0)).map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "SplFileObject::__construct()",
                        format!("local file stream seek failed: {error}"),
                    ),
                )
            })?;
        }
        self.streams.insert(stream_id, StreamResource::File(stream));

        let contents = if stream_mode.readable {
            fs::read_to_string(&filesystem_path).map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "SplFileObject::__construct()",
                        format!(
                            "Cannot open file {path}: {}",
                            php_filesystem_open_error_message(&error)
                        ),
                    ),
                )
            })?
        } else {
            String::new()
        };
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        let lines = Self::spl_file_object_split_lines(&contents);
        let eof = lines.is_empty();
        self.spl_file_objects.insert(
            object.id(),
            SplFileObjectState {
                contents,
                lines,
                cursor: 0,
                byte_position: 0,
                eof,
                stream_id: Some(stream_id),
                ..SplFileObjectState::default()
            },
        );
        Ok(())
    }

    fn call_spl_file_object_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                self.initialize_spl_file_object(&object, &args, span)?;
                Ok(Value::Null)
            }
            "current" | "getcurrentline" => {
                expect_arity("SplFileObject::current", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Self::spl_file_object_current_value(state))
            }
            "fgetc" => {
                expect_arity("SplFileObject::fgetc", &args, 0, span)?;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                if state.byte_position >= state.contents.len() {
                    state.eof = true;
                    return Ok(Value::Bool(false));
                }
                let start = utf8_boundary_at_or_before(&state.contents, state.byte_position);
                let Some(character) = state.contents[start..].chars().next() else {
                    state.eof = true;
                    return Ok(Value::Bool(false));
                };
                state.byte_position = start + character.len_utf8();
                state.eof = false;
                Self::spl_file_object_sync_cursor_from_byte_position(state);
                Ok(Value::String(character.to_string()))
            }
            "fgets" => {
                expect_arity("SplFileObject::fgets", &args, 0, span)?;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                let line = state
                    .lines
                    .get(state.cursor)
                    .cloned()
                    .map(|line| Self::spl_file_object_apply_max_line_len(state, &line))
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false));
                if state.cursor < state.lines.len() {
                    state.cursor += 1;
                    Self::spl_file_object_sync_byte_position_from_cursor(state);
                    state.eof = state.cursor >= state.lines.len();
                } else {
                    state.eof = true;
                }
                Ok(line)
            }
            "fread" => {
                expect_arity("SplFileObject::fread", &args, 1, span)?;
                let length = php_internal_int_argument(
                    "SplFileObject::fread()",
                    1,
                    "length",
                    &args[0],
                    span,
                )?;
                if length <= 0 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileObject::fread()",
                            "SplFileObject::fread(): Argument #1 ($length) must be greater than 0",
                        ),
                    ));
                }
                let length = length as usize;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                let start = utf8_boundary_at_or_before(
                    &state.contents,
                    state.byte_position.min(state.contents.len()),
                );
                let end = utf8_boundary_at_or_before(
                    &state.contents,
                    start.saturating_add(length).min(state.contents.len()),
                );
                let contents = state.contents[start..end].to_string();
                state.byte_position = end;
                state.eof = end >= state.contents.len() && contents.len() < length;
                Self::spl_file_object_sync_cursor_from_byte_position(state);
                Ok(Value::String(contents))
            }
            "fpassthru" => {
                expect_arity("SplFileObject::fpassthru", &args, 0, span)?;
                let contents = {
                    let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                    let start = utf8_boundary_at_or_before(
                        &state.contents,
                        state.byte_position.min(state.contents.len()),
                    );
                    let contents = state.contents[start..].to_string();
                    state.byte_position = state.contents.len();
                    state.eof = true;
                    Self::spl_file_object_sync_cursor_from_byte_position(state);
                    contents
                };
                let length = contents.len() as i64;
                self.append_output_at(&contents, span);
                Ok(Value::Int(length))
            }
            "fwrite" | "fputs" => {
                if args.is_empty() || args.len() > 2 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileObject::fwrite()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let stream_id = self.spl_file_object_stream_id(&object, method_name, span)?;
                let mut fwrite_args = vec![Value::Resource(stream_id), args[0].clone()];
                if let Some(length) = args.get(1) {
                    fwrite_args.push(length.clone());
                }
                let result = self.call_fwrite(&fwrite_args, span)?;
                if matches!(result, Value::Int(_)) {
                    self.spl_file_object_refresh_from_stream(
                        object.id(),
                        stream_id,
                        method_name,
                        span,
                    )?;
                    let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                    state.eof = false;
                }
                Ok(result)
            }
            "fputcsv" => {
                if args.is_empty() || args.len() > 5 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileObject::fputcsv()",
                            ArityExpectation::Between { min: 1, max: 5 },
                            args.len(),
                        ),
                    ));
                }
                let state = self.spl_file_object_state(&object, method_name, span)?;
                let stream_id = state.stream_id.ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileObject::fputcsv()",
                            "missing SplFileObject stream state",
                        ),
                    )
                })?;
                let separator = csv_single_character_argument(
                    "SplFileObject::fputcsv()",
                    "separator",
                    args.get(1),
                    state.csv_separator,
                    false,
                    span,
                )?
                .expect("non-empty separator has a character");
                let enclosure = csv_single_character_argument(
                    "SplFileObject::fputcsv()",
                    "enclosure",
                    args.get(2),
                    state.csv_enclosure,
                    false,
                    span,
                )?
                .expect("non-empty enclosure has a character");
                let escape = csv_single_character_argument(
                    "SplFileObject::fputcsv()",
                    "escape",
                    args.get(3),
                    state.csv_escape.unwrap_or('\\'),
                    true,
                    span,
                )?;
                let mut fputcsv_args = Vec::with_capacity(6);
                fputcsv_args.push(Value::Resource(stream_id));
                fputcsv_args.push(args[0].clone());
                fputcsv_args.push(Value::String(separator.to_string()));
                fputcsv_args.push(Value::String(enclosure.to_string()));
                fputcsv_args.push(Value::String(
                    escape.map(|escape| escape.to_string()).unwrap_or_default(),
                ));
                fputcsv_args.push(
                    args.get(4)
                        .cloned()
                        .unwrap_or_else(|| Value::String("\n".to_string())),
                );
                let result = self.call_fputcsv(&fputcsv_args, span)?;
                if matches!(result, Value::Int(_)) {
                    self.spl_file_object_refresh_from_stream(
                        object.id(),
                        stream_id,
                        method_name,
                        span,
                    )?;
                    let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                    state.eof = false;
                }
                Ok(result)
            }
            "fflush" => {
                expect_arity("SplFileObject::fflush", &args, 0, span)?;
                let stream_id = self.spl_file_object_stream_id(&object, method_name, span)?;
                self.call_fflush(&[Value::Resource(stream_id)], span)
            }
            "ftell" => {
                expect_arity("SplFileObject::ftell", &args, 0, span)?;
                let stream_id = self.spl_file_object_stream_id(&object, method_name, span)?;
                self.call_ftell(&[Value::Resource(stream_id)], span)
            }
            "fstat" => {
                expect_arity("SplFileObject::fstat", &args, 0, span)?;
                let stream_id = self.spl_file_object_stream_id(&object, method_name, span)?;
                self.call_fstat(&[Value::Resource(stream_id)], span)
            }
            "fgetcsv" => {
                if args.len() > 3 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileObject::fgetcsv()",
                            ArityExpectation::Between { min: 0, max: 3 },
                            args.len(),
                        ),
                    ));
                }
                let state_snapshot = self
                    .spl_file_object_state(&object, method_name, span)?
                    .clone();
                let separator = match args.first() {
                    Some(value) => csv_single_character_argument(
                        "SplFileObject::fgetcsv()",
                        "separator",
                        Some(value),
                        state_snapshot.csv_separator,
                        false,
                        span,
                    )?
                    .expect("non-empty separator has a character"),
                    None => state_snapshot.csv_separator,
                };
                let enclosure = match args.get(1) {
                    Some(value) => csv_single_character_argument(
                        "SplFileObject::fgetcsv()",
                        "enclosure",
                        Some(value),
                        state_snapshot.csv_enclosure,
                        false,
                        span,
                    )?
                    .expect("non-empty enclosure has a character"),
                    None => state_snapshot.csv_enclosure,
                };
                if args.get(2).is_none() && !state_snapshot.csv_escape_configured {
                    self.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        "SplFileObject::fgetcsv(): the $escape parameter must be provided, as its default value will change, either explicitly or via SplFileObject::setCsvControl()",
                        span,
                    )?;
                }
                let escape = match args.get(2) {
                    Some(value) => csv_single_character_argument(
                        "SplFileObject::fgetcsv()",
                        "escape",
                        Some(value),
                        state_snapshot.csv_escape.unwrap_or('\\'),
                        true,
                        span,
                    )?,
                    None => state_snapshot.csv_escape,
                };
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                let Some(line) = state.lines.get(state.cursor).cloned() else {
                    state.eof = true;
                    return Ok(Value::Bool(false));
                };
                state.cursor += 1;
                Self::spl_file_object_sync_byte_position_from_cursor(state);
                state.eof = state.cursor >= state.lines.len();
                Ok(Self::spl_file_object_csv_array_from_line(
                    &line, separator, enclosure, escape,
                ))
            }
            "getcsvcontrol" => {
                expect_arity("SplFileObject::getCsvControl", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Self::spl_file_object_csv_control_array(state))
            }
            "getflags" => {
                expect_arity("SplFileObject::getFlags", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Value::Int(state.flags))
            }
            "getmaxlinelen" => {
                expect_arity("SplFileObject::getMaxLineLen", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Value::Int(state.max_line_len as i64))
            }
            "setcsvcontrol" => {
                if args.len() > 3 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplFileObject::setCsvControl()",
                            ArityExpectation::Between { min: 0, max: 3 },
                            args.len(),
                        ),
                    ));
                }
                let separator = csv_single_character_argument(
                    "SplFileObject::setCsvControl()",
                    "separator",
                    args.first(),
                    ',',
                    false,
                    span,
                )?
                .expect("non-empty separator has a character");
                let enclosure = csv_single_character_argument(
                    "SplFileObject::setCsvControl()",
                    "enclosure",
                    args.get(1),
                    '"',
                    false,
                    span,
                )?
                .expect("non-empty enclosure has a character");
                let escape = csv_single_character_argument(
                    "SplFileObject::setCsvControl()",
                    "escape",
                    args.get(2),
                    '\\',
                    true,
                    span,
                )?;
                let escape_configured = args.get(2).is_some();
                if !escape_configured {
                    self.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        "SplFileObject::setCsvControl(): the $escape parameter must be provided as its default value will change",
                        span,
                    )?;
                }
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.csv_separator = separator;
                state.csv_enclosure = enclosure;
                state.csv_escape = escape;
                state.csv_escape_configured = escape_configured;
                Ok(Value::Null)
            }
            "setflags" => {
                expect_arity("SplFileObject::setFlags", &args, 1, span)?;
                let flags = php_internal_int_argument(
                    "SplFileObject::setFlags()",
                    1,
                    "flags",
                    &args[0],
                    span,
                )?;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.flags = flags;
                Ok(Value::Null)
            }
            "setmaxlinelen" => {
                expect_arity("SplFileObject::setMaxLineLen", &args, 1, span)?;
                let max_length = php_internal_int_argument(
                    "SplFileObject::setMaxLineLen()",
                    1,
                    "maxLength",
                    &args[0],
                    span,
                )?;
                if max_length < 0 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileObject::setMaxLineLen()",
                            "SplFileObject::setMaxLineLen(): Argument #1 ($maxLength) must be greater than or equal to 0",
                        ),
                    ));
                }
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.max_line_len = max_length as usize;
                Ok(Value::Null)
            }
            "key" => {
                expect_arity("SplFileObject::key", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Value::Int(state.cursor as i64))
            }
            "next" => {
                expect_arity("SplFileObject::next", &args, 0, span)?;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.cursor = state.cursor.saturating_add(1).min(state.lines.len());
                Self::spl_file_object_sync_byte_position_from_cursor(state);
                state.eof = state.cursor >= state.lines.len();
                Ok(Value::Null)
            }
            "rewind" => {
                expect_arity("SplFileObject::rewind", &args, 0, span)?;
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.cursor = 0;
                state.byte_position = 0;
                state.eof = state.lines.is_empty();
                Ok(Value::Null)
            }
            "seek" => {
                expect_arity("SplFileObject::seek", &args, 1, span)?;
                let line =
                    php_internal_int_argument("SplFileObject::seek()", 1, "line", &args[0], span)?;
                if line < 0 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplFileObject::seek()",
                            "SplFileObject::seek(): Argument #1 ($line) must be greater than or equal to 0",
                        ),
                    ));
                }
                let state = self.spl_file_object_state_mut(&object, method_name, span)?;
                state.cursor = (line as usize).min(state.lines.len());
                Self::spl_file_object_sync_byte_position_from_cursor(state);
                state.eof = state.cursor >= state.lines.len();
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("SplFileObject::valid", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Value::Bool(!state.eof && state.cursor < state.lines.len()))
            }
            "eof" => {
                expect_arity("SplFileObject::eof", &args, 0, span)?;
                let state = self.spl_file_object_state(&object, method_name, span)?;
                Ok(Value::Bool(state.eof))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn spl_object_storage_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&SplObjectStorageState> {
        self.spl_object_storages.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplObjectStorage::{method_name}()"),
                    "missing SplObjectStorage runtime state",
                ),
            )
        })
    }

    fn spl_object_storage_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut SplObjectStorageState> {
        self.spl_object_storages
            .get_mut(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("SplObjectStorage::{method_name}()"),
                        "missing SplObjectStorage runtime state",
                    ),
                )
            })
    }

    fn spl_object_storage_object_argument(
        method_name: &str,
        args: &[Value],
        index: usize,
        span: Span,
    ) -> CompileResult<PhpObject> {
        match args.get(index) {
            Some(Value::Object(object)) => Ok(object.clone()),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplObjectStorage::{method_name}()"),
                    format!(
                        "SplObjectStorage::{method_name}(): Argument #{} ($object) must be of type object, {} given",
                        index + 1,
                        other.type_name()
                    ),
                ),
            )),
            None => Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    format!("SplObjectStorage::{method_name}()"),
                    ArityExpectation::AtLeast(index + 1),
                    args.len(),
                ),
            )),
        }
    }

    fn spl_object_storage_argument(
        &self,
        method_name: &str,
        args: &[Value],
        index: usize,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let object = Self::spl_object_storage_object_argument(method_name, args, index, span)?;
        if self.is_spl_object_storage_object(&object) {
            Ok(object)
        } else {
            Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplObjectStorage::{method_name}()"),
                    format!(
                        "argument #{} must be a SplObjectStorage instance, got {}",
                        index + 1,
                        object.class_name()
                    ),
                ),
            ))
        }
    }

    fn spl_object_storage_insert_or_update(
        state: &mut SplObjectStorageState,
        hash: String,
        object: PhpObject,
        info: Value,
    ) {
        if let Some(entry) = state.entries.iter_mut().find(|entry| entry.hash == hash) {
            entry.hash = hash;
            entry.object = object;
            entry.info = info;
        } else {
            state
                .entries
                .push(SplObjectStorageEntry { hash, object, info });
        }
    }

    fn spl_object_storage_remove_with_cursor_key_mode(
        state: &mut SplObjectStorageState,
        hash: &str,
        preserve_cursor_key: bool,
    ) {
        if let Some(index) = state.entries.iter().position(|entry| entry.hash == hash) {
            state.entries.remove(index);
            if state.cursor > index {
                state.cursor -= 1;
            }
            if state.cursor > state.entries.len() {
                state.cursor = state.entries.len();
            }
            if !preserve_cursor_key {
                state.cursor_key = state.cursor;
            }
        }
    }

    fn spl_object_storage_remove(state: &mut SplObjectStorageState, hash: &str) {
        Self::spl_object_storage_remove_with_cursor_key_mode(state, hash, false);
    }

    fn spl_object_storage_flat_array_from_state(state: &SplObjectStorageState) -> PhpArray {
        let mut array = PhpArray::new();
        for entry in &state.entries {
            array.insert(
                ArrayKey::Int(array.len() as i64),
                Value::Object(entry.object.clone()),
            );
            array.insert(ArrayKey::Int(array.len() as i64), entry.info.clone());
        }
        array
    }

    fn spl_object_storage_entries_from_flat_array(
        &mut self,
        storage: PhpObject,
        array: &PhpArray,
        method_name: &str,
        span: Span,
    ) -> CompileResult<Vec<SplObjectStorageEntry>> {
        if array.len() % 2 != 0 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplObjectStorage::{method_name}()"),
                    "serialized storage entry array must contain object/info pairs",
                ),
            ));
        }

        let mut entries = Vec::with_capacity(array.len() / 2);
        let mut pending_object = None;
        for (index, entry) in array.entries().iter().enumerate() {
            if index % 2 == 0 {
                let Value::Object(object) = entry.value() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("SplObjectStorage::{method_name}()"),
                            format!(
                                "serialized storage object entry must be object, {} given",
                                entry.value().type_name()
                            ),
                        ),
                    ));
                };
                pending_object = Some(object.clone());
                continue;
            }

            let object = pending_object
                .take()
                .expect("even entry should set pending storage object");
            let hash =
                self.spl_object_storage_hash_for_object(storage.clone(), object.clone(), span)?;
            entries.push(SplObjectStorageEntry {
                hash,
                object,
                info: entry.value_cloned(),
            });
        }

        Ok(entries)
    }

    fn replace_spl_object_storage_entries_from_array(
        &mut self,
        object: PhpObject,
        array: &PhpArray,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.ensure_spl_object_storage_not_hashing(method_name, span)?;
        let entries = self.spl_object_storage_entries_from_flat_array(
            object.clone(),
            array,
            method_name,
            span,
        )?;
        self.spl_object_storages.insert(
            object.id(),
            SplObjectStorageState {
                entries,
                cursor: 0,
                cursor_key: 0,
            },
        );
        Ok(())
    }

    fn spl_object_storage_serialized_properties_array(object: &PhpObject) -> PhpArray {
        let mut properties = PhpArray::new();
        for property in object
            .properties()
            .into_iter()
            .filter(|property| property.is_initialized() && !property.is_unset())
        {
            properties.insert(
                ArrayKey::String(property.mangled_name()),
                property.value_cloned(),
            );
        }
        properties
    }

    fn apply_spl_object_storage_serialized_properties(
        &self,
        object: &PhpObject,
        properties: &PhpArray,
        span: Span,
    ) -> CompileResult<()> {
        for entry in properties.entries() {
            let ArrayKey::String(name) = &entry.key else {
                continue;
            };
            object
                .write_serialized_property(name, entry.value_cloned())
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(())
    }

    fn spl_object_storage_remove_preserving_cursor_key(
        state: &mut SplObjectStorageState,
        hash: &str,
    ) {
        Self::spl_object_storage_remove_with_cursor_key_mode(state, hash, true);
    }

    fn call_spl_object_storage_offset_unset_array_syntax_with_values(
        &mut self,
        object: PhpObject,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity("SplObjectStorage::offsetUnset", &args, 1, span)?;
        let stored_object =
            Self::spl_object_storage_object_argument("offsetUnset", &args, 0, span)?;
        self.ensure_spl_object_storage_not_hashing("offsetUnset", span)?;
        let hash = self.spl_object_storage_hash_for_object(object.clone(), stored_object, span)?;
        let state = self.spl_object_storage_state_mut(&object, "offsetUnset", span)?;
        Self::spl_object_storage_remove_preserving_cursor_key(state, &hash);
        Ok(Value::Null)
    }

    fn ensure_spl_object_storage_not_hashing(
        &self,
        method_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        if self.spl_object_storage_get_hash_depth == 0 {
            return Ok(());
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("SplObjectStorage::{method_name}()"),
                "Modification of SplObjectStorage during getHash() is prohibited",
            ),
        ))
    }

    fn spl_object_storage_hash_for_object(
        &mut self,
        storage: PhpObject,
        stored_object: PhpObject,
        span: Span,
    ) -> CompileResult<String> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(storage.class_id(), "getHash")
        else {
            return Ok(stored_object.id().to_string());
        };

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            return Ok(stored_object.id().to_string());
        }

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::getHash()"),
                    "static SplObjectStorage::getHash() overrides are not implemented",
                ),
            ));
        }
        self.ensure_instance_method_visible(class_id, &class_name, "getHash", visibility, span)?;

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity(function, 1, span)?;
        ensure_supported_function_metadata(function, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        self.spl_object_storage_get_hash_depth += 1;
        let result = self.call_user_function_with_this(
            function,
            storage.clone(),
            vec![Value::Object(stored_object)],
            Some(class_id),
            Some(storage.class_id()),
        );
        self.spl_object_storage_get_hash_depth -= 1;

        match result? {
            Value::String(hash) => Ok(hash),
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::getHash()"),
                    format!(
                        "{class_name}::getHash(): Return value must be of type string, {} returned",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn spl_object_storage_objects_equal(
        &self,
        left: &PhpObject,
        right: &PhpObject,
        span: Span,
    ) -> CompileResult<bool> {
        if !left.class_name().eq_ignore_ascii_case(right.class_name()) {
            return Ok(false);
        }

        let left_state = self.spl_object_storage_state(left, "compare", span)?;
        let right_state = self.spl_object_storage_state(right, "compare", span)?;
        if left_state.entries.len() != right_state.entries.len() {
            return Ok(false);
        }

        for left_entry in &left_state.entries {
            let Some(right_entry) = right_state
                .entries
                .iter()
                .find(|entry| entry.hash == left_entry.hash)
            else {
                return Ok(false);
            };
            if left_entry.object.id() != right_entry.object.id() {
                return Ok(false);
            }
            if !left_entry
                .info
                .php_cmp_checked(&right_entry.info, Comparison::Eq)
                .map_err(|error| runtime_error(span, error))?
            {
                return Ok(false);
            }
        }

        Ok(true)
    }

    fn call_spl_object_storage_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                expect_arity("SplObjectStorage::__construct", &args, 0, span)?;
                Ok(Value::Null)
            }
            "__serialize" => {
                expect_arity("SplObjectStorage::__serialize", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                let mut result = PhpArray::new();
                result.insert(
                    ArrayKey::Int(0),
                    Value::Array(Self::spl_object_storage_flat_array_from_state(state)),
                );
                result.insert(
                    ArrayKey::Int(1),
                    Value::Array(Self::spl_object_storage_serialized_properties_array(
                        &object,
                    )),
                );
                Ok(Value::Array(result))
            }
            "__unserialize" => {
                expect_arity("SplObjectStorage::__unserialize", &args, 1, span)?;
                let Some(Value::Array(data)) = args.first() else {
                    let given = args
                        .first()
                        .map(php_type_error_given)
                        .unwrap_or_else(|| "none".to_string());
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplObjectStorage::__unserialize()",
                            format!("Argument #1 ($data) must be of type array, {given} given"),
                        ),
                    ));
                };
                let Some(Value::Array(entries)) = data.get(ArrayKey::Int(0)) else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplObjectStorage::__unserialize()",
                            "Argument #1 ($data) must contain a storage entry array",
                        ),
                    ));
                };
                self.replace_spl_object_storage_entries_from_array(
                    object.clone(),
                    entries,
                    "__unserialize",
                    span,
                )?;
                if let Some(Value::Array(properties)) = data.get(ArrayKey::Int(1)) {
                    self.apply_spl_object_storage_serialized_properties(&object, properties, span)?;
                }
                Ok(Value::Null)
            }
            "attach" | "offsetset" => {
                if !(args.len() == 1 || args.len() == 2) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            format!("SplObjectStorage::{method_name}()"),
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let stored_object =
                    Self::spl_object_storage_object_argument(method_name, &args, 0, span)?;
                let info = args.get(1).cloned().unwrap_or(Value::Null);
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let hash = self.spl_object_storage_hash_for_object(
                    object.clone(),
                    stored_object.clone(),
                    span,
                )?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                Self::spl_object_storage_insert_or_update(state, hash, stored_object, info);
                Ok(Value::Null)
            }
            "detach" | "offsetunset" => {
                expect_arity(&format!("SplObjectStorage::{method_name}"), &args, 1, span)?;
                let stored_object =
                    Self::spl_object_storage_object_argument(method_name, &args, 0, span)?;
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let hash =
                    self.spl_object_storage_hash_for_object(object.clone(), stored_object, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                Self::spl_object_storage_remove(state, &hash);
                Ok(Value::Null)
            }
            "contains" | "offsetexists" => {
                expect_arity(&format!("SplObjectStorage::{method_name}"), &args, 1, span)?;
                let stored_object =
                    Self::spl_object_storage_object_argument(method_name, &args, 0, span)?;
                let hash =
                    self.spl_object_storage_hash_for_object(object.clone(), stored_object, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    state.entries.iter().any(|entry| entry.hash == hash),
                ))
            }
            "offsetget" => {
                expect_arity("SplObjectStorage::offsetGet", &args, 1, span)?;
                let stored_object =
                    Self::spl_object_storage_object_argument(method_name, &args, 0, span)?;
                let hash =
                    self.spl_object_storage_hash_for_object(object.clone(), stored_object, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                state
                    .entries
                    .iter()
                    .find(|entry| entry.hash == hash)
                    .map(|entry| entry.info.clone())
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplObjectStorage::offsetGet()",
                                "Object not found",
                            ),
                        )
                    })
            }
            "count" => {
                expect_arity("SplObjectStorage::count", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                Ok(Value::Int(state.entries.len() as i64))
            }
            "rewind" => {
                expect_arity("SplObjectStorage::rewind", &args, 0, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                state.cursor = 0;
                state.cursor_key = 0;
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("SplObjectStorage::valid", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                Ok(Value::Bool(state.cursor < state.entries.len()))
            }
            "key" => {
                expect_arity("SplObjectStorage::key", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                Ok(Value::Int(state.cursor_key as i64))
            }
            "current" => {
                expect_arity("SplObjectStorage::current", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                state
                    .entries
                    .get(state.cursor)
                    .map(|entry| Value::Object(entry.object.clone()))
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplObjectStorage::current()",
                                "Called current() on invalid iterator",
                            ),
                        )
                    })
            }
            "next" => {
                expect_arity("SplObjectStorage::next", &args, 0, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                state.cursor = state.cursor.saturating_add(1);
                state.cursor_key = state.cursor_key.saturating_add(1);
                Ok(Value::Null)
            }
            "getinfo" => {
                expect_arity("SplObjectStorage::getInfo", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                Ok(state
                    .entries
                    .get(state.cursor)
                    .map(|entry| entry.info.clone())
                    .unwrap_or(Value::Null))
            }
            "setinfo" => {
                expect_arity("SplObjectStorage::setInfo", &args, 1, span)?;
                let info = args.first().cloned().unwrap_or(Value::Null);
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                if let Some(entry) = state.entries.get_mut(state.cursor) {
                    entry.info = info;
                }
                Ok(Value::Null)
            }
            "gethash" => {
                expect_arity("SplObjectStorage::getHash", &args, 1, span)?;
                let stored_object =
                    Self::spl_object_storage_object_argument(method_name, &args, 0, span)?;
                Ok(Value::String(stored_object.id().to_string()))
            }
            "addall" => {
                expect_arity("SplObjectStorage::addAll", &args, 1, span)?;
                let other = self.spl_object_storage_argument(method_name, &args, 0, span)?;
                let other_state = self
                    .spl_object_storage_state(&other, method_name, span)?
                    .clone();
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let mut entries = Vec::with_capacity(other_state.entries.len());
                for entry in other_state.entries {
                    let hash = self.spl_object_storage_hash_for_object(
                        object.clone(),
                        entry.object.clone(),
                        span,
                    )?;
                    entries.push((hash, entry.object, entry.info));
                }
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                for (hash, stored_object, info) in entries {
                    Self::spl_object_storage_insert_or_update(state, hash, stored_object, info);
                }
                Ok(Value::Null)
            }
            "removeall" => {
                expect_arity("SplObjectStorage::removeAll", &args, 1, span)?;
                let other = self.spl_object_storage_argument(method_name, &args, 0, span)?;
                let other_hashes = self
                    .spl_object_storage_state(&other, method_name, span)?
                    .entries
                    .iter()
                    .map(|entry| entry.hash.clone())
                    .collect::<HashSet<_>>();
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                state
                    .entries
                    .retain(|entry| !other_hashes.contains(&entry.hash));
                if state.cursor > state.entries.len() {
                    state.cursor = state.entries.len();
                }
                state.cursor_key = state.cursor;
                Ok(Value::Null)
            }
            "removeallexcept" => {
                expect_arity("SplObjectStorage::removeAllExcept", &args, 1, span)?;
                let other = self.spl_object_storage_argument(method_name, &args, 0, span)?;
                let own_entries = self
                    .spl_object_storage_state(&object, method_name, span)?
                    .entries
                    .iter()
                    .map(|entry| (entry.hash.clone(), entry.object.clone()))
                    .collect::<Vec<_>>();
                let other_hashes = self
                    .spl_object_storage_state(&other, method_name, span)?
                    .entries
                    .iter()
                    .map(|entry| entry.hash.clone())
                    .collect::<HashSet<_>>();
                let other_uses_core_hash = self
                    .resolve_instance_method(other.class_id(), "getHash")
                    .is_some_and(|(class_id, _, _, _, _)| {
                        self.resolved_method_is_core_spl_object_storage(class_id)
                    });
                let allowed_hashes = if other_uses_core_hash {
                    other_hashes
                } else {
                    let mut allowed = HashSet::new();
                    for (own_hash, stored_object) in own_entries {
                        let other_hash = self.spl_object_storage_hash_for_object(
                            other.clone(),
                            stored_object,
                            span,
                        )?;
                        if other_hashes.contains(&other_hash) {
                            allowed.insert(own_hash);
                        }
                    }
                    allowed
                };
                self.ensure_spl_object_storage_not_hashing(method_name, span)?;
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                state
                    .entries
                    .retain(|entry| allowed_hashes.contains(&entry.hash));
                if state.cursor > state.entries.len() {
                    state.cursor = state.entries.len();
                }
                state.cursor_key = state.cursor;
                Ok(Value::Null)
            }
            "serialize" => {
                expect_arity("SplObjectStorage::serialize", &args, 0, span)?;
                let state = self.spl_object_storage_state(&object, method_name, span)?;
                let mut output = String::new();
                format_php_serialized_value(
                    &Value::Array(Self::spl_object_storage_flat_array_from_state(state)),
                    &mut output,
                )
                .ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplObjectStorage::serialize()",
                            "storage entries require serializable object/info values in the current subset",
                        ),
                    )
                })?;
                Ok(Value::String(output))
            }
            "unserialize" => {
                expect_arity("SplObjectStorage::unserialize", &args, 1, span)?;
                let data = string_builtin_argument(
                    "SplObjectStorage::unserialize()",
                    "data",
                    &args[0],
                    span,
                )?;
                if data.is_empty() {
                    self.spl_object_storages
                        .insert(object.id(), SplObjectStorageState::default());
                    return Ok(Value::Null);
                }
                let mut parser = PhpSerializedParser::new(&data);
                let parsed = parser.parse_value();
                match parsed {
                    Some(Value::Array(entries)) if parser.is_finished() => {
                        self.replace_spl_object_storage_entries_from_array(
                            object.clone(),
                            &entries,
                            "unserialize",
                            span,
                        )?;
                        Ok(Value::Null)
                    }
                    _ => Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplObjectStorage::unserialize()",
                            format!(
                                "Error at offset {} of {} bytes",
                                parser.position(),
                                parser.len()
                            ),
                        ),
                    )),
                }
            }
            "seek" => {
                expect_arity("SplObjectStorage::seek", &args, 1, span)?;
                let position = match args.first() {
                    Some(Value::Int(value)) => *value,
                    Some(other) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplObjectStorage::seek()",
                                format!("position must be int, got {}", other.type_name()),
                            ),
                        ));
                    }
                    None => 0,
                };
                let state = self.spl_object_storage_state_mut(&object, method_name, span)?;
                if position < 0 || position as usize >= state.entries.len() {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplObjectStorage::seek()",
                            format!("Seek position {position} is out of range"),
                        ),
                    ));
                }
                state.cursor = position as usize;
                state.cursor_key = position as usize;
                Ok(Value::Null)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("SplObjectStorage::{method_name}()")),
            )),
        }
    }

    fn spl_doubly_linked_list_state(
        &self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&SplDoublyLinkedListState> {
        self.spl_doubly_linked_lists
            .get(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("SplDoublyLinkedList::{method_name}()"),
                        "missing SplDoublyLinkedList runtime state",
                    ),
                )
            })
    }

    fn spl_doubly_linked_list_state_mut(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        span: Span,
    ) -> CompileResult<&mut SplDoublyLinkedListState> {
        self.spl_doubly_linked_lists
            .get_mut(&object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("SplDoublyLinkedList::{method_name}()"),
                        "missing SplDoublyLinkedList runtime state",
                    ),
                )
            })
    }

    fn spl_doubly_linked_list_index_argument(
        method_name: &str,
        args: &[Value],
        index: usize,
        span: Span,
    ) -> CompileResult<i64> {
        match args.get(index) {
            Some(Value::Int(value)) => Ok(*value),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplDoublyLinkedList::{method_name}()"),
                    format!(
                        "SplDoublyLinkedList::{method_name}(): Argument #{} ($index) must be of type int, {} given",
                        index + 1,
                        other.type_name()
                    ),
                ),
            )),
            None => Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    format!("SplDoublyLinkedList::{method_name}()"),
                    ArityExpectation::AtLeast(index + 1),
                    args.len(),
                ),
            )),
        }
    }

    fn spl_doubly_linked_list_usize_index(
        method_name: &str,
        args: &[Value],
        index: usize,
        span: Span,
    ) -> CompileResult<usize> {
        let value = Self::spl_doubly_linked_list_index_argument(method_name, args, index, span)?;
        usize::try_from(value).map_err(|_| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("SplDoublyLinkedList::{method_name}()"),
                    format!(
                        "SplDoublyLinkedList::{method_name}(): Argument #1 ($index) is out of range"
                    ),
                ),
            )
        })
    }

    fn spl_doubly_linked_list_out_of_range(method_name: &str, span: Span) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("SplDoublyLinkedList::{method_name}()"),
                format!(
                    "SplDoublyLinkedList::{method_name}(): Argument #1 ($index) is out of range"
                ),
            ),
        )
    }

    fn spl_doubly_linked_list_values_array(values: &[Value]) -> PhpArray {
        let mut array = PhpArray::new();
        for value in values {
            array
                .append(value.clone())
                .expect("SplDoublyLinkedList length fits in array keys");
        }
        array
    }

    fn sync_spl_doubly_linked_list_properties(
        &self,
        object: &PhpObject,
        state: &SplDoublyLinkedListState,
        span: Span,
    ) -> CompileResult<()> {
        let class_id = self
            .classes
            .lookup_class_id("SplDoublyLinkedList")
            .ok_or_else(|| {
                runtime_error(span, RuntimeError::undefined_class("SplDoublyLinkedList"))
            })?;
        object
            .write_property_from_context(
                "flags",
                Value::Int(state.iterator_mode),
                Some(class_id),
                &[class_id],
            )
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_property_from_context(
                "dllist",
                Value::Array(Self::spl_doubly_linked_list_values_array(&state.values)),
                Some(class_id),
                &[class_id],
            )
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn sync_spl_doubly_linked_list_object_properties(
        &self,
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        if let Some(state) = self.spl_doubly_linked_lists.get(&object.id()) {
            self.sync_spl_doubly_linked_list_properties(object, state, span)?;
        }
        Ok(())
    }

    fn call_spl_doubly_linked_list_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                expect_arity("SplDoublyLinkedList::__construct", &args, 0, span)?;
                Ok(Value::Null)
            }
            "push" | "enqueue" => {
                expect_arity(
                    &format!("SplDoublyLinkedList::{method_name}"),
                    &args,
                    1,
                    span,
                )?;
                let value = args.first().cloned().unwrap_or(Value::Null);
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    state.values.push(value);
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "unshift" => {
                expect_arity("SplDoublyLinkedList::unshift", &args, 1, span)?;
                let value = args.first().cloned().unwrap_or(Value::Null);
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    state.values.insert(0, value);
                    if let Some(cursor) = state.cursor.as_mut() {
                        *cursor += 1;
                    }
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "add" => {
                expect_arity("SplDoublyLinkedList::add", &args, 2, span)?;
                let index = Self::spl_doubly_linked_list_usize_index(method_name, &args, 0, span)?;
                let value = args.get(1).cloned().unwrap_or(Value::Null);
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    if index > state.values.len() {
                        return Err(Self::spl_doubly_linked_list_out_of_range(method_name, span));
                    }
                    state.values.insert(index, value);
                    if let Some(cursor) = state.cursor.as_mut() {
                        if *cursor >= index {
                            *cursor += 1;
                        }
                    }
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "pop" => {
                expect_arity("SplDoublyLinkedList::pop", &args, 0, span)?;
                let value = {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    state.values.pop().ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "SplDoublyLinkedList::pop()",
                                "Can't pop from an empty datastructure",
                            ),
                        )
                    })?
                };
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(value)
            }
            "shift" | "dequeue" => {
                expect_arity(
                    &format!("SplDoublyLinkedList::{method_name}"),
                    &args,
                    0,
                    span,
                )?;
                let value = {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    if state.values.is_empty() {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("SplDoublyLinkedList::{method_name}()"),
                                "Can't shift from an empty datastructure",
                            ),
                        ));
                    }
                    let value = state.values.remove(0);
                    if let Some(cursor) = state.cursor.as_mut() {
                        *cursor = cursor.saturating_sub(1);
                    }
                    value
                };
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(value)
            }
            "isempty" => {
                expect_arity("SplDoublyLinkedList::isEmpty", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Bool(state.values.is_empty()))
            }
            "count" => {
                expect_arity("SplDoublyLinkedList::count", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Int(state.values.len() as i64))
            }
            "setiteratormode" => {
                expect_arity("SplDoublyLinkedList::setIteratorMode", &args, 1, span)?;
                let mode =
                    Self::spl_doubly_linked_list_index_argument(method_name, &args, 0, span)?;
                if object.class_name().eq_ignore_ascii_case("SplQueue")
                    && mode & SPL_DLL_IT_MODE_LIFO != 0
                    || object.class_name().eq_ignore_ascii_case("SplStack")
                        && mode & SPL_DLL_IT_MODE_LIFO == 0
                {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplDoublyLinkedList::setIteratorMode()",
                            "Iterators' LIFO/FIFO modes for SplStack/SplQueue objects are frozen",
                        ),
                    ));
                }
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    state.iterator_mode = mode;
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "getiteratormode" => {
                expect_arity("SplDoublyLinkedList::getIteratorMode", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Int(state.iterator_mode))
            }
            "rewind" => {
                expect_arity("SplDoublyLinkedList::rewind", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                state.active_lifo = state.iterator_mode & SPL_DLL_IT_MODE_LIFO != 0;
                state.cursor = if state.active_lifo {
                    state.values.len().checked_sub(1)
                } else {
                    Some(0)
                };
                Ok(Value::Null)
            }
            "valid" => {
                expect_arity("SplDoublyLinkedList::valid", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    state
                        .cursor
                        .is_some_and(|cursor| cursor < state.values.len()),
                ))
            }
            "key" => {
                expect_arity("SplDoublyLinkedList::key", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Int(state.cursor.unwrap_or(0) as i64))
            }
            "current" => {
                expect_arity("SplDoublyLinkedList::current", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(state
                    .cursor
                    .and_then(|cursor| state.values.get(cursor).cloned())
                    .unwrap_or(Value::Null))
            }
            "next" => {
                expect_arity("SplDoublyLinkedList::next", &args, 0, span)?;
                let deleted = {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    if state.iterator_mode & SPL_DLL_IT_MODE_DELETE != 0 {
                        state.cursor = match (state.cursor, state.active_lifo) {
                            (Some(cursor), _) if cursor >= state.values.len() => None,
                            (Some(cursor), true) => {
                                state.values.remove(cursor);
                                cursor
                                    .checked_sub(1)
                                    .or_else(|| (!state.values.is_empty()).then_some(0))
                            }
                            (Some(cursor), false) => {
                                state.values.remove(cursor);
                                (cursor < state.values.len()).then_some(cursor)
                            }
                            (None, _) => None,
                        };
                        true
                    } else {
                        state.cursor = match (state.cursor, state.active_lifo) {
                            (Some(0), true) => None,
                            (Some(cursor), true) => Some(cursor - 1),
                            (Some(cursor), false) => Some(cursor.saturating_add(1)),
                            (None, _) => None,
                        };
                        false
                    }
                };
                if deleted {
                    self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                }
                Ok(Value::Null)
            }
            "prev" => {
                expect_arity("SplDoublyLinkedList::prev", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                state.cursor = match (state.cursor, state.active_lifo) {
                    (Some(cursor), true) => cursor
                        .checked_add(1)
                        .filter(|next| *next < state.values.len()),
                    (Some(0), false) => None,
                    (Some(cursor), false) => Some(cursor - 1),
                    (None, _) => None,
                };
                Ok(Value::Null)
            }
            "offsetexists" => {
                expect_arity("SplDoublyLinkedList::offsetExists", &args, 1, span)?;
                let index =
                    Self::spl_doubly_linked_list_index_argument(method_name, &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                Ok(Value::Bool(
                    index >= 0 && (index as usize) < state.values.len(),
                ))
            }
            "offsetget" => {
                expect_arity("SplDoublyLinkedList::offsetGet", &args, 1, span)?;
                let index = Self::spl_doubly_linked_list_usize_index(method_name, &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                state
                    .values
                    .get(index)
                    .cloned()
                    .ok_or_else(|| Self::spl_doubly_linked_list_out_of_range(method_name, span))
            }
            "offsetset" => {
                if !(args.len() == 1 || args.len() == 2) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "SplDoublyLinkedList::offsetSet()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let value = args.last().cloned().unwrap_or(Value::Null);
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    if args.len() == 1 || matches!(args.first(), Some(Value::Null)) {
                        state.values.push(value);
                    } else {
                        let index =
                            Self::spl_doubly_linked_list_usize_index(method_name, &args, 0, span)?;
                        if index >= state.values.len() {
                            return Err(Self::spl_doubly_linked_list_out_of_range(
                                method_name,
                                span,
                            ));
                        }
                        state.values[index] = value;
                    }
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "offsetunset" => {
                expect_arity("SplDoublyLinkedList::offsetUnset", &args, 1, span)?;
                let index = Self::spl_doubly_linked_list_usize_index(method_name, &args, 0, span)?;
                {
                    let state =
                        self.spl_doubly_linked_list_state_mut(&object, method_name, span)?;
                    if index >= state.values.len() {
                        return Err(Self::spl_doubly_linked_list_out_of_range(method_name, span));
                    }
                    state.values.remove(index);
                    if let Some(cursor) = state.cursor.as_mut() {
                        if *cursor > index {
                            *cursor -= 1;
                        } else if *cursor >= state.values.len() {
                            state.cursor = None;
                        }
                    }
                }
                self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
                Ok(Value::Null)
            }
            "top" => {
                expect_arity("SplDoublyLinkedList::top", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                state.values.last().cloned().ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplDoublyLinkedList::top()",
                            "Can't peek at an empty datastructure",
                        ),
                    )
                })
            }
            "bottom" => {
                expect_arity("SplDoublyLinkedList::bottom", &args, 0, span)?;
                let state = self.spl_doubly_linked_list_state(&object, method_name, span)?;
                state.values.first().cloned().ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "SplDoublyLinkedList::bottom()",
                            "Can't peek at an empty datastructure",
                        ),
                    )
                })
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "{}::{method_name}()",
                    object.class_name()
                )),
            )),
        }
    }

    fn create_datetimezone_object_from_name(
        &mut self,
        name: &str,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let class_id = self
            .classes
            .lookup_class_id("DateTimeZone")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("DateTimeZone")))?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("DateTimeZone class id should resolve");
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &[],
            Vec::new(),
            Vec::new(),
            object_id,
        );
        self.assign_datetimezone_object_name(&object, name, span)?;
        Ok(object)
    }

    fn initialize_datetimezone_object(
        &mut self,
        object: &PhpObject,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        expect_expr_arity("DateTimeZone::__construct", args.len(), 1, span)?;
        let value = self.evaluate(&args[0], scope)?;
        let name = match value {
            Value::String(value) => value,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_object_instantiation(
                        object.class_name().to_string(),
                        format!(
                            "DateTimeZone name must be string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        self.assign_datetimezone_object_name(object, &name, span)
    }

    fn assign_datetimezone_object_name(
        &self,
        object: &PhpObject,
        name: &str,
        span: Span,
    ) -> CompileResult<()> {
        let (timezone_type, timezone_name) =
            bounded_timezone_object_parts(name).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "DateTimeZone::__construct()",
                        format!(
                            "timezone identifier {name} is not implemented in the current subset"
                        ),
                    ),
                )
            })?;
        object
            .write_public_property("timezone_type", Value::Int(timezone_type))
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("timezone", Value::String(timezone_name))
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn create_datetimezone_object_from_state(
        &mut self,
        class_id: ClassId,
        state: &PhpArray,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("DateTimeZone class id should resolve");
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &[],
            Vec::new(),
            Vec::new(),
            object_id,
        );
        self.assign_datetimezone_object_serialization_state(&object, state, span)?;
        Ok(object)
    }

    fn call_datetimezone_set_state_static(
        &mut self,
        class_id: ClassId,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        expect_expr_arity("DateTimeZone::__set_state", args.len(), 1, span)?;
        let state = self.evaluate(&args[0], caller_scope)?;
        let Value::Array(state) = state else {
            return Err(datetimezone_invalid_serialization_error(span));
        };
        let object = self.create_datetimezone_object_from_state(class_id, &state, span)?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn assign_datetimezone_object_serialization_state(
        &self,
        object: &PhpObject,
        state: &PhpArray,
        span: Span,
    ) -> CompileResult<()> {
        let (timezone_type, timezone_name) = datetimezone_serialization_state(state, span)?;
        object
            .write_public_property("timezone_type", Value::Int(timezone_type))
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("timezone", Value::String(timezone_name))
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn datetimezone_serialization_state_array(
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<PhpArray> {
        let timezone_type = match object.read_public_property("timezone_type") {
            Ok(Value::Int(value)) => value,
            _ => return Err(datetimezone_invalid_serialization_error(span)),
        };
        let timezone_name = match object.read_public_property("timezone") {
            Ok(Value::String(value)) => value,
            _ => return Err(datetimezone_invalid_serialization_error(span)),
        };
        let Some(canonical_name) =
            normalized_datetimezone_serialization_state(timezone_type, &timezone_name)
        else {
            return Err(datetimezone_invalid_serialization_error(span));
        };

        let mut state = PhpArray::new();
        state.insert("timezone_type", Value::Int(timezone_type));
        state.insert("timezone", Value::String(canonical_name));
        Ok(state)
    }

    fn datetimezone_name(
        object: &PhpObject,
        function: impl Into<String>,
        span: Span,
    ) -> CompileResult<String> {
        match object.read_public_property("timezone") {
            Ok(Value::String(name)) => Ok(name),
            _ => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "DateTimeZone object is not initialized in the current subset",
                ),
            )),
        }
    }

    fn datetimezone_type(
        object: &PhpObject,
        function: impl Into<String>,
        span: Span,
    ) -> CompileResult<i64> {
        match object.read_public_property("timezone_type") {
            Ok(Value::Int(timezone_type)) => Ok(timezone_type),
            _ => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "DateTimeZone object is not initialized in the current subset",
                ),
            )),
        }
    }

    fn datetimezone_argument(
        &self,
        function: &'static str,
        args: &[Value],
        index: usize,
        span: Span,
    ) -> CompileResult<PhpObject> {
        match args.get(index) {
            Some(Value::Object(object)) if object.is_instance_of_class_name("DateTimeZone") => {
                Ok(object.clone())
            }
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #{} must be a DateTimeZone object, {} given",
                        index + 1,
                        other.type_name()
                    ),
                ),
            )),
            None => Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    function,
                    ArityExpectation::AtLeast(index + 1),
                    args.len(),
                ),
            )),
        }
    }

    fn call_datetimezone_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                self.initialize_datetimezone_object(&object, args, span, caller_scope)?;
                Ok(Value::Null)
            }
            "__serialize" => {
                expect_expr_arity("DateTimeZone::__serialize", args.len(), 0, span)?;
                Self::datetimezone_serialization_state_array(&object, span).map(Value::Array)
            }
            "__unserialize" => {
                expect_expr_arity("DateTimeZone::__unserialize", args.len(), 1, span)?;
                let state = self.evaluate(&args[0], caller_scope)?;
                let Value::Array(state) = state else {
                    return Err(datetimezone_invalid_serialization_error(span));
                };
                self.assign_datetimezone_object_serialization_state(&object, &state, span)?;
                Ok(Value::Null)
            }
            "getname" => {
                expect_expr_arity("DateTimeZone::getName", args.len(), 0, span)?;
                Self::datetimezone_name(&object, "DateTimeZone::getName()", span).map(Value::String)
            }
            "getlocation" => {
                expect_expr_arity("DateTimeZone::getLocation", args.len(), 0, span)?;
                let name = Self::datetimezone_name(&object, "DateTimeZone::getLocation()", span)?;
                let timezone_type =
                    Self::datetimezone_type(&object, "DateTimeZone::getLocation()", span)?;
                Ok(bounded_timezone_location_value(&name, timezone_type))
            }
            "getoffset" => {
                expect_expr_arity("DateTimeZone::getOffset", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let datetime = match value {
                    Value::Object(object)
                        if object.is_instance_of_class_name("DateTime")
                            || object.is_instance_of_class_name("DateTimeImmutable") =>
                    {
                        object
                    }
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DateTimeZone::getOffset()",
                                format!(
                                    "Argument #1 ($datetime) must be of type DateTimeInterface, {} given",
                                    php_type_error_given(&other)
                                ),
                            ),
                        ));
                    }
                };
                let state = self.date_time_objects.get(&datetime.id()).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTimeZone::getOffset()",
                            "DateTime object is not initialized in the current subset",
                        ),
                    )
                })?;
                let name = Self::datetimezone_name(&object, "DateTimeZone::getOffset()", span)?;
                let timezone = bounded_timezone_from_name(&name).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTimeZone::getOffset()",
                            format!("timezone {name} is not implemented in the current subset"),
                        ),
                    )
                })?;
                Ok(Value::Int(timezone.offset_at_timestamp(state.timestamp)))
            }
            "gettransitions" => {
                if args.len() > 2 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DateTimeZone::getTransitions()",
                            ArityExpectation::Between { min: 0, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let values = args
                    .iter()
                    .map(|arg| self.evaluate(arg, caller_scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                let start = optional_date_int_arg(
                    "DateTimeZone::getTransitions()",
                    values.first(),
                    "timestampBegin",
                    span,
                )?
                .unwrap_or(i64::MIN / 2);
                let end = optional_date_int_arg(
                    "DateTimeZone::getTransitions()",
                    values.get(1),
                    "timestampEnd",
                    span,
                )?
                .unwrap_or(i64::MAX / 2);
                let name =
                    Self::datetimezone_name(&object, "DateTimeZone::getTransitions()", span)?;
                Ok(Value::Array(bounded_timezone_transitions_array(
                    &name, start, end,
                )))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DateTimeZone::{method_name}()")),
            )),
        }
    }

    fn initialize_datetime_object(
        &mut self,
        object: &PhpObject,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        self.initialize_datetime_object_for_function(
            object,
            args,
            span,
            scope,
            "DateTime::__construct()",
        )
    }

    fn initialize_datetimeimmutable_object(
        &mut self,
        object: &PhpObject,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        self.initialize_datetime_object_for_function(
            object,
            args,
            span,
            scope,
            "DateTimeImmutable::__construct()",
        )
    }

    fn initialize_datetime_object_for_function(
        &mut self,
        object: &PhpObject,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
        function: &'static str,
    ) -> CompileResult<()> {
        if args.len() > 2 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    function,
                    ArityExpectation::Between { min: 0, max: 2 },
                    args.len(),
                ),
            ));
        }
        let values = args
            .iter()
            .map(|expr| self.evaluate(expr, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        self.initialize_datetime_object_from_values(
            object,
            values.first(),
            values.get(1),
            function,
            span,
        )
    }

    fn datetime_constructor_timezone(
        &self,
        function: &'static str,
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<BoundedTimezone> {
        let default_timezone = bounded_timezone_from_name(&self.default_timezone)
            .expect("stored default timezone should be bounded");
        let Some(value) = value else {
            return Ok(default_timezone);
        };
        match value {
            Value::Null => Ok(default_timezone),
            Value::Object(object) if object.is_instance_of_class_name("DateTimeZone") => {
                let timezone_name = Self::datetimezone_name(object, function, span)?;
                bounded_timezone_from_name(&timezone_name).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            function,
                            format!(
                                "timezone {timezone_name} is not implemented in the current subset"
                            ),
                        ),
                    )
                })
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "timezone argument must be DateTimeZone or null in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn initialize_datetime_object_from_values(
        &mut self,
        object: &PhpObject,
        value: Option<&Value>,
        timezone_value: Option<&Value>,
        function: &'static str,
        span: Span,
    ) -> CompileResult<()> {
        let default_timezone =
            self.datetime_constructor_timezone(function, timezone_value, span)?;
        let (timestamp, microsecond, timezone) = match value {
            Some(Value::Null) | None => (self.request_time, 0, default_timezone),
            Some(Value::String(value)) if value.eq_ignore_ascii_case("now") => {
                (self.request_time, 0, default_timezone)
            }
            Some(Value::String(value)) => {
                if let Some(zone) = bounded_timezone_from_name(value) {
                    (self.request_time, 0, zone)
                } else {
                    let timezone = bounded_datetime_timezone_hint(value, &default_timezone);
                    let (timestamp, microsecond) =
                        parse_bounded_datetime_with_microsecond(value, &default_timezone)
                            .unwrap_or((self.request_time, 0));
                    (timestamp, microsecond, timezone)
                }
            }
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_object_instantiation(
                        object.class_name().to_string(),
                        format!(
                            "DateTime time argument must be string or null in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        self.assign_datetime_object_state_with_microsecond(
            object,
            timestamp,
            microsecond,
            timezone,
            span,
        )
    }

    fn assign_datetime_object_state(
        &mut self,
        object: &PhpObject,
        timestamp: i64,
        timezone: BoundedTimezone,
        span: Span,
    ) -> CompileResult<()> {
        self.assign_datetime_object_state_with_microsecond(object, timestamp, 0, timezone, span)
    }

    fn assign_datetime_object_state_with_microsecond(
        &mut self,
        object: &PhpObject,
        timestamp: i64,
        microsecond: i64,
        timezone: BoundedTimezone,
        _span: Span,
    ) -> CompileResult<()> {
        let (timezone_type, timezone_name) =
            bounded_timezone_object_parts(&timezone.name).unwrap_or((3, timezone.name.clone()));
        let formatted_date = format_bounded_date("Y-m-d H:i:s", timestamp, &timezone);
        let date = if microsecond == 0 {
            format!("{formatted_date}.000000")
        } else {
            format!("{formatted_date}.{}", zero_pad(microsecond, 6))
        };
        object.write_forced_public_property("date", Value::String(date));
        object.write_forced_public_property("timezone_type", Value::Int(timezone_type));
        object.write_forced_public_property("timezone", Value::String(timezone_name));
        self.date_time_objects.insert(
            object.id(),
            BoundedDateTimeObjectState {
                timestamp,
                microsecond,
                timezone,
            },
        );
        Ok(())
    }

    fn create_datetime_object_from_values(
        &mut self,
        args: &[Value],
        span: Span,
    ) -> CompileResult<PhpObject> {
        let class_id = self
            .classes
            .lookup_class_id("DateTime")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("DateTime")))?;
        self.create_datetime_object_from_values_for_class(class_id, args, "date_create()", span)
    }

