    fn call_datetime_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                self.initialize_datetime_object(&object, args, span, caller_scope)?;
                Ok(Value::Null)
            }
            "format" => {
                expect_expr_arity("DateTime::format", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let format =
                    self.date_format_string_argument("DateTime::format()", 1, &value, span)?;
                let state = self.date_time_objects.get(&object.id()).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTime::format()",
                            "DateTime object is not initialized in the current subset",
                        ),
                    )
                })?;
                Ok(Value::String(format_bounded_date_with_microsecond(
                    &format,
                    state.timestamp,
                    &state.timezone,
                    state.microsecond,
                )))
            }
            "getoffset" => {
                expect_expr_arity("DateTime::getOffset", args.len(), 0, span)?;
                let state = self.date_time_objects.get(&object.id()).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTime::getOffset()",
                            "DateTime object is not initialized in the current subset",
                        ),
                    )
                })?;
                Ok(Value::Int(
                    state.timezone.offset_at_timestamp(state.timestamp),
                ))
            }
            "gettimezone" => {
                expect_expr_arity("DateTime::getTimezone", args.len(), 0, span)?;
                let timezone_name = self
                    .date_time_objects
                    .get(&object.id())
                    .map(|state| state.timezone.name.clone())
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DateTime::getTimezone()",
                                "DateTime object is not initialized in the current subset",
                            ),
                        )
                    })?;
                let timezone_object =
                    self.create_datetimezone_object_from_name(&timezone_name, span)?;
                self.track_allocated_object(&timezone_object);
                Ok(Value::Object(timezone_object))
            }
            "settimezone" => {
                expect_expr_arity("DateTime::setTimezone", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let timezone_object = match value {
                    Value::Object(object) if object.is_instance_of_class_name("DateTimeZone") => {
                        object
                    }
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DateTime::setTimezone()",
                                format!(
                                    "Argument #1 ($timezone) must be DateTimeZone in the current subset, got {}",
                                    other.type_name()
                                ),
                            ),
                        ));
                    }
                };
                let state = self
                    .date_time_objects
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DateTime::setTimezone()",
                                "DateTime object is not initialized in the current subset",
                            ),
                        )
                    })?;
                let timezone_name =
                    Self::datetimezone_name(&timezone_object, "DateTime::setTimezone()", span)?;
                let timezone = bounded_timezone_from_name(&timezone_name).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTime::setTimezone()",
                            format!(
                                "timezone {timezone_name} is not implemented in the current subset"
                            ),
                        ),
                    )
                })?;
                self.assign_datetime_object_state_with_microsecond(
                    &object,
                    state.timestamp,
                    state.microsecond,
                    timezone,
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "setdate" => {
                expect_expr_arity("DateTime::setDate", args.len(), 3, span)?;
                let values = args
                    .iter()
                    .map(|arg| self.evaluate(arg, caller_scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.set_datetime_date_parts(
                    &object,
                    "DateTime::setDate()",
                    &values[0],
                    &values[1],
                    &values[2],
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "setisodate" => {
                if !(2..=3).contains(&args.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DateTime::setISODate",
                            ArityExpectation::Between { min: 2, max: 3 },
                            args.len(),
                        ),
                    ));
                }
                let values = args
                    .iter()
                    .map(|arg| self.evaluate(arg, caller_scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.set_datetime_iso_date_parts(
                    &object,
                    "DateTime::setISODate()",
                    &values[0],
                    &values[1],
                    values.get(2),
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "settime" => {
                if !(2..=4).contains(&args.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DateTime::setTime",
                            ArityExpectation::Between { min: 2, max: 4 },
                            args.len(),
                        ),
                    ));
                }
                let values = args
                    .iter()
                    .map(|arg| self.evaluate(arg, caller_scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.set_datetime_time_parts(
                    &object,
                    "DateTime::setTime()",
                    &values[0],
                    &values[1],
                    values.get(2),
                    values.get(3),
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "gettimestamp" => {
                expect_expr_arity("DateTime::getTimestamp", args.len(), 0, span)?;
                let state = self.date_time_objects.get(&object.id()).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DateTime::getTimestamp()",
                            "DateTime object is not initialized in the current subset",
                        ),
                    )
                })?;
                Ok(Value::Int(state.timestamp))
            }
            "getmicrosecond" => {
                expect_expr_arity("DateTime::getMicrosecond", args.len(), 0, span)?;
                let state =
                    self.datetime_object_state(&object, "DateTime::getMicrosecond()", span)?;
                Ok(Value::Int(state.microsecond))
            }
            "setmicrosecond" => {
                expect_expr_arity("DateTime::setMicrosecond", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let microsecond = required_date_int_arg(
                    "DateTime::setMicrosecond()",
                    &value,
                    "microsecond",
                    span,
                )?;
                self.set_datetime_microsecond(
                    &object,
                    "DateTime::setMicrosecond()",
                    microsecond,
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "settimestamp" => {
                expect_expr_arity("DateTime::setTimestamp", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let timestamp =
                    required_date_int_arg("DateTime::setTimestamp()", &value, "timestamp", span)?;
                let timezone = self
                    .date_time_objects
                    .get(&object.id())
                    .map(|state| state.timezone.clone())
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "DateTime::setTimestamp()",
                                "DateTime object is not initialized in the current subset",
                            ),
                        )
                    })?;
                self.assign_datetime_object_state(&object, timestamp, timezone, span)?;
                Ok(Value::Object(object))
            }
            "modify" => {
                expect_expr_arity("DateTime::modify", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let modifier =
                    self.date_modifier_string_argument("DateTime::modify()", 1, &value, span)?;
                self.modify_datetime_object(&object, &modifier, "DateTime::modify()", span)?;
                Ok(Value::Object(object))
            }
            "add" => {
                expect_expr_arity("DateTime::add", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let interval = Self::dateinterval_object_argument(
                    "DateTime::add()",
                    std::slice::from_ref(&value),
                    0,
                    span,
                )?;
                self.apply_datetime_interval_mutation(
                    &object,
                    &interval,
                    false,
                    "DateTime::add()",
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "sub" => {
                expect_expr_arity("DateTime::sub", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let interval = Self::dateinterval_object_argument(
                    "DateTime::sub()",
                    std::slice::from_ref(&value),
                    0,
                    span,
                )?;
                self.apply_datetime_interval_mutation(
                    &object,
                    &interval,
                    true,
                    "DateTime::sub()",
                    span,
                )?;
                Ok(Value::Object(object))
            }
            "diff" => {
                if !(1..=2).contains(&args.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DateTime::diff",
                            ArityExpectation::Between { min: 1, max: 2 },
                            args.len(),
                        ),
                    ));
                }
                let target = self.evaluate(&args[0], caller_scope)?;
                let target =
                    Self::datetime_interface_value_argument("DateTime::diff()", &target, 1, span)?;
                let absolute = match args.get(1) {
                    Some(arg) => self.evaluate(arg, caller_scope)?.is_truthy(),
                    None => false,
                };
                self.create_dateinterval_from_datetime_diff(
                    &object,
                    &target,
                    absolute,
                    "DateTime::diff()",
                    span,
                )
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DateTime::{method_name}()")),
            )),
        }
    }

