    fn modify_datetime_object(
        &mut self,
        object: &PhpObject,
        modifier: &str,
        function: &'static str,
        span: Span,
    ) -> CompileResult<()> {
        let state = self
            .date_time_objects
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "DateTime object is not initialized in the current subset",
                    ),
                )
            })?;
        let (timestamp, microsecond, timezone) =
            match parse_bounded_at_timestamp_with_microsecond(modifier.trim()) {
                Some((timestamp, microsecond)) => (
                    timestamp,
                    microsecond,
                    BoundedTimezone::numeric_fixed_offset(0),
                ),
                None => {
                    let (timestamp, microsecond) = apply_bounded_datetime_modifier(
                        state.timestamp,
                        state.microsecond,
                        &state.timezone,
                        modifier,
                    )
                    .ok_or_else(|| {
                        date_malformed_string_error(
                            span,
                            date_modifier_parse_error(function, modifier),
                        )
                    })?;
                    (timestamp, microsecond, state.timezone)
                }
            };
        self.assign_datetime_object_state_with_microsecond(
            object,
            timestamp,
            microsecond,
            timezone,
            span,
        )
    }

    fn datetime_object_state(
        &self,
        object: &PhpObject,
        function: &'static str,
        span: Span,
    ) -> CompileResult<BoundedDateTimeObjectState> {
        self.date_time_objects
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "DateTime object is not initialized in the current subset",
                    ),
                )
            })
    }

    fn datetime_copy_source_state(
        &self,
        object: &PhpObject,
        function: &'static str,
        span: Span,
    ) -> CompileResult<BoundedDateTimeObjectState> {
        self.date_time_objects
            .get(&object.id())
            .cloned()
            .ok_or_else(|| self.date_object_uninitialized_error(object, function, span))
    }

    fn date_object_uninitialized_error(
        &self,
        object: &PhpObject,
        function: &'static str,
        span: Span,
    ) -> Diagnostic {
        let inherited = if object.is_instance_of_class_name("DateTimeImmutable") {
            "DateTimeImmutable"
        } else {
            "DateTime"
        };
        let message = format!(
            "Object of type {} (inheriting {inherited}) has not been correctly initialized by calling parent::__construct() in its constructor",
            object.class_name()
        );
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{DATE_OBJECT_ERROR_DIAGNOSTIC_PREFIX}{message}"),
            ),
        )
    }

    fn set_datetime_date_parts(
        &mut self,
        object: &PhpObject,
        function: &'static str,
        year_value: &Value,
        month_value: &Value,
        day_value: &Value,
        span: Span,
    ) -> CompileResult<()> {
        let year = required_date_int_arg(function, year_value, "year", span)?;
        let month = required_date_int_arg(function, month_value, "month", span)?;
        let day = required_date_int_arg(function, day_value, "day", span)?;
        let state = self.datetime_object_state(object, function, span)?;
        let current = bounded_datetime_parts(
            state.timestamp,
            state.timezone.offset_at_timestamp(state.timestamp),
        );
        self.assign_datetime_local_parts(
            object,
            function,
            year,
            month,
            day,
            current.hour,
            current.minute,
            current.second,
            state.microsecond,
            4,
            state.timezone,
            span,
        )
    }

    fn set_datetime_iso_date_parts(
        &mut self,
        object: &PhpObject,
        function: &'static str,
        year_value: &Value,
        week_value: &Value,
        day_value: Option<&Value>,
        span: Span,
    ) -> CompileResult<()> {
        let year = required_date_int_arg(function, year_value, "year", span)?;
        let week = required_date_int_arg(function, week_value, "week", span)?;
        let day_of_week = match day_value {
            Some(value) => required_date_int_arg(function, value, "dayOfWeek", span)?,
            None => 1,
        };
        let (year, month, day) =
            iso_week_date_to_civil(year, week, day_of_week).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "ISO week date is outside the current bounded timestamp subset",
                    ),
                )
            })?;
        let state = self.datetime_object_state(object, function, span)?;
        let current = bounded_datetime_parts(
            state.timestamp,
            state.timezone.offset_at_timestamp(state.timestamp),
        );
        self.assign_datetime_local_parts(
            object,
            function,
            year,
            month,
            day,
            current.hour,
            current.minute,
            current.second,
            state.microsecond,
            4,
            state.timezone,
            span,
        )
    }

    fn set_datetime_time_parts(
        &mut self,
        object: &PhpObject,
        function: &'static str,
        hour_value: &Value,
        minute_value: &Value,
        second_value: Option<&Value>,
        microsecond_value: Option<&Value>,
        span: Span,
    ) -> CompileResult<()> {
        let hour = required_date_int_arg(function, hour_value, "hour", span)?;
        let minute = required_date_int_arg(function, minute_value, "minute", span)?;
        let second = match second_value {
            Some(value) => required_date_int_arg(function, value, "second", span)?,
            None => 0,
        };
        let microsecond = match microsecond_value {
            Some(value) => required_date_int_arg(function, value, "microsecond", span)?,
            None => 0,
        };
        let state = self.datetime_object_state(object, function, span)?;
        let current = bounded_datetime_parts(
            state.timestamp,
            state.timezone.offset_at_timestamp(state.timestamp),
        );
        self.assign_datetime_local_parts(
            object,
            function,
            current.year,
            current.month,
            current.day,
            hour,
            minute,
            second,
            microsecond,
            4,
            state.timezone,
            span,
        )
    }

    fn set_datetime_microsecond(
        &mut self,
        object: &PhpObject,
        function: &'static str,
        microsecond: i64,
        span: Span,
    ) -> CompileResult<()> {
        validate_datetime_microsecond(function, 1, microsecond, span)?;
        let state = self.datetime_object_state(object, function, span)?;
        self.assign_datetime_object_state_with_microsecond(
            object,
            state.timestamp,
            microsecond,
            state.timezone,
            span,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn assign_datetime_local_parts(
        &mut self,
        object: &PhpObject,
        function: &'static str,
        year: i64,
        month: i64,
        day: i64,
        hour: i64,
        minute: i64,
        second: i64,
        microsecond: i64,
        microsecond_position: usize,
        timezone: BoundedTimezone,
        span: Span,
    ) -> CompileResult<()> {
        validate_datetime_microsecond(function, microsecond_position, microsecond, span)?;
        let timestamp = timestamp_from_overflowing_local_parts(
            year, month, day, hour, minute, second, &timezone,
        )
        .ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "date/time parts overflow the current bounded timestamp subset",
                ),
            )
        })?;
        self.assign_datetime_object_state_with_microsecond(
            object,
            timestamp,
            microsecond,
            timezone,
            span,
        )
    }

