    fn call_date_timezone_set(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("date_timezone_set", args, 2, span)?;
        let object = self.datetime_object_argument("date_timezone_set()", args, 0, span)?;
        let timezone_object = self.datetimezone_argument("date_timezone_set()", args, 1, span)?;
        let timestamp = self
            .date_time_objects
            .get(&object.id())
            .map(|state| state.timestamp)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "date_timezone_set()",
                        "DateTime object is not initialized in the current subset",
                    ),
                )
            })?;
        let timezone_name = Self::datetimezone_name(&timezone_object, "date_timezone_set()", span)?;
        let timezone = bounded_timezone_from_name(&timezone_name).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "date_timezone_set()",
                    format!("timezone {timezone_name} is not implemented in the current subset"),
                ),
            )
        })?;
        self.assign_datetime_object_state(&object, timestamp, timezone, span)?;
        Ok(Value::Object(object))
    }

    fn call_timezone_open(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("timezone_open", args, 1, span)?;
        let name = match &args[0] {
            Value::String(value) => value.clone(),
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => args[0]
                .try_echo_string()
                .map_err(|error| runtime_error(span, error))?,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "timezone_open()",
                        format!(
                            "timezone argument must be string-compatible scalar in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        match self.create_datetimezone_object_from_name(&name, span) {
            Ok(object) => {
                self.track_allocated_object(&object);
                Ok(Value::Object(object))
            }
            Err(_) => {
                self.emit_display_warning(
                    format!("timezone_open(): Unknown or bad timezone ({name})"),
                    span,
                )?;
                Ok(Value::Bool(false))
            }
        }
    }

    fn call_timezone_name_get(&self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("timezone_name_get", args, 1, span)?;
        let object = self.datetimezone_argument("timezone_name_get()", args, 0, span)?;
        Self::datetimezone_name(&object, "timezone_name_get()", span).map(Value::String)
    }

    fn call_timezone_location_get(&self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("timezone_location_get", args, 1, span)?;
        let object = self.datetimezone_argument("timezone_location_get()", args, 0, span)?;
        let name = Self::datetimezone_name(&object, "timezone_location_get()", span)?;
        let timezone_type = Self::datetimezone_type(&object, "timezone_location_get()", span)?;
        Ok(bounded_timezone_location_value(&name, timezone_type))
    }

    fn call_timezone_offset_get(&self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("timezone_offset_get", args, 2, span)?;
        let timezone_object = match args.first() {
            Some(Value::Object(object)) if object.is_instance_of_class_name("DateTimeZone") => {
                object.clone()
            }
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "timezone_offset_get()",
                        format!(
                            "Argument #1 ($object) must be of type DateTimeZone, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
            None => {
                return Err(runtime_error(
                    span,
                    RuntimeError::arity_mismatch(
                        "timezone_offset_get()",
                        ArityExpectation::AtLeast(1),
                        args.len(),
                    ),
                ));
            }
        };
        let datetime_object = match &args[1] {
            Value::Object(object)
                if object.is_instance_of_class_name("DateTime")
                    || object.is_instance_of_class_name("DateTimeImmutable") =>
            {
                object
            }
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "timezone_offset_get()",
                        format!(
                            "Argument #2 ($datetime) must be of type DateTimeInterface, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        let state = self
            .date_time_objects
            .get(&datetime_object.id())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "timezone_offset_get()",
                        "DateTime object is not initialized in the current subset",
                    ),
                )
            })?;
        let name = Self::datetimezone_name(&timezone_object, "timezone_offset_get()", span)?;
        let timezone = bounded_timezone_from_name(&name).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "timezone_offset_get()",
                    format!("timezone {name} is not implemented in the current subset"),
                ),
            )
        })?;
        Ok(Value::Int(timezone.offset_at_timestamp(state.timestamp)))
    }

    fn call_timezone_transitions_get(&self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.is_empty() || args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "timezone_transitions_get()",
                    ArityExpectation::Between { min: 1, max: 3 },
                    args.len(),
                ),
            ));
        }
        let object = self.datetimezone_argument("timezone_transitions_get()", args, 0, span)?;
        let start = optional_date_int_arg(
            "timezone_transitions_get()",
            args.get(1),
            "timestampBegin",
            span,
        )?
        .unwrap_or(i64::MIN / 2);
        let end = optional_date_int_arg(
            "timezone_transitions_get()",
            args.get(2),
            "timestampEnd",
            span,
        )?
        .unwrap_or(i64::MAX / 2);
        let name = Self::datetimezone_name(&object, "timezone_transitions_get()", span)?;
        Ok(Value::Array(bounded_timezone_transitions_array(
            &name, start, end,
        )))
    }

    fn execute_foreach_iterator_by_value(
        &mut self,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        self.call_required_iterator_method(object.clone(), "rewind", span)?;

        loop {
            if !self
                .call_required_iterator_method(object.clone(), "valid", span)?
                .is_truthy()
            {
                break;
            }

            self.tick(span)?;
            let (current, array_copy_source) = self
                .call_required_iterator_current_method_with_array_copy_source(
                    object.clone(),
                    span,
                    scope,
                )?;
            let iterator_key =
                if key.is_some() || self.foreach_iterator_needs_value_only_key_probe(&object) {
                    Some(self.call_required_iterator_method(object.clone(), "key", span)?)
                } else {
                    None
                };
            if let Some(iterator_key) = iterator_key {
                self.write_foreach_key_target(key, iterator_key, span, scope)?;
            }
            let target_is_alias = value
                .variable_name()
                .is_some_and(|name| scope.is_array_offset_alias_name(name));
            let current_is_array = matches!(current, Value::Array(_));
            self.write_foreach_value_target(value, current, span, scope)?;
            if !target_is_alias && current_is_array {
                if let Some(source) = array_copy_source {
                    if let Some(name) = value.variable_name() {
                        scope.mirror_array_copy_source_aliases_from_copy(name, &source);
                        scope.record_public_object_property_array_copy_source(name, source);
                    }
                }
            }

            match self.execute_statements(body, scope)? {
                Flow::Normal => {
                    self.call_required_iterator_method(object.clone(), "next", span)?;
                }
                Flow::Continue { depth, .. } if depth <= 1 => {
                    self.call_required_iterator_method(object.clone(), "next", span)?;
                }
                Flow::Continue { depth, span } => {
                    return Ok(Flow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                Flow::Break { depth, .. } if depth <= 1 => break,
                Flow::Break { depth, span } => {
                    return Ok(Flow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (Flow::Return(_)
                | Flow::Goto { .. }
                | Flow::Throw { .. }
                | Flow::Exit(_)) => {
                    return Ok(flow);
                }
            }
        }

        Ok(Flow::Normal)
    }

    fn foreach_iterator_needs_value_only_key_probe(&self, object: &PhpObject) -> bool {
        let class_id = object.class_id();
        self.is_spl_infinite_iterator_class_id(class_id)
            || self.is_spl_limit_iterator_class_id(class_id)
    }

    fn public_object_properties_as_foreach_array(object: &PhpObject) -> PhpArray {
        let mut array = PhpArray::new();
        for property in object.properties() {
            if property.visibility() == Visibility::Public && property.is_initialized() {
                array.insert(
                    ArrayKey::String(property.object_iteration_name()),
                    property.value_cloned(),
                );
            }
        }
        array
    }

    fn initialize_superglobals(
        &mut self,
        query_string: &str,
        cookie_header: &str,
        upload_files: &str,
        request_method: &str,
        content_type: &str,
    ) {
        let method = if request_method.trim().is_empty() {
            "GET".to_string()
        } else {
            request_method.trim().to_ascii_uppercase()
        };
        let content_length = self.request_body.len().to_string();

        let mut server = PhpArray::new();
        server.insert("SERVER_SOFTWARE", Value::String("phpc".to_string()));
        server.insert("REQUEST_URI", Value::String("/".to_string()));
        server.insert("HTTP_HOST", Value::String("localhost".to_string()));
        server.insert("PHP_SELF", Value::String("/index.php".to_string()));
        server.insert("SCRIPT_NAME", Value::String("/index.php".to_string()));
        server.insert("SCRIPT_FILENAME", Value::String("/index.php".to_string()));
        server.insert("REQUEST_TIME", Value::Int(self.request_time));
        server.insert("QUERY_STRING", Value::String(query_string.to_string()));
        server.insert("HTTP_COOKIE", Value::String(cookie_header.to_string()));
        server.insert("REQUEST_METHOD", Value::String(method.clone()));
        server.insert("CONTENT_TYPE", Value::String(content_type.to_string()));
        server.insert("CONTENT_LENGTH", Value::String(content_length));

        let cookie = parse_cookie_header_pairs(cookie_header);
        let get = parse_urlencoded_request_pairs(query_string);
        let post = if method == "POST" && is_form_urlencoded_content_type(content_type) {
            parse_urlencoded_request_pairs(&self.request_body)
        } else {
            PhpArray::new()
        };
        let mut request = get.clone();
        merge_request_array(&mut request, &post);
        let files = parse_upload_file_metadata_pairs(upload_files);
        let mut env = PhpArray::new();
        for (name, value) in std::env::vars() {
            env.insert(name, Value::String(value));
        }

        self.global_symbols
            .borrow_mut()
            .insert("_SERVER".to_string(), value_cell(Value::Array(server)));
        self.global_symbols
            .borrow_mut()
            .insert("_ENV".to_string(), value_cell(Value::Array(env)));
        self.global_symbols
            .borrow_mut()
            .insert("_COOKIE".to_string(), value_cell(Value::Array(cookie)));
        self.global_symbols
            .borrow_mut()
            .insert("_GET".to_string(), value_cell(Value::Array(get)));
        self.global_symbols
            .borrow_mut()
            .insert("_POST".to_string(), value_cell(Value::Array(post)));
        self.global_symbols
            .borrow_mut()
            .insert("_REQUEST".to_string(), value_cell(Value::Array(request)));
        self.global_symbols
            .borrow_mut()
            .insert("_FILES".to_string(), value_cell(Value::Array(files)));
    }

    fn initialize_static_property_defaults(&mut self, program: &Program) -> CompileResult<()> {
        for stmt in &program.statements {
            let Stmt::Class(class) = stmt else {
                continue;
            };
            if class.is_nested {
                continue;
            }
            let class_id = self
                .classes
                .lookup_class_id(&class.name)
                .expect("class registration should declare class id");

            for member in &class.members {
                let ClassMember::Property(property) = member else {
                    continue;
                };
                if !property.is_static {
                    continue;
                }
                let Some(default) = &property.default else {
                    continue;
                };

                let mut default_scope = SymbolTable::new();
                let value = self.evaluate(default, &mut default_scope)?;
                self.static_property_defaults
                    .insert((class_id, property.name.clone()), value.clone());
                self.static_properties
                    .insert((class_id, property.name.clone()), VariableCell::new(value));
            }
        }

        Ok(())
    }

    fn initialize_instance_property_defaults(&mut self, program: &Program) -> CompileResult<()> {
        for stmt in &program.statements {
            let Stmt::Class(class) = stmt else {
                continue;
            };
            if class.is_nested {
                continue;
            }
            let class_id = self
                .classes
                .lookup_class_id(&class.name)
                .expect("class registration should declare class id");

            self.initialize_instance_property_defaults_for_class(class_id, class)?;
        }

        Ok(())
    }

    fn register_included_declarations(&mut self, program: &Program) -> CompileResult<()> {
        for stmt in &program.statements {
            match stmt {
                Stmt::Function(function) if !function.is_nested => {
                    let key = function.name.to_ascii_lowercase();
                    if self.functions.contains_key(&key) {
                        return Err(runtime_error(
                            function.span,
                            RuntimeError::duplicate_function(callable_name(&function.name)),
                        ));
                    }
                    self.function_source_files
                        .insert(key.clone(), self.source_file.clone());
                    self.functions.insert(key, Rc::new(function.clone()));
                }
                Stmt::Class(class) if !class.is_nested => {
                    let key = class.name.to_ascii_lowercase();
                    if self.interface_lookup.contains_key(&key)
                        || self.trait_lookup.contains_key(&key)
                        || self.enum_lookup.contains_key(&key)
                    {
                        return Err(runtime_error(
                            class.span,
                            RuntimeError::duplicate_class(&class.name),
                        ));
                    }
                    let class_id = register_class_name(&mut self.classes, class)?;
                    self.class_source_metadata.insert(
                        class_id,
                        class_like_source_metadata_from_class(class, self.source_file.clone()),
                    );
                    if class.is_abstract {
                        self.abstract_classes.insert(class_id);
                    }
                    if class.is_final {
                        self.final_classes.insert(class_id);
                    }
                    register_final_method_markers(&mut self.final_methods, class_id, class);
                }
                Stmt::Interface(interface) => {
                    self.interface_source_metadata.insert(
                        interface.name.to_ascii_lowercase(),
                        class_like_source_metadata_from_interface(
                            interface,
                            self.source_file.clone(),
                        ),
                    );
                    register_interface_name(
                        &self.classes,
                        &self.trait_lookup,
                        &self.enum_lookup,
                        &mut self.interfaces,
                        &mut self.interface_lookup,
                        interface,
                    )?;
                }
                Stmt::Trait(trait_decl) => {
                    self.trait_source_metadata.insert(
                        trait_decl.name.to_ascii_lowercase(),
                        class_like_source_metadata_from_trait(trait_decl, self.source_file.clone()),
                    );
                    register_trait_name(
                        &self.classes,
                        &self.interface_lookup,
                        &self.enum_lookup,
                        &mut self.traits,
                        &mut self.trait_lookup,
                        trait_decl,
                    )?;
                }
                Stmt::Enum(enum_decl) => {
                    let class_id = register_enum_name(
                        &mut self.classes,
                        &self.interface_lookup,
                        &self.trait_lookup,
                        &mut self.enums,
                        &mut self.enum_lookup,
                        enum_decl,
                    )?;
                    self.class_source_metadata.insert(
                        class_id,
                        class_like_source_metadata_from_enum(enum_decl, self.source_file.clone()),
                    );
                }
                _ => {}
            }
        }
        self.autoload_missing_interface_parent_dependencies(program)?;
        validate_interface_parent_relationships(
            &self.classes,
            &self.trait_lookup,
            &self.interface_lookup,
            &self.interfaces,
        )?;

        for stmt in &program.statements {
            let Stmt::Class(class) = stmt else {
                continue;
            };
            if class.is_nested {
                continue;
            }
            self.autoload_missing_class_dependencies(class)?;
            let class_id = register_class_members(
                &mut self.classes,
                &self.final_classes,
                &self.abstract_methods,
                &self.final_methods,
                &self.method_signatures,
                &self.interface_lookup,
                &self.trait_lookup,
                class,
            )?;
            register_class_member_runtime_tables(
                &mut self.class_constants,
                &mut self.static_properties,
                &mut self.static_property_defaults,
                &mut self.property_source_metadata,
                &mut self.methods,
                &mut self.method_signatures,
                &mut self.abstract_methods,
                &self.trait_lookup,
                self.source_file.clone(),
                class_id,
                class,
            )?;
        }

        self.initialize_static_property_defaults(program)
            .and_then(|_| self.initialize_instance_property_defaults(program))
    }

    fn autoload_missing_interface_parent_dependencies(
        &mut self,
        program: &Program,
    ) -> CompileResult<()> {
        for stmt in &program.statements {
            let Stmt::Interface(interface) = stmt else {
                continue;
            };
            for parent_name in &interface.parents {
                if !self.class_like_exists(parent_name, AutoloadKind::Interface) {
                    self.run_autoload_callbacks(
                        parent_name,
                        AutoloadKind::Interface,
                        interface.span,
                    )?;
                }
            }
        }
        Ok(())
    }

    fn autoload_missing_class_dependencies(&mut self, class: &ClassDecl) -> CompileResult<()> {
        if let Some(parent_name) = &class.parent {
            if self.classes.lookup_class(parent_name).is_none() {
                self.run_autoload_callbacks(parent_name, AutoloadKind::Class, class.span)?;
            }
        }

        for interface_name in &class.interfaces {
            if !self.class_like_exists(interface_name, AutoloadKind::Interface) {
                self.run_autoload_callbacks(interface_name, AutoloadKind::Interface, class.span)?;
            }
        }

        for trait_use in &class.trait_uses {
            if !self.class_like_exists(&trait_use.name, AutoloadKind::Trait) {
                self.run_autoload_callbacks(&trait_use.name, AutoloadKind::Trait, trait_use.span)?;
            }
        }

        Ok(())
    }

    fn register_nested_class_declaration(&mut self, class: &ClassDecl) -> CompileResult<()> {
        let key = class.name.to_ascii_lowercase();
        if self.interface_lookup.contains_key(&key)
            || self.trait_lookup.contains_key(&key)
            || self.enum_lookup.contains_key(&key)
        {
            return Err(runtime_error(
                class.span,
                RuntimeError::duplicate_class(&class.name),
            ));
        }
        let class_id = register_class_name(&mut self.classes, class)?;
        self.class_source_metadata.insert(
            class_id,
            class_like_source_metadata_from_class(class, self.source_file.clone()),
        );
        if class.is_abstract {
            self.abstract_classes.insert(class_id);
        }
        if class.is_final {
            self.final_classes.insert(class_id);
        }
        if let Err(error) = self.autoload_missing_class_dependencies(class) {
            self.abstract_classes.remove(&class_id);
            self.final_classes.remove(&class_id);
            self.class_source_metadata.remove(&class_id);
            self.classes.remove_last_declared_class(class_id);
            return Err(error);
        }
        if let Err(error) = register_class_members(
            &mut self.classes,
            &self.final_classes,
            &self.abstract_methods,
            &self.final_methods,
            &self.method_signatures,
            &self.interface_lookup,
            &self.trait_lookup,
            class,
        ) {
            self.abstract_classes.remove(&class_id);
            self.final_classes.remove(&class_id);
            self.class_source_metadata.remove(&class_id);
            self.classes.remove_last_declared_class(class_id);
            return Err(error);
        }
        register_final_method_markers(&mut self.final_methods, class_id, class);
        register_class_member_runtime_tables(
            &mut self.class_constants,
            &mut self.static_properties,
            &mut self.static_property_defaults,
            &mut self.property_source_metadata,
            &mut self.methods,
            &mut self.method_signatures,
            &mut self.abstract_methods,
            &self.trait_lookup,
            self.source_file.clone(),
            class_id,
            class,
        )?;
        if let Err(error) = self.initialize_static_property_defaults_for_class(class_id, class) {
            remove_class_member_runtime_tables(
                &mut self.class_constants,
                &mut self.static_properties,
                &mut self.static_property_defaults,
                &mut self.property_source_metadata,
                &mut self.methods,
                &mut self.method_signatures,
                &mut self.abstract_methods,
                class_id,
            );
            self.abstract_classes.remove(&class_id);
            self.final_classes.remove(&class_id);
            self.final_methods
                .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);
            self.class_source_metadata.remove(&class_id);
            self.classes.remove_last_declared_class(class_id);
            return Err(error);
        }
        if let Err(error) = self.initialize_instance_property_defaults_for_class(class_id, class) {
            remove_class_member_runtime_tables(
                &mut self.class_constants,
                &mut self.static_properties,
                &mut self.static_property_defaults,
                &mut self.property_source_metadata,
                &mut self.methods,
                &mut self.method_signatures,
                &mut self.abstract_methods,
                class_id,
            );
            self.instance_property_defaults
                .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);
            self.instance_property_default_exprs
                .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);
            self.abstract_classes.remove(&class_id);
            self.final_classes.remove(&class_id);
            self.final_methods
                .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);
            self.class_source_metadata.remove(&class_id);
            self.classes.remove_last_declared_class(class_id);
            return Err(error);
        }

        Ok(())
    }

    fn register_nested_function_declaration(
        &mut self,
        function: &FunctionDecl,
    ) -> CompileResult<()> {
        let key = function.name.to_ascii_lowercase();
        if self.functions.contains_key(&key) {
            return Err(runtime_error(
                function.span,
                RuntimeError::duplicate_function(callable_name(&function.name)),
            ));
        }
        self.functions.insert(key, Rc::new(function.clone()));
        Ok(())
    }

    fn initialize_static_property_defaults_for_class(
        &mut self,
        class_id: ClassId,
        class: &ClassDecl,
    ) -> CompileResult<()> {
        let class_properties = declared_class_properties(class);
        for property in composed_trait_properties(class, &self.trait_lookup)? {
            if class_properties.contains_key(&property.name) || !property.is_static {
                continue;
            }
            let Some(default) = &property.default else {
                continue;
            };

            let mut default_scope = SymbolTable::new();
            let value = self.evaluate(default, &mut default_scope)?;
            self.static_property_defaults
                .insert((class_id, property.name.clone()), value.clone());
            self.static_properties
                .insert((class_id, property.name.clone()), VariableCell::new(value));
        }

        for member in &class.members {
            let ClassMember::Property(property) = member else {
                continue;
            };
            if !property.is_static {
                continue;
            }
            let Some(default) = &property.default else {
                continue;
            };

            let mut default_scope = SymbolTable::new();
            let value = self.evaluate(default, &mut default_scope)?;
            self.static_property_defaults
                .insert((class_id, property.name.clone()), value.clone());
            self.static_properties
                .insert((class_id, property.name.clone()), VariableCell::new(value));
        }

        Ok(())
    }

    fn initialize_instance_property_defaults_for_class(
        &mut self,
        class_id: ClassId,
        class: &ClassDecl,
    ) -> CompileResult<()> {
        self.instance_property_defaults
            .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);
        self.instance_property_default_exprs
            .retain(|(declaring_class_id, _), _| *declaring_class_id != class_id);

        let class_properties = declared_class_properties(class);
        for property in composed_trait_properties(class, &self.trait_lookup)? {
            if class_properties.contains_key(&property.name) || property.is_static {
                continue;
            }
            self.register_instance_property_default(class_id, &property)?;
        }

        for member in &class.members {
            let ClassMember::Property(property) = member else {
                continue;
            };
            if property.is_static {
                continue;
            }
            self.register_instance_property_default(class_id, property)?;
        }

        Ok(())
    }

    fn register_instance_property_default(
        &mut self,
        class_id: ClassId,
        property: &ClassPropertyDecl,
    ) -> CompileResult<()> {
        let Some(default) = &property.default else {
            return Ok(());
        };

        let key = (class_id, property.name.clone());
        if instance_property_default_requires_deferred_evaluation(default) {
            self.instance_property_default_exprs
                .insert(key, default.clone());
            return Ok(());
        }

        let mut default_scope = SymbolTable::new();
        let value = self.evaluate(default, &mut default_scope)?;
        self.instance_property_defaults.insert(key, value);
        Ok(())
    }

    fn run(&mut self, program: &Program) -> CompileResult<Execution> {
        let mut scope = SymbolTable::from_root(self.global_symbols.clone());
        self.emit_deprecated_dollar_brace_interpolation_diagnostics(program)?;
        let flow = match self.with_strict_types_scope(program.strict_types, |this| {
            this.execute_statements(&program.statements, &mut scope)
        }) {
            Ok(flow) => flow,
            Err(error) => {
                if let Some(message) = fatal_memory_error_message(&error) {
                    return self.fatal_runtime_message_execution(&error, &message);
                }
                if let Some(message) = fatal_declare_error_message(&error) {
                    return self.fatal_runtime_message_execution(&error, &message);
                }
                if let Some(message) = fatal_append_offset_read_message(&error) {
                    return self.fatal_runtime_message_execution(&error, &message);
                }
                if is_positional_argument_after_named_argument_error(&error) {
                    return self.fatal_runtime_message_execution(&error, &error.message);
                }
                if is_first_class_callable_creation_fatal_error(&error) {
                    return self.fatal_runtime_message_execution(&error, &error.message);
                }
                if let Some(message) = class_name_resolution_fatal_message(&error) {
                    return self.fatal_runtime_message_execution(&error, &message);
                }
                if let Some((error_class_name, error_message)) =
                    catchable_php_error_class_and_message(&error)
                {
                    if error_class_name == "TypeError"
                        && is_call_argument_type_error_message(&error_message)
                    {
                        return self.uncaught_call_argument_type_error_execution(
                            &error,
                            error_class_name,
                            &error_message,
                        );
                    }
                    return self.uncaught_php_error_execution(
                        &error,
                        error_class_name,
                        &error_message,
                    );
                }
                return Err(error);
            }
        };
        match flow {
            Flow::Normal | Flow::Return(_) => {
                self.run_shutdown_callbacks()?;
                self.run_shutdown_destructors()?;
                self.flush_output_buffers()?;
                Ok(Execution {
                    stdout: self.stdout.clone(),
                    stdout_bytes: self.execution_stdout_bytes(),
                    stderr: self.stderr.clone(),
                    exit_code: self.exit_signal.unwrap_or(0),
                })
            }
            Flow::Exit(code) => {
                self.run_shutdown_callbacks()?;
                self.run_shutdown_destructors()?;
                self.flush_output_buffers()?;
                Ok(Execution {
                    stdout: self.stdout.clone(),
                    stdout_bytes: self.execution_stdout_bytes(),
                    stderr: self.stderr.clone(),
                    exit_code: self.exit_signal.unwrap_or(code),
                })
            }
            Flow::Break { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
            )),
            Flow::Continue { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("continue cannot be used outside a loop"),
            )),
            Flow::Throw { object, span } => self.uncaught_throw_execution(&object, span),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn execute_statements(
        &mut self,
        statements: &[Stmt],
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let mut labels = HashMap::new();
        for (index, stmt) in statements.iter().enumerate() {
            if let Stmt::Label { name, .. } = stmt {
                labels.insert(name.clone(), index);
            }
        }

        let mut index = 0;
        while index < statements.len() {
            match self.execute_statement(&statements[index], scope)? {
                Flow::Normal => {}
                Flow::Goto { label, span } => {
                    let Some(target) = labels.get(&label) else {
                        return Ok(Flow::Goto { label, span });
                    };
                    index = *target;
                    continue;
                }
                flow @ (Flow::Break { .. }
                | Flow::Continue { .. }
                | Flow::Return(_)
                | Flow::Throw { .. }
                | Flow::Exit(_)) => return Ok(flow),
            }
            if let Some(code) = self.exit_signal {
                return Ok(Flow::Exit(code));
            }
            index += 1;
        }
        Ok(Flow::Normal)
    }

    fn append_output(&mut self, output: &str) {
        self.append_output_from(output, None);
    }

    fn append_output_at(&mut self, output: &str, span: Span) {
        self.append_output_from(output, Some(span));
    }

    fn append_output_bytes_at(&mut self, output: &[u8], span: Span) {
        if let Some(capture) = self.output_handler_output_captures.last_mut() {
            capture.extend_from_slice(output);
            return;
        }
        if let Some(buffer) = self.output_buffers.last_mut() {
            buffer.contents.extend_from_slice(output);
        } else {
            self.mark_output_bytes_started(output, Some(span));
            self.stdout.push_str(&String::from_utf8_lossy(output));
            self.stdout_bytes.extend_from_slice(output);
        }
    }

    fn emit_warning(
        &mut self,
        function: &str,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_runtime_diagnostic(function, "Warning", PHP_E_WARNING, message, span)
    }

    fn emit_startup_warning(&mut self, message: impl AsRef<str>) {
        if self.error_reporting_mask & PHP_E_WARNING == 0 {
            return;
        }
        self.append_output(&format!(
            "Warning: PHP Startup: {} in Unknown on line 0\n",
            message.as_ref()
        ));
    }

    fn emit_startup_warning_without_prefix(&mut self, message: impl AsRef<str>) {
        if self.error_reporting_mask & PHP_E_WARNING == 0 {
            return;
        }
        self.append_output(&format!(
            "Warning: {} in Unknown on line 0\n",
            message.as_ref()
        ));
    }

    fn emit_disable_functions_startup_warnings(&mut self) {
        let Some(value) = self.ini_value("disable_functions") else {
            return;
        };

        let mut warned = HashSet::new();
        for part in value
            .split(|ch: char| ch == ',' || ch.is_ascii_whitespace())
            .filter(|part| !part.is_empty())
        {
            let key = part.to_ascii_lowercase();
            if matches!(key.as_str(), "exit" | "die") && warned.insert(key.clone()) {
                self.emit_startup_warning_without_prefix(format!(
                    "Cannot disable function {key}()"
                ));
            }
        }
    }

    fn emit_startup_deprecated(&mut self, message: impl AsRef<str>) {
        if self.error_reporting_mask & PHP_E_DEPRECATED == 0 {
            return;
        }
        if !self.stdout.is_empty()
            || self
                .output_buffers
                .iter()
                .any(|buffer| !buffer.contents.is_empty())
        {
            self.append_output("\n");
        }
        self.append_output(&format!(
            "Deprecated: PHP Startup: {} in Unknown on line 0\n",
            message.as_ref()
        ));
    }

    fn emit_assert_startup_deprecations(&mut self) {
        for name in [
            "assert.active",
            "assert.warning",
            "assert.callback",
            "assert.exception",
        ] {
            if assert_startup_ini_setting_is_deprecated(name, &self.ini_values) {
                self.emit_startup_deprecated(format!("{name} INI setting is deprecated"));
            }
        }
    }

    fn with_error_control_suppression<T>(
        &mut self,
        evaluate: impl FnOnce(&mut Self) -> CompileResult<T>,
    ) -> CompileResult<T> {
        let previous_depth = self.error_control_suppression_depth;
        self.error_control_suppression_depth = previous_depth + 1;
        let result = evaluate(self);
        self.error_control_suppression_depth = previous_depth;
        result
    }

    fn current_strict_types(&self) -> bool {
        self.strict_types_stack.last().copied().unwrap_or(false)
    }

    fn with_strict_types_scope<T>(
        &mut self,
        strict_types: bool,
        evaluate: impl FnOnce(&mut Self) -> CompileResult<T>,
    ) -> CompileResult<T> {
        self.strict_types_stack.push(strict_types);
        let result = evaluate(self);
        self.strict_types_stack.pop();
        result
    }

    fn diagnostics_are_suppressed(&self) -> bool {
        self.error_control_suppression_depth > 0
    }

    fn emit_notice(
        &mut self,
        function: &str,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_runtime_diagnostic(function, "Notice", PHP_E_NOTICE, message, span)
    }

    fn emit_display_notice(&mut self, message: impl AsRef<str>, span: Span) -> CompileResult<()> {
        self.emit_display_diagnostic("Notice", PHP_E_NOTICE, message, span)
    }

    fn emit_array_access_indirect_modification_notice(
        &mut self,
        class_name: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_notice(
            format!("Indirect modification of overloaded element of {class_name} has no effect"),
            span,
        )
    }

    fn emit_array_access_reference_assignment_fatal(&mut self, span: Span) {
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: Uncaught Error: Cannot assign by reference to an array dimension of an object in {file}:{}\nStack trace:\n#0 {{main}}\n  thrown in {file} on line {}",
            span.line, span.line
        ));
        self.exit_signal = Some(255);
    }

    fn emit_debug_info_return_fatal(&mut self, span: Span) {
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: __debuginfo() must return an array in {file} on line {}",
            span.line
        ));
        self.exit_signal = Some(255);
    }

    fn emit_simple_fatal(&mut self, message: &str, span: Span) {
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: {message} in {file} on line {}",
            span.line
        ));
        self.exit_signal = Some(255);
    }

    fn emit_display_warning(&mut self, message: impl AsRef<str>, span: Span) -> CompileResult<()> {
        self.emit_display_diagnostic("Warning", PHP_E_WARNING, message, span)
    }

    fn emit_deprecated_dollar_brace_interpolation_diagnostics(
        &mut self,
        program: &Program,
    ) -> CompileResult<()> {
        for span in collect_deprecated_dollar_brace_interpolation_spans(program) {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Using ${var} in strings is deprecated, use {$var} instead",
                span,
            )?;
        }
        Ok(())
    }

    fn emit_undefined_variable_warning(&mut self, name: &str, span: Span) -> CompileResult<()> {
        let message = if is_initialized_request_auto_global_name(name) {
            format!("Undefined global variable ${name}")
        } else {
            format!("Undefined variable ${name}")
        };
        self.emit_display_warning(message, span)
    }

    fn emit_undefined_property_warning(
        &mut self,
        class_name: &str,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(
            format!("Undefined property: {class_name}::${property}"),
            span,
        )
    }

    fn materialize_or_read_reference_argument_cell(
        &mut self,
        caller_scope: &mut SymbolTable,
        caller_name: &str,
        span: Span,
    ) -> CompileResult<VariableCell> {
        if let Some(cell) = caller_scope.read_cell(caller_name) {
            return Ok(cell);
        }
        if caller_name == "GLOBALS" || caller_name.eq_ignore_ascii_case("this") {
            return Err(runtime_error(
                span,
                RuntimeError::undefined_variable(caller_name),
            ));
        }
        let cell = value_cell(Value::Null);
        caller_scope.bind_static_to_cell(caller_name, cell.clone());
        Ok(cell)
    }

    fn emit_display_diagnostic(
        &mut self,
        label: &str,
        level: i64,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        let message = message.as_ref().to_string();
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        if self.diagnostics_are_suppressed() {
            return Ok(());
        }
        if self.call_error_handler_for_diagnostic(level, &message, &file, span)? {
            return Ok(());
        }
        if self.error_reporting_mask & level == 0 {
            return Ok(());
        }

        let current_output_is_empty = self.stdout.is_empty()
            && self
                .output_buffers
                .iter()
                .all(|buffer| buffer.contents.is_empty());
        let mut output = String::new();
        if !current_output_is_empty {
            output.push('\n');
        }
        output.push_str(&format!(
            "{label}: {message} in {file} on line {}\n",
            span.line
        ));
        self.append_output_at(&output, span);
        Ok(())
    }

    fn emit_deprecated(
        &mut self,
        function: &str,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_runtime_diagnostic(function, "Deprecated", PHP_E_DEPRECATED, message, span)
    }

    fn emit_false_to_array_deprecation(&mut self, span: Span) -> CompileResult<()> {
        self.emit_deprecated(
            "array assignment",
            "Automatic conversion of false to array is deprecated",
            span,
        )
    }

    fn string_offset_index(
        key: &ArrayKey,
        byte_len: usize,
        operation: &str,
        span: Span,
    ) -> CompileResult<usize> {
        let offset = match key {
            ArrayKey::Int(offset) => *offset,
            ArrayKey::String(offset) => Self::parse_string_offset_key(offset).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot {operation} offset on string"
                    )),
                )
            })?,
        };

        Self::string_offset_index_from_i64(offset, byte_len, span)
    }

    fn string_offset_index_from_i64(
        offset: i64,
        byte_len: usize,
        span: Span,
    ) -> CompileResult<usize> {
        let resolved = if offset < 0 {
            byte_len as i64 + offset
        } else {
            offset
        };
        if resolved < 0 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "string offset",
                    "negative offsets before the start of the string are not implemented",
                ),
            ));
        }
        Ok(resolved as usize)
    }

    fn parse_string_offset_key(value: &str) -> Option<i64> {
        let value = value.trim();
        if value.is_empty() {
            return None;
        }

        let digits = value
            .strip_prefix(['+', '-'])
            .filter(|digits| !digits.is_empty())
            .unwrap_or(value);
        if !digits.bytes().all(|byte| byte.is_ascii_digit()) {
            return None;
        }

        value.parse::<i64>().ok()
    }

    fn parse_leading_integer_string_offset_key(value: &str) -> Option<i64> {
        let trimmed = value.trim_start();
        let bytes = trimmed.as_bytes();
        let mut end = 0;

        if matches!(bytes.first(), Some(b'+') | Some(b'-')) {
            end += 1;
        }

        let digit_start = end;
        while matches!(bytes.get(end), Some(b'0'..=b'9')) {
            end += 1;
        }

        if end == digit_start || matches!(bytes.get(end), Some(b'.')) {
            return None;
        }

        trimmed[..end].parse::<i64>().ok()
    }

    fn evaluate_string_offset_index(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(i64, String)> {
        let key = self.evaluate(expr, scope)?;
        match key {
            Value::Int(value) => Ok((value, value.to_string())),
            Value::Bool(value) => {
                self.emit_display_warning("String offset cast occurred", expr.span())?;
                let value = i64::from(value);
                Ok((value, value.to_string()))
            }
            Value::Float(value) => {
                self.emit_display_warning("String offset cast occurred", expr.span())?;
                let value = php_float_to_wrapping_i64(value);
                Ok((value, value.to_string()))
            }
            Value::Null => {
                self.emit_display_warning("String offset cast occurred", expr.span())?;
                Ok((0, "0".to_string()))
            }
            Value::String(value) => {
                if let Some(offset) = Self::parse_string_offset_key(&value) {
                    return Ok((offset, value));
                }
                if let Some(offset) = Self::parse_leading_integer_string_offset_key(&value) {
                    self.emit_display_warning(
                        format!("Illegal string offset \"{value}\""),
                        expr.span(),
                    )?;
                    return Ok((offset, value));
                }
                Err(Self::offset_type_runtime_error(
                    &Value::String(value),
                    "string",
                    expr.span(),
                ))
            }
            Value::BinaryString(value) => {
                let value = String::from_utf8_lossy(&value).into_owned();
                if let Some(offset) = Self::parse_string_offset_key(&value) {
                    return Ok((offset, value));
                }
                if let Some(offset) = Self::parse_leading_integer_string_offset_key(&value) {
                    self.emit_display_warning(
                        format!("Illegal string offset \"{value}\""),
                        expr.span(),
                    )?;
                    return Ok((offset, value));
                }
                Err(runtime_error(
                    expr.span(),
                    RuntimeError::invalid_array_access(
                        "Cannot access offset of type string on string".to_string(),
                    ),
                ))
            }
            other => Err(Self::offset_type_runtime_error(
                &other,
                "string",
                expr.span(),
            )),
        }
    }

    fn offset_type_runtime_error(value: &Value, container: &str, span: Span) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::invalid_array_access(format!(
                "Cannot access offset of type {} on {container}",
                Self::offset_access_type_name(value)
            )),
        )
    }

    fn float_to_array_key_i64(&mut self, value: f64, span: Span) -> CompileResult<i64> {
        if php_float_to_int_is_not_representable(value) {
            self.emit_float_not_representable_warning(value, span)?;
        } else if value.trunc() != value {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!(
                    "Implicit conversion from float {} to int loses precision",
                    format_php_float_to_int_deprecation_value(value)
                ),
                span,
            )?;
        }

        Ok(php_float_to_wrapping_i64(value))
    }

    fn emit_float_not_representable_warning(
        &mut self,
        value: f64,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(
            format!(
                "The float {} is not representable as an int, cast occurred",
                php_float_to_int_warning_string(value)
            ),
            span,
        )
    }

    fn read_ascii_string_offset_at(
        &mut self,
        value: &str,
        offset: i64,
        display_key: &str,
        span: Span,
    ) -> CompileResult<Value> {
        if !value.is_ascii() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "string offset",
                    "binary and multibyte string offset reads are not implemented",
                ),
            ));
        }

        let index = Self::string_offset_index_from_i64(offset, value.len(), span)?;
        let Some(byte) = value.as_bytes().get(index) else {
            self.emit_display_warning(format!("Uninitialized string offset {display_key}"), span)?;
            return Ok(Value::String(String::new()));
        };
        Ok(Value::String(char::from(*byte).to_string()))
    }

    fn write_ascii_string_offset(
        &mut self,
        value: &mut String,
        key: &ArrayKey,
        replacement: Value,
        span: Span,
    ) -> CompileResult<()> {
        if !value.is_ascii() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "string offset",
                    "binary and multibyte string offset writes are not implemented",
                ),
            ));
        }

        let index = Self::string_offset_index(key, value.len(), "write", span)?;
        let replacement = self.value_to_echo_string(replacement, span)?;
        if replacement.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot assign an empty string to a string offset".to_string(),
                ),
            ));
        }
        if !replacement.is_ascii() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "string offset",
                    "binary and multibyte replacement strings are not implemented",
                ),
            ));
        }
        if replacement.len() > 1 {
            self.emit_warning(
                "string offset",
                "Only the first byte will be assigned to the string offset",
                span,
            )?;
        }

        let replacement = replacement.as_bytes()[0];
        let mut bytes = value.as_bytes().to_vec();
        if index > bytes.len() {
            bytes.resize(index, b' ');
            bytes.push(replacement);
        } else if index == bytes.len() {
            bytes.push(replacement);
        } else {
            bytes[index] = replacement;
        }
        *value = String::from_utf8(bytes).expect("ASCII string offset writes remain valid UTF-8");
        Ok(())
    }

    fn emit_runtime_diagnostic(
        &mut self,
        function: &str,
        label: &str,
        level: i64,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        let message = message.as_ref().to_string();
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        if self.diagnostics_are_suppressed() {
            return Ok(());
        }
        if self.call_error_handler_for_diagnostic(level, &message, &file, span)? {
            return Ok(());
        }
        if self.error_reporting_mask & level == 0 {
            return Ok(());
        }
        if !self.stderr.is_empty() {
            self.stderr.push('\n');
        }
        self.stderr.push_str(&format!(
            "PHP {label}:  {function}: {} in {file} on line {}",
            message, span.line
        ));
        Ok(())
    }

    fn call_error_handler_for_diagnostic(
        &mut self,
        level: i64,
        message: &str,
        file: &str,
        span: Span,
    ) -> CompileResult<bool> {
        if self.error_handler_active {
            return Ok(false);
        }
        let Some(handler) = self.error_handlers.last().cloned() else {
            return Ok(false);
        };
        if handler.mask.is_some_and(|mask| mask & level == 0) {
            return Ok(false);
        }

        let args = vec![
            Value::Int(level),
            Value::String(message.to_string()),
            Value::String(file.to_string()),
            Value::Int(span.line as i64),
        ];
        self.error_handler_active = true;
        let result = self.call_error_handler_callback(handler.callback, args, span);
        self.error_handler_active = false;
        Ok(!matches!(result?, Value::Bool(false)))
    }

    fn call_error_handler_callback(
        &mut self,
        handler: Value,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        match handler {
            Value::String(name) => {
                let callable = self.lookup_function(&name).ok_or_else(|| {
                    runtime_error(span, RuntimeError::undefined_function(callable_name(&name)))
                })?;
                match callable {
                    Callable::User(function) => {
                        let function = function.as_ref();
                        let args = error_handler_args_for_function(function, &args);
                        ensure_user_function_arity_with_extra_policy(
                            function,
                            args.len(),
                            span,
                            true,
                        )?;
                        ensure_supported_function_signature(function, args.len(), span)?;
                        self.ensure_user_function_call_depth(function, span)?;
                        self.call_error_handler_user_function_with_checked_values(
                            function,
                            args,
                            span,
                            None,
                            None,
                            None,
                            Vec::new(),
                        )
                    }
                    Callable::Builtin(key) => self.call_builtin(&key, args, span),
                }
            }
            Value::Array(array) => self.call_error_handler_array_callable(&array, args, span),
            Value::Closure(closure) => {
                let function = self
                    .closure_functions
                    .get(&closure.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "set_error_handler()",
                                "closure body metadata is missing in the current subset",
                            ),
                        )
                    })?;
                let function = function.as_ref();
                let args = error_handler_args_for_function(function, &args);
                ensure_user_function_arity_with_extra_policy(function, args.len(), span, false)
                    .map_err(|error| callback_context_diagnostic("set_error_handler()", error))?;
                ensure_supported_function_signature(function, args.len(), span)?;
                self.ensure_user_function_call_depth(function, span)?;
                let prebound_locals = self.closure_prebound_locals(&closure);
                let (this_object, class_context, called_class_context) =
                    self.closure_call_context(&closure);
                self.call_error_handler_user_function_with_checked_values(
                    function,
                    args,
                    span,
                    this_object,
                    class_context,
                    called_class_context,
                    prebound_locals,
                )
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "set_error_handler()",
                    format!(
                        "stored handler must be string, array callable, or closure in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn call_error_handler_user_function_with_checked_values(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        span: Span,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        prebound_locals: Vec<PreboundLocal>,
    ) -> CompileResult<Value> {
        let trace_args = args.clone();
        let trace_callable =
            self.pending_uncaught_user_call_callable(function, this_object.as_ref(), class_context);
        let trace_function_line = function.span.line;
        let result = self.call_user_function_with_checked_values_and_locals(
            function,
            args,
            this_object,
            class_context,
            called_class_context,
            Vec::new(),
            None,
            prebound_locals,
            Vec::new(),
        );
        if let Err(error) = &result {
            self.record_pending_uncaught_call_frame(
                trace_callable,
                trace_function_line,
                span,
                &trace_args,
                error,
            );
        }
        result
    }

    fn call_error_handler_array_callable(
        &mut self,
        callback: &PhpArray,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let Some((target, method_name)) = array_callable_parts_cloned(callback) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "set_error_handler()",
                    "array callback must be [object-or-class, method] in the current subset",
                ),
            ));
        };

        match target {
            Value::Object(object) => {
                let called_class_id = object.class_id();
                let receiver_class_name = self
                    .classes
                    .get(called_class_id)
                    .expect("object class id should resolve to class metadata")
                    .name()
                    .to_string();
                let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
                    self.resolve_instance_method(called_class_id, &method_name)
                else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::undefined_function(format!(
                            "{receiver_class_name}::{method_name}()"
                        )),
                    ));
                };
                if visibility != Visibility::Public {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("{class_name}::{method_name}()"),
                            "error-handler array callable method dispatch is only implemented for public methods",
                        ),
                    ));
                }

                let function =
                    self.method_function(class_id, &class_name, &resolved_method_name, span)?;
                let function = function.as_ref();
                let args = error_handler_args_for_function(function, &args);
                ensure_user_function_arity(function, args.len(), span)?;
                ensure_supported_function_signature(function, args.len(), span)?;
                self.ensure_user_function_call_depth(function, span)?;
                let this_object = if is_static { None } else { Some(object) };
                self.call_error_handler_user_function_with_checked_values(
                    function,
                    args,
                    span,
                    this_object,
                    Some(class_id),
                    Some(called_class_id),
                    Vec::new(),
                )
            }
            Value::String(class_name) => {
                let class_id = self.classes.lookup_class_id(&class_name).ok_or_else(|| {
                    runtime_error(span, RuntimeError::undefined_class(&class_name))
                })?;
                let receiver_class = self
                    .classes
                    .get(class_id)
                    .expect("class id should resolve to class metadata");
                let Some((
                    declaring_class_id,
                    declaring_class_name,
                    resolved_method_name,
                    visibility,
                    is_static,
                )) = self.resolve_instance_method(class_id, &method_name)
                else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::undefined_function(format!(
                            "{}::{method_name}()",
                            receiver_class.name()
                        )),
                    ));
                };
                if !is_static {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("{declaring_class_name}::{method_name}()"),
                            "non-static method error handlers require an object receiver in the current subset",
                        ),
                    ));
                }
                if visibility != Visibility::Public {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            format!("{declaring_class_name}::{method_name}()"),
                            "error-handler array callable method dispatch is only implemented for public methods",
                        ),
                    ));
                }

                let function = self.method_function(
                    declaring_class_id,
                    &declaring_class_name,
                    &resolved_method_name,
                    span,
                )?;
                let function = function.as_ref();
                let args = error_handler_args_for_function(function, &args);
                ensure_user_function_arity(function, args.len(), span)?;
                ensure_supported_function_signature(function, args.len(), span)?;
                self.ensure_user_function_call_depth(function, span)?;
                self.call_error_handler_user_function_with_checked_values(
                    function,
                    args,
                    span,
                    None,
                    Some(declaring_class_id),
                    Some(class_id),
                    Vec::new(),
                )
            }
            _ => unreachable!("array_callable_parts restricts callback targets"),
        }
    }

    fn append_output_from(&mut self, output: &str, span: Option<Span>) {
        if let Some(capture) = self.output_handler_output_captures.last_mut() {
            capture.extend_from_slice(output.as_bytes());
            return;
        }
        if let Some(buffer) = self.output_buffers.last_mut() {
            buffer.contents.extend_from_slice(output.as_bytes());
        } else {
            self.mark_output_started(output, span);
            self.stdout.push_str(output);
            self.stdout_bytes.extend_from_slice(output.as_bytes());
        }
    }

    fn flush_output_buffers(&mut self) -> CompileResult<()> {
        while let Some(buffer) = self.output_buffers.pop() {
            let result = self.apply_output_buffer_handler(
                buffer.handler.as_ref(),
                buffer.contents,
                Self::output_buffer_handler_phase(buffer.handler_started, PHP_OUTPUT_HANDLER_FINAL),
                buffer.span,
            )?;
            self.append_output_handler_result(
                result,
                OutputHandlerAppendTarget::Stdout,
                "ob_end_flush()",
                buffer.span,
            )?;
            self.maybe_flush_active_output_buffer_for_chunk(buffer.span)?;
        }
        Ok(())
    }

    fn append_output_bytes_below_active_buffer_at(
        &mut self,
        output: &[u8],
        span: Span,
    ) -> CompileResult<()> {
        let Some(active_index) = self.output_buffers.len().checked_sub(1) else {
            self.mark_output_bytes_started(output, Some(span));
            self.stdout.push_str(&String::from_utf8_lossy(output));
            self.stdout_bytes.extend_from_slice(output);
            return Ok(());
        };
        self.append_output_bytes_below_buffer_at_index(active_index, output, span)
    }

    fn append_output_bytes_below_buffer_at_index(
        &mut self,
        buffer_index: usize,
        output: &[u8],
        span: Span,
    ) -> CompileResult<()> {
        if buffer_index > 0 {
            let parent_index = buffer_index - 1;
            if let Some(parent) = self.output_buffers.get_mut(parent_index) {
                parent.contents.extend_from_slice(output);
                self.maybe_flush_output_buffer_at_index_for_chunk(parent_index, span)?;
            }
        } else {
            self.mark_output_bytes_started(output, Some(span));
            self.stdout.push_str(&String::from_utf8_lossy(output));
            self.stdout_bytes.extend_from_slice(output);
        }
        Ok(())
    }

    fn push_unbuffered_stdout_text(&mut self, output: &str) {
        self.stdout.push_str(output);
        self.stdout_bytes.extend_from_slice(output.as_bytes());
    }

    fn push_unbuffered_stdout_char(&mut self, ch: char) {
        self.stdout.push(ch);
        let mut buffer = [0; 4];
        self.stdout_bytes
            .extend_from_slice(ch.encode_utf8(&mut buffer).as_bytes());
    }

    fn mark_output_started(&mut self, output: &str, span: Option<Span>) {
        if output.is_empty() || self.output_start.is_some() {
            return;
        }

        let line = span.map(|span| span.line).unwrap_or(0);
        let file = self.source_file.clone().unwrap_or_default();
        self.output_start = Some(OutputStart { file, line });
    }

    fn mark_output_bytes_started(&mut self, output: &[u8], span: Option<Span>) {
        if output.is_empty() || self.output_start.is_some() {
            return;
        }

        let line = span.map(|span| span.line).unwrap_or(0);
        let file = self.source_file.clone().unwrap_or_default();
        self.output_start = Some(OutputStart { file, line });
    }

    fn execution_stdout_bytes(&self) -> Vec<u8> {
        if self.stdout_bytes.is_empty() {
            self.stdout.as_bytes().to_vec()
        } else {
            self.stdout_bytes.clone()
        }
    }

    fn header_output_started_warning(&self) -> Option<String> {
        self.output_start.as_ref().map(|start| {
            format!(
                "Cannot modify header information - headers already sent by (output started at {}:{})",
                start.file, start.line
            )
        })
    }

    fn session_output_started_warning(&self) -> Option<String> {
        self.output_start
            .as_ref()
            .map(|_| "Session cannot be started after headers have already been sent".to_string())
    }

    fn execute_statement(&mut self, stmt: &Stmt, scope: &mut SymbolTable) -> CompileResult<Flow> {
        self.tick(stmt.span())?;
        match stmt {
            Stmt::Namespace { .. } | Stmt::Use { .. } => Ok(Flow::Normal),
            Stmt::Echo { exprs, .. } => {
                for expr in exprs {
                    let value = self.evaluate(expr, scope)?;
                    let output = self.value_to_echo_bytes(value, expr.span())?;
                    self.append_output_bytes_at(&output, expr.span());
                    self.maybe_flush_active_output_buffer_for_chunk(expr.span())?;
                }
                Ok(Flow::Normal)
            }
            Stmt::Print { expr, .. } => {
                let value = self.evaluate(expr, scope)?;
                let output = self.value_to_echo_bytes(value, expr.span())?;
                self.append_output_bytes_at(&output, expr.span());
                self.maybe_flush_active_output_buffer_for_chunk(expr.span())?;
                Ok(Flow::Normal)
            }
            Stmt::Assign { target, expr, .. } => {
                self.execute_assignment(target, expr, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::ReferenceAssign {
                target,
                source,
                span,
            } => {
                self.execute_reference_assignment(target, source, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::CompoundAssign {
                target,
                op,
                expr,
                span,
            } => {
                self.execute_compound_assignment(target, *op, expr, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::IncrementDecrement { target, op, span } => {
                self.execute_increment_decrement(target, *op, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::NullCoalesceAssign { target, expr, .. } => {
                self.evaluate_null_coalesce_assignment(target, expr, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::Expr { expr, .. } => {
                self.execute_discard_expression(expr, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::Goto { label, span } => Ok(Flow::Goto {
                label: label.clone(),
                span: *span,
            }),
            Stmt::Label { .. } => Ok(Flow::Normal),
            Stmt::If {
                condition,
                then_branch,
                else_branch,
                ..
            } => {
                if self.evaluate(condition, scope)?.is_truthy() {
                    self.execute_statements(then_branch, scope)
                } else {
                    self.execute_statements(else_branch, scope)
                }
            }
            Stmt::While {
                condition,
                body,
                span,
            } => {
                loop {
                    self.tick(*span)?;
                    if !self.evaluate(condition, scope)?.is_truthy() {
                        break;
                    }
                    match self.execute_statements(body, scope)? {
                        Flow::Normal => {}
                        Flow::Continue { depth, .. } if depth <= 1 => {}
                        Flow::Continue { depth, span } => {
                            return Ok(Flow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        Flow::Break { depth, .. } if depth <= 1 => break,
                        Flow::Break { depth, span } => {
                            return Ok(Flow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (Flow::Return(_)
                        | Flow::Goto { .. }
                        | Flow::Throw { .. }
                        | Flow::Exit(_)) => {
                            return Ok(flow);
                        }
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::DoWhile {
                body,
                condition,
                span,
            } => {
                loop {
                    self.tick(*span)?;
                    match self.execute_statements(body, scope)? {
                        Flow::Normal => {}
                        Flow::Continue { depth, .. } if depth <= 1 => {}
                        Flow::Continue { depth, span } => {
                            return Ok(Flow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        Flow::Break { depth, .. } if depth <= 1 => break,
                        Flow::Break { depth, span } => {
                            return Ok(Flow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (Flow::Return(_)
                        | Flow::Goto { .. }
                        | Flow::Throw { .. }
                        | Flow::Exit(_)) => {
                            return Ok(flow);
                        }
                    }

                    if !self.evaluate(condition, scope)?.is_truthy() {
                        break;
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::For {
                initializers,
                conditions,
                increments,
                body,
                span,
            } => {
                for initializer in initializers {
                    self.execute_for_action(initializer, scope)?;
                }

                loop {
                    self.tick(*span)?;
                    if !conditions.is_empty() {
                        let mut keep_running = true;
                        for condition in conditions {
                            keep_running = self.evaluate(condition, scope)?.is_truthy();
                        }
                        if !keep_running {
                            break;
                        }
                    }

                    match self.execute_statements(body, scope)? {
                        Flow::Normal => {}
                        Flow::Continue { depth, .. } if depth <= 1 => {}
                        Flow::Continue { depth, span } => {
                            return Ok(Flow::Continue {
                                depth: depth - 1,
                                span,
                            });
                        }
                        Flow::Break { depth, .. } if depth <= 1 => break,
                        Flow::Break { depth, span } => {
                            return Ok(Flow::Break {
                                depth: depth - 1,
                                span,
                            });
                        }
                        flow @ (Flow::Return(_)
                        | Flow::Goto { .. }
                        | Flow::Throw { .. }
                        | Flow::Exit(_)) => {
                            return Ok(flow);
                        }
                    }

                    for increment in increments {
                        self.execute_for_action(increment, scope)?;
                    }
                }

                Ok(Flow::Normal)
            }
            Stmt::Switch { value, cases, .. } => self.execute_switch(value, cases, scope),
            Stmt::Foreach {
                iterable,
                key,
                value,
                by_reference,
                body,
                span,
            } => {
                if let Some((message, fatal_span)) =
                    key.as_ref().and_then(Self::foreach_value_target_fatal)
                {
                    self.emit_simple_fatal(message, fatal_span);
                    return Ok(Flow::Exit(255));
                }
                if let Some((message, fatal_span)) = Self::foreach_value_target_fatal(value) {
                    self.emit_simple_fatal(message, fatal_span);
                    return Ok(Flow::Exit(255));
                }
                if *by_reference {
                    let root = self.by_reference_foreach_root(iterable, scope, *span)?;
                    Self::read_foreach_root_array(&root, scope, *span)?;
                    let mut position = 0usize;
                    let mut lingering_reference_key = None;

                    loop {
                        let array = Self::read_foreach_root_array(&root, scope, *span)?;
                        let Some(entry) = array.entries().get(position) else {
                            break;
                        };
                        let entry_key = entry.key.clone();
                        self.tick(*span)?;

                        self.write_foreach_key_target(
                            key,
                            value_from_array_key(&entry_key),
                            *span,
                            scope,
                        )?;
                        self.bind_foreach_value_target_reference_to_key(
                            value, &root, &entry_key, *span, scope,
                        )?;
                        if let Some(value_name) = value.variable_name() {
                            let active = Self::active_foreach_reference_for_slot(
                                &root, value_name, &entry_key, position, scope, *span,
                            )?;
                            self.active_foreach_references.push(active);
                        }
                        let flow_result = self.execute_statements(body, scope);
                        let active = if value.variable_name().is_some() {
                            self.active_foreach_references.pop()
                        } else {
                            None
                        };
                        let flow = flow_result?;

                        let array = Self::read_foreach_root_array(&root, scope, *span)?;
                        let current_position = Self::foreach_current_position_after_body(
                            &array,
                            &entry_key,
                            active.as_ref(),
                        );
                        lingering_reference_key =
                            if let (Some(value_name), Some(current_position)) =
                                (value.variable_name(), current_position.as_ref())
                            {
                                foreach_value_still_bound_to_key(
                                    scope,
                                    &root,
                                    value_name,
                                    &current_position.key,
                                )
                                .then(|| current_position.key.clone())
                            } else {
                                None
                            };
                        position = Self::foreach_next_position_after_body(
                            position,
                            current_position.as_ref(),
                            active.as_ref(),
                        );

                        match flow {
                            Flow::Normal => {}
                            Flow::Continue { depth, .. } if depth <= 1 => {}
                            Flow::Continue {
                                depth,
                                span: flow_span,
                            } => {
                                if let Some(value_name) = value.variable_name() {
                                    bind_foreach_lingering_reference(
                                        scope,
                                        value_name,
                                        &root,
                                        lingering_reference_key,
                                        *span,
                                    )?;
                                }
                                return Ok(Flow::Continue {
                                    depth: depth - 1,
                                    span: flow_span,
                                });
                            }
                            Flow::Break { depth, .. } if depth <= 1 => break,
                            Flow::Break {
                                depth,
                                span: flow_span,
                            } => {
                                if let Some(value_name) = value.variable_name() {
                                    bind_foreach_lingering_reference(
                                        scope,
                                        value_name,
                                        &root,
                                        lingering_reference_key,
                                        *span,
                                    )?;
                                }
                                return Ok(Flow::Break {
                                    depth: depth - 1,
                                    span: flow_span,
                                });
                            }
                            Flow::Goto {
                                label,
                                span: flow_span,
                            } => {
                                if let Some(value_name) = value.variable_name() {
                                    bind_foreach_lingering_reference(
                                        scope,
                                        value_name,
                                        &root,
                                        lingering_reference_key,
                                        *span,
                                    )?;
                                }
                                return Ok(Flow::Goto {
                                    label,
                                    span: flow_span,
                                });
                            }
                            flow @ (Flow::Return(_) | Flow::Throw { .. } | Flow::Exit(_)) => {
                                return Ok(flow);
                            }
                        }
                    }

                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            *span,
                        )?;
                    }
                    return Ok(Flow::Normal);
                }
                let iterable = self.evaluate_foreach_iterable(iterable, scope)?;
                self.execute_foreach_by_value_iterable(iterable, key, value, body, *span, scope)
            }
            Stmt::UnsetVariable { name, .. } => {
                let value = scope.unset_static(name);
                self.finalize_released_value(value, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetArrayIndex { name, index, span } => {
                self.execute_unset_array_index(name, index, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetNestedArrayIndex {
                name,
                indices,
                span,
            } => {
                self.execute_unset_nested_array_index(name, indices, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetObjectProperty {
                object,
                property,
                span,
            } => {
                self.execute_unset_object_property(object, property, *span, scope, true)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetDynamicObjectProperty {
                object,
                property,
                span,
            } => {
                self.execute_unset_dynamic_object_property(object, property, *span, scope)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetStaticProperty {
                class_name,
                property,
                span,
            } => {
                self.execute_unset_named_static_property(class_name, property, *span)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetSelfStaticProperty { property, span } => {
                self.execute_unset_self_static_property(property, *span)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetParentStaticProperty { property, span } => {
                self.execute_unset_parent_static_property(property, *span)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetLateStaticProperty { property, span } => {
                self.execute_unset_late_static_property(property, *span)?;
                Ok(Flow::Normal)
            }
            Stmt::UnsetMany { targets, span } => {
                for target in targets {
                    self.execute_unset_target(target, *span, scope)?;
                }
                Ok(Flow::Normal)
            }
            Stmt::ConstDeclaration { declarations, .. } => {
                for declaration in declarations {
                    self.execute_const_declaration(
                        &declaration.name,
                        &declaration.value,
                        &declaration.attributes,
                        declaration.span,
                        scope,
                    )?;
                }
                Ok(Flow::Normal)
            }
            Stmt::Require { path, once, span } => {
                self.execute_file_include(path, *once, true, *span, scope)
            }
            Stmt::Include { path, once, span } => {
                self.execute_file_include(path, *once, false, *span, scope)
            }
            Stmt::Function(function) => {
                if function.is_nested {
                    self.register_nested_function_declaration(function)?;
                }
                Ok(Flow::Normal)
            }
            Stmt::Interface(_) | Stmt::Enum(_) => Ok(Flow::Normal),
            Stmt::Trait(trait_decl) => {
                self.emit_deprecated_trait_use_diagnostics(
                    &trait_decl.name,
                    &trait_decl.trait_uses,
                )?;
                Ok(Flow::Normal)
            }
            Stmt::Class(class) => {
                if class.is_nested {
                    self.register_nested_class_declaration(class)?;
                }
                self.emit_deprecated_trait_use_diagnostics(&class.name, &class.trait_uses)?;
                Ok(Flow::Normal)
            }
            Stmt::Return { value, span } => {
                self.last_return_span = Some(*span);
                let value = match value {
                    Some(expr) => self.evaluate(expr, scope)?,
                    None => Value::Null,
                };
                Ok(Flow::Return(value))
            }
            Stmt::Throw { expr, span } => {
                let object = self.throwable_object_from_expr(expr, *span, scope)?;
                Ok(Flow::Throw {
                    object,
                    span: *span,
                })
            }
            Stmt::Try {
                body,
                catches,
                finally_body,
                ..
            } => self.execute_try_statement(body, catches, finally_body.as_deref(), scope),
            Stmt::Break { depth, span } => Ok(Flow::Break {
                depth: *depth,
                span: *span,
            }),
            Stmt::Continue { depth, span } => Ok(Flow::Continue {
                depth: *depth,
                span: *span,
            }),
            Stmt::Global { names, .. } => {
                if self.function_context.is_empty() {
                    for name in names {
                        if scope.read_named(name).is_none() {
                            scope.write_static(name, Value::Null);
                        }
                    }
                    Ok(Flow::Normal)
                } else {
                    for name in names {
                        scope.import_global(name);
                    }
                    Ok(Flow::Normal)
                }
            }
            Stmt::StaticLocal { declarations, span } => {
                self.execute_static_local_declaration(declarations, *span, scope)?;
                Ok(Flow::Normal)
            }
        }
    }

    fn tick(&mut self, span: Span) -> CompileResult<()> {
        if let Some(max_steps) = self.max_execution_steps {
            if self.execution_steps >= max_steps {
                let source = self.source_file.as_deref().unwrap_or("<unknown>");
                let function_context = self
                    .function_context
                    .last()
                    .map(|name| format!("; function {name}()"))
                    .unwrap_or_default();
                return Err(Diagnostic::new(
                    Phase::Runtime,
                    span.line,
                    span.column,
                    format!(
                        "maximum execution step budget exceeded after {max_steps} step(s); last location {source}:{}:{}{function_context}",
                        span.line, span.column
                    ),
                ));
            }
        }
        self.execution_steps += 1;
        Ok(())
    }

    fn execute_static_local_declaration(
        &mut self,
        declarations: &[StaticLocalDeclarator],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let Some(function_name) = self.function_context.last().cloned() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "static",
                    "top-level static local declarations are not implemented",
                ),
            ));
        };
        let function_key = function_name.to_ascii_lowercase();

        for declaration in declarations {
            if let Some(active) = self.active_static_locals.last_mut() {
                if !active.contains(&declaration.name) {
                    active.push(declaration.name.clone());
                }
            }

            let key = (function_key.clone(), declaration.name.clone());
            let value = if let Some(value) = self.static_locals.get(&key) {
                value.clone()
            } else {
                let value = match &declaration.default {
                    Some(default) => self.evaluate(default, scope)?,
                    None => Value::Null,
                };
                self.static_locals.insert(key, value.clone());
                value
            };
            scope.write_static(&declaration.name, value);
        }

        Ok(())
    }

    fn execute_try_statement(
        &mut self,
        body: &[Stmt],
        catches: &[CatchClause],
        finally_body: Option<&[Stmt]>,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let try_flow = match self.execute_statements(body, scope) {
            Ok(Flow::Throw { object, span }) => {
                self.execute_catch_flow(object, span, catches, scope)?
            }
            Ok(flow) => flow,
            Err(error) if catchable_php_error_message(&error).is_some() => {
                match self.execute_catchable_php_error_catch_flow(&error, catches, scope)? {
                    Some(flow) => flow,
                    None => return Err(error),
                }
            }
            Err(error) => return Err(error),
        };
        if let Some(finally_body) = finally_body {
            let finally_flow = self.execute_statements(finally_body, scope)?;
            if !matches!(finally_flow, Flow::Normal) {
                return Ok(finally_flow);
            }
        }
        Ok(try_flow)
    }

    fn execute_catch_flow(
        &mut self,
        object: PhpObject,
        span: Span,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        for catch in catches {
            if !self.catch_matches_thrown_object(&object, catch)? {
                continue;
            }
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(object));
            }
            return self.execute_statements(&catch.body, scope);
        }

        Ok(Flow::Throw { object, span })
    }

    fn execute_catchable_php_error_catch_flow(
        &mut self,
        error: &Diagnostic,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<Flow>> {
        let Some((error_class_name, error_message)) =
            self.catchable_php_error_class_and_message_with_pending_call_site(error)
        else {
            return Ok(None);
        };
        let Some(error_class_id) = self.classes.lookup_class_id(error_class_name) else {
            return Ok(None);
        };
        let error_object =
            self.create_core_error_object(error_message, error_class_id, error.line)?;
        for catch in catches {
            if !self.catch_matches_class(error_class_id, catch)? {
                continue;
            }
            self.clear_pending_uncaught_call_frames();
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(error_object.clone()));
            }
            return self.execute_statements(&catch.body, scope).map(Some);
        }
        Ok(None)
    }

    fn throwable_object_from_expr(
        &mut self,
        expr: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<PhpObject> {
        let thrown = self.evaluate(expr, scope)?;
        self.throwable_object_from_value(thrown, span)
    }

    fn throwable_object_from_value(&self, thrown: Value, span: Span) -> CompileResult<PhpObject> {
        let Value::Object(object) = thrown else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "throw",
                    format!("throwing {} values is not implemented", thrown.type_name()),
                ),
            ));
        };
        if !Self::is_throwable_object(&object) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "throw",
                    format!(
                        "objects of class {} do not implement Throwable in the current subset",
                        object.class_name()
                    ),
                ),
            ));
        }
        Ok(object)
    }

    fn is_throwable_object(object: &PhpObject) -> bool {
        object.is_instance_of_class_name("Exception")
            || object.is_instance_of_class_name("Error")
            || object.is_instance_of_class_name("Throwable")
    }

    fn catch_matches_thrown_object(
        &self,
        object: &PhpObject,
        catch: &CatchClause,
    ) -> CompileResult<bool> {
        for catch_type in &catch.types {
            let catch_name = catch_type
                .name
                .strip_prefix('\\')
                .unwrap_or(&catch_type.name);
            if catch_name.eq_ignore_ascii_case("Throwable") {
                if Self::is_throwable_object(object) {
                    return Ok(true);
                }
                continue;
            }

            let Some(class) = self.classes.lookup_class(catch_name) else {
                continue;
            };
            if object.class_id() == class.id()
                || self.classes.is_subclass_of(object.class_id(), class.id())
            {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn catch_matches_class(&self, class_id: ClassId, catch: &CatchClause) -> CompileResult<bool> {
        for catch_type in &catch.types {
            let catch_name = catch_type
                .name
                .strip_prefix('\\')
                .unwrap_or(&catch_type.name);
            if catch_name.eq_ignore_ascii_case("Throwable") {
                let exception_id = self.classes.lookup_class_id("Exception");
                let error_id = self.classes.lookup_class_id("Error");
                if exception_id.is_some_and(|exception_id| {
                    class_id == exception_id || self.classes.is_subclass_of(class_id, exception_id)
                }) || error_id.is_some_and(|error_id| {
                    class_id == error_id || self.classes.is_subclass_of(class_id, error_id)
                }) {
                    return Ok(true);
                }
                continue;
            }

            let Some(class) = self.classes.lookup_class(catch_name) else {
                continue;
            };
            if class_id == class.id() || self.classes.is_subclass_of(class_id, class.id()) {
                return Ok(true);
            }
        }
        Ok(false)
    }

    fn uncaught_throw_execution(
        &mut self,
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<Execution> {
        if self.call_exception_handler_for_throw(object, span)? {
            self.run_shutdown_callbacks()?;
            self.run_shutdown_destructors()?;
            self.flush_output_buffers()?;
            return Ok(Execution {
                stdout: self.stdout.clone(),
                stdout_bytes: self.execution_stdout_bytes(),
                stderr: self.stderr.clone(),
                exit_code: self.exit_signal.unwrap_or(0),
            });
        }

        self.emit_uncaught_throw_fatal(object, span);
        self.exit_signal = Some(255);
        self.run_shutdown_callbacks()?;
        self.run_shutdown_destructors()?;
        self.flush_output_buffers()?;
        Ok(Execution {
            stdout: self.stdout.clone(),
            stdout_bytes: self.execution_stdout_bytes(),
            stderr: self.stderr.clone(),
            exit_code: self.exit_signal.unwrap_or(255),
        })
    }

    fn call_exception_handler_for_throw(
        &mut self,
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<bool> {
        if self.exception_handler_active {
            return Ok(false);
        }
        let Some(handler) = self.exception_handlers.last().cloned() else {
            return Ok(false);
        };
        if matches!(handler, Value::Null) {
            return Ok(false);
        }

        self.exception_handler_active = true;
        let result = self.call_exception_handler_callback(handler, object.clone(), span);
        self.exception_handler_active = false;
        result.map(|_| true)
    }

    fn call_exception_handler_callback(
        &mut self,
        handler: Value,
        object: PhpObject,
        span: Span,
    ) -> CompileResult<Value> {
        let args = vec![Value::Object(object)];
        match handler {
            Value::String(name) => {
                if let Some(callable) = self.lookup_function(&name) {
                    return match callable {
                        Callable::User(function) => {
                            self.call_user_function_with_values(function, args, span)
                        }
                        Callable::Builtin(key) => self.call_builtin(&key, args, span),
                    };
                }

                if static_method_callable_string(&name).is_some() {
                    let callback = static_method_callable_value_from_string(&name, span)?;
                    return self.call_array_callable_with_values(
                        &callback,
                        args,
                        span,
                    );
                }

                Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(callable_name(&name)),
                ))
            }
            Value::Array(array) => self.call_array_callable_with_values(&array, args, span),
            Value::Closure(closure) => {
                self.invoke_closure_value(closure, args, span, "set_exception_handler()")
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "set_exception_handler()",
                    format!(
                        "stored handler must be string, array callable, or closure in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn emit_uncaught_throw_fatal(&mut self, object: &PhpObject, span: Span) {
        let class_name = object.class_name();
        let message = self.throwable_message_for_fatal(object);
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        let stack_trace = self.formatted_pending_uncaught_call_trace(&file);
        self.push_uncaught_fatal_separator();
        let message_suffix = if message.is_empty() {
            String::new()
        } else {
            format!(": {message}")
        };
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: Uncaught {class_name}{message_suffix} in {file}:{}\nStack trace:\n{stack_trace}\n  thrown in {file} on line {}",
            span.line, span.line
        ));
    }

    fn throwable_message_for_fatal(&self, object: &PhpObject) -> String {
        let class_id = object.class_id();
        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        match object.read_property_from_context("message", Some(class_id), &protected_class_ids) {
            Ok(Value::String(message)) => message,
            Ok(Value::Int(message)) => message.to_string(),
            Ok(Value::Float(message)) => message.to_string(),
            Ok(Value::Bool(true)) => "1".to_string(),
            Ok(Value::Bool(false) | Value::Null) | Err(_) => String::new(),
            Ok(other) => other.type_name().to_string(),
        }
    }

    fn throwable_display_file(&self) -> String {
        self.source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string())
    }

    fn throwable_display_file_for_object(&self, object: &PhpObject) -> String {
        let class_id = object.class_id();
        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        match object.read_property_from_context("file", Some(class_id), &protected_class_ids) {
            Ok(Value::String(file)) => file,
            Ok(Value::BinaryString(bytes)) => String::from_utf8_lossy(&bytes).into_owned(),
            Ok(Value::Int(file)) => file.to_string(),
            Ok(Value::Float(file)) => file.to_string(),
            Ok(Value::Bool(true)) => "1".to_string(),
            Ok(Value::Bool(false) | Value::Null) | Err(_) => self.throwable_display_file(),
            Ok(other) => other.type_name().to_string(),
        }
    }

    fn throwable_display_line(&self, object: &PhpObject, fallback: usize) -> usize {
        let class_id = object.class_id();
        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        match object.read_property_from_context("line", Some(class_id), &protected_class_ids) {
            Ok(Value::Int(line)) if line >= 0 => line as usize,
            _ => fallback,
        }
    }

    fn throwable_trace_as_string(&self, object: &PhpObject) -> String {
        self.throwable_string_traces
            .get(&object.id())
            .cloned()
            .unwrap_or_else(|| "#0 {main}".to_string())
    }

    fn throwable_to_php_string(&self, object: &PhpObject, span: Span) -> Option<String> {
        if !Self::is_throwable_object(object) {
            return None;
        }

        let class_name = object.class_name();
        let message = self.throwable_message_for_fatal(object);
        let message_suffix = if message.is_empty() {
            String::new()
        } else {
            format!(": {message}")
        };
        let file = self.throwable_display_file_for_object(object);
        let line = self.throwable_display_line(object, span.line);
        let stack_trace = self.throwable_trace_as_string(object);
        Some(format!(
            "{class_name}{message_suffix} in {file}:{line}\nStack trace:\n{stack_trace}"
        ))
    }

    fn uncaught_throw_error(&self, object: &PhpObject, span: Span) -> Diagnostic {
        let message = self.throwable_message_for_fatal(object);
        let message_suffix = if message.is_empty() {
            String::new()
        } else {
            format!(": {message}")
        };
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "throw",
                format!(
                    "uncaught {} propagation beyond catch/finally is not implemented{}",
                    object.class_name(),
                    message_suffix
                ),
            ),
        )
    }

    fn uncaught_call_argument_type_error_execution(
        &mut self,
        error: &Diagnostic,
        error_class_name: &str,
        error_message: &str,
    ) -> CompileResult<Execution> {
        self.emit_uncaught_call_argument_type_error_fatal(error, error_class_name, error_message);
        self.exit_signal = Some(255);
        self.run_shutdown_callbacks()?;
        self.run_shutdown_destructors()?;
        self.flush_output_buffers()?;
        Ok(Execution {
            stdout: self.stdout.clone(),
            stdout_bytes: self.execution_stdout_bytes(),
            stderr: self.stderr.clone(),
            exit_code: self.exit_signal.unwrap_or(255),
        })
    }

    fn uncaught_php_error_execution(
        &mut self,
        error: &Diagnostic,
        error_class_name: &str,
        error_message: &str,
    ) -> CompileResult<Execution> {
        self.emit_uncaught_php_error_fatal(error, error_class_name, error_message);
        self.exit_signal = Some(255);
        self.run_shutdown_callbacks()?;
        self.run_shutdown_destructors()?;
        self.flush_output_buffers()?;
        Ok(Execution {
            stdout: self.stdout.clone(),
            stdout_bytes: self.execution_stdout_bytes(),
            stderr: self.stderr.clone(),
            exit_code: self.exit_signal.unwrap_or(255),
        })
    }

    fn fatal_runtime_message_execution(
        &mut self,
        error: &Diagnostic,
        message: &str,
    ) -> CompileResult<Execution> {
        self.emit_runtime_fatal_message(error, message);
        self.exit_signal = Some(255);
        self.run_shutdown_callbacks()?;
        self.run_shutdown_destructors()?;
        self.flush_output_buffers()?;
        Ok(Execution {
            stdout: self.stdout.clone(),
            stdout_bytes: self.execution_stdout_bytes(),
            stderr: self.stderr.clone(),
            exit_code: self.exit_signal.unwrap_or(255),
        })
    }

    fn emit_runtime_fatal_message(&mut self, error: &Diagnostic, message: &str) {
        let file = self
            .source_file
            .clone()
            .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
            .unwrap_or_else(|| "Command line code".to_string());
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: {message} in {file} on line {}",
            error.line
        ));
    }

    fn emit_uncaught_php_error_fatal(
        &mut self,
        error: &Diagnostic,
        error_class_name: &str,
        error_message: &str,
    ) {
        let file = self
            .source_file
            .clone()
            .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
            .unwrap_or_else(|| "Command line code".to_string());
        let line = error.line;
        let stack_trace = self.formatted_pending_uncaught_call_trace(&file);
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: Uncaught {error_class_name}: {error_message} in {file}:{line}\nStack trace:\n{stack_trace}\n  thrown in {file} on line {line}"
        ));
    }

    fn push_uncaught_fatal_separator(&mut self) {
        if self.stdout.is_empty() {
            return;
        }
        if !self.stdout.ends_with('\n') {
            self.push_unbuffered_stdout_char('\n');
            return;
        }
        if !self.stdout.ends_with("\n\n") {
            self.push_unbuffered_stdout_char('\n');
        }
    }

    fn formatted_pending_uncaught_call_trace(&self, file: &str) -> String {
        Self::formatted_call_trace(&self.pending_uncaught_call_frames, file)
    }

    fn formatted_call_trace(frames: &[PendingUncaughtCallFrame], file: &str) -> String {
        if frames.is_empty() {
            return "#0 {main}".to_string();
        }

        let mut trace = String::new();
        for (index, frame) in frames.iter().enumerate() {
            trace.push_str(&format!(
                "#{index} {file}({}): {}({})\n",
                frame.call_line,
                frame.display_callable(file),
                format_stack_trace_args(&frame.args)
            ));
        }
        trace.push_str(&format!("#{} {{main}}", frames.len()));
        trace
    }

    fn current_structured_trace_frames(&self) -> Vec<PendingUncaughtCallFrame> {
        self.active_debug_backtrace_frames
            .iter()
            .rev()
            .cloned()
            .collect()
    }

    fn store_throwable_trace(&mut self, object: &PhpObject, file: &str) {
        let frames = self.current_structured_trace_frames();
        let trace = Self::formatted_call_trace(&frames, file);
        self.throwable_string_traces.insert(object.id(), trace);
        self.throwable_traces.insert(object.id(), frames);
    }

    fn throwable_trace_array(&self, object: &PhpObject, span: Span) -> CompileResult<Value> {
        let frames = self
            .throwable_traces
            .get(&object.id())
            .cloned()
            .unwrap_or_default();
        self.structured_trace_array(&frames, span)
    }

    fn structured_trace_array(
        &self,
        frames: &[PendingUncaughtCallFrame],
        span: Span,
    ) -> CompileResult<Value> {
        let file = self.throwable_display_file();
        let mut output = PhpArray::new();
        for frame in frames {
            output
                .append(self.structured_trace_frame_array(frame, &file, span)?)
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(Value::Array(output))
    }

    fn structured_trace_frame_array(
        &self,
        frame: &PendingUncaughtCallFrame,
        file: &str,
        span: Span,
    ) -> CompileResult<Value> {
        let mut args = PhpArray::new();
        for value in &frame.args {
            args.append(value.clone())
                .map_err(|error| runtime_error(span, error))?;
        }

        let mut entry = PhpArray::new();
        entry.insert(
            ArrayKey::String("file".to_string()),
            Value::String(file.to_string()),
        );
        entry.insert(
            ArrayKey::String("line".to_string()),
            Value::Int(frame.call_line as i64),
        );
        entry.insert(
            ArrayKey::String("function".to_string()),
            Value::String(frame.display_callable(file)),
        );
        entry.insert(ArrayKey::String("args".to_string()), Value::Array(args));
        Ok(Value::Array(entry))
    }

    fn clear_pending_uncaught_call_frames(&mut self) {
        self.pending_uncaught_call_frames.clear();
    }

    fn catchable_php_error_class_and_message_with_pending_call_site(
        &self,
        error: &Diagnostic,
    ) -> Option<(&'static str, String)> {
        let (class_name, message) = catchable_php_error_class_and_message(error)?;
        Some((
            class_name,
            self.append_pending_call_site_to_argument_type_error_message(error, &message),
        ))
    }

    fn append_pending_call_site_to_argument_type_error_message(
        &self,
        error: &Diagnostic,
        message: &str,
    ) -> String {
        if message.contains(", called in ") {
            return message.to_string();
        }
        let Some(callable) = call_argument_type_error_callable(message) else {
            return message.to_string();
        };
        let Some(frame) = self.pending_uncaught_call_frames.last() else {
            return message.to_string();
        };
        if frame.function_line == frame.call_line {
            return message.to_string();
        }
        let callable = callable.strip_suffix("()").unwrap_or(callable);
        let same_callable = callable_names_match_pending_frame(callable, &frame.function_name)
            || (frame.function_name == "{closure}" && callable.starts_with("{closure:"));
        if !same_callable {
            return message.to_string();
        }
        let file = self
            .source_file
            .clone()
            .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
            .unwrap_or_else(|| "Command line code".to_string());
        format!("{message}, called in {file} on line {}", frame.call_line)
    }

    fn record_pending_uncaught_call_frame(
        &mut self,
        function_name: String,
        function_line: usize,
        call_span: Span,
        args: &[Value],
        error: &Diagnostic,
    ) {
        if catchable_php_error_message(error).is_none() {
            return;
        }
        if self
            .pending_uncaught_call_frames
            .last()
            .is_some_and(PendingUncaughtCallFrame::is_core_attribute_constructor)
        {
            return;
        }
        self.pending_uncaught_call_frames
            .push(PendingUncaughtCallFrame {
                function_name,
                function_line,
                call_line: call_span.line,
                args: args.to_vec(),
            });
    }

    fn pending_user_debug_call_frame(
        &mut self,
        function: &FunctionDecl,
        this_object: Option<&PhpObject>,
        class_context: Option<ClassId>,
        call_span: Span,
        args: &[Value],
    ) -> CompileResult<PendingUncaughtCallFrame> {
        Ok(PendingUncaughtCallFrame {
            function_name: self.pending_uncaught_user_call_callable(
                function,
                this_object,
                class_context,
            ),
            function_line: function.span.line,
            call_line: call_span.line,
            args: self.sensitive_parameter_trace_args(function, args, call_span)?,
        })
    }

    fn sensitive_parameter_trace_args(
        &mut self,
        function: &FunctionDecl,
        args: &[Value],
        span: Span,
    ) -> CompileResult<Vec<Value>> {
        let mut output = Vec::with_capacity(args.len());
        for (index, value) in args.iter().enumerate() {
            let should_redact = Self::call_argument_param_for_index(function, index)
                .map(|(_, param)| attributes_include_sensitive_parameter(&param.attributes))
                .unwrap_or(false);
            if should_redact {
                output.push(Value::Object(
                    self.create_sensitive_parameter_value_object(value.clone(), span)?,
                ));
            } else {
                output.push(value.clone());
            }
        }
        Ok(output)
    }

    fn pending_uncaught_user_call_callable(
        &self,
        function: &FunctionDecl,
        this_object: Option<&PhpObject>,
        class_context: Option<ClassId>,
    ) -> String {
        if function.name == "{closure}" {
            let source_file = self.source_file.as_deref().unwrap_or("Command line code");
            let closure_name = format!("{{closure:{source_file}:{}}}", function.span.line);
            if let Some(object) = this_object {
                return format!("{}->{closure_name}", object.class_name());
            }
            if let Some(class_id) = class_context {
                if let Some(class) = self.classes.get(class_id) {
                    return format!("{}::{closure_name}", class.name());
                }
            }
            return closure_name;
        }

        if let Some(class_id) = class_context {
            if let Some(class) = self.classes.get(class_id) {
                if this_object.is_some() {
                    return format!("{}->{}", class.name(), function.name);
                }
                return format!("{}::{}", class.name(), function.name);
            }
        }

        if let Some(object) = this_object {
            return format!("{}->{}", object.class_name(), function.name);
        }

        function.name.clone()
    }

    fn record_pending_uncaught_internal_call_frame(
        &mut self,
        callable: impl Into<String>,
        call_span: Span,
        args: &[Value],
        error: &Diagnostic,
    ) {
        if catchable_php_error_message(error).is_none() {
            return;
        }
        self.pending_uncaught_call_frames
            .push(PendingUncaughtCallFrame {
                function_name: callable.into(),
                function_line: call_span.line,
                call_line: call_span.line,
                args: args.to_vec(),
            });
    }

    fn emit_uncaught_call_argument_type_error_fatal(
        &mut self,
        error: &Diagnostic,
        error_class_name: &str,
        error_message: &str,
    ) {
        let file = self
            .source_file
            .clone()
            .or_else(|| error.file.as_ref().map(|file| file.display().to_string()))
            .unwrap_or_else(|| "Command line code".to_string());
        let line = error.line;
        let has_only_internal_frames = self
            .pending_uncaught_call_frames
            .iter()
            .all(|frame| frame.function_line == frame.call_line);
        if !self.pending_uncaught_call_frames.is_empty() && has_only_internal_frames {
            let stack_trace = self.formatted_pending_uncaught_call_trace(&file);
            self.push_uncaught_fatal_separator();
            self.push_unbuffered_stdout_text(&format!(
                "Fatal error: Uncaught {error_class_name}: {error_message} in {file}:{line}\nStack trace:\n{stack_trace}\n  thrown in {file} on line {line}"
            ));
            return;
        }
        let callable = call_argument_type_error_callable(error_message).unwrap_or("{main}");
        let matching_frame = self
            .pending_uncaught_call_frames
            .last()
            .filter(|frame| pending_frame_matches_call_argument_callable(frame, callable));
        let call_line = matching_frame.map_or(line, |frame| frame.call_line);
        let trace_callable = matching_frame
            .map(|frame| {
                format_call_trace_callable_with_args(&frame.display_callable(&file), &frame.args)
            })
            .unwrap_or_else(|| callable.to_string());
        self.push_uncaught_fatal_separator();
        self.push_unbuffered_stdout_text(&format!(
            "Fatal error: Uncaught {error_class_name}: {error_message}, called in {file} on line {call_line} and defined in {file}:{line}\nStack trace:\n#0 {file}({call_line}): {trace_callable}\n#1 {{main}}\n  thrown in {file} on line {line}"
        ));
    }

    fn create_core_error_object(
        &mut self,
        message: String,
        class_id: ClassId,
        line: usize,
    ) -> CompileResult<PhpObject> {
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("core Error class id should resolve");
        let class_name = class.name().to_string();
        let code = if class_name.eq_ignore_ascii_case("DOMException") {
            dom_exception_code_for_message(&message)
        } else {
            0
        };
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        let protected_class_ids = self.protected_class_ids_for_context(class_id);
        object
            .write_property_from_context(
                "message",
                Value::String(message),
                Some(class_id),
                &protected_class_ids,
            )
            .map_err(|error| runtime_error(Span { line: 0, column: 0 }, error))?;
        object
            .write_property_from_context(
                "code",
                Value::Int(code),
                Some(class_id),
                &protected_class_ids,
            )
            .map_err(|error| runtime_error(Span { line: 0, column: 0 }, error))?;
        let file = self.throwable_display_file();
        object
            .write_property_from_context(
                "file",
                Value::String(file.clone()),
                Some(class_id),
                &protected_class_ids,
            )
            .map_err(|error| runtime_error(Span { line: 0, column: 0 }, error))?;
        object
            .write_property_from_context(
                "line",
                Value::Int(line as i64),
                Some(class_id),
                &protected_class_ids,
            )
            .map_err(|error| runtime_error(Span { line: 0, column: 0 }, error))?;
        object
            .write_property_from_context(
                "previous",
                Value::Null,
                Some(class_id),
                &protected_class_ids,
            )
            .map_err(|error| runtime_error(Span { line: 0, column: 0 }, error))?;
        let trace_frames = self.pending_uncaught_call_frames.clone();
        let stack_trace = Self::formatted_call_trace(&trace_frames, &file);
        self.throwable_string_traces
            .insert(object.id(), stack_trace);
        self.throwable_traces.insert(object.id(), trace_frames);
        self.track_allocated_object(&object);
        Ok(object)
    }

    fn execute_for_action(
        &mut self,
        action: &ForAction,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match action {
            ForAction::Assign { target, expr } => self.execute_assignment(target, expr, scope),
            ForAction::CompoundAssign {
                target,
                op,
                expr,
                span,
            } => self.execute_compound_assignment(target, *op, expr, *span, scope),
            ForAction::IncrementDecrement { target, op, span } => {
                self.execute_increment_decrement(target, *op, *span, scope)
            }
            ForAction::Expr { expr } => self.execute_discard_expression(expr, scope),
        }
    }

    fn execute_discard_expression(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        if let Expr::Cast {
            kind: CastKind::Void,
            expr: inner,
            ..
        } = expr
        {
            let value = self.evaluate(inner, scope)?;
            self.finalize_released_value(Some(value), scope)?;
            return Ok(());
        }

        let value = self.evaluate(expr, scope)?;
        self.finalize_released_value(Some(value), scope)?;
        self.emit_no_discard_warning_for_expr(expr, scope)
    }

    fn emit_no_discard_warning_for_expr(
        &mut self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> CompileResult<()> {
        let Some(target) = self.no_discard_warning_target_for_expr(expr, scope) else {
            return Ok(());
        };

        let message = match target.message_override {
            Some(message) => Some(message),
            None => target
                .attribute
                .as_ref()
                .map(|attribute| {
                    self.no_discard_attribute_message(
                        attribute,
                        target.strict_types,
                        target.function_span,
                    )
                })
                .transpose()?
                .flatten(),
        };
        let mut diagnostic = format!(
            "The return value of {} {}() should either be used or intentionally ignored by casting it as (void)",
            target.callable_kind, target.callable_name
        );
        if let Some(message) = message.filter(|value| !value.is_empty()) {
            diagnostic.push_str(", ");
            diagnostic.push_str(&message);
        }

        self.emit_display_diagnostic("Warning", PHP_E_USER_WARNING, diagnostic, expr.span())
    }

    fn no_discard_warning_target_for_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<NoDiscardWarningTarget> {
        match expr {
            Expr::Call { name, args, .. } => {
                let key = name.trim_start_matches('\\').to_ascii_lowercase();
                if key == "call_user_func" {
                    return args.first().and_then(|arg| {
                        self.no_discard_warning_target_for_callback_expr(arg, scope)
                    });
                }

                match self.lookup_direct_function_call(name) {
                    Some(Callable::User(function)) => self.no_discard_warning_target_for_function(
                        function.as_ref(),
                        "function",
                        function.name.clone(),
                    ),
                    _ => None,
                }
            }
            Expr::DynamicCall { callee, .. } => self
                .callable_value_from_no_discard_expr(callee, scope)
                .and_then(|value| self.no_discard_warning_target_for_callable_value(&value)),
            Expr::MethodCall { target, method, .. } => self
                .object_value_from_no_discard_expr(target, scope)
                .and_then(|object| {
                    self.no_discard_warning_target_for_object_method(&object, method)
                }),
            Expr::StaticMethodCall {
                class_name, method, ..
            } => self.no_discard_warning_target_for_static_method(class_name, method),
            Expr::ObjectStaticMethodCall { target, method, .. } => self
                .callable_value_from_no_discard_expr(target, scope)
                .and_then(|value| {
                    self.no_discard_warning_target_for_static_method_value(&value, method)
                }),
            Expr::SelfMethodCall { method, .. } => self
                .class_context
                .last()
                .and_then(|class_id| self.classes.get(*class_id))
                .and_then(|class| {
                    self.no_discard_warning_target_for_static_method(class.name(), method)
                }),
            Expr::LateStaticMethodCall { method, .. } => self
                .called_class_context
                .last()
                .or_else(|| self.class_context.last())
                .and_then(|class_id| self.classes.get(*class_id))
                .and_then(|class| {
                    self.no_discard_warning_target_for_static_method(class.name(), method)
                }),
            _ => None,
        }
    }

    fn no_discard_warning_target_for_callback_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<NoDiscardWarningTarget> {
        if let Some(value) = self.callable_value_from_no_discard_expr(expr, scope) {
            return self.no_discard_warning_target_for_callable_value(&value);
        }

        let Expr::Array { items, .. } = expr else {
            return None;
        };
        let [first, second] = items.as_slice() else {
            return None;
        };
        if first.key.is_some() || second.key.is_some() || first.by_reference || second.by_reference
        {
            return None;
        }
        let target = self.callable_value_from_no_discard_expr(&first.value, scope)?;
        let method = Self::literal_string_expr_value(&second.value)?;
        self.no_discard_warning_target_for_array_callable_parts(&target, &method)
    }

    fn callable_value_from_no_discard_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<Value> {
        match expr {
            Expr::Variable(name, _) => scope.read_named(name),
            Expr::String(_, _) => Self::literal_string_expr_value(expr).map(Value::String),
            _ => None,
        }
    }

    fn object_value_from_no_discard_expr(
        &self,
        expr: &Expr,
        scope: &SymbolTable,
    ) -> Option<PhpObject> {
        match self.callable_value_from_no_discard_expr(expr, scope)? {
            Value::Object(object) => Some(object),
            _ => None,
        }
    }

    fn literal_string_expr_value(expr: &Expr) -> Option<String> {
        let Expr::String(value, _) = expr else {
            return None;
        };
        match php_string_literal_value(value) {
            Value::String(value) => Some(value),
            Value::BinaryString(bytes) => Some(String::from_utf8_lossy(&bytes).into_owned()),
            _ => None,
        }
    }

    fn no_discard_warning_target_for_callable_value(
        &self,
        value: &Value,
    ) -> Option<NoDiscardWarningTarget> {
        match value {
            Value::String(name) => {
                if let Some((class_name, method)) = static_method_callable_string(name) {
                    return self.no_discard_warning_target_for_static_method(class_name, method);
                }
                match self.lookup_function(name) {
                    Some(Callable::User(function)) => self.no_discard_warning_target_for_function(
                        function.as_ref(),
                        "function",
                        function.name.clone(),
                    ),
                    _ => None,
                }
            }
            Value::Closure(closure) => self.no_discard_warning_target_for_closure(closure),
            Value::Array(callback) => {
                let (target, method) = array_callable_parts(callback)?;
                self.no_discard_warning_target_for_array_callable_parts(target, method)
            }
            _ => None,
        }
    }

    fn no_discard_warning_target_for_array_callable_parts(
        &self,
        target: &Value,
        method: &str,
    ) -> Option<NoDiscardWarningTarget> {
        match target {
            Value::Object(object) => {
                self.no_discard_warning_target_for_object_method(object, method)
            }
            Value::String(class_name) => {
                self.no_discard_warning_target_for_static_method(class_name, method)
            }
            _ => None,
        }
    }

    fn no_discard_warning_target_for_function(
        &self,
        function: &FunctionDecl,
        callable_kind: &'static str,
        callable_name: String,
    ) -> Option<NoDiscardWarningTarget> {
        let attribute = function
            .attributes
            .iter()
            .find(|attribute| attribute_name_is_no_discard(attribute))
            .cloned()?;
        Some(NoDiscardWarningTarget {
            callable_kind,
            callable_name,
            attribute: Some(attribute),
            strict_types: function.strict_types,
            function_span: function.span,
            message_override: None,
        })
    }

    fn no_discard_warning_target_for_closure(
        &self,
        closure: &PhpClosure,
    ) -> Option<NoDiscardWarningTarget> {
        let function = self.closure_functions.get(&closure.id())?;
        let attribute = function
            .attributes
            .iter()
            .find(|attribute| attribute_name_is_no_discard(attribute))
            .cloned()?;
        let file = self
            .closure_reflection_functions
            .get(&closure.id())
            .and_then(|state| state.file_name.as_deref())
            .or(self.source_file.as_deref())
            .unwrap_or("Command line code");
        let line = self
            .closure_reflection_functions
            .get(&closure.id())
            .map(|state| state.start_line)
            .unwrap_or(function.span.line);
        Some(NoDiscardWarningTarget {
            callable_kind: "function",
            callable_name: format!("{{closure:{file}:{line}}}"),
            attribute: Some(attribute),
            strict_types: function.strict_types,
            function_span: function.span,
            message_override: None,
        })
    }

    fn no_discard_warning_target_for_object_method(
        &self,
        object: &PhpObject,
        method_name: &str,
    ) -> Option<NoDiscardWarningTarget> {
        if object.is_instance_of_class_name("DateTimeImmutable")
            && method_name.eq_ignore_ascii_case("setTimestamp")
        {
            return Some(NoDiscardWarningTarget {
                callable_kind: "method",
                callable_name: "DateTimeImmutable::setTimestamp".to_string(),
                attribute: None,
                strict_types: false,
                function_span: Span::new(0, 0),
                message_override: Some(
                    "as DateTimeImmutable::setTimestamp() does not modify the object itself"
                        .to_string(),
                ),
            });
        }

        let (class_id, class_name, resolved_method_name, _, _) =
            self.resolve_instance_method_for_current_object_scope(object.class_id(), method_name)?;
        let function = self
            .methods
            .get(&(class_id, resolved_method_name.to_ascii_lowercase()))?;
        self.no_discard_warning_target_for_function(
            function.as_ref(),
            "method",
            format!("{class_name}::{resolved_method_name}"),
        )
    }

    fn no_discard_warning_target_for_static_method_value(
        &self,
        value: &Value,
        method_name: &str,
    ) -> Option<NoDiscardWarningTarget> {
        match value {
            Value::Object(object) => {
                self.no_discard_warning_target_for_static_method(object.class_name(), method_name)
            }
            Value::String(class_name) => {
                self.no_discard_warning_target_for_static_method(class_name, method_name)
            }
            _ => None,
        }
    }

    fn no_discard_warning_target_for_static_method(
        &self,
        class_name: &str,
        method_name: &str,
    ) -> Option<NoDiscardWarningTarget> {
        let class_id = self.classes.lookup_class_id(class_name)?;
        let (declaring_class_id, declaring_class_name, resolved_method_name, _, is_static) =
            self.resolve_instance_method(class_id, method_name)?;
        if !is_static {
            return None;
        }
        let function = self.methods.get(&(
            declaring_class_id,
            resolved_method_name.to_ascii_lowercase(),
        ))?;
        self.no_discard_warning_target_for_function(
            function.as_ref(),
            "method",
            format!("{declaring_class_name}::{resolved_method_name}"),
        )
    }

    fn execute_file_include(
        &mut self,
        path: &Expr,
        once: bool,
        required: bool,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let (flow, _) = self.evaluate_file_include(path, once, required, span, scope)?;
        match flow {
            Flow::Normal | Flow::Return(_) => Ok(Flow::Normal),
            Flow::Exit(code) => Ok(Flow::Exit(code)),
            Flow::Break { depth, span } => Ok(Flow::Break { depth, span }),
            Flow::Continue { depth, span } => Ok(Flow::Continue { depth, span }),
            Flow::Throw { object, span } => Ok(Flow::Throw { object, span }),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn evaluate_file_include(
        &mut self,
        path: &Expr,
        once: bool,
        required: bool,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Flow, Value)> {
        let construct = if required {
            if once {
                "require_once"
            } else {
                "require"
            }
        } else if once {
            "include_once"
        } else {
            "include"
        };
        let path_value = self.evaluate(path, scope)?;
        let Value::String(path_value) = path_value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    construct,
                    "path must evaluate to a string in the current subset",
                ),
            ));
        };

        self.evaluate_file_include_path(&path_value, once, required, construct, span, scope)
    }

    fn evaluate_file_include_path(
        &mut self,
        path_value: &str,
        once: bool,
        required: bool,
        construct: &'static str,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Flow, Value)> {
        let path = self.resolve_required_path(path_value, construct, span)?;
        if self.trace_includes {
            eprintln!("phpc trace include: {}", path.source_file.display());
        }
        let include_key =
            fs::canonicalize(&path.read_path).unwrap_or_else(|_| path.read_path.clone());
        if once && self.required_once.contains(&include_key) {
            return Ok((Flow::Normal, Value::Bool(true)));
        }

        let source = match fs::read_to_string(&path.read_path) {
            Ok(source) => source,
            Err(error) => {
                self.emit_warning(
                    &format!("{construct}()"),
                    format!(
                        "{construct}({}): Failed to open stream: {error}",
                        path.source_file.display()
                    ),
                    span,
                )?;
                self.emit_warning(
                    &format!("{construct}()"),
                    format!(
                        "{construct}(): Failed opening '{}' for inclusion (include_path='{}')",
                        path.source_file.display(),
                        self.include_path
                    ),
                    span,
                )?;
                if required {
                    self.emit_required_file_fatal(construct, &path.source_file, span);
                    self.exit_signal = Some(255);
                    return Ok((Flow::Exit(255), Value::Null));
                }
                return Ok((Flow::Normal, Value::Bool(false)));
            }
        };
        self.cache_bounded_realpath_entry_for_local_path(&path.read_path);
        let program = parse_source(&source).map_err(|error| error.with_file(&path.source_file))?;
        self.required_once.insert(include_key);
        let included_file = path.source_file.display().to_string();
        if !self
            .included_files
            .iter()
            .any(|file| file == &included_file)
        {
            self.included_files.push(included_file.clone());
        }

        let previous_source_file = self.source_file.clone();
        self.source_file = Some(included_file);
        let flow = (|| {
            self.emit_deprecated_dollar_brace_interpolation_diagnostics(&program)?;
            self.register_included_declarations(&program)?;
            self.with_strict_types_scope(program.strict_types, |this| {
                this.execute_statements(&program.statements, scope)
            })
        })();
        self.source_file = previous_source_file;

        match flow? {
            Flow::Normal => Ok((Flow::Normal, Value::Int(1))),
            Flow::Return(value) => Ok((Flow::Normal, value)),
            Flow::Exit(code) => Ok((Flow::Exit(code), Value::Null)),
            Flow::Break { depth, span } => Ok((Flow::Break { depth, span }, Value::Null)),
            Flow::Continue { depth, span } => Ok((Flow::Continue { depth, span }, Value::Null)),
            Flow::Throw { object, span } => Ok((Flow::Throw { object, span }, Value::Null)),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn emit_required_file_fatal(&mut self, construct: &str, path: &Path, span: Span) {
        let file = self
            .source_file
            .clone()
            .unwrap_or_else(|| "Command line code".to_string());
        if !self.stderr.is_empty() {
            self.stderr.push('\n');
        }
        self.stderr.push_str(&format!(
            "PHP Fatal error:  {construct}(): Failed opening required '{}' (include_path='{}') in {file} on line {}",
            path.display(),
            self.include_path,
            span.line
        ));
    }

    fn resolve_file_get_contents_path(&self, path: &str, use_include_path: bool) -> PathBuf {
        let path = PathBuf::from(path);
        if path.is_absolute() || !use_include_path {
            return local_filesystem_metadata_path(path.to_string_lossy().as_ref());
        }

        let source_base = self
            .source_file
            .as_deref()
            .and_then(|source_file| Path::new(source_file).parent())
            .filter(|parent| !parent.as_os_str().is_empty())
            .unwrap_or_else(|| Path::new("."));
        let source_relative_path = source_base.join(&path);
        if let Some(candidate) = self.first_existing_include_candidate(&source_relative_path, &path)
        {
            return candidate.read_path;
        }

        local_filesystem_metadata_path(path.to_string_lossy().as_ref())
    }

    fn included_files_array(&self) -> PhpArray {
        let mut files = Vec::new();
        if let Some(main) = &self.main_source_file {
            files.push(main.clone());
        }
        for included in &self.included_files {
            if !files.iter().any(|file| file == included) {
                files.push(included.clone());
            }
        }

        let mut array = PhpArray::new();
        for (index, file) in files.into_iter().enumerate() {
            array.insert(index as i64, Value::String(file));
        }
        array
    }

    fn enforce_bounded_open_basedir(
        &mut self,
        function: &str,
        display_path: &str,
        filesystem_path: &Path,
        span: Span,
    ) -> CompileResult<bool> {
        if self.path_allowed_by_bounded_open_basedir(filesystem_path) {
            return Ok(true);
        }

        let allowed_paths = self.ini_value("open_basedir").unwrap_or_default();
        self.emit_display_warning(
            format!(
                "{function}: open_basedir restriction in effect. File({display_path}) is not within the allowed path(s): ({allowed_paths})"
            ),
            span,
        )?;
        Ok(false)
    }

    fn enforce_bounded_open_basedir_for_local_display_path(
        &mut self,
        function: &str,
        display_path: &str,
        span: Span,
    ) -> CompileResult<bool> {
        let filesystem_path = local_open_basedir_check_path(display_path);
        self.enforce_bounded_open_basedir(function, display_path, &filesystem_path, span)
    }

    fn emit_stream_open_denied_after_open_basedir(
        &mut self,
        function: &str,
        path: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(
            format!("{function}({path}): Failed to open stream: Operation not permitted"),
            span,
        )
    }

    fn emit_directory_open_denied_after_open_basedir(
        &mut self,
        function: &str,
        path: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(
            format!("{function}({path}): Failed to open directory: Operation not permitted"),
            span,
        )
    }

    fn emit_scandir_denied_after_open_basedir(
        &mut self,
        path: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_directory_open_denied_after_open_basedir("scandir", path, span)?;
        self.emit_display_warning("scandir(): (errno 1): Operation not permitted", span)
    }

    fn path_allowed_by_bounded_open_basedir(&self, filesystem_path: &Path) -> bool {
        let Some(value) = self.ini_value("open_basedir") else {
            return true;
        };
        if value.is_empty() {
            return true;
        }

        let candidate = open_basedir_check_path(filesystem_path);
        value
            .split(INCLUDE_PATH_SEPARATOR)
            .filter(|entry| !entry.is_empty())
            .map(PathBuf::from)
            .map(|entry| open_basedir_check_path(&entry))
            .any(|base| candidate.starts_with(base))
    }

    fn clear_stat_cache_path(&mut self, path: &str) {
        let metadata_path = local_filesystem_metadata_path(path);
        self.stat_cache.remove(&metadata_path);
    }

    fn cache_realpath_entry(&mut self, resolved: String, metadata: &fs::Metadata) {
        self.realpath_cache.insert(
            resolved.clone(),
            RealpathCacheEntry {
                realpath: resolved,
                is_dir: metadata.is_dir(),
                expires: self.request_time.saturating_add(120),
            },
        );
    }

    fn bounded_realpath_entry_for_local_path(
        &self,
        filesystem_path: &Path,
    ) -> Option<(String, fs::Metadata)> {
        let metadata = fs::metadata(filesystem_path).ok()?;
        let resolved = fs::canonicalize(filesystem_path).ok()?;
        let resolved = resolved.into_os_string().into_string().ok()?;
        Some((resolved, metadata))
    }

    fn cache_bounded_realpath_entry_for_local_path(&mut self, filesystem_path: &Path) {
        if let Some((resolved, metadata)) =
            self.bounded_realpath_entry_for_local_path(filesystem_path)
        {
            self.cache_realpath_entry(resolved, &metadata);
        }
    }

    fn seed_main_source_directory_realpath_cache(&mut self) {
        let Some(source_file) = self.main_source_file.as_deref() else {
            return;
        };
        let source_path = local_filesystem_metadata_path(source_file);
        if fs::metadata(&source_path).is_err() {
            return;
        }
        let Some(parent) = source_path.parent() else {
            return;
        };
        let directory = if parent.as_os_str().is_empty() {
            PathBuf::from(".")
        } else {
            parent.to_path_buf()
        };
        self.cache_bounded_realpath_entry_for_local_path(&directory);
    }

    fn realpath_cache_array(&self) -> PhpArray {
        let mut cache = PhpArray::new();
        let mut keys = self.realpath_cache.keys().cloned().collect::<Vec<_>>();
        keys.sort();
        for key in keys {
            let Some(entry) = self.realpath_cache.get(&key) else {
                continue;
            };
            let mut value = PhpArray::new();
            value.insert("key", Value::Int(0));
            value.insert("is_dir", Value::Bool(entry.is_dir));
            value.insert("realpath", Value::String(entry.realpath.clone()));
            value.insert("expires", Value::Int(entry.expires));
            cache.insert(key, Value::Array(value));
        }
        cache
    }

    fn realpath_cache_size(&self) -> i64 {
        self.realpath_cache
            .values()
            .map(|entry| {
                let path_len = entry.realpath.len() as i64;
                path_len.saturating_mul(2).saturating_add(80)
            })
            .sum()
    }

    fn resolve_required_path(
        &self,
        path: &str,
        construct: &'static str,
        span: Span,
    ) -> CompileResult<ResolvedRequirePath> {
        if let Some(file_url_path) = bounded_local_file_url_path(path) {
            let read_path = file_url_path.map_err(|message| {
                runtime_error(span, RuntimeError::unsupported_call(construct, message))
            })?;
            return Ok(ResolvedRequirePath {
                read_path: read_path.clone(),
                source_file: read_path,
            });
        }

        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    construct,
                    "stream and URL require paths other than bounded local file:// URLs are not implemented",
                ),
            ));
        }

        let path = PathBuf::from(path);
        if path.is_absolute() {
            return Ok(ResolvedRequirePath {
                read_path: path.clone(),
                source_file: path,
            });
        }

        let base = self
            .source_file
            .as_deref()
            .and_then(|source_file| {
                let parent = Path::new(source_file).parent()?;
                if parent.as_os_str().is_empty() {
                    None
                } else {
                    Some(parent.to_path_buf())
                }
            })
            .unwrap_or_else(|| PathBuf::from("."));
        let source_file = base.join(&path);
        if let Some(resolved) = self.first_existing_include_candidate(&source_file, &path) {
            return Ok(resolved);
        }

        let read_path = repo_root_relative_path(&source_file).unwrap_or_else(|| {
            // Rust fixture tests run from the crate directory while committed
            // source-map snapshots use repo-relative fixture paths.
            source_file.clone()
        });
        Ok(ResolvedRequirePath {
            read_path,
            source_file,
        })
    }

    fn first_existing_include_candidate(
        &self,
        source_relative_path: &Path,
        requested_path: &Path,
    ) -> Option<ResolvedRequirePath> {
        for candidate in
            include_path_candidates(source_relative_path, requested_path, &self.include_path)
        {
            if candidate.exists() {
                return Some(ResolvedRequirePath {
                    read_path: candidate.clone(),
                    source_file: candidate,
                });
            }
            if let Some(repo_candidate) = repo_root_relative_path(&candidate) {
                if repo_candidate.exists() {
                    return Some(ResolvedRequirePath {
                        read_path: repo_candidate,
                        source_file: candidate,
                    });
                }
            }
        }

        None
    }

    fn execute_switch(
        &mut self,
        value: &Expr,
        cases: &[SwitchCase],
        scope: &mut SymbolTable,
    ) -> CompileResult<Flow> {
        let switch_value = self.evaluate(value, scope)?;
        let mut default_index = None;
        let mut matched_index = None;

        for (index, case) in cases.iter().enumerate() {
            let Some(condition) = &case.condition else {
                if default_index.is_none() {
                    default_index = Some(index);
                }
                continue;
            };

            let case_value = self.evaluate(condition, scope)?;
            let matched = switch_value
                .php_cmp_checked(&case_value, Comparison::Eq)
                .map_err(|error| runtime_error(condition.span(), error))?;
            if matched {
                matched_index = Some(index);
                break;
            }
        }

        let Some(mut index) = matched_index.or(default_index) else {
            return Ok(Flow::Normal);
        };

        while index < cases.len() {
            match self.execute_statements(&cases[index].body, scope)? {
                Flow::Normal => {}
                Flow::Break { depth, .. } if depth <= 1 => return Ok(Flow::Normal),
                Flow::Break { depth, span } => {
                    return Ok(Flow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                Flow::Continue { depth, span } if depth <= 1 => {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control(
                            "continue inside switch is not implemented; use break for switch cases in the current subset",
                        ),
                    ));
                }
                Flow::Continue { depth, span } => {
                    return Ok(Flow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (Flow::Return(_)
                | Flow::Goto { .. }
                | Flow::Throw { .. }
                | Flow::Exit(_)) => return Ok(flow),
            }
            index += 1;
        }

        Ok(Flow::Normal)
    }

    fn execute_unset_target(
        &mut self,
        target: &UnsetTarget,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match target {
            UnsetTarget::Variable { name, .. } => {
                let value = scope.unset_static(name);
                self.finalize_released_value(value, scope)?;
                Ok(())
            }
            UnsetTarget::ArrayIndex { name, index, .. } => {
                self.execute_unset_array_index(name, index, span, scope)
            }
            UnsetTarget::NestedArrayIndex { name, indices, .. } => {
                self.execute_unset_nested_array_index(name, indices, span, scope)
            }
            UnsetTarget::ObjectProperty {
                object, property, ..
            } => self.execute_unset_object_property(object, property, span, scope, true),
            UnsetTarget::DynamicObjectProperty {
                object, property, ..
            } => self.execute_unset_dynamic_object_property(object, property, span, scope),
            UnsetTarget::NonDirectObjectProperty {
                holder, property, ..
            } => self.execute_unset_non_direct_object_property(holder, property, span, scope),
            UnsetTarget::NonDirectDynamicObjectProperty {
                holder, property, ..
            } => {
                self.execute_unset_non_direct_dynamic_object_property(holder, property, span, scope)
            }
            UnsetTarget::ObjectPropertyArrayIndex {
                object,
                property,
                indices,
                ..
            } => self.execute_unset_object_property_nested_array_index(
                object, property, indices, span, scope,
            ),
            UnsetTarget::DynamicObjectPropertyArrayIndex {
                object,
                property,
                indices,
                ..
            } => self.execute_unset_dynamic_object_property_nested_array_index(
                object, property, indices, span, scope,
            ),
            UnsetTarget::NonDirectObjectPropertyArrayIndex {
                holder,
                property,
                indices,
                ..
            } => self.execute_unset_non_direct_object_property_nested_array_index(
                holder, property, indices, span, scope,
            ),
            UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
                holder,
                property,
                indices,
                ..
            } => self.execute_unset_non_direct_dynamic_object_property_nested_array_index(
                holder, property, indices, span, scope,
            ),
            UnsetTarget::StaticPropertyArrayIndex { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "unset",
                    "static-property array-offset targets are not implemented in the interpreter",
                ),
            )),
            UnsetTarget::ObjectStaticProperty {
                target, property, ..
            } => self.execute_unset_object_static_property(target, property, span, scope),
            UnsetTarget::StaticProperty {
                class_name,
                property,
                ..
            } => self.execute_unset_named_static_property(class_name, property, span),
            UnsetTarget::SelfStaticProperty { property, .. } => {
                self.execute_unset_self_static_property(property, span)
            }
            UnsetTarget::ParentStaticProperty { property, .. } => {
                self.execute_unset_parent_static_property(property, span)
            }
            UnsetTarget::LateStaticProperty { property, .. } => {
                self.execute_unset_late_static_property(property, span)
            }
        }
    }

    fn execute_unset_object_property(
        &mut self,
        object_name: &str,
        property: &str,
        span: Span,
        scope: &mut SymbolTable,
        call_magic_on_missing: bool,
    ) -> CompileResult<()> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot unset property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let alias_fallbacks =
            scope.public_object_property_root_alias_fallbacks(object_name, property);
        let boundary = scope.object_property_holder_storage_boundary(
            object_name,
            &object,
            property,
            &[],
            current_class_id,
            &protected_class_ids,
        );
        scope.pre_replace_holder_storage(&boundary);
        if self.array_object_property_should_use_storage(
            &object,
            property,
            current_class_id,
            &protected_class_ids,
            span,
        )? {
            self.array_object_unset_property_from_storage(&object, property, span)?;
            scope.post_replace_holder_storage(&boundary);
            return Ok(());
        }
        let found = object
            .unset_property_from_context(property, current_class_id, &protected_class_ids)
            .map_err(|error| runtime_error(span, error))?;
        if found {
            scope.post_replace_holder_storage(&boundary);
            scope.remove_public_object_property_root_from_array_offset_aliases(
                object_name,
                property,
                &alias_fallbacks,
            );
            self.mark_dateinterval_state_property_dirty(&object, property);
        } else {
            if call_magic_on_missing {
                self.call_magic_property_method_with_caller_scope(
                    object, "__unset", property, span, scope,
                )?;
            }
        }
        Ok(())
    }

    fn execute_unset_dynamic_object_property(
        &mut self,
        object_name: &str,
        property: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
        self.execute_unset_object_property(object_name, &property_name, span, scope, true)
    }

    fn execute_unset_non_direct_object_property(
        &mut self,
        holder: &Expr,
        property: &str,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let temp_name = self.non_direct_object_holder_temp(holder, property, scope, span)?;
        self.execute_unset_object_property(&temp_name, property, span, scope, true)
    }

    fn execute_unset_non_direct_dynamic_object_property(
        &mut self,
        holder: &Expr,
        property: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
        let temp_name = self.non_direct_object_holder_temp(holder, &property_name, scope, span)?;
        self.execute_unset_object_property(&temp_name, &property_name, span, scope, true)
    }

    fn execute_unset_dynamic_object_property_nested_array_index(
        &mut self,
        object_name: &str,
        property: &Expr,
        indices: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
        self.execute_unset_object_property_nested_array_index(
            object_name,
            &property_name,
            indices,
            span,
            scope,
        )
    }

    fn execute_unset_non_direct_object_property_nested_array_index(
        &mut self,
        holder: &Expr,
        property: &str,
        indices: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let temp_name = self.non_direct_object_holder_temp(holder, property, scope, span)?;
        self.execute_unset_object_property_nested_array_index(
            &temp_name, property, indices, span, scope,
        )
    }

    fn execute_unset_non_direct_dynamic_object_property_nested_array_index(
        &mut self,
        holder: &Expr,
        property: &Expr,
        indices: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let property_name = self.evaluate_dynamic_property_name(property, span, scope)?;
        let temp_name = self.non_direct_object_holder_temp(holder, &property_name, scope, span)?;
        self.execute_unset_object_property_nested_array_index(
            &temp_name,
            &property_name,
            indices,
            span,
            scope,
        )
    }

    fn execute_unset_array_index(
        &mut self,
        name: &str,
        index: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        if let Some(Value::Object(object)) = scope.read_named(name) {
            if self.is_spl_object_storage_object(&object) {
                let offset_arg = self.evaluate(index, scope)?;
                if self
                    .resolve_instance_method(object.class_id(), "offsetUnset")
                    .is_some_and(|(class_id, _, _, _, _)| {
                        self.resolved_method_is_core_spl_object_storage(class_id)
                    })
                {
                    self.call_spl_object_storage_offset_unset_array_syntax_with_values(
                        object,
                        vec![offset_arg],
                        span,
                    )?;
                } else {
                    self.call_array_access_method_with_caller_scope(
                        object,
                        "offsetUnset",
                        vec![offset_arg],
                        span,
                        scope,
                    )?;
                }
                return Ok(());
            }
        }
        let key = self.evaluate_array_key(index, scope)?;
        if name == "GLOBALS" {
            let Some(global_name) = globals_offset_name(&key) else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "$GLOBALS",
                        "only string-keyed direct offset unsets are implemented",
                    ),
                ));
            };
            scope.unset_global_name(global_name);
            return Ok(());
        }
        let foreach_detach = self
            .active_foreach_references
            .iter()
            .rev()
            .find(|active| {
                active.root
                    == (ForeachArrayRoot::Static {
                        name: name.to_string(),
                        keys: Vec::new(),
                    })
                    && active.key == key
            })
            .and_then(|active| {
                scope
                    .is_static_bound_to_array_offset(&active.value_name, name, &key)
                    .then(|| {
                        scope
                            .read_named(&active.value_name)
                            .map(|value| (active.value_name.clone(), value))
                    })
                    .flatten()
            });

        match scope.read_named(name) {
            Some(Value::Array(mut array)) => {
                let unset_paths =
                    scope.unset_paths_for_array_root(name, std::slice::from_ref(&key));
                scope.detach_array_offset_aliases_for_unset_paths(&unset_paths);
                array.remove(key.clone());
                scope.write_static(name, Value::Array(array));
                if let Some((value_name, value)) = foreach_detach {
                    scope.bind_static_to_cell(&value_name, value_cell(value));
                }
                Ok(())
            }
            Some(Value::Object(object)) => {
                self.call_array_access_method_with_caller_scope(
                    object,
                    "offsetUnset",
                    vec![Self::array_key_value(Some(key))],
                    span,
                    scope,
                )?;
                Ok(())
            }
            Some(Value::Null) | None => Ok(()),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_unset_nested_array_index(
        &mut self,
        name: &str,
        indices: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, scope))
            .collect::<CompileResult<Vec<_>>>()?;

        if name == "GLOBALS" {
            let (global_name, nested_keys) = SymbolTable::split_globals_reference_path(keys, span)?;
            if nested_keys.is_empty() {
                scope.unset_global_name(&global_name);
                return Ok(());
            }
            match scope.read_global_name(&global_name) {
                Some(Value::Array(mut array)) => {
                    let unset_path = ArrayOffsetAlias {
                        root: ArrayOffsetAliasRoot::GlobalArray {
                            name: global_name.clone(),
                        },
                        keys: nested_keys.clone(),
                    };
                    scope.detach_array_offset_aliases_for_unset_paths(&[unset_path]);
                    Self::unset_nested_array_value(&mut array, &nested_keys, span)?;
                    scope.write_global_name(&global_name, Value::Array(array));
                    Ok(())
                }
                Some(Value::Object(object))
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.execute_unset_array_access_path(object, &nested_keys, span, scope)
                }
                Some(Value::Null) | None => Ok(()),
                Some(other) => Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot unset offset on {}",
                        other.type_name()
                    )),
                )),
            }?;
            return Ok(());
        }

        match scope.read_named(name) {
            Some(Value::Array(mut array)) => {
                let unset_paths = scope.unset_paths_for_array_root(name, &keys);
                scope.detach_array_offset_aliases_for_unset_paths(&unset_paths);
                Self::unset_nested_array_value(&mut array, &keys, span)?;
                scope.write_static(name, Value::Array(array));
                Ok(())
            }
            Some(Value::Object(object))
                if self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess") =>
            {
                self.execute_unset_array_access_path(object, &keys, span, scope)
            }
            Some(Value::Null) | None => Ok(()),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn unset_nested_array_value(
        array: &mut PhpArray,
        keys: &[ArrayKey],
        span: Span,
    ) -> CompileResult<()> {
        let Some((key, rest)) = keys.split_first() else {
            return Ok(());
        };

        if rest.is_empty() {
            array.remove(key.clone());
            return Ok(());
        }

        let mut child = match array.get_cloned(key.clone()) {
            Some(Value::Array(child)) => child,
            Some(Value::Null) | None => return Ok(()),
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot unset offset on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        Self::unset_nested_array_value(&mut child, rest, span)?;
        array.insert(key.clone(), Value::Array(child));
        Ok(())
    }

    fn execute_unset_object_property_nested_array_index(
        &mut self,
        object_name: &str,
        property: &str,
        indices: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot unset property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let Some(mut slot) = object
            .read_property_for_isset_from_context(property, current_class_id, &protected_class_ids)
            .map_err(|error| runtime_error(span, error))?
        else {
            return self.execute_unset_magic_get_array_index(object, property, &keys, span, scope);
        };

        match &mut slot {
            Value::Array(array) => {
                let unset_paths = vec![
                    ArrayOffsetAlias {
                        root: ArrayOffsetAliasRoot::PublicObjectProperty {
                            object: object_name.to_string(),
                            property: property.to_string(),
                        },
                        keys: keys.clone(),
                    },
                    ArrayOffsetAlias {
                        root: ArrayOffsetAliasRoot::ContextObjectProperty {
                            object: object_name.to_string(),
                            property: property.to_string(),
                            current_class_id,
                            protected_class_ids: protected_class_ids.clone(),
                        },
                        keys: keys.clone(),
                    },
                ];
                let boundary = scope.object_property_holder_storage_boundary(
                    object_name,
                    &object,
                    property,
                    &keys,
                    current_class_id,
                    &protected_class_ids,
                );
                scope.pre_replace_holder_storage(&boundary);
                scope.detach_array_offset_aliases_for_unset_paths(&unset_paths);
                Self::unset_nested_array_value(array, &keys, span)?;
                object
                    .write_property_from_context(
                        property,
                        slot,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                scope.post_replace_holder_storage(&boundary);
                scope.sync_array_offset_aliases_for_object_property_root(object_name, property);
                Ok(())
            }
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess") =>
            {
                self.execute_unset_array_access_path(object.clone(), &keys, span, scope)
            }
            Value::Null => Ok(()),
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_unset_magic_get_array_index(
        &mut self,
        object: PhpObject,
        property: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), "__get")
        else {
            return Ok(());
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::__get()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, "__get", visibility, span)?;

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity(function, 1, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        if function.returns_by_reference {
            ensure_supported_reference_return_function_metadata(function, span)?;
            let Some(cell) =
                self.call_magic_get_reference_return_cell(object, property, span, scope)?
            else {
                return Ok(());
            };
            match cell.value_cloned() {
                Value::Object(object)
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.execute_unset_array_access_path(object, keys, span, scope)
                }
                Value::Array(_) | Value::Null => {
                    let temp_name = self.next_foreach_temporary_array_name();
                    scope.bind_static_to_cell(&temp_name, cell);
                    self.execute_unset_static_array_keys(&temp_name, keys, span, scope)
                }
                _ => Ok(()),
            }
        } else {
            ensure_supported_magic_array_access_function_signature(function, 1, span)?;
            let called_class_id = object.class_id();
            let (value, _) = self.call_user_function_with_this_and_array_copy_source(
                function,
                object,
                vec![Value::String(property.to_string())],
                Some(class_id),
                Some(called_class_id),
                scope,
            )?;
            match value {
                Value::Object(object)
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.execute_unset_array_access_path(object, keys, span, scope)
                }
                Value::Array(_) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    Ok(())
                }
                _ => Ok(()),
            }
        }
    }

    fn execute_unset_array_access_path(
        &mut self,
        object: PhpObject,
        keys: &[ArrayKey],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let Some((first_key, rest_keys)) = keys.split_first() else {
            return Ok(());
        };

        let offset_get_returns_by_reference =
            if let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
                self.resolve_instance_method(object.class_id(), "offsetGet")
            {
                if is_static || visibility != Visibility::Public {
                    false
                } else {
                    let function =
                        self.method_function(class_id, &class_name, &resolved_method_name, span)?;
                    function.as_ref().returns_by_reference
                }
            } else {
                false
            };

        if offset_get_returns_by_reference && !rest_keys.is_empty() {
            let hidden_name = self.hidden_array_access_reference_object_name(&object);
            scope.write_static(&hidden_name, Value::Object(object.clone()));
            if let Some(binding) = self.evaluate_array_access_reference_source_binding_for_object(
                object.clone(),
                hidden_name,
                keys.to_vec(),
                None,
                span,
                scope,
            )? {
                match binding {
                    NonDirectReferenceSourceBinding::ArrayOffset(alias) => {
                        return self.execute_unset_array_offset_alias_path(alias, span, scope);
                    }
                    NonDirectReferenceSourceBinding::DetachedValue(_) => return Ok(()),
                }
            }
        }

        if rest_keys.is_empty() {
            self.call_array_access_method_with_caller_scope(
                object,
                "offsetUnset",
                vec![Self::array_key_value(Some(first_key.clone()))],
                span,
                scope,
            )?;
            return Ok(());
        }

        let class_name = object.class_name().to_string();
        let value = self.call_array_access_method_with_caller_scope(
            object,
            "offsetGet",
            vec![Self::array_key_value(Some(first_key.clone()))],
            span,
            scope,
        )?;
        match value {
            Value::Object(object)
                if self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess") =>
            {
                self.execute_unset_array_access_path(object, rest_keys, span, scope)
            }
            Value::Array(_) | Value::Null | Value::Bool(false) => {
                self.emit_array_access_indirect_modification_notice(&class_name, span)?;
                Ok(())
            }
            Value::String(_) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access("cannot unset string offsets".to_string()),
            )),
            Value::Bool(true) | Value::Int(_) | Value::Float(_) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot unset offset in a non-array variable".to_string(),
                ),
            )),
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_unset_array_offset_alias_path(
        &mut self,
        mut alias: ArrayOffsetAlias,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let Some(last_key) = alias.keys.pop() else {
            return Ok(());
        };
        let unset_alias = ArrayOffsetAlias {
            root: alias.root.clone(),
            keys: {
                let mut keys = alias.keys.clone();
                keys.push(last_key.clone());
                keys
            },
        };

        match scope.read_array_offset_alias(&alias) {
            Some(Value::Array(mut array)) => {
                scope.detach_array_offset_aliases_for_unset_paths(&[unset_alias]);
                Self::unset_nested_array_value(&mut array, &[last_key], span)?;
                if !scope.write_array_offset_alias(&alias, Value::Array(array)) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(
                            "cannot unset ArrayAccess reference-return array offset".to_string(),
                        ),
                    ));
                }
                Ok(())
            }
            Some(Value::Null) | None => Ok(()),
            Some(Value::String(_)) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access("cannot unset string offsets".to_string()),
            )),
            Some(Value::Bool(true) | Value::Int(_) | Value::Float(_)) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot unset offset in a non-array variable".to_string(),
                ),
            )),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_unset_static_array_keys(
        &mut self,
        name: &str,
        keys: &[ArrayKey],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match scope.read_named(name) {
            Some(Value::Array(mut array)) => {
                let unset_paths = scope.unset_paths_for_array_root(name, keys);
                scope.detach_array_offset_aliases_for_unset_paths(&unset_paths);
                Self::unset_nested_array_value(&mut array, keys, span)?;
                scope.write_static(name, Value::Array(array));
                Ok(())
            }
            Some(Value::Null) | None => Ok(()),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot unset offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn execute_unset_named_static_property(
        &self,
        class_name: &str,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.classes
            .lookup_class_id(class_name)
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(class_name)))?;
        self.reject_static_property_unset(class_name, property, span)
    }

    fn execute_unset_object_static_property(
        &mut self,
        target: &Expr,
        property: &str,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (_, class_name) =
            self.resolve_dynamic_static_receiver(target, property, span, scope)?;
        self.reject_static_property_unset(&class_name, property, span)
    }

    fn execute_unset_self_static_property(&self, property: &str, span: Span) -> CompileResult<()> {
        let Some(current_class_id) = self.class_context.last().copied() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("self::${property}"),
                    "self static property access requires instance method context",
                ),
            ));
        };

        let class_name = self
            .classes
            .get(current_class_id)
            .expect("active class context should resolve to class metadata")
            .name();
        self.reject_static_property_unset(class_name, property, span)
    }

    fn execute_unset_parent_static_property(
        &self,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        let (parent_class_id, parent_class_name) =
            self.resolve_parent_static_property_context(property, span)?;
        self.classes
            .get(parent_class_id)
            .expect("parent class id should resolve to class metadata");
        self.reject_static_property_unset(&parent_class_name, property, span)
    }

    fn execute_unset_late_static_property(&self, property: &str, span: Span) -> CompileResult<()> {
        let (called_class_id, called_class_name) =
            self.resolve_late_static_property_context(property, span)?;
        self.classes
            .get(called_class_id)
            .expect("called class id should resolve to class metadata");
        self.reject_static_property_unset(&called_class_name, property, span)
    }

    fn reject_static_property_unset(
        &self,
        class_name: &str,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{class_name}::${property}"),
                "static property unset is not supported; assign null to the static property in the current subset",
            ),
        ))
    }

    fn execute_const_declaration(
        &mut self,
        name: &str,
        value: &Expr,
        attributes: &[AttributeDecl],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let has_class_scope =
            !self.class_context.is_empty() || !self.trait_class_context.is_empty();
        if let Some(error) = const_declaration_class_scope_error(value, has_class_scope) {
            return Err(error);
        }
        let value = self.evaluate_constant_like_expr(value, scope)?;
        if let Some(type_name) = unsupported_runtime_constant_value_type(&value) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "const declaration",
                    format!(
                        "value must be null, bool, int, float, string, array, or object values in the current subset, got {type_name}"
                    ),
                ),
            ));
        }
        self.constants
            .define_with_metadata(
                name,
                value,
                RuntimeConstantMetadata {
                    file_name: self.source_file.clone(),
                    attributes: attributes.to_vec(),
                },
            )
            .map_err(|error| runtime_error(span, error))
    }

    fn evaluate(&mut self, expr: &Expr, scope: &mut SymbolTable) -> CompileResult<Value> {
        match expr {
            Expr::Null(_) => Ok(Value::Null),
            Expr::Bool(value, _) => Ok(Value::Bool(*value)),
            Expr::Int(value, _) => Ok(Value::Int(*value)),
            Expr::Float(value, _) => Ok(Value::Float(*value)),
            Expr::String(value, _) => Ok(php_string_literal_value(value)),
            Expr::InterpolatedString { parts, span } => {
                self.evaluate_interpolated_string(parts, *span, scope)
            }
            Expr::Variable(name, span) => {
                if name == "GLOBALS" {
                    return Ok(scope.materialized_globals_array_value());
                }
                if name.eq_ignore_ascii_case("this") && scope.read_named("this").is_none() {
                    return Err(this_not_in_object_context_error(*span));
                }
                match scope.read_named(name) {
                    Some(value) => Ok(value),
                    None => {
                        self.emit_undefined_variable_warning(name, *span)?;
                        Ok(Value::Null)
                    }
                }
            }
            Expr::MagicLine { span } => Ok(Value::Int(span.line as i64)),
            Expr::MagicFile { .. } => {
                Ok(Value::String(self.source_file.clone().unwrap_or_default()))
            }
            Expr::MagicDir { .. } => Ok(Value::String(self.magic_dir_value())),
            Expr::MagicFunction { .. } => Ok(Value::String(
                self.function_context.last().cloned().unwrap_or_default(),
            )),
            Expr::MagicClass { span } => Ok(Value::String(self.magic_class_value(*span)?)),
            Expr::MagicMethod { span } => Ok(Value::String(self.magic_method_value(*span)?)),
            Expr::GlobalConstant { name, span } => self.evaluate_global_constant(name, *span),
            Expr::ClassNameConstant { class_name, .. } => Ok(Value::String(class_name.clone())),
            Expr::SelfClassNameConstant { span } => self.evaluate_self_class_name_constant(*span),
            Expr::ParentClassNameConstant { span } => {
                self.evaluate_parent_class_name_constant(*span)
            }
            Expr::StaticClassNameConstant { span } => {
                self.evaluate_static_class_name_constant(*span)
            }
            Expr::ObjectClassNameConstant { target, span } => {
                let value = self.evaluate(target, scope)?;
                match value {
                    Value::Object(object) => Ok(Value::String(object.class_name().to_string())),
                    Value::String(class_name) => Ok(Value::String(
                        self.classes
                            .lookup_class(&class_name)
                            .map(|class| class.name().to_string())
                            .unwrap_or(class_name),
                    )),
                    Value::BinaryString(class_name) => {
                        let class_name = class_name.strip_prefix(b"\\").unwrap_or(&class_name);
                        Ok(Value::BinaryString(
                            self.classes
                                .lookup_class_bytes(class_name)
                                .map(|class| class.name().as_bytes().to_vec())
                                .unwrap_or_else(|| class_name.to_vec()),
                        ))
                    }
                    Value::Null => Err(Diagnostic::new(
                        Phase::Runtime,
                        span.line,
                        span.column,
                        "Cannot use \"::class\" on null",
                    )),
                    _other if matches!(target.as_ref(), Expr::Int(_, _)) => Err(Diagnostic::new(
                        Phase::Runtime,
                        span.line,
                        span.column,
                        "Illegal class name",
                    )),
                    other => Err(Diagnostic::new(
                        Phase::Runtime,
                        span.line,
                        span.column,
                        format!("Cannot use \"::class\" on {}", other.type_name()),
                    )),
                }
            }
            Expr::ClassConstant {
                class_name,
                constant,
                span,
            } => self.evaluate_named_class_constant(class_name, constant, *span),
            Expr::ObjectStaticClassConstant {
                target,
                constant,
                span,
            } => self.evaluate_object_static_class_constant(target, constant, *span, scope),
            Expr::SelfClassConstant { constant, span } => {
                self.evaluate_self_class_constant(constant, *span)
            }
            Expr::ParentClassConstant { constant, span } => {
                self.evaluate_parent_class_constant(constant, *span)
            }
            Expr::LateStaticClassConstant { constant, span } => {
                self.evaluate_late_static_class_constant(constant, *span)
            }
            Expr::Array { items, span } => self.evaluate_array(items, *span, scope),
            Expr::Index {
                target,
                index,
                span,
            } => self.evaluate_array_index(target, index, *span, scope),
            Expr::AppendIndex { span, .. } => Err(append_offset_read_error(*span)),
            Expr::Property {
                target,
                property,
                span,
            } => self.evaluate_property_read(target, property, *span, scope),
            Expr::DynamicProperty {
                target,
                property,
                span,
            } => self.evaluate_dynamic_property_read(target, property, *span, scope),
            Expr::StaticProperty {
                class_name,
                property,
                span,
            } => self.evaluate_named_static_property(class_name, property, *span),
            Expr::ObjectStaticProperty {
                target,
                property,
                span,
            } => self.evaluate_object_static_property(target, property, *span, scope),
            Expr::SelfStaticProperty { property, span } => {
                self.evaluate_self_static_property(property, *span)
            }
            Expr::ParentStaticProperty { property, span } => {
                self.evaluate_parent_static_property(property, *span)
            }
            Expr::LateStaticProperty { property, span } => {
                self.evaluate_late_static_property(property, *span)
            }
            Expr::DynamicStaticProperty {
                class_name,
                property,
                span,
            } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                self.evaluate_named_static_property(class_name, &property, *span)
            }
            Expr::DynamicObjectStaticProperty {
                target,
                property,
                span,
            } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                self.evaluate_object_static_property(target, &property, *span, scope)
            }
            Expr::DynamicSelfStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                self.evaluate_self_static_property(&property, *span)
            }
            Expr::DynamicParentStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                self.evaluate_parent_static_property(&property, *span)
            }
            Expr::DynamicLateStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                self.evaluate_late_static_property(&property, *span)
            }
            Expr::NamedArgument { span, .. } | Expr::SpreadArgument { span, .. } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call(
                    "source-order call argument",
                    "interpreter call consumers have not been wired to shared source-order call-argument normalization",
                ),
            )),
            Expr::MethodCall {
                target,
                method,
                args,
                span,
            } => self.call_instance_method(target, method, args, *span, scope),
            Expr::DynamicMethodCall {
                target,
                method,
                args,
                span,
            } => self.call_dynamic_instance_method(target, method, args, *span, scope),
            Expr::ParentMethodCall { method, args, span } => {
                self.call_parent_method(method, args, *span, scope)
            }
            Expr::StaticMethodCall {
                class_name,
                method,
                args,
                span,
            } => self.call_named_static_method(class_name, method, args, *span, scope),
            Expr::ObjectStaticMethodCall {
                target,
                method,
                args,
                span,
            } => self.call_object_static_method(target, method, args, *span, scope),
            Expr::SelfMethodCall { method, args, span } => {
                self.call_self_method(method, args, *span, scope)
            }
            Expr::LateStaticMethodCall { method, args, span } => {
                self.call_late_static_method(method, args, *span, scope)
            }
            Expr::Call { name, args, span } => self.call_function(name, args, *span, scope),
            Expr::DynamicCall { callee, args, span } => {
                self.call_dynamic_function(callee, args, *span, scope)
            }
            Expr::InstanceOf {
                expr,
                class_name,
                span,
            } => {
                let value = self.evaluate(expr, scope)?;
                let class_name = self.resolve_instanceof_class_name(class_name, *span, scope)?;
                Ok(Value::Bool(self.value_instanceof(&value, &class_name)))
            }
            Expr::Closure {
                params,
                captures,
                return_type,
                returns_by_reference,
                body,
                attributes,
                is_static,
                span,
                is_arrow,
                ..
            } => self.evaluate_closure_expression(
                params,
                captures,
                return_type.as_ref(),
                *returns_by_reference,
                body,
                attributes,
                *is_static,
                *is_arrow,
                *span,
                scope,
            ),
            Expr::New {
                class_name,
                args,
                span,
            } => self.instantiate_object(class_name, args, *span, scope),
            Expr::Clone { expr, span } => self.evaluate_clone_expression(expr, *span, scope),
            Expr::Unary { op, expr, span } => {
                let value = self.evaluate(expr, scope)?;
                self.apply_unary(*op, value, *span)
            }
            Expr::ErrorControl { expr, .. } => {
                self.with_error_control_suppression(|this| this.evaluate(expr, scope))
            }
            Expr::Include { path, once, span } => {
                let (flow, value) = self.evaluate_file_include(path, *once, false, *span, scope)?;
                match flow {
                    Flow::Normal | Flow::Return(_) => Ok(value),
                    Flow::Exit(_) => Ok(Value::Null),
                    Flow::Break { span, .. } => Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
                    )),
                    Flow::Continue { span, .. } => Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control(
                            "continue cannot be used outside a loop",
                        ),
                    )),
                    Flow::Throw { object, span } => Err(self.uncaught_throw_error(&object, span)),
                    Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
                }
            }
            Expr::Require { path, once, span } => {
                let (flow, value) = self.evaluate_file_include(path, *once, true, *span, scope)?;
                match flow {
                    Flow::Normal | Flow::Return(_) => Ok(value),
                    Flow::Exit(_) => Ok(Value::Null),
                    Flow::Break { span, .. } => Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
                    )),
                    Flow::Continue { span, .. } => Err(runtime_error(
                        span,
                        RuntimeError::invalid_loop_control(
                            "continue cannot be used outside a loop",
                        ),
                    )),
                    Flow::Throw { object, span } => Err(self.uncaught_throw_error(&object, span)),
                    Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
                }
            }
            Expr::Cast { kind, expr, span } => {
                let value = self.evaluate(expr, scope)?;
                self.apply_cast(*kind, value, *span)
            }
            Expr::Ternary {
                condition,
                if_true,
                if_false,
                ..
            } => {
                if self.evaluate(condition, scope)?.is_truthy() {
                    self.evaluate(if_true, scope)
                } else {
                    self.evaluate(if_false, scope)
                }
            }
            Expr::ShortTernary {
                condition,
                if_false,
                ..
            } => {
                let condition_value = self.evaluate(condition, scope)?;
                if condition_value.is_truthy() {
                    Ok(condition_value)
                } else {
                    self.evaluate(if_false, scope)
                }
            }
            Expr::Match {
                subject,
                arms,
                span,
            } => self.evaluate_match_expression(subject, arms, *span, scope),
            Expr::Assign { target, expr, .. } => self.evaluate_assignment(target, expr, scope),
            Expr::CompoundAssign {
                target,
                op,
                expr,
                span,
            } => self.evaluate_compound_assignment(target, *op, expr, *span, scope),
            Expr::NullCoalesceAssign { target, expr, .. } => {
                self.evaluate_null_coalesce_assignment(target, expr, scope)
            }
            Expr::IncrementDecrement {
                target,
                op,
                position,
                span,
            } => self.evaluate_increment_decrement(target, *op, *position, *span, scope),
            Expr::Binary {
                left,
                op,
                right,
                span,
            } => {
                if matches!(op, BinaryOp::NullCoalesce) {
                    return self.evaluate_null_coalescing(left, right, *span, scope);
                }
                if matches!(op, BinaryOp::LogicalAnd) {
                    let left = self.evaluate(left, scope)?;
                    if !left.is_truthy() {
                        return Ok(Value::Bool(false));
                    }
                    return Ok(Value::Bool(self.evaluate(right, scope)?.is_truthy()));
                }
                if matches!(op, BinaryOp::LogicalOr) {
                    let left = self.evaluate(left, scope)?;
                    if left.is_truthy() {
                        return Ok(Value::Bool(true));
                    }
                    return Ok(Value::Bool(self.evaluate(right, scope)?.is_truthy()));
                }
                if matches!(op, BinaryOp::LogicalXor) {
                    let left = self.evaluate(left, scope)?.is_truthy();
                    let right = self.evaluate(right, scope)?.is_truthy();
                    return Ok(Value::Bool(left ^ right));
                }
                let (left, right) =
                    if Self::binary_rhs_assignment_mutates_left_variable(left, right) {
                        let right = self.evaluate(right, scope)?;
                        let left = self.evaluate(left, scope)?;
                        (left, right)
                    } else {
                        let left = self.evaluate(left, scope)?;
                        let right = self.evaluate(right, scope)?;
                        (left, right)
                    };
                self.apply_binary(*op, left, right, *span, scope)
            }
        }
    }

    fn evaluate_match_expression(
        &mut self,
        subject: &Expr,
        arms: &[MatchArm],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let subject_value = self.evaluate(subject, scope)?;
        let mut default_result = None;

        for arm in arms {
            if arm.conditions.is_empty() {
                default_result = Some(&arm.result);
                continue;
            }

            for condition in &arm.conditions {
                let condition_value = self.evaluate(condition, scope)?;
                let matches = subject_value
                    .php_identical_checked(&condition_value)
                    .map_err(|error| runtime_error(arm.span, error))?;
                if matches {
                    return self.evaluate(&arm.result, scope);
                }
            }
        }

        if let Some(result) = default_result {
            return self.evaluate(result, scope);
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "match",
                "Unhandled match case is not implemented in the current subset",
            ),
        ))
    }

    fn binary_rhs_assignment_mutates_left_variable(left: &Expr, right: &Expr) -> bool {
        let Expr::Variable(name, _) = left else {
            return false;
        };

        Self::expr_assigns_to_direct_variable(right, name)
    }

    fn expr_assigns_to_direct_variable(expr: &Expr, name: &str) -> bool {
        match expr {
            Expr::Assign { target, expr, .. }
            | Expr::CompoundAssign { target, expr, .. }
            | Expr::NullCoalesceAssign { target, expr, .. } => {
                Self::assign_target_mutates_direct_variable(target, name)
                    || Self::expr_assigns_to_direct_variable(expr, name)
            }
            Expr::Binary { left, right, .. } => {
                Self::expr_assigns_to_direct_variable(left, name)
                    || Self::expr_assigns_to_direct_variable(right, name)
            }
            Expr::Unary { expr, .. }
            | Expr::ErrorControl { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Include { path: expr, .. }
            | Expr::Require { path: expr, .. }
            | Expr::NamedArgument { expr, .. }
            | Expr::SpreadArgument { expr, .. }
            | Expr::Clone { expr, .. }
            | Expr::AppendIndex { target: expr, .. } => {
                Self::expr_assigns_to_direct_variable(expr, name)
            }
            Expr::Index { target, index, .. } => {
                Self::expr_assigns_to_direct_variable(target, name)
                    || Self::expr_assigns_to_direct_variable(index, name)
            }
            Expr::Property { target, .. }
            | Expr::MethodCall { target, .. }
            | Expr::DynamicCall { callee: target, .. }
            | Expr::ObjectStaticProperty { target, .. }
            | Expr::ObjectStaticClassConstant { target, .. }
            | Expr::ObjectClassNameConstant { target, .. } => {
                Self::expr_assigns_to_direct_variable(target, name)
            }
            Expr::DynamicProperty {
                target, property, ..
            }
            | Expr::DynamicObjectStaticProperty {
                target, property, ..
            } => {
                Self::expr_assigns_to_direct_variable(target, name)
                    || Self::expr_assigns_to_direct_variable(property, name)
            }
            Expr::DynamicMethodCall {
                target,
                method,
                args,
                ..
            } => {
                Self::expr_assigns_to_direct_variable(target, name)
                    || Self::expr_assigns_to_direct_variable(method, name)
                    || args
                        .iter()
                        .any(|arg| Self::expr_assigns_to_direct_variable(arg, name))
            }
            Expr::Call { args, .. }
            | Expr::ParentMethodCall { args, .. }
            | Expr::StaticMethodCall { args, .. }
            | Expr::SelfMethodCall { args, .. }
            | Expr::LateStaticMethodCall { args, .. }
            | Expr::New { args, .. } => args
                .iter()
                .any(|arg| Self::expr_assigns_to_direct_variable(arg, name)),
            Expr::ObjectStaticMethodCall { target, args, .. } => {
                Self::expr_assigns_to_direct_variable(target, name)
                    || args
                        .iter()
                        .any(|arg| Self::expr_assigns_to_direct_variable(arg, name))
            }
            Expr::Array { items, .. } => items.iter().any(|item| {
                item.key
                    .as_ref()
                    .is_some_and(|key| Self::expr_assigns_to_direct_variable(key, name))
                    || Self::expr_assigns_to_direct_variable(&item.value, name)
            }),
            Expr::Ternary {
                condition,
                if_true,
                if_false,
                ..
            } => {
                Self::expr_assigns_to_direct_variable(condition, name)
                    || Self::expr_assigns_to_direct_variable(if_true, name)
                    || Self::expr_assigns_to_direct_variable(if_false, name)
            }
            Expr::ShortTernary {
                condition,
                if_false,
                ..
            } => {
                Self::expr_assigns_to_direct_variable(condition, name)
                    || Self::expr_assigns_to_direct_variable(if_false, name)
            }
            Expr::Match { subject, arms, .. } => {
                Self::expr_assigns_to_direct_variable(subject, name)
                    || arms.iter().any(|arm| {
                        arm.conditions
                            .iter()
                            .any(|condition| Self::expr_assigns_to_direct_variable(condition, name))
                            || Self::expr_assigns_to_direct_variable(&arm.result, name)
                    })
            }
            Expr::InstanceOf {
                expr, class_name, ..
            } => {
                Self::expr_assigns_to_direct_variable(expr, name)
                    || Self::new_class_name_assigns_to_direct_variable(class_name, name)
            }
            Expr::Closure { params, .. } => params
                .iter()
                .filter_map(|param| param.default.as_ref())
                .any(|default| Self::expr_assigns_to_direct_variable(default, name)),
            Expr::IncrementDecrement { target, .. } => {
                Self::assign_target_mutates_direct_variable(target, name)
            }
            _ => false,
        }
    }

    fn new_class_name_assigns_to_direct_variable(class_name: &NewClassName, name: &str) -> bool {
        match class_name {
            NewClassName::DynamicExpression(expr) => {
                Self::expr_assigns_to_direct_variable(expr, name)
            }
            NewClassName::Named(_)
            | NewClassName::DynamicVariable(_)
            | NewClassName::SelfClass
            | NewClassName::ParentClass
            | NewClassName::StaticClass => false,
        }
    }

    fn assign_target_mutates_direct_variable(target: &AssignTarget, name: &str) -> bool {
        matches!(
            target,
            AssignTarget::Variable { name: target, .. }
                | AssignTarget::ArrayIndex { name: target, .. }
                | AssignTarget::NestedArrayIndex { name: target, .. }
                | AssignTarget::NestedArrayAppend { name: target, .. }
                if target == name
        )
    }

    fn instantiate_object(
        &mut self,
        class_name: &NewClassName,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let class_name = self.resolve_new_class_name(class_name, span, scope)?;
        if self.classes.lookup_class(&class_name).is_none() {
            self.run_autoload_callbacks(&class_name, AutoloadKind::Class, span)?;
        }
        if self.classes.lookup_class(&class_name).is_none() {
            if let Some(interface) = self.interface_lookup.get(&class_name.to_ascii_lowercase()) {
                return Err(Diagnostic::new(
                    Phase::Runtime,
                    span.line,
                    span.column,
                    format!("Cannot instantiate interface {}", interface.name),
                ));
            }
        }
        let (class_id, declared_class_name) = {
            let class = self
                .classes
                .lookup_class(&class_name)
                .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(&class_name)))?;
            (class.id(), class.name().to_string())
        };
        if declared_class_name.eq_ignore_ascii_case("PDO") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    declared_class_name,
                    "PDO connections, drivers, statements, and host database state are not implemented in the current subset",
                ),
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("Directory") {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                "Cannot directly construct Directory, use dir() instead",
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("Attribute") {
            return self.instantiate_core_attribute(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("Deprecated") {
            return self.instantiate_core_deprecated(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("NoDiscard") {
            return self.instantiate_core_no_discard(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("SensitiveParameterValue") {
            return self.instantiate_core_sensitive_parameter_value(args, span, scope);
        }
        if self
            .enum_lookup
            .contains_key(&declared_class_name.to_ascii_lowercase())
        {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    declared_class_name,
                    "enum cases are singleton objects and direct enum construction is not implemented",
                ),
            ));
        }
        if self.abstract_classes.contains(&class_id) {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                format!("Cannot instantiate abstract class {declared_class_name}"),
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("mysqli") {
            return self.instantiate_mysqli(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("mysqli_driver") {
            return self.instantiate_mysqli_driver(args, span);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionClass") {
            return self.instantiate_reflection_class(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionObject") {
            return self.instantiate_reflection_object(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionFunction") {
            return self.instantiate_reflection_function(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionMethod") {
            return self.instantiate_reflection_method(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionParameter") {
            return self.instantiate_reflection_parameter(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionProperty") {
            return self.instantiate_reflection_property(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionClassConstant") {
            return self.instantiate_reflection_class_constant(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionConstant") {
            return self.instantiate_reflection_constant(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionAttribute") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    declared_class_name,
                    "ReflectionAttribute objects are only materialized by supported getAttributes() paths in the current subset",
                ),
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionExtension") {
            return self.instantiate_reflection_extension(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionZendExtension") {
            return self.instantiate_reflection_zend_extension(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("ReflectionType")
            || declared_class_name.eq_ignore_ascii_case("ReflectionNamedType")
            || declared_class_name.eq_ignore_ascii_case("ReflectionUnionType")
            || declared_class_name.eq_ignore_ascii_case("ReflectionIntersectionType")
        {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    declared_class_name,
                    "reflection type objects are only materialized by supported reflection getType() paths in the current subset",
                ),
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("BcMath\\Number") {
            return self.instantiate_bcmath_number(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("HashContext") {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                "Call to private HashContext::__construct() from global scope",
            ));
        }
        if declared_class_name.eq_ignore_ascii_case("Uri\\Rfc3986\\Uri") {
            return self.instantiate_uri_rfc3986(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("Uri\\WhatWg\\Url") {
            return self.instantiate_uri_whatwg_url(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("DOMAttr") {
            return self.instantiate_dom_attr(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("DOMElement") {
            return self.instantiate_dom_element(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("DOMDocument") {
            return self.instantiate_dom_document(args, span, scope);
        }
        if declared_class_name.eq_ignore_ascii_case("DOMDocumentType") {
            return self.instantiate_dom_document_type(args, span, scope);
        }

        let constructor = self.resolve_instance_method(class_id, "__construct");

        let object = self.allocate_object_without_constructor(class_id, span)?;
        let Some((
            constructor_class_id,
            constructor_class_name,
            constructor_name,
            constructor_visibility,
            constructor_is_static,
        )) = constructor
        else {
            if self.is_datetimezone_class_id(class_id) {
                self.initialize_datetimezone_object(&object, args, span, scope)?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if self.is_dateinterval_class_id(class_id) {
                self.initialize_dateinterval_object(&object, args, span, scope)?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if self.is_dateperiod_class_id(class_id) {
                self.initialize_dateperiod_object(&object, args, span, scope)?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if self.is_datetime_class_id(class_id) {
                self.initialize_datetime_object(&object, args, span, scope)?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if self.is_datetimeimmutable_class_id(class_id) {
                self.initialize_datetimeimmutable_object(&object, args, span, scope)?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if self.is_exception_class_or_subclass(class_id) {
                self.initialize_core_exception_object(
                    &object,
                    class_id,
                    &declared_class_name,
                    args,
                    span,
                    scope,
                )?;
                self.track_allocated_object(&object);
                return Ok(Value::Object(object));
            }
            if !args.is_empty() {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_object_instantiation(
                        declared_class_name,
                        "constructor arguments are not implemented",
                    ),
                ));
            }
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        };

        if constructor_is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    declared_class_name,
                    "static constructors are not implemented",
                ),
            ));
        }

        if constructor_name.eq_ignore_ascii_case("__construct")
            && self.resolved_method_is_core_reflection_class(constructor_class_id)
        {
            self.assign_reflection_class_constructor_state_from_exprs(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_php_token(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.initialize_php_token_object(&object, &values, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_array_object(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_array_object_method_with_values(object.clone(), "__construct", values, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_object_storage(constructor_class_id) {
            expect_expr_arity("SplObjectStorage::__construct", args.len(), 0, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_fixed_array(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_fixed_array_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(constructor_class_id) {
            expect_expr_arity("SplDoublyLinkedList::__construct", args.len(), 0, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_file_info(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_file_info_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_file_object(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_file_object_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_directory_iterator(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_directory_iterator_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_filesystem_iterator(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_filesystem_iterator_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_recursive_iterator_iterator_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(constructor_class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.call_spl_iterator_wrapper_method_with_values(
                object.clone(),
                "__construct",
                values,
                span,
            )?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_mysqli(constructor_class_id) {
            if args.len() > 6 {
                return Err(runtime_error(
                    span,
                    RuntimeError::arity_mismatch(
                        "mysqli::__construct()",
                        ArityExpectation::Between { min: 0, max: 6 },
                        args.len(),
                    ),
                ));
            }
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, scope))
                .collect::<CompileResult<Vec<_>>>()?;
            self.validate_mysqli_connect_arguments("mysqli::__construct()", &values, span)?;
            self.initialize_mysqli_placeholder_object(&object, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_datetimezone(constructor_class_id) {
            self.initialize_datetimezone_object(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_dateinterval(constructor_class_id) {
            self.initialize_dateinterval_object(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_dateperiod(constructor_class_id) {
            self.initialize_dateperiod_object(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_datetime(constructor_class_id) {
            self.initialize_datetime_object(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if self.resolved_method_is_core_datetimeimmutable(constructor_class_id) {
            self.initialize_datetimeimmutable_object(&object, args, span, scope)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        if !self.can_call_constructor(constructor_class_id, constructor_visibility) {
            let reason = match constructor_visibility {
                Visibility::Private => format!(
                    "private constructor {}::__construct() requires same-class construction context",
                    constructor_class_name
                ),
                Visibility::Protected => format!(
                    "protected constructor {}::__construct() requires same-class or child-class construction context",
                    constructor_class_name
                ),
                Visibility::Public => unreachable!("public constructors are always callable"),
            };
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(declared_class_name, reason),
            ));
        }

        let function = self.method_function(
            constructor_class_id,
            &constructor_class_name,
            &constructor_name,
            span,
        )?;
        let function = function.as_ref();
        Self::ensure_user_function_expr_arity_unless_spread(function, args, span)?;
        ensure_supported_function_metadata(function, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let (values, reference_bindings) =
            self.evaluate_user_function_call_arguments(function, args, span, scope)?;
        if function_has_promoted_properties(function) {
            let protected_class_ids = self.protected_class_ids_for_context(constructor_class_id);
            for (param, value) in function.params.iter().zip(values.iter()) {
                if param.promotion.is_none() {
                    continue;
                }
                object
                    .write_property_from_context_with_object_type_resolver(
                        &param.name,
                        value.clone(),
                        Some(constructor_class_id),
                        &protected_class_ids,
                        |object, type_name| object.is_instance_of_class_name(type_name),
                    )
                    .map_err(|error| runtime_error(span, error))?;
            }
        }

        let trace_args = values.clone();
        let trace_callable = self.pending_uncaught_user_call_callable(
            function,
            Some(&object),
            Some(constructor_class_id),
        );
        let trace_function_line = function.span.line;
        let result = self.call_user_function_with_checked_values(
            function,
            values,
            Some(object.clone()),
            Some(constructor_class_id),
            Some(object.class_id()),
            reference_bindings,
            Some(scope),
        );
        if let Err(error) = &result {
            self.record_pending_uncaught_call_frame(
                trace_callable,
                trace_function_line,
                span,
                &trace_args,
                error,
            );
        }
        result?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn allocate_object_without_constructor(
        &mut self,
        class_id: ClassId,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let object_id = self.allocate_object_id();
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let class = self
            .classes
            .get(class_id)
            .expect("class id should resolve to class metadata");
        let class_name = class.name().to_string();
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        if self.is_spl_fixed_array_class_id(class_id) {
            self.spl_fixed_arrays
                .insert(object.id(), SplFixedArrayState::default());
        }
        if self.is_array_object_storage_class_id(class_id) {
            self.array_objects
                .insert(object.id(), BoundedArrayObjectState::default());
        }
        if self.is_spl_object_storage_class_id(class_id) {
            self.spl_object_storages
                .insert(object.id(), SplObjectStorageState::default());
        }
        if self.is_spl_doubly_linked_list_class_id(class_id) {
            let iterator_mode = Self::spl_doubly_linked_list_default_iterator_mode(&class_name);
            self.spl_doubly_linked_lists
                .insert(object.id(), SplDoublyLinkedListState::new(iterator_mode));
        }
        if self.is_spl_file_info_class_id(class_id) {
            self.spl_file_infos
                .insert(object.id(), SplFileInfoState::default());
        }
        if self.is_spl_file_object_class_id(class_id) {
            self.spl_file_objects
                .insert(object.id(), SplFileObjectState::default());
        }
        if self.is_spl_directory_iterator_class_id(class_id) {
            self.spl_directory_iterators
                .insert(object.id(), DirectoryIteratorState::default());
        }
        if self.is_spl_recursive_iterator_iterator_class_id(class_id) {
            self.spl_recursive_iterator_iterators
                .insert(object.id(), RecursiveIteratorIteratorState::default());
        }
        self.apply_instance_property_defaults(&object, class_id, span)?;
        self.sync_spl_doubly_linked_list_object_properties(&object, span)?;
        Ok(object)
    }

    fn resolve_new_class_name(
        &mut self,
        class_name: &NewClassName,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<String> {
        match class_name {
            NewClassName::Named(name) => Ok(name.clone()),
            NewClassName::DynamicVariable(name) => match scope.read_static(name, span)? {
                Value::String(class_name) => Ok(class_name),
                other => Err(runtime_error(
                    span,
                    RuntimeError::unsupported_object_instantiation(
                        "dynamic class name",
                        format!(
                            "dynamic class variable must contain a string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                )),
            },
            NewClassName::DynamicExpression(expr) => {
                match self.evaluate(expr, scope)? {
                Value::String(class_name) => Ok(class_name),
                Value::Object(object) => Ok(object.class_name().to_string()),
                other => Err(runtime_error(
                    span,
                    RuntimeError::unsupported_object_instantiation(
                        "dynamic class name",
                        format!(
                            "dynamic class-name expression must evaluate to a string or object in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                )),
                }
            }
            NewClassName::SelfClass => {
                let Some(current_class_id) = self.class_context.last().copied() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_object_instantiation(
                            "self",
                            "self requires active class context",
                        ),
                    ));
                };
                Ok(self
                    .classes
                    .get(current_class_id)
                    .expect("active class context should resolve to class metadata")
                    .name()
                    .to_string())
            }
            NewClassName::ParentClass => {
                let Some(current_class_id) = self.class_context.last().copied() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_object_instantiation(
                            "parent",
                            "parent requires active class context",
                        ),
                    ));
                };
                let current_class = self
                    .classes
                    .get(current_class_id)
                    .expect("active class context should resolve to class metadata");
                let Some(parent_class_id) = current_class.parent_id() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_object_instantiation(
                            "parent",
                            "parent requires a parent class",
                        ),
                    ));
                };
                Ok(self
                    .classes
                    .get(parent_class_id)
                    .expect("parent class id should resolve to class metadata")
                    .name()
                    .to_string())
            }
            NewClassName::StaticClass => {
                let Some(called_class_id) = self.called_class_context.last().copied() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_object_instantiation(
                            "static",
                            "static requires method or static class context",
                        ),
                    ));
                };
                Ok(self
                    .classes
                    .get(called_class_id)
                    .expect("called class context should resolve to class metadata")
                    .name()
                    .to_string())
            }
        }
    }

    fn instantiate_core_attribute(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let flags = self.core_attribute_flags_from_args(args, span, scope)?;
        let class_id = self
            .classes
            .lookup_class_id("Attribute")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("Attribute")))?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("core Attribute class id should resolve");
        let object = PhpObject::from_class_with_id(class, object_id);
        object
            .write_public_property("flags", Value::Int(flags))
            .map_err(|error| runtime_error(span, error))?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn core_attribute_flags_from_args(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<i64> {
        let flags_expr = match args {
            [] => None,
            [Expr::NamedArgument { name, expr, span }] if name == "flags" => {
                Some((expr.as_ref(), *span))
            }
            [Expr::NamedArgument { name, span, .. }] => {
                return Err(runtime_error(
                    *span,
                    RuntimeError::unsupported_object_instantiation(
                        "Attribute",
                        format!("unknown named argument ${name} for Attribute::__construct()"),
                    ),
                ));
            }
            [Expr::SpreadArgument { span, .. }] => {
                return Err(runtime_error(
                    *span,
                    RuntimeError::unsupported_object_instantiation(
                        "Attribute",
                        "argument unpacking is not implemented for Attribute::__construct()",
                    ),
                ));
            }
            [expr] => Some((expr, expr.span())),
            _ => {
                return Err(runtime_error(
                    span,
                    RuntimeError::arity_mismatch(
                        "Attribute::__construct()",
                        ArityExpectation::Between { min: 0, max: 1 },
                        args.len(),
                    ),
                ));
            }
        };
        let flags = if let Some((arg, arg_span)) = flags_expr {
            match self.evaluate(arg, scope)? {
                Value::Int(value) => value,
                other => {
                    return Err(runtime_error(
                        arg_span,
                        RuntimeError::unsupported_call(
                            "Attribute::__construct()",
                            format!(
                                "Argument #1 ($flags) must be of type int, {} given",
                                php_type_error_given(&other)
                            ),
                        ),
                    ));
                }
            }
        } else {
            PHP_ATTRIBUTE_TARGET_ALL
        };
        if flags & !(PHP_ATTRIBUTE_TARGET_ALL | PHP_ATTRIBUTE_IS_REPEATABLE) != 0 {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                "Invalid attribute flags specified",
            ));
        }
        Ok(flags)
    }

    fn instantiate_core_deprecated(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let (message, since) =
            self.deprecated_attribute_message_parts_from_exprs(args, false, span, scope)?;
        let class_id = self
            .classes
            .lookup_class_id("Deprecated")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("Deprecated")))?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("core Deprecated class id should resolve");
        let object = PhpObject::from_class_with_id(class, object_id);
        object
            .write_public_property("message", optional_string_value(message.as_deref()))
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("since", optional_string_value(since.as_deref()))
            .map_err(|error| runtime_error(span, error))?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

