    fn write_magic_get_array_access_append_with_reference_propagation(
        &mut self,
        object_name: &str,
        property: &str,
        keys: Vec<ArrayKey>,
        suffix_keys: &[ArrayKey],
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        let Some(Value::Object(holder)) = scope.read_named(object_name) else {
            return Ok(false);
        };
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match holder.read_property_from_context(property, current_class_id, &protected_class_ids) {
            Ok(_) => return Ok(false),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {}
            Err(error) => return Err(runtime_error(span, error)),
        }

        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(holder.class_id(), "__get")
        else {
            return Ok(false);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::__get()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, "__get", visibility, span)?;
        let returns_by_reference = {
            let function =
                self.method_function(class_id, &class_name, &resolved_method_name, span)?;
            function.as_ref().returns_by_reference
        };

        if returns_by_reference {
            let function =
                self.method_function(class_id, &class_name, &resolved_method_name, span)?;
            let function = function.as_ref();
            ensure_user_function_arity(function, 1, span)?;
            ensure_supported_reference_return_function_metadata(function, span)?;
            self.ensure_user_function_call_depth(function, span)?;
            if let Some(return_target) =
                self.reference_return_this_property_name(function, property, span)?
            {
                if array_literal_references.is_empty() && !return_target.prefix_keys.is_empty() {
                    if let Some(cell) = self.call_magic_get_reference_return_cell(
                        holder.clone(),
                        property,
                        span,
                        scope,
                    )? {
                        match cell.value_cloned() {
                            Value::Array(_) | Value::Null | Value::Bool(false) => {
                                let temp_name = self.next_foreach_temporary_array_name();
                                scope.bind_static_to_cell(&temp_name, cell);
                                let alias = ArrayOffsetAlias {
                                    root: ArrayOffsetAliasRoot::StaticArray {
                                        name: temp_name.clone(),
                                    },
                                    keys: keys.clone(),
                                };
                                scope.materialize_array_offset_alias(&alias, span)?;
                                if !scope
                                    .write_array_offset_alias_checked_with_object_type_resolver(
                                        &alias,
                                        value.clone(),
                                        span,
                                        &|object, type_name| {
                                            self.object_satisfies_live_property_type(
                                                object, type_name,
                                            )
                                        },
                                    )?
                                {
                                    return Err(runtime_error(
                                        span,
                                        RuntimeError::invalid_array_access(
                                            "cannot write magic __get() returned array bucket"
                                                .to_string(),
                                        ),
                                    ));
                                }
                                let root =
                                    scope.canonical_equivalent_static_array_alias_root(&alias.root);
                                scope.sync_array_offset_aliases_for_root_path_checked_with_object_type_resolver(
                                    &root,
                                    &keys,
                                    span,
                                    &|object, type_name| {
                                        self.object_satisfies_live_property_type(object, type_name)
                                    },
                                )?;
                                return Ok(true);
                            }
                            _ => {}
                        }
                    }
                }
                let protected_class_ids = self.protected_class_ids_for_context(class_id);
                let property_visibility = holder
                    .property_visibility_from_context(
                        &return_target.property,
                        Some(class_id),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                let root = if property_visibility == Visibility::Public {
                    ArrayOffsetAliasRoot::PublicObjectProperty {
                        object: object_name.to_string(),
                        property: return_target.property.clone(),
                    }
                } else {
                    ArrayOffsetAliasRoot::ContextObjectProperty {
                        object: object_name.to_string(),
                        property: return_target.property.clone(),
                        current_class_id: Some(class_id),
                        protected_class_ids: protected_class_ids.clone(),
                    }
                };
                let root = scope.canonical_equivalent_object_property_alias_root(&root);
                let mut target_keys = return_target.prefix_keys.clone();
                target_keys.extend(keys.iter().cloned());
                match holder
                    .read_property_from_context(
                        &return_target.property,
                        Some(class_id),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?
                {
                    Value::Array(_) | Value::Null | Value::Bool(false) => {
                        let stored_value =
                            Self::wrap_value_in_array_suffix(suffix_keys, value, span)?;
                        let alias = scope.append_object_property_array_offset_reference_alias(
                            root,
                            target_keys,
                            stored_value,
                            span,
                        )?;
                        let mut reference_keys = alias.keys;
                        reference_keys.extend(suffix_keys.iter().cloned());
                        self.bind_or_mirror_array_references_to_alias_root(
                            expr,
                            alias.root,
                            reference_keys,
                            array_literal_references,
                            array_literal_copy_sources,
                            scope,
                        )?;
                        return Ok(true);
                    }
                    Value::Object(object)
                        if keys.is_empty()
                            && self
                                .classes
                                .implements_interface(object.class_id(), "ArrayAccess") =>
                    {
                        return self.write_array_access_object_append_with_reference_propagation(
                            object,
                            suffix_keys,
                            value,
                            expr,
                            array_literal_references,
                            array_literal_copy_sources,
                            span,
                            scope,
                        );
                    }
                    Value::Object(object)
                        if !keys.is_empty()
                            && self
                                .classes
                                .implements_interface(object.class_id(), "ArrayAccess") =>
                    {
                        return self
                            .write_array_access_object_nested_append_with_reference_propagation(
                                object,
                                keys,
                                suffix_keys,
                                value,
                                expr,
                                array_literal_references,
                                array_literal_copy_sources,
                                span,
                                scope,
                            );
                    }
                    _ => {}
                }
            }
            let Some(cell) =
                self.call_magic_get_reference_return_cell(holder, property, span, scope)?
            else {
                return Ok(false);
            };

            let current_value = cell.value_cloned();
            match current_value {
                Value::Object(object)
                    if keys.is_empty()
                        && self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.write_array_access_object_append_with_reference_propagation(
                        object,
                        suffix_keys,
                        value,
                        expr,
                        array_literal_references,
                        array_literal_copy_sources,
                        span,
                        scope,
                    )
                }
                Value::Object(object)
                    if !keys.is_empty()
                        && self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.write_array_access_object_nested_append_with_reference_propagation(
                        object,
                        keys,
                        suffix_keys,
                        value,
                        expr,
                        array_literal_references,
                        array_literal_copy_sources,
                        span,
                        scope,
                    )
                }
                Value::Object(_) => Ok(false),
                Value::Array(_) | Value::Null | Value::Bool(false) => {
                    let temp_name = self.next_foreach_temporary_array_name();
                    scope.bind_static_to_cell(&temp_name, cell);
                    let stored_value = Self::wrap_value_in_array_suffix(suffix_keys, value, span)?;
                    let alias = scope.append_array_offset_reference_alias(
                        &temp_name,
                        keys,
                        stored_value,
                        span,
                    )?;
                    let root = scope.canonical_equivalent_static_array_alias_root(&alias.root);
                    let mut reference_keys = alias.keys;
                    reference_keys.extend(suffix_keys.iter().cloned());
                    self.bind_or_mirror_array_references_to_alias_root(
                        expr,
                        root,
                        reference_keys,
                        array_literal_references,
                        array_literal_copy_sources,
                        scope,
                    )?;
                    Ok(true)
                }
                _ => Ok(false),
            }
        } else {
            let magic_value = self
                .call_magic_get_property_value_with_array_copy_source(
                    holder, property, span, scope,
                )?
                .map(|(value, source, _)| {
                    let source = if matches!(value, Value::Array(_)) {
                        source
                    } else {
                        None
                    };
                    scope.value_with_object_property_aliases_from_array_copy(value, source, true)
                });
            match magic_value {
                Some(Value::Object(object))
                    if keys.is_empty()
                        && self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.write_array_access_object_append_with_reference_propagation(
                        object,
                        suffix_keys,
                        value,
                        expr,
                        array_literal_references,
                        array_literal_copy_sources,
                        span,
                        scope,
                    )
                }
                Some(Value::Object(object))
                    if !keys.is_empty()
                        && self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    self.write_array_access_object_nested_append_with_reference_propagation(
                        object,
                        keys,
                        suffix_keys,
                        value,
                        expr,
                        array_literal_references,
                        array_literal_copy_sources,
                        span,
                        scope,
                    )
                }
                Some(returned_value @ Value::Array(_)) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    if self.write_by_value_overloaded_array_path_array_access_object(
                        &returned_value,
                        &keys,
                        suffix_keys,
                        value.clone(),
                        expr,
                        &array_literal_references,
                        array_literal_copy_sources,
                        true,
                        span,
                        scope,
                    )? {
                        return Ok(true);
                    }
                    self.write_by_value_overloaded_array_reference_cells(
                        returned_value,
                        &keys,
                        suffix_keys,
                        value,
                        expr,
                        &array_literal_references,
                        array_literal_copy_sources,
                        true,
                        span,
                        scope,
                    )
                }
                Some(Value::Null) | Some(Value::Bool(false)) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    Ok(true)
                }
                Some(
                    value
                    @ (Value::Bool(true) | Value::Int(_) | Value::Float(_) | Value::String(_)),
                ) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot write offset on {}",
                            value.type_name()
                        )),
                    ))
                }
                Some(_) | None => Ok(false),
            }
        }
    }

    fn write_magic_get_array_access_keyed_with_reference_propagation(
        &mut self,
        object_name: &str,
        property: &str,
        keys: Vec<ArrayKey>,
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        if keys.is_empty() {
            return Ok(false);
        }

        let Some(Value::Object(holder)) = scope.read_named(object_name) else {
            return Ok(false);
        };
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match holder.read_property_from_context(property, current_class_id, &protected_class_ids) {
            Ok(_) => return Ok(false),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {}
            Err(error) => return Err(runtime_error(span, error)),
        }

        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(holder.class_id(), "__get")
        else {
            return Ok(false);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::__get()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, "__get", visibility, span)?;
        let returns_by_reference = {
            let function =
                self.method_function(class_id, &class_name, &resolved_method_name, span)?;
            function.as_ref().returns_by_reference
        };

        let array_access_object = if returns_by_reference {
            let function =
                self.method_function(class_id, &class_name, &resolved_method_name, span)?;
            let function = function.as_ref();
            ensure_user_function_arity(function, 1, span)?;
            ensure_supported_reference_return_function_metadata(function, span)?;
            self.ensure_user_function_call_depth(function, span)?;
            if let Some(return_target) =
                self.reference_return_this_property_name(function, property, span)?
            {
                let protected_class_ids = self.protected_class_ids_for_context(class_id);
                let property_visibility = holder
                    .property_visibility_from_context(
                        &return_target.property,
                        Some(class_id),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                let root = if property_visibility == Visibility::Public {
                    ArrayOffsetAliasRoot::PublicObjectProperty {
                        object: object_name.to_string(),
                        property: return_target.property.clone(),
                    }
                } else {
                    ArrayOffsetAliasRoot::ContextObjectProperty {
                        object: object_name.to_string(),
                        property: return_target.property.clone(),
                        current_class_id: Some(class_id),
                        protected_class_ids: protected_class_ids.clone(),
                    }
                };
                let root = scope.canonical_equivalent_object_property_alias_root(&root);
                let mut target_keys = return_target.prefix_keys.clone();
                target_keys.extend(keys.iter().cloned());
                match holder
                    .read_property_from_context(
                        &return_target.property,
                        Some(class_id),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?
                {
                    Value::Array(_) | Value::Null | Value::Bool(false) => {
                        let alias = ArrayOffsetAlias {
                            root: root.clone(),
                            keys: target_keys.clone(),
                        };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        if !scope.write_array_offset_alias_checked_with_object_type_resolver(
                            &alias,
                            value.clone(),
                            span,
                            &|object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )? {
                            return Err(runtime_error(
                                span,
                                RuntimeError::invalid_array_access(
                                    "cannot write magic __get() backing array bucket".to_string(),
                                ),
                            ));
                        }
                        scope.sync_array_offset_aliases_for_root_path_checked_with_object_type_resolver(
                            &root,
                            &target_keys,
                            span,
                            &|object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )?;
                        self.bind_or_mirror_array_references_to_alias_root(
                            expr,
                            root,
                            target_keys,
                            array_literal_references,
                            array_literal_copy_sources,
                            scope,
                        )?;
                        return Ok(true);
                    }
                    Value::Object(object)
                        if self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                    {
                        Some(object)
                    }
                    _ => None,
                }
            } else {
                let Some(cell) =
                    self.call_magic_get_reference_return_cell(holder, property, span, scope)?
                else {
                    return Ok(false);
                };
                let current_value = cell.value_cloned();
                match current_value {
                    Value::Array(_) | Value::Null | Value::Bool(false) => {
                        let temp_name = self.next_foreach_temporary_array_name();
                        scope.bind_static_to_cell(&temp_name, cell);
                        let alias = ArrayOffsetAlias {
                            root: ArrayOffsetAliasRoot::StaticArray {
                                name: temp_name.clone(),
                            },
                            keys: keys.clone(),
                        };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        if !scope.write_array_offset_alias_checked_with_object_type_resolver(
                            &alias,
                            value.clone(),
                            span,
                            &|object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )? {
                            return Err(runtime_error(
                                span,
                                RuntimeError::invalid_array_access(
                                    "cannot write magic __get() returned array bucket".to_string(),
                                ),
                            ));
                        }
                        let root = scope.canonical_equivalent_static_array_alias_root(&alias.root);
                        self.bind_or_mirror_array_references_to_alias_root(
                            expr,
                            root,
                            keys.clone(),
                            array_literal_references,
                            array_literal_copy_sources,
                            scope,
                        )?;
                        return Ok(true);
                    }
                    Value::Object(object)
                        if self
                            .classes
                            .implements_interface(object.class_id(), "ArrayAccess") =>
                    {
                        Some(object)
                    }
                    _ => None,
                }
            }
        } else {
            let magic_value = self
                .call_magic_get_property_value_with_array_copy_source(
                    holder, property, span, scope,
                )?
                .map(|(value, source, _)| {
                    let source = if matches!(value, Value::Array(_)) {
                        source
                    } else {
                        None
                    };
                    scope.value_with_object_property_aliases_from_array_copy(value, source, true)
                });
            match magic_value {
                Some(Value::Object(object))
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    Some(object)
                }
                Some(returned_value @ Value::Array(_)) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    if self.write_by_value_overloaded_array_path_array_access_object(
                        &returned_value,
                        &keys,
                        &[],
                        value.clone(),
                        expr,
                        &array_literal_references,
                        array_literal_copy_sources,
                        false,
                        span,
                        scope,
                    )? {
                        return Ok(true);
                    }
                    return self.write_by_value_overloaded_array_reference_cells(
                        returned_value,
                        &keys,
                        &[],
                        value,
                        expr,
                        &array_literal_references,
                        array_literal_copy_sources,
                        false,
                        span,
                        scope,
                    );
                }
                Some(Value::Null) | Some(Value::Bool(false)) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    return Ok(true);
                }
                Some(
                    value
                    @ (Value::Bool(true) | Value::Int(_) | Value::Float(_) | Value::String(_)),
                ) => {
                    self.emit_notice(
                        "__get()",
                        format!(
                            "Indirect modification of overloaded property {class_name}::${property} has no effect"
                        ),
                        span,
                    )?;
                    return Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot write offset on {}",
                            value.type_name()
                        )),
                    ));
                }
                _ => None,
            }
        };

        let Some(array_access_object) = array_access_object else {
            return Ok(false);
        };

        if keys.len() == 1 {
            self.write_array_access_object_keyed_with_reference_propagation(
                array_access_object,
                keys[0].clone(),
                value,
                expr,
                array_literal_references,
                array_literal_copy_sources,
                span,
                scope,
            )
        } else {
            self.write_array_access_object_nested_keyed_with_reference_propagation(
                array_access_object,
                keys,
                value,
                expr,
                array_literal_references,
                array_literal_copy_sources,
                span,
                scope,
            )
        }
    }

    fn reference_return_this_property_name(
        &self,
        function: &FunctionDecl,
        requested_property: &str,
        span: Span,
    ) -> CompileResult<Option<ThisPropertyReferenceTarget>> {
        let Some(param) = function.params.first() else {
            return Ok(None);
        };
        let Some(analysis) = Self::single_return_analysis(function, &param.name) else {
            return Ok(None);
        };

        match analysis.return_value {
            Expr::Property {
                target, property, ..
            } => {
                if !matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") {
                    return Ok(None);
                }
                Ok(Some(ThisPropertyReferenceTarget {
                    property: property.clone(),
                    prefix_keys: Vec::new(),
                    suffix_keys: Vec::new(),
                }))
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                if !matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") {
                    return Ok(None);
                }
                if !Self::expr_is_parameter_or_local_copy(
                    property.as_ref(),
                    &param.name,
                    &analysis.local_param_aliases,
                ) {
                    return Ok(None);
                }
                Ok(Some(ThisPropertyReferenceTarget {
                    property: requested_property.to_string(),
                    prefix_keys: Vec::new(),
                    suffix_keys: Vec::new(),
                }))
            }
            Expr::Index { target, index, .. } => {
                Self::reference_return_this_property_offset_target(
                    function,
                    target,
                    index,
                    requested_property,
                    &analysis.local_param_aliases,
                    &analysis.local_property_aliases,
                    &analysis.local_literal_key_aliases,
                    span,
                )
            }
            Expr::Variable(name, _) => {
                let Some((property, indices)) =
                    Self::local_property_alias_return_path(name, &analysis.local_property_aliases)
                else {
                    return Ok(None);
                };
                Self::reference_return_this_property_indices_target(
                    function,
                    property,
                    indices,
                    requested_property,
                    &analysis.local_param_aliases,
                    &analysis.local_literal_key_aliases,
                    span,
                )
            }
            _ => Ok(None),
        }
    }

    fn reference_return_this_property_offset_target(
        function: &FunctionDecl,
        target: &Expr,
        index: &Expr,
        requested_property: &str,
        local_param_aliases: &[String],
        local_property_aliases: &[ThisPropertyLocalAlias],
        local_literal_key_aliases: &[LocalLiteralKeyAlias],
        span: Span,
    ) -> CompileResult<Option<ThisPropertyReferenceTarget>> {
        let Some((property, indices)) =
            Self::collect_this_property_or_local_alias_index_return_path(
                target,
                index,
                local_property_aliases,
            )
        else {
            return Ok(None);
        };
        Self::reference_return_this_property_indices_target(
            function,
            property,
            indices,
            requested_property,
            local_param_aliases,
            local_literal_key_aliases,
            span,
        )
    }

    fn reference_return_this_property_indices_target(
        function: &FunctionDecl,
        property: String,
        indices: Vec<&Expr>,
        requested_property: &str,
        local_param_aliases: &[String],
        local_literal_key_aliases: &[LocalLiteralKeyAlias],
        _span: Span,
    ) -> CompileResult<Option<ThisPropertyReferenceTarget>> {
        let Some(param) = function.params.first() else {
            return Ok(None);
        };
        let mut prefix_keys = Vec::new();
        let mut used_requested_property = false;
        for index in indices {
            if Self::expr_is_parameter_or_local_copy(index, &param.name, local_param_aliases) {
                if used_requested_property {
                    return Ok(None);
                }
                prefix_keys.push(ArrayKey::String(requested_property.to_string()));
                used_requested_property = true;
                continue;
            }

            let Some(key) = Self::literal_reference_return_array_key_with_locals(
                index,
                local_literal_key_aliases,
            ) else {
                return Ok(None);
            };
            prefix_keys.push(key);
        }
        if !used_requested_property {
            return Ok(None);
        }

        Ok(Some(ThisPropertyReferenceTarget {
            property,
            prefix_keys,
            suffix_keys: Vec::new(),
        }))
    }

    fn collect_this_property_or_local_alias_index_return_path<'a>(
        target: &'a Expr,
        index: &'a Expr,
        local_property_aliases: &'a [ThisPropertyLocalAlias],
    ) -> Option<(String, Vec<&'a Expr>)> {
        let mut indices = vec![index];
        let mut current = target;
        while let Expr::Index { target, index, .. } = current {
            indices.push(index.as_ref());
            current = target.as_ref();
        }
        indices.reverse();

        match current {
            Expr::Property {
                target, property, ..
            } if matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") => {
                Some((property.clone(), indices))
            }
            Expr::Variable(name, _) => local_property_aliases
                .iter()
                .find(|alias| alias.local == *name)
                .map(|alias| {
                    let mut combined_indices = alias.prefix_indices.iter().collect::<Vec<_>>();
                    combined_indices.extend(indices);
                    (alias.property.clone(), combined_indices)
                }),
            _ => None,
        }
    }

    fn local_property_alias_return_path<'a>(
        name: &str,
        local_property_aliases: &'a [ThisPropertyLocalAlias],
    ) -> Option<(String, Vec<&'a Expr>)> {
        local_property_aliases
            .iter()
            .find(|alias| alias.local == name)
            .map(|alias| {
                (
                    alias.property.clone(),
                    alias.prefix_indices.iter().collect::<Vec<_>>(),
                )
            })
    }

    fn literal_reference_return_array_key(expr: &Expr) -> Option<ArrayKey> {
        match expr {
            Expr::String(value, _) => Some(ArrayKey::String(value.clone())),
            Expr::Int(value, _) => Some(ArrayKey::Int(*value)),
            _ => None,
        }
    }

    fn literal_reference_return_array_key_with_locals(
        expr: &Expr,
        local_literal_key_aliases: &[LocalLiteralKeyAlias],
    ) -> Option<ArrayKey> {
        Self::literal_reference_return_array_key(expr).or_else(|| match expr {
            Expr::Variable(name, _) => local_literal_key_aliases
                .iter()
                .find(|alias| alias.local == *name)
                .map(|alias| alias.key.clone()),
            _ => None,
        })
    }

    fn write_array_access_object_nested_append_with_reference_propagation(
        &mut self,
        array_access_object: PhpObject,
        keys: Vec<ArrayKey>,
        suffix_keys: &[ArrayKey],
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        if keys.is_empty() {
            return Ok(false);
        }

        let hidden_name = self.hidden_array_access_reference_object_name(&array_access_object);
        scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));

        if self.write_array_access_by_value_nested_with_reference_cells_for_object(
            array_access_object.clone(),
            keys.clone(),
            None,
            suffix_keys,
            value.clone(),
            expr,
            &array_literal_references,
            array_literal_copy_sources,
            true,
            true,
            span,
            scope,
        )? {
            return Ok(true);
        }

        let (parent_alias, _) = self.evaluate_array_access_reference_source_alias_for_object(
            array_access_object,
            hidden_name,
            keys,
            None,
            span,
            scope,
        )?;
        let value = self.value_with_assignment_reference_cells(
            value,
            expr,
            &array_literal_references,
            array_literal_copy_sources,
            scope,
            expr.span(),
        )?;
        let stored_value = Self::wrap_value_in_array_suffix(suffix_keys, value, span)?;
        let target_alias = scope.append_object_property_array_offset_reference_alias(
            parent_alias.root,
            parent_alias.keys,
            stored_value,
            span,
        )?;
        let mut reference_keys = target_alias.keys;
        reference_keys.extend(suffix_keys.iter().cloned());
        self.bind_or_mirror_array_references_to_alias_root(
            expr,
            target_alias.root,
            reference_keys,
            array_literal_references,
            array_literal_copy_sources,
            scope,
        )?;
        Ok(true)
    }

    fn write_array_access_object_append_with_reference_propagation(
        &mut self,
        array_access_object: PhpObject,
        suffix_keys: &[ArrayKey],
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        let hidden_name = self.hidden_array_access_reference_object_name(&array_access_object);
        scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));

        let method_value = self.value_with_assignment_reference_cells(
            value,
            expr,
            &array_literal_references,
            array_literal_copy_sources,
            scope,
            expr.span(),
        )?;
        let stored_value = Self::wrap_value_in_array_suffix(suffix_keys, method_value, span)?;
        let indexed_copy_source_bindings =
            Self::indexed_array_copy_source_bindings_for_argument_with_prefix(
                1,
                suffix_keys,
                array_literal_copy_sources,
            );
        self.call_array_access_method_with_caller_scope_and_arg_sources(
            array_access_object.clone(),
            "offsetSet",
            vec![Self::array_key_value(None), stored_value],
            span,
            scope,
            indexed_copy_source_bindings,
        )?;
        if let Some((root, reference_keys)) = self.array_access_offset_set_alias_for_object(
            array_access_object.clone(),
            &hidden_name,
            None,
            true,
            span,
            scope,
        )? {
            let mut target_keys = reference_keys.clone();
            target_keys.extend(suffix_keys.iter().cloned());
            self.bind_or_mirror_array_references_to_alias_root(
                expr,
                root,
                target_keys,
                array_literal_references,
                array_literal_copy_sources,
                scope,
            )?;
        }
        Ok(true)
    }

    fn write_array_access_object_keyed_with_reference_propagation(
        &mut self,
        array_access_object: PhpObject,
        key: ArrayKey,
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        let hidden_name = self.hidden_array_access_reference_object_name(&array_access_object);
        scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));

        let method_value = self.value_with_assignment_reference_cells(
            value,
            expr,
            &array_literal_references,
            array_literal_copy_sources,
            scope,
            expr.span(),
        )?;
        let indexed_copy_source_bindings =
            Self::indexed_array_copy_source_bindings_for_argument(1, array_literal_copy_sources);
        self.call_array_access_method_with_caller_scope_and_arg_sources(
            array_access_object.clone(),
            "offsetSet",
            vec![Self::array_key_value(Some(key.clone())), method_value],
            span,
            scope,
            indexed_copy_source_bindings,
        )?;
        if let Some((root, reference_keys)) = self.array_access_offset_set_alias_for_object(
            array_access_object,
            &hidden_name,
            Some(key),
            true,
            span,
            scope,
        )? {
            self.bind_or_mirror_array_references_to_alias_root(
                expr,
                root,
                reference_keys,
                array_literal_references,
                array_literal_copy_sources,
                scope,
            )?;
        }
        Ok(true)
    }

    fn write_array_access_object_nested_keyed_with_reference_propagation(
        &mut self,
        array_access_object: PhpObject,
        keys: Vec<ArrayKey>,
        value: Value,
        expr: &Expr,
        array_literal_references: Vec<ArrayLiteralReferenceElement>,
        array_literal_copy_sources: &[(Vec<ArrayKey>, ArrayCopySource)],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<bool> {
        if keys.len() < 2 {
            return Ok(false);
        }

        let hidden_name = self.hidden_array_access_reference_object_name(&array_access_object);
        scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));

        if self.write_array_access_by_value_nested_with_reference_cells_for_object(
            array_access_object.clone(),
            keys.clone(),
            None,
            &[],
            value.clone(),
            expr,
            &array_literal_references,
            array_literal_copy_sources,
            false,
            false,
            span,
            scope,
        )? {
            return Ok(true);
        }

        let (target_alias, _) = self.evaluate_array_access_reference_source_alias_for_object(
            array_access_object,
            hidden_name,
            keys,
            None,
            span,
            scope,
        )?;
        if !scope.write_array_offset_alias_checked_with_object_type_resolver(
            &target_alias,
            value,
            span,
            &|object, type_name| self.object_satisfies_live_property_type(object, type_name),
        )? {
            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot write property-held ArrayAccess nested backing bucket".to_string(),
                ),
            ));
        }
        self.bind_or_mirror_array_references_to_alias_root(
            expr,
            target_alias.root,
            target_alias.keys,
            array_literal_references,
            array_literal_copy_sources,
            scope,
        )?;
        Ok(true)
    }

    fn write_nested_array_assignment(
        &mut self,
        name: &str,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        if !scope.is_array_offset_alias_name(name) {
            scope.clear_public_object_property_array_copy_source(name);
            scope.clear_array_literal_copy_source_paths_for_root(name);
            let cell = { scope.routed_storage(name).borrow().get(name).cloned() };

            if let Some(cell) = cell {
                cell.update_value(|slot| {
                    if matches!(slot, Value::Bool(false)) {
                        self.emit_false_to_array_deprecation(span)?;
                        *slot = Value::Array(PhpArray::new());
                    } else if matches!(slot, Value::Null) {
                        *slot = Value::Array(PhpArray::new());
                    }

                    match slot {
                        Value::Array(array) => {
                            self.write_nested_array_value(array, keys, value, span)
                        }
                        other => Err(runtime_error(
                            span,
                            RuntimeError::invalid_array_access(format!(
                                "cannot write offset on {}",
                                other.type_name()
                            )),
                        )),
                    }
                })?;
            } else {
                let mut array = PhpArray::new();
                self.write_nested_array_value(&mut array, keys, value, span)?;
                scope.write_static(name, Value::Array(array));
            }

            if scope.name_routes_to_global_storage(name) {
                scope.sync_array_offset_aliases_for_global_root(name);
            }
            scope.sync_array_offset_aliases_for_root_path(
                &ArrayOffsetAliasRoot::StaticArray {
                    name: name.to_string(),
                },
                keys,
            );
            return Ok(());
        }

        let mut slot = scope
            .read_named(name)
            .unwrap_or_else(|| Value::Array(PhpArray::new()));

        if matches!(slot, Value::Bool(false)) {
            self.emit_false_to_array_deprecation(span)?;
            slot = Value::Array(PhpArray::new());
        } else if matches!(slot, Value::Null) {
            slot = Value::Array(PhpArray::new());
        }

        match &mut slot {
            Value::Array(array) => {
                self.write_nested_array_value(array, keys, value, span)?;
                scope.write_static(name, slot);
                scope.sync_array_offset_aliases_for_root_path(
                    &ArrayOffsetAliasRoot::StaticArray {
                        name: name.to_string(),
                    },
                    keys,
                );
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot write offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn write_global_nested_array_assignment(
        &mut self,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (global_name, keys) = SymbolTable::split_globals_reference_path(keys.to_vec(), span)?;

        let cell = { scope.global_storage().borrow().get(&global_name).cloned() };

        if let Some(cell) = cell {
            cell.update_value(|slot| {
                if matches!(slot, Value::Bool(false)) {
                    self.emit_false_to_array_deprecation(span)?;
                    *slot = Value::Array(PhpArray::new());
                } else if matches!(slot, Value::Null) {
                    *slot = Value::Array(PhpArray::new());
                }

                match slot {
                    Value::Array(array) => self.write_nested_array_value(array, &keys, value, span),
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot write offset on {}",
                            other.type_name()
                        )),
                    )),
                }
            })?;
        } else {
            let mut array = PhpArray::new();
            self.write_nested_array_value(&mut array, &keys, value, span)?;
            scope.write_global_name(&global_name, Value::Array(array));
        }

        scope.sync_array_offset_aliases_for_root_path(
            &ArrayOffsetAliasRoot::GlobalArray {
                name: global_name.clone(),
            },
            &keys,
        );
        Ok(())
    }

    fn write_object_property_nested_array_assignment(
        &mut self,
        object_name: &str,
        property: &str,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot write property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };
        self.ensure_object_property_writable_for_array_mutation(
            object_name,
            property,
            span,
            scope,
        )?;

        let mut slot = object
            .read_property_from_context(property, current_class_id, &protected_class_ids)
            .map_err(|error| runtime_error(span, error))?;

        if matches!(slot, Value::Bool(false)) {
            self.emit_false_to_array_deprecation(span)?;
            slot = Value::Array(PhpArray::new());
        } else if matches!(slot, Value::Null) {
            slot = Value::Array(PhpArray::new());
        }

        if let Value::Object(object) = slot {
            if keys.len() == 1
                && self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess")
            {
                self.call_array_access_method_with_caller_scope(
                    object,
                    "offsetSet",
                    vec![Self::array_key_value(Some(keys[0].clone())), value],
                    span,
                    scope,
                )?;
                return Ok(());
            }

            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access("cannot write offset on object".to_string()),
            ));
        }

        match &mut slot {
            Value::String(string) if keys.len() == 1 => {
                let boundary = scope.object_property_holder_storage_boundary(
                    object_name,
                    &object,
                    property,
                    keys,
                    current_class_id,
                    &protected_class_ids,
                );
                scope.pre_replace_holder_storage(&boundary);
                self.write_ascii_string_offset(string, &keys[0], value, span)?;
                object
                    .write_property_from_context_with_object_type_resolver(
                        property,
                        slot,
                        current_class_id,
                        &protected_class_ids,
                        |object, type_name| {
                            self.object_satisfies_live_property_type(object, type_name)
                        },
                    )
                    .map_err(|error| runtime_error(span, error))?;
                scope.post_replace_holder_storage(&boundary);
                Ok(())
            }
            Value::Array(array) => {
                let boundary = scope.object_property_holder_storage_boundary(
                    object_name,
                    &object,
                    property,
                    keys,
                    current_class_id,
                    &protected_class_ids,
                );
                scope.pre_replace_holder_storage(&boundary);
                self.write_nested_array_value(array, keys, value, span)?;
                object
                    .write_property_from_context(
                        property,
                        slot,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                scope.post_replace_holder_storage(&boundary);
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot write offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn write_object_property_nested_array_append(
        &mut self,
        object_name: &str,
        property: &str,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object = match scope.read_static(object_name, span)? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot write property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };
        self.ensure_object_property_writable_for_array_mutation(
            object_name,
            property,
            span,
            scope,
        )?;

        let mut slot = object
            .read_property_from_context(property, current_class_id, &protected_class_ids)
            .map_err(|error| runtime_error(span, error))?;

        if matches!(slot, Value::Bool(false)) {
            self.emit_false_to_array_deprecation(span)?;
            slot = Value::Array(PhpArray::new());
        } else if matches!(slot, Value::Null) {
            slot = Value::Array(PhpArray::new());
        }

        if let Value::Object(object) = slot {
            if keys.is_empty()
                && self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess")
            {
                self.call_array_access_method_with_caller_scope(
                    object,
                    "offsetSet",
                    vec![Self::array_key_value(None), value],
                    span,
                    scope,
                )?;
                return Ok(());
            }

            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access("cannot write offset on object".to_string()),
            ));
        }

        match &mut slot {
            Value::Array(array) => {
                let boundary = scope.object_property_holder_storage_boundary(
                    object_name,
                    &object,
                    property,
                    keys,
                    current_class_id,
                    &protected_class_ids,
                );
                scope.pre_replace_holder_storage(&boundary);
                Self::append_nested_array_value(array, keys, value, span)?;
                object
                    .write_property_from_context(
                        property,
                        slot,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?;
                scope.post_replace_holder_storage(&boundary);
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot write offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn write_object_property_nested_array_append_with_suffix(
        &mut self,
        object_name: &str,
        property: &str,
        keys: &[ArrayKey],
        suffix_keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        self.ensure_object_property_writable_for_array_mutation(
            object_name,
            property,
            span,
            scope,
        )?;
        self.reject_object_property_array_access_reference_target_if_needed(
            object_name,
            property,
            span,
            scope,
        )?;
        let root = self.context_object_property_alias_root(object_name, property, span, scope)?;
        let stored_value = Self::wrap_value_in_array_suffix(suffix_keys, value, span)?;
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let boundary = match scope.read_static(object_name, span)? {
            Value::Object(object) => Some(scope.object_property_holder_storage_boundary(
                object_name,
                &object,
                property,
                keys,
                current_class_id,
                &protected_class_ids,
            )),
            _ => None,
        };
        if let Some(boundary) = boundary.as_ref() {
            scope.pre_replace_holder_storage(boundary);
        }
        let appended_alias = scope.append_object_property_array_offset_reference_alias(
            root,
            keys.to_vec(),
            stored_value,
            span,
        )?;
        if let Some(boundary) = boundary.as_ref() {
            scope.post_replace_holder_storage(boundary);
        }
        scope.sync_array_offset_aliases_for_root_path(&appended_alias.root, &appended_alias.keys);
        Ok(())
    }

    fn wrap_value_in_array_suffix(
        suffix_keys: &[ArrayKey],
        value: Value,
        span: Span,
    ) -> CompileResult<Value> {
        if suffix_keys.is_empty() {
            return Ok(value);
        }

        let mut array = PhpArray::new();
        Self::write_nested_array_value_without_reference_constraints(
            &mut array,
            suffix_keys,
            value,
            span,
        )?;
        Ok(Value::Array(array))
    }

    fn write_nested_array_value_without_reference_constraints(
        array: &mut PhpArray,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
    ) -> CompileResult<()> {
        let Some((key, rest)) = keys.split_first() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "array assignment",
                    "nested array assignment requires at least one key",
                ),
            ));
        };

        if rest.is_empty() {
            array.insert(key.clone(), value);
            return Ok(());
        }

        let mut child = match array.get_cloned(key.clone()) {
            Some(Value::Array(child)) => child,
            Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot write offset on {}",
                        other.type_name()
                    )),
                ));
            }
        };
        Self::write_nested_array_value_without_reference_constraints(
            &mut child, rest, value, span,
        )?;
        array.insert(key.clone(), Value::Array(child));
        Ok(())
    }

    fn write_nested_array_value(
        &mut self,
        array: &mut PhpArray,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
    ) -> CompileResult<()> {
        let Some((key, rest)) = keys.split_first() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "array assignment",
                    "nested array assignment requires at least one key",
                ),
            ));
        };

        if rest.is_empty() {
            array
                .insert_checked_with_object_type_resolver(
                    key.clone(),
                    value,
                    |object, type_name| self.object_satisfies_live_property_type(object, type_name),
                )
                .map_err(|error| runtime_error(span, error))?;
            return Ok(());
        }

        let mut child = match array.get_cloned(key.clone()) {
            Some(Value::Array(child)) => child,
            Some(Value::String(mut string)) if rest.len() == 1 => {
                self.write_ascii_string_offset(&mut string, &rest[0], value, span)?;
                array
                    .insert_checked_with_object_type_resolver(
                        key.clone(),
                        Value::String(string),
                        |object, type_name| {
                            self.object_satisfies_live_property_type(object, type_name)
                        },
                    )
                    .map_err(|error| runtime_error(span, error))?;
                return Ok(());
            }
            Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot write offset on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        self.write_nested_array_value(&mut child, rest, value, span)?;
        array.insert(key.clone(), Value::Array(child));
        Ok(())
    }

    fn read_nested_array_value(
        array: &PhpArray,
        keys: &[ArrayKey],
        span: Span,
    ) -> CompileResult<Value> {
        let Some((key, rest)) = keys.split_first() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "array access",
                    "nested array access requires at least one key",
                ),
            ));
        };

        let value = array.get_cloned(key.clone()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::undefined_array_key(key.diagnostic_key()),
            )
        })?;
        if rest.is_empty() {
            return Ok(value);
        }

        match value {
            Value::Array(child) => Self::read_nested_array_value(&child, rest, span),
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot read offset from {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn write_nested_array_append(
        &mut self,
        name: &str,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let mut slot = scope
            .read_named(name)
            .unwrap_or_else(|| Value::Array(PhpArray::new()));

        if matches!(slot, Value::Bool(false)) {
            self.emit_false_to_array_deprecation(span)?;
            slot = Value::Array(PhpArray::new());
        } else if matches!(slot, Value::Null) {
            slot = Value::Array(PhpArray::new());
        }

        match &mut slot {
            Value::Array(array) => {
                Self::append_nested_array_value(array, keys, value, span)?;
                scope.write_static(name, slot);
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot write offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn write_global_nested_array_append(
        &mut self,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (global_name, keys) = SymbolTable::split_globals_reference_path(keys.to_vec(), span)?;
        let mut slot = scope
            .read_global_name(&global_name)
            .unwrap_or_else(|| Value::Array(PhpArray::new()));

        if matches!(slot, Value::Bool(false)) {
            self.emit_false_to_array_deprecation(span)?;
            slot = Value::Array(PhpArray::new());
        } else if matches!(slot, Value::Null) {
            slot = Value::Array(PhpArray::new());
        }

        match &mut slot {
            Value::Array(array) => {
                Self::append_nested_array_value(array, &keys, value, span)?;
                scope.write_global_name(&global_name, slot);
                scope.sync_array_offset_aliases_for_global_root(&global_name);
                Ok(())
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(format!(
                    "cannot write offset on {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn append_nested_array_value(
        array: &mut PhpArray,
        keys: &[ArrayKey],
        value: Value,
        span: Span,
    ) -> CompileResult<()> {
        let Some((key, rest)) = keys.split_first() else {
            array
                .append(value)
                .map_err(|error| runtime_error(span, error))?;
            return Ok(());
        };

        let mut child = match array.get_cloned(key.clone()) {
            Some(Value::Array(child)) => child,
            Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot write offset on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        Self::append_nested_array_value(&mut child, rest, value, span)?;
        array.insert(key.clone(), Value::Array(child));
        Ok(())
    }

    fn evaluate_list_assignment(
        &mut self,
        items: &[ListAssignmentItem],
        expr: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let value = self.evaluate(expr, scope)?;
        let mut assignments = Vec::new();
        self.collect_list_assignment_writes(items, &value, span, &mut assignments)?;

        for (name, element) in assignments {
            scope.write_static(&name, element);
        }

        Ok(value)
    }

    fn collect_list_assignment_writes(
        &mut self,
        items: &[ListAssignmentItem],
        source: &Value,
        span: Span,
        assignments: &mut Vec<(String, Value)>,
    ) -> CompileResult<()> {
        for (index, item) in items.iter().enumerate() {
            let Some(target) = item.target.as_ref() else {
                continue;
            };
            let key = Self::list_assignment_item_key(item.key.as_ref(), index);
            let element = self.read_list_assignment_element(source, &key, span)?;
            match target {
                ListAssignmentTarget::Variable { name, .. } => {
                    assignments.push((name.clone(), element));
                }
                ListAssignmentTarget::List { items, .. } => {
                    self.collect_list_assignment_writes(items, &element, span, assignments)?;
                }
            }
        }
        Ok(())
    }

    fn list_assignment_item_key(
        key: Option<&ListAssignmentKey>,
        positional_index: usize,
    ) -> ArrayKey {
        match key {
            Some(ListAssignmentKey::Int(value)) => ArrayKey::Int(*value),
            Some(ListAssignmentKey::String(value)) => ArrayKey::String(value.clone()),
            None => ArrayKey::Int(positional_index as i64),
        }
    }

    fn read_list_assignment_element(
        &mut self,
        source: &Value,
        key: &ArrayKey,
        span: Span,
    ) -> CompileResult<Value> {
        match source {
            Value::Array(array) => {
                if let Some(value) = array.get_cloned(key.clone()) {
                    Ok(value)
                } else {
                    self.emit_display_warning(
                        format!("Undefined array key {}", key.diagnostic_key()),
                        span,
                    )?;
                    Ok(Value::Null)
                }
            }
            Value::Null => Ok(Value::Null),
            Value::Object(object)
                if !self
                    .classes
                    .implements_interface(object.class_id(), "ArrayAccess") =>
            {
                Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "Cannot use object of type {} as array",
                        object.class_name()
                    )),
                ))
            }
            Value::Closure(_) => Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "Cannot use object of type Closure as array".to_string(),
                ),
            )),
            other => {
                self.emit_display_warning(
                    format!("Cannot use {} as array", other.type_name()),
                    span,
                )?;
                Ok(Value::Null)
            }
        }
    }

    fn execute_compound_assignment(
        &mut self,
        target: &AssignTarget,
        op: CompoundAssignOp,
        expr: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        self.evaluate_compound_assignment(target, op, expr, span, scope)
            .map(|_| ())
    }

    fn evaluate_compound_assignment(
        &mut self,
        target: &AssignTarget,
        op: CompoundAssignOp,
        expr: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let (place, left) = self.read_compound_assignment_left(target, span, scope)?;
        let right = self.evaluate(expr, scope)?;
        let value = self.apply_compound_assignment_op(left, op, right, span, scope)?;
        self.write_compound_assignment_place(place, value.clone(), span, scope)?;
        Ok(value)
    }

    fn read_compound_assignment_left(
        &mut self,
        target: &AssignTarget,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(CompoundAssignmentPlace, Value)> {
        match target {
            AssignTarget::Variable { name, .. } => Ok((
                CompoundAssignmentPlace::Variable(name.clone()),
                scope.read_static(name, span)?,
            )),
            AssignTarget::List { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "compound assignment",
                    "list destructuring targets are not implemented",
                ),
            )),
            AssignTarget::ArrayIndex {
                name,
                index: Some(index),
                ..
            } => {
                let key = self.evaluate_array_key(index, scope)?;
                match scope.read_named(name) {
                    Some(Value::Array(array)) => {
                        let value = array.get_cloned(key.clone()).ok_or_else(|| {
                            runtime_error(
                                span,
                                RuntimeError::undefined_array_key(key.diagnostic_key()),
                            )
                        })?;
                        Ok((
                            CompoundAssignmentPlace::ArrayIndex {
                                name: name.clone(),
                                key,
                            },
                            value,
                        ))
                    }
                    Some(Value::Object(object)) => {
                        let value = self.call_array_access_method_with_caller_scope(
                            object,
                            "offsetGet",
                            vec![Self::array_key_value(Some(key.clone()))],
                            span,
                            scope,
                        )?;
                        Ok((
                            CompoundAssignmentPlace::ArrayAccessOffset {
                                name: name.clone(),
                                key,
                            },
                            value,
                        ))
                    }
                    Some(other) => Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot read offset from {}",
                            other.type_name()
                        )),
                    )),
                    None => Err(runtime_error(span, RuntimeError::undefined_variable(name))),
                }
            }
            AssignTarget::NestedArrayIndex { name, indices, .. } => match scope.read_named(name) {
                Some(Value::String(_)) => {
                    if let Some(first_index) = indices.first() {
                        let _ = self.evaluate_string_offset_index(first_index, scope)?;
                    }
                    Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(
                            "Cannot use string offset as an array".to_string(),
                        ),
                    ))
                }
                Some(Value::Object(object))
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess") =>
                {
                    let keys = indices
                        .iter()
                        .map(|index| self.evaluate_array_key(index, scope))
                        .collect::<CompileResult<Vec<_>>>()?;
                    self.read_array_access_nested_compound_assignment_left(
                        object, keys, span, scope,
                    )
                }
                Some(Value::Array(_)) => Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "compound assignment",
                        "nested array targets are not implemented",
                    ),
                )),
                Some(other) => Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot read offset from {}",
                        other.type_name()
                    )),
                )),
                None => Err(runtime_error(span, RuntimeError::undefined_variable(name))),
            },
            AssignTarget::NestedArrayAppend { .. }
            | AssignTarget::StaticPropertyArrayIndex { .. }
            | AssignTarget::StaticPropertyArrayAppend { .. }
            | AssignTarget::NonDirectObjectPropertyArrayAppend { .. }
            | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { .. }
            | AssignTarget::ObjectPropertyArrayAppend { .. }
            | AssignTarget::DynamicObjectPropertyArrayAppend { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "compound assignment",
                    "nested array targets are not implemented",
                ),
            )),
            AssignTarget::ObjectPropertyArrayIndex {
                object,
                property,
                indices,
                ..
            } => {
                let keys = indices
                    .iter()
                    .map(|index| self.evaluate_array_key(index, scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                match scope.read_static(object, span)? {
                    Value::Object(object_value) => {
                        let (current_class_id, protected_class_ids) =
                            self.current_property_access_context();
                        let property_value = object_value
                            .read_property_from_context(
                                property,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        if let Value::Object(array_access_object) = property_value.clone() {
                            if keys.len() == 1
                                && self.classes.implements_interface(
                                    array_access_object.class_id(),
                                    "ArrayAccess",
                                )
                            {
                                let left = self.call_array_access_method_with_caller_scope(
                                    array_access_object,
                                    "offsetGet",
                                    vec![Self::array_key_value(Some(keys[0].clone()))],
                                    span,
                                    scope,
                                )?;
                                return Ok((
                                    CompoundAssignmentPlace::ObjectPropertyArrayAccessOffset {
                                        object: object.clone(),
                                        property: property.clone(),
                                        key: keys[0].clone(),
                                    },
                                    left,
                                ));
                            }
                        }
                        let Value::Array(array) = property_value else {
                            return Err(runtime_error(
                                span,
                                RuntimeError::invalid_array_access(format!(
                                    "cannot read offset from {}",
                                    property_value.type_name()
                                )),
                            ));
                        };
                        let left = Self::read_nested_array_value(&array, &keys, span)?;
                        Ok((
                            CompoundAssignmentPlace::ObjectPropertyArrayIndex {
                                object: object.clone(),
                                property: property.clone(),
                                keys,
                            },
                            left,
                        ))
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_property_access(format!(
                            "cannot read property ${property} from {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            AssignTarget::DynamicObjectPropertyArrayIndex {
                object,
                property,
                indices,
                ..
            } => {
                let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                let target = AssignTarget::ObjectPropertyArrayIndex {
                    object: object.clone(),
                    property,
                    indices: indices.clone(),
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::NonDirectObjectPropertyArrayIndex {
                holder,
                property,
                indices,
                ..
            } => {
                let temp_name =
                    self.non_direct_object_holder_temp(holder, property, scope, span)?;
                let target = AssignTarget::ObjectPropertyArrayIndex {
                    object: temp_name,
                    property: property.clone(),
                    indices: indices.clone(),
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
                holder,
                property,
                indices,
                ..
            } => {
                let source_snapshot = scope.public_array_copy_source_snapshot();
                let holder_value = self.evaluate(holder, scope)?;
                scope.restore_unchanged_public_array_copy_sources(source_snapshot);
                let holder_object = match holder_value {
                    Value::Object(object) => object,
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::invalid_property_access(format!(
                                "cannot read dynamic property from {}",
                                other.type_name()
                            )),
                        ));
                    }
                };
                let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                let temp_name = self.next_foreach_temporary_array_name();
                scope.write_static(&temp_name, Value::Object(holder_object));
                let target = AssignTarget::ObjectPropertyArrayIndex {
                    object: temp_name,
                    property,
                    indices: indices.clone(),
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::ArrayIndex { index: None, .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "compound assignment",
                    "append-offset targets are not implemented",
                ),
            )),
            AssignTarget::Property {
                object, property, ..
            } => match scope.read_named(object) {
                Some(Value::Object(value)) => {
                    let (current_class_id, protected_class_ids) =
                        self.current_property_access_context();
                    let left = self.read_object_property_for_read_modify_write(
                        &value,
                        property,
                        current_class_id,
                        &protected_class_ids,
                        span,
                    )?;
                    Ok((
                        CompoundAssignmentPlace::ObjectProperty {
                            object: object.clone(),
                            property: property.clone(),
                        },
                        left,
                    ))
                }
                Some(other) => Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} from {}",
                        other.type_name()
                    )),
                )),
                None => Err(runtime_error(
                    span,
                    RuntimeError::undefined_variable(object),
                )),
            },
            AssignTarget::DynamicProperty {
                object, property, ..
            } => {
                let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                let target = AssignTarget::Property {
                    object: object.clone(),
                    property,
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::NonDirectProperty {
                holder, property, ..
            } => {
                let temp_name =
                    self.non_direct_object_holder_temp(holder, property, scope, span)?;
                let target = AssignTarget::Property {
                    object: temp_name,
                    property: property.clone(),
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::NonDirectDynamicProperty {
                holder, property, ..
            } => {
                let source_snapshot = scope.public_array_copy_source_snapshot();
                let holder_value = self.evaluate(holder, scope)?;
                scope.restore_unchanged_public_array_copy_sources(source_snapshot);
                let holder_object = match holder_value {
                    Value::Object(object) => object,
                    other => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::invalid_property_access(format!(
                                "cannot read dynamic property from {}",
                                other.type_name()
                            )),
                        ));
                    }
                };
                let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                let temp_name = self.next_foreach_temporary_array_name();
                scope.write_static(&temp_name, Value::Object(holder_object));
                let target = AssignTarget::Property {
                    object: temp_name,
                    property,
                    span,
                };
                self.read_compound_assignment_left(&target, span, scope)
            }
            AssignTarget::ObjectStaticProperty { .. }
            | AssignTarget::DynamicObjectStaticProperty { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "compound assignment",
                    "dynamic static property targets are not implemented",
                ),
            )),
            AssignTarget::StaticProperty { .. }
            | AssignTarget::DynamicStaticProperty { .. }
            | AssignTarget::SelfStaticProperty { .. }
            | AssignTarget::DynamicSelfStaticProperty { .. }
            | AssignTarget::ParentStaticProperty { .. }
            | AssignTarget::DynamicParentStaticProperty { .. }
            | AssignTarget::LateStaticProperty { .. }
            | AssignTarget::DynamicLateStaticProperty { .. } => {
                let (declaring_class_id, property, value) =
                    self.read_static_property_target(target, span)?;
                Ok((
                    CompoundAssignmentPlace::StaticProperty {
                        declaring_class_id,
                        property,
                    },
                    value,
                ))
            }
            AssignTarget::UnsupportedExpression { message, span } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call("compound assignment target", message),
            )),
        }
    }

    fn read_array_access_nested_compound_assignment_left(
        &mut self,
        object: PhpObject,
        keys: Vec<ArrayKey>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(CompoundAssignmentPlace, Value)> {
        let Some((first_key, rest_keys)) = keys.split_first() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "compound assignment",
                    "nested ArrayAccess assignment requires at least one key",
                ),
            ));
        };

        let (first_value, first_source) = self
            .call_array_access_offset_get_with_array_copy_source(
                object.clone(),
                Self::array_key_value(Some(first_key.clone())),
                span,
                scope,
            )?;
        if rest_keys.is_empty() {
            let hidden_name = self.hidden_array_access_reference_object_name(&object);
            scope.write_static(&hidden_name, Value::Object(object));
            return Ok((
                CompoundAssignmentPlace::ArrayAccessOffset {
                    name: hidden_name,
                    key: first_key.clone(),
                },
                first_value,
            ));
        }

        let first_source = if matches!(first_value, Value::Array(_)) {
            first_source
        } else {
            None
        };
        let first_value = scope.value_with_object_property_aliases_from_array_copy(
            first_value,
            first_source,
            true,
        );

        if let Value::Object(nested_object) = &first_value {
            if self
                .classes
                .implements_interface(nested_object.class_id(), "ArrayAccess")
            {
                let Some((nested_key, nested_rest)) = rest_keys.split_first() else {
                    unreachable!("rest_keys is not empty");
                };
                if nested_rest.is_empty() {
                    let value = self.call_array_access_method_with_caller_scope(
                        nested_object.clone(),
                        "offsetGet",
                        vec![Self::array_key_value(Some(nested_key.clone()))],
                        span,
                        scope,
                    )?;
                    let hidden_name = self.hidden_array_access_reference_object_name(nested_object);
                    scope.write_static(&hidden_name, Value::Object(nested_object.clone()));
                    return Ok((
                        CompoundAssignmentPlace::ArrayAccessOffset {
                            name: hidden_name,
                            key: nested_key.clone(),
                        },
                        value,
                    ));
                }
                return self.read_array_access_nested_compound_assignment_left(
                    nested_object.clone(),
                    rest_keys.to_vec(),
                    span,
                    scope,
                );
            }
        }

        let class_name = object.class_name().to_string();
        self.emit_array_access_indirect_modification_notice(&class_name, span)?;
        self.reject_by_value_array_access_scalar_parent_for_nested_write(
            &first_value,
            rest_keys,
            false,
            span,
        )?;
        let left = if let Value::Array(array) = first_value {
            Self::read_nested_array_value(&array, rest_keys, span)?
        } else {
            Value::Null
        };
        Ok((CompoundAssignmentPlace::ArrayAccessTemporary, left))
    }

    fn read_object_property_for_read_modify_write(
        &mut self,
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        span: Span,
    ) -> CompileResult<Value> {
        match object.read_property_from_context(property, current_class_id, protected_class_ids) {
            Ok(value) => Ok(value),
            Err(error) if Self::is_undefined_property_error(&error) => {
                if object
                    .is_unset_untyped_declared_property_from_context(
                        property,
                        current_class_id,
                        protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))?
                {
                    self.emit_undefined_property_warning(object.class_name(), property, span)?;
                    Ok(Value::Null)
                } else {
                    Err(runtime_error(span, error))
                }
            }
            Err(error) => Err(runtime_error(span, error)),
        }
    }

    fn write_compound_assignment_place(
        &mut self,
        place: CompoundAssignmentPlace,
        value: Value,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        match place {
            CompoundAssignmentPlace::Variable(name) => {
                scope.write_static_checked_with_object_type_resolver(
                    &name,
                    value,
                    span,
                    |object, type_name| self.object_satisfies_live_property_type(object, type_name),
                )?;
                Ok(())
            }
            CompoundAssignmentPlace::ArrayIndex { name, key } => match scope.read_named(&name) {
                Some(Value::Array(mut array)) => {
                    array
                        .insert_checked_with_object_type_resolver(
                            key,
                            value,
                            |object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )
                        .map_err(|error| runtime_error(span, error))?;
                    scope.write_static(&name, Value::Array(array));
                    Ok(())
                }
                Some(other) => Err(runtime_error(
                    span,
                    RuntimeError::invalid_array_access(format!(
                        "cannot write offset on {}",
                        other.type_name()
                    )),
                )),
                None => Err(runtime_error(span, RuntimeError::undefined_variable(name))),
            },
            CompoundAssignmentPlace::ArrayAccessOffset { name, key } => {
                match scope.read_named(&name) {
                    Some(Value::Object(object)) => self
                        .call_array_access_method_with_caller_scope(
                            object,
                            "offsetSet",
                            vec![Self::array_key_value(Some(key)), value],
                            span,
                            scope,
                        )
                        .map(|_| ()),
                    Some(other) => Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot write offset on {}",
                            other.type_name()
                        )),
                    )),
                    None => Err(runtime_error(span, RuntimeError::undefined_variable(name))),
                }
            }
            CompoundAssignmentPlace::ArrayAccessTemporary => Ok(()),
            CompoundAssignmentPlace::ObjectPropertyArrayAccessOffset {
                object,
                property,
                key,
            } => {
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                match scope.read_static(&object, span)? {
                    Value::Object(object) => {
                        let property_value = object
                            .read_property_from_context(
                                &property,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        match property_value {
                            Value::Object(array_access_object) => self
                                .call_array_access_method_with_caller_scope(
                                    array_access_object,
                                    "offsetSet",
                                    vec![Self::array_key_value(Some(key)), value],
                                    span,
                                    scope,
                                )
                                .map(|_| ()),
                            other => Err(runtime_error(
                                span,
                                RuntimeError::invalid_array_access(format!(
                                    "cannot write offset on {}",
                                    other.type_name()
                                )),
                            )),
                        }
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_property_access(format!(
                            "cannot write property ${property} on {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            CompoundAssignmentPlace::ObjectProperty { object, property } => {
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                match scope.read_static(&object, span)? {
                    Value::Object(object_value) => {
                        let boundary = scope.object_property_holder_storage_boundary(
                            &object,
                            &object_value,
                            &property,
                            &[],
                            current_class_id,
                            &protected_class_ids,
                        );
                        scope.pre_replace_holder_storage(&boundary);
                        let alias_fallbacks =
                            scope.public_object_property_root_alias_fallbacks(&object, &property);
                        object_value
                            .write_property_from_context(
                                &property,
                                value,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        scope.post_replace_holder_storage(&boundary);
                        scope.remove_public_object_property_root_from_array_offset_aliases(
                            &object,
                            &property,
                            &alias_fallbacks,
                        );
                        scope
                            .sync_array_offset_aliases_for_object_property_root(&object, &property);
                        Ok(())
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_property_access(format!(
                            "cannot write property ${property} on {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            CompoundAssignmentPlace::ObjectPropertyArrayIndex {
                object,
                property,
                keys,
            } => {
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                match scope.read_static(&object, span)? {
                    Value::Object(object_value) => {
                        let mut property_value = object_value
                            .read_property_from_context(
                                &property,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        let Value::Array(array) = &mut property_value else {
                            return Err(runtime_error(
                                span,
                                RuntimeError::invalid_array_access(format!(
                                    "cannot write offset on {}",
                                    property_value.type_name()
                                )),
                            ));
                        };
                        let boundary = scope.object_property_holder_storage_boundary(
                            &object,
                            &object_value,
                            &property,
                            &keys,
                            current_class_id,
                            &protected_class_ids,
                        );
                        scope.pre_replace_holder_storage(&boundary);
                        self.write_nested_array_value(array, &keys, value, span)?;
                        object_value
                            .write_property_from_context(
                                &property,
                                property_value,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        scope.post_replace_holder_storage(&boundary);
                        scope
                            .sync_array_offset_aliases_for_object_property_root(&object, &property);
                        Ok(())
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_property_access(format!(
                            "cannot write property ${property} on {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            CompoundAssignmentPlace::StaticProperty {
                declaring_class_id,
                property,
            } => {
                if let Some(cell) = self
                    .static_properties
                    .get(&(declaring_class_id, property.clone()))
                {
                    cell.set_value(value);
                } else {
                    self.static_properties
                        .insert((declaring_class_id, property), VariableCell::new(value));
                }
                Ok(())
            }
        }
    }

    fn apply_compound_assignment_op(
        &mut self,
        left: Value,
        op: CompoundAssignOp,
        right: Value,
        span: Span,
        scope: &SymbolTable,
    ) -> CompileResult<Value> {
        if matches!(op, CompoundAssignOp::Concat) {
            let mut bytes = self.value_to_echo_bytes(left, span)?;
            bytes.extend(self.value_to_echo_bytes(right, span)?);
            return Ok(interpreter_value_from_php_string_bytes(bytes));
        }

        self.emit_float_string_to_int_compound_deprecations(op, &left, &right, span)?;

        if let Some(binary_op) = Self::compound_assignment_bcmath_binary_op(op) {
            if let Some(result) =
                self.apply_bcmath_number_binary_operator(binary_op, &left, &right, span, scope)?
            {
                return Ok(result);
            }
        }

        let value = match op {
            CompoundAssignOp::Add => left.php_add(&right),
            CompoundAssignOp::Sub => left.php_sub(&right),
            CompoundAssignOp::Mul => left.php_mul(&right),
            CompoundAssignOp::Div => left.php_div(&right),
            CompoundAssignOp::Mod => left.php_mod(&right),
            CompoundAssignOp::Pow => {
                if let Some(result) = self.apply_bcmath_number_binary_operator(
                    BinaryOp::Pow,
                    &left,
                    &right,
                    span,
                    scope,
                )? {
                    return Ok(result);
                }
                return php_pow_result(self, &left, &right, span);
            }
            CompoundAssignOp::Concat => {
                unreachable!("concatenation is handled before runtime helpers")
            }
            CompoundAssignOp::BitwiseAnd => left.php_bitwise_and(&right),
            CompoundAssignOp::BitwiseOr => left.php_bitwise_or(&right),
            CompoundAssignOp::BitwiseXor => left.php_bitwise_xor(&right),
            CompoundAssignOp::ShiftLeft => left.php_shift_left(&right),
            CompoundAssignOp::ShiftRight => left.php_shift_right(&right),
        };

        value.map_err(|error| runtime_error(span, error))
    }

    fn compound_assignment_bcmath_binary_op(op: CompoundAssignOp) -> Option<BinaryOp> {
        match op {
            CompoundAssignOp::Add => Some(BinaryOp::Add),
            CompoundAssignOp::Sub => Some(BinaryOp::Sub),
            CompoundAssignOp::Mul => Some(BinaryOp::Mul),
            CompoundAssignOp::Div => Some(BinaryOp::Div),
            CompoundAssignOp::Mod => Some(BinaryOp::Mod),
            CompoundAssignOp::Pow => Some(BinaryOp::Pow),
            _ => None,
        }
    }

    fn emit_float_string_to_int_compound_deprecations(
        &mut self,
        op: CompoundAssignOp,
        left: &Value,
        right: &Value,
        span: Span,
    ) -> CompileResult<()> {
        let should_check = match op {
            CompoundAssignOp::Mod | CompoundAssignOp::ShiftLeft | CompoundAssignOp::ShiftRight => {
                true
            }
            CompoundAssignOp::BitwiseAnd
            | CompoundAssignOp::BitwiseOr
            | CompoundAssignOp::BitwiseXor => {
                !(value_is_string_like(left) && value_is_string_like(right))
            }
            _ => false,
        };
        if !should_check {
            return Ok(());
        }

        self.emit_float_string_to_int_deprecation_for_value(left, span)?;
        self.emit_float_string_to_int_deprecation_for_value(right, span)
    }

    fn execute_increment_decrement(
        &mut self,
        target: &AssignTarget,
        op: IncrementDecrementOp,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        let (place, value) = self.read_increment_decrement_left(target, span, scope)?;
        let updated = self.increment_decrement_value(value, op, span)?;
        self.write_compound_assignment_place(place, updated, span, scope)?;
        Ok(())
    }

    fn evaluate_increment_decrement(
        &mut self,
        target: &AssignTarget,
        op: IncrementDecrementOp,
        position: IncrementDecrementPosition,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let (place, previous) = self.read_increment_decrement_left(target, span, scope)?;
        let updated = self.increment_decrement_value(previous.clone(), op, span)?;
        self.write_compound_assignment_place(place, updated.clone(), span, scope)?;

        Ok(match position {
            IncrementDecrementPosition::Pre => updated,
            IncrementDecrementPosition::Post => previous,
        })
    }

    fn read_increment_decrement_left(
        &mut self,
        target: &AssignTarget,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(CompoundAssignmentPlace, Value)> {
        match target {
            AssignTarget::Variable { name, .. } => {
                let value = if let Some(value) = scope.read_named(name) {
                    value.clone()
                } else {
                    self.emit_undefined_variable_warning(name, span)?;
                    Value::Null
                };
                Ok((CompoundAssignmentPlace::Variable(name.clone()), value))
            }
            AssignTarget::List { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "increment/decrement",
                    "list destructuring targets are not implemented",
                ),
            )),
            AssignTarget::ArrayIndex {
                name,
                index: Some(index),
                ..
            } => {
                let key = self.evaluate_array_key(index, scope)?;
                match scope.read_named(name) {
                    Some(Value::Array(array)) => {
                        let value = array.get_cloned(key.clone()).ok_or_else(|| {
                            runtime_error(
                                span,
                                RuntimeError::undefined_array_key(key.diagnostic_key()),
                            )
                        })?;
                        Ok((
                            CompoundAssignmentPlace::ArrayIndex {
                                name: name.clone(),
                                key,
                            },
                            value,
                        ))
                    }
                    Some(Value::Object(object)) => {
                        let class_name = object.class_name().to_string();
                        let value = self.call_array_access_method_with_caller_scope(
                            object,
                            "offsetGet",
                            vec![Self::array_key_value(Some(key))],
                            span,
                            scope,
                        )?;
                        self.emit_array_access_indirect_modification_notice(&class_name, span)?;
                        Ok((CompoundAssignmentPlace::ArrayAccessTemporary, value))
                    }
                    Some(other) => Err(runtime_error(
                        span,
                        RuntimeError::invalid_array_access(format!(
                            "cannot read offset from {}",
                            other.type_name()
                        )),
                    )),
                    None => Err(runtime_error(span, RuntimeError::undefined_variable(name))),
                }
            }
            AssignTarget::NestedArrayIndex { .. }
            | AssignTarget::NestedArrayAppend { .. }
            | AssignTarget::StaticPropertyArrayIndex { .. }
            | AssignTarget::StaticPropertyArrayAppend { .. }
            | AssignTarget::DynamicObjectPropertyArrayIndex { .. }
            | AssignTarget::NonDirectObjectPropertyArrayIndex { .. }
            | AssignTarget::NonDirectObjectPropertyArrayAppend { .. }
            | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex { .. }
            | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { .. }
            | AssignTarget::ObjectPropertyArrayAppend { .. }
            | AssignTarget::DynamicObjectPropertyArrayAppend { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "increment/decrement",
                    "nested array targets are not implemented",
                ),
            )),
            AssignTarget::ObjectPropertyArrayIndex {
                object,
                property,
                indices,
                ..
            } => {
                let keys = indices
                    .iter()
                    .map(|index| self.evaluate_array_key(index, scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                if keys.len() != 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "increment/decrement",
                            "nested array targets are not implemented",
                        ),
                    ));
                }
                match scope.read_static(object, span)? {
                    Value::Object(object_value) => {
                        let (current_class_id, protected_class_ids) =
                            self.current_property_access_context();
                        let property_value = object_value
                            .read_property_from_context(
                                property,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(span, error))?;
                        match property_value {
                            Value::Object(array_access_object) => {
                                let class_name = array_access_object.class_name().to_string();
                                let value = self.call_array_access_method_with_caller_scope(
                                    array_access_object,
                                    "offsetGet",
                                    vec![Self::array_key_value(Some(keys[0].clone()))],
                                    span,
                                    scope,
                                )?;
                                self.emit_array_access_indirect_modification_notice(
                                    &class_name,
                                    span,
                                )?;
                                Ok((CompoundAssignmentPlace::ArrayAccessTemporary, value))
                            }
                            _ => Err(runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    "increment/decrement",
                                    "nested array targets are not implemented",
                                ),
                            )),
                        }
                    }
                    other => Err(runtime_error(
                        span,
                        RuntimeError::invalid_property_access(format!(
                            "cannot read property ${property} from {}",
                            other.type_name()
                        )),
                    )),
                }
            }
            AssignTarget::ArrayIndex { index: None, .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "increment/decrement",
                    "append-offset targets are not implemented",
                ),
            )),
            AssignTarget::Property {
                object, property, ..
            } => match scope.read_named(object) {
                Some(Value::Object(value)) => {
                    let (current_class_id, protected_class_ids) =
                        self.current_property_access_context();
                    let left = self.read_object_property_for_read_modify_write(
                        &value,
                        property,
                        current_class_id,
                        &protected_class_ids,
                        span,
                    )?;
                    Ok((
                        CompoundAssignmentPlace::ObjectProperty {
                            object: object.clone(),
                            property: property.clone(),
                        },
                        left,
                    ))
                }
                Some(other) => Err(runtime_error(
                    span,
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} from {}",
                        other.type_name()
                    )),
                )),
                None => Err(runtime_error(
                    span,
                    RuntimeError::undefined_variable(object),
                )),
            },
            AssignTarget::DynamicProperty { .. }
            | AssignTarget::NonDirectProperty { .. }
            | AssignTarget::NonDirectDynamicProperty { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "increment/decrement",
                    "dynamic property targets are not implemented",
                ),
            )),
            AssignTarget::ObjectStaticProperty { .. }
            | AssignTarget::DynamicObjectStaticProperty { .. } => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "increment/decrement",
                    "dynamic static property targets are not implemented",
                ),
            )),
            AssignTarget::StaticProperty { .. }
            | AssignTarget::DynamicStaticProperty { .. }
            | AssignTarget::SelfStaticProperty { .. }
            | AssignTarget::DynamicSelfStaticProperty { .. }
            | AssignTarget::ParentStaticProperty { .. }
            | AssignTarget::DynamicParentStaticProperty { .. }
            | AssignTarget::LateStaticProperty { .. }
            | AssignTarget::DynamicLateStaticProperty { .. } => {
                let (declaring_class_id, property, value) =
                    self.read_static_property_target(target, span)?;
                Ok((
                    CompoundAssignmentPlace::StaticProperty {
                        declaring_class_id,
                        property,
                    },
                    value,
                ))
            }
            AssignTarget::UnsupportedExpression { message, span } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call("increment/decrement target", message),
            )),
        }
    }

    fn increment_decrement_value(
        &mut self,
        value: Value,
        op: IncrementDecrementOp,
        span: Span,
    ) -> CompileResult<Value> {
        Ok(match (value, op) {
            (Value::Int(value), op) => increment_decrement_integer_value(value, op),
            (Value::Float(value), IncrementDecrementOp::Increment) => Value::Float(value + 1.0),
            (Value::Float(value), IncrementDecrementOp::Decrement) => Value::Float(value - 1.0),
            (Value::Null, IncrementDecrementOp::Increment) => Value::Int(1),
            (Value::Null, IncrementDecrementOp::Decrement) => {
                self.emit_display_warning(
                    "Decrement on type null has no effect, this will change in the next major version of PHP",
                    span,
                )?;
                Value::Null
            }
            (Value::Bool(value), op) => {
                self.emit_display_warning(
                    format!(
                        "{} on type bool has no effect, this will change in the next major version of PHP",
                        increment_decrement_operation_name(op),
                    ),
                    span,
                )?;
                Value::Bool(value)
            }
            (Value::String(value), op) => {
                self.increment_decrement_string_value(value.into_bytes(), op, span)?
            }
            (Value::BinaryString(value), op) => {
                self.increment_decrement_string_value(value, op, span)?
            }
            (Value::Array(_), op) => {
                return Err(increment_decrement_type_error(op, "array", span));
            }
            (Value::Object(object), op) => {
                if object.class_name().eq_ignore_ascii_case("BcMath\\Number") {
                    let decimal = self.bcmath_number_object_decimal(&object, span)?;
                    let one = BcDecimal::one();
                    let updated = match op {
                        IncrementDecrementOp::Increment => decimal.add(&one),
                        IncrementDecrementOp::Decrement => decimal.sub(&one),
                    };
                    return self
                        .bcmath_number_object(updated, None, span)
                        .map(Value::Object);
                }
                return Err(increment_decrement_type_error(
                    op,
                    object.class_name(),
                    span,
                ));
            }
            (Value::Closure(_), op) => {
                return Err(increment_decrement_type_error(op, "Closure", span));
            }
            (Value::Resource(_), op) => {
                return Err(increment_decrement_type_error(op, "resource", span));
            }
        })
    }

    fn increment_decrement_string_value(
        &mut self,
        bytes: Vec<u8>,
        op: IncrementDecrementOp,
        span: Span,
    ) -> CompileResult<Value> {
        if let Ok(value) = std::str::from_utf8(&bytes) {
            match classify_php_numeric_string(value) {
                PhpNumericStringClassification::Integer(value) => {
                    return Ok(increment_decrement_integer_value(value, op));
                }
                PhpNumericStringClassification::Float(value) => {
                    return Ok(match op {
                        IncrementDecrementOp::Increment => Value::Float(value + 1.0),
                        IncrementDecrementOp::Decrement => Value::Float(value - 1.0),
                    });
                }
                PhpNumericStringClassification::LeadingNumeric
                | PhpNumericStringClassification::NonNumeric => {}
            }
        }

        let message = match op {
            IncrementDecrementOp::Increment => {
                "Increment on non-numeric string is deprecated, use str_increment() instead"
            }
            IncrementDecrementOp::Decrement if bytes.is_empty() => {
                "Decrement on empty string is deprecated as non-numeric"
            }
            IncrementDecrementOp::Decrement => {
                "Decrement on non-numeric string has no effect and is deprecated"
            }
        };
        self.emit_display_diagnostic("Deprecated", PHP_E_DEPRECATED, message, span)?;

        Ok(match op {
            IncrementDecrementOp::Increment => {
                interpreter_value_from_php_string_bytes(php_legacy_string_increment_bytes(&bytes))
            }
            IncrementDecrementOp::Decrement if bytes.is_empty() => Value::Int(-1),
            IncrementDecrementOp::Decrement => interpreter_value_from_php_string_bytes(bytes),
        })
    }

    fn evaluate_null_coalesce_assignment(
        &mut self,
        target: &AssignTarget,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match target {
            AssignTarget::Variable { name, .. } => {
                if let Some(value) = scope.read_named(name) {
                    if !matches!(value, Value::Null) {
                        return Ok(value.clone());
                    }
                }
                let (value, array_copy_source) =
                    self.evaluate_value_with_array_copy_source(expr, scope)?;
                let assigned_array_copy_source = if matches!(value, Value::Array(_)) {
                    array_copy_source.or_else(|| {
                        self.public_object_property_array_copy_source_for_value_expr(expr, scope)
                    })
                } else {
                    None
                };
                scope.write_static(name, value.clone());
                if let Some(source) = assigned_array_copy_source {
                    scope.record_public_object_property_array_copy_source(name, source);
                }
                Ok(value)
            }
            AssignTarget::List { span, .. } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call(
                    "??=",
                    "list destructuring targets are not implemented",
                ),
            )),
            AssignTarget::ArrayIndex {
                name,
                index: Some(index),
                span,
            } => {
                if let Some(Value::Object(object)) = scope.read_named(name) {
                    if self.is_spl_object_storage_object(&object) {
                        let offset_arg = self.evaluate(index, scope)?;
                        let exists = self
                            .call_array_access_method_with_caller_scope(
                                object.clone(),
                                "offsetExists",
                                vec![offset_arg.clone()],
                                *span,
                                scope,
                            )?
                            .is_truthy();
                        if exists {
                            let current = self.call_array_access_method_with_caller_scope(
                                object.clone(),
                                "offsetGet",
                                vec![offset_arg.clone()],
                                *span,
                                scope,
                            )?;
                            if !matches!(current, Value::Null) {
                                return Ok(current);
                            }
                        }
                        let value = self.evaluate(expr, scope)?;
                        self.call_array_access_method_with_caller_scope(
                            object,
                            "offsetSet",
                            vec![offset_arg, value.clone()],
                            *span,
                            scope,
                        )?;
                        return Ok(value);
                    }
                }
                let key = self.evaluate_array_key(index, scope)?;
                let should_assign = match scope.read_named(name) {
                    Some(Value::Array(array)) => match array.get_cloned(key.clone()) {
                        Some(value) if !matches!(value, Value::Null) => {
                            return Ok(value);
                        }
                        _ => true,
                    },
                    Some(Value::Null) | None => true,
                    Some(other) => {
                        return Err(runtime_error(
                            *span,
                            RuntimeError::invalid_array_access(format!(
                                "cannot write offset on {}",
                                other.type_name()
                            )),
                        ));
                    }
                };

                if should_assign {
                    let value = self.evaluate(expr, scope)?;
                    let mut slot = scope
                        .read_named(name)
                        .unwrap_or_else(|| Value::Array(PhpArray::new()));

                    if matches!(slot, Value::Null) {
                        slot = Value::Array(PhpArray::new());
                    }

                    match &mut slot {
                        Value::Array(array) => {
                            array
                                .insert_checked_with_object_type_resolver(
                                    key,
                                    value.clone(),
                                    |object, type_name| {
                                        self.object_satisfies_live_property_type(object, type_name)
                                    },
                                )
                                .map_err(|error| runtime_error(*span, error))?;
                            scope.write_static(name, slot);
                            Ok(value)
                        }
                        other => Err(runtime_error(
                            *span,
                            RuntimeError::invalid_array_access(format!(
                                "cannot write offset on {}",
                                other.type_name()
                            )),
                        )),
                    }
                } else {
                    unreachable!("non-null array entries return before assignment")
                }
            }
            AssignTarget::ArrayIndex {
                index: None, span, ..
            } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call("??=", "append-offset targets are not implemented"),
            )),
            AssignTarget::NestedArrayIndex { span, .. }
            | AssignTarget::NestedArrayAppend { span, .. }
            | AssignTarget::StaticPropertyArrayIndex { span, .. }
            | AssignTarget::StaticPropertyArrayAppend { span, .. }
            | AssignTarget::ObjectPropertyArrayIndex { span, .. }
            | AssignTarget::DynamicObjectPropertyArrayIndex { span, .. }
            | AssignTarget::NonDirectObjectPropertyArrayIndex { span, .. }
            | AssignTarget::NonDirectObjectPropertyArrayAppend { span, .. }
            | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex { span, .. }
            | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { span, .. }
            | AssignTarget::ObjectPropertyArrayAppend { span, .. }
            | AssignTarget::DynamicObjectPropertyArrayAppend { span, .. } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call("??=", "nested array targets are not implemented"),
            )),
            AssignTarget::Property {
                object,
                property,
                span,
            } => {
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                let should_assign = match scope.read_named(object) {
                    Some(Value::Object(object)) => {
                        match object
                            .read_property_for_isset_from_context(
                                property,
                                current_class_id,
                                &protected_class_ids,
                            )
                            .map_err(|error| runtime_error(*span, error))?
                        {
                            Some(value) if !matches!(value, Value::Null) => {
                                return Ok(value.clone());
                            }
                            Some(_) | None => true,
                        }
                    }
                    Some(_) | None => true,
                };

                if should_assign {
                    let value = self.evaluate(expr, scope)?;
                    match scope.read_static(object, *span)? {
                        Value::Object(object_value) => {
                            let boundary = scope.object_property_holder_storage_boundary(
                                object,
                                &object_value,
                                property,
                                &[],
                                current_class_id,
                                &protected_class_ids,
                            );
                            scope.pre_replace_holder_storage(&boundary);
                            let alias_fallbacks =
                                scope.public_object_property_root_alias_fallbacks(object, property);
                            object_value
                                .write_property_from_context(
                                    property,
                                    value.clone(),
                                    current_class_id,
                                    &protected_class_ids,
                                )
                                .map_err(|error| runtime_error(*span, error))?;
                            scope.post_replace_holder_storage(&boundary);
                            scope.remove_public_object_property_root_from_array_offset_aliases(
                                object,
                                property,
                                &alias_fallbacks,
                            );
                            scope.sync_array_offset_aliases_for_object_property_root(
                                object, property,
                            );
                            Ok(value)
                        }
                        other => Err(runtime_error(
                            *span,
                            RuntimeError::invalid_property_access(format!(
                                "cannot write property ${property} on {}",
                                other.type_name()
                            )),
                        )),
                    }
                } else {
                    unreachable!("non-null object properties return before assignment")
                }
            }
            AssignTarget::DynamicProperty {
                object,
                property,
                span,
            } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let target = AssignTarget::Property {
                    object: object.clone(),
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::NonDirectProperty {
                holder,
                property,
                span,
            } => {
                let temp_name =
                    self.non_direct_object_holder_temp(holder, property, scope, *span)?;
                let target = AssignTarget::Property {
                    object: temp_name,
                    property: property.clone(),
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::NonDirectDynamicProperty {
                holder,
                property,
                span,
            } => {
                let source_snapshot = scope.public_array_copy_source_snapshot();
                let holder_value = self.evaluate(holder, scope)?;
                scope.restore_unchanged_public_array_copy_sources(source_snapshot);
                let holder_object = match holder_value {
                    Value::Object(object) => object,
                    other => {
                        return Err(runtime_error(
                            *span,
                            RuntimeError::invalid_property_access(format!(
                                "cannot write dynamic property on {}",
                                other.type_name()
                            )),
                        ));
                    }
                };
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let temp_name = self.next_foreach_temporary_array_name();
                scope.write_static(&temp_name, Value::Object(holder_object));
                let target = AssignTarget::Property {
                    object: temp_name,
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::ObjectStaticProperty { span, .. } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call(
                    "??=",
                    "dynamic static property targets are not implemented",
                ),
            )),
            AssignTarget::DynamicObjectStaticProperty { span, .. } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call(
                    "??=",
                    "dynamic static property targets are not implemented",
                ),
            )),
            AssignTarget::StaticProperty { span, .. }
            | AssignTarget::SelfStaticProperty { span, .. }
            | AssignTarget::ParentStaticProperty { span, .. }
            | AssignTarget::LateStaticProperty { span, .. } => {
                let (declaring_class_id, property, current) =
                    self.read_static_property_target(target, *span)?;
                if !matches!(current, Value::Null) {
                    return Ok(current);
                }

                let value = self.evaluate(expr, scope)?;
                if let Some(cell) = self
                    .static_properties
                    .get(&(declaring_class_id, property.clone()))
                {
                    cell.set_value(value.clone());
                } else {
                    self.static_properties.insert(
                        (declaring_class_id, property),
                        VariableCell::new(value.clone()),
                    );
                }
                Ok(value)
            }
            AssignTarget::DynamicStaticProperty {
                class_name,
                property,
                span,
            } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let target = AssignTarget::StaticProperty {
                    class_name: class_name.clone(),
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::DynamicSelfStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let target = AssignTarget::SelfStaticProperty {
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::DynamicParentStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let target = AssignTarget::ParentStaticProperty {
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::DynamicLateStaticProperty { property, span } => {
                let property = self.evaluate_dynamic_property_name(property, *span, scope)?;
                let target = AssignTarget::LateStaticProperty {
                    property,
                    span: *span,
                };
                self.evaluate_null_coalesce_assignment(&target, expr, scope)
            }
            AssignTarget::UnsupportedExpression { message, span } => Err(runtime_error(
                *span,
                RuntimeError::unsupported_call("??= target", message),
            )),
        }
    }

    fn evaluate_global_constant(&mut self, name: &str, span: Span) -> CompileResult<Value> {
        if let Some(exact_name) = name.strip_prefix('\\') {
            let value = self
                .constants
                .get(exact_name)
                .ok_or_else(|| runtime_error(span, RuntimeError::undefined_constant(exact_name)))?;
            if let Some(metadata) = self.constants.metadata(exact_name).cloned() {
                self.emit_deprecated_global_constant_diagnostic(
                    exact_name,
                    &metadata.attributes,
                    span,
                )?;
            }
            self.emit_builtin_global_constant_deprecation(exact_name, span)?;
            return Ok(value);
        }

        if let Some(value) = self.constants.get(name) {
            if let Some(metadata) = self.constants.metadata(name).cloned() {
                self.emit_deprecated_global_constant_diagnostic(name, &metadata.attributes, span)?;
            }
            self.emit_builtin_global_constant_deprecation(name, span)?;
            return Ok(value);
        }

        if let Some((_, fallback_name)) = name.rsplit_once('\\') {
            if let Some(value) = self.constants.get(fallback_name) {
                if let Some(metadata) = self.constants.metadata(fallback_name).cloned() {
                    self.emit_deprecated_global_constant_diagnostic(
                        fallback_name,
                        &metadata.attributes,
                        span,
                    )?;
                }
                self.emit_builtin_global_constant_deprecation(fallback_name, span)?;
                return Ok(value);
            }
        }

        Err(runtime_error(span, RuntimeError::undefined_constant(name)))
    }

    fn emit_builtin_global_constant_deprecation(
        &mut self,
        name: &str,
        span: Span,
    ) -> CompileResult<()> {
        if name == "DATE_RFC7231" {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Constant DATE_RFC7231 is deprecated since 8.5, as this format ignores the associated timezone and always uses GMT",
                span,
            )?;
        }
        if matches!(
            name,
            "SUNFUNCS_RET_TIMESTAMP" | "SUNFUNCS_RET_STRING" | "SUNFUNCS_RET_DOUBLE"
        ) {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!(
                    "Constant {name} is deprecated since 8.4, as date_sunrise() and date_sunset() were deprecated in 8.1"
                ),
                span,
            )?;
        }
        if matches!(name, "FILTER_SANITIZE_STRING" | "FILTER_SANITIZE_STRIPPED") {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!("Constant {name} is deprecated since 8.1, use htmlspecialchars() instead"),
                span,
            )?;
        }
        if matches!(
            name,
            "ASSERT_ACTIVE"
                | "ASSERT_CALLBACK"
                | "ASSERT_BAIL"
                | "ASSERT_WARNING"
                | "ASSERT_EXCEPTION"
        ) {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!(
                    "Constant {name} is deprecated since 8.3, as assert_options() is deprecated"
                ),
                span,
            )?;
        }
        if name == "E_STRICT" {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Constant E_STRICT is deprecated since 8.4, the error level was removed",
                span,
            )?;
        }
        Ok(())
    }

    fn array_literal_next_auto_key(
        next_auto_index: &mut i64,
        auto_index_exhausted: &mut bool,
        span: Span,
    ) -> CompileResult<ArrayKey> {
        if *auto_index_exhausted {
            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_key("cannot append after maximum integer key"),
            ));
        }

        let key = ArrayKey::Int(*next_auto_index);
        Self::array_literal_update_append_cursor(&key, next_auto_index, auto_index_exhausted);
        Ok(key)
    }

    fn array_literal_update_append_cursor(
        key: &ArrayKey,
        next_auto_index: &mut i64,
        auto_index_exhausted: &mut bool,
    ) {
        let ArrayKey::Int(value) = key else {
            return;
        };
        if *auto_index_exhausted {
            return;
        }

        let should_advance = if *value >= 0 {
            *value >= *next_auto_index
        } else if *next_auto_index == 0 {
            true
        } else {
            *next_auto_index < 0 && *value >= *next_auto_index
        };
        if !should_advance {
            return;
        }

        match value.checked_add(1) {
            Some(next) => *next_auto_index = next,
            None => *auto_index_exhausted = true,
        }
    }

    fn array_literal_spread_expr(item: &ArrayItem) -> Option<&Expr> {
        if item.key.is_some() || item.by_reference {
            return None;
        }
        let Expr::SpreadArgument { expr, .. } = &item.value else {
            return None;
        };
        Some(expr)
    }

    fn evaluate_array_literal_spread_array(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<PhpArray> {
        let (value, array_copy_source) = self.evaluate_value_with_array_copy_source(expr, scope)?;
        let value = scope.value_with_object_property_aliases_from_array_copy(
            value,
            array_copy_source,
            true,
        );
        match value {
            Value::Array(array) => Ok(array),
            other => Err(runtime_error(
                expr.span(),
                RuntimeError::unsupported_call(
                    "array unpack",
                    format!(
                        "Only arrays and Traversables can be unpacked, {} given",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn append_array_literal_spread_entries(
        array: &mut PhpArray,
        source: &PhpArray,
        span: Span,
        next_auto_index: &mut i64,
        auto_index_exhausted: &mut bool,
    ) -> CompileResult<()> {
        for entry in source.entries() {
            match &entry.key {
                ArrayKey::Int(_) => {
                    let key = Self::array_literal_next_auto_key(
                        next_auto_index,
                        auto_index_exhausted,
                        span,
                    )?;
                    array.insert_slot(key, entry.slot().clone());
                }
                ArrayKey::String(key) => {
                    array.insert_slot(key.clone(), entry.slot().clone());
                }
            }
        }
        Ok(())
    }

    fn evaluate_array(
        &mut self,
        items: &[ArrayItem],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let mut array = PhpArray::new();
        let mut next_auto_index = 0;
        let mut auto_index_exhausted = false;

        for item in items {
            if let Some(expr) = Self::array_literal_spread_expr(item) {
                let source = self.evaluate_array_literal_spread_array(expr, scope)?;
                Self::append_array_literal_spread_entries(
                    &mut array,
                    &source,
                    expr.span(),
                    &mut next_auto_index,
                    &mut auto_index_exhausted,
                )?;
                continue;
            }

            let key = match &item.key {
                Some(expr) => {
                    let key = self.evaluate_array_key(expr, scope)?;
                    Self::array_literal_update_append_cursor(
                        &key,
                        &mut next_auto_index,
                        &mut auto_index_exhausted,
                    );
                    key
                }
                None => Self::array_literal_next_auto_key(
                    &mut next_auto_index,
                    &mut auto_index_exhausted,
                    span,
                )?,
            };
            if item.by_reference {
                let (_, reference) =
                    self.evaluate_array_literal_reference_cell(&item.value, scope)?;
                array.insert_reference(key, reference);
                continue;
            }
            let (value, array_copy_source) =
                self.evaluate_value_with_array_copy_source(&item.value, scope)?;
            let value = scope.value_with_object_property_aliases_from_array_copy(
                value,
                array_copy_source,
                true,
            );

            array.insert(key, value);
        }

        array.set_append_cursor(next_auto_index, auto_index_exhausted);
        Ok(Value::Array(array))
    }

    fn evaluate_array_for_direct_assignment(
        &mut self,
        items: &[ArrayItem],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(
        Value,
        Vec<ArrayLiteralReferenceElement>,
        Vec<(Vec<ArrayKey>, ArrayCopySource)>,
    )> {
        let mut array = PhpArray::new();
        let mut references = Vec::new();
        let mut copy_sources = Vec::new();
        let mut next_auto_index = 0;
        let mut auto_index_exhausted = false;

        for item in items {
            if let Some(expr) = Self::array_literal_spread_expr(item) {
                let source = self.evaluate_array_literal_spread_array(expr, scope)?;
                Self::append_array_literal_spread_entries(
                    &mut array,
                    &source,
                    expr.span(),
                    &mut next_auto_index,
                    &mut auto_index_exhausted,
                )?;
                continue;
            }

            let key = match &item.key {
                Some(expr) => {
                    let key = self.evaluate_array_key(expr, scope)?;
                    Self::array_literal_update_append_cursor(
                        &key,
                        &mut next_auto_index,
                        &mut auto_index_exhausted,
                    );
                    key
                }
                None => Self::array_literal_next_auto_key(
                    &mut next_auto_index,
                    &mut auto_index_exhausted,
                    span,
                )?,
            };

            if item.by_reference {
                let array_copy_source = self
                    .public_object_property_array_copy_source_for_value_expr(&item.value, scope);
                let (value, reference) =
                    self.evaluate_array_literal_reference_element(&item.value, scope)?;
                array.insert(key.clone(), value);
                references.push(match reference {
                    ArrayLiteralReferenceElement::Variable {
                        mut keys,
                        source_name,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::Variable { keys, source_name }
                    }
                    ArrayLiteralReferenceElement::Alias {
                        mut keys,
                        source_alias,
                        value,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::Alias {
                            keys,
                            source_alias,
                            value,
                        }
                    }
                    ArrayLiteralReferenceElement::CopiedArray {
                        mut keys,
                        source_name,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::CopiedArray { keys, source_name }
                    }
                });
                if let Some(source) = array_copy_source {
                    copy_sources.push((vec![key], source));
                }
                continue;
            }

            let (value, nested_references, nested_copy_sources) = match &item.value {
                Expr::Array { items, span } => {
                    self.evaluate_array_for_direct_assignment(items, *span, scope)?
                }
                _ => {
                    let (value, array_copy_source) =
                        self.evaluate_value_with_array_copy_source(&item.value, scope)?;
                    let value_is_array = matches!(value, Value::Array(_));
                    (
                        scope.value_with_object_property_aliases_from_array_copy(
                            value,
                            array_copy_source.clone(),
                            false,
                        ),
                        Vec::new(),
                        if value_is_array {
                            array_copy_source
                                .map(|source| vec![(Vec::new(), source)])
                                .unwrap_or_default()
                        } else {
                            Vec::new()
                        },
                    )
                }
            };
            array.insert(key.clone(), value);
            for reference in nested_references {
                references.push(match reference {
                    ArrayLiteralReferenceElement::Variable {
                        mut keys,
                        source_name,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::Variable { keys, source_name }
                    }
                    ArrayLiteralReferenceElement::Alias {
                        mut keys,
                        source_alias,
                        value,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::Alias {
                            keys,
                            source_alias,
                            value,
                        }
                    }
                    ArrayLiteralReferenceElement::CopiedArray {
                        mut keys,
                        source_name,
                    } => {
                        keys.insert(0, key.clone());
                        ArrayLiteralReferenceElement::CopiedArray { keys, source_name }
                    }
                });
            }
            for (mut keys, source) in nested_copy_sources {
                keys.insert(0, key.clone());
                copy_sources.push((keys, source));
            }
            if let Expr::Variable(source_name, _) = &item.value {
                references.push(ArrayLiteralReferenceElement::CopiedArray {
                    keys: vec![key],
                    source_name: source_name.clone(),
                });
            }
        }

        array.set_append_cursor(next_auto_index, auto_index_exhausted);
        Ok((Value::Array(array), references, copy_sources))
    }

    fn evaluate_array_literal_reference_cell(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, VariableCell)> {
        if let Expr::Variable(source_name, span) = expr {
            let cell = scope.read_cell(source_name).ok_or_else(|| {
                runtime_error(*span, RuntimeError::undefined_variable(source_name))
            })?;
            return Ok((cell.value_cloned(), cell));
        }

        if let Some((source_alias, value)) =
            self.evaluate_direct_array_reference_argument(expr, scope)?
        {
            let aliases = vec![source_alias];
            let Some(cell) = scope.reference_cell_for_array_literal_alias_group(&aliases) else {
                return Err(runtime_error(
                    expr.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind array literal reference element".to_string(),
                    ),
                ));
            };
            return Ok((value, cell));
        }

        if let Some((source_alias, value)) =
            self.evaluate_magic_get_array_reference_argument(expr, scope)?
        {
            let aliases = vec![source_alias];
            let Some(cell) = scope.reference_cell_for_array_literal_alias_group(&aliases) else {
                return Err(runtime_error(
                    expr.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind magic array literal reference element".to_string(),
                    ),
                ));
            };
            return Ok((value, cell));
        }

        if let Some((source_alias, value)) =
            self.evaluate_visible_object_property_array_reference_argument(expr, scope, false)?
        {
            let aliases = vec![source_alias];
            let Some(cell) = scope.reference_cell_for_array_literal_alias_group(&aliases) else {
                return Err(runtime_error(
                    expr.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind object-property array literal reference element".to_string(),
                    ),
                ));
            };
            return Ok((value, cell));
        }

        if let Some((source_alias, value)) =
            self.evaluate_visible_object_property_reference_element_alias(expr, scope)?
        {
            let aliases = vec![source_alias];
            let Some(cell) = scope.reference_cell_for_array_literal_alias_group(&aliases) else {
                return Err(runtime_error(
                    expr.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind object-property array literal reference element".to_string(),
                    ),
                ));
            };
            return Ok((value, cell));
        }

        Err(runtime_error(
            expr.span(),
            RuntimeError::unsupported_call(
                "array literal",
                "runtime reference elements are only implemented for direct variables, direct array offsets, direct visible object-property array offsets, and bounded magic __get array offsets in the current subset",
            ),
        ))
    }

    fn bind_array_literal_references_to_alias_root(
        &mut self,
        root: ArrayOffsetAliasRoot,
        references: Vec<ArrayLiteralReferenceElement>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        self.bind_array_literal_references_to_alias_root_with_prefix(
            root,
            Vec::new(),
            references,
            span,
            scope,
        )
    }

    fn bind_array_literal_references_to_alias_root_with_prefix(
        &mut self,
        root: ArrayOffsetAliasRoot,
        prefix: Vec<ArrayKey>,
        references: Vec<ArrayLiteralReferenceElement>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<()> {
        for reference in references {
            match reference {
                ArrayLiteralReferenceElement::Variable {
                    keys: reference_keys,
                    source_name,
                } => {
                    let mut keys = prefix.clone();
                    keys.extend(reference_keys);
                    if SymbolTable::alias_root_allows_reference_slot_fast_path(&root) {
                        scope.bind_object_property_array_offset_alias_root_to_static_source(
                            root.clone(),
                            keys,
                            &source_name,
                            span,
                        )?;
                    } else {
                        scope.bind_array_offset_alias_root_to_static_source(
                            ArrayOffsetAlias {
                                root: root.clone(),
                                keys,
                            },
                            &source_name,
                            span,
                        )?;
                    }
                }
                ArrayLiteralReferenceElement::Alias {
                    keys: reference_keys,
                    source_alias,
                    value,
                } => {
                    let mut keys = prefix.clone();
                    keys.extend(reference_keys);
                    let target_alias = ArrayOffsetAlias {
                        root: root.clone(),
                        keys,
                    };
                    scope.bind_array_offset_alias_to_reference_alias(
                        target_alias,
                        source_alias,
                        value,
                        span,
                    )?;
                }
                ArrayLiteralReferenceElement::CopiedArray {
                    keys: reference_keys,
                    source_name,
                } => {
                    let mut keys = prefix.clone();
                    keys.extend(reference_keys);
                    scope.mirror_nested_static_array_offset_aliases_from_copy_to_alias_root(
                        root.clone(),
                        &keys,
                        &source_name,
                    );
                }
            }
        }
        Ok(())
    }

    fn evaluate_array_literal_reference_element(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, ArrayLiteralReferenceElement)> {
        if let Expr::Variable(source_name, span) = expr {
            let value = scope.read_named(source_name).ok_or_else(|| {
                runtime_error(*span, RuntimeError::undefined_variable(source_name))
            })?;
            return Ok((
                value,
                ArrayLiteralReferenceElement::Variable {
                    keys: Vec::new(),
                    source_name: source_name.clone(),
                },
            ));
        }

        if let Some((source_alias, value)) =
            self.evaluate_direct_array_reference_argument(expr, scope)?
        {
            return Ok((
                value.clone(),
                ArrayLiteralReferenceElement::Alias {
                    keys: Vec::new(),
                    source_alias,
                    value,
                },
            ));
        }

        if let Some((source_alias, value)) =
            self.evaluate_magic_get_array_reference_argument(expr, scope)?
        {
            return Ok((
                value.clone(),
                ArrayLiteralReferenceElement::Alias {
                    keys: Vec::new(),
                    source_alias,
                    value,
                },
            ));
        }

        if let Some((source_alias, value)) =
            self.evaluate_visible_object_property_array_reference_argument(expr, scope, false)?
        {
            return Ok((
                value.clone(),
                ArrayLiteralReferenceElement::Alias {
                    keys: Vec::new(),
                    source_alias,
                    value,
                },
            ));
        }

        if let Some((source_alias, value)) =
            self.evaluate_visible_object_property_reference_element_alias(expr, scope)?
        {
            return Ok((
                value.clone(),
                ArrayLiteralReferenceElement::Alias {
                    keys: Vec::new(),
                    source_alias,
                    value,
                },
            ));
        }

        Err(runtime_error(
            expr.span(),
            RuntimeError::unsupported_call(
                "array literal",
                "stored reference elements are only implemented for direct variables, direct array offsets, direct visible object-property array offsets, and bounded magic __get array offsets in the current subset",
            ),
        ))
    }

    fn evaluate_visible_object_property_reference_element_alias(
        &mut self,
        expr: &Expr,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let Some((object_name, property)) =
            self.direct_object_property_reference_argument_parts(expr, scope)?
        else {
            return Ok(None);
        };
        let root =
            self.context_object_property_alias_root(&object_name, &property, expr.span(), scope)?;
        let alias = ArrayOffsetAlias {
            root: scope.canonical_equivalent_object_property_alias_root(&root),
            keys: Vec::new(),
        };
        let value = scope.read_array_offset_alias(&alias).unwrap_or(Value::Null);
        Ok(Some((alias, value)))
    }

    fn magic_dir_value(&self) -> String {
        let Some(source_file) = &self.source_file else {
            return String::new();
        };
        let Some(parent) = Path::new(source_file).parent() else {
            return ".".to_string();
        };
        if parent.as_os_str().is_empty() {
            ".".to_string()
        } else {
            parent.to_string_lossy().into_owned()
        }
    }

    fn function_context_name(&self, function: &FunctionDecl) -> String {
        if function.name == "{closure}" {
            let source_file = self
                .source_file
                .clone()
                .unwrap_or_else(|| "Command line code".to_string());
            return format!("{{closure:{source_file}:{}}}", function.span.line);
        }
        function.name.clone()
    }

    fn magic_method_value(&self, span: Span) -> CompileResult<String> {
        let Some(function_name) = self.function_context.last() else {
            return Ok(String::new());
        };
        let Some(class_id) = self.class_context.last().copied() else {
            if let Some(trait_name) = self.trait_class_context.last() {
                return Ok(format!("{trait_name}::{function_name}"));
            }
            return Ok(function_name.clone());
        };
        let class = self.classes.get(class_id).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::undefined_class(format!("class id {}", class_id.index())),
            )
        })?;
        Ok(format!("{}::{function_name}", class.name()))
    }

    fn magic_class_value(&self, span: Span) -> CompileResult<String> {
        let Some(class_id) = self.class_context.last().copied() else {
            if let Some(trait_name) = self.trait_class_context.last() {
                return Ok(trait_name.clone());
            }
            return Ok(String::new());
        };
        let class = self.classes.get(class_id).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::undefined_class(format!("class id {}", class_id.index())),
            )
        })?;
        Ok(class.name().to_string())
    }

    fn create_dom_object(&mut self, class_name: &str, span: Span) -> CompileResult<PhpObject> {
        let class_id = self.classes.lookup_class_id(class_name).ok_or_else(|| {
            runtime_error(span, RuntimeError::undefined_class(class_name.to_string()))
        })?;
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("DOM core class id should resolve");
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.track_allocated_object(&object);
        Ok(object)
    }

    fn instantiate_dom_attr(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "DOMAttr::__construct()",
                    format!(
                        "DOMAttr::__construct() expects at least 1 argument, {} given",
                        args.len()
                    ),
                ),
            ));
        }
        let values = args
            .iter()
            .map(|arg| self.evaluate(arg, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        let name = string_builtin_argument("DOMAttr::__construct()", "name", &values[0], span)?;
        let value = match values.get(1) {
            Some(value) => string_builtin_argument("DOMAttr::__construct()", "value", value, span)?,
            None => String::new(),
        };
        dom_validate_xml_name("DOMAttr::__construct()", &name, span)?;
        self.create_dom_attr_object(&name, &value, span)
            .map(Value::Object)
    }

    fn instantiate_dom_element(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if !(1..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "DOMElement::__construct()",
                    ArityExpectation::Between { min: 1, max: 3 },
                    args.len(),
                ),
            ));
        }
        let values = args
            .iter()
            .map(|arg| self.evaluate(arg, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        let tag_name = string_builtin_argument(
            "DOMElement::__construct()",
            "qualifiedName",
            &values[0],
            span,
        )?;
        dom_validate_xml_name("DOMElement::__construct()", &tag_name, span)?;
        let object = self.create_dom_element_object(&tag_name, span)?;
        if let Some(value) = values.get(1) {
            let text = string_builtin_argument("DOMElement::__construct()", "value", value, span)?;
            object
                .write_public_property("nodeValue", Value::String(text))
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(Value::Object(object))
    }

    fn instantiate_dom_document(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if args.len() > 2 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "DOMDocument::__construct()",
                    ArityExpectation::Between { min: 0, max: 2 },
                    args.len(),
                ),
            ));
        }
        for arg in args {
            self.evaluate(arg, scope)?;
        }
        let object = self.create_dom_object("DOMDocument", span)?;
        object
            .write_public_property("nodeName", Value::String("#document".to_string()))
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("nodeValue", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("parentNode", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("ownerDocument", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("firstElementChild", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("documentElement", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("__children", Value::Array(PhpArray::new()))
            .map_err(|error| runtime_error(span, error))?;
        Ok(Value::Object(object))
    }

    fn instantiate_dom_document_type(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        for arg in args {
            self.evaluate(arg, scope)?;
        }
        self.create_dom_object("DOMDocumentType", span)
            .map(Value::Object)
    }

    fn create_dom_attr_object(
        &mut self,
        name: &str,
        value: &str,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let object = self.create_dom_object("DOMAttr", span)?;
        for (property, property_value) in [
            ("nodeName", Value::String(name.to_string())),
            ("nodeValue", Value::String(value.to_string())),
            ("name", Value::String(name.to_string())),
            ("value", Value::String(value.to_string())),
            ("ownerElement", Value::Null),
            ("parentNode", Value::Null),
            ("ownerDocument", Value::Null),
            ("namespaceURI", Value::Null),
            ("prefix", Value::Null),
            ("localName", Value::String(dom_local_name(name))),
            ("firstElementChild", Value::Null),
        ] {
            object
                .write_public_property(property, property_value)
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(object)
    }

    fn create_dom_element_object(
        &mut self,
        tag_name: &str,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let object = self.create_dom_object("DOMElement", span)?;
        for (property, property_value) in [
            ("nodeName", Value::String(tag_name.to_string())),
            ("nodeValue", Value::String(String::new())),
            ("tagName", Value::String(tag_name.to_string())),
            ("parentNode", Value::Null),
            ("ownerDocument", Value::Null),
            ("firstElementChild", Value::Null),
            ("__attributes", Value::Array(PhpArray::new())),
            ("__children", Value::Array(PhpArray::new())),
        ] {
            object
                .write_public_property(property, property_value)
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(object)
    }

    fn call_dom_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let values = args
            .iter()
            .map(|arg| self.evaluate(arg, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        if object.class_name().eq_ignore_ascii_case("DOMAttr") {
            return self.call_dom_attr_method(object, method_name, &values, span);
        }
        if object.class_name().eq_ignore_ascii_case("DOMElement") {
            return self.call_dom_element_method(object, method_name, &values, span);
        }
        if object.class_name().eq_ignore_ascii_case("DOMDocument") {
            return self.call_dom_document_method(object, method_name, &values, span);
        }
        if object.class_name().eq_ignore_ascii_case("DOMDocumentType") {
            return Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DOMDocumentType::{method_name}()")),
            ));
        }
        Err(runtime_error(
            span,
            RuntimeError::undefined_function(format!("DOMNode::{method_name}()")),
        ))
    }

    fn read_dom_document_type_property(
        &self,
        object: &PhpObject,
        property: &str,
        span: Span,
    ) -> CompileResult<Option<Value>> {
        if !object.class_name().eq_ignore_ascii_case("DOMDocumentType")
            || !dom_document_type_invalid_state_property(property)
        {
            return Ok(None);
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("DOMDocumentType::${property}"),
                "Invalid State Error",
            ),
        ))
    }

    fn call_dom_attr_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        values: &[Value],
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                if !(1..=2).contains(&values.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DOMAttr::__construct()",
                            format!(
                                "DOMAttr::__construct() expects at least 1 argument, {} given",
                                values.len()
                            ),
                        ),
                    ));
                }
                let name =
                    string_builtin_argument("DOMAttr::__construct()", "name", &values[0], span)?;
                let value = match values.get(1) {
                    Some(value) => {
                        string_builtin_argument("DOMAttr::__construct()", "value", value, span)?
                    }
                    None => String::new(),
                };
                dom_validate_xml_name("DOMAttr::__construct()", &name, span)?;
                object
                    .write_public_property("nodeName", Value::String(name.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("nodeValue", Value::String(value.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("name", Value::String(name.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("value", Value::String(value))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("localName", Value::String(dom_local_name(&name)))
                    .map_err(|error| runtime_error(span, error))?;
                Ok(Value::Null)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DOMAttr::{method_name}()")),
            )),
        }
    }

    fn call_dom_document_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        values: &[Value],
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => Ok(Value::Null),
            "createattribute" => {
                expect_arity("DOMDocument::createAttribute", values, 1, span)?;
                let name = string_builtin_argument(
                    "DOMDocument::createAttribute()",
                    "name",
                    &values[0],
                    span,
                )?;
                dom_validate_xml_name("DOMDocument::createAttribute()", &name, span)?;
                self.create_dom_attr_object(&name, "", span)
                    .map(Value::Object)
            }
            "createelement" => {
                if !(1..=2).contains(&values.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DOMDocument::createElement()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            values.len(),
                        ),
                    ));
                }
                let tag_name = string_builtin_argument(
                    "DOMDocument::createElement()",
                    "qualifiedName",
                    &values[0],
                    span,
                )?;
                dom_validate_xml_name("DOMDocument::createElement()", &tag_name, span)?;
                let element = self.create_dom_element_object(&tag_name, span)?;
                element
                    .write_public_property("ownerDocument", Value::Object(object.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                if let Some(value) = values.get(1) {
                    let text = string_builtin_argument(
                        "DOMDocument::createElement()",
                        "value",
                        value,
                        span,
                    )?;
                    element
                        .write_public_property("nodeValue", Value::String(text))
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(Value::Object(element))
            }
            "appendchild" => {
                expect_arity("DOMDocument::appendChild", values, 1, span)?;
                let Value::Object(child) = &values[0] else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DOMDocument::appendChild()",
                            format!("argument must be DOMNode, got {}", values[0].type_name()),
                        ),
                    ));
                };
                self.dom_document_append_child(&object, child, span)?;
                Ok(Value::Object(child.clone()))
            }
            "removechild" => {
                expect_arity("DOMDocument::removeChild", values, 1, span)?;
                let Value::Object(child) = &values[0] else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DOMDocument::removeChild()",
                            format!("argument must be DOMNode, got {}", values[0].type_name()),
                        ),
                    ));
                };
                self.dom_document_remove_child(&object, child, span)?;
                Ok(Value::Object(child.clone()))
            }
            "importnode" => {
                if !(1..=2).contains(&values.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DOMDocument::importNode()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            values.len(),
                        ),
                    ));
                }
                let Value::Object(node) = &values[0] else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DOMDocument::importNode()",
                            format!("argument must be DOMNode, got {}", values[0].type_name()),
                        ),
                    ));
                };
                node.write_public_property("ownerDocument", Value::Object(object))
                    .map_err(|error| runtime_error(span, error))?;
                Ok(Value::Object(node.clone()))
            }
            "savexml" => {
                if values.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DOMDocument::saveXML()",
                            ArityExpectation::Between { min: 0, max: 1 },
                            values.len(),
                        ),
                    ));
                }
                if let Some(Value::Object(node)) = values.first() {
                    return self
                        .dom_serialize_node(node, false, span)
                        .map(Value::String);
                }
                let mut output = String::from("<?xml version=\"1.0\"?>\n");
                match object
                    .read_public_property("documentElement")
                    .map_err(|error| runtime_error(span, error))?
                {
                    Value::Object(root) => {
                        output.push_str(&self.dom_serialize_node(&root, false, span)?);
                        output.push('\n');
                    }
                    _ => {}
                }
                Ok(Value::String(output))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DOMDocument::{method_name}()")),
            )),
        }
    }

    fn call_dom_element_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        values: &[Value],
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                if !(1..=3).contains(&values.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DOMElement::__construct()",
                            ArityExpectation::Between { min: 1, max: 3 },
                            values.len(),
                        ),
                    ));
                }
                let tag_name = string_builtin_argument(
                    "DOMElement::__construct()",
                    "qualifiedName",
                    &values[0],
                    span,
                )?;
                dom_validate_xml_name("DOMElement::__construct()", &tag_name, span)?;
                object
                    .write_public_property("nodeName", Value::String(tag_name.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("tagName", Value::String(tag_name))
                    .map_err(|error| runtime_error(span, error))?;
                if let Some(value) = values.get(1) {
                    let text =
                        string_builtin_argument("DOMElement::__construct()", "value", value, span)?;
                    object
                        .write_public_property("nodeValue", Value::String(text))
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(Value::Null)
            }
            "appendchild" => {
                expect_arity("DOMElement::appendChild", values, 1, span)?;
                let Value::Object(child) = &values[0] else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "DOMElement::appendChild()",
                            format!("argument must be DOMNode, got {}", values[0].type_name()),
                        ),
                    ));
                };
                if child.class_name().eq_ignore_ascii_case("DOMAttr") {
                    let name = self.dom_attr_name(child, span)?;
                    self.dom_set_element_attribute(&object, &name, child, span)?;
                    return Ok(Value::Object(child.clone()));
                }
                let mut children = self.dom_element_children(&object, span)?;
                children
                    .append(Value::Object(child.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("__children", Value::Array(children))
                    .map_err(|error| runtime_error(span, error))?;
                object
                    .write_public_property("firstElementChild", Value::Object(child.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                child
                    .write_public_property("parentNode", Value::Object(object.clone()))
                    .map_err(|error| runtime_error(span, error))?;
                Ok(Value::Object(child.clone()))
            }
            "setattribute" => {
                expect_arity("DOMElement::setAttribute", values, 2, span)?;
                let name = string_builtin_argument(
                    "DOMElement::setAttribute()",
                    "name",
                    &values[0],
                    span,
                )?;
                let value = string_builtin_argument(
                    "DOMElement::setAttribute()",
                    "value",
                    &values[1],
                    span,
                )?;
                dom_validate_xml_name("DOMElement::setAttribute()", &name, span)?;
                let attr = self.create_dom_attr_object(&name, &value, span)?;
                self.dom_set_element_attribute(&object, &name, &attr, span)?;
                Ok(Value::Object(attr))
            }
            "getattribute" => {
                expect_arity("DOMElement::getAttribute", values, 1, span)?;
                let name = string_builtin_argument(
                    "DOMElement::getAttribute()",
                    "name",
                    &values[0],
                    span,
                )?;
                let attrs = self.dom_element_attributes(&object, span)?;
                match attrs.get_cloned(ArrayKey::String(name)) {
                    Some(Value::Object(attr)) => {
                        self.dom_attr_value(&attr, span).map(Value::String)
                    }
                    _ => Ok(Value::String(String::new())),
                }
            }
            "hasattribute" => {
                expect_arity("DOMElement::hasAttribute", values, 1, span)?;
                let name = string_builtin_argument(
                    "DOMElement::hasAttribute()",
                    "name",
                    &values[0],
                    span,
                )?;
                Ok(Value::Bool(
                    self.dom_element_attributes(&object, span)?
                        .contains_key(ArrayKey::String(name)),
                ))
            }
            "getattributenode" => {
                expect_arity("DOMElement::getAttributeNode", values, 1, span)?;
                let name = string_builtin_argument(
                    "DOMElement::getAttributeNode()",
                    "name",
                    &values[0],
                    span,
                )?;
                Ok(self
                    .dom_element_attributes(&object, span)?
                    .get_cloned(ArrayKey::String(name))
                    .unwrap_or(Value::Null))
            }
            "getattributenames" => {
                expect_arity("DOMElement::getAttributeNames", values, 0, span)?;
                let attrs = self.dom_element_attributes(&object, span)?;
                let mut names = PhpArray::new();
                for entry in attrs.entries() {
                    if let ArrayKey::String(name) = &entry.key {
                        names
                            .append(Value::String(name.clone()))
                            .map_err(|error| runtime_error(span, error))?;
                    }
                }
                Ok(Value::Array(names))
            }
            "hasattributes" => {
                expect_arity("DOMElement::hasAttributes", values, 0, span)?;
                Ok(Value::Bool(
                    !self.dom_element_attributes(&object, span)?.is_empty(),
                ))
            }
            "toggleattribute" => {
                if !(1..=2).contains(&values.len()) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "DOMElement::toggleAttribute()",
                            ArityExpectation::Between { min: 1, max: 2 },
                            values.len(),
                        ),
                    ));
                }
                let name = string_builtin_argument(
                    "DOMElement::toggleAttribute()",
                    "name",
                    &values[0],
                    span,
                )?;
                dom_validate_xml_name("DOMElement::toggleAttribute()", &name, span)?;
                let force = values.get(1).map(Value::is_truthy);
                let mut attrs = self.dom_element_attributes(&object, span)?;
                let has_attr = attrs.contains_key(ArrayKey::String(name.clone()));
                match (has_attr, force) {
                    (true, Some(true)) => Ok(Value::Bool(true)),
                    (true, None) | (true, Some(false)) => {
                        attrs.remove(ArrayKey::String(name));
                        object
                            .write_public_property("__attributes", Value::Array(attrs))
                            .map_err(|error| runtime_error(span, error))?;
                        Ok(Value::Bool(false))
                    }
                    (false, Some(false)) => Ok(Value::Bool(false)),
                    (false, None) | (false, Some(true)) => {
                        let attr = self.create_dom_attr_object(&name, "", span)?;
                        self.dom_set_element_attribute(&object, &name, &attr, span)?;
                        Ok(Value::Bool(true))
                    }
                }
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("DOMElement::{method_name}()")),
            )),
        }
    }

    fn dom_element_attributes(&self, object: &PhpObject, span: Span) -> CompileResult<PhpArray> {
        match object
            .read_public_property("__attributes")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::Array(attrs) => Ok(attrs),
            _ => Ok(PhpArray::new()),
        }
    }

    fn dom_element_children(&self, object: &PhpObject, span: Span) -> CompileResult<PhpArray> {
        match object
            .read_public_property("__children")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::Array(children) => Ok(children),
            _ => Ok(PhpArray::new()),
        }
    }

    fn dom_set_element_attribute(
        &mut self,
        element: &PhpObject,
        name: &str,
        attr: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        let mut attrs = self.dom_element_attributes(element, span)?;
        attr.write_public_property("ownerElement", Value::Object(element.clone()))
            .map_err(|error| runtime_error(span, error))?;
        attr.write_public_property("parentNode", Value::Object(element.clone()))
            .map_err(|error| runtime_error(span, error))?;
        attr.write_public_property("name", Value::String(name.to_string()))
            .map_err(|error| runtime_error(span, error))?;
        attr.write_public_property("nodeName", Value::String(name.to_string()))
            .map_err(|error| runtime_error(span, error))?;
        attrs.insert(
            ArrayKey::String(name.to_string()),
            Value::Object(attr.clone()),
        );
        element
            .write_public_property("__attributes", Value::Array(attrs))
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn dom_document_append_child(
        &mut self,
        document: &PhpObject,
        child: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        let mut children = match document
            .read_public_property("__children")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::Array(children) => children,
            _ => PhpArray::new(),
        };
        children
            .append(Value::Object(child.clone()))
            .map_err(|error| runtime_error(span, error))?;
        document
            .write_public_property("__children", Value::Array(children))
            .map_err(|error| runtime_error(span, error))?;
        if child.class_name().eq_ignore_ascii_case("DOMElement") {
            document
                .write_public_property("documentElement", Value::Object(child.clone()))
                .map_err(|error| runtime_error(span, error))?;
            document
                .write_public_property("firstElementChild", Value::Object(child.clone()))
                .map_err(|error| runtime_error(span, error))?;
        }
        child
            .write_public_property("ownerDocument", Value::Object(document.clone()))
            .map_err(|error| runtime_error(span, error))?;
        child
            .write_public_property("parentNode", Value::Object(document.clone()))
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn dom_document_remove_child(
        &mut self,
        document: &PhpObject,
        child: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        let children = match document
            .read_public_property("__children")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::Array(children) => children,
            _ => PhpArray::new(),
        };
        let mut remaining = PhpArray::new();
        for entry in children.entries() {
            match entry.value() {
                Value::Object(existing) if existing.id() == child.id() => {}
                value => {
                    remaining
                        .append(value.clone())
                        .map_err(|error| runtime_error(span, error))?;
                }
            }
        }
        document
            .write_public_property("__children", Value::Array(remaining))
            .map_err(|error| runtime_error(span, error))?;
        match document
            .read_public_property("documentElement")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::Object(existing) if existing.id() == child.id() => {
                document
                    .write_public_property("documentElement", Value::Null)
                    .map_err(|error| runtime_error(span, error))?;
                document
                    .write_public_property("firstElementChild", Value::Null)
                    .map_err(|error| runtime_error(span, error))?;
            }
            _ => {}
        }
        if child.class_name().eq_ignore_ascii_case("DOMElement") {
            self.dom_clear_element_attribute_owners(child, span)?;
        }
        child
            .write_public_property("parentNode", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        child
            .write_public_property("ownerDocument", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn dom_clear_element_attribute_owners(
        &mut self,
        element: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        let attrs = self.dom_element_attributes(element, span)?;
        for entry in attrs.entries() {
            if let Value::Object(attr) = entry.value() {
                attr.write_public_property("ownerElement", Value::Null)
                    .map_err(|error| runtime_error(span, error))?;
                attr.write_public_property("parentNode", Value::Null)
                    .map_err(|error| runtime_error(span, error))?;
                attr.write_public_property("ownerDocument", Value::Null)
                    .map_err(|error| runtime_error(span, error))?;
            }
        }
        Ok(())
    }

    fn dom_attr_name(&self, attr: &PhpObject, span: Span) -> CompileResult<String> {
        match attr
            .read_public_property("name")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::String(name) => Ok(name),
            value => string_builtin_argument("DOMAttr::$name", "name", &value, span),
        }
    }

    fn dom_attr_value(&self, attr: &PhpObject, span: Span) -> CompileResult<String> {
        let value = attr
            .read_public_property("value")
            .map_err(|error| runtime_error(span, error))?;
        string_builtin_argument("DOMAttr::$value", "value", &value, span)
    }

    fn dom_serialize_node(
        &self,
        node: &PhpObject,
        include_declaration: bool,
        span: Span,
    ) -> CompileResult<String> {
        if node.class_name().eq_ignore_ascii_case("DOMDocument") {
            let mut output = if include_declaration {
                String::from("<?xml version=\"1.0\"?>\n")
            } else {
                String::new()
            };
            if let Value::Object(root) = node
                .read_public_property("documentElement")
                .map_err(|error| runtime_error(span, error))?
            {
                output.push_str(&self.dom_serialize_element(&root, span)?);
            }
            return Ok(output);
        }
        if node.class_name().eq_ignore_ascii_case("DOMElement") {
            return self.dom_serialize_element(node, span);
        }
        if node.class_name().eq_ignore_ascii_case("DOMAttr") {
            let name = self.dom_attr_name(node, span)?;
            let value = self.dom_attr_value(node, span)?;
            return Ok(format!("{name}=\"{}\"", xml_escape_attribute(&value)));
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "DOMDocument::saveXML()",
                format!("unsupported DOM node class {}", node.class_name()),
            ),
        ))
    }

    fn dom_serialize_element(&self, element: &PhpObject, span: Span) -> CompileResult<String> {
        let tag_name = match element
            .read_public_property("tagName")
            .map_err(|error| runtime_error(span, error))?
        {
            Value::String(name) => name,
            value => string_builtin_argument("DOMElement::$tagName", "tagName", &value, span)?,
        };
        let attrs = self.dom_element_attributes(element, span)?;
        let mut output = format!("<{tag_name}");
        for entry in attrs.entries() {
            if let Value::Object(attr) = entry.value() {
                let name = self.dom_attr_name(attr, span)?;
                let value = self.dom_attr_value(attr, span)?;
                output.push(' ');
                output.push_str(&name);
                output.push_str("=\"");
                output.push_str(&xml_escape_attribute(&value));
                output.push('"');
            }
        }
        let children = self.dom_element_children(element, span)?;
        let node_value = element
            .read_public_property("nodeValue")
            .map_err(|error| runtime_error(span, error))?;
        let node_text =
            string_builtin_argument("DOMElement::$nodeValue", "nodeValue", &node_value, span)?;
        if children.is_empty() && node_text.is_empty() {
            output.push_str("/>");
            return Ok(output);
        }
        output.push('>');
        output.push_str(&xml_escape_text(&node_text));
        for entry in children.entries() {
            if let Value::Object(child) = entry.value() {
                output.push_str(&self.dom_serialize_node(child, false, span)?);
            }
        }
        output.push_str("</");
        output.push_str(&tag_name);
        output.push('>');
        Ok(output)
    }

    fn create_mysqli_placeholder(&mut self, span: Span) -> CompileResult<Value> {
        let class_id = self.classes.lookup_class_id("mysqli").ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::undefined_class("mysqli core placeholder"),
            )
        })?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("core mysqli class id should resolve");
        let object = PhpObject::from_class_with_id(class, object_id);
        self.initialize_mysqli_placeholder_object(&object, span)?;
        Ok(Value::Object(object))
    }

    fn initialize_mysqli_placeholder_object(
        &self,
        object: &PhpObject,
        span: Span,
    ) -> CompileResult<()> {
        object
            .write_public_property("connect_errno", Value::Int(0))
            .map_err(|error| runtime_error(span, error))?;
        object
            .write_public_property("connect_error", Value::Null)
            .map_err(|error| runtime_error(span, error))?;
        Ok(())
    }

    fn instantiate_mysqli(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if args.len() > 6 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "mysqli::__construct()",
                    ArityExpectation::Between { min: 0, max: 6 },
                    args.len(),
                ),
            ));
        }
        let values = args
            .iter()
            .map(|arg| self.evaluate(arg, scope))
            .collect::<CompileResult<Vec<_>>>()?;
        self.validate_mysqli_connect_arguments("mysqli::__construct()", &values, span)?;
        self.create_mysqli_placeholder(span)
    }

    fn instantiate_mysqli_driver(&mut self, args: &[Expr], span: Span) -> CompileResult<Value> {
        expect_expr_arity("mysqli_driver::__construct", args.len(), 0, span)?;
        let class_id = self
            .classes
            .lookup_class_id("mysqli_driver")
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::undefined_class("mysqli_driver core placeholder"),
                )
            })?;
        let object_id = self.allocate_object_id();
        let class = self
            .classes
            .get(class_id)
            .expect("core mysqli_driver class id should resolve");
        let object = PhpObject::from_class_with_id(class, object_id);
        for (property, value) in [
            (
                "client_info",
                Value::String("mysqlnd 8.0.0-phpc-placeholder".to_string()),
            ),
            ("client_version", Value::Int(80000)),
            ("driver_version", Value::Int(80000)),
            ("embedded", Value::Bool(false)),
            ("reconnect", Value::Bool(false)),
            ("report_mode", Value::Int(self.mysqli_report_mode)),
        ] {
            object
                .write_public_property(property, value)
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(Value::Object(object))
    }

