    fn call_magic_instance_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Option<Value>> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), method_name)
        else {
            return Ok(None);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, method_name, visibility, span)?;

        if self.resolved_method_is_core_array_object(class_id) {
            return self
                .call_array_object_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            return self
                .call_spl_object_storage_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_fixed_array(class_id) {
            return self
                .call_spl_fixed_array_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(class_id) {
            return self
                .call_spl_doubly_linked_list_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_directory_iterator(class_id) {
            return self
                .call_spl_directory_iterator_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_filesystem_iterator(class_id) {
            return self
                .call_spl_filesystem_iterator_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_recursive_directory_iterator(class_id) {
            return self
                .call_spl_recursive_directory_iterator_method_with_values(
                    object,
                    method_name,
                    args,
                    span,
                )
                .map(Some);
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(class_id) {
            return self
                .call_spl_recursive_iterator_iterator_method_with_values(
                    object,
                    method_name,
                    args,
                    span,
                )
                .map(Some);
        }

        if self.resolved_method_is_core_spl_file_info(class_id) {
            return self
                .call_spl_file_info_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_file_object(class_id) {
            return self
                .call_spl_file_object_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(class_id) {
            return self
                .call_spl_iterator_wrapper_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_php_token(class_id)
            && php_token_core_instance_method(method_name)
        {
            return self
                .call_php_token_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if method_name.eq_ignore_ascii_case("__toString") && args.is_empty() {
            if object.is_instance_of_class_name("ReflectionClass") {
                let state = self
                    .reflection_classes
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionClass::__toString()",
                                "missing ReflectionClass runtime metadata",
                            ),
                        )
                    })?;
                return self
                    .reflection_class_to_string(&state, span)
                    .map(Value::String)
                    .map(Some);
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionFunction")
            {
                let state = self
                    .reflection_functions
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionFunction::__toString()",
                                "missing ReflectionFunction runtime metadata",
                            ),
                        )
                    })?;
                return self
                    .reflection_function_to_string(&state, span)
                    .map(Value::String)
                    .map(Some);
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionParameter")
            {
                let state = self
                    .reflection_parameters
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionParameter::__toString()",
                                "missing ReflectionParameter runtime metadata",
                            ),
                        )
                    })?;
                return self
                    .reflection_parameter_to_string(&state, span)
                    .map(Value::String)
                    .map(Some);
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionProperty")
            {
                let state = self
                    .reflection_properties
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionProperty::__toString()",
                                "missing ReflectionProperty runtime metadata",
                            ),
                        )
                    })?;
                return self
                    .reflection_property_to_string(&state, span)
                    .map(Value::String)
                    .map(Some);
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionAttribute")
            {
                let state = self
                    .reflection_attributes
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionAttribute::__toString()",
                                "missing ReflectionAttribute runtime metadata",
                            ),
                        )
                    })?;
                return self
                    .reflection_attribute_to_string(&state, span)
                    .map(Value::String)
                    .map(Some);
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionNamedType")
            {
                let state = self
                    .reflection_named_types
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "ReflectionNamedType::__toString()",
                                "missing ReflectionNamedType runtime metadata",
                            ),
                        )
                    })?;
                return Ok(Some(Value::String(reflection_named_type_to_string(&state))));
            }
            if object
                .class_name()
                .eq_ignore_ascii_case("ReflectionUnionType")
                || object
                    .class_name()
                    .eq_ignore_ascii_case("ReflectionIntersectionType")
            {
                let state = self
                    .reflection_compound_types
                    .get(&object.id())
                    .cloned()
                    .ok_or_else(|| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                format!("{}::__toString()", object.class_name()),
                                "missing reflection compound type runtime metadata",
                            ),
                        )
                    })?;
                return Ok(Some(Value::String(reflection_compound_type_to_string(
                    &state,
                ))));
            }
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity(function, args.len(), span)?;
        ensure_supported_magic_array_access_function_signature(function, args.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        self.call_user_function_with_this(
            function,
            object,
            args,
            Some(class_id),
            Some(called_class_id),
        )
        .map(Some)
    }

    fn call_magic_instance_method_with_values_and_caller_scope(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<Value>> {
        self.call_magic_instance_method_with_values_and_caller_scope_and_arg_sources(
            object,
            method_name,
            args,
            span,
            caller_scope,
            Vec::new(),
        )
    }

    fn call_magic_instance_method_with_values_and_caller_scope_and_arg_sources(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
        caller_scope: &mut SymbolTable,
        indexed_array_copy_source_bindings: Vec<IndexedArrayCopySourceBinding>,
    ) -> CompileResult<Option<Value>> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), method_name)
        else {
            return Ok(None);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, method_name, visibility, span)?;

        if self.resolved_method_is_core_array_object(class_id) {
            return self
                .call_array_object_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            return self
                .call_spl_object_storage_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_fixed_array(class_id) {
            return self
                .call_spl_fixed_array_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(class_id) {
            return self
                .call_spl_doubly_linked_list_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_directory_iterator(class_id) {
            return self
                .call_spl_directory_iterator_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_filesystem_iterator(class_id) {
            return self
                .call_spl_filesystem_iterator_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_recursive_directory_iterator(class_id) {
            return self
                .call_spl_recursive_directory_iterator_method_with_values(
                    object,
                    method_name,
                    args,
                    span,
                )
                .map(Some);
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(class_id) {
            return self
                .call_spl_recursive_iterator_iterator_method_with_values(
                    object,
                    method_name,
                    args,
                    span,
                )
                .map(Some);
        }

        if self.resolved_method_is_core_spl_file_info(class_id) {
            return self
                .call_spl_file_info_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_file_object(class_id) {
            return self
                .call_spl_file_object_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(class_id) {
            return self
                .call_spl_iterator_wrapper_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        if self.resolved_method_is_core_php_token(class_id)
            && php_token_core_instance_method(method_name)
        {
            return self
                .call_php_token_method_with_values(object, method_name, args, span)
                .map(Some);
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity(function, args.len(), span)?;
        ensure_supported_magic_array_access_function_signature(function, args.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        let by_value_array_copy_source_bindings = Self::array_copy_source_bindings_for_indexed_args(
            function,
            indexed_array_copy_source_bindings,
        );
        self.call_user_function_with_checked_values_and_locals_with_array_copy_source_and_arg_sources(
            function,
            args,
            Vec::new(),
            Some(object),
            Some(class_id),
            Some(called_class_id),
            Vec::new(),
            Some(&mut *caller_scope),
            Vec::new(),
            Vec::new(),
            by_value_array_copy_source_bindings,
            None,
        )
        .map(|(value, _)| value)
        .map(Some)
    }

    fn call_reference_return_magic_instance_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnBinding>> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), method_name)
        else {
            return Ok(None);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, method_name, visibility, span)?;

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        if !function.returns_by_reference {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "function does not return by reference",
                ),
            ));
        }
        ensure_user_function_arity(function, args.len(), span)?;
        ensure_supported_reference_return_function_metadata(function, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        self.call_reference_return_function_with_checked_values_for_reference_assignment(
            function,
            args,
            Some(object),
            Some(class_id),
            Some(called_class_id),
            Vec::new(),
            caller_scope,
        )
        .map(Some)
    }

    fn is_undefined_property_error(error: &RuntimeError) -> bool {
        matches!(error.kind(), RuntimeErrorKind::UndefinedProperty { .. })
    }

    fn is_magic_get_fallback_property_error(error: &RuntimeError) -> bool {
        matches!(
            error.kind(),
            RuntimeErrorKind::UndefinedProperty { .. }
                | RuntimeErrorKind::UnsupportedPropertyAccess { .. }
        )
    }

    fn is_magic_get_fallback_property_error_for_object(
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        error: &RuntimeError,
    ) -> bool {
        Self::is_magic_get_fallback_property_error(error)
            || Self::is_unset_typed_property_read_error_for_object(
                object,
                property,
                current_class_id,
                protected_class_ids,
                error,
            )
    }

    fn is_unset_typed_property_read_error_for_object(
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        error: &RuntimeError,
    ) -> bool {
        matches!(
            error.kind(),
            RuntimeErrorKind::UninitializedTypedProperty { .. }
        ) && object
            .is_unset_property_from_context(property, current_class_id, protected_class_ids)
            .unwrap_or(false)
    }

    fn coerce_magic_get_unset_typed_property_value(
        &self,
        object: &PhpObject,
        property: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        value: Value,
        source: Option<ArrayCopySource>,
        strict_scalars: bool,
        span: Span,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let value = object
            .coerce_unset_typed_property_read_value_from_context_with_object_type_resolver(
                property,
                value,
                current_class_id,
                protected_class_ids,
                strict_scalars,
                |object, type_name| self.object_satisfies_live_property_type(object, type_name),
            )
            .map_err(|error| runtime_error(span, error))?;
        let source = if matches!(value, Value::Array(_)) {
            source
        } else {
            None
        };
        Ok((value, source))
    }

    fn evaluate_dynamic_property_read(
        &mut self,
        target: &Expr,
        property: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let property = self.evaluate_dynamic_property_name(property, span, scope)?;
        let target_value = self.evaluate(target, scope)?;

        match target_value {
            Value::Object(object) => {
                if let Some(value) =
                    self.read_dom_document_type_property(&object, &property, span)?
                {
                    return Ok(value);
                }
                let (current_class_id, protected_class_ids) =
                    self.current_property_access_context();
                match object.read_property_from_context(
                    &property,
                    current_class_id,
                    &protected_class_ids,
                ) {
                    Ok(value) => {
                        if self.array_object_property_should_use_storage(
                            &object,
                            &property,
                            current_class_id,
                            &protected_class_ids,
                            span,
                        )? {
                            return self
                                .array_object_read_property_from_storage(&object, &property, span);
                        }
                        Ok(value)
                    }
                    Err(error)
                        if Self::is_magic_get_fallback_property_error_for_object(
                            &object,
                            &property,
                            current_class_id,
                            &protected_class_ids,
                            &error,
                        ) =>
                    {
                        let type_check_unset_typed =
                            Self::is_unset_typed_property_read_error_for_object(
                                &object,
                                &property,
                                current_class_id,
                                &protected_class_ids,
                                &error,
                            );
                        if self.array_object_property_should_use_storage(
                            &object,
                            &property,
                            current_class_id,
                            &protected_class_ids,
                            span,
                        )? {
                            return self
                                .array_object_read_property_from_storage(&object, &property, span);
                        }
                        self.call_magic_get_property_value_with_array_copy_source(
                            object.clone(),
                            &property,
                            span,
                            scope,
                        )?
                        .map(|(value, _, magic_strict_types)| {
                            if type_check_unset_typed {
                                self.coerce_magic_get_unset_typed_property_value(
                                    &object,
                                    &property,
                                    current_class_id,
                                    &protected_class_ids,
                                    value,
                                    None,
                                    magic_strict_types,
                                    span,
                                )
                                .map(|(value, _)| value)
                            } else {
                                Ok(value)
                            }
                        })
                        .transpose()?
                        .map(Ok)
                        .unwrap_or_else(|| {
                            if Self::is_undefined_property_error(&error) {
                                self.emit_undefined_property_warning(
                                    object.class_name(),
                                    &property,
                                    span,
                                )?;
                                Ok(Value::Null)
                            } else {
                                Err(runtime_error(span, error))
                            }
                        })
                    }
                    Err(error) => Err(runtime_error(span, error)),
                }
            }
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_property_access(format!(
                    "cannot read property ${property} from {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn evaluate_dynamic_property_read_with_array_copy_source(
        &mut self,
        target: &Expr,
        property: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let property = self.evaluate_dynamic_property_name(property, span, scope)?;
        self.evaluate_property_read_with_array_copy_source(target, &property, span, scope)
    }

    fn evaluate_dynamic_property_name(
        &mut self,
        property: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<String> {
        match self.evaluate(property, scope)? {
            Value::String(value) => Ok(value),
            Value::Int(value) => Ok(value.to_string()),
            other => Err(runtime_error(
                span,
                RuntimeError::invalid_property_access(format!(
                    "dynamic property names only support strings and integers in the current subset, got {}",
                    other.type_name()
                )),
            )),
        }
    }

    fn call_instance_method(
        &mut self,
        target: &Expr,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        self.call_instance_method_with_array_copy_source(
            target,
            method_name,
            args,
            span,
            caller_scope,
        )
        .map(|(value, _)| value)
    }

    fn call_dynamic_instance_method(
        &mut self,
        target: &Expr,
        method: &Expr,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        self.call_dynamic_instance_method_with_array_copy_source(
            target,
            method,
            args,
            span,
            caller_scope,
        )
        .map(|(value, _)| value)
    }

    fn call_dynamic_instance_method_with_array_copy_source(
        &mut self,
        target: &Expr,
        method: &Expr,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let method_name = self.evaluate_dynamic_method_name(method, span, caller_scope)?;
        self.call_instance_method_with_array_copy_source(
            target,
            &method_name,
            args,
            span,
            caller_scope,
        )
    }

    fn call_closure_bind_to(
        &mut self,
        closure: PhpClosure,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "Closure::bindTo()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let new_this = self.evaluate_by_value_argument_with_cow_source(&args[0], caller_scope)?;
        let this_object = match new_this {
            Value::Null => None,
            Value::Object(object) => Some(object),
            other => {
                return Err(runtime_error(
                    args[0].span(),
                    RuntimeError::unsupported_call(
                        "Closure::bindTo()",
                        format!(
                            "Argument #1 ($newThis) must be of type ?object, {} given",
                            php_type_error_given(&other)
                        ),
                    ),
                ));
            }
        };

        let scope_class_id = if let Some(scope_expr) = args.get(1) {
            let scope_value =
                self.evaluate_by_value_argument_with_cow_source(scope_expr, caller_scope)?;
            self.closure_bind_scope_class_id(&closure, scope_value, scope_expr.span())?
        } else {
            this_object
                .as_ref()
                .map(|object| object.class_id())
                .or_else(|| {
                    self.closure_bound_contexts
                        .get(&closure.id())
                        .and_then(|context| context.class_context)
                })
        };
        let called_class_id = scope_class_id.or_else(|| this_object.as_ref().map(|o| o.class_id()));

        let rebound = self.clone_closure_with_bound_context(
            &closure,
            this_object,
            scope_class_id,
            called_class_id,
            span,
        )?;
        Ok((Value::Closure(rebound), None))
    }

    fn closure_bind_scope_class_id(
        &self,
        closure: &PhpClosure,
        value: Value,
        span: Span,
    ) -> CompileResult<Option<ClassId>> {
        match value {
            Value::Null => Ok(None),
            Value::Object(object) => Ok(Some(object.class_id())),
            Value::String(class_name) => {
                if class_name.eq_ignore_ascii_case("static") {
                    return Ok(self.closure_bound_contexts.get(&closure.id()).and_then(
                        |context| context.called_class_context.or(context.class_context),
                    ));
                }
                let lookup = class_name.strip_prefix('\\').unwrap_or(&class_name);
                self.classes
                    .lookup_class_id(lookup)
                    .map(Some)
                    .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(lookup)))
            }
            Value::BinaryString(bytes) => {
                let class_name = String::from_utf8(bytes).map_err(|_| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "Closure::bindTo()",
                            "Argument #2 ($newScope) must be a valid class name",
                        ),
                    )
                })?;
                let lookup = class_name.strip_prefix('\\').unwrap_or(&class_name);
                self.classes
                    .lookup_class_id(lookup)
                    .map(Some)
                    .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class(lookup)))
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Closure::bindTo()",
                    format!(
                        "Argument #2 ($newScope) must be of type object|string|null, {} given",
                        php_type_error_given(&other)
                    ),
                ),
            )),
        }
    }

    fn clone_closure_with_bound_context(
        &mut self,
        closure: &PhpClosure,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        span: Span,
    ) -> CompileResult<PhpClosure> {
        let id = self.allocate_object_id();
        let captures = closure.captures().to_vec();
        let rebound = if let Some(descriptor) = closure.descriptor() {
            PhpClosure::new_with_descriptor(id, closure.is_arrow(), captures, descriptor)
        } else {
            PhpClosure::new(id, closure.is_arrow(), captures)
        };

        let function = self
            .closure_functions
            .get(&closure.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "Closure::bindTo()",
                        "closure body metadata is missing in the current subset",
                    ),
                )
            })?;
        self.closure_functions.insert(id, function);

        if let Some(mut state) = self
            .closure_reflection_functions
            .get(&closure.id())
            .cloned()
        {
            state.closure_id = Some(id);
            state.closure_scope_class_id = class_context;
            state.closure_called_class_id = called_class_context;
            state.closure_this = this_object.clone();
            self.closure_reflection_functions.insert(id, state);
        }

        self.closure_values.insert(id, rebound.clone());
        if this_object.is_some() || class_context.is_some() || called_class_context.is_some() {
            self.closure_bound_contexts.insert(
                id,
                ClosureBoundContext {
                    this_object,
                    class_context,
                    called_class_context,
                },
            );
        }
        if let Some(alias_captures) = self.closure_alias_captures.get(&closure.id()).cloned() {
            self.closure_alias_captures.insert(id, alias_captures);
        }
        if let Some(array_copy_source_captures) = self
            .closure_array_copy_source_captures
            .get(&closure.id())
            .cloned()
        {
            self.closure_array_copy_source_captures
                .insert(id, array_copy_source_captures);
        }

        Ok(rebound)
    }

    fn evaluate_dynamic_method_name(
        &mut self,
        method: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<String> {
        match self.evaluate(method, scope)? {
            Value::String(value) => Ok(value),
            Value::Int(value) => Ok(value.to_string()),
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "dynamic method call",
                    format!(
                        "method name must evaluate to string or integer in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn call_instance_method_with_array_copy_source(
        &mut self,
        target: &Expr,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let target_value = self.evaluate(target, caller_scope)?;
        let object = match target_value {
            Value::Object(object) => object,
            Value::Closure(closure) if method_name.eq_ignore_ascii_case("bindTo") => {
                return self.call_closure_bind_to(closure, args, span, caller_scope);
            }
            Value::Closure(closure) if method_name.eq_ignore_ascii_case("__invoke") => {
                return self.invoke_closure_value_direct_with_array_copy_source(
                    closure,
                    args,
                    span,
                    caller_scope,
                    "Closure::__invoke",
                );
            }
            other => {
                return Err(Diagnostic::new(
                    Phase::Runtime,
                    span.line,
                    span.column,
                    format!(
                        "Call to a member function {method_name}() on {}",
                        other.type_name()
                    ),
                ));
            }
        };
        if object.is_instance_of_class_name("Error")
            || object.is_instance_of_class_name("Exception")
        {
            return self
                .call_core_error_method(object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("Generator") {
            return self
                .call_generator_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("Directory") {
            return self
                .call_directory_method(object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("mysqli") {
            return self
                .call_mysqli_method(object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("PhpToken")
            && php_token_core_instance_method(method_name)
        {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            return self
                .call_php_token_method_with_values(object, method_name, values, span)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DateTimeZone")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_datetimezone,
            )
        {
            return self
                .call_datetimezone_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DateInterval")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_dateinterval,
            )
        {
            return self
                .call_dateinterval_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DatePeriod")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_dateperiod,
            )
        {
            return self
                .call_dateperiod_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DateTime")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_datetime,
            )
        {
            return self
                .call_datetime_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DateTimeImmutable")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_datetimeimmutable,
            )
        {
            return self
                .call_datetimeimmutable_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("NoDiscard") {
            return self
                .call_no_discard_method(method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("Deprecated") {
            return self
                .call_deprecated_method(method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("SensitiveParameterValue")
        {
            return self
                .call_sensitive_parameter_value_method(&object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("ReflectionClass")
            && self.instance_method_resolves_to_core_class(
                &object,
                method_name,
                Self::resolved_method_is_core_reflection_class,
            )
        {
            return self
                .call_reflection_class_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionFunction")
        {
            return self
                .call_reflection_function_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("ReflectionMethod") {
            return self.call_reflection_method_method_with_array_copy_source(
                object,
                method_name,
                args,
                span,
                caller_scope,
            );
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionParameter")
        {
            return self
                .call_reflection_parameter_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionProperty")
        {
            return self
                .call_reflection_property_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionClassConstant")
        {
            return self
                .call_reflection_class_constant_method(
                    object,
                    method_name,
                    args,
                    span,
                    caller_scope,
                )
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionConstant")
        {
            return self
                .call_reflection_constant_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionAttribute")
        {
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_reflection_attribute_method(object, method_name, args, span);
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &[], error);
            }
            return result.map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionExtension")
        {
            return self
                .call_reflection_extension_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionZendExtension")
        {
            return self
                .call_reflection_zend_extension_method(
                    object,
                    method_name,
                    args,
                    span,
                    caller_scope,
                )
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionNamedType")
        {
            return self
                .call_reflection_named_type_method(object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("ReflectionUnionType")
            || object
                .class_name()
                .eq_ignore_ascii_case("ReflectionIntersectionType")
        {
            return self
                .call_reflection_compound_type_method(object, method_name, args, span)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("BcMath\\Number") {
            return self
                .call_bcmath_number_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object
            .class_name()
            .eq_ignore_ascii_case("Uri\\Rfc3986\\Uri")
        {
            return self
                .call_uri_rfc3986_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.class_name().eq_ignore_ascii_case("Uri\\WhatWg\\Url") {
            return self
                .call_uri_whatwg_url_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }
        if object.is_instance_of_class_name("DOMNode") {
            return self
                .call_dom_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None));
        }

        let (class_id, class_name, resolved_method_name, visibility, is_static) = {
            let receiver_class_name = self
                .classes
                .get(object.class_id())
                .expect("object class id should resolve to class metadata")
                .name()
                .to_string();
            let Some(method) = self
                .resolve_instance_method_for_current_object_scope(object.class_id(), method_name)
            else {
                if let Some(result) = self
                    .call_missing_instance_method_via_magic_with_array_copy_source(
                        object.clone(),
                        method_name,
                        args,
                        span,
                        caller_scope,
                    )?
                {
                    return Ok(result);
                }
                return match self.call_missing_instance_method_via_magic(
                    object,
                    method_name,
                    args,
                    span,
                    caller_scope,
                )? {
                    Some(value) => Ok((value, None)),
                    None => Err(runtime_error(
                        span,
                        RuntimeError::undefined_function(format!(
                            "{receiver_class_name}::{method_name}()"
                        )),
                    )),
                };
            };
            method
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::{method_name}()"),
                    "static method dispatch through object receivers is not implemented",
                ),
            ));
        }

        if !self.method_visible_for_dispatch(
            Some(object.class_id()),
            class_id,
            method_name,
            visibility,
        ) {
            if let Some(result) = self
                .call_missing_instance_method_via_magic_with_array_copy_source(
                    object.clone(),
                    method_name,
                    args,
                    span,
                    caller_scope,
                )?
            {
                return Ok(result);
            }
            if let Some(value) = self.call_missing_instance_method_via_magic(
                object.clone(),
                method_name,
                args,
                span,
                caller_scope,
            )? {
                return Ok((value, None));
            }
            return Err(self.method_visibility_error(&class_name, method_name, visibility, span));
        }

        if self.resolved_method_is_core_array_object(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            return self
                .call_array_object_method_with_values_and_uncaught_frame(
                    object,
                    method_name,
                    values,
                    span,
                )
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_object_storage(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            return self
                .call_spl_object_storage_method_with_values(object, method_name, values, span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_fixed_array(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            return self
                .call_spl_fixed_array_method_with_values(object, method_name, values, span)
                .map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_doubly_linked_list(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_doubly_linked_list_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_directory_iterator(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_directory_iterator_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_filesystem_iterator(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_filesystem_iterator_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_recursive_directory_iterator(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_recursive_directory_iterator_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_recursive_iterator_iterator(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_recursive_iterator_iterator_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_file_object(class_id) {
            let values = self.evaluate_spl_file_object_method_arguments(
                method_name,
                args,
                span,
                caller_scope,
            )?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_file_object_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_file_info(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_file_info_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        if self.resolved_method_is_core_spl_iterator_wrapper(class_id) {
            let values = args
                .iter()
                .map(|arg| self.evaluate(arg, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            let callable = format!("{}->{method_name}", object.class_name());
            let result = self.call_spl_iterator_wrapper_method_with_values(
                object,
                method_name,
                values.clone(),
                span,
            );
            if let Err(error) = &result {
                self.record_pending_uncaught_internal_call_frame(callable, span, &values, error);
            }
            return result.map(|value| (value, None));
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        Self::ensure_user_function_expr_arity_unless_spread(function, args, span)?;
        if function.returns_by_reference {
            ensure_supported_reference_return_function_metadata(function, span)?;
            self.ensure_user_function_call_depth(function, span)?;

            let (values, reference_bindings, by_value_array_copy_source_bindings) = self
                .evaluate_user_function_call_arguments_with_options_and_array_copy_sources(
                    function,
                    args,
                    span,
                    caller_scope,
                    true,
                )?;
            let called_class_id = object.class_id();
            return self
                .call_reference_return_function_value_with_checked_values_with_array_copy_sources_and_return_source(
                    function,
                    values,
                    Some(object),
                    Some(class_id),
                    Some(called_class_id),
                    reference_bindings,
                    caller_scope,
                    by_value_array_copy_source_bindings,
                );
        }
        ensure_supported_function_metadata(function, span)?;

        let called_class_id = object.class_id();
        self.call_source_aware_user_function_with_expr_args(
            function,
            args,
            span,
            caller_scope,
            Some(object),
            Some(class_id),
            Some(called_class_id),
            Vec::new(),
        )
    }

    fn call_core_error_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
    ) -> CompileResult<Value> {
        self.call_core_error_method_with_arg_count(&object, method_name, args.len(), span)
    }

    fn call_core_error_method_with_arg_count(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        arg_count: usize,
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "getmessage" => {
                expect_expr_arity("Error::getMessage", arg_count, 0, span)?;
                Ok(Value::String(self.throwable_message_for_fatal(object)))
            }
            "getcode" => {
                expect_expr_arity("Error::getCode", arg_count, 0, span)?;
                let protected_class_ids = self.protected_class_ids_for_context(object.class_id());
                object
                    .read_property_from_context(
                        "code",
                        Some(object.class_id()),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))
            }
            "getfile" => {
                expect_expr_arity("Error::getFile", arg_count, 0, span)?;
                Ok(Value::String(
                    self.throwable_display_file_for_object(object),
                ))
            }
            "getline" => {
                expect_expr_arity("Error::getLine", arg_count, 0, span)?;
                let protected_class_ids = self.protected_class_ids_for_context(object.class_id());
                object
                    .read_property_from_context(
                        "line",
                        Some(object.class_id()),
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(span, error))
            }
            "getprevious" => {
                expect_expr_arity("Error::getPrevious", arg_count, 0, span)?;
                let protected_class_ids = self.protected_class_ids_for_context(object.class_id());
                Ok(object
                    .read_property_from_context(
                        "previous",
                        Some(object.class_id()),
                        &protected_class_ids,
                    )
                    .unwrap_or(Value::Null))
            }
            "gettraceasstring" => {
                expect_expr_arity("Error::getTraceAsString", arg_count, 0, span)?;
                Ok(Value::String(self.throwable_trace_as_string(object)))
            }
            "gettrace" => {
                expect_expr_arity("Error::getTrace", arg_count, 0, span)?;
                self.throwable_trace_array(object, span)
            }
            "getseverity" if object.is_instance_of_class_name("ErrorException") => {
                expect_expr_arity("ErrorException::getSeverity", arg_count, 0, span)?;
                let protected_class_ids = self.protected_class_ids_for_context(object.class_id());
                match object.read_property_from_context(
                    "severity",
                    Some(object.class_id()),
                    &protected_class_ids,
                ) {
                    Ok(Value::Int(severity)) => Ok(Value::Int(severity)),
                    Ok(Value::Bool(true)) => Ok(Value::Int(1)),
                    Ok(Value::Bool(false) | Value::Null) | Err(_) => Ok(Value::Int(PHP_E_ERROR)),
                    Ok(Value::Float(severity)) => Ok(Value::Int(severity as i64)),
                    Ok(Value::String(severity)) => {
                        severity.parse::<i64>().map(Value::Int).map_err(|_| {
                            runtime_error(
                                span,
                                RuntimeError::unsupported_call(
                                    "ErrorException::getSeverity()",
                                    "severity property must be int-like in the current subset",
                                ),
                            )
                        })
                    }
                    Ok(_) => Ok(Value::Int(PHP_E_ERROR)),
                }
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("Error::{method_name}()")),
            )),
        }
    }

    fn call_no_discard_method(
        &mut self,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                let mut trace_args = Vec::new();
                let result = self.no_discard_attribute_message_from_exprs_inner(
                    args,
                    self.current_strict_types(),
                    &mut trace_args,
                    caller_scope,
                );
                if let Err(error) = &result {
                    self.record_pending_uncaught_internal_call_frame(
                        "NoDiscard->__construct",
                        span,
                        &trace_args,
                        error,
                    );
                }
                result?;

                let error = Self::no_discard_readonly_message_property_error(span);
                self.record_pending_uncaught_internal_call_frame(
                    "NoDiscard->__construct",
                    span,
                    &trace_args,
                    &error,
                );
                Err(error)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("NoDiscard::{method_name}()")),
            )),
        }
    }

    fn call_deprecated_method(
        &mut self,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                let mut trace_args = Vec::new();
                let result = self.deprecated_attribute_message_parts_from_exprs_inner(
                    args,
                    self.current_strict_types(),
                    &mut trace_args,
                    caller_scope,
                );
                if let Err(error) = &result {
                    self.record_pending_uncaught_internal_call_frame(
                        "Deprecated->__construct",
                        span,
                        &trace_args,
                        error,
                    );
                }
                result?;

                let error = Self::deprecated_readonly_property_error("message", span);
                self.record_pending_uncaught_internal_call_frame(
                    "Deprecated->__construct",
                    span,
                    &trace_args,
                    &error,
                );
                Err(error)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("Deprecated::{method_name}()")),
            )),
        }
    }

    fn call_sensitive_parameter_value_method(
        &mut self,
        object: &PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
    ) -> CompileResult<Value> {
        match method_name.to_ascii_lowercase().as_str() {
            "getvalue" => {
                expect_expr_arity("SensitiveParameterValue::getValue", args.len(), 0, span)?;
                let class_id = object.class_id();
                let protected_class_ids = self.protected_class_ids_for_context(class_id);
                object
                    .read_property_from_context("value", Some(class_id), &protected_class_ids)
                    .map_err(|error| runtime_error(span, error))
            }
            "__construct" => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "SensitiveParameterValue::__construct()",
                    "manual reinitialization is not supported in the current subset",
                ),
            )),
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!(
                    "SensitiveParameterValue::{method_name}()"
                )),
            )),
        }
    }

    fn deprecated_readonly_property_error(property: &str, span: Span) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::unsupported_property_access(format!(
                "Cannot modify readonly property Deprecated::${property}"
            )),
        )
    }

    fn no_discard_readonly_message_property_error(span: Span) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::unsupported_property_access(
                "Cannot modify readonly property NoDiscard::$message",
            ),
        )
    }

    fn call_reflection_class_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let state = self
            .reflection_classes
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionClass::{method_name}()"),
                        "missing ReflectionClass runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "__construct" if object.class_name().eq_ignore_ascii_case("ReflectionObject") => {
                expect_expr_arity("ReflectionObject::__construct", args.len(), 1, span)?;
                let target = self.evaluate(&args[0], caller_scope)?;
                if !matches!(target, Value::Object(_) | Value::Closure(_)) {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "ReflectionObject::__construct()",
                            format!(
                                "argument must be object in the current subset, got {}",
                                target.type_name()
                            ),
                        ),
                    ));
                }
                let state = self.resolve_reflection_class_target(&target, span)?;
                self.assign_reflection_object_state(&object, state, span)?;
                Ok(Value::Null)
            }
            "__construct" => {
                self.assign_reflection_class_constructor_state_from_exprs(
                    &object,
                    args,
                    span,
                    caller_scope,
                )?;
                Ok(Value::Null)
            }
            "__tostring" => {
                expect_expr_arity("ReflectionClass::__toString", args.len(), 0, span)?;
                self.reflection_class_to_string(&state, span)
                    .map(Value::String)
            }
            "getname" => {
                expect_expr_arity("ReflectionClass::getName", args.len(), 0, span)?;
                Ok(Value::String(state.name))
            }
            "getshortname" => {
                expect_expr_arity("ReflectionClass::getShortName", args.len(), 0, span)?;
                Ok(Value::String(
                    state
                        .name
                        .rsplit('\\')
                        .next()
                        .unwrap_or(state.name.as_str())
                        .to_string(),
                ))
            }
            "getfilename" => {
                expect_expr_arity("ReflectionClass::getFileName", args.len(), 0, span)?;
                Ok(state
                    .file_name
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getstartline" => {
                expect_expr_arity("ReflectionClass::getStartLine", args.len(), 0, span)?;
                Ok(Value::Int(state.start_line as i64))
            }
            "getendline" => {
                expect_expr_arity("ReflectionClass::getEndLine", args.len(), 0, span)?;
                Ok(Value::Int(state.end_line as i64))
            }
            "getdoccomment" => {
                expect_expr_arity("ReflectionClass::getDocComment", args.len(), 0, span)?;
                Ok(state
                    .doc_comment
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getextensionname" => {
                expect_expr_arity("ReflectionClass::getExtensionName", args.len(), 0, span)?;
                Ok(reflection_extension_name_for_class_name(&state.name)
                    .map(|name| Value::String(name.to_string()))
                    .unwrap_or(Value::Bool(false)))
            }
            "getextension" => {
                expect_expr_arity("ReflectionClass::getExtension", args.len(), 0, span)?;
                let Some(extension_name) = reflection_extension_name_for_class_name(&state.name)
                else {
                    return Ok(Value::Null);
                };
                self.create_reflection_extension_object(
                    ReflectionExtensionState {
                        name: extension_name.to_string(),
                    },
                    span,
                )
            }
            "getattributes" => self.call_reflection_get_attributes(
                &state.attributes,
                PHP_ATTRIBUTE_TARGET_CLASS,
                args,
                span,
                caller_scope,
            ),
            "innamespace" => {
                expect_expr_arity("ReflectionClass::inNamespace", args.len(), 0, span)?;
                Ok(Value::Bool(state.name.contains('\\')))
            }
            "getnamespacename" => {
                expect_expr_arity("ReflectionClass::getNamespaceName", args.len(), 0, span)?;
                Ok(Value::String(reflection_class_namespace_name(&state.name)))
            }
            "isinternal" => {
                expect_expr_arity("ReflectionClass::isInternal", args.len(), 0, span)?;
                Ok(Value::Bool(!self.reflection_class_is_user_defined(&state)))
            }
            "isuserdefined" => {
                expect_expr_arity("ReflectionClass::isUserDefined", args.len(), 0, span)?;
                Ok(Value::Bool(self.reflection_class_is_user_defined(&state)))
            }
            "isinterface" => {
                expect_expr_arity("ReflectionClass::isInterface", args.len(), 0, span)?;
                Ok(Value::Bool(state.kind == ReflectionClassKind::Interface))
            }
            "istrait" => {
                expect_expr_arity("ReflectionClass::isTrait", args.len(), 0, span)?;
                Ok(Value::Bool(state.kind == ReflectionClassKind::Trait))
            }
            "isabstract" => {
                expect_expr_arity("ReflectionClass::isAbstract", args.len(), 0, span)?;
                Ok(Value::Bool(self.reflection_class_is_abstract(&state)))
            }
            "isfinal" => {
                expect_expr_arity("ReflectionClass::isFinal", args.len(), 0, span)?;
                Ok(Value::Bool(self.reflection_class_is_final(&state)))
            }
            "isreadonly" => {
                expect_expr_arity("ReflectionClass::isReadOnly", args.len(), 0, span)?;
                Ok(Value::Bool(false))
            }
            "iscloneable" => {
                expect_expr_arity("ReflectionClass::isCloneable", args.len(), 0, span)?;
                Ok(Value::Bool(self.reflection_class_is_cloneable(&state)))
            }
            "getmodifiers" => {
                expect_expr_arity("ReflectionClass::getModifiers", args.len(), 0, span)?;
                Ok(Value::Int(self.reflection_class_modifier_mask(&state)))
            }
            "isinstantiable" => {
                expect_expr_arity("ReflectionClass::isInstantiable", args.len(), 0, span)?;
                let instantiable = state
                    .class_id
                    .is_some_and(|class_id| !self.abstract_classes.contains(&class_id));
                Ok(Value::Bool(instantiable))
            }
            "newinstance" => {
                let values = args
                    .iter()
                    .map(|arg| self.evaluate(arg, caller_scope))
                    .collect::<CompileResult<Vec<_>>>()?;
                self.reflection_class_new_instance_from_values(&state, values, span)
            }
            "newinstanceargs" => {
                let values =
                    self.reflection_class_new_instance_args_values(args, span, caller_scope)?;
                self.reflection_class_new_instance_from_values(&state, values, span)
            }
            "newinstancewithoutconstructor" => {
                expect_expr_arity(
                    "ReflectionClass::newInstanceWithoutConstructor",
                    args.len(),
                    0,
                    span,
                )?;
                let (ReflectionClassKind::Class, Some(class_id)) = (state.kind, state.class_id)
                else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_object_instantiation(
                            state.name,
                            "only concrete classes can be instantiated without constructor",
                        ),
                    ));
                };
                if self.abstract_classes.contains(&class_id) {
                    return Err(Diagnostic::new(
                        Phase::Runtime,
                        span.line,
                        span.column,
                        format!("Cannot instantiate abstract class {}", state.name),
                    ));
                }
                let object = self.allocate_object_without_constructor(class_id, span)?;
                self.track_allocated_object(&object);
                Ok(Value::Object(object))
            }
            "isinstance" => {
                expect_expr_arity("ReflectionClass::isInstance", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let Value::Object(object) = value else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "ReflectionClass::isInstance",
                            format!(
                                "object argument must be object in the current subset, got {}",
                                value.type_name()
                            ),
                        ),
                    ));
                };
                Ok(Value::Bool(
                    self.reflection_class_matches_object(&state, &object),
                ))
            }
            "issubclassof" => {
                expect_expr_arity("ReflectionClass::isSubclassOf", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let target =
                    match self.resolve_reflection_class_subclass_target(value.clone(), span) {
                        Ok(target) => target,
                        Err(error) => {
                            self.record_pending_uncaught_internal_call_frame(
                                "ReflectionClass->isSubclassOf",
                                span,
                                &[value],
                                &error,
                            );
                            return Err(error);
                        }
                    };
                Ok(Value::Bool(
                    self.reflection_class_is_subclass_of(&state, &target),
                ))
            }
            "implementsinterface" => {
                expect_expr_arity("ReflectionClass::implementsInterface", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let target =
                    match self.resolve_reflection_class_interface_target(value.clone(), span) {
                        Ok(target) => target,
                        Err(error) => {
                            self.record_pending_uncaught_internal_call_frame(
                                "ReflectionClass->implementsInterface",
                                span,
                                &[value],
                                &error,
                            );
                            return Err(error);
                        }
                    };
                Ok(Value::Bool(self.reflection_class_implements_interface(
                    &state,
                    &target.name,
                )))
            }
            "isiterable" | "isiterateable" => {
                let method = if method_name.eq_ignore_ascii_case("isIterable") {
                    "ReflectionClass::isIterable"
                } else {
                    "ReflectionClass::isIterateable"
                };
                expect_expr_arity(method, args.len(), 0, span)?;
                Ok(Value::Bool(self.reflection_class_is_iterable(&state)))
            }
            "getparentclass" => {
                expect_expr_arity("ReflectionClass::getParentClass", args.len(), 0, span)?;
                let Some(class_id) = state.class_id else {
                    return Ok(Value::Bool(false));
                };
                let Some(parent_id) = self
                    .classes
                    .get(class_id)
                    .expect("reflected class id should resolve")
                    .parent_id()
                else {
                    return Ok(Value::Bool(false));
                };
                let parent_name = self
                    .classes
                    .get(parent_id)
                    .expect("reflected parent class id should resolve")
                    .name()
                    .to_string();
                self.create_reflection_class_object(
                    ReflectionClassState {
                        name: parent_name,
                        kind: ReflectionClassKind::Class,
                        class_id: Some(parent_id),
                        closure_id: None,
                        file_name: self
                            .class_source_metadata
                            .get(&parent_id)
                            .and_then(|metadata| metadata.file_name.clone()),
                        start_line: self
                            .class_source_metadata
                            .get(&parent_id)
                            .map(|metadata| metadata.start_line)
                            .unwrap_or(0),
                        end_line: self
                            .class_source_metadata
                            .get(&parent_id)
                            .map(|metadata| metadata.end_line)
                            .unwrap_or(0),
                        doc_comment: self
                            .class_source_metadata
                            .get(&parent_id)
                            .and_then(|metadata| metadata.doc_comment.clone()),
                        attributes: self
                            .class_source_metadata
                            .get(&parent_id)
                            .map(|metadata| metadata.attributes.clone())
                            .unwrap_or_default(),
                    },
                    span,
                )
            }
            "getinterfacenames" => {
                expect_expr_arity("ReflectionClass::getInterfaceNames", args.len(), 0, span)?;
                let mut names = PhpArray::new();
                match state.kind {
                    ReflectionClassKind::Class => {
                        if let Some(class_id) = state.class_id {
                            for interface_name in self.class_implements_interface_names(class_id) {
                                names
                                    .append(Value::String(interface_name))
                                    .expect("interface count fits in array keys");
                            }
                        }
                    }
                    ReflectionClassKind::Interface => {
                        if let Some(interface) =
                            self.interface_lookup.get(&state.name.to_ascii_lowercase())
                        {
                            for parent_name in &interface.parents {
                                names
                                    .append(Value::String(parent_name.clone()))
                                    .expect("interface parent count fits in array keys");
                            }
                        }
                    }
                    ReflectionClassKind::Trait => {}
                }
                Ok(Value::Array(names))
            }
            "getinterfaces" => {
                expect_expr_arity("ReflectionClass::getInterfaces", args.len(), 0, span)?;
                let mut interfaces = PhpArray::new();
                for interface_name in self.reflection_class_interface_names(&state) {
                    let interface = self.create_reflection_class_object(
                        self.reflection_class_state_for(
                            interface_name.clone(),
                            ReflectionClassKind::Interface,
                            None,
                        ),
                        span,
                    )?;
                    interfaces.insert(ArrayKey::String(interface_name), interface);
                }
                Ok(Value::Array(interfaces))
            }
            "gettraitnames" => {
                expect_expr_arity("ReflectionClass::getTraitNames", args.len(), 0, span)?;
                let mut names = PhpArray::new();
                for trait_name in self.reflection_class_trait_names(&state) {
                    names
                        .append(Value::String(trait_name))
                        .expect("trait count fits in array keys");
                }
                Ok(Value::Array(names))
            }
            "gettraits" => {
                expect_expr_arity("ReflectionClass::getTraits", args.len(), 0, span)?;
                let mut traits = PhpArray::new();
                for trait_name in self.reflection_class_trait_names(&state) {
                    let trait_reflection = self.create_reflection_class_object(
                        self.reflection_class_state_for(
                            trait_name.clone(),
                            ReflectionClassKind::Trait,
                            None,
                        ),
                        span,
                    )?;
                    traits.insert(ArrayKey::String(trait_name), trait_reflection);
                }
                Ok(Value::Array(traits))
            }
            "getconstructor" => {
                expect_expr_arity("ReflectionClass::getConstructor", args.len(), 0, span)?;
                if !self.reflection_class_has_method(&state, "__construct") {
                    return Ok(Value::Null);
                }
                let method = self.resolve_reflection_method_target(&state, "__construct", span)?;
                self.create_reflection_method_object(method, span)
            }
            "hasconstant" => {
                expect_expr_arity("ReflectionClass::hasConstant", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let constant = reflection_scalar_name_argument(value, span)?;
                Ok(Value::Bool(
                    self.reflection_class_resolve_constant(&state, &constant, span)?
                        .is_some(),
                ))
            }
            "getconstant" => {
                expect_expr_arity("ReflectionClass::getConstant", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let constant = reflection_scalar_name_argument(value, span)?;
                let Some(constant_state) =
                    self.reflection_class_resolve_constant(&state, &constant, span)?
                else {
                    self.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        "ReflectionClass::getConstant() for a non-existent constant is deprecated, use ReflectionClass::hasConstant() to check if the constant exists",
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                };
                self.evaluate_reflection_class_constant_value(&constant_state, span)
            }
            "getconstants" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "ReflectionClass::getConstants()",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let filter = if let Some(arg) = args.first() {
                    let value = self.evaluate(arg, caller_scope)?;
                    Some(reflection_class_constant_filter_argument(value, span)?)
                } else {
                    None
                };
                let mut constants = PhpArray::new();
                for constant in self.reflection_class_constants(&state, filter)? {
                    let value = self.evaluate_reflection_class_constant_value(&constant, span)?;
                    constants.insert(ArrayKey::String(constant.name), value);
                }
                Ok(Value::Array(constants))
            }
            "hasmethod" => {
                expect_expr_arity("ReflectionClass::hasMethod", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let method = reflection_scalar_string_argument(
                    "ReflectionClass::hasMethod",
                    "name",
                    value,
                    span,
                )?;
                Ok(Value::Bool(
                    self.reflection_class_has_method(&state, &method),
                ))
            }
            "getmethod" => {
                expect_expr_arity("ReflectionClass::getMethod", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let method = reflection_scalar_string_argument(
                    "ReflectionClass::getMethod",
                    "name",
                    value,
                    span,
                )?;
                let method = self.resolve_reflection_method_target(&state, &method, span)?;
                self.create_reflection_method_object(method, span)
            }
            "getmethods" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "ReflectionClass::getMethods()",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                let filter = if let Some(arg) = args.first() {
                    let value = self.evaluate(arg, caller_scope)?;
                    Some(reflection_method_filter_argument(value, span)?)
                } else {
                    None
                };
                let mut methods = PhpArray::new();
                for method in self.reflection_class_methods(&state, filter, span)? {
                    let method = self.create_reflection_method_object(method, span)?;
                    methods
                        .append(method)
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(Value::Array(methods))
            }
            "hasproperty" => {
                expect_expr_arity("ReflectionClass::hasProperty", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let Value::String(property) = value else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "ReflectionClass::hasProperty",
                            format!(
                                "property argument must be string in the current subset, got {}",
                                value.type_name()
                            ),
                        ),
                    ));
                };
                Ok(Value::Bool(
                    state.kind == ReflectionClassKind::Class
                        && state.class_id.is_some_and(|class_id| {
                            self.resolve_class_property_metadata(class_id, &property)
                                .is_some()
                        }),
                ))
            }
            "getproperty" => {
                expect_expr_arity("ReflectionClass::getProperty", args.len(), 1, span)?;
                let value = self.evaluate(&args[0], caller_scope)?;
                let Value::String(property) = value else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "ReflectionClass::getProperty",
                            format!(
                                "property argument must be string in the current subset, got {}",
                                value.type_name()
                            ),
                        ),
                    ));
                };
                let property = self.resolve_reflection_property_target(&state, &property, span)?;
                self.create_reflection_property_object(property, span)
            }
            "getproperties" => {
                expect_expr_arity("ReflectionClass::getProperties", args.len(), 0, span)?;
                let mut properties = PhpArray::new();
                if state.kind == ReflectionClassKind::Class {
                    if let Some(class_id) = state.class_id {
                        for property in self.reflection_class_properties(class_id) {
                            let property =
                                self.create_reflection_property_object(property, span)?;
                            properties
                                .append(property)
                                .map_err(|error| runtime_error(span, error))?;
                        }
                    }
                }
                Ok(Value::Array(properties))
            }
            "getstaticproperties" => {
                expect_expr_arity("ReflectionClass::getStaticProperties", args.len(), 0, span)?;
                Ok(Value::Array(
                    self.reflection_class_static_properties(&state),
                ))
            }
            "getdefaultproperties" => {
                expect_expr_arity("ReflectionClass::getDefaultProperties", args.len(), 0, span)?;
                self.reflection_class_default_properties(&state, span)
                    .map(Value::Array)
            }
            "getstaticpropertyvalue" => {
                if args.len() > 2 {
                    return Err(reflection_class_static_property_argument_error(
                        "ReflectionClass::getStaticPropertyValue",
                        format!(
                            "ReflectionClass::getStaticPropertyValue() expects at most 2 arguments, {} given",
                            args.len()
                        ),
                        span,
                    ));
                }
                let Some(name_arg) = args.first() else {
                    return Err(reflection_class_static_property_argument_error(
                        "ReflectionClass::getStaticPropertyValue",
                        "ReflectionClass::getStaticPropertyValue() expects at least 1 argument, 0 given",
                        span,
                    ));
                };
                let value = self.evaluate(name_arg, caller_scope)?;
                let property = self.reflection_class_static_property_name_argument(
                    "ReflectionClass::getStaticPropertyValue",
                    value,
                    span,
                )?;
                if let Some(value) =
                    self.reflection_class_static_property_value(&state, &property, span)?
                {
                    return Ok(value);
                }
                if let Some(default) = args.get(1) {
                    return self.evaluate(default, caller_scope);
                }
                Err(reflection_exception_error(
                    span,
                    format!("Property {}::${property} does not exist", state.name),
                ))
            }
            "setstaticpropertyvalue" => {
                if args.len() != 2 {
                    return Err(reflection_class_static_property_argument_error(
                        "ReflectionClass::setStaticPropertyValue",
                        format!(
                            "ReflectionClass::setStaticPropertyValue() expects exactly 2 arguments, {} given",
                            args.len()
                        ),
                        span,
                    ));
                }
                let value = self.evaluate(&args[0], caller_scope)?;
                let property = self.reflection_class_static_property_name_argument(
                    "ReflectionClass::setStaticPropertyValue",
                    value,
                    span,
                )?;
                let value = self.evaluate(&args[1], caller_scope)?;
                self.reflection_class_set_static_property_value(&state, &property, value, span)?;
                Ok(Value::Null)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("ReflectionClass::{method_name}()")),
            )),
        }
    }

    fn reflection_class_new_instance_args_values(
        &mut self,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Vec<Value>> {
        if args.len() > 1 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "ReflectionClass::newInstanceArgs()",
                    ArityExpectation::Between { min: 0, max: 1 },
                    args.len(),
                ),
            ));
        }
        let Some(arg) = args.first() else {
            return Ok(Vec::new());
        };
        let value = self.evaluate(arg, caller_scope)?;
        let Value::Array(array) = value else {
            let error = runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionClass::newInstanceArgs()",
                    format!(
                        "Argument #1 ($args) must be of type array, {} given",
                        php_type_error_given(&value)
                    ),
                ),
            );
            self.record_pending_uncaught_internal_call_frame(
                "ReflectionClass->newInstanceArgs",
                span,
                std::slice::from_ref(&value),
                &error,
            );
            return Err(error);
        };
        Ok(array
            .entries()
            .iter()
            .map(|entry| entry.value_cloned())
            .collect())
    }

    fn reflection_class_new_instance_from_values(
        &mut self,
        state: &ReflectionClassState,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let (ReflectionClassKind::Class, Some(class_id)) = (state.kind, state.class_id) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    state.name.clone(),
                    "only concrete classes can be instantiated by ReflectionClass::newInstance()",
                ),
            ));
        };
        if self.abstract_classes.contains(&class_id) {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                format!("Cannot instantiate abstract class {}", state.name),
            ));
        }

        let Some((
            constructor_class_id,
            constructor_class_name,
            constructor_name,
            constructor_visibility,
            constructor_is_static,
        )) = self.resolve_instance_method(class_id, "__construct")
        else {
            if !values.is_empty() {
                return Err(reflection_exception_error(
                    span,
                    format!(
                        "Class {} does not have a constructor, so you cannot pass any constructor arguments",
                        state.name
                    ),
                ));
            }
            let object = self.allocate_object_without_constructor(class_id, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        };

        if constructor_is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_object_instantiation(
                    state.name.clone(),
                    "static constructors are not implemented",
                ),
            ));
        }
        if constructor_visibility != Visibility::Public {
            return Err(reflection_exception_error(
                span,
                format!("Access to non-public constructor of class {}", state.name),
            ));
        }

        let object = self.allocate_object_without_constructor(class_id, span)?;
        if constructor_name.eq_ignore_ascii_case("__construct")
            && self.resolved_method_is_core_reflection_class(constructor_class_id)
        {
            self.assign_reflection_class_constructor_state_from_values(&object, values, span)?;
            self.track_allocated_object(&object);
            return Ok(Value::Object(object));
        }

        let function = self.method_function(
            constructor_class_id,
            &constructor_class_name,
            &constructor_name,
            span,
        )?;
        let function = function.as_ref();
        ensure_reflection_constructor_arity_with_extra_policy(
            function,
            values.len(),
            &constructor_class_name,
            &constructor_name,
            span,
        )?;
        ensure_supported_function_metadata(function, span)?;
        self.ensure_user_function_call_depth(function, span)?;
        self.emit_call_user_func_method_reference_parameter_warnings(
            function,
            values.len(),
            &constructor_class_name,
            &constructor_name,
            span,
        )?;

        if function_has_promoted_properties(function) {
            let protected_class_ids = self.protected_class_ids_for_context(constructor_class_id);
            for (param, value) in function.params.iter().zip(values.iter()) {
                if param.promotion.is_none() {
                    continue;
                }
                object
                    .write_property_from_context_with_object_type_resolver(
                        &param.name,
                        value.clone(),
                        Some(constructor_class_id),
                        &protected_class_ids,
                        |object, type_name| object.is_instance_of_class_name(type_name),
                    )
                    .map_err(|error| runtime_error(span, error))?;
            }
        }

        let trace_args = values.clone();
        let trace_callable = self.pending_uncaught_user_call_callable(
            function,
            Some(&object),
            Some(constructor_class_id),
        );
        let trace_function_line = function.span.line;
        let result = self.call_user_function_with_checked_values(
            function,
            values,
            Some(object.clone()),
            Some(constructor_class_id),
            Some(object.class_id()),
            Vec::new(),
            None,
        );
        if let Err(error) = &result {
            self.record_pending_uncaught_call_frame(
                trace_callable,
                trace_function_line,
                span,
                &trace_args,
                error,
            );
        }
        result?;
        self.track_allocated_object(&object);
        Ok(Value::Object(object))
    }

    fn reflection_class_is_user_defined(&self, state: &ReflectionClassState) -> bool {
        match state.kind {
            ReflectionClassKind::Class => state
                .class_id
                .is_some_and(|class_id| self.class_source_metadata.contains_key(&class_id)),
            ReflectionClassKind::Interface => self
                .interface_source_metadata
                .contains_key(&state.name.to_ascii_lowercase()),
            ReflectionClassKind::Trait => self
                .trait_source_metadata
                .contains_key(&state.name.to_ascii_lowercase()),
        }
    }

    fn reflection_class_is_abstract(&self, state: &ReflectionClassState) -> bool {
        state
            .class_id
            .is_some_and(|class_id| self.abstract_classes.contains(&class_id))
    }

    fn reflection_class_is_final(&self, state: &ReflectionClassState) -> bool {
        state
            .class_id
            .is_some_and(|class_id| self.final_classes.contains(&class_id))
    }

    fn reflection_class_modifier_mask(&self, state: &ReflectionClassState) -> i64 {
        let mut mask = 0;
        if self.reflection_class_is_final(state) {
            mask |= REFLECTION_MODIFIER_FINAL;
        }
        if self.reflection_class_is_abstract(state) {
            mask |= REFLECTION_MODIFIER_EXPLICIT_ABSTRACT;
        }
        mask
    }

    fn reflection_class_is_cloneable(&self, state: &ReflectionClassState) -> bool {
        let Some(class_id) = state.class_id else {
            return false;
        };
        if state.kind != ReflectionClassKind::Class || self.abstract_classes.contains(&class_id) {
            return false;
        }
        if reflection_object_is_uncloneable_class(&state.name)
            || state.name.eq_ignore_ascii_case("mysqli_driver")
        {
            return false;
        }
        !self
            .resolve_instance_method(class_id, "__clone")
            .is_some_and(|(_, _, _, visibility, is_static)| {
                is_static || visibility != Visibility::Public
            })
    }

    fn reflection_class_matches_object(
        &self,
        state: &ReflectionClassState,
        object: &PhpObject,
    ) -> bool {
        match state.kind {
            ReflectionClassKind::Class => state.class_id.is_some_and(|class_id| {
                object.class_id() == class_id
                    || self.classes.is_subclass_of(object.class_id(), class_id)
            }),
            ReflectionClassKind::Interface => {
                self.class_implements_or_matches_core_interface(object.class_id(), &state.name)
            }
            ReflectionClassKind::Trait => false,
        }
    }

    fn resolve_reflection_class_compare_argument(
        &mut self,
        value: Value,
        method: &'static str,
        parameter: &'static str,
        expected_type: &'static str,
        span: Span,
    ) -> CompileResult<ReflectionClassCompareArgument> {
        match value {
            Value::Object(object) if object.is_instance_of_class_name("ReflectionClass") => self
                .reflection_classes
                .get(&object.id())
                .cloned()
                .map(ReflectionClassCompareArgument::Reflected)
                .ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            method,
                            "missing ReflectionClass runtime metadata",
                        ),
                    )
                }),
            Value::Null => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "{method}: Passing null to parameter #1 (${parameter}) of type {expected_type} is deprecated"
                    ),
                    span,
                )?;
                Ok(ReflectionClassCompareArgument::Name(String::new()))
            }
            other => {
                let Some(bytes) = other.php_scalar_string_bytes() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            method,
                            format!(
                                "Argument #1 (${parameter}) must be of type {expected_type}, {} given",
                                php_type_error_given(&other)
                            ),
                        ),
                    ));
                };
                String::from_utf8(bytes)
                    .map(ReflectionClassCompareArgument::Name)
                    .map_err(|_| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                method,
                                format!(
                                    "Argument #1 (${parameter}) must be valid UTF-8 in the current subset"
                                ),
                            ),
                        )
                    })
            }
        }
    }

    fn resolve_reflection_class_subclass_target(
        &mut self,
        value: Value,
        span: Span,
    ) -> CompileResult<ReflectionClassState> {
        match self.resolve_reflection_class_compare_argument(
            value,
            "ReflectionClass::isSubclassOf()",
            "class",
            "ReflectionClass|string",
            span,
        )? {
            ReflectionClassCompareArgument::Reflected(state) => Ok(state),
            ReflectionClassCompareArgument::Name(name) => self
                .reflection_class_state_for_name_without_autoload(&name)
                .ok_or_else(|| {
                    reflection_exception_error(span, format!("Class \"{name}\" does not exist"))
                }),
        }
    }

    fn resolve_reflection_class_interface_target(
        &mut self,
        value: Value,
        span: Span,
    ) -> CompileResult<ReflectionClassState> {
        let target = match self.resolve_reflection_class_compare_argument(
            value,
            "ReflectionClass::implementsInterface()",
            "interface",
            "ReflectionClass|string",
            span,
        )? {
            ReflectionClassCompareArgument::Reflected(state) => state,
            ReflectionClassCompareArgument::Name(name) => self
                .reflection_class_state_for_name_without_autoload(&name)
                .ok_or_else(|| {
                    reflection_exception_error(span, format!("Interface \"{name}\" does not exist"))
                })?,
        };
        if target.kind != ReflectionClassKind::Interface {
            return Err(reflection_exception_error(
                span,
                format!("{} is not an interface", target.name),
            ));
        }
        Ok(target)
    }

    fn reflection_class_state_for_name_without_autoload(
        &self,
        name: &str,
    ) -> Option<ReflectionClassState> {
        if let Some(class) = self.classes.lookup_class(name) {
            return Some(self.reflection_class_state_for(
                class.name().to_string(),
                ReflectionClassKind::Class,
                Some(class.id()),
            ));
        }
        if let Some(interface) = self.interface_lookup.get(&name.to_ascii_lowercase()) {
            return Some(self.reflection_class_state_for(
                interface.name.clone(),
                ReflectionClassKind::Interface,
                None,
            ));
        }
        if let Some(trait_decl) = self.trait_lookup.get(&name.to_ascii_lowercase()) {
            return Some(self.reflection_class_state_for(
                trait_decl.name.clone(),
                ReflectionClassKind::Trait,
                None,
            ));
        }
        None
    }

    fn resolve_reflection_class_name_without_autoload(
        &self,
        name: &str,
        span: Span,
    ) -> CompileResult<ReflectionClassState> {
        self.reflection_class_state_for_name_without_autoload(name)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "ReflectionClass comparison",
                        format!("target {name} must name a declared class, interface, or trait"),
                    ),
                )
            })
    }

    fn reflection_class_implements_interface(
        &self,
        subject: &ReflectionClassState,
        interface_name: &str,
    ) -> bool {
        match subject.kind {
            ReflectionClassKind::Class => subject.class_id.is_some_and(|class_id| {
                self.class_implements_or_matches_core_interface(class_id, interface_name)
            }),
            ReflectionClassKind::Interface => {
                subject.name.eq_ignore_ascii_case(interface_name)
                    || self.interface_extends_interface(&subject.name, interface_name)
            }
            ReflectionClassKind::Trait => false,
        }
    }

    fn reflection_class_is_subclass_of(
        &self,
        child: &ReflectionClassState,
        parent: &ReflectionClassState,
    ) -> bool {
        match (child.kind, parent.kind) {
            (ReflectionClassKind::Class, ReflectionClassKind::Class) => {
                let (Some(child_id), Some(parent_id)) = (child.class_id, parent.class_id) else {
                    return false;
                };
                child_id != parent_id && self.classes.is_subclass_of(child_id, parent_id)
            }
            (ReflectionClassKind::Class, ReflectionClassKind::Interface) => {
                child.class_id.is_some_and(|class_id| {
                    self.class_implements_or_matches_core_interface(class_id, &parent.name)
                })
            }
            (ReflectionClassKind::Interface, ReflectionClassKind::Interface) => {
                !child.name.eq_ignore_ascii_case(&parent.name)
                    && self.interface_extends_interface(&child.name, &parent.name)
            }
            _ => false,
        }
    }

    fn interface_extends_interface(&self, child_name: &str, parent_name: &str) -> bool {
        let Some(interface) = self.interface_lookup.get(&child_name.to_ascii_lowercase()) else {
            return false;
        };
        interface.parents.iter().any(|candidate| {
            candidate.eq_ignore_ascii_case(parent_name)
                || self.interface_extends_interface(candidate, parent_name)
        })
    }

    fn reflection_class_is_iterable(&self, state: &ReflectionClassState) -> bool {
        match state.kind {
            ReflectionClassKind::Class => state.class_id.is_some_and(|class_id| {
                self.classes.implements_interface(class_id, "Iterator")
                    || self
                        .classes
                        .implements_interface(class_id, "IteratorAggregate")
            }),
            ReflectionClassKind::Interface => {
                state.name.eq_ignore_ascii_case("Traversable")
                    || state.name.eq_ignore_ascii_case("Iterator")
                    || state.name.eq_ignore_ascii_case("IteratorAggregate")
                    || self.interface_extends_interface(&state.name, "Traversable")
                    || self.interface_extends_interface(&state.name, "Iterator")
                    || self.interface_extends_interface(&state.name, "IteratorAggregate")
            }
            ReflectionClassKind::Trait => false,
        }
    }

    fn reflection_class_resolve_constant(
        &self,
        state: &ReflectionClassState,
        constant: &str,
        span: Span,
    ) -> CompileResult<Option<ReflectionClassConstantState>> {
        let resolution = match state.kind {
            ReflectionClassKind::Class => {
                let Some(class_id) = state.class_id else {
                    return Ok(None);
                };
                self.resolve_class_constant(class_id, constant)
            }
            ReflectionClassKind::Interface => {
                let Some(interface) = self.interface_lookup.get(&state.name.to_ascii_lowercase())
                else {
                    return Ok(None);
                };
                self.resolve_interface_constant(interface, constant)
            }
            ReflectionClassKind::Trait => {
                let Some(trait_decl) = self.trait_lookup.get(&state.name.to_ascii_lowercase())
                else {
                    return Ok(None);
                };
                self.resolve_trait_constant(trait_decl, constant)?
            }
        };

        match resolution {
            ConstantResolution::Found(resolved) => Ok(Some(
                ReflectionClassConstantState::from_resolved(constant, resolved),
            )),
            ConstantResolution::Missing => Ok(None),
            ConstantResolution::Ambiguous(owners) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{}::{constant}", state.name),
                    format!(
                        "interface constant resolution is ambiguous between {}",
                        owners.join(", ")
                    ),
                ),
            )),
        }
    }

    fn resolve_trait_constant(
        &self,
        trait_decl: &TraitDecl,
        constant: &str,
    ) -> CompileResult<ConstantResolution> {
        let mut matches = Vec::new();
        let mut path = HashSet::new();
        for constant_decl in
            composed_trait_constants_for_trait(trait_decl, &self.trait_lookup, &mut path)?
        {
            if constant_decl.name == constant {
                matches.push(ResolvedConstant {
                    declaring_class_id: None,
                    declaring_name: trait_decl.name.clone(),
                    visibility: runtime_visibility(constant_decl.visibility),
                    is_final: constant_decl.is_final,
                    type_decl: constant_decl.type_decl,
                    value: constant_decl.value,
                    kind: ConstantOwnerKind::Class,
                    attributes: constant_decl.attributes,
                });
            }
        }

        Ok(match matches.len() {
            0 => ConstantResolution::Missing,
            1 => ConstantResolution::Found(matches.remove(0)),
            _ => ConstantResolution::Ambiguous(
                matches
                    .into_iter()
                    .map(|resolved| format!("{}::{constant}", resolved.declaring_name))
                    .collect(),
            ),
        })
    }

    fn reflection_class_constants(
        &self,
        state: &ReflectionClassState,
        filter: Option<i64>,
    ) -> CompileResult<Vec<ReflectionClassConstantState>> {
        let mut constants = Vec::new();
        let mut seen = HashSet::new();
        match state.kind {
            ReflectionClassKind::Class => {
                if let Some(class_id) = state.class_id {
                    self.push_class_constant_states(class_id, filter, &mut seen, &mut constants);
                    self.push_class_interface_constant_states(
                        class_id,
                        filter,
                        &mut seen,
                        &mut constants,
                    );
                }
            }
            ReflectionClassKind::Interface => {
                if let Some(interface) = self.interface_lookup.get(&state.name.to_ascii_lowercase())
                {
                    self.push_interface_constant_states(
                        interface,
                        filter,
                        &mut seen,
                        &mut constants,
                    );
                }
            }
            ReflectionClassKind::Trait => {
                if let Some(trait_decl) = self.trait_lookup.get(&state.name.to_ascii_lowercase()) {
                    let mut path = HashSet::new();
                    for constant in composed_trait_constants_for_trait(
                        trait_decl,
                        &self.trait_lookup,
                        &mut path,
                    )? {
                        if !seen.insert(constant.name.clone()) {
                            continue;
                        }
                        let constant_state = ReflectionClassConstantState {
                            declaring_class_name: trait_decl.name.clone(),
                            declaring_class_id: None,
                            name: constant.name,
                            visibility: runtime_visibility(constant.visibility),
                            is_final: constant.is_final,
                            type_decl: constant.type_decl,
                            value: constant.value,
                            kind: ConstantOwnerKind::Class,
                            attributes: constant.attributes,
                        };
                        if reflection_class_constant_matches_filter(&constant_state, filter) {
                            constants.push(constant_state);
                        }
                    }
                }
            }
        }
        Ok(constants)
    }

    fn push_class_constant_states(
        &self,
        class_id: ClassId,
        filter: Option<i64>,
        seen: &mut HashSet<String>,
        constants: &mut Vec<ReflectionClassConstantState>,
    ) {
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            for metadata in class.constants() {
                if !seen.insert(metadata.name().to_string()) {
                    continue;
                }
                let Some(constant_state) =
                    self.reflection_class_constant_state_for_class_metadata(current_id, metadata)
                else {
                    continue;
                };
                if reflection_class_constant_matches_filter(&constant_state, filter) {
                    constants.push(constant_state);
                }
            }
            current = class.parent_id();
        }
    }

    fn reflection_class_constant_state_for_class_metadata(
        &self,
        class_id: ClassId,
        metadata: &PhpClassConstantMetadata,
    ) -> Option<ReflectionClassConstantState> {
        let class = self.classes.get(class_id)?;
        let constant = self
            .class_constants
            .get(&(class_id, metadata.name().to_string()))?;
        Some(ReflectionClassConstantState {
            declaring_class_name: class.name().to_string(),
            declaring_class_id: Some(class_id),
            name: metadata.name().to_string(),
            visibility: metadata.visibility(),
            is_final: metadata.is_final(),
            type_decl: constant.type_decl.clone(),
            value: constant.value.clone(),
            kind: ConstantOwnerKind::Class,
            attributes: constant.attributes.clone(),
        })
    }

    fn push_class_interface_constant_states(
        &self,
        class_id: ClassId,
        filter: Option<i64>,
        seen: &mut HashSet<String>,
        constants: &mut Vec<ReflectionClassConstantState>,
    ) {
        for interface_name in implemented_interface_names(&self.classes, class_id) {
            let Some(interface) = self
                .interface_lookup
                .get(&interface_name.to_ascii_lowercase())
            else {
                continue;
            };
            self.push_interface_constant_states(interface, filter, seen, constants);
        }
    }

    fn push_interface_constant_states(
        &self,
        interface: &InterfaceDecl,
        filter: Option<i64>,
        seen: &mut HashSet<String>,
        constants: &mut Vec<ReflectionClassConstantState>,
    ) {
        for constant in &interface.constants {
            if !seen.insert(constant.name.clone()) {
                continue;
            }
            let constant_state = ReflectionClassConstantState {
                declaring_class_name: interface.name.clone(),
                declaring_class_id: None,
                name: constant.name.clone(),
                visibility: Visibility::Public,
                is_final: constant.is_final,
                type_decl: constant.type_decl.clone(),
                value: constant.value.clone(),
                kind: ConstantOwnerKind::Interface,
                attributes: constant.attributes.clone(),
            };
            if reflection_class_constant_matches_filter(&constant_state, filter) {
                constants.push(constant_state);
            }
        }
        for parent_name in &interface.parents {
            let Some(parent) = self.interface_lookup.get(&parent_name.to_ascii_lowercase()) else {
                continue;
            };
            self.push_interface_constant_states(parent, filter, seen, constants);
        }
    }

    fn evaluate_reflection_class_constant_value(
        &mut self,
        constant: &ReflectionClassConstantState,
        span: Span,
    ) -> CompileResult<Value> {
        self.evaluate_reflection_constant_expr(
            constant.declaring_class_id,
            &constant.declaring_class_name,
            &constant.name,
            constant.kind,
            constant.type_decl.as_ref(),
            &constant.value,
            span,
        )
    }

    fn reflection_class_methods(
        &self,
        state: &ReflectionClassState,
        filter: Option<i64>,
        span: Span,
    ) -> CompileResult<Vec<ReflectionMethodState>> {
        let mut methods = Vec::new();
        if let Some(closure_id) = state.closure_id {
            let method_state = self.reflection_closure_invoke_method_state(closure_id, span)?;
            if reflection_method_matches_filter(&method_state, filter) {
                methods.push(method_state);
            }
            return Ok(methods);
        }
        match state.kind {
            ReflectionClassKind::Class => {
                let Some(class_id) = state.class_id else {
                    return Ok(methods);
                };
                let mut seen = HashSet::new();
                let mut trait_methods = Vec::new();
                let mut current = Some(class_id);
                let mut include_private = true;
                while let Some(current_id) = current {
                    let class = self
                        .classes
                        .get(current_id)
                        .expect("reflected class id should resolve");
                    let class_source = self.class_source_metadata.get(&current_id);
                    for method in class.methods() {
                        if !include_private && method.visibility() == Visibility::Private {
                            continue;
                        }
                        if !seen.insert(method.name().to_ascii_lowercase()) {
                            continue;
                        }
                        let method_state =
                            self.reflection_class_method_state(class_id, current_id, method);
                        let is_declared_in_class = class_source.is_some_and(|metadata| {
                            method_state.start_line >= metadata.start_line
                                && method_state.start_line <= metadata.end_line
                        });
                        if is_declared_in_class {
                            if reflection_method_matches_filter(&method_state, filter) {
                                methods.push(method_state);
                            }
                        } else {
                            trait_methods.push(method_state);
                        }
                    }
                    include_private = false;
                    current = class.parent_id();
                }
                for method_state in trait_methods {
                    if reflection_method_matches_filter(&method_state, filter) {
                        methods.push(method_state);
                    }
                }
            }
            ReflectionClassKind::Interface => {
                if let Some(interface) = self.interface_lookup.get(&state.name.to_ascii_lowercase())
                {
                    let mut seen = HashSet::new();
                    for method in &interface.methods {
                        let key = format!(
                            "{}::{}",
                            interface.name.to_ascii_lowercase(),
                            method.function.name.to_ascii_lowercase()
                        );
                        if !seen.insert(key) {
                            continue;
                        }
                        let method_state =
                            self.reflection_interface_method_state(interface.name.clone(), method);
                        if reflection_method_matches_filter(&method_state, filter) {
                            methods.push(method_state);
                        }
                    }
                    for parent_name in &interface.parents {
                        let Some(parent) =
                            self.interface_lookup.get(&parent_name.to_ascii_lowercase())
                        else {
                            continue;
                        };
                        for (declaring_interface, method) in
                            expanded_interface_methods(&self.interface_lookup, parent)
                        {
                            let key = format!(
                                "{}::{}",
                                declaring_interface.to_ascii_lowercase(),
                                method.function.name.to_ascii_lowercase()
                            );
                            if !seen.insert(key) {
                                continue;
                            }
                            let method_state =
                                self.reflection_interface_method_state(declaring_interface, method);
                            if reflection_method_matches_filter(&method_state, filter) {
                                methods.push(method_state);
                            }
                        }
                    }
                }
            }
            ReflectionClassKind::Trait => {
                if let Some(trait_decl) = self.trait_lookup.get(&state.name.to_ascii_lowercase()) {
                    for method in self.reflection_trait_methods(trait_decl)? {
                        let method_state = self.reflection_trait_method_state(trait_decl, &method);
                        if reflection_method_matches_filter(&method_state, filter) {
                            methods.push(method_state);
                        }
                    }
                }
            }
        }
        Ok(methods)
    }

    fn reflection_class_to_string(
        &mut self,
        state: &ReflectionClassState,
        span: Span,
    ) -> CompileResult<String> {
        if !self.reflection_class_is_user_defined(state) {
            if state.kind == ReflectionClassKind::Class
                && state.name.eq_ignore_ascii_case("Directory")
            {
                return Ok(directory_reflection_class_to_string().to_string());
            }
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionClass::__toString()",
                    "internal class string rendering is not implemented in the current subset",
                ),
            ));
        }

        let mut output = self.reflection_class_to_string_header(state);
        if let Some(file_name) = state.file_name.as_deref() {
            output.push_str(&format!(
                "  @@ {file_name} {}-{}\n",
                state.start_line, state.end_line
            ));
        }
        output.push('\n');

        let constants = self.reflection_class_constants(state, None)?;
        output.push_str(&format!("  - Constants [{}] {{\n", constants.len()));
        for constant in &constants {
            output.push_str("    ");
            output.push_str(&self.reflection_class_constant_to_string(constant, span)?);
            output.push('\n');
        }
        output.push_str("  }\n\n");

        let properties = match state.kind {
            ReflectionClassKind::Class => state
                .class_id
                .map(|class_id| self.reflection_class_properties(class_id))
                .unwrap_or_default(),
            ReflectionClassKind::Trait => {
                match self.trait_lookup.get(&state.name.to_ascii_lowercase()) {
                    Some(trait_decl) => composed_trait_properties_for_trait(
                        trait_decl,
                        &self.trait_lookup,
                        &mut HashSet::new(),
                    )?
                    .into_iter()
                    .map(|property| ReflectionPropertyState {
                        declaring_class_name: trait_decl.name.clone(),
                        declaring_kind: ReflectionClassKind::Trait,
                        declaring_class_id: None,
                        name: property.name,
                        doc_comment: property.doc_comment,
                        visibility: runtime_visibility(property.visibility),
                        is_static: property.is_static,
                        is_dynamic: false,
                        has_default: property.default.is_some(),
                        type_decl: property.type_decl.map(|decl| decl.text),
                        attributes: property.attributes,
                    })
                    .collect(),
                    None => Vec::new(),
                }
            }
            ReflectionClassKind::Interface => Vec::new(),
        };
        let (static_properties, instance_properties): (Vec<_>, Vec<_>) = properties
            .into_iter()
            .partition(|property| property.is_static);

        output.push_str(&format!(
            "  - Static properties [{}] {{\n",
            static_properties.len()
        ));
        for property in &static_properties {
            output.push_str("    ");
            output.push_str(&self.reflection_class_property_to_string(property, span)?);
            output.push('\n');
        }
        output.push_str("  }\n\n");

        let methods = self.reflection_class_methods(state, None, span)?;
        let (static_methods, instance_methods): (Vec<_>, Vec<_>) =
            methods.into_iter().partition(|method| method.is_static);

        output.push_str(&format!(
            "  - Static methods [{}] {{\n",
            static_methods.len()
        ));
        for (index, method) in static_methods.iter().enumerate() {
            if index > 0 {
                output.push('\n');
            }
            let method = self.reflection_method_to_string(method, span)?;
            output.push_str(&indent_reflection_block(&method, "    "));
        }
        output.push_str("  }\n\n");

        output.push_str(&format!(
            "  - Properties [{}] {{\n",
            instance_properties.len()
        ));
        for property in &instance_properties {
            output.push_str("    ");
            output.push_str(&self.reflection_class_property_to_string(property, span)?);
            output.push('\n');
        }
        output.push_str("  }\n\n");

        output.push_str(&format!("  - Methods [{}] {{\n", instance_methods.len()));
        for (index, method) in instance_methods.iter().enumerate() {
            if index > 0 {
                output.push('\n');
            }
            let method = self.reflection_method_to_string(method, span)?;
            output.push_str(&indent_reflection_block(&method, "    "));
        }
        output.push_str("  }\n}\n");
        Ok(output)
    }

    fn reflection_class_to_string_header(&self, state: &ReflectionClassState) -> String {
        match state.kind {
            ReflectionClassKind::Class => {
                let abstract_prefix = if self.reflection_class_is_abstract(state) {
                    "abstract "
                } else {
                    ""
                };
                let final_prefix = if self.reflection_class_is_final(state) {
                    "final "
                } else {
                    ""
                };
                let parent = state
                    .class_id
                    .and_then(|class_id| self.classes.get(class_id))
                    .and_then(|class| class.parent_id())
                    .and_then(|parent_id| self.classes.get(parent_id))
                    .map(|parent| format!(" extends {}", parent.name()))
                    .unwrap_or_default();
                format!(
                    "Class [ <user> {abstract_prefix}{final_prefix}class {}{parent} ] {{\n",
                    state.name
                )
            }
            ReflectionClassKind::Interface => {
                format!("Interface [ <user> interface {} ] {{\n", state.name)
            }
            ReflectionClassKind::Trait => {
                format!("Trait [ <user> trait {} ] {{\n", state.name)
            }
        }
    }

    fn reflection_class_constant_to_string(
        &mut self,
        state: &ReflectionClassConstantState,
        span: Span,
    ) -> CompileResult<String> {
        let value = self.evaluate_reflection_class_constant_value(state, span)?;
        let visibility = reflection_visibility_name(state.visibility);
        let type_name = reflection_class_constant_type_name(&value);
        let rendered = reflection_class_constant_display_value(&value);
        Ok(format!(
            "Constant [ {visibility} {type_name} {} ] {{ {rendered} }}",
            state.name
        ))
    }

    fn reflection_class_property_to_string(
        &mut self,
        state: &ReflectionPropertyState,
        span: Span,
    ) -> CompileResult<String> {
        let visibility = reflection_visibility_name(state.visibility);
        let static_marker = if state.is_static { " static" } else { "" };
        let type_marker = state
            .type_decl
            .as_deref()
            .map(|type_decl| format!(" {type_decl}"))
            .unwrap_or_default();
        let default = if state.has_default {
            format!(
                " = {}",
                reflection_value_export_short(
                    &self.reflection_property_default_value(state, span)?
                )
            )
        } else {
            String::new()
        };
        Ok(format!(
            "Property [ {visibility}{static_marker}{type_marker} ${}{default} ]",
            state.name
        ))
    }

    fn reflection_method_prototype(
        &self,
        state: &ReflectionMethodState,
    ) -> Option<ReflectionMethodState> {
        if state.visibility == Visibility::Private {
            return None;
        }

        match state.declaring_kind {
            ReflectionClassKind::Class => {
                let declaring_class_id = state.declaring_class_id?;
                let declaring_class = self.classes.get(declaring_class_id)?;
                let mut current = declaring_class.parent_id();
                while let Some(current_id) = current {
                    let class = self.classes.get(current_id)?;
                    if let Some(method) = class.method(&state.name) {
                        if method.visibility() != Visibility::Private {
                            return Some(
                                self.reflection_class_method_state(current_id, current_id, method),
                            );
                        }
                    }
                    current = class.parent_id();
                }

                for interface_name in self.class_implements_interface_names(declaring_class_id) {
                    let Some(interface) = self
                        .interface_lookup
                        .get(&interface_name.to_ascii_lowercase())
                    else {
                        continue;
                    };
                    for (declaring_interface, method) in
                        expanded_interface_methods(&self.interface_lookup, interface)
                    {
                        if method.function.name.eq_ignore_ascii_case(&state.name) {
                            return Some(
                                self.reflection_interface_method_state(declaring_interface, method),
                            );
                        }
                    }
                }
                None
            }
            ReflectionClassKind::Interface => {
                let interface = self
                    .interface_lookup
                    .get(&state.declaring_class_name.to_ascii_lowercase())?;
                for parent_name in &interface.parents {
                    let Some(parent) = self.interface_lookup.get(&parent_name.to_ascii_lowercase())
                    else {
                        continue;
                    };
                    for (declaring_interface, method) in
                        expanded_interface_methods(&self.interface_lookup, parent)
                    {
                        if method.function.name.eq_ignore_ascii_case(&state.name) {
                            return Some(
                                self.reflection_interface_method_state(declaring_interface, method),
                            );
                        }
                    }
                }
                None
            }
            ReflectionClassKind::Trait => None,
        }
    }

    fn reflection_class_trait_names(&self, state: &ReflectionClassState) -> Vec<String> {
        match state.kind {
            ReflectionClassKind::Class => state
                .class_id
                .and_then(|class_id| self.classes.get(class_id))
                .map(|class| class.traits().to_vec())
                .unwrap_or_default(),
            ReflectionClassKind::Trait => self
                .trait_lookup
                .get(&state.name.to_ascii_lowercase())
                .map(|trait_decl| self.reflection_trait_trait_names(trait_decl))
                .unwrap_or_default(),
            ReflectionClassKind::Interface => Vec::new(),
        }
    }

    fn reflection_class_interface_names(&self, state: &ReflectionClassState) -> Vec<String> {
        match state.kind {
            ReflectionClassKind::Class => state
                .class_id
                .map(|class_id| self.class_implements_interface_names(class_id))
                .unwrap_or_default(),
            ReflectionClassKind::Interface => {
                let Some(interface) = self.interface_lookup.get(&state.name.to_ascii_lowercase())
                else {
                    return Vec::new();
                };
                let mut names = Vec::new();
                let mut seen = HashSet::new();
                for parent_name in &interface.parents {
                    self.push_class_implements_interface_name(
                        parent_name,
                        true,
                        &mut names,
                        &mut seen,
                    );
                }
                names
            }
            ReflectionClassKind::Trait => Vec::new(),
        }
    }

    fn reflection_class_has_method(&self, state: &ReflectionClassState, method_name: &str) -> bool {
        if state.closure_id.is_some() && method_name.eq_ignore_ascii_case("__invoke") {
            return true;
        }
        match state.kind {
            ReflectionClassKind::Class => state.class_id.is_some_and(|class_id| {
                self.resolve_instance_method(class_id, method_name)
                    .is_some()
            }),
            ReflectionClassKind::Interface => self
                .interface_lookup
                .get(&state.name.to_ascii_lowercase())
                .is_some_and(|interface| {
                    expanded_interface_methods(&self.interface_lookup, interface)
                        .iter()
                        .any(|(_, method)| method.function.name.eq_ignore_ascii_case(method_name))
                }),
            ReflectionClassKind::Trait => self
                .trait_lookup
                .get(&state.name.to_ascii_lowercase())
                .is_some_and(|trait_decl| {
                    self.reflection_trait_methods(trait_decl)
                        .unwrap_or_default()
                        .iter()
                        .any(|method| method.function.name.eq_ignore_ascii_case(method_name))
                }),
        }
    }

    fn reflection_class_default_properties(
        &mut self,
        state: &ReflectionClassState,
        span: Span,
    ) -> CompileResult<PhpArray> {
        let mut defaults = PhpArray::new();
        let (ReflectionClassKind::Class, Some(class_id)) = (state.kind, state.class_id) else {
            return Ok(defaults);
        };

        let mut seen = HashSet::new();
        for include_static in [true, false] {
            for (declaring_class_id, property_name) in
                self.reflection_class_default_property_entries(class_id, include_static)
            {
                if !seen.insert(property_name.clone()) {
                    continue;
                }
                let value = if include_static {
                    self.static_property_defaults
                        .get(&(declaring_class_id, property_name.clone()))
                        .cloned()
                        .unwrap_or(Value::Null)
                } else {
                    self.reflection_instance_property_default_value(
                        declaring_class_id,
                        &property_name,
                        span,
                    )?
                };
                defaults.insert(ArrayKey::String(property_name), value);
            }
        }

        Ok(defaults)
    }

    fn reflection_class_default_property_entries(
        &self,
        class_id: ClassId,
        include_static: bool,
    ) -> Vec<(ClassId, String)> {
        let mut entries = Vec::new();
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            entries.extend(class.properties().iter().filter_map(|property| {
                if property.is_static() != include_static
                    || (current_id != class_id && property.visibility() == Visibility::Private)
                    || !self.reflection_property_metadata_has_default(current_id, property)
                {
                    return None;
                }
                Some((current_id, property.name().to_string()))
            }));
            current = class.parent_id();
        }
        entries
    }

    fn reflection_class_static_properties(&self, state: &ReflectionClassState) -> PhpArray {
        let mut properties = PhpArray::new();
        let (ReflectionClassKind::Class, Some(class_id)) = (state.kind, state.class_id) else {
            return properties;
        };

        let mut seen = HashSet::new();
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            for property in class.properties() {
                if !property.is_static()
                    || (current_id != class_id && property.visibility() == Visibility::Private)
                    || !seen.insert(property.name().to_string())
                {
                    continue;
                }
                if let Some(value) = self
                    .static_properties
                    .get(&(current_id, property.name().to_string()))
                    .map(VariableCell::value_cloned)
                {
                    properties.insert(ArrayKey::String(property.name().to_string()), value);
                }
            }
            current = class.parent_id();
        }

        properties
    }

    fn reflection_class_static_property_value(
        &self,
        state: &ReflectionClassState,
        property_name: &str,
        span: Span,
    ) -> CompileResult<Option<Value>> {
        let Some((declaring_class_id, declaring_class_name)) =
            self.resolve_reflection_static_property_storage(state, property_name)
        else {
            return Ok(None);
        };
        self.static_properties
            .get(&(declaring_class_id, property_name.to_string()))
            .map(VariableCell::value_cloned)
            .map(Some)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::uninitialized_typed_static_property(
                        declaring_class_name,
                        property_name,
                    ),
                )
            })
    }

    fn reflection_class_static_property_name_argument(
        &mut self,
        method: &'static str,
        value: Value,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            Value::Null => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "{method}(): Passing null to parameter #1 ($name) of type string is deprecated"
                    ),
                    span,
                )?;
                Ok(String::new())
            }
            Value::Array(_) => Err(reflection_class_static_property_argument_error(
                method,
                format!("{method}(): Argument #1 ($name) must be of type string, array given"),
                span,
            )),
            value => value
                .try_echo_string()
                .map_err(|error| runtime_error(span, error)),
        }
    }

    fn reflection_class_set_static_property_value(
        &mut self,
        state: &ReflectionClassState,
        property_name: &str,
        value: Value,
        span: Span,
    ) -> CompileResult<()> {
        let Some((declaring_class_id, declaring_class_name)) =
            self.resolve_reflection_static_property_storage(state, property_name)
        else {
            return Err(reflection_exception_error(
                span,
                format!(
                    "Class {} does not have a property named {property_name}",
                    state.name
                ),
            ));
        };
        let value = self.coerce_static_property_value(
            declaring_class_id,
            &declaring_class_name,
            property_name,
            value,
            span,
        )?;
        if let Some(cell) = self
            .static_properties
            .get(&(declaring_class_id, property_name.to_string()))
        {
            let value = self.coerce_reference_cell_value_for_write(cell, value, span)?;
            cell.set_value(value);
        } else {
            self.static_properties.insert(
                (declaring_class_id, property_name.to_string()),
                VariableCell::new(value),
            );
        }
        Ok(())
    }

    fn resolve_reflection_static_property_storage(
        &self,
        state: &ReflectionClassState,
        property_name: &str,
    ) -> Option<(ClassId, String)> {
        let (ReflectionClassKind::Class, Some(class_id)) = (state.kind, state.class_id) else {
            return None;
        };
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            if let Some(property) = class.property(property_name) {
                if current_id != class_id && property.visibility() == Visibility::Private {
                    current = class.parent_id();
                    continue;
                }
                return property
                    .is_static()
                    .then(|| (current_id, class.name().to_string()));
            }
            current = class.parent_id();
        }
        None
    }

    fn static_property_type_decl(&self, class_id: ClassId, property: &str) -> Option<String> {
        self.classes
            .get(class_id)
            .and_then(|class| class.property(property))
            .and_then(|property| property.type_decl())
            .map(str::to_string)
    }

    fn coerce_reference_cell_value_for_write(
        &self,
        cell: &PhpReferenceCell,
        value: Value,
        span: Span,
    ) -> CompileResult<Value> {
        cell.coerce_value_for_write_with_object_type_resolver(value, |object, type_name| {
            self.object_satisfies_live_property_type(object, type_name)
        })
        .map_err(|error| runtime_error(span, error))
    }

    fn constrain_static_property_reference_cell(
        &mut self,
        cell: &PhpReferenceCell,
        declaring_class_id: ClassId,
        declaring_class_name: &str,
        property: &str,
        span: Span,
    ) -> CompileResult<()> {
        let value = self.coerce_static_property_value(
            declaring_class_id,
            declaring_class_name,
            property,
            cell.value_cloned(),
            span,
        )?;
        let value = self.coerce_reference_cell_value_for_write(cell, value, span)?;
        cell.set_value(value);
        let type_decl = self.static_property_type_decl(declaring_class_id, property);
        cell.add_property_type_constraint(type_decl.as_deref(), declaring_class_name, property);
        Ok(())
    }

    fn reflection_trait_methods(
        &self,
        trait_decl: &TraitDecl,
    ) -> CompileResult<Vec<ClassMethodDecl>> {
        trait_semantics::compose_effective_trait_methods_for_trait(trait_decl, &self.trait_lookup)
            .map(|methods| {
                methods
                    .into_iter()
                    .map(|method| method.method)
                    .collect::<Vec<_>>()
            })
            .map_err(|error| error.to_diagnostic(Phase::Runtime))
    }

    fn reflection_trait_trait_names(&self, trait_decl: &TraitDecl) -> Vec<String> {
        let mut names = Vec::new();
        let mut seen = HashSet::new();
        for trait_use in &trait_decl.trait_uses {
            let Some(used_trait) = self.trait_lookup.get(&trait_use.name.to_ascii_lowercase())
            else {
                continue;
            };
            let canonical_key = used_trait.name.to_ascii_lowercase();
            if seen.insert(canonical_key) {
                names.push(used_trait.name.clone());
            }
        }
        names
    }

    fn reflection_class_method_state(
        &self,
        reflected_class_id: ClassId,
        declaring_class_id: ClassId,
        method: &PhpMethodMetadata,
    ) -> ReflectionMethodState {
        let declaring_class = self
            .classes
            .get(declaring_class_id)
            .expect("declaring class id should resolve");
        let signature_key = (declaring_class_id, method.name().to_ascii_lowercase());
        let signature = self.method_signatures.get(&signature_key);
        let declaring_class_name = declaring_class.name().to_string();
        let params = signature
            .map(reflection_parameter_metadata_from_signature)
            .unwrap_or_else(|| {
                reflection_internal_method_params(&declaring_class_name, method.name())
            });
        let is_internal = !self.class_source_metadata.contains_key(&declaring_class_id);
        let static_variables = signature
            .map(|signature| signature.static_variables.clone())
            .unwrap_or_default();
        ReflectionMethodState {
            reflected_class_id: Some(reflected_class_id),
            declaring_class_name,
            declaring_kind: ReflectionClassKind::Class,
            declaring_class_id: Some(declaring_class_id),
            closure_id: None,
            name: method.name().to_string(),
            file_name: signature.and_then(|signature| signature.file_name.clone()),
            start_line: signature.map(|signature| signature.start_line).unwrap_or(0),
            end_line: signature.map(|signature| signature.end_line).unwrap_or(0),
            doc_comment: signature.and_then(|signature| signature.doc_comment.clone()),
            visibility: method.visibility(),
            is_static: method.is_static(),
            is_abstract: method.is_abstract(),
            is_final: method.is_final(),
            is_internal,
            return_type: signature.and_then(|signature| signature.return_type.clone()),
            returns_by_reference: signature
                .map(|signature| signature.returns_by_reference)
                .unwrap_or(false),
            params,
            static_variables,
            is_deprecated: signature.is_some_and(|signature| signature.is_deprecated),
            attributes: signature
                .map(|signature| signature.attributes.clone())
                .unwrap_or_default(),
        }
    }

    fn reflection_interface_method_state(
        &self,
        declaring_interface: String,
        method: &InterfaceMethodDecl,
    ) -> ReflectionMethodState {
        let metadata = self
            .interface_source_metadata
            .get(&declaring_interface.to_ascii_lowercase());
        ReflectionMethodState {
            reflected_class_id: None,
            declaring_class_name: declaring_interface,
            declaring_kind: ReflectionClassKind::Interface,
            declaring_class_id: None,
            closure_id: None,
            name: method.function.name.clone(),
            file_name: metadata.and_then(|metadata| metadata.file_name.clone()),
            start_line: method.function.span.line,
            end_line: method.function.end_line,
            doc_comment: method.function.doc_comment.clone(),
            visibility: Visibility::Public,
            is_static: method.is_static,
            is_abstract: true,
            is_final: false,
            is_internal: false,
            return_type: method
                .function
                .return_type
                .as_ref()
                .map(|decl| decl.text.clone()),
            returns_by_reference: method.function.returns_by_reference,
            params: reflection_parameter_metadata_from_function_params(&method.function.params),
            static_variables: reflection_static_variables_from_body(&method.function.body),
            is_deprecated: attributes_include_deprecated(&method.attributes),
            attributes: method.attributes.clone(),
        }
    }

    fn reflection_trait_method_state(
        &self,
        trait_decl: &TraitDecl,
        method: &ClassMethodDecl,
    ) -> ReflectionMethodState {
        let metadata = self
            .trait_source_metadata
            .get(&trait_decl.name.to_ascii_lowercase());
        ReflectionMethodState {
            reflected_class_id: None,
            declaring_class_name: trait_decl.name.clone(),
            declaring_kind: ReflectionClassKind::Trait,
            declaring_class_id: None,
            closure_id: None,
            name: method.function.name.clone(),
            file_name: metadata.and_then(|metadata| metadata.file_name.clone()),
            start_line: method.function.span.line,
            end_line: method.function.end_line,
            doc_comment: method.function.doc_comment.clone(),
            visibility: runtime_visibility(method.visibility),
            is_static: method.is_static,
            is_abstract: method.is_abstract,
            is_final: method.is_final,
            is_internal: false,
            return_type: method
                .function
                .return_type
                .as_ref()
                .map(|decl| decl.text.clone()),
            returns_by_reference: method.function.returns_by_reference,
            params: reflection_parameter_metadata_from_function_params(&method.function.params),
            static_variables: reflection_static_variables_from_body(&method.function.body),
            is_deprecated: attributes_include_deprecated(&method.attributes),
            attributes: method.attributes.clone(),
        }
    }

    fn resolve_class_property_metadata(
        &self,
        class_id: ClassId,
        property_name: &str,
    ) -> Option<ReflectionPropertyState> {
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            if let Some(property) = class.property(property_name) {
                if current_id == class_id || property.visibility() != Visibility::Private {
                    let source_metadata = self
                        .property_source_metadata
                        .get(&(class.id(), property.name().to_string()));
                    return Some(ReflectionPropertyState {
                        declaring_class_name: class.name().to_string(),
                        declaring_kind: ReflectionClassKind::Class,
                        declaring_class_id: Some(class.id()),
                        name: property.name().to_string(),
                        doc_comment: source_metadata
                            .and_then(|metadata| metadata.doc_comment.clone()),
                        visibility: property.visibility(),
                        is_static: property.is_static(),
                        is_dynamic: false,
                        has_default: self
                            .reflection_property_metadata_has_default(class.id(), property),
                        type_decl: property.type_decl().map(str::to_string),
                        attributes: source_metadata
                            .map(|metadata| metadata.attributes.clone())
                            .unwrap_or_default(),
                    });
                }
            }
            current = class.parent_id();
        }
        None
    }

    fn resolve_trait_property_metadata(
        &self,
        trait_name: &str,
        property_name: &str,
        _span: Span,
    ) -> CompileResult<Option<ReflectionPropertyState>> {
        let Some(trait_decl) = self.trait_lookup.get(&trait_name.to_ascii_lowercase()) else {
            return Ok(None);
        };
        let properties = composed_trait_properties_for_trait(
            trait_decl,
            &self.trait_lookup,
            &mut HashSet::new(),
        )?;
        Ok(properties
            .into_iter()
            .find(|property| property.name == property_name)
            .map(|property| ReflectionPropertyState {
                declaring_class_name: trait_name.to_string(),
                declaring_kind: ReflectionClassKind::Trait,
                declaring_class_id: None,
                name: property.name,
                doc_comment: property.doc_comment,
                visibility: runtime_visibility(property.visibility),
                is_static: property.is_static,
                is_dynamic: false,
                has_default: property.default.is_some(),
                type_decl: property.type_decl.map(|decl| decl.text),
                attributes: property.attributes,
            }))
    }

    fn reflection_class_properties(&self, class_id: ClassId) -> Vec<ReflectionPropertyState> {
        let mut properties = Vec::new();
        let mut seen = HashSet::new();
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self
                .classes
                .get(current_id)
                .expect("class id should resolve to class metadata");
            for property in class.properties() {
                if current_id != class_id && property.visibility() == Visibility::Private {
                    continue;
                }
                if !seen.insert(property.name().to_string()) {
                    continue;
                }
                let source_metadata = self
                    .property_source_metadata
                    .get(&(class.id(), property.name().to_string()));
                properties.push(ReflectionPropertyState {
                    declaring_class_name: class.name().to_string(),
                    declaring_kind: ReflectionClassKind::Class,
                    declaring_class_id: Some(class.id()),
                    name: property.name().to_string(),
                    doc_comment: source_metadata.and_then(|metadata| metadata.doc_comment.clone()),
                    visibility: property.visibility(),
                    is_static: property.is_static(),
                    is_dynamic: false,
                    has_default: self
                        .reflection_property_metadata_has_default(class.id(), property),
                    type_decl: property.type_decl().map(str::to_string),
                    attributes: source_metadata
                        .map(|metadata| metadata.attributes.clone())
                        .unwrap_or_default(),
                });
            }
            current = class.parent_id();
        }
        properties
    }

    fn reflection_property_metadata_has_default(
        &self,
        declaring_class_id: ClassId,
        property: &PhpPropertyMetadata,
    ) -> bool {
        if property.is_static() {
            self.static_property_defaults
                .contains_key(&(declaring_class_id, property.name().to_string()))
        } else {
            property.type_decl().is_none()
                || self
                    .instance_property_defaults
                    .contains_key(&(declaring_class_id, property.name().to_string()))
                || self
                    .instance_property_default_exprs
                    .contains_key(&(declaring_class_id, property.name().to_string()))
        }
    }

    fn reflection_static_variables_array(
        &mut self,
        variables: &[(String, Option<Expr>)],
    ) -> CompileResult<Value> {
        let mut array = PhpArray::new();
        let mut default_scope = SymbolTable::new();
        for (name, default) in variables {
            let value = match default {
                Some(default) => self.evaluate(default, &mut default_scope)?,
                None => Value::Null,
            };
            array.insert(ArrayKey::String(name.clone()), value);
        }
        Ok(Value::Array(array))
    }

    fn reflection_closure_used_variables_array(&self, state: &ReflectionFunctionState) -> Value {
        let mut array = PhpArray::new();
        let Some(closure_id) = state.closure_id else {
            return Value::Array(array);
        };
        let Some(closure) = self.closure_values.get(&closure_id) else {
            return Value::Array(array);
        };
        for capture in closure.captures() {
            let key = ArrayKey::String(capture.name().to_string());
            if capture.by_reference() {
                array.insert_reference(key, capture.cell());
            } else {
                array.insert(key, capture.value());
            }
        }
        Value::Array(array)
    }

    fn reflection_function_bound_variable_names(
        &self,
        state: &ReflectionFunctionState,
    ) -> Vec<String> {
        let mut names = Vec::new();
        if let Some(closure_id) = state.closure_id {
            if let Some(closure) = self.closure_values.get(&closure_id) {
                names.extend(
                    closure
                        .captures()
                        .iter()
                        .map(|capture| capture.name().to_string()),
                );
            }
        }
        names.extend(state.static_variables.iter().map(|(name, _)| name.clone()));
        names
    }

    fn create_reflection_class_object_for_class_id(
        &mut self,
        class_id: ClassId,
        span: Span,
    ) -> CompileResult<Value> {
        let class_name = self
            .classes
            .get(class_id)
            .expect("reflected class id should resolve")
            .name()
            .to_string();
        let state =
            self.reflection_class_state_for(class_name, ReflectionClassKind::Class, Some(class_id));
        self.create_reflection_class_object(state, span)
    }

    fn call_reflection_function_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let state = self
            .reflection_functions
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionFunction::{method_name}()"),
                        "missing ReflectionFunction runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionFunction::__construct()",
                    "reinitializing ReflectionFunction objects is not implemented",
                ),
            )),
            "__tostring" => {
                expect_expr_arity("ReflectionFunction::__toString", args.len(), 0, span)?;
                self.reflection_function_to_string(&state, span)
                    .map(Value::String)
            }
            "getname" => {
                expect_expr_arity("ReflectionFunction::getName", args.len(), 0, span)?;
                Ok(Value::String(reflection_function_display_name(&state)))
            }
            "getshortname" => {
                expect_expr_arity("ReflectionFunction::getShortName", args.len(), 0, span)?;
                Ok(Value::String(reflection_name_short_name(&state.name)))
            }
            "getnamespacename" => {
                expect_expr_arity("ReflectionFunction::getNamespaceName", args.len(), 0, span)?;
                Ok(Value::String(reflection_name_namespace_name(&state.name)))
            }
            "innamespace" => {
                expect_expr_arity("ReflectionFunction::inNamespace", args.len(), 0, span)?;
                Ok(Value::Bool(reflection_name_in_namespace(&state.name)))
            }
            "isinternal" => {
                expect_expr_arity("ReflectionFunction::isInternal", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_internal))
            }
            "isuserdefined" => {
                expect_expr_arity("ReflectionFunction::isUserDefined", args.len(), 0, span)?;
                Ok(Value::Bool(!state.is_internal))
            }
            "isclosure" => {
                expect_expr_arity("ReflectionFunction::isClosure", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_closure))
            }
            "isanonymous" => {
                expect_expr_arity("ReflectionFunction::isAnonymous", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_closure))
            }
            "isstatic" => {
                expect_expr_arity("ReflectionFunction::isStatic", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_static))
            }
            "getextensionname" => {
                expect_expr_arity("ReflectionFunction::getExtensionName", args.len(), 0, span)?;
                if state.is_internal {
                    Ok(Value::String(reflection_internal_extension_name(
                        &state.name,
                    )))
                } else {
                    Ok(Value::Bool(false))
                }
            }
            "getextension" => {
                expect_expr_arity("ReflectionFunction::getExtension", args.len(), 0, span)?;
                if !state.is_internal {
                    return Ok(Value::Null);
                }
                self.create_reflection_extension_object(
                    ReflectionExtensionState {
                        name: reflection_internal_extension_name(&state.name),
                    },
                    span,
                )
            }
            "getfilename" => {
                expect_expr_arity("ReflectionFunction::getFileName", args.len(), 0, span)?;
                Ok(state
                    .file_name
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getstartline" => {
                expect_expr_arity("ReflectionFunction::getStartLine", args.len(), 0, span)?;
                if state.is_internal {
                    return Ok(Value::Bool(false));
                }
                Ok(Value::Int(state.start_line as i64))
            }
            "getendline" => {
                expect_expr_arity("ReflectionFunction::getEndLine", args.len(), 0, span)?;
                if state.is_internal {
                    return Ok(Value::Bool(false));
                }
                Ok(Value::Int(state.end_line as i64))
            }
            "getdoccomment" => {
                expect_expr_arity("ReflectionFunction::getDocComment", args.len(), 0, span)?;
                Ok(state
                    .doc_comment
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getparameters" => {
                expect_expr_arity("ReflectionFunction::getParameters", args.len(), 0, span)?;
                let mut parameters = PhpArray::new();
                for (position, parameter) in state.params.iter().cloned().enumerate() {
                    let parameter = self.create_reflection_parameter_object(
                        ReflectionParameterState {
                            declaring: ReflectionParameterDeclaring::Function(state.clone()),
                            parameter,
                            position,
                        },
                        span,
                    )?;
                    parameters
                        .append(parameter)
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(Value::Array(parameters))
            }
            "getnumberofparameters" => {
                expect_expr_arity(
                    "ReflectionFunction::getNumberOfParameters",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Int(state.params.len() as i64))
            }
            "getnumberofrequiredparameters" => {
                expect_expr_arity(
                    "ReflectionFunction::getNumberOfRequiredParameters",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Int(
                    state
                        .params
                        .iter()
                        .filter(|param| param.default.is_none() && !param.is_variadic)
                        .count() as i64,
                ))
            }
            "isvariadic" => {
                expect_expr_arity("ReflectionFunction::isVariadic", args.len(), 0, span)?;
                Ok(Value::Bool(
                    state.params.iter().any(|param| param.is_variadic),
                ))
            }
            "getstaticvariables" => {
                expect_expr_arity(
                    "ReflectionFunction::getStaticVariables",
                    args.len(),
                    0,
                    span,
                )?;
                self.reflection_static_variables_array(&state.static_variables)
            }
            "getclosureusedvariables" => {
                expect_expr_arity(
                    "ReflectionFunction::getClosureUsedVariables",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(self.reflection_closure_used_variables_array(&state))
            }
            "getclosure" => {
                expect_expr_arity("ReflectionFunction::getClosure", args.len(), 0, span)?;
                if state.is_closure {
                    let Some(closure_id) = state.closure_id else {
                        return Ok(Value::Null);
                    };
                    return Ok(self
                        .closure_values
                        .get(&closure_id)
                        .cloned()
                        .map(Value::Closure)
                        .unwrap_or(Value::Null));
                }
                Ok(Value::String(state.name))
            }
            "getclosurethis" => {
                expect_expr_arity("ReflectionFunction::getClosureThis", args.len(), 0, span)?;
                Ok(state.closure_this.map(Value::Object).unwrap_or(Value::Null))
            }
            "getclosurescopeclass" => {
                expect_expr_arity(
                    "ReflectionFunction::getClosureScopeClass",
                    args.len(),
                    0,
                    span,
                )?;
                let Some(class_id) = state.closure_scope_class_id else {
                    return Ok(Value::Null);
                };
                self.create_reflection_class_object_for_class_id(class_id, span)
            }
            "getclosurecalledclass" => {
                expect_expr_arity(
                    "ReflectionFunction::getClosureCalledClass",
                    args.len(),
                    0,
                    span,
                )?;
                let Some(class_id) = state.closure_called_class_id else {
                    return Ok(Value::Null);
                };
                self.create_reflection_class_object_for_class_id(class_id, span)
            }
            "hasreturntype" => {
                expect_expr_arity("ReflectionFunction::hasReturnType", args.len(), 0, span)?;
                Ok(Value::Bool(state.return_type.is_some()))
            }
            "getreturntype" => {
                expect_expr_arity("ReflectionFunction::getReturnType", args.len(), 0, span)?;
                let Some(type_decl) = state.return_type.as_deref() else {
                    return Ok(Value::Null);
                };
                if let Some(compound_state) =
                    reflection_compound_type_state_from_type_decl(type_decl)
                {
                    return self.create_reflection_compound_type_object(compound_state, span);
                }
                let Some(type_state) = reflection_named_type_state_from_type_decl(type_decl, None)
                else {
                    return Ok(Value::Null);
                };
                self.create_reflection_named_type_object(type_state, span)
            }
            "returnsreference" => {
                expect_expr_arity("ReflectionFunction::returnsReference", args.len(), 0, span)?;
                Ok(Value::Bool(state.returns_by_reference))
            }
            "isdisabled" => {
                expect_expr_arity("ReflectionFunction::isDisabled", args.len(), 0, span)?;
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    "Method ReflectionFunction::isDisabled() is deprecated since 8.0, as ReflectionFunction can no longer be constructed for disabled functions",
                    span,
                )?;
                Ok(Value::Bool(false))
            }
            "isdeprecated" => {
                expect_expr_arity("ReflectionFunction::isDeprecated", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_deprecated))
            }
            "getattributes" => self.call_reflection_get_attributes(
                &state.attributes,
                PHP_ATTRIBUTE_TARGET_FUNCTION,
                args,
                span,
                caller_scope,
            ),
            "invoke" => {
                if let Some(value) = self.invoke_reflection_function_exprs_with_array_copy_source(
                    state.clone(),
                    args,
                    span,
                    caller_scope,
                )? {
                    return Ok(value);
                }
                let values = self.evaluate_reflection_invocation_exprs(args, caller_scope)?;
                self.invoke_reflection_function(state, values, span)
            }
            "invokeargs" => {
                expect_expr_arity("ReflectionFunction::invokeArgs", args.len(), 1, span)?;
                if let Some(value) = self
                    .invoke_reflection_function_argument_array_with_array_copy_source(
                        state.clone(),
                        &args[0],
                        span,
                        caller_scope,
                    )?
                {
                    return Ok(value);
                }
                let values =
                    self.evaluate_reflection_invocation_args_array(&args[0], caller_scope, span)?;
                self.invoke_reflection_function(state, values, span)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("ReflectionFunction::{method_name}()")),
            )),
        }
    }

    fn reflection_function_to_string(
        &mut self,
        state: &ReflectionFunctionState,
        span: Span,
    ) -> CompileResult<String> {
        let kind = if state.is_internal {
            "internal"
        } else {
            "user"
        };
        if state.is_closure {
            let name = reflection_function_display_name(state);
            let mut output = format!("Closure [ <{kind}> function {name} ] {{\n");
            if !state.is_internal {
                if let Some(file_name) = state.file_name.as_deref() {
                    output.push_str(&format!(
                        "  @@ {file_name} {} - {}\n",
                        state.start_line, state.end_line
                    ));
                }
            }
            let bound_variables = self.reflection_function_bound_variable_names(state);
            if !bound_variables.is_empty() {
                output.push('\n');
                output.push_str(&format!(
                    "  - Bound Variables [{}] {{\n",
                    bound_variables.len()
                ));
                for (position, name) in bound_variables.iter().enumerate() {
                    output.push_str(&format!("      Variable #{position} [ ${name} ]\n"));
                }
                output.push_str("  }\n");
            }
            output.push_str("}\n");
            return Ok(output);
        }

        let mut output = format!("Function [ <{kind}> function {} ] {{\n", state.name);
        if !state.is_internal {
            if let Some(file_name) = state.file_name.as_deref() {
                output.push_str(&format!(
                    "  @@ {file_name} {} - {}\n",
                    state.start_line, state.end_line
                ));
            }
            output.push('\n');
        }
        output.push_str(&format!("  - Parameters [{}] {{\n", state.params.len()));
        for (position, parameter) in state.params.iter().cloned().enumerate() {
            let parameter_state = ReflectionParameterState {
                declaring: ReflectionParameterDeclaring::Function(state.clone()),
                parameter,
                position,
            };
            output.push_str("    ");
            output.push_str(&self.reflection_parameter_to_string(&parameter_state, span)?);
            output.push('\n');
        }
        output.push_str("  }\n}\n");
        Ok(output)
    }

    fn reflection_method_to_string(
        &mut self,
        state: &ReflectionMethodState,
        span: Span,
    ) -> CompileResult<String> {
        let kind = if state.is_internal {
            "internal:Reflection".to_string()
        } else if let (Some(reflected_class_id), Some(declaring_class_id)) =
            (state.reflected_class_id, state.declaring_class_id)
        {
            if reflected_class_id != declaring_class_id {
                format!("user, inherits {}", state.declaring_class_name)
            } else {
                "user".to_string()
            }
        } else {
            "user".to_string()
        };
        let traits = if state.name.eq_ignore_ascii_case("__construct") {
            format!("{kind}, ctor")
        } else {
            kind
        };
        let abstract_prefix = if state.is_abstract { "abstract " } else { "" };
        let final_prefix = if state.is_final { "final " } else { "" };
        let static_prefix = if state.is_static { "static " } else { "" };
        let visibility = match state.visibility {
            Visibility::Public => "public",
            Visibility::Protected => "protected",
            Visibility::Private => "private",
        };
        let mut output = format!(
            "Method [ <{traits}> {abstract_prefix}{final_prefix}{static_prefix}{visibility} method {} ] {{\n",
            state.name
        );
        if !state.is_internal {
            if let Some(file_name) = state.file_name.as_deref() {
                output.push_str(&format!(
                    "  @@ {file_name} {} - {}\n",
                    state.start_line, state.end_line
                ));
            }
        }
        if !state.params.is_empty() {
            output.push_str(&format!("\n  - Parameters [{}] {{\n", state.params.len()));
            for (position, parameter) in state.params.iter().cloned().enumerate() {
                let parameter_state = ReflectionParameterState {
                    declaring: ReflectionParameterDeclaring::Method(state.clone()),
                    parameter,
                    position,
                };
                output.push_str("    ");
                output.push_str(&self.reflection_parameter_to_string(&parameter_state, span)?);
                output.push('\n');
            }
            output.push_str("  }\n");
        }
        output.push_str("}\n");
        Ok(output)
    }

    fn call_reflection_method_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let state = self
            .reflection_methods
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionMethod::{method_name}()"),
                        "missing ReflectionMethod runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::__construct()",
                    "reinitializing ReflectionMethod objects is not implemented",
                ),
            )),
            "__tostring" => {
                expect_expr_arity("ReflectionMethod::__toString", args.len(), 0, span)?;
                self.reflection_method_to_string(&state, span)
                    .map(Value::String)
            }
            "getname" => {
                expect_expr_arity("ReflectionMethod::getName", args.len(), 0, span)?;
                Ok(Value::String(state.name))
            }
            "getfilename" => {
                expect_expr_arity("ReflectionMethod::getFileName", args.len(), 0, span)?;
                Ok(state
                    .file_name
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getstartline" => {
                expect_expr_arity("ReflectionMethod::getStartLine", args.len(), 0, span)?;
                if state.is_internal {
                    return Ok(Value::Bool(false));
                }
                Ok(Value::Int(state.start_line as i64))
            }
            "getendline" => {
                expect_expr_arity("ReflectionMethod::getEndLine", args.len(), 0, span)?;
                if state.is_internal {
                    return Ok(Value::Bool(false));
                }
                Ok(Value::Int(state.end_line as i64))
            }
            "getdoccomment" => {
                expect_expr_arity("ReflectionMethod::getDocComment", args.len(), 0, span)?;
                Ok(state
                    .doc_comment
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getdeclaringclass" => {
                expect_expr_arity("ReflectionMethod::getDeclaringClass", args.len(), 0, span)?;
                self.create_reflection_class_object(
                    self.reflection_class_state_for(
                        state.declaring_class_name,
                        state.declaring_kind,
                        state.declaring_class_id,
                    ),
                    span,
                )
            }
            "getmodifiers" => {
                expect_expr_arity("ReflectionMethod::getModifiers", args.len(), 0, span)?;
                Ok(Value::Int(reflection_method_modifier_mask(&state)))
            }
            "getparameters" => {
                expect_expr_arity("ReflectionMethod::getParameters", args.len(), 0, span)?;
                let mut parameters = PhpArray::new();
                for (position, parameter) in state.params.iter().cloned().enumerate() {
                    let parameter = self.create_reflection_parameter_object(
                        ReflectionParameterState {
                            declaring: ReflectionParameterDeclaring::Method(state.clone()),
                            parameter,
                            position,
                        },
                        span,
                    )?;
                    parameters
                        .append(parameter)
                        .map_err(|error| runtime_error(span, error))?;
                }
                Ok(Value::Array(parameters))
            }
            "getnumberofparameters" => {
                expect_expr_arity(
                    "ReflectionMethod::getNumberOfParameters",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Int(state.params.len() as i64))
            }
            "getnumberofrequiredparameters" => {
                expect_expr_arity(
                    "ReflectionMethod::getNumberOfRequiredParameters",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Int(
                    state
                        .params
                        .iter()
                        .filter(|param| param.default.is_none() && !param.is_variadic)
                        .count() as i64,
                ))
            }
            "getstaticvariables" => {
                expect_expr_arity("ReflectionMethod::getStaticVariables", args.len(), 0, span)?;
                self.reflection_static_variables_array(&state.static_variables)
            }
            "hasreturntype" => {
                expect_expr_arity("ReflectionMethod::hasReturnType", args.len(), 0, span)?;
                Ok(Value::Bool(state.return_type.is_some()))
            }
            "getreturntype" => {
                expect_expr_arity("ReflectionMethod::getReturnType", args.len(), 0, span)?;
                let Some(type_decl) = state.return_type.as_deref() else {
                    return Ok(Value::Null);
                };
                let type_decl =
                    reflection_type_decl_resolve_self(type_decl, &state.declaring_class_name);
                if let Some(compound_state) =
                    reflection_compound_type_state_from_type_decl(&type_decl)
                {
                    return self.create_reflection_compound_type_object(compound_state, span);
                }
                let Some(type_state) = reflection_named_type_state_from_type_decl(&type_decl, None)
                else {
                    return Ok(Value::Null);
                };
                self.create_reflection_named_type_object(type_state, span)
            }
            "ispublic" => {
                expect_expr_arity("ReflectionMethod::isPublic", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Public))
            }
            "isprotected" => {
                expect_expr_arity("ReflectionMethod::isProtected", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Protected))
            }
            "isprivate" => {
                expect_expr_arity("ReflectionMethod::isPrivate", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Private))
            }
            "isstatic" => {
                expect_expr_arity("ReflectionMethod::isStatic", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_static))
            }
            "isfinal" => {
                expect_expr_arity("ReflectionMethod::isFinal", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_final))
            }
            "isabstract" => {
                expect_expr_arity("ReflectionMethod::isAbstract", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_abstract))
            }
            "isconstructor" => {
                expect_expr_arity("ReflectionMethod::isConstructor", args.len(), 0, span)?;
                Ok(Value::Bool(state.name.eq_ignore_ascii_case("__construct")))
            }
            "isdeprecated" => {
                expect_expr_arity("ReflectionMethod::isDeprecated", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_deprecated))
            }
            "getattributes" => self.call_reflection_get_attributes(
                &state.attributes,
                PHP_ATTRIBUTE_TARGET_METHOD,
                args,
                span,
                caller_scope,
            ),
            "isdestructor" => {
                expect_expr_arity("ReflectionMethod::isDestructor", args.len(), 0, span)?;
                Ok(Value::Bool(state.name.eq_ignore_ascii_case("__destruct")))
            }
            "isinternal" => {
                expect_expr_arity("ReflectionMethod::isInternal", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_internal))
            }
            "isuserdefined" => {
                expect_expr_arity("ReflectionMethod::isUserDefined", args.len(), 0, span)?;
                Ok(Value::Bool(!state.is_internal))
            }
            "returnsreference" => {
                expect_expr_arity("ReflectionMethod::returnsReference", args.len(), 0, span)?;
                Ok(Value::Bool(state.returns_by_reference))
            }
            "setaccessible" => {
                expect_expr_arity("ReflectionMethod::setAccessible", args.len(), 1, span)?;
                let _ = self.evaluate(&args[0], caller_scope)?;
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    "Method ReflectionMethod::setAccessible() is deprecated since 8.5, as it has no effect since PHP 8.1",
                    span,
                )?;
                Ok(Value::Null)
            }
            "getclosure" => {
                if args.len() > 1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::arity_mismatch(
                            "ReflectionMethod::getClosure()",
                            ArityExpectation::Between { min: 0, max: 1 },
                            args.len(),
                        ),
                    ));
                }
                if let Some(closure_id) = state.closure_id {
                    if let Some(target_expr) = args.first() {
                        let target = self.evaluate(target_expr, caller_scope)?;
                        let Value::Closure(closure) = target else {
                            return Err(runtime_error(
                                target_expr.span(),
                                RuntimeError::unsupported_call(
                                    "ReflectionMethod::getClosure",
                                    format!(
                                        "closure method requires closure target, got {}",
                                        target.type_name()
                                    ),
                                ),
                            ));
                        };
                        return Ok(Value::Closure(closure));
                    }
                    return Ok(self
                        .closure_values
                        .get(&closure_id)
                        .cloned()
                        .map(Value::Closure)
                        .unwrap_or(Value::Null));
                }
                let mut callable = PhpArray::new();
                if state.is_static {
                    callable.insert(
                        ArrayKey::Int(0),
                        Value::String(state.declaring_class_name.clone()),
                    );
                    callable.insert(ArrayKey::Int(1), Value::String(state.name.clone()));
                    return Ok(Value::Array(callable));
                }
                let Some(target_expr) = args.first() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "ReflectionMethod::getClosure",
                            "non-static method closure requires an object in the current subset",
                        ),
                    ));
                };
                let target = self.evaluate(target_expr, caller_scope)?;
                let Value::Object(object) = target else {
                    return Err(runtime_error(
                        target_expr.span(),
                        RuntimeError::unsupported_call(
                            "ReflectionMethod::getClosure",
                            format!(
                                "non-static method closure requires object, got {}",
                                target.type_name()
                            ),
                        ),
                    ));
                };
                callable.insert(ArrayKey::Int(0), Value::Object(object));
                callable.insert(ArrayKey::Int(1), Value::String(state.name.clone()));
                Ok(Value::Array(callable))
            }
            "getprototype" => {
                expect_expr_arity("ReflectionMethod::getPrototype", args.len(), 0, span)?;
                let Some(prototype) = self.reflection_method_prototype(&state) else {
                    return Err(reflection_exception_error(
                        span,
                        format!(
                            "Method {}::{} does not have a prototype",
                            state.declaring_class_name, state.name
                        ),
                    ));
                };
                self.create_reflection_method_object(prototype, span)
            }
            "hasprototype" => {
                expect_expr_arity("ReflectionMethod::hasPrototype", args.len(), 0, span)?;
                Ok(Value::Bool(
                    self.reflection_method_prototype(&state).is_some(),
                ))
            }
            "invoke" => {
                if args.is_empty() {
                    return Err(reflection_method_invoke_argument_count_error(
                        args.len(),
                        span,
                    ));
                }
                let target = self.evaluate(&args[0], caller_scope)?;
                let values = self.evaluate_reflection_invocation_exprs(&args[1..], caller_scope)?;
                self.invoke_reflection_method(state, target, values, span)
            }
            "invokeargs" => {
                if state.is_abstract {
                    return Err(reflection_method_abstract_invoke_error(&state, span));
                }
                expect_expr_arity("ReflectionMethod::invokeArgs", args.len(), 2, span)?;
                let target = self.evaluate(&args[0], caller_scope)?;
                let values = self.evaluate_reflection_method_invocation_args_array(
                    &args[1],
                    caller_scope,
                    span,
                )?;
                self.invoke_reflection_method(state, target, values, span)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("ReflectionMethod::{method_name}()")),
            )),
        }
    }

    fn call_reflection_method_method_with_array_copy_source(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let state = self
            .reflection_methods
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionMethod::{method_name}()"),
                        "missing ReflectionMethod runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "invoke" => {
                if args.is_empty() {
                    return Err(reflection_method_invoke_argument_count_error(
                        args.len(),
                        span,
                    ));
                }
                let target = self.evaluate(&args[0], caller_scope)?;
                self.invoke_reflection_method_with_expr_args(
                    state,
                    target,
                    &args[1..],
                    span,
                    caller_scope,
                )
            }
            "invokeargs" => {
                if state.is_abstract {
                    return Err(reflection_method_abstract_invoke_error(&state, span));
                }
                expect_expr_arity("ReflectionMethod::invokeArgs", args.len(), 2, span)?;
                let target = self.evaluate(&args[0], caller_scope)?;
                self.invoke_reflection_method_with_argument_array_expr(
                    state,
                    target,
                    &args[1],
                    span,
                    caller_scope,
                )
            }
            _ => self
                .call_reflection_method_method(object, method_name, args, span, caller_scope)
                .map(|value| (value, None)),
        }
    }

    fn evaluate_reflection_invocation_exprs(
        &mut self,
        args: &[Expr],
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Vec<Value>> {
        args.iter()
            .map(|arg| self.evaluate(arg, caller_scope))
            .collect()
    }

    fn evaluate_reflection_invocation_args_array(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<Vec<Value>> {
        let value = self.evaluate(arg, caller_scope)?;
        let Value::Array(array) = value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "reflection invocation",
                    format!(
                        "invokeArgs argument list must be array in the current subset, got {}",
                        value.type_name()
                    ),
                ),
            ));
        };
        Ok(array
            .entries()
            .iter()
            .map(|entry| entry.value_cloned())
            .collect())
    }

    fn evaluate_reflection_method_invocation_args_array(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<Vec<Value>> {
        let value = self.evaluate(arg, caller_scope)?;
        let Value::Array(array) = value else {
            return Err(reflection_method_invoke_args_array_type_error(&value, span));
        };
        Ok(array
            .entries()
            .iter()
            .map(|entry| entry.value_cloned())
            .collect())
    }

    fn invoke_reflection_function_exprs_with_array_copy_source(
        &mut self,
        state: ReflectionFunctionState,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<Value>> {
        if state.is_closure {
            let Some(closure_id) = state.closure_id else {
                return Ok(None);
            };
            let Some(closure) = self.closure_values.get(&closure_id).cloned() else {
                return Ok(None);
            };
            let Some(function) = self.closure_functions.get(&closure.id()).cloned() else {
                return Ok(None);
            };
            if function.returns_by_reference {
                return Ok(None);
            }
            let function = function.as_ref();
            let prebound_locals = self.closure_prebound_locals(&closure);
            let (this_object, class_context, called_class_context) =
                self.closure_call_context(&closure);
            return self
                .call_source_aware_user_function_with_expr_args(
                    function,
                    args,
                    span,
                    caller_scope,
                    this_object,
                    class_context,
                    called_class_context,
                    prebound_locals,
                )
                .map(|(value, _)| Some(value));
        }

        let Some(Callable::User(function)) = self.lookup_function(&state.name) else {
            return Ok(None);
        };
        if function.returns_by_reference {
            return Ok(None);
        }
        self.call_source_aware_user_function_with_expr_args(
            function.as_ref(),
            args,
            span,
            caller_scope,
            None,
            None,
            None,
            Vec::new(),
        )
        .map(|(value, _)| Some(value))
    }

    fn invoke_reflection_function_argument_array_with_array_copy_source(
        &mut self,
        state: ReflectionFunctionState,
        argument_expr: &Expr,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<Value>> {
        if state.is_closure {
            let Some(closure_id) = state.closure_id else {
                return Ok(None);
            };
            let Some(closure) = self.closure_values.get(&closure_id).cloned() else {
                return Ok(None);
            };
            let Some(function) = self.closure_functions.get(&closure.id()).cloned() else {
                return Ok(None);
            };
            if function.returns_by_reference {
                return Ok(None);
            }
            let function = function.as_ref();
            let prebound_locals = self.closure_prebound_locals(&closure);
            let (this_object, class_context, called_class_context) =
                self.closure_call_context(&closure);
            let result = self.call_source_aware_user_function_with_call_user_func_array_argument(
                function,
                argument_expr,
                span,
                caller_scope,
                this_object,
                class_context,
                called_class_context,
                prebound_locals,
            )?;
            return Ok(result.map(|(value, _)| value));
        }

        let Some(Callable::User(function)) = self.lookup_function(&state.name) else {
            return Ok(None);
        };
        if function.returns_by_reference {
            return Ok(None);
        }
        let result = self.call_source_aware_user_function_with_call_user_func_array_argument(
            function.as_ref(),
            argument_expr,
            span,
            caller_scope,
            None,
            None,
            None,
            Vec::new(),
        )?;
        Ok(result.map(|(value, _)| value))
    }

    fn invoke_reflection_function(
        &mut self,
        state: ReflectionFunctionState,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        if state.is_closure {
            let Some(closure_id) = state.closure_id else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "ReflectionFunction::invoke",
                        "closure reflection metadata is missing in the current subset",
                    ),
                ));
            };
            return self.invoke_reflection_closure(closure_id, values, span);
        }
        let function = match self.lookup_function(&state.name) {
            Some(Callable::User(function)) => function,
            Some(Callable::Builtin(key)) => return self.call_builtin(&key, values, span),
            None => {
                return Err(runtime_error(
                    span,
                    RuntimeError::undefined_function(format!("{}()", state.name)),
                ));
            }
        };
        let function = function.as_ref();
        ensure_user_function_arity(function, values.len(), span)?;
        ensure_supported_function_signature(function, values.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;
        self.call_user_function_with_checked_values(
            function,
            values,
            None,
            None,
            None,
            Vec::new(),
            None,
        )
    }

    fn invoke_reflection_closure(
        &mut self,
        closure_id: i64,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let closure = self
            .closure_values
            .get(&closure_id)
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "ReflectionFunction::invoke",
                        "closure capture metadata is missing in the current subset",
                    ),
                )
            })?;
        self.invoke_closure_value(closure, values, span, "ReflectionFunction::invoke")
    }

    fn invoke_closure_value(
        &mut self,
        closure: PhpClosure,
        values: Vec<Value>,
        span: Span,
        context: &str,
    ) -> CompileResult<Value> {
        self.invoke_closure_value_with_extra_policy(closure, values, span, context, false)
    }

    fn invoke_closure_value_with_extra_policy(
        &mut self,
        closure: PhpClosure,
        values: Vec<Value>,
        span: Span,
        context: &str,
        allow_extra_user_args: bool,
    ) -> CompileResult<Value> {
        if let Some(callable) = self
            .first_class_closure_callables
            .get(&closure.id())
            .cloned()
        {
            return self.call_first_class_callable_descriptor_with_values(
                callable,
                values,
                span,
                context,
                allow_extra_user_args,
            );
        }
        let function = self
            .closure_functions
            .get(&closure.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        context,
                        "closure body metadata is missing in the current subset",
                    ),
                )
            })?;
        let function = function.as_ref();
        ensure_user_function_arity_with_extra_policy(
            function,
            values.len(),
            span,
            allow_extra_user_args,
        )
        .map_err(|error| callback_context_diagnostic(context, error))?;
        ensure_supported_function_signature(function, values.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;
        let prebound_locals = self.closure_prebound_locals(&closure);
        let (this_object, class_context, called_class_context) =
            self.closure_call_context(&closure);
        self.call_user_function_with_checked_values_and_locals(
            function,
            values,
            this_object,
            class_context,
            called_class_context,
            Vec::new(),
            None,
            prebound_locals,
            Vec::new(),
        )
    }

    fn invoke_static_trait_reflection_method(
        &mut self,
        trait_name: &str,
        method_name: &str,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let function = self.trait_reflection_method_function(trait_name, method_name, span)?;
        let function = function.as_ref();
        ensure_user_function_arity_with_extra_policy(function, values.len(), span, true)?;
        ensure_supported_function_signature(function, values.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;

        self.trait_class_context.push(trait_name.to_string());
        self.trait_called_class_context.push(trait_name.to_string());
        let result = self.call_user_function_with_checked_values(
            function,
            values,
            None,
            None,
            None,
            Vec::new(),
            None,
        );
        self.trait_called_class_context.pop();
        self.trait_class_context.pop();
        result
    }

    fn call_trait_reflection_static_method(
        &mut self,
        trait_name: &str,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        context: &str,
    ) -> CompileResult<Value> {
        let method = self.trait_reflection_method_decl(trait_name, method_name, span)?;
        if !method.is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{trait_name}::{method_name}()"),
                    format!(
                        "non-static trait method dispatch through {context} is not implemented"
                    ),
                ),
            ));
        }
        if method.is_abstract {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{trait_name}::{method_name}()"),
                    "abstract trait methods are not executable in the current subset",
                ),
            ));
        }

        let function = method.function;
        ensure_user_function_arity(&function, args.len(), span)?;
        ensure_supported_function_signature(&function, args.len(), span)?;
        self.ensure_user_function_call_depth(&function, span)?;

        let mut values = Vec::with_capacity(args.len());
        for arg in args {
            values.push(self.evaluate_by_value_argument_with_cow_source(arg, caller_scope)?);
        }

        self.invoke_static_trait_reflection_method(trait_name, &function.name, values, span)
    }

    fn trait_reflection_method_decl(
        &self,
        trait_name: &str,
        method_name: &str,
        span: Span,
    ) -> CompileResult<ClassMethodDecl> {
        let trait_decl = self
            .trait_lookup
            .get(&trait_name.to_ascii_lowercase())
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::undefined_class(format!("{trait_name} trait")),
                )
            })?;
        self.reflection_trait_methods(trait_decl)?
            .into_iter()
            .find(|method| method.function.name.eq_ignore_ascii_case(method_name))
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::undefined_function(format!("{trait_name}::{method_name}()")),
                )
            })
    }

    fn invoke_closure_value_direct(
        &mut self,
        closure: PhpClosure,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        context: &str,
    ) -> CompileResult<Value> {
        if let Some(callable) = self
            .first_class_closure_callables
            .get(&closure.id())
            .cloned()
        {
            return self.call_first_class_callable_descriptor_direct(
                callable,
                args,
                span,
                caller_scope,
                context,
            );
        }
        let function = self
            .closure_functions
            .get(&closure.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        context,
                        "closure body metadata is missing in the current subset",
                    ),
                )
            })?;
        let function = function.as_ref();
        Self::ensure_user_function_expr_arity_unless_spread(function, args, span)?;
        if function.returns_by_reference {
            ensure_supported_reference_return_function_metadata(function, span)?;
            self.ensure_user_function_call_depth(function, span)?;
            let (values, reference_bindings, by_value_array_copy_source_bindings) = self
                .evaluate_user_function_call_arguments_with_options_and_array_copy_sources(
                    function,
                    args,
                    span,
                    caller_scope,
                    true,
                )?;
            let prebound_locals = self.closure_prebound_locals(&closure);
            let (this_object, class_context, called_class_context) =
                self.closure_call_context(&closure);
            return self.call_reference_return_function_value_with_checked_values_and_locals(
                function,
                values,
                this_object,
                class_context,
                called_class_context,
                reference_bindings,
                caller_scope,
                prebound_locals,
                by_value_array_copy_source_bindings,
            );
        }
        ensure_supported_function_metadata(function, span)?;
        let prebound_locals = self.closure_prebound_locals(&closure);
        let (this_object, class_context, called_class_context) =
            self.closure_call_context(&closure);
        self.call_source_aware_user_function_with_expr_args(
            function,
            args,
            span,
            caller_scope,
            this_object,
            class_context,
            called_class_context,
            prebound_locals,
        )
        .map(|(value, _)| value)
    }

    fn invoke_closure_value_direct_with_array_copy_source(
        &mut self,
        closure: PhpClosure,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        context: &str,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if self
            .first_class_closure_callables
            .contains_key(&closure.id())
        {
            return self
                .invoke_closure_value_direct(closure, args, span, caller_scope, context)
                .map(|value| (value, None));
        }
        let function = self
            .closure_functions
            .get(&closure.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        context,
                        "closure body metadata is missing in the current subset",
                    ),
                )
            })?;
        let function = function.as_ref();
        if function.returns_by_reference {
            return self
                .invoke_closure_value_direct(closure, args, span, caller_scope, context)
                .map(|value| (value, None));
        }
        let prebound_locals = self.closure_prebound_locals(&closure);
        let (this_object, class_context, called_class_context) =
            self.closure_call_context(&closure);
        self.call_source_aware_user_function_with_expr_args(
            function,
            args,
            span,
            caller_scope,
            this_object,
            class_context,
            called_class_context,
            prebound_locals,
        )
    }

    fn closure_prebound_locals(&self, closure: &PhpClosure) -> Vec<PreboundLocal> {
        let mut locals: Vec<_> = closure
            .captures()
            .iter()
            .map(|capture| {
                if capture.by_reference() {
                    if let Some((source, source_scope)) =
                        self.closure_array_copy_source_capture(closure, capture.name())
                    {
                        return PreboundLocal::CellWithArrayCopySource {
                            name: capture.name().to_string(),
                            cell: capture.cell(),
                            source,
                            source_scope,
                        };
                    }
                    PreboundLocal::Cell {
                        name: capture.name().to_string(),
                        cell: capture.cell(),
                    }
                } else {
                    let value = capture.value();
                    if let Some((source, source_scope)) =
                        self.closure_array_copy_source_capture(closure, capture.name())
                    {
                        return PreboundLocal::ValueWithArrayCopySource {
                            name: capture.name().to_string(),
                            value,
                            source,
                            source_scope,
                        };
                    }
                    PreboundLocal::Value {
                        name: capture.name().to_string(),
                        value,
                    }
                }
            })
            .collect();
        if let Some(alias_captures) = self.closure_alias_captures.get(&closure.id()) {
            locals.extend(
                alias_captures
                    .iter()
                    .map(|capture| PreboundLocal::ArrayOffsets {
                        name: capture.name.clone(),
                        aliases: capture.aliases.clone(),
                        source_scope: capture.source_scope.clone(),
                    }),
            );
        }
        locals
    }

    fn closure_call_context(
        &self,
        closure: &PhpClosure,
    ) -> (Option<PhpObject>, Option<ClassId>, Option<ClassId>) {
        self.closure_bound_contexts
            .get(&closure.id())
            .map(|context| {
                (
                    context.this_object.clone(),
                    context.class_context,
                    context.called_class_context,
                )
            })
            .unwrap_or((None, None, None))
    }

    fn closure_array_copy_source_capture(
        &self,
        closure: &PhpClosure,
        name: &str,
    ) -> Option<(ArrayCopySource, SymbolTable)> {
        self.closure_array_copy_source_captures
            .get(&closure.id())?
            .iter()
            .rev()
            .find(|(candidate, _, _)| candidate == name)
            .map(|(_, source, source_scope)| (source.clone(), source_scope.clone()))
    }

    fn invoke_reflection_method(
        &mut self,
        state: ReflectionMethodState,
        target: Value,
        values: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        if let Some(error) = reflection_method_core_invoke_error(&state, span) {
            return Err(error);
        }

        if state.is_abstract {
            return Err(reflection_method_abstract_invoke_error(&state, span));
        }

        if matches!(state.declaring_kind, ReflectionClassKind::Trait) && state.is_static {
            match target {
                Value::Null | Value::Object(_) => {}
                other => {
                    return Err(reflection_method_invoke_object_type_error(&other, span));
                }
            }

            return self.invoke_static_trait_reflection_method(
                &state.declaring_class_name,
                &state.name,
                values,
                span,
            );
        }
        let ReflectionClassKind::Class = state.declaring_kind else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "interface and trait method reflection invocation is not implemented",
                ),
            ));
        };
        let Some(declaring_class_id) = state.declaring_class_id else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "method reflection invocation requires a declared user class target",
                ),
            ));
        };
        if state.is_static {
            match target {
                Value::Null | Value::Object(_) => {}
                other => {
                    return Err(reflection_method_invoke_object_type_error(&other, span));
                }
            }

            let function = self.method_function(
                declaring_class_id,
                &state.declaring_class_name,
                &state.name,
                span,
            )?;
            let function = function.as_ref();
            ensure_user_function_arity_with_extra_policy(function, values.len(), span, true)?;
            ensure_supported_function_signature(function, values.len(), span)?;
            self.ensure_user_function_call_depth(function, span)?;
            let called_class_id = state.reflected_class_id.unwrap_or(declaring_class_id);
            return self.call_user_function_with_checked_values(
                function,
                values,
                None,
                Some(declaring_class_id),
                Some(called_class_id),
                Vec::new(),
                None,
            );
        }

        let Value::Object(object) = target else {
            return Err(reflection_method_invoke_object_type_error(&target, span));
        };
        if object.class_id() != declaring_class_id
            && !self
                .classes
                .is_subclass_of(object.class_id(), declaring_class_id)
        {
            return Err(reflection_method_invoke_non_instance_error(span));
        }

        let function = self.method_function(
            declaring_class_id,
            &state.declaring_class_name,
            &state.name,
            span,
        )?;
        let function = function.as_ref();
        ensure_user_function_arity_with_extra_policy(function, values.len(), span, true)?;
        ensure_supported_function_signature(function, values.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;
        let called_class_id = object.class_id();
        self.call_user_function_with_checked_values(
            function,
            values,
            Some(object),
            Some(declaring_class_id),
            Some(called_class_id),
            Vec::new(),
            None,
        )
    }

    fn invoke_reflection_method_with_expr_args(
        &mut self,
        state: ReflectionMethodState,
        target: Value,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if let Some(error) = reflection_method_core_invoke_error(&state, span) {
            return Err(error);
        }

        if state.is_abstract {
            return Err(reflection_method_abstract_invoke_error(&state, span));
        }

        if matches!(state.declaring_kind, ReflectionClassKind::Trait) && state.is_static {
            let values = self.evaluate_reflection_invocation_exprs(args, caller_scope)?;
            return self
                .invoke_reflection_method(state, target, values, span)
                .map(|value| (value, None));
        }
        let ReflectionClassKind::Class = state.declaring_kind else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "interface and trait method reflection invocation is not implemented",
                ),
            ));
        };
        let Some(declaring_class_id) = state.declaring_class_id else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "method reflection invocation requires a declared user class target",
                ),
            ));
        };
        if state.is_static {
            match target {
                Value::Null | Value::Object(_) => {}
                other => {
                    return Err(reflection_method_invoke_object_type_error(&other, span));
                }
            }

            let function = self.method_function(
                declaring_class_id,
                &state.declaring_class_name,
                &state.name,
                span,
            )?;
            let function = function.as_ref();
            ensure_supported_function_signature(function, args.len(), span)?;
            let called_class_id = state.reflected_class_id.unwrap_or(declaring_class_id);
            return self.call_source_aware_user_function_with_expr_args(
                function,
                args,
                span,
                caller_scope,
                None,
                Some(declaring_class_id),
                Some(called_class_id),
                Vec::new(),
            );
        }

        let Value::Object(object) = target else {
            return Err(reflection_method_invoke_object_type_error(&target, span));
        };
        if object.class_id() != declaring_class_id
            && !self
                .classes
                .is_subclass_of(object.class_id(), declaring_class_id)
        {
            return Err(reflection_method_invoke_non_instance_error(span));
        }

        let function = self.method_function(
            declaring_class_id,
            &state.declaring_class_name,
            &state.name,
            span,
        )?;
        let function = function.as_ref();
        ensure_supported_function_signature(function, args.len(), span)?;
        let called_class_id = object.class_id();
        self.call_source_aware_user_function_with_expr_args(
            function,
            args,
            span,
            caller_scope,
            Some(object),
            Some(declaring_class_id),
            Some(called_class_id),
            Vec::new(),
        )
    }

    fn invoke_reflection_method_with_argument_array_expr(
        &mut self,
        state: ReflectionMethodState,
        target: Value,
        argument_expr: &Expr,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if let Some(error) = reflection_method_core_invoke_error(&state, span) {
            return Err(error);
        }

        if state.is_abstract {
            return Err(reflection_method_abstract_invoke_error(&state, span));
        }

        if matches!(state.declaring_kind, ReflectionClassKind::Trait) && state.is_static {
            let values = self.evaluate_reflection_method_invocation_args_array(
                argument_expr,
                caller_scope,
                span,
            )?;
            return self
                .invoke_reflection_method(state, target, values, span)
                .map(|value| (value, None));
        }
        let ReflectionClassKind::Class = state.declaring_kind else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "interface and trait method reflection invocation is not implemented",
                ),
            ));
        };
        let Some(declaring_class_id) = state.declaring_class_id else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionMethod::invoke",
                    "method reflection invocation requires a declared user class target",
                ),
            ));
        };
        if state.is_static {
            match target {
                Value::Null | Value::Object(_) => {}
                other => {
                    return Err(reflection_method_invoke_object_type_error(&other, span));
                }
            }

            let function = self.method_function(
                declaring_class_id,
                &state.declaring_class_name,
                &state.name,
                span,
            )?;
            let function = function.as_ref();
            if let Some(result) = self
                .call_source_aware_user_function_with_call_user_func_array_argument(
                    function,
                    argument_expr,
                    span,
                    caller_scope,
                    None,
                    Some(declaring_class_id),
                    Some(state.reflected_class_id.unwrap_or(declaring_class_id)),
                    Vec::new(),
                )
                .map_err(reflection_method_invoke_args_error_from_call_user_func_array)?
            {
                return Ok(result);
            }
            let values = self.evaluate_reflection_method_invocation_args_array(
                argument_expr,
                caller_scope,
                span,
            )?;
            return self
                .invoke_reflection_method(state, target, values, span)
                .map(|value| (value, None));
        }

        let Value::Object(object) = target else {
            return Err(reflection_method_invoke_object_type_error(&target, span));
        };
        if object.class_id() != declaring_class_id
            && !self
                .classes
                .is_subclass_of(object.class_id(), declaring_class_id)
        {
            return Err(reflection_method_invoke_non_instance_error(span));
        }

        let function = self.method_function(
            declaring_class_id,
            &state.declaring_class_name,
            &state.name,
            span,
        )?;
        let function = function.as_ref();
        if let Some(result) = self
            .call_source_aware_user_function_with_call_user_func_array_argument(
                function,
                argument_expr,
                span,
                caller_scope,
                Some(object.clone()),
                Some(declaring_class_id),
                Some(object.class_id()),
                Vec::new(),
            )
            .map_err(reflection_method_invoke_args_error_from_call_user_func_array)?
        {
            return Ok(result);
        }
        let values = self.evaluate_reflection_method_invocation_args_array(
            argument_expr,
            caller_scope,
            span,
        )?;
        self.invoke_reflection_method(state, Value::Object(object), values, span)
            .map(|value| (value, None))
    }

    fn call_reflection_parameter_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let state = self
            .reflection_parameters
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionParameter::{method_name}()"),
                        "missing ReflectionParameter runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => {
                if args.len() != 2 {
                    return Err(reflection_constructor_exact_argument_count_error(
                        "ReflectionParameter",
                        2,
                        args.len(),
                        span,
                    ));
                }
                let function_target = self.evaluate(&args[0], caller_scope)?;
                let parameter_target = self.evaluate(&args[1], caller_scope)?;
                let declaring =
                    self.resolve_reflection_parameter_function_target(&function_target, span)?;
                let state =
                    self.resolve_reflection_parameter_target(declaring, &parameter_target, span)?;
                self.assign_reflection_parameter_state(&object, state, span)?;
                Ok(Value::Null)
            }
            "__tostring" => {
                expect_expr_arity("ReflectionParameter::__toString", args.len(), 0, span)?;
                self.reflection_parameter_to_string(&state, span)
                    .map(Value::String)
            }
            "getname" => {
                expect_expr_arity("ReflectionParameter::getName", args.len(), 0, span)?;
                Ok(Value::String(state.parameter.name))
            }
            "getposition" => {
                expect_expr_arity("ReflectionParameter::getPosition", args.len(), 0, span)?;
                Ok(Value::Int(state.position as i64))
            }
            "getdeclaringclass" => {
                expect_expr_arity(
                    "ReflectionParameter::getDeclaringClass",
                    args.len(),
                    0,
                    span,
                )?;
                match state.declaring {
                    ReflectionParameterDeclaring::Method(method) => self
                        .create_reflection_class_object(
                            self.reflection_class_state_for(
                                method.declaring_class_name,
                                method.declaring_kind,
                                method.declaring_class_id,
                            ),
                            span,
                        ),
                    ReflectionParameterDeclaring::Function(_) => Ok(Value::Null),
                }
            }
            "getdeclaringfunction" => {
                expect_expr_arity(
                    "ReflectionParameter::getDeclaringFunction",
                    args.len(),
                    0,
                    span,
                )?;
                match state.declaring {
                    ReflectionParameterDeclaring::Function(function) => {
                        self.create_reflection_function_object(function, span)
                    }
                    ReflectionParameterDeclaring::Method(method) => {
                        self.create_reflection_method_object(method, span)
                    }
                }
            }
            "isoptional" => {
                expect_expr_arity("ReflectionParameter::isOptional", args.len(), 0, span)?;
                Ok(Value::Bool(
                    state.parameter.default.is_some() || state.parameter.is_variadic,
                ))
            }
            "isdefaultvalueavailable" => {
                expect_expr_arity(
                    "ReflectionParameter::isDefaultValueAvailable",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Bool(state.parameter.default.is_some()))
            }
            "getdefaultvalue" => {
                expect_expr_arity("ReflectionParameter::getDefaultValue", args.len(), 0, span)?;
                let Some(default) = state.parameter.default else {
                    return Err(reflection_exception_error(
                        span,
                        "Internal error: Failed to retrieve the default value",
                    ));
                };
                let mut default_scope = SymbolTable::new();
                self.evaluate(&default, &mut default_scope)
            }
            "isdefaultvalueconstant" => {
                expect_expr_arity(
                    "ReflectionParameter::isDefaultValueConstant",
                    args.len(),
                    0,
                    span,
                )?;
                if state.parameter.default.is_none() {
                    return Err(reflection_exception_error(
                        span,
                        "Internal error: Failed to retrieve the default value",
                    ));
                }
                Ok(Value::Bool(state.parameter.default_constant_name.is_some()))
            }
            "getdefaultvalueconstantname" => {
                expect_expr_arity(
                    "ReflectionParameter::getDefaultValueConstantName",
                    args.len(),
                    0,
                    span,
                )?;
                match state.parameter.default_constant_name {
                    Some(name) => Ok(Value::String(name)),
                    None if state.parameter.default.is_none() => Err(reflection_exception_error(
                        span,
                        "Internal error: Failed to retrieve the default value",
                    )),
                    None => Ok(Value::Null),
                }
            }
            "ispassedbyreference" => {
                expect_expr_arity(
                    "ReflectionParameter::isPassedByReference",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Bool(state.parameter.by_reference))
            }
            "canbepassedbyvalue" => {
                expect_expr_arity(
                    "ReflectionParameter::canBePassedByValue",
                    args.len(),
                    0,
                    span,
                )?;
                Ok(Value::Bool(state.parameter.can_be_passed_by_value))
            }
            "isvariadic" => {
                expect_expr_arity("ReflectionParameter::isVariadic", args.len(), 0, span)?;
                Ok(Value::Bool(state.parameter.is_variadic))
            }
            "iscallable" => {
                expect_expr_arity("ReflectionParameter::isCallable", args.len(), 0, span)?;
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    "Method ReflectionParameter::isCallable() is deprecated since 8.0, use ReflectionParameter::getType() instead",
                    span,
                )?;
                Ok(Value::Bool(
                    state
                        .parameter
                        .type_decl
                        .as_deref()
                        .is_some_and(type_decl_contains_callable),
                ))
            }
            "hastype" => {
                expect_expr_arity("ReflectionParameter::hasType", args.len(), 0, span)?;
                Ok(Value::Bool(state.parameter.type_decl.is_some()))
            }
            "gettype" => {
                expect_expr_arity("ReflectionParameter::getType", args.len(), 0, span)?;
                let Some(type_decl) = state.parameter.type_decl.as_deref() else {
                    return Ok(Value::Null);
                };
                let implicit_nullable_type_decl;
                let reflected_type_decl =
                    if reflection_parameter_has_implicit_nullable_default(&state.parameter)
                        && type_decl.contains('&')
                    {
                        implicit_nullable_type_decl =
                            reflection_implicit_nullable_type_text(type_decl);
                        implicit_nullable_type_decl.as_str()
                    } else {
                        type_decl
                    };
                if let Some(compound_state) =
                    reflection_compound_type_state_from_type_decl(reflected_type_decl)
                {
                    return self.create_reflection_compound_type_object(compound_state, span);
                }
                let Some(type_state) = reflection_named_type_state_from_type_decl(
                    reflected_type_decl,
                    state.parameter.default.as_ref(),
                ) else {
                    return Ok(Value::Null);
                };
                self.create_reflection_named_type_object(type_state, span)
            }
            "allowsnull" => {
                expect_expr_arity("ReflectionParameter::allowsNull", args.len(), 0, span)?;
                Ok(Value::Bool(reflection_parameter_allows_null(
                    state.parameter.type_decl.as_deref(),
                    state.parameter.default.as_ref(),
                )))
            }
            "getattributes" => self.call_reflection_get_attributes(
                &state.parameter.attributes,
                PHP_ATTRIBUTE_TARGET_PARAMETER,
                args,
                span,
                caller_scope,
            ),
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("ReflectionParameter::{method_name}()")),
            )),
        }
    }

    fn call_reflection_property_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let state = self
            .reflection_properties
            .get(&object.id())
            .cloned()
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("ReflectionProperty::{method_name}()"),
                        "missing ReflectionProperty runtime metadata",
                    ),
                )
            })?;

        match method_name.to_ascii_lowercase().as_str() {
            "__construct" => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "ReflectionProperty::__construct()",
                    "reinitializing ReflectionProperty objects is not implemented",
                ),
            )),
            "__tostring" => {
                expect_expr_arity("ReflectionProperty::__toString", args.len(), 0, span)?;
                self.reflection_property_to_string(&state, span)
                    .map(Value::String)
            }
            "getname" => {
                expect_expr_arity("ReflectionProperty::getName", args.len(), 0, span)?;
                Ok(Value::String(state.name))
            }
            "getdoccomment" => {
                expect_expr_arity("ReflectionProperty::getDocComment", args.len(), 0, span)?;
                Ok(state
                    .doc_comment
                    .map(Value::String)
                    .unwrap_or(Value::Bool(false)))
            }
            "getdeclaringclass" => {
                expect_expr_arity("ReflectionProperty::getDeclaringClass", args.len(), 0, span)?;
                self.create_reflection_class_object(
                    self.reflection_class_state_for(
                        state.declaring_class_name,
                        state.declaring_kind,
                        state.declaring_class_id,
                    ),
                    span,
                )
            }
            "getmodifiers" => {
                expect_expr_arity("ReflectionProperty::getModifiers", args.len(), 0, span)?;
                Ok(Value::Int(reflection_property_modifier_mask(&state)))
            }
            "getmangledname" => {
                expect_expr_arity("ReflectionProperty::getMangledName", args.len(), 0, span)?;
                Ok(Value::String(reflection_property_mangled_name(&state)))
            }
            "isdefault" => {
                expect_expr_arity("ReflectionProperty::isDefault", args.len(), 0, span)?;
                Ok(Value::Bool(!state.is_dynamic))
            }
            "isdynamic" => {
                expect_expr_arity("ReflectionProperty::isDynamic", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_dynamic))
            }
            "ispublic" => {
                expect_expr_arity("ReflectionProperty::isPublic", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Public))
            }
            "isprotected" => {
                expect_expr_arity("ReflectionProperty::isProtected", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Protected))
            }
            "isprivate" => {
                expect_expr_arity("ReflectionProperty::isPrivate", args.len(), 0, span)?;
                Ok(Value::Bool(state.visibility == Visibility::Private))
            }
            "isstatic" => {
                expect_expr_arity("ReflectionProperty::isStatic", args.len(), 0, span)?;
                Ok(Value::Bool(state.is_static))
            }
            "hasdefaultvalue" => {
                expect_expr_arity("ReflectionProperty::hasDefaultValue", args.len(), 0, span)?;
                Ok(Value::Bool(state.has_default))
            }
            "getdefaultvalue" => {
                expect_expr_arity("ReflectionProperty::getDefaultValue", args.len(), 0, span)?;
                if !state.has_default {
                    self.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        "ReflectionProperty::getDefaultValue() for a property without a default value is deprecated, use ReflectionProperty::hasDefaultValue() to check if the default value exists",
                        span,
                    )?;
                }
                self.reflection_property_default_value(&state, span)
            }
            "hastype" => {
                expect_expr_arity("ReflectionProperty::hasType", args.len(), 0, span)?;
                Ok(Value::Bool(state.type_decl.is_some()))
            }
            "gettype" => {
                expect_expr_arity("ReflectionProperty::getType", args.len(), 0, span)?;
                let Some(type_decl) = state.type_decl.as_deref() else {
                    return Ok(Value::Null);
                };
                if let Some(compound_state) =
                    reflection_compound_type_state_from_type_decl(type_decl)
                {
                    return self.create_reflection_compound_type_object(compound_state, span);
                }
                let Some(type_state) = reflection_named_type_state_from_type_decl(type_decl, None)
                else {
                    return Ok(Value::Null);
                };
                self.create_reflection_named_type_object(type_state, span)
            }
            "getattributes" => self.call_reflection_get_attributes(
                &state.attributes,
                PHP_ATTRIBUTE_TARGET_PROPERTY,
                args,
                span,
                caller_scope,
            ),
            "getvalue" => self.reflection_property_get_value(&state, args, span, caller_scope),
            "setvalue" => self.reflection_property_set_value(&state, args, span, caller_scope),
            "isinitialized" => self
                .reflection_property_is_initialized(&state, args, span, caller_scope)
                .map(Value::Bool),
            "isreadable" => {
                let target = self.reflection_property_access_probe_target(
                    "ReflectionProperty::isReadable",
                    args,
                    span,
                    caller_scope,
                )?;
                self.reflection_property_is_readable(&state, target, span)
                    .map(Value::Bool)
            }
            "iswritable" => {
                let target = self.reflection_property_access_probe_target(
                    "ReflectionProperty::isWritable",
                    args,
                    span,
                    caller_scope,
                )?;
                self.reflection_property_is_writable(&state, target, span)
                    .map(Value::Bool)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("ReflectionProperty::{method_name}()")),
            )),
        }
    }

