    fn call_reference_return_function_value_with_checked_values_and_locals_and_return_source(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        argument_keys: Vec<Option<ArrayKey>>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        caller_scope: &mut SymbolTable,
        prebound_locals: Vec<PreboundLocal>,
        by_value_array_copy_source_bindings: Vec<ArrayCopySourceBinding>,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let binding = self
            .call_reference_return_function_with_checked_values_and_locals_for_reference_assignment(
                function,
                args,
                argument_keys,
                this_object,
                class_context,
                called_class_context,
                reference_bindings,
                caller_scope,
                prebound_locals,
                by_value_array_copy_source_bindings,
            )?;

        self.read_reference_return_binding_value_with_array_copy_source(
            function,
            &binding,
            caller_scope,
        )
    }

    fn read_reference_return_binding_value_with_array_copy_source(
        &self,
        function: &FunctionDecl,
        binding: &ReferenceReturnBinding,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        let source = Self::public_object_property_array_copy_source_from_reference_binding(
            binding,
            caller_scope,
        );
        match binding {
            ReferenceReturnBinding::Cell(cell) => {
                caller_scope.rehydrate_reference_cell_array_aliases(cell);
                Ok((cell.value_cloned(), source))
            }
            ReferenceReturnBinding::ArrayOffset(alias) => {
                let value = caller_scope.read_array_offset_alias(alias).ok_or_else(|| {
                    runtime_error(
                        function.span,
                        RuntimeError::invalid_array_access(
                            "cannot read reference-return array-offset result".to_string(),
                        ),
                    )
                })?;
                Ok((value, source))
            }
            ReferenceReturnBinding::ArrayOffsets(aliases) => {
                let alias = aliases.first().ok_or_else(|| {
                    runtime_error(
                        function.span,
                        RuntimeError::invalid_array_access(
                            "cannot read empty reference-return array-offset result".to_string(),
                        ),
                    )
                })?;
                let value = caller_scope.read_array_offset_alias(alias).ok_or_else(|| {
                    runtime_error(
                        function.span,
                        RuntimeError::invalid_array_access(
                            "cannot read reference-return array-offset result".to_string(),
                        ),
                    )
                })?;
                Ok((value, source))
            }
        }
    }

    fn call_reference_return_function_with_checked_values(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        mut writeback_scope: Option<&mut SymbolTable>,
    ) -> CompileResult<VariableCell> {
        self.function_context
            .push(self.function_context_name(function));
        if let Some(class_context) = class_context {
            self.class_context.push(class_context);
        }
        if let Some(called_class_context) = called_class_context {
            self.called_class_context.push(called_class_context);
        }
        let mut local_scope = SymbolTable::new_child(self.global_symbols.clone());
        if let Some(this_object) = this_object.as_ref() {
            local_scope.write_static("this", Value::Object(this_object.clone()));
            if let Some(source_scope) = writeback_scope.as_deref() {
                local_scope.import_public_object_property_aliases_for_object_value(
                    "this",
                    this_object,
                    source_scope,
                );
            }
        }
        let mut array_offset_binding_cells = Vec::new();
        for (index, param) in function.params.iter().enumerate() {
            if param.is_variadic {
                let mut rest = PhpArray::new();
                for arg in args.iter().skip(index) {
                    rest.append(arg.clone())
                        .map_err(|error| runtime_error(param.span, error))?;
                }
                local_scope.write_static(&param.name, Value::Array(rest));
                for binding in reference_bindings
                    .iter()
                    .filter(|binding| binding.param_name == param.name)
                {
                    let ReferenceBindingTarget::ValueWithArrayCopySourceAtPath {
                        target_keys,
                        source,
                    } = &binding.target
                    else {
                        continue;
                    };
                    if let Some(source_scope) = writeback_scope.as_deref() {
                        local_scope.import_array_copy_source_aliases_from_copy_to_path(
                            &param.name,
                            target_keys,
                            source,
                            source_scope,
                        );
                    }
                    local_scope.record_array_literal_copy_source_path(
                        &param.name,
                        target_keys.clone(),
                        source.clone(),
                    );
                }
                break;
            }

            if let Some(binding) = reference_bindings
                .iter()
                .find(|binding| binding.param_name == param.name)
            {
                if let Some(arg) = args.get(index) {
                    if let Err(error) = self.coerce_call_argument_value(
                        function,
                        index,
                        param,
                        arg.clone(),
                        class_context,
                        called_class_context,
                    ) {
                        self.function_context.pop();
                        if class_context.is_some() {
                            self.class_context.pop();
                        }
                        if called_class_context.is_some() {
                            self.called_class_context.pop();
                        }
                        return Err(error);
                    }
                }
                match &binding.target {
                    ReferenceBindingTarget::CallerCell { cell, .. } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                    }
                    ReferenceBindingTarget::ReferenceReturnCell { cell } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                    }
                    ReferenceBindingTarget::CallerCellWithStaticArrayCopySource {
                        cell,
                        source,
                        source_was_dirty,
                        ..
                    }
                    | ReferenceBindingTarget::CallerCellWithArrayCopySource {
                        cell,
                        source,
                        source_was_dirty,
                        ..
                    } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                        if let Some(source_scope) = writeback_scope.as_deref() {
                            local_scope.import_array_copy_source_aliases_from_copy(
                                &param.name,
                                source,
                                source_scope,
                            );
                        }
                        local_scope.mirror_array_copy_source_aliases_from_copy(&param.name, source);
                        local_scope.record_public_object_property_array_copy_source(
                            &param.name,
                            source.clone(),
                        );
                        if *source_was_dirty {
                            local_scope
                                .mark_public_object_property_array_copy_source_dirty(&param.name);
                        }
                    }
                    ReferenceBindingTarget::ValueWithArrayCopySource { source } => {
                        if let Some(arg) = args.get(index) {
                            if let Some(source_scope) = writeback_scope.as_deref_mut() {
                                let arg = source_scope
                                    .value_with_object_property_aliases_from_array_copy(
                                        arg.clone(),
                                        Some(source.clone()),
                                        true,
                                    );
                                local_scope.write_static(&param.name, arg);
                                local_scope.import_array_copy_source_aliases_from_copy(
                                    &param.name,
                                    source,
                                    source_scope,
                                );
                            } else {
                                local_scope.write_static(&param.name, arg.clone());
                            }
                            local_scope
                                .mirror_array_copy_source_aliases_from_copy(&param.name, source);
                            local_scope.record_public_object_property_array_copy_source(
                                &param.name,
                                source.clone(),
                            );
                        }
                    }
                    ReferenceBindingTarget::ValueWithArrayCopySourceAtPath { .. } => {}
                    ReferenceBindingTarget::ValueCopy => {
                        if let Some(arg) = args.get(index) {
                            local_scope.write_static(&param.name, arg.clone());
                        }
                    }
                    ReferenceBindingTarget::ArrayOffset(alias) => {
                        if let Some(arg) = args.get(index) {
                            let aliases = vec![alias.clone()];
                            let cell = if let Some(scope) = writeback_scope.as_deref_mut() {
                                if let Some(cell) =
                                    scope.reference_cell_for_array_literal_alias_group(&aliases)
                                {
                                    local_scope.bind_static_to_cell(&param.name, cell.clone());
                                    Some(cell)
                                } else {
                                    None
                                }
                            } else {
                                None
                            };
                            let cell = if cell.is_none() {
                                local_scope.write_static(&param.name, arg.clone());
                                local_scope.read_cell(&param.name)
                            } else {
                                cell
                            };
                            if let Some(cell) = cell {
                                array_offset_binding_cells.push((
                                    param.name.clone(),
                                    aliases,
                                    cell,
                                ));
                            }
                        }
                    }
                    ReferenceBindingTarget::ArrayOffsets(aliases) => {
                        if let Some(arg) = args.get(index) {
                            let cell = if let Some(scope) = writeback_scope.as_deref_mut() {
                                if let Some(cell) =
                                    scope.reference_cell_for_array_literal_alias_group(aliases)
                                {
                                    local_scope.bind_static_to_cell(&param.name, cell.clone());
                                    Some(cell)
                                } else {
                                    None
                                }
                            } else {
                                None
                            };
                            let cell = if cell.is_none() {
                                local_scope.write_static(&param.name, arg.clone());
                                local_scope.read_cell(&param.name)
                            } else {
                                cell
                            };
                            if let Some(cell) = cell {
                                array_offset_binding_cells.push((
                                    param.name.clone(),
                                    aliases.clone(),
                                    cell,
                                ));
                            }
                        }
                    }
                }
                continue;
            }

            let value = if let Some(arg) = args.get(index) {
                arg.clone()
            } else {
                let default = param
                    .default
                    .as_ref()
                    .expect("arity check ensures missing params have defaults");
                let mut default_scope = SymbolTable::new();
                match self.evaluate_constant_like_expr(default, &mut default_scope) {
                    Ok(value) => value,
                    Err(error) => {
                        self.function_context.pop();
                        if class_context.is_some() {
                            self.class_context.pop();
                        }
                        if called_class_context.is_some() {
                            self.called_class_context.pop();
                        }
                        return Err(error);
                    }
                }
            };
            local_scope.write_static(&param.name, value);
        }

        let active_function_arguments =
            Self::active_function_call_arguments_for_func_get(function, &args, &[], &local_scope);

        self.call_depth += 1;
        self.active_static_locals.push(Vec::new());
        self.active_symbol_roots.push(local_scope.symbols.clone());
        self.active_function_call_arguments
            .push(active_function_arguments);
        let local_binding_result = self.with_strict_types_scope(function.strict_types, |this| {
            this.execute_reference_return_assignment_statements(function, &mut local_scope)
        });
        self.active_function_call_arguments.pop();
        let result = local_binding_result.and_then(|binding| {
            self.reference_return_local_binding_cell(
                function,
                binding,
                function.span,
                &mut local_scope,
            )
        });
        let writeback_result = if result.is_ok() {
            let mut writeback_result = Ok(());
            if let Some(target_scope) = writeback_scope.as_deref_mut() {
                for (param_name, aliases, original_cell) in &array_offset_binding_cells {
                    let Some(local_cell) = local_scope.read_cell(param_name) else {
                        continue;
                    };
                    if !local_cell.shares_reference_with(original_cell) {
                        continue;
                    }
                    let Some(value) = local_scope.read_named(param_name) else {
                        continue;
                    };
                    let wrote_aliases = target_scope
                        .write_array_offset_aliases_checked_preserving_static_copy_sources(
                            aliases,
                            value,
                            function.span,
                            &|object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )?;
                    if !wrote_aliases {
                        writeback_result = Err(runtime_error(
                            function.span,
                            RuntimeError::invalid_array_access(
                                "cannot write array reference argument".to_string(),
                            ),
                        ));
                        break;
                    }
                    for alias in aliases {
                        match &alias.root {
                            ArrayOffsetAliasRoot::StaticArray { name } => {
                                target_scope.sync_array_offset_aliases_for_static_root(name);
                            }
                            ArrayOffsetAliasRoot::GlobalArray { name } => {
                                target_scope.sync_array_offset_aliases_for_global_root(name);
                            }
                            ArrayOffsetAliasRoot::PublicObjectProperty { object, property }
                            | ArrayOffsetAliasRoot::ContextObjectProperty {
                                object,
                                property,
                                ..
                            } => {
                                target_scope.sync_array_offset_aliases_for_object_property_root(
                                    object, property,
                                );
                            }
                        }
                    }
                }
            } else {
                for (param_name, aliases, original_cell) in &array_offset_binding_cells {
                    let Some(local_cell) = local_scope.read_cell(param_name) else {
                        continue;
                    };
                    if !local_cell.shares_reference_with(original_cell) {
                        continue;
                    }
                    let Some(value) = local_scope.read_named(param_name) else {
                        continue;
                    };
                    let wrote_aliases = local_scope
                        .write_array_offset_aliases_checked_preserving_static_copy_sources(
                            aliases,
                            value,
                            function.span,
                            &|object, type_name| {
                                self.object_satisfies_live_property_type(object, type_name)
                            },
                        )?;
                    if !wrote_aliases {
                        writeback_result = Err(runtime_error(
                            function.span,
                            RuntimeError::invalid_array_access(
                                "cannot write array reference argument".to_string(),
                            ),
                        ));
                        break;
                    }
                    for alias in aliases {
                        match &alias.root {
                            ArrayOffsetAliasRoot::StaticArray { name } => {
                                local_scope.sync_array_offset_aliases_for_static_root(name);
                            }
                            ArrayOffsetAliasRoot::GlobalArray { name } => {
                                local_scope.sync_array_offset_aliases_for_global_root(name);
                            }
                            ArrayOffsetAliasRoot::PublicObjectProperty { object, property }
                            | ArrayOffsetAliasRoot::ContextObjectProperty {
                                object,
                                property,
                                ..
                            } => {
                                local_scope.sync_array_offset_aliases_for_object_property_root(
                                    object, property,
                                );
                            }
                        }
                    }
                }
            }
            writeback_result
        } else {
            Ok(())
        };
        let static_names = self.active_static_locals.pop().unwrap_or_default();
        let function_key = function.name.to_ascii_lowercase();
        for name in static_names {
            if let Some(value) = local_scope.read_named(&name) {
                self.static_locals
                    .insert((function_key.clone(), name), value.clone());
            }
        }
        self.active_symbol_roots.pop();
        self.call_depth -= 1;
        self.function_context.pop();
        if class_context.is_some() {
            self.class_context.pop();
        }
        if called_class_context.is_some() {
            self.called_class_context.pop();
        }

        writeback_result?;
        if result.is_ok() {
            if let Some(target_scope) = writeback_scope.as_deref_mut() {
                target_scope.sync_dirty_object_property_array_copy_sources_from_scope(&local_scope);
                target_scope.sync_dirty_array_copy_sources_from_scope(&local_scope);
                if let Some(this_object) = this_object.as_ref() {
                    target_scope
                        .detach_stale_object_aliases_from_local_scope(&local_scope, this_object);
                    target_scope.sync_array_offset_aliases_for_object_value(this_object);
                }
            }
        }
        result
    }

    fn execute_reference_return_assignment_statements(
        &mut self,
        function: &FunctionDecl,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnLocalBinding> {
        match self.execute_reference_return_assignment_statement_list(
            function,
            &function.body,
            scope,
        )? {
            ReferenceReturnBodyFlow::Return(binding) => Ok(binding),
            ReferenceReturnBodyFlow::Normal => {
                if function
                    .return_type
                    .as_ref()
                    .is_some_and(|decl| type_decl_is_exact(decl, "never"))
                {
                    let class_context = self.class_context.last().copied();
                    let callable = self.return_type_callable_name(function, class_context);
                    let callable_kind = if class_context.is_some() && function.name != "{closure}" {
                        "method"
                    } else {
                        "function"
                    };
                    return Err(Diagnostic::new(
                        Phase::Runtime,
                        function.span.line,
                        function.span.column,
                        format!(
                            "{callable}: never-returning {callable_kind} must not implicitly return"
                        ),
                    ));
                }
                Err(runtime_error(
                    function.span,
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "reference-return functions must return a direct variable or direct array offset in the current subset",
                    ),
                ))
            }
            ReferenceReturnBodyFlow::Break { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
            )),
            ReferenceReturnBodyFlow::Continue { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("continue cannot be used outside a loop"),
            )),
            ReferenceReturnBodyFlow::Goto { label, span } => {
                Err(undefined_goto_label_error(span, &label))
            }
            ReferenceReturnBodyFlow::Throw { object, span } => {
                Err(self.uncaught_throw_error(&object, span))
            }
        }
    }

    fn execute_reference_return_assignment_statement(
        &mut self,
        function: &FunctionDecl,
        stmt: &Stmt,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        self.tick(stmt.span())?;
        if let Stmt::Return { value, span } = stmt {
            let Some(value) = value else {
                return Err(runtime_error(
                    *span,
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "reference-return functions must return a value in the current subset",
                    ),
                ));
            };
            let binding =
                self.reference_return_local_binding_from_expr(function, value, *span, scope)?;
            return Ok(ReferenceReturnBodyFlow::Return(binding));
        }

        if let Stmt::Break { depth, span } = stmt {
            return Ok(ReferenceReturnBodyFlow::Break {
                depth: *depth,
                span: *span,
            });
        }

        if let Stmt::Continue { depth, span } = stmt {
            return Ok(ReferenceReturnBodyFlow::Continue {
                depth: *depth,
                span: *span,
            });
        }

        if let Stmt::Goto { label, span } = stmt {
            return Ok(ReferenceReturnBodyFlow::Goto {
                label: label.clone(),
                span: *span,
            });
        }

        if let Stmt::Throw { expr, span } = stmt {
            let object = self.throwable_object_from_expr(expr, *span, scope)?;
            return Ok(ReferenceReturnBodyFlow::Throw {
                object,
                span: *span,
            });
        }

        if let Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } = stmt
        {
            let branch = if self.evaluate(condition, scope)?.is_truthy() {
                then_branch
            } else {
                else_branch
            };
            return self
                .execute_reference_return_assignment_statement_list(function, branch, scope);
        }

        if let Stmt::While {
            condition,
            body,
            span,
        } = stmt
        {
            loop {
                self.tick(*span)?;
                if !self.evaluate(condition, scope)?.is_truthy() {
                    return Ok(ReferenceReturnBodyFlow::Normal);
                }
                match self
                    .execute_reference_return_assignment_statement_list(function, body, scope)?
                {
                    ReferenceReturnBodyFlow::Normal => {}
                    ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                    ReferenceReturnBodyFlow::Continue { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Continue {
                            depth: depth - 1,
                            span,
                        });
                    }
                    ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                        return Ok(ReferenceReturnBodyFlow::Normal);
                    }
                    ReferenceReturnBodyFlow::Break { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Break {
                            depth: depth - 1,
                            span,
                        });
                    }
                    flow @ (ReferenceReturnBodyFlow::Goto { .. }
                    | ReferenceReturnBodyFlow::Throw { .. }
                    | ReferenceReturnBodyFlow::Return(_)) => return Ok(flow),
                }
            }
        }

        if let Stmt::DoWhile {
            body,
            condition,
            span,
        } = stmt
        {
            loop {
                self.tick(*span)?;
                match self
                    .execute_reference_return_assignment_statement_list(function, body, scope)?
                {
                    ReferenceReturnBodyFlow::Normal => {}
                    ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                    ReferenceReturnBodyFlow::Continue { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Continue {
                            depth: depth - 1,
                            span,
                        });
                    }
                    ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                        return Ok(ReferenceReturnBodyFlow::Normal);
                    }
                    ReferenceReturnBodyFlow::Break { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Break {
                            depth: depth - 1,
                            span,
                        });
                    }
                    flow @ (ReferenceReturnBodyFlow::Goto { .. }
                    | ReferenceReturnBodyFlow::Throw { .. }
                    | ReferenceReturnBodyFlow::Return(_)) => return Ok(flow),
                }

                if !self.evaluate(condition, scope)?.is_truthy() {
                    return Ok(ReferenceReturnBodyFlow::Normal);
                }
            }
        }

        if let Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            span,
        } = stmt
        {
            for initializer in initializers {
                self.execute_for_action(initializer, scope)?;
            }

            loop {
                self.tick(*span)?;
                if !conditions.is_empty() {
                    let mut keep_running = true;
                    for condition in conditions {
                        keep_running = self.evaluate(condition, scope)?.is_truthy();
                    }
                    if !keep_running {
                        return Ok(ReferenceReturnBodyFlow::Normal);
                    }
                }

                match self
                    .execute_reference_return_assignment_statement_list(function, body, scope)?
                {
                    ReferenceReturnBodyFlow::Normal => {}
                    ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                    ReferenceReturnBodyFlow::Continue { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Continue {
                            depth: depth - 1,
                            span,
                        });
                    }
                    ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                        return Ok(ReferenceReturnBodyFlow::Normal);
                    }
                    ReferenceReturnBodyFlow::Break { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Break {
                            depth: depth - 1,
                            span,
                        });
                    }
                    flow @ (ReferenceReturnBodyFlow::Goto { .. }
                    | ReferenceReturnBodyFlow::Throw { .. }
                    | ReferenceReturnBodyFlow::Return(_)) => return Ok(flow),
                }

                for increment in increments {
                    self.execute_for_action(increment, scope)?;
                }
            }
        }

        if let Stmt::Foreach {
            iterable,
            key,
            value,
            by_reference,
            body,
            span,
        } = stmt
        {
            if !by_reference {
                let iterable = self.evaluate(iterable, scope)?;
                return match iterable {
                    Value::Array(array) => self.execute_reference_return_assignment_foreach_array(
                        function, array, key, value, body, *span, scope,
                    ),
                    Value::Object(object)
                        if self
                            .classes
                            .implements_interface(object.class_id(), "Iterator") =>
                    {
                        self.execute_reference_return_assignment_foreach_iterator_by_value(
                            function, object, key, value, body, *span, scope,
                        )
                    }
                    Value::Object(object)
                        if self
                            .classes
                            .implements_interface(object.class_id(), "IteratorAggregate") =>
                    {
                        let iterator =
                            self.call_required_iterator_method(object, "getIterator", *span)?;
                        match iterator {
                            Value::Object(iterator)
                                if self
                                    .classes
                                    .implements_interface(iterator.class_id(), "Iterator") =>
                            {
                                let flow = self
                                    .execute_reference_return_assignment_foreach_iterator_by_value(
                                        function,
                                        iterator.clone(),
                                        key,
                                        value,
                                        body,
                                        *span,
                                        scope,
                                    )?;
                                self.retire_unrooted_temporary_object_handle(&iterator, scope)?;
                                Ok(flow)
                            }
                            other => Err(runtime_error(
                                *span,
                                RuntimeError::invalid_foreach(format!(
                                    "IteratorAggregate::getIterator() must return an Iterator object in the current subset, got {}",
                                    other.type_name()
                                )),
                            )),
                        }
                    },
                    Value::Object(object) if !self.is_traversable_object(&object) => self
                        .execute_reference_return_assignment_foreach_public_object_by_value(
                            function, object, key, value, body, *span, scope,
                        ),
                    other => Err(runtime_error(
                        *span,
                        RuntimeError::invalid_foreach(format!(
                            "can only iterate arrays, ordinary public-property objects, or bounded Iterator objects in the current subset, got {}",
                            other.type_name()
                        )),
                    )),
                };
            }

            return self.execute_reference_return_assignment_foreach_by_reference(
                function, iterable, key, value, body, *span, scope,
            );
        }

        if let Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } = stmt
        {
            let try_flow = match self
                .execute_reference_return_assignment_statement_list(function, body, scope)
            {
                Ok(flow) => flow,
                Err(error) if catchable_php_error_message(&error).is_some() => {
                    match self.execute_catchable_php_error_reference_return_catch_flow(
                        function, &error, catches, scope,
                    )? {
                        Some(flow) => flow,
                        None => return Err(error),
                    }
                }
                Err(error) => return Err(error),
            };
            let try_flow = match try_flow {
                ReferenceReturnBodyFlow::Throw { object, span } => self
                    .execute_reference_return_assignment_catch_flow(
                        function, object, span, catches, scope,
                    )?,
                flow => flow,
            };
            if let Some(finally_body) = finally_body {
                let finally_flow = self.execute_reference_return_assignment_statement_list(
                    function,
                    finally_body,
                    scope,
                )?;
                if !matches!(finally_flow, ReferenceReturnBodyFlow::Normal) {
                    return Ok(finally_flow);
                }
            }
            return Ok(try_flow);
        }

        if let Stmt::Switch { value, cases, .. } = stmt {
            return self.execute_reference_return_assignment_switch(function, value, cases, scope);
        }

        match self.execute_statement(stmt, scope)? {
            Flow::Normal => Ok(ReferenceReturnBodyFlow::Normal),
            Flow::Return(_) => Err(runtime_error(
                stmt.span(),
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "reference returns through this control-flow form are not implemented",
                ),
            )),
            Flow::Break { depth, span } => Ok(ReferenceReturnBodyFlow::Break { depth, span }),
            Flow::Continue { depth, span } => Ok(ReferenceReturnBodyFlow::Continue { depth, span }),
            Flow::Throw { object, span } => Ok(ReferenceReturnBodyFlow::Throw { object, span }),
            Flow::Exit(_) => Err(runtime_error(
                stmt.span(),
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "exit during reference-return evaluation is not implemented",
                ),
            )),
            Flow::Goto { label, span } => Ok(ReferenceReturnBodyFlow::Goto { label, span }),
        }
    }

    fn execute_reference_return_assignment_catch_flow(
        &mut self,
        function: &FunctionDecl,
        object: PhpObject,
        span: Span,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        for catch in catches {
            if !self.catch_matches_thrown_object(&object, catch)? {
                continue;
            }
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(object));
            }
            return self.execute_reference_return_assignment_statement_list(
                function,
                &catch.body,
                scope,
            );
        }

        Ok(ReferenceReturnBodyFlow::Throw { object, span })
    }

    fn execute_catchable_php_error_reference_return_catch_flow(
        &mut self,
        function: &FunctionDecl,
        error: &Diagnostic,
        catches: &[CatchClause],
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnBodyFlow>> {
        let Some((error_class_name, error_message)) =
            self.catchable_php_error_class_and_message_with_pending_call_site(error)
        else {
            return Ok(None);
        };
        let Some(error_class_id) = self.classes.lookup_class_id(error_class_name) else {
            return Ok(None);
        };
        let error_object =
            self.create_core_error_object(error_message, error_class_id, error.line)?;
        for catch in catches {
            if !self.catch_matches_class(error_class_id, catch)? {
                continue;
            }
            self.clear_pending_uncaught_call_frames();
            if let Some(variable) = &catch.variable {
                scope.write_static(variable, Value::Object(error_object.clone()));
            }
            return self
                .execute_reference_return_assignment_statement_list(function, &catch.body, scope)
                .map(Some);
        }
        Ok(None)
    }

    fn execute_reference_return_assignment_foreach_flow(
        &mut self,
        function: &FunctionDecl,
        body: &[Stmt],
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnBodyFlow>> {
        match self.execute_reference_return_assignment_statement_list(function, body, scope)? {
            ReferenceReturnBodyFlow::Normal => Ok(None),
            ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => Ok(None),
            ReferenceReturnBodyFlow::Continue { depth, span } => {
                Ok(Some(ReferenceReturnBodyFlow::Continue {
                    depth: depth - 1,
                    span,
                }))
            }
            ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                Ok(Some(ReferenceReturnBodyFlow::Normal))
            }
            ReferenceReturnBodyFlow::Break { depth, span } => {
                Ok(Some(ReferenceReturnBodyFlow::Break {
                    depth: depth - 1,
                    span,
                }))
            }
            flow @ (ReferenceReturnBodyFlow::Goto { .. }
            | ReferenceReturnBodyFlow::Throw { .. }
            | ReferenceReturnBodyFlow::Return(_)) => Ok(Some(flow)),
        }
    }

    fn execute_reference_return_assignment_foreach_public_object_by_value(
        &mut self,
        function: &FunctionDecl,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let properties: Vec<(String, String)> = object
            .initialized_visible_properties(current_class_id, &protected_class_ids)
            .into_iter()
            .map(|property| {
                (
                    property.name().to_string(),
                    property.object_iteration_name(),
                )
            })
            .collect();

        for (property, iteration_name) in properties {
            self.tick(span)?;
            self.write_foreach_key_target(key, Value::String(iteration_name), span, scope)?;
            self.write_foreach_value_target(
                value,
                object.read_property_from_context(
                    &property,
                    current_class_id,
                    &protected_class_ids,
                )?,
                span,
                scope,
            )?;
            if let Some(flow) =
                self.execute_reference_return_assignment_foreach_flow(function, body, scope)?
            {
                return Ok(flow);
            }
        }

        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn execute_reference_return_assignment_foreach_iterator_by_value(
        &mut self,
        function: &FunctionDecl,
        object: PhpObject,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        self.call_required_iterator_method(object.clone(), "rewind", span)?;

        loop {
            if !self
                .call_required_iterator_method(object.clone(), "valid", span)?
                .is_truthy()
            {
                break;
            }

            self.tick(span)?;
            let (current, array_copy_source) = self
                .call_required_iterator_current_method_with_array_copy_source(
                    object.clone(),
                    span,
                    scope,
                )?;
            let iterator_key =
                if key.is_some() || self.foreach_iterator_needs_value_only_key_probe(&object) {
                    Some(self.call_required_iterator_method(object.clone(), "key", span)?)
                } else {
                    None
                };
            if let Some(iterator_key) = iterator_key {
                self.write_foreach_key_target(key, iterator_key, span, scope)?;
            }
            let target_is_alias = value
                .variable_name()
                .is_some_and(|name| scope.is_array_offset_alias_name(name));
            let current_is_array = matches!(current, Value::Array(_));
            self.write_foreach_value_target(value, current, span, scope)?;
            if !target_is_alias && current_is_array {
                if let Some(source) = array_copy_source {
                    if let Some(name) = value.variable_name() {
                        scope.mirror_array_copy_source_aliases_from_copy(name, &source);
                    }
                }
            }

            match self.execute_reference_return_assignment_foreach_flow(function, body, scope)? {
                None => {
                    self.call_required_iterator_method(object.clone(), "next", span)?;
                }
                Some(ReferenceReturnBodyFlow::Normal) => break,
                Some(ReferenceReturnBodyFlow::Continue { depth, span }) => {
                    return Ok(ReferenceReturnBodyFlow::Continue { depth, span });
                }
                Some(ReferenceReturnBodyFlow::Break { depth, span }) => {
                    return Ok(ReferenceReturnBodyFlow::Break { depth, span });
                }
                Some(
                    flow @ (ReferenceReturnBodyFlow::Goto { .. }
                    | ReferenceReturnBodyFlow::Throw { .. }
                    | ReferenceReturnBodyFlow::Return(_)),
                ) => return Ok(flow),
            }
        }

        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn execute_reference_return_assignment_foreach_array(
        &mut self,
        function: &FunctionDecl,
        array: PhpArray,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        for entry in array.entries() {
            self.tick(span)?;
            self.write_foreach_key_target(key, value_from_array_key(&entry.key), span, scope)?;
            self.write_foreach_value_target(value, entry.value_cloned(), span, scope)?;
            match self.execute_reference_return_assignment_statement_list(function, body, scope)? {
                ReferenceReturnBodyFlow::Normal => {}
                ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                ReferenceReturnBodyFlow::Continue { depth, span } => {
                    return Ok(ReferenceReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span,
                    });
                }
                ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                    return Ok(ReferenceReturnBodyFlow::Normal);
                }
                ReferenceReturnBodyFlow::Break { depth, span } => {
                    return Ok(ReferenceReturnBodyFlow::Break {
                        depth: depth - 1,
                        span,
                    });
                }
                flow @ (ReferenceReturnBodyFlow::Goto { .. }
                | ReferenceReturnBodyFlow::Throw { .. }
                | ReferenceReturnBodyFlow::Return(_)) => return Ok(flow),
            }
        }

        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn execute_reference_return_assignment_foreach_by_reference(
        &mut self,
        function: &FunctionDecl,
        iterable: &Expr,
        key: &Option<ForeachValueTarget>,
        value: &ForeachValueTarget,
        body: &[Stmt],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        let root = self.by_reference_foreach_root(iterable, scope, span)?;
        Self::read_foreach_root_array(&root, scope, span)?;
        let mut position = 0usize;
        let mut lingering_reference_key = None;

        loop {
            let array = Self::read_foreach_root_array(&root, scope, span)?;
            let Some(entry) = array.entries().get(position) else {
                break;
            };
            let entry_key = entry.key.clone();
            self.tick(span)?;

            self.write_foreach_key_target(key, value_from_array_key(&entry_key), span, scope)?;
            self.bind_foreach_value_target_reference_to_key(value, &root, &entry_key, span, scope)?;
            if let Some(value_name) = value.variable_name() {
                let active = Self::active_foreach_reference_for_slot(
                    &root, value_name, &entry_key, position, scope, span,
                )?;
                self.active_foreach_references.push(active);
            }
            let flow_result =
                self.execute_reference_return_assignment_statement_list(function, body, scope);
            let active = if value.variable_name().is_some() {
                self.active_foreach_references.pop()
            } else {
                None
            };
            let flow = flow_result?;

            let array = Self::read_foreach_root_array(&root, scope, span)?;
            let current_position =
                Self::foreach_current_position_after_body(&array, &entry_key, active.as_ref());
            lingering_reference_key = if let (Some(value_name), Some(current_position)) =
                (value.variable_name(), current_position.as_ref())
            {
                foreach_value_still_bound_to_key(scope, &root, value_name, &current_position.key)
                    .then(|| current_position.key.clone())
            } else {
                None
            };
            position = Self::foreach_next_position_after_body(
                position,
                current_position.as_ref(),
                active.as_ref(),
            );

            match flow {
                ReferenceReturnBodyFlow::Normal => {}
                ReferenceReturnBodyFlow::Continue { depth, .. } if depth <= 1 => {}
                ReferenceReturnBodyFlow::Continue {
                    depth,
                    span: flow_span,
                } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(ReferenceReturnBodyFlow::Continue {
                        depth: depth - 1,
                        span: flow_span,
                    });
                }
                ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => break,
                ReferenceReturnBodyFlow::Break {
                    depth,
                    span: flow_span,
                } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(ReferenceReturnBodyFlow::Break {
                        depth: depth - 1,
                        span: flow_span,
                    });
                }
                flow @ ReferenceReturnBodyFlow::Goto { .. } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(flow);
                }
                flow @ ReferenceReturnBodyFlow::Throw { .. } => {
                    if let Some(value_name) = value.variable_name() {
                        bind_foreach_lingering_reference(
                            scope,
                            value_name,
                            &root,
                            lingering_reference_key,
                            span,
                        )?;
                    }
                    return Ok(flow);
                }
                flow @ ReferenceReturnBodyFlow::Return(_) => return Ok(flow),
            }
        }

        if let Some(value_name) = value.variable_name() {
            bind_foreach_lingering_reference(
                scope,
                value_name,
                &root,
                lingering_reference_key,
                span,
            )?;
        }
        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn execute_reference_return_assignment_switch(
        &mut self,
        function: &FunctionDecl,
        value: &Expr,
        cases: &[SwitchCase],
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        let switch_value = self.evaluate(value, scope)?;
        let mut default_index = None;
        let mut matched_index = None;

        for (index, case) in cases.iter().enumerate() {
            let Some(condition) = &case.condition else {
                if default_index.is_none() {
                    default_index = Some(index);
                }
                continue;
            };

            let case_value = self.evaluate(condition, scope)?;
            let matched = switch_value
                .php_cmp_checked(&case_value, Comparison::Eq)
                .map_err(|error| runtime_error(condition.span(), error))?;
            if matched {
                matched_index = Some(index);
                break;
            }
        }

        let Some(mut index) = matched_index.or(default_index) else {
            return Ok(ReferenceReturnBodyFlow::Normal);
        };

        while index < cases.len() {
            for stmt in &cases[index].body {
                match self.execute_reference_return_assignment_statement(function, stmt, scope)? {
                    ReferenceReturnBodyFlow::Normal => {}
                    ReferenceReturnBodyFlow::Break { depth, .. } if depth <= 1 => {
                        return Ok(ReferenceReturnBodyFlow::Normal);
                    }
                    ReferenceReturnBodyFlow::Break { depth, span } => {
                        return Ok(ReferenceReturnBodyFlow::Break {
                            depth: depth - 1,
                            span,
                        });
                    }
                    ReferenceReturnBodyFlow::Continue { span, .. } => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::invalid_loop_control(
                                "continue inside switch is not implemented; use break for switch cases in the current subset",
                            ),
                        ));
                    }
                    flow @ (ReferenceReturnBodyFlow::Goto { .. }
                    | ReferenceReturnBodyFlow::Throw { .. }
                    | ReferenceReturnBodyFlow::Return(_)) => return Ok(flow),
                }
            }
            index += 1;
        }

        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn execute_reference_return_assignment_statement_list(
        &mut self,
        function: &FunctionDecl,
        statements: &[Stmt],
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnBodyFlow> {
        let mut labels = HashMap::new();
        for (index, stmt) in statements.iter().enumerate() {
            if let Stmt::Label { name, .. } = stmt {
                labels.insert(name.clone(), index);
            }
        }

        let mut index = 0;
        while index < statements.len() {
            let stmt = &statements[index];
            if let Stmt::Goto { label, span } = stmt {
                let Some(target) = labels.get(label) else {
                    return Ok(ReferenceReturnBodyFlow::Goto {
                        label: label.clone(),
                        span: *span,
                    });
                };
                index = *target;
                continue;
            }

            let flow = self.execute_reference_return_assignment_statement(function, stmt, scope)?;
            match flow {
                ReferenceReturnBodyFlow::Normal => {}
                ReferenceReturnBodyFlow::Goto { label, span } => {
                    let Some(target) = labels.get(&label) else {
                        return Ok(ReferenceReturnBodyFlow::Goto { label, span });
                    };
                    index = *target;
                    continue;
                }
                flow => return Ok(flow),
            }
            index += 1;
        }
        Ok(ReferenceReturnBodyFlow::Normal)
    }

    fn reference_return_this_property_array_access_local_binding(
        &mut self,
        function: &FunctionDecl,
        property: &str,
        keys: Vec<ArrayKey>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnLocalBinding>> {
        let Some(Value::Object(object)) = scope.read_named("this") else {
            return Ok(None);
        };
        self.reference_return_property_value_array_access_local_binding(
            function, object, property, keys, span, scope,
        )
    }

    fn reference_return_object_property_array_access_local_binding(
        &mut self,
        function: &FunctionDecl,
        object_name: &str,
        property: &str,
        keys: Vec<ArrayKey>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnLocalBinding>> {
        let Some(Value::Object(object)) = scope.read_named(object_name) else {
            return Ok(None);
        };
        self.reference_return_property_value_array_access_local_binding(
            function, object, property, keys, span, scope,
        )
    }

    fn reference_return_property_value_array_access_local_binding(
        &mut self,
        function: &FunctionDecl,
        object: PhpObject,
        property: &str,
        keys: Vec<ArrayKey>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnLocalBinding>> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let Ok(Value::Object(array_access_object)) =
            object.read_property_from_context(property, current_class_id, &protected_class_ids)
        else {
            return Ok(None);
        };
        if !self
            .classes
            .implements_interface(array_access_object.class_id(), "ArrayAccess")
        {
            return Ok(None);
        }

        let hidden_name = self.hidden_array_access_reference_object_name(&array_access_object);
        scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));
        self.reference_return_array_access_local_binding_for_object(
            function,
            array_access_object,
            hidden_name,
            keys,
            span,
            scope,
        )
    }

    fn reference_return_array_access_local_binding_for_object(
        &mut self,
        function: &FunctionDecl,
        object: PhpObject,
        object_name: String,
        keys: Vec<ArrayKey>,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Option<ReferenceReturnLocalBinding>> {
        if !self
            .classes
            .implements_interface(object.class_id(), "ArrayAccess")
        {
            return Ok(None);
        }

        let Some(binding) = self.evaluate_array_access_reference_source_binding_for_object(
            object,
            object_name,
            keys,
            None,
            span,
            scope,
        )?
        else {
            return Ok(None);
        };

        match binding {
            NonDirectReferenceSourceBinding::ArrayOffset(alias) => Ok(Some(
                ReferenceReturnLocalBinding::ArrayOffsetAliases(vec![alias]),
            )),
            NonDirectReferenceSourceBinding::DetachedValue(_) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "reference-return ArrayAccess expressions require by-reference offsetGet() returning a covered lvalue in the current subset",
                ),
            )),
        }
    }

    fn reference_return_local_binding_from_expr(
        &mut self,
        function: &FunctionDecl,
        value: &Expr,
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<ReferenceReturnLocalBinding> {
        match value {
            Expr::Call { .. }
            | Expr::MethodCall { .. }
            | Expr::DynamicMethodCall { .. }
            | Expr::StaticMethodCall { .. }
            | Expr::SelfMethodCall { .. }
            | Expr::ParentMethodCall { .. }
            | Expr::LateStaticMethodCall { .. }
            | Expr::ObjectStaticMethodCall { .. }
            | Expr::DynamicCall { .. } => {
                let binding = self.evaluate_reference_return_call_binding(value, span, scope)?;
                match binding {
                    ReferenceReturnBinding::Cell(cell) => Ok(ReferenceReturnLocalBinding::Cell(cell)),
                    ReferenceReturnBinding::ArrayOffset(alias) => {
                        Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(vec![alias]))
                    }
                    ReferenceReturnBinding::ArrayOffsets(aliases) => {
                        Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(aliases))
                    }
                }
            }
            Expr::Variable(name, variable_span) => {
                if let Some(aliases) = scope.array_offset_aliases_for_name(name) {
                    return Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(aliases));
                }
                if let Some(source) = scope
                    .public_or_dirty_object_property_array_copy_source_for_static(name)
                {
                    if let Some(cell) = scope.read_cell(name) {
                        self.rehydrate_array_copy_return_cell_reference_cells(
                            &source,
                            &cell,
                            scope,
                        );
                        return Ok(ReferenceReturnLocalBinding::Cell(cell));
                    }
                }
                scope
                    .direct_reference_cell_for_static_source(name)
                    .map(ReferenceReturnLocalBinding::Cell)
                    .ok_or_else(|| runtime_error(*variable_span, RuntimeError::undefined_variable(name)))
            }
            Expr::StaticProperty { .. }
            | Expr::DynamicStaticProperty { .. }
            | Expr::ObjectStaticProperty { .. }
            | Expr::DynamicObjectStaticProperty { .. }
            | Expr::SelfStaticProperty { .. }
            | Expr::DynamicSelfStaticProperty { .. }
            | Expr::ParentStaticProperty { .. }
            | Expr::DynamicParentStaticProperty { .. }
            | Expr::LateStaticProperty { .. }
            | Expr::DynamicLateStaticProperty { .. } => {
                let cell = self.static_property_reference_cell_from_expr(value, span, scope)?;
                Ok(ReferenceReturnLocalBinding::Cell(cell))
            }
            Expr::Index { target, index, .. } => {
                if let Some((root_name, indices)) =
                    Self::collect_direct_variable_array_index_path(target, index)
                {
                    let keys = indices
                        .iter()
                        .map(|index| self.evaluate_array_key(index, scope))
                        .collect::<CompileResult<Vec<_>>>()?;
                    if let Some(Value::Object(object)) = scope.read_named(root_name) {
                        if let Some(binding) = self
                            .reference_return_array_access_local_binding_for_object(
                                function,
                                object,
                                root_name.to_string(),
                                keys.clone(),
                                span,
                                scope,
                            )?
                        {
                            return Ok(binding);
                        }
                    }
                    if root_name == "GLOBALS" {
                        let (global_name, keys) =
                            SymbolTable::split_globals_reference_path(keys, span)?;
                        let alias = ArrayOffsetAlias {
                            root: ArrayOffsetAliasRoot::GlobalArray { name: global_name },
                            keys,
                        };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        return Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(vec![
                            alias,
                        ]));
                    }
                    if scope.name_routes_to_global_storage(root_name) {
                        let alias = ArrayOffsetAlias {
                            root: ArrayOffsetAliasRoot::GlobalArray {
                                name: root_name.to_string(),
                            },
                            keys,
                        };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        return Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(vec![
                            alias,
                        ]));
                    }
                    if let Some(aliases) = scope.array_offset_aliases_for_name(root_name) {
                        return Ok(ReferenceReturnLocalBinding::ArrayOffsetAliases(
                            Self::array_offset_aliases_with_suffix(&aliases, &keys),
                        ));
                    }
                    let alias = ArrayOffsetAlias {
                        root: ArrayOffsetAliasRoot::StaticArray {
                            name: root_name.to_string(),
                        },
                        keys: keys.clone(),
                    };
                    let retained =
                        scope.retained_static_copy_sources_for_aliases(std::slice::from_ref(
                            &alias,
                        ));
                    scope.materialize_array_offset_alias(&alias, span)?;
                    scope.restore_retained_static_copy_sources(retained);
                    return Ok(ReferenceReturnLocalBinding::ArrayOffset {
                        root_name: root_name.to_string(),
                        keys,
                    });
                }

                if let Some((property, indices)) =
                    Self::collect_this_property_array_index_path(target, index)
                {
                    let keys = indices
                        .iter()
                        .map(|index| self.evaluate_array_key(index, scope))
                        .collect::<CompileResult<Vec<_>>>()?;
                    if let Some(binding) = self
                        .reference_return_this_property_array_access_local_binding(
                            function, property, keys.clone(), span, scope,
                        )?
                    {
                        return Ok(binding);
                    }
                    let root = self.this_object_property_alias_root(property, scope, span)?;
                    let alias = ArrayOffsetAlias { root, keys };
                    scope.materialize_array_offset_alias(&alias, span)?;
                    return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                        alias,
                    ));
                }

                if let Some((object_name, property, indices)) =
                    Self::collect_direct_object_property_array_index_path(target, index)
                {
                    if object_name != "this" {
                        let keys = indices
                            .iter()
                            .map(|index| self.evaluate_array_key(index, scope))
                            .collect::<CompileResult<Vec<_>>>()?;
                        if let Some(binding) = self
                            .reference_return_object_property_array_access_local_binding(
                                function,
                                object_name,
                                property,
                                keys.clone(),
                                span,
                                scope,
                            )?
                        {
                            return Ok(binding);
                        }
                        let root = self.context_object_property_alias_root(
                            object_name,
                            property,
                            span,
                            scope,
                        )?;
                        let alias = ArrayOffsetAlias { root, keys };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                            alias,
                        ));
                    }
                }

                if let Expr::Property {
                    target, property, ..
                } = target.as_ref()
                {
                    if matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") {
                        let key = self.evaluate_array_key(index, scope)?;
                        if let Some(binding) = self
                            .reference_return_this_property_array_access_local_binding(
                                function,
                                property,
                                vec![key.clone()],
                                span,
                                scope,
                            )?
                        {
                            return Ok(binding);
                        }
                        let root = self.this_object_property_alias_root(property, scope, span)?;
                        let alias = ArrayOffsetAlias {
                            root,
                            keys: vec![key],
                        };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                            alias,
                        ));
                    }
                }

                if let Some((object_name, property, indices)) =
                    Self::collect_direct_dynamic_object_property_array_index_path(target, index)
                {
                    if object_name == "this" {
                        let property =
                            self.evaluate_dynamic_property_name(property, span, scope)?;
                        let keys = indices
                            .iter()
                            .map(|index| self.evaluate_array_key(index, scope))
                            .collect::<CompileResult<Vec<_>>>()?;
                        if let Some(binding) = self
                            .reference_return_this_property_array_access_local_binding(
                                function,
                                &property,
                                keys.clone(),
                                span,
                                scope,
                            )?
                        {
                            return Ok(binding);
                        }
                        let root = self.this_object_property_alias_root(&property, scope, span)?;
                        let alias = ArrayOffsetAlias { root, keys };
                        scope.materialize_array_offset_alias(&alias, span)?;
                        return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                            alias,
                        ));
                    }
                }

                if let Some((static_property, indices)) =
                    Self::collect_static_property_array_index_path(target, index)
                {
                    let keys = indices
                        .iter()
                        .map(|index| self.evaluate_array_key(index, scope))
                        .collect::<CompileResult<Vec<_>>>()?;
                    let cell = self.static_property_array_offset_reference_cell_from_expr(
                        static_property,
                        &keys,
                        span,
                        scope,
                    )?;
                    return Ok(ReferenceReturnLocalBinding::Cell(cell));
                }

                let (root, indices) = Self::collect_array_index_path(target, index);
                let root_value = self.evaluate(root, scope)?;
                if let Value::Object(object) = root_value {
                    let keys = indices
                        .iter()
                        .map(|index| self.evaluate_array_key(index, scope))
                        .collect::<CompileResult<Vec<_>>>()?;
                    let hidden_name = self.hidden_array_access_reference_object_name(&object);
                    scope.write_static(&hidden_name, Value::Object(object.clone()));
                    if let Some(binding) = self
                        .reference_return_array_access_local_binding_for_object(
                            function,
                            object,
                            hidden_name,
                            keys,
                            span,
                            scope,
                        )?
                    {
                        return Ok(binding);
                    }
                }

                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "reference-return array-offset expressions are only implemented for direct variable roots and bounded direct object-property roots in the current subset",
                    ),
                ))
            }
            Expr::Property {
                target, property, ..
            } => {
                if matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") {
                    let root = self.this_object_property_alias_root(property, scope, span)?;
                    let alias = ArrayOffsetAlias {
                        root,
                        keys: Vec::new(),
                    };
                    scope.materialize_array_offset_alias(&alias, span)?;
                    return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                        alias,
                    ));
                }
                if let Expr::Variable(object_name, _) = target.as_ref() {
                    let root =
                        self.context_object_property_alias_root(object_name, property, span, scope)?;
                    let alias = ArrayOffsetAlias {
                        root,
                        keys: Vec::new(),
                    };
                    scope.materialize_array_offset_alias(&alias, span)?;
                    return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                        alias,
                    ));
                }
                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "reference-return property expressions are only implemented for bounded direct object-property roots in the current subset",
                    ),
                ))
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                if matches!(target.as_ref(), Expr::Variable(name, _) if name == "this") {
                    let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                    let root = self.this_object_property_alias_root(&property, scope, span)?;
                    let alias = ArrayOffsetAlias {
                        root,
                        keys: Vec::new(),
                    };
                    scope.materialize_array_offset_alias(&alias, span)?;
                    return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                        alias,
                    ));
                }
                if let Expr::Variable(object_name, _) = target.as_ref() {
                    let property = self.evaluate_dynamic_property_name(property, span, scope)?;
                    let root = self.context_object_property_alias_root(
                        object_name,
                        &property,
                        span,
                        scope,
                    )?;
                    let alias = ArrayOffsetAlias {
                        root,
                        keys: Vec::new(),
                    };
                    scope.materialize_array_offset_alias(&alias, span)?;
                    return Ok(ReferenceReturnLocalBinding::ObjectPropertyArrayOffset(
                        alias,
                    ));
                }
                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "reference-return dynamic-property expressions are only implemented for bounded direct object-property roots in the current subset",
                    ),
                ))
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "reference returns are only implemented for direct variable and direct array-offset return expressions",
                ),
            )),
        }
    }

    fn call_user_function_with_values(
        &mut self,
        function: Rc<FunctionDecl>,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        let function = function.as_ref();
        ensure_user_function_arity_with_extra_policy(function, args.len(), span, true)?;
        ensure_supported_function_signature(function, args.len(), span)?;
        self.ensure_user_function_call_depth(function, span)?;
        self.call_user_function_with_checked_values(
            function,
            args,
            None,
            None,
            None,
            Vec::new(),
            None,
        )
    }

    fn evaluate_user_function_call_arguments(
        &mut self,
        function: &FunctionDecl,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Vec<Value>, Vec<ReferenceBinding>)> {
        self.evaluate_user_function_call_arguments_with_options(
            function,
            args,
            span,
            caller_scope,
            false,
        )
    }

    fn evaluate_user_function_call_arguments_with_options(
        &mut self,
        function: &FunctionDecl,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        allow_reference_return_array_bindings: bool,
    ) -> CompileResult<(Vec<Value>, Vec<ReferenceBinding>)> {
        let frame = self.evaluate_user_function_call_frame_bindings_with_options(
            function,
            args,
            span,
            caller_scope,
            allow_reference_return_array_bindings,
        )?;
        let values = frame.values;
        let reference_bindings = frame.reference_bindings;
        Ok((values, reference_bindings))
    }

    fn evaluate_user_function_call_frame_bindings_with_options(
        &mut self,
        function: &FunctionDecl,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        allow_reference_return_array_bindings: bool,
    ) -> CompileResult<CallFrameArgumentBindings> {
        if args
            .iter()
            .any(|arg| matches!(arg, Expr::NamedArgument { .. }))
            && function.params.iter().all(|param| !param.by_reference)
        {
            let (values, argument_keys) = self.evaluate_positional_array_spread_call_values(
                function,
                &callable_name(&function.name),
                args,
                span,
                caller_scope,
            )?;
            let by_value_array_copy_bindings =
                Self::by_value_array_copy_bindings_for_call(function, args);

            return Ok(CallFrameArgumentBindings {
                values,
                argument_keys,
                reference_bindings: Vec::new(),
                array_copy_source_bindings: Vec::new(),
                by_value_array_copy_bindings,
            });
        }

        let (values, reference_bindings, array_copy_source_bindings) = self
            .evaluate_user_function_call_arguments_with_options_and_array_copy_sources(
                function,
                args,
                span,
                caller_scope,
                allow_reference_return_array_bindings,
            )?;
        let by_value_array_copy_bindings =
            Self::by_value_array_copy_bindings_for_call(function, args);

        Ok(CallFrameArgumentBindings {
            values,
            argument_keys: Vec::new(),
            reference_bindings,
            array_copy_source_bindings,
            by_value_array_copy_bindings,
        })
    }

    fn evaluate_user_function_call_arguments_with_options_and_array_copy_sources(
        &mut self,
        function: &FunctionDecl,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        allow_reference_return_array_bindings: bool,
    ) -> CompileResult<(
        Vec<Value>,
        Vec<ReferenceBinding>,
        Vec<ArrayCopySourceBinding>,
    )> {
        if call_arguments_have_spread(args) {
            let frame =
                self.evaluate_array_spread_call_frame_bindings(function, args, span, caller_scope)?;
            return Ok((
                frame.values,
                frame.reference_bindings,
                frame.array_copy_source_bindings,
            ));
        }

        if args
            .iter()
            .any(|arg| matches!(arg, Expr::NamedArgument { .. }))
        {
            return self
                .evaluate_user_function_named_call_arguments_with_options_and_array_copy_sources(
                    function,
                    args,
                    span,
                    caller_scope,
                    allow_reference_return_array_bindings,
                );
        }

        let mut values = Vec::with_capacity(args.len());
        let mut reference_bindings = Vec::new();
        let mut by_value_array_copy_source_bindings = Vec::new();

        for (index, arg) in args.iter().enumerate() {
            let Some((param_index, param)) = function
                .params
                .get(index)
                .map(|param| (index, param))
                .or_else(|| {
                    function
                        .params
                        .iter()
                        .enumerate()
                        .next_back()
                        .filter(|(_, param)| param.is_variadic)
                })
            else {
                values.push(self.evaluate_by_value_argument_with_cow_source(arg, caller_scope)?);
                continue;
            };

            let evaluated = self.evaluate_user_function_call_argument_for_param(
                function,
                param,
                param_index,
                arg,
                index,
                caller_scope,
                allow_reference_return_array_bindings,
            )?;
            if self.exit_signal.is_some() {
                return Ok((
                    values,
                    reference_bindings,
                    by_value_array_copy_source_bindings,
                ));
            }
            values.push(evaluated.value);
            if let Some(binding) = evaluated.reference_binding {
                reference_bindings.push(binding);
            }
            if let Some(binding) = evaluated.array_copy_source_binding {
                by_value_array_copy_source_bindings.push(binding);
            }
        }

        if function
            .params
            .iter()
            .enumerate()
            .any(|(index, param)| param.by_reference && param.is_variadic && index < args.len())
        {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable_name(&function.name),
                    "variadic reference parameter invocation is not implemented",
                ),
            ));
        }

        Ok((
            values,
            reference_bindings,
            by_value_array_copy_source_bindings,
        ))
    }

    fn evaluate_user_function_named_call_arguments_with_options_and_array_copy_sources(
        &mut self,
        function: &FunctionDecl,
        args: &[Expr],
        span: Span,
        caller_scope: &mut SymbolTable,
        allow_reference_return_array_bindings: bool,
    ) -> CompileResult<(
        Vec<Value>,
        Vec<ReferenceBinding>,
        Vec<ArrayCopySourceBinding>,
    )> {
        let mut slots: Vec<Option<EvaluatedCallArgument>> =
            (0..function.params.len()).map(|_| None).collect();
        let mut saw_named = false;
        let mut positional_index = 0usize;
        let mut highest_param_index: Option<usize> = None;

        for (source_index, arg) in args.iter().enumerate() {
            let (param_index, arg_expr) = match arg {
                Expr::NamedArgument { name, expr, span } => {
                    saw_named = true;
                    let Some(param_index) =
                        function.params.iter().position(|param| param.name == *name)
                    else {
                        return Err(runtime_error(
                            *span,
                            RuntimeError::unsupported_call(
                                callable_name(&function.name),
                                format!(
                                    "named argument ${name} does not match a declared parameter in the current subset"
                                ),
                            ),
                        ));
                    };
                    (param_index, expr.as_ref())
                }
                Expr::SpreadArgument { span, .. } => {
                    return Err(runtime_error(
                        *span,
                        RuntimeError::unsupported_call(
                            callable_name(&function.name),
                            "spread arguments mixed with named arguments are not implemented in the current subset",
                        ),
                    ));
                }
                expr => {
                    if saw_named {
                        return Err(runtime_error(
                            expr.span(),
                            RuntimeError::unsupported_call(
                                callable_name(&function.name),
                                "positional arguments after named arguments are not implemented in the current subset",
                            ),
                        ));
                    }
                    let param_index = positional_index;
                    positional_index += 1;
                    (param_index, expr)
                }
            };

            let Some((effective_param_index, param)) = function
                .params
                .get(param_index)
                .map(|param| (param_index, param))
                .or_else(|| {
                    function
                        .params
                        .iter()
                        .enumerate()
                        .next_back()
                        .filter(|(_, param)| param.is_variadic)
                })
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::arity_mismatch(
                        callable_name(&function.name),
                        arity_expectation(
                            required_param_count(function),
                            function.params.len(),
                            false,
                        ),
                        args.len(),
                    ),
                ));
            };

            if param.is_variadic {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        "variadic parameters with named arguments are not implemented in the current subset",
                    ),
                ));
            }

            if slots[effective_param_index].is_some() {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::unsupported_call(
                        callable_name(&function.name),
                        format!(
                            "duplicate argument for parameter ${} is not implemented in the current subset",
                            param.name
                        ),
                    ),
                ));
            }

            let evaluated = self.evaluate_user_function_call_argument_for_param(
                function,
                param,
                effective_param_index,
                arg_expr,
                source_index,
                caller_scope,
                allow_reference_return_array_bindings,
            )?;
            if self.exit_signal.is_some() {
                return Ok((Vec::new(), Vec::new(), Vec::new()));
            }
            slots[effective_param_index] = Some(evaluated);
            highest_param_index = Some(
                highest_param_index
                    .map(|current| current.max(effective_param_index))
                    .unwrap_or(effective_param_index),
            );
        }

        let Some(highest_param_index) = highest_param_index else {
            return Ok((Vec::new(), Vec::new(), Vec::new()));
        };

        let mut values = Vec::with_capacity(highest_param_index + 1);
        let mut reference_bindings = Vec::new();
        let mut by_value_array_copy_source_bindings = Vec::new();

        for (param_index, slot) in slots.into_iter().enumerate().take(highest_param_index + 1) {
            if let Some(evaluated) = slot {
                values.push(evaluated.value);
                if let Some(binding) = evaluated.reference_binding {
                    reference_bindings.push(binding);
                }
                if let Some(binding) = evaluated.array_copy_source_binding {
                    by_value_array_copy_source_bindings.push(binding);
                }
                continue;
            }

            let param = &function.params[param_index];
            let Some(default) = param.default.as_ref() else {
                return Err(runtime_error(
                    span,
                    RuntimeError::arity_mismatch(
                        callable_name(&function.name),
                        arity_expectation(
                            required_param_count(function),
                            function.params.len(),
                            false,
                        ),
                        args.len(),
                    ),
                ));
            };
            let mut default_scope = SymbolTable::new();
            values.push(self.evaluate_constant_like_expr(default, &mut default_scope)?);
        }

        Ok((
            values,
            reference_bindings,
            by_value_array_copy_source_bindings,
        ))
    }

    fn evaluate_visible_object_property_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<
        Option<(
            VariableCell,
            Value,
            String,
            Option<ArrayCopySource>,
            Option<(PhpObject, String)>,
        )>,
    > {
        let Some((object_name, property)) =
            self.direct_object_property_reference_argument_parts(arg, caller_scope)?
        else {
            return Ok(None);
        };

        let object = match caller_scope.read_static(&object_name, arg.span())? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.read_property_from_context(&property, current_class_id, &protected_class_ids) {
            Ok(value) => {
                let source = if matches!(value, Value::Array(_)) {
                    caller_scope
                        .object_property_array_copy_source_for_path(&object, &property, &[])
                        .or_else(|| {
                            Some(ArrayCopySource::object_property(
                                object.clone(),
                                property.clone(),
                                Vec::new(),
                                true,
                            ))
                        })
                } else {
                    None
                };
                let cell = object
                    .bind_property_reference_cell_from_context(
                        &property,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(arg.span(), error))?;
                let mut value = cell.value_cloned();
                if matches!(value, Value::Array(_)) {
                    let local_property_source = ArrayCopySource::object_property(
                        object.clone(),
                        property.clone(),
                        Vec::new(),
                        true,
                    );
                    value = caller_scope.value_with_object_property_aliases_from_array_copy(
                        value,
                        Some(local_property_source),
                        true,
                    );
                    cell.set_value(value.clone());
                }
                Ok(Some((
                    cell,
                    value,
                    format!("${object_name}->{property}"),
                    source,
                    Some((object, property)),
                )))
            }
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => Ok(None),
            Err(error) => Err(runtime_error(arg.span(), error)),
        }
    }

    fn evaluate_nested_visible_object_property_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(VariableCell, Value, String)>> {
        let (target, property) = match arg {
            Expr::Property {
                target, property, ..
            } => {
                if matches!(target.as_ref(), Expr::Variable(_, _)) {
                    return Ok(None);
                }
                (target.as_ref(), property.clone())
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                if matches!(target.as_ref(), Expr::Variable(_, _)) {
                    return Ok(None);
                }
                let property =
                    self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
                (target.as_ref(), property)
            }
            _ => return Ok(None),
        };

        let holder = self.evaluate(target, caller_scope)?;
        let Value::Object(object) = holder else {
            return Err(runtime_error(
                arg.span(),
                RuntimeError::invalid_property_access(format!(
                    "cannot read property ${property} on {}",
                    holder.type_name()
                )),
            ));
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.read_property_from_context(&property, current_class_id, &protected_class_ids) {
            Ok(_) => {
                let cell = object
                    .bind_property_reference_cell_from_context(
                        &property,
                        current_class_id,
                        &protected_class_ids,
                    )
                    .map_err(|error| runtime_error(arg.span(), error))?;
                let value = cell.value_cloned();
                Ok(Some((cell, value, format!("<object>->{property}"))))
            }
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => Ok(None),
            Err(error) => Err(runtime_error(arg.span(), error)),
        }
    }

    fn evaluate_by_value_argument_with_cow_source(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        let (value, array_copy_source) =
            self.evaluate_by_value_call_argument_with_array_copy_source(arg, caller_scope)?;
        Ok(
            caller_scope.value_with_object_property_aliases_from_array_copy(
                value,
                array_copy_source,
                true,
            ),
        )
    }

    fn detached_reference_argument_target(
        value: Value,
        source: Option<ArrayCopySource>,
        name: &str,
    ) -> ReferenceBindingTarget {
        if let Some(source) = source {
            ReferenceBindingTarget::ValueWithArrayCopySource { source }
        } else {
            ReferenceBindingTarget::CallerCell {
                name: name.to_string(),
                cell: value_cell(value),
            }
        }
    }

    fn evaluate_magic_get_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(VariableCell, Value)>> {
        let Some((object_name, property)) =
            self.direct_object_property_reference_argument_parts(arg, caller_scope)?
        else {
            return Ok(None);
        };

        let object = match caller_scope.read_static(&object_name, arg.span())? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.read_property_from_context(&property, current_class_id, &protected_class_ids) {
            Ok(_) => Ok(None),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {
                match self.call_magic_get_reference_root_binding(
                    object,
                    &property,
                    arg.span(),
                    caller_scope,
                )? {
                    Some(MagicGetReferenceRootBinding::Cell(cell)) => {
                        let value = cell.value_cloned();
                        Ok(Some((cell, value)))
                    }
                    Some(MagicGetReferenceRootBinding::DetachedValue(value)) => {
                        Ok(Some((value_cell(value.clone()), value)))
                    }
                    None => Ok(None),
                }
            }
            Err(error) => Err(runtime_error(arg.span(), error)),
        }
    }

    fn direct_object_property_reference_argument_parts(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(String, String)>> {
        match arg {
            Expr::Property {
                target, property, ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    return Ok(None);
                };
                Ok(Some((object_name.clone(), property.clone())))
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                let Expr::Variable(object_name, _) = target.as_ref() else {
                    return Ok(None);
                };
                let property =
                    self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
                Ok(Some((object_name.clone(), property)))
            }
            _ => Ok(None),
        }
    }

    fn evaluate_by_value_magic_get_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(Value, ReferenceBindingTarget)>> {
        let Some((object_name, property)) =
            self.direct_object_property_reference_argument_parts(arg, caller_scope)?
        else {
            return Ok(None);
        };

        let object = match caller_scope.read_static(&object_name, arg.span())? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.read_property_from_context(&property, current_class_id, &protected_class_ids) {
            Ok(_) => Ok(None),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => Ok(self
                .call_by_value_magic_get_reference_argument_with_array_copy_source(
                    object,
                    &property,
                    arg.span(),
                    caller_scope,
                    false,
                )?
                .map(|(value, source)| {
                    let target = Self::detached_reference_argument_target(
                        value.clone(),
                        source,
                        "<magic __get value>",
                    );
                    (value, target)
                })),
            Err(error) => Err(runtime_error(arg.span(), error)),
        }
    }

    fn call_by_value_magic_get_reference_argument_with_array_copy_source(
        &mut self,
        object: PhpObject,
        property: &str,
        span: Span,
        caller_scope: &mut SymbolTable,
        suppress_notice_for_array_access_object: bool,
    ) -> CompileResult<Option<(Value, Option<ArrayCopySource>)>> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), "__get")
        else {
            return Ok(None);
        };

        if is_static {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{class_name}::__get()"),
                    "static magic instance methods are not implemented in the current subset",
                ),
            ));
        }

        self.ensure_instance_method_visible(class_id, &class_name, "__get", visibility, span)?;

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        if function.returns_by_reference {
            return Ok(None);
        }
        ensure_user_function_arity(function, 1, span)?;
        ensure_supported_magic_array_access_function_signature(function, 1, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let called_class_id = object.class_id();
        let (value, source) = self.call_user_function_with_this_and_array_copy_source(
            function,
            object,
            vec![Value::String(property.to_string())],
            Some(class_id),
            Some(called_class_id),
            caller_scope,
        )?;
        let suppress_notice = suppress_notice_for_array_access_object
            && matches!(
                &value,
                Value::Object(object)
                    if self
                        .classes
                        .implements_interface(object.class_id(), "ArrayAccess")
            );
        if !suppress_notice {
            self.emit_notice(
                "__get()",
                format!(
                    "Indirect modification of overloaded property {class_name}::${property} has no effect"
                ),
                span,
            )?;
        }
        let source = if matches!(value, Value::Array(_)) {
            source
        } else {
            None
        };
        let value = caller_scope.value_with_object_property_aliases_from_array_copy(
            value,
            source.clone(),
            true,
        );
        Ok(Some((value, source)))
    }

    fn evaluate_magic_get_array_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let Some((object_name, property, indices)) =
            self.direct_or_dynamic_object_property_array_argument_parts(arg, caller_scope)?
        else {
            return Ok(None);
        };

        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, caller_scope))
            .collect::<CompileResult<Vec<_>>>()?;
        let Some(binding) = self.evaluate_magic_get_array_access_reference_source_binding(
            &object_name,
            &property,
            keys,
            arg.span(),
            caller_scope,
            true,
            false,
        )?
        else {
            return Ok(None);
        };
        self.array_offset_alias_from_reference_source_binding(binding, arg.span(), caller_scope)
            .map(Some)
    }

    fn evaluate_by_value_magic_get_array_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(Value, ReferenceBindingTarget)>> {
        let Some((object_name, property, indices)) =
            self.direct_or_dynamic_object_property_array_argument_parts(arg, caller_scope)?
        else {
            return Ok(None);
        };
        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, caller_scope))
            .collect::<CompileResult<Vec<_>>>()?;
        if keys.is_empty() {
            return Ok(None);
        }

        let object = match caller_scope.read_static(&object_name, arg.span())? {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        match object.read_property_from_context(&property, current_class_id, &protected_class_ids) {
            Ok(_) => Ok(None),
            Err(error) if Self::is_magic_get_fallback_property_error(&error) => {
                let Some((root_value, root_source)) = self
                    .call_by_value_magic_get_reference_argument_with_array_copy_source(
                        object,
                        &property,
                        arg.span(),
                        caller_scope,
                        true,
                    )?
                else {
                    return Ok(None);
                };

                if let Value::Object(nested_object) = &root_value {
                    if self
                        .classes
                        .implements_interface(nested_object.class_id(), "ArrayAccess")
                    {
                        let hidden_name =
                            self.hidden_array_access_reference_object_name(nested_object);
                        caller_scope
                            .write_static(&hidden_name, Value::Object(nested_object.clone()));
                        return self.evaluate_by_value_array_access_reference_argument_for_object(
                            nested_object.clone(),
                            hidden_name,
                            keys,
                            arg.span(),
                            caller_scope,
                        );
                    }
                }

                self.reject_by_value_array_access_scalar_parent_for_nested_write(
                    &root_value,
                    &keys,
                    false,
                    arg.span(),
                )?;
                let (value, source) = if let Value::Array(array) = root_value {
                    let value = Self::detached_array_copy_reference_source_value(array, &keys);
                    let source = root_source.and_then(|source| {
                        Self::array_copy_source_with_suffix(source, &keys, &value)
                    });
                    (value, source)
                } else {
                    (Value::Null, None)
                };
                let source = if matches!(value, Value::Array(_)) {
                    source
                } else {
                    None
                };
                let value = caller_scope.value_with_object_property_aliases_from_array_copy(
                    value,
                    source.clone(),
                    true,
                );
                let target = Self::detached_reference_argument_target(
                    value.clone(),
                    source,
                    "<magic __get value>",
                );
                Ok(Some((value, target)))
            }
            Err(error) => Err(runtime_error(arg.span(), error)),
        }
    }

    fn direct_or_dynamic_object_property_array_argument_parts<'a>(
        &mut self,
        arg: &'a Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(String, String, Vec<&'a Expr>)>> {
        if let Some((object, property, indices)) =
            Self::direct_object_property_array_argument_parts(arg)
        {
            return Ok(Some((object, property, indices)));
        }

        if let Some((object, property, indices)) =
            Self::dynamic_object_property_array_argument_parts(arg)
        {
            let property =
                self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
            return Ok(Some((object, property, indices)));
        }

        Ok(None)
    }

    fn evaluate_by_value_array_access_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(Value, ReferenceBindingTarget)>> {
        let Expr::Index { target, index, .. } = arg else {
            return Ok(None);
        };

        if let Some((name, indices)) = Self::collect_direct_variable_array_index_path(target, index)
        {
            let keys = indices
                .iter()
                .map(|index| self.evaluate_array_key(index, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            if self
                .array_access_array_copy_source_for_direct_variable_keys_with_terminal_ref(
                    name,
                    &keys,
                    arg.span(),
                    caller_scope,
                )
                .is_some_and(|(_, terminal_returns_by_reference)| terminal_returns_by_reference)
            {
                return Ok(None);
            }
            let Some(Value::Object(object)) = caller_scope.read_named(name) else {
                return Ok(None);
            };
            if !self
                .classes
                .implements_interface(object.class_id(), "ArrayAccess")
            {
                return Ok(None);
            }
            return self.evaluate_by_value_array_access_reference_argument_for_object(
                object,
                name.to_string(),
                keys,
                arg.span(),
                caller_scope,
            );
        }

        if let Some((object_name, property, indices)) =
            Self::collect_direct_object_property_array_index_path(target, index)
        {
            let keys = indices
                .iter()
                .map(|index| self.evaluate_array_key(index, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            if self
                .array_access_array_copy_source_for_object_property_keys_with_terminal_ref(
                    object_name,
                    property,
                    &keys,
                    arg.span(),
                    caller_scope,
                )
                .is_some_and(|(_, terminal_returns_by_reference)| terminal_returns_by_reference)
            {
                return Ok(None);
            }
            let Some(Value::Object(holder)) = caller_scope.read_named(object_name) else {
                return Ok(None);
            };
            let (current_class_id, protected_class_ids) = self.current_property_access_context();
            let Ok(Value::Object(object)) =
                holder.read_property_from_context(property, current_class_id, &protected_class_ids)
            else {
                return Ok(None);
            };
            if !self
                .classes
                .implements_interface(object.class_id(), "ArrayAccess")
            {
                return Ok(None);
            }
            let hidden_name = self.hidden_array_access_reference_object_name(&object);
            caller_scope.write_static(&hidden_name, Value::Object(object.clone()));
            return self.evaluate_by_value_array_access_reference_argument_for_object(
                object,
                hidden_name,
                keys,
                arg.span(),
                caller_scope,
            );
        }

        if let Some((object_name, property, indices)) =
            Self::collect_direct_dynamic_object_property_array_index_path(target, index)
        {
            let property =
                self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
            let keys = indices
                .iter()
                .map(|index| self.evaluate_array_key(index, caller_scope))
                .collect::<CompileResult<Vec<_>>>()?;
            if self
                .array_access_array_copy_source_for_object_property_keys_with_terminal_ref(
                    object_name,
                    &property,
                    &keys,
                    arg.span(),
                    caller_scope,
                )
                .is_some_and(|(_, terminal_returns_by_reference)| terminal_returns_by_reference)
            {
                return Ok(None);
            }
            let Some(Value::Object(holder)) = caller_scope.read_named(object_name) else {
                return Ok(None);
            };
            let (current_class_id, protected_class_ids) = self.current_property_access_context();
            let Ok(Value::Object(object)) = holder.read_property_from_context(
                &property,
                current_class_id,
                &protected_class_ids,
            ) else {
                return Ok(None);
            };
            if !self
                .classes
                .implements_interface(object.class_id(), "ArrayAccess")
            {
                return Ok(None);
            }
            let hidden_name = self.hidden_array_access_reference_object_name(&object);
            caller_scope.write_static(&hidden_name, Value::Object(object.clone()));
            return self.evaluate_by_value_array_access_reference_argument_for_object(
                object,
                hidden_name,
                keys,
                arg.span(),
                caller_scope,
            );
        }

        Ok(None)
    }

    fn evaluate_by_value_array_access_reference_argument_for_object(
        &mut self,
        object: PhpObject,
        object_name: String,
        keys: Vec<ArrayKey>,
        span: Span,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(Value, ReferenceBindingTarget)>> {
        let Some((class_id, class_name, resolved_method_name, visibility, is_static)) =
            self.resolve_instance_method(object.class_id(), "offsetGet")
        else {
            return Ok(None);
        };
        if is_static || visibility != Visibility::Public {
            return Ok(None);
        }

        let function = self.method_function(class_id, &class_name, &resolved_method_name, span)?;
        let function = function.as_ref();
        if function.returns_by_reference {
            let (alias, value) = self.evaluate_array_access_reference_source_alias_for_object(
                object,
                object_name,
                keys,
                None,
                span,
                caller_scope,
            )?;
            return Ok(Some((value, ReferenceBindingTarget::ArrayOffset(alias))));
        }
        ensure_user_function_arity(function, 1, span)?;
        ensure_supported_magic_array_access_function_signature(function, 1, span)?;
        self.ensure_user_function_call_depth(function, span)?;

        let Some((first_key, rest_keys)) = keys.split_first() else {
            return Ok(None);
        };
        let called_class_id = object.class_id();
        let (first_value, first_source) = self.call_user_function_with_this_and_array_copy_source(
            function,
            object,
            vec![Self::array_key_value(Some(first_key.clone()))],
            Some(class_id),
            Some(called_class_id),
            caller_scope,
        )?;

        if let Value::Object(nested_object) = &first_value {
            if self
                .classes
                .implements_interface(nested_object.class_id(), "ArrayAccess")
            {
                if rest_keys.is_empty() {
                    let target = Self::detached_reference_argument_target(
                        first_value.clone(),
                        None,
                        "<ArrayAccess value>",
                    );
                    return Ok(Some((first_value, target)));
                }
                let hidden_name = self.hidden_array_access_reference_object_name(nested_object);
                caller_scope.write_static(&hidden_name, Value::Object(nested_object.clone()));
                return self.evaluate_by_value_array_access_reference_argument_for_object(
                    nested_object.clone(),
                    hidden_name,
                    rest_keys.to_vec(),
                    span,
                    caller_scope,
                );
            }
        }

        self.emit_array_access_indirect_modification_notice(&class_name, span)?;

        if !rest_keys.is_empty() {
            self.reject_by_value_array_access_scalar_parent_for_nested_write(
                &first_value,
                rest_keys,
                false,
                span,
            )?;
        }

        let (value, source) = if rest_keys.is_empty() {
            (first_value, first_source)
        } else if let Value::Array(array) = first_value {
            let value = Self::detached_array_copy_reference_source_value(array, rest_keys);
            let source = first_source
                .and_then(|source| Self::array_copy_source_with_suffix(source, rest_keys, &value));
            (value, source)
        } else {
            (Value::Null, None)
        };
        let source = if matches!(value, Value::Array(_)) {
            source
        } else {
            None
        };
        let value = caller_scope.value_with_object_property_aliases_from_array_copy(
            value,
            source.clone(),
            true,
        );
        let target =
            Self::detached_reference_argument_target(value.clone(), source, "<ArrayAccess value>");
        Ok(Some((value, target)))
    }

    fn array_copy_source_with_suffix(
        mut source: ArrayCopySource,
        suffix: &[ArrayKey],
        value: &Value,
    ) -> Option<ArrayCopySource> {
        if !matches!(value, Value::Array(_)) {
            return None;
        }
        source.keys.extend(suffix.iter().cloned());
        source.include_exact_path = false;
        Some(source)
    }

    fn evaluate_direct_array_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let Expr::Index { target, index, .. } = arg else {
            return Ok(None);
        };
        let Some((name, indices)) = Self::collect_direct_variable_array_index_path(target, index)
        else {
            return Ok(None);
        };

        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, caller_scope))
            .collect::<CompileResult<Vec<_>>>()?;

        if let Some(binding) = self.evaluate_direct_array_access_reference_source_binding(
            name,
            keys.clone(),
            arg.span(),
            caller_scope,
        )? {
            return self
                .array_offset_alias_from_reference_source_binding(binding, arg.span(), caller_scope)
                .map(Some);
        }

        if let Some((alias, value)) = self.evaluate_direct_array_access_reference_source_alias(
            name,
            keys.clone(),
            arg.span(),
            caller_scope,
        )? {
            return Ok(Some((alias, value)));
        }

        let alias = if name == "GLOBALS" {
            let (global_name, keys) = SymbolTable::split_globals_reference_path(keys, arg.span())?;
            ArrayOffsetAlias {
                root: ArrayOffsetAliasRoot::GlobalArray { name: global_name },
                keys,
            }
        } else {
            ArrayOffsetAlias {
                root: ArrayOffsetAliasRoot::StaticArray {
                    name: name.to_string(),
                },
                keys,
            }
        };
        caller_scope.materialize_array_offset_alias(&alias, arg.span())?;
        let value = caller_scope
            .read_array_offset_alias(&alias)
            .ok_or_else(|| {
                runtime_error(
                    arg.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind missing array offset reference argument".to_string(),
                    ),
                )
            })?;
        Ok(Some((alias, value)))
    }

    fn evaluate_append_array_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let Expr::AppendIndex { target, span } = arg else {
            return Ok(None);
        };
        let Some(source) = Self::append_reference_source_from_argument_target(target, *span) else {
            return Ok(None);
        };
        self.evaluate_append_reference_source_alias(&source, *span, caller_scope)
    }

    fn append_reference_source_from_argument_target(
        target: &Expr,
        span: Span,
    ) -> Option<ReferenceSource> {
        match target {
            Expr::Variable(name, _) => Some(ReferenceSource::ArrayAppend {
                name: name.clone(),
                indices: Vec::new(),
                span,
            }),
            Expr::Index { target, index, .. } => {
                if let Some((object, property, indices)) =
                    Self::collect_direct_dynamic_object_property_array_index_path(target, index)
                {
                    return Some(ReferenceSource::DynamicObjectPropertyArrayAppend {
                        object: object.to_string(),
                        property: property.clone(),
                        indices: Self::owned_exprs(indices),
                        span,
                    });
                }
                if let Some((object, property, indices)) =
                    Self::collect_direct_object_property_array_index_path(target, index)
                {
                    return Some(ReferenceSource::ObjectPropertyArrayAppend {
                        object: object.to_string(),
                        property: property.to_string(),
                        indices: Self::owned_exprs(indices),
                        span,
                    });
                }
                if let Some((holder, property, indices)) =
                    Self::collect_dynamic_object_property_array_index_path(target, index)
                {
                    return Some(ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
                        holder: holder.clone(),
                        property: property.clone(),
                        indices: Self::owned_exprs(indices),
                        span,
                    });
                }
                if let Some((holder, property, indices)) =
                    Self::collect_object_property_array_index_path(target, index)
                {
                    return Some(ReferenceSource::NonDirectObjectPropertyArrayAppend {
                        holder: holder.clone(),
                        property: property.to_string(),
                        indices: Self::owned_exprs(indices),
                        span,
                    });
                }
                if let Some((name, indices)) =
                    Self::collect_direct_variable_array_index_path(target, index)
                {
                    return Some(ReferenceSource::ArrayAppend {
                        name: name.to_string(),
                        indices: Self::owned_exprs(indices),
                        span,
                    });
                }
                let (target, indices) = Self::collect_array_index_path(target, index);
                Some(ReferenceSource::ExpressionArrayAppend {
                    target: target.clone(),
                    indices: Self::owned_exprs(indices),
                    span,
                })
            }
            Expr::Property {
                target, property, ..
            } => {
                if let Expr::Variable(object, _) = target.as_ref() {
                    Some(ReferenceSource::ObjectPropertyArrayAppend {
                        object: object.clone(),
                        property: property.clone(),
                        indices: Vec::new(),
                        span,
                    })
                } else {
                    Some(ReferenceSource::NonDirectObjectPropertyArrayAppend {
                        holder: target.as_ref().clone(),
                        property: property.clone(),
                        indices: Vec::new(),
                        span,
                    })
                }
            }
            Expr::DynamicProperty {
                target, property, ..
            } => {
                if let Expr::Variable(object, _) = target.as_ref() {
                    Some(ReferenceSource::DynamicObjectPropertyArrayAppend {
                        object: object.clone(),
                        property: property.as_ref().clone(),
                        indices: Vec::new(),
                        span,
                    })
                } else {
                    Some(ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
                        holder: target.as_ref().clone(),
                        property: property.as_ref().clone(),
                        indices: Vec::new(),
                        span,
                    })
                }
            }
            _ => Some(ReferenceSource::ExpressionArrayAppend {
                target: target.clone(),
                indices: Vec::new(),
                span,
            }),
        }
    }

    fn owned_exprs(exprs: Vec<&Expr>) -> Vec<Expr> {
        exprs.into_iter().cloned().collect()
    }

    fn evaluate_visible_object_property_array_reference_argument(
        &mut self,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        allow_non_direct_magic_get: bool,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        if let Some((object, property, indices)) =
            Self::direct_object_property_array_argument_parts(arg)
        {
            return self.evaluate_object_property_array_reference_argument(
                object,
                property,
                indices,
                arg,
                caller_scope,
                true,
            );
        }

        if let Some((object, property, indices)) =
            Self::dynamic_object_property_array_argument_parts(arg)
        {
            let property =
                self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
            return self.evaluate_object_property_array_reference_argument(
                object,
                property,
                indices,
                arg,
                caller_scope,
                false,
            );
        }

        let Expr::Index { target, index, .. } = arg else {
            return Ok(None);
        };

        if let Some((holder, property, indices)) =
            Self::collect_object_property_array_index_path(target, index)
        {
            return self.evaluate_non_direct_holder_object_property_array_reference_argument(
                holder,
                property,
                indices,
                arg,
                caller_scope,
                allow_non_direct_magic_get,
            );
        }

        if let Some((holder, property, indices)) =
            Self::collect_dynamic_object_property_array_index_path(target, index)
        {
            let property =
                self.evaluate_dynamic_property_name(property, arg.span(), caller_scope)?;
            return self.evaluate_non_direct_holder_object_property_array_reference_argument(
                holder,
                &property,
                indices,
                arg,
                caller_scope,
                allow_non_direct_magic_get,
            );
        }

        Ok(None)
    }

    fn evaluate_non_direct_holder_object_property_array_reference_argument(
        &mut self,
        holder: &Expr,
        property: &str,
        indices: Vec<&Expr>,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        allow_magic_get: bool,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let holder_value = self.evaluate(holder, caller_scope)?;
        let holder_object = match holder_value {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };

        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, caller_scope))
            .collect::<CompileResult<Vec<_>>>()?;
        let temp_name = self.next_foreach_temporary_array_name();
        caller_scope.write_static(&temp_name, Value::Object(holder_object));
        if allow_magic_get {
            if let Some(alias) = self.evaluate_magic_get_array_reference_source_alias(
                &temp_name,
                property,
                keys.clone(),
                arg.span(),
                caller_scope,
            )? {
                return Ok(Some(alias));
            }
        }

        self.evaluate_object_property_array_reference_argument_with_keys(
            temp_name,
            property.to_string(),
            keys,
            arg,
            caller_scope,
            true,
        )
    }

    fn evaluate_object_property_array_reference_argument(
        &mut self,
        object: String,
        property: String,
        indices: Vec<&Expr>,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        allow_plain_property_array: bool,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let keys = indices
            .iter()
            .map(|index| self.evaluate_array_key(index, caller_scope))
            .collect::<CompileResult<Vec<_>>>()?;
        self.evaluate_object_property_array_reference_argument_with_keys(
            object,
            property,
            keys,
            arg,
            caller_scope,
            allow_plain_property_array,
        )
    }

    fn evaluate_object_property_array_reference_argument_with_keys(
        &mut self,
        object: String,
        property: String,
        keys: Vec<ArrayKey>,
        arg: &Expr,
        caller_scope: &mut SymbolTable,
        allow_plain_property_array: bool,
    ) -> CompileResult<Option<(ArrayOffsetAlias, Value)>> {
        let (current_class_id, protected_class_ids) = self.current_property_access_context();
        let object_value = caller_scope.read_static(&object, arg.span())?;
        let object_handle = match object_value {
            Value::Object(object) => object,
            other => {
                return Err(runtime_error(
                    arg.span(),
                    RuntimeError::invalid_property_access(format!(
                        "cannot read property ${property} on {}",
                        other.type_name()
                    )),
                ));
            }
        };
        let visibility = object_handle
            .property_visibility_from_context(&property, current_class_id, &protected_class_ids)
            .map_err(|error| runtime_error(arg.span(), error))?;
        if let Ok(Value::Object(array_access_object)) = object_handle.read_property_from_context(
            &property,
            current_class_id,
            &protected_class_ids,
        ) {
            if self
                .classes
                .implements_interface(array_access_object.class_id(), "ArrayAccess")
            {
                let hidden_name =
                    self.hidden_array_access_reference_object_name(&array_access_object);
                caller_scope.write_static(&hidden_name, Value::Object(array_access_object.clone()));
                let Some(binding) = self
                    .evaluate_array_access_reference_source_binding_for_object(
                        array_access_object,
                        hidden_name,
                        keys,
                        None,
                        arg.span(),
                        caller_scope,
                    )?
                else {
                    return Ok(None);
                };
                return self
                    .array_offset_alias_from_reference_source_binding(
                        binding,
                        arg.span(),
                        caller_scope,
                    )
                    .map(Some);
            }
        }
        if !allow_plain_property_array {
            return Ok(None);
        }
        let root = if visibility == Visibility::Public {
            ArrayOffsetAliasRoot::PublicObjectProperty { object, property }
        } else {
            ArrayOffsetAliasRoot::ContextObjectProperty {
                object,
                property,
                current_class_id,
                protected_class_ids,
            }
        };
        let alias = ArrayOffsetAlias { root, keys };
        caller_scope.materialize_array_offset_alias(&alias, arg.span())?;
        let value = caller_scope
            .read_array_offset_alias(&alias)
            .ok_or_else(|| {
                runtime_error(
                    arg.span(),
                    RuntimeError::invalid_array_access(
                        "cannot bind missing object-property array offset".to_string(),
                    ),
                )
            })?;
        Ok(Some((alias, value)))
    }

    fn direct_object_property_array_argument_parts(
        expr: &Expr,
    ) -> Option<(String, String, Vec<&Expr>)> {
        let mut indices = Vec::new();
        let mut current = expr;
        while let Expr::Index { target, index, .. } = current {
            indices.push(index.as_ref());
            current = target.as_ref();
        }
        if indices.is_empty() {
            return None;
        }
        indices.reverse();

        let Expr::Property {
            target, property, ..
        } = current
        else {
            return None;
        };
        let Expr::Variable(object, _) = target.as_ref() else {
            return None;
        };
        Some((object.clone(), property.clone(), indices))
    }

    fn dynamic_object_property_array_argument_parts(
        expr: &Expr,
    ) -> Option<(String, &Expr, Vec<&Expr>)> {
        let mut indices = Vec::new();
        let mut current = expr;
        while let Expr::Index { target, index, .. } = current {
            indices.push(index.as_ref());
            current = target.as_ref();
        }
        if indices.is_empty() {
            return None;
        }
        indices.reverse();

        let Expr::DynamicProperty {
            target, property, ..
        } = current
        else {
            return None;
        };
        let Expr::Variable(object, _) = target.as_ref() else {
            return None;
        };
        Some((object.clone(), property.as_ref(), indices))
    }

    fn write_back_reference_bindings(
        &mut self,
        array_offset_binding_cells: &[(String, Vec<ArrayOffsetAlias>, VariableCell, bool)],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<()> {
        for (param_name, aliases, original_cell, had_existing_reference) in
            array_offset_binding_cells
        {
            let value = match local_scope.read_cell(param_name) {
                Some(local_cell) if local_cell.shares_reference_with(original_cell) => {
                    local_scope.read_named(param_name).unwrap_or(Value::Null)
                }
                _ => original_cell.value_cloned(),
            };
            let reference_escaped =
                local_scope.reference_cell_is_captured_by_object_property(original_cell);
            if reference_escaped {
                self.write_back_array_offset_aliases_reference_cell(
                    aliases,
                    original_cell.clone(),
                    caller_scope,
                    span,
                )?;
            } else {
                self.write_back_array_offset_aliases(aliases, value, caller_scope, span)?;
            }
            if !had_existing_reference && !reference_escaped {
                caller_scope.demote_array_offset_aliases_to_value_slots(aliases, span)?;
            }
        }
        Ok(())
    }

    fn write_back_by_value_array_copy_aliases(
        &mut self,
        alias_writebacks: &[(String, Vec<ArrayKey>, Vec<ArrayOffsetAlias>)],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<()> {
        for (source_name, source_keys, local_aliases) in alias_writebacks {
            for local_alias in local_aliases {
                let ArrayOffsetAliasRoot::StaticArray { name: local_name } = &local_alias.root
                else {
                    continue;
                };
                if local_alias.keys.is_empty() {
                    continue;
                }
                let value = if let Some(value) =
                    local_scope.detached_static_array_offset_value(local_name, &local_alias.keys)
                {
                    Some(value)
                } else {
                    match local_scope.array_offset_alias_group_for_stored_array_path(
                        local_name,
                        &local_alias.keys,
                    ) {
                        Some(active_local_aliases)
                            if active_local_aliases.contains(local_alias) =>
                        {
                            local_scope.read_array_offset_alias(local_alias)
                        }
                        _ => local_scope
                            .read_storage_named(local_name)
                            .and_then(|value| Self::array_path_value(&value, &local_alias.keys)),
                    }
                };
                let Some(value) = value else {
                    continue;
                };
                let local_reference = match local_scope
                    .array_offset_alias_group_for_stored_array_path(local_name, &local_alias.keys)
                {
                    Some(active_local_aliases) if active_local_aliases.contains(local_alias) => {
                        active_local_aliases.iter().find_map(|alias| {
                            local_scope.read_array_offset_alias_reference_cell(alias)
                        })
                    }
                    _ => None,
                };
                let mut caller_keys = source_keys.clone();
                caller_keys.extend(local_alias.keys.iter().cloned());
                let Some(caller_aliases) = caller_scope
                    .array_offset_alias_group_for_stored_array_path(source_name, &caller_keys)
                else {
                    continue;
                };
                if let Some(reference) = local_reference {
                    self.write_back_array_offset_aliases_reference_cell(
                        &caller_aliases,
                        reference,
                        caller_scope,
                        span,
                    )?;
                } else {
                    self.write_back_array_offset_aliases(
                        &caller_aliases,
                        value,
                        caller_scope,
                        span,
                    )?;
                }
            }
        }
        Ok(())
    }

    fn write_back_array_copy_source_aliases(
        &mut self,
        alias_writebacks: &[ArrayCopySourceAliasWriteback],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<()> {
        for (local_name, local_prefix_keys, source, local_aliases) in alias_writebacks {
            for local_alias in local_aliases {
                let ArrayOffsetAliasRoot::StaticArray { name } = &local_alias.root else {
                    continue;
                };
                if name != local_name
                    || local_alias.keys.is_empty()
                    || !local_alias.keys.starts_with(local_prefix_keys)
                    || local_alias.keys.len() <= local_prefix_keys.len()
                {
                    continue;
                }
                let (value, local_reference) = if let Some(value) =
                    local_scope.detached_static_array_offset_value(local_name, &local_alias.keys)
                {
                    (Some(value), None)
                } else {
                    let Some(active_local_aliases) = local_scope
                        .array_offset_alias_group_for_stored_array_path(
                            local_name,
                            &local_alias.keys,
                        )
                    else {
                        continue;
                    };
                    if !active_local_aliases.contains(local_alias) {
                        continue;
                    }
                    let local_reference = active_local_aliases.iter().find_map(|alias| {
                        local_scope.read_array_offset_alias_reference_cell(alias)
                    });
                    let value = local_scope
                        .read_storage_named(local_name)
                        .and_then(|value| Self::array_path_value(&value, &local_alias.keys));
                    (value, local_reference)
                };
                let Some(value) = value else { continue };

                for source_handle in
                    caller_scope.runtime_alias_lvalue_handles_for_array_copy_source(source)
                {
                    let mut source_keys = source.keys.clone();
                    source_keys.extend(local_alias.keys[local_prefix_keys.len()..].iter().cloned());
                    if local_scope.array_copy_source_path_was_detached(source, &source_keys) {
                        continue;
                    }
                    let source_alias = ArrayOffsetAlias {
                        root: source_handle.root,
                        keys: source_keys,
                    };
                    let Some(caller_aliases) = caller_scope
                        .array_offset_alias_group_for_stored_root_path(source_alias, None)
                    else {
                        continue;
                    };
                    let caller_aliases = caller_aliases
                        .into_iter()
                        .filter(|alias| match &alias.root {
                            ArrayOffsetAliasRoot::StaticArray { name } => {
                                caller_scope.read_storage_named(name).is_some()
                            }
                            ArrayOffsetAliasRoot::GlobalArray { .. }
                            | ArrayOffsetAliasRoot::PublicObjectProperty { .. }
                            | ArrayOffsetAliasRoot::ContextObjectProperty { .. } => true,
                        })
                        .collect::<Vec<_>>();
                    if caller_aliases.is_empty() {
                        continue;
                    }
                    if let Some(reference) = local_reference.clone() {
                        self.write_back_array_offset_aliases_reference_cell(
                            &caller_aliases,
                            reference,
                            caller_scope,
                            span,
                        )?;
                    } else {
                        self.write_back_array_offset_aliases(
                            &caller_aliases,
                            value.clone(),
                            caller_scope,
                            span,
                        )?;
                    }
                }
            }
        }
        Ok(())
    }

    fn sync_reference_binding_array_copy_source_metadata(
        &mut self,
        reference_bindings: &[ReferenceBinding],
        by_value_array_copy_source_bindings: &[ArrayCopySourceBinding],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
    ) {
        for binding in reference_bindings {
            let has_imported_source = by_value_array_copy_source_bindings
                .iter()
                .any(|(param_name, _, _)| param_name == &binding.param_name)
                || matches!(
                    binding.target,
                    ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { .. }
                        | ReferenceBindingTarget::CallerCellWithArrayCopySource { .. }
                );
            if !has_imported_source
                || local_scope
                    .public_or_dirty_object_property_array_copy_source_for_static(
                        &binding.param_name,
                    )
                    .is_some()
            {
                continue;
            }

            match &binding.target {
                ReferenceBindingTarget::CallerCell { name, .. } => {
                    caller_scope.remove_public_object_property_array_copy_source(name);
                }
                ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { name, .. } => {
                    caller_scope.remove_public_object_property_array_copy_source(name);
                }
                ReferenceBindingTarget::CallerCellWithArrayCopySource {
                    object, property, ..
                } => {
                    caller_scope.remove_object_property_array_copy_source_paths(object, property);
                }
                ReferenceBindingTarget::ValueWithArrayCopySource { .. } => {}
                ReferenceBindingTarget::ValueWithArrayCopySourceAtPath { .. } => {}
                ReferenceBindingTarget::ValueCopy => {}
                ReferenceBindingTarget::ReferenceReturnCell { .. } => {}
                ReferenceBindingTarget::ArrayOffset(_)
                | ReferenceBindingTarget::ArrayOffsets(_) => {}
            }
        }
    }

    fn sync_reference_binding_array_literal_copy_source_paths(
        reference_bindings: &[ReferenceBinding],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
    ) {
        for binding in reference_bindings {
            if !local_scope
                .dirty_array_literal_copy_source_roots
                .contains(&binding.param_name)
                && !local_scope
                    .array_literal_copy_source_paths
                    .contains_key(&binding.param_name)
            {
                continue;
            }

            let portable_paths = local_scope
                .array_literal_copy_source_paths
                .get(&binding.param_name)
                .map(|paths| {
                    paths
                        .iter()
                        .filter_map(|(keys, source)| {
                            SymbolTable::portable_array_copy_source_from_scope(source, local_scope)
                                .map(|source| (keys.clone(), source))
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            match &binding.target {
                ReferenceBindingTarget::CallerCell { name, .. } => {
                    caller_scope.record_array_literal_copy_source_paths(name, portable_paths);
                }
                ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { name, .. } => {
                    caller_scope.record_array_literal_copy_source_paths(name, portable_paths);
                }
                ReferenceBindingTarget::CallerCellWithArrayCopySource {
                    object, property, ..
                } => {
                    caller_scope.record_object_property_array_copy_source_paths(
                        object,
                        property,
                        portable_paths,
                    );
                }
                ReferenceBindingTarget::ValueWithArrayCopySource { .. }
                | ReferenceBindingTarget::ValueWithArrayCopySourceAtPath { .. }
                | ReferenceBindingTarget::ValueCopy
                | ReferenceBindingTarget::ReferenceReturnCell { .. }
                | ReferenceBindingTarget::ArrayOffset(_)
                | ReferenceBindingTarget::ArrayOffsets(_) => {}
            }
        }
    }

    fn detach_reference_binding_array_copy_source_aliases(
        &mut self,
        reference_bindings: &[ReferenceBinding],
        by_value_array_copy_source_bindings: &[ArrayCopySourceBinding],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
    ) {
        for binding in reference_bindings {
            let has_imported_source = by_value_array_copy_source_bindings
                .iter()
                .any(|(param_name, _, _)| param_name == &binding.param_name)
                || matches!(
                    binding.target,
                    ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { .. }
                        | ReferenceBindingTarget::CallerCellWithArrayCopySource { .. }
                );
            if !has_imported_source {
                continue;
            }

            let detached_paths =
                local_scope.detached_static_array_offset_values_for_root(&binding.param_name);
            if detached_paths.is_empty() {
                continue;
            }

            match &binding.target {
                ReferenceBindingTarget::CallerCell { name, .. } => {
                    caller_scope.detach_static_array_offset_alias_paths(name, &detached_paths);
                }
                ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { name, .. } => {
                    caller_scope.detach_static_array_offset_alias_paths(name, &detached_paths);
                }
                ReferenceBindingTarget::CallerCellWithArrayCopySource {
                    object, property, ..
                } => {
                    caller_scope.detach_object_property_array_offset_alias_paths(
                        object,
                        property,
                        &detached_paths,
                    );
                }
                ReferenceBindingTarget::ValueWithArrayCopySource { .. } => {}
                ReferenceBindingTarget::ValueWithArrayCopySourceAtPath { .. } => {}
                ReferenceBindingTarget::ValueCopy => {}
                ReferenceBindingTarget::ReferenceReturnCell { .. } => {}
                ReferenceBindingTarget::ArrayOffset(_)
                | ReferenceBindingTarget::ArrayOffsets(_) => {}
            }
        }
    }

    fn write_back_detached_object_property_array_offset_aliases(
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
    ) {
        let mut groups: Vec<(PhpObject, String, Vec<(Vec<ArrayKey>, VariableCell)>)> = Vec::new();
        for (object, property, keys, cell) in
            local_scope.detached_object_property_array_offset_values()
        {
            if let Some((_, _, paths)) =
                groups
                    .iter_mut()
                    .find(|(candidate_object, candidate_property, _)| {
                        candidate_object == &object && candidate_property == &property
                    })
            {
                paths.push((keys, cell));
            } else {
                groups.push((object, property, vec![(keys, cell)]));
            }
        }

        for (object, property, paths) in groups {
            caller_scope
                .detach_object_property_array_offset_alias_path_cells(&object, &property, &paths);
        }
    }

    fn write_back_reference_parameter_object_aliases(
        &mut self,
        reference_bindings: &[ReferenceBinding],
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        this_object: Option<&PhpObject>,
        span: Span,
    ) -> CompileResult<()> {
        for binding in reference_bindings {
            let caller_name = match &binding.target {
                ReferenceBindingTarget::CallerCell { name, .. }
                | ReferenceBindingTarget::CallerCellWithStaticArrayCopySource { name, .. } => name,
                _ => continue,
            };
            let Some(aliases) = local_scope.array_offset_aliases_for_name(&binding.param_name)
            else {
                continue;
            };

            for alias in aliases {
                let Some(translated_alias) = self.translate_local_object_alias_to_caller(
                    alias,
                    local_scope,
                    caller_scope,
                    this_object,
                ) else {
                    continue;
                };
                caller_scope.bind_array_offset_alias_root_to_static_source(
                    translated_alias,
                    caller_name,
                    span,
                )?;
            }
        }

        Ok(())
    }

    fn translate_local_object_alias_to_caller(
        &self,
        alias: ArrayOffsetAlias,
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        this_object: Option<&PhpObject>,
    ) -> Option<ArrayOffsetAlias> {
        match alias.root {
            ArrayOffsetAliasRoot::PublicObjectProperty { object, property } => {
                let object =
                    self.caller_object_alias_name(&object, local_scope, caller_scope, this_object)?;
                Some(ArrayOffsetAlias {
                    root: ArrayOffsetAliasRoot::PublicObjectProperty { object, property },
                    keys: alias.keys,
                })
            }
            ArrayOffsetAliasRoot::ContextObjectProperty {
                object,
                property,
                current_class_id,
                protected_class_ids,
            } => {
                let object =
                    self.caller_object_alias_name(&object, local_scope, caller_scope, this_object)?;
                Some(ArrayOffsetAlias {
                    root: ArrayOffsetAliasRoot::ContextObjectProperty {
                        object,
                        property,
                        current_class_id,
                        protected_class_ids,
                    },
                    keys: alias.keys,
                })
            }
            _ => None,
        }
    }

    fn caller_object_alias_name(
        &self,
        local_object_name: &str,
        local_scope: &SymbolTable,
        caller_scope: &mut SymbolTable,
        this_object: Option<&PhpObject>,
    ) -> Option<String> {
        let object = if local_object_name == "this" {
            this_object?.clone()
        } else {
            match local_scope.read_named(local_object_name)? {
                Value::Object(object) => object,
                _ => return None,
            }
        };

        caller_scope
            .object_names_for_value(&object)
            .into_iter()
            .next()
            .or_else(|| {
                let hidden_name = self.hidden_array_access_reference_object_name(&object);
                caller_scope.write_static(&hidden_name, Value::Object(object));
                Some(hidden_name)
            })
    }

    fn write_back_array_offset_aliases(
        &mut self,
        aliases: &[ArrayOffsetAlias],
        value: Value,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<()> {
        let retained_static_copy_sources = scope.retained_static_copy_sources_for_aliases(aliases);
        if !scope.write_array_offset_aliases_checked_with_object_type_resolver(
            aliases,
            value,
            span,
            &|object, type_name| self.object_satisfies_live_property_type(object, type_name),
        )? {
            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot write array reference argument".to_string(),
                ),
            ));
        }
        for alias in aliases {
            match &alias.root {
                ArrayOffsetAliasRoot::StaticArray { name } => {
                    scope.sync_array_offset_aliases_for_static_root(name);
                }
                ArrayOffsetAliasRoot::GlobalArray { name } => {
                    scope.sync_array_offset_aliases_for_global_root(name);
                }
                ArrayOffsetAliasRoot::PublicObjectProperty { object, property }
                | ArrayOffsetAliasRoot::ContextObjectProperty {
                    object, property, ..
                } => {
                    scope.sync_array_offset_aliases_for_object_property_root(object, property);
                }
            }
        }
        scope.restore_retained_static_copy_sources(retained_static_copy_sources);
        Ok(())
    }

    fn write_back_array_offset_aliases_reference_cell(
        &mut self,
        aliases: &[ArrayOffsetAlias],
        reference: VariableCell,
        scope: &mut SymbolTable,
        span: Span,
    ) -> CompileResult<()> {
        if !scope.write_array_offset_aliases_reference_cell_preserving_static_copy_sources(
            aliases, reference,
        ) {
            return Err(runtime_error(
                span,
                RuntimeError::invalid_array_access(
                    "cannot write array reference argument".to_string(),
                ),
            ));
        }
        scope.sync_alias_roots(aliases);
        Ok(())
    }

    fn array_offset_aliases_with_suffix(
        aliases: &[ArrayOffsetAlias],
        keys: &[ArrayKey],
    ) -> Vec<ArrayOffsetAlias> {
        aliases
            .iter()
            .map(|alias| {
                let mut alias = alias.clone();
                alias.keys.extend(keys.iter().cloned());
                alias
            })
            .collect()
    }

    fn matching_array_offset_binding_cell(
        array_offset_binding_cells: &[(String, Vec<ArrayOffsetAlias>, VariableCell, bool)],
        aliases: &[ArrayOffsetAlias],
    ) -> Option<(VariableCell, bool)> {
        array_offset_binding_cells.iter().find_map(
            |(_, existing_aliases, cell, had_existing_reference)| {
                existing_aliases
                    .iter()
                    .any(|existing| aliases.iter().any(|alias| alias == existing))
                    .then(|| (cell.clone(), *had_existing_reference))
            },
        )
    }

    fn call_user_function_with_checked_values(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        reference_scope: Option<&mut SymbolTable>,
    ) -> CompileResult<Value> {
        self.call_user_function_with_checked_values_and_locals(
            function,
            args,
            this_object,
            class_context,
            called_class_context,
            reference_bindings,
            reference_scope,
            Vec::new(),
            Vec::new(),
        )
    }

    fn call_user_function_with_checked_values_and_locals(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        reference_scope: Option<&mut SymbolTable>,
        prebound_locals: Vec<PreboundLocal>,
        by_value_array_copy_bindings: Vec<(String, String, Vec<ArrayKey>)>,
    ) -> CompileResult<Value> {
        self.call_user_function_with_checked_values_and_locals_with_array_copy_source(
            function,
            args,
            this_object,
            class_context,
            called_class_context,
            reference_bindings,
            reference_scope,
            prebound_locals,
            by_value_array_copy_bindings,
        )
        .map(|(value, _)| value)
    }

    fn call_user_function_with_checked_values_and_locals_with_array_copy_source(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        reference_scope: Option<&mut SymbolTable>,
        prebound_locals: Vec<PreboundLocal>,
        by_value_array_copy_bindings: Vec<(String, String, Vec<ArrayKey>)>,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        self.call_user_function_with_checked_values_and_locals_with_array_copy_source_and_arg_sources(
            function,
            args,
            Vec::new(),
            this_object,
            class_context,
            called_class_context,
            reference_bindings,
            reference_scope,
            prebound_locals,
            by_value_array_copy_bindings,
            Vec::new(),
            None,
        )
    }

    fn call_user_function_with_call_frame(
        &mut self,
        function: &FunctionDecl,
        frame: CallFrameArgumentBindings,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_scope: Option<&mut SymbolTable>,
        prebound_locals: Vec<PreboundLocal>,
    ) -> CompileResult<Value> {
        self.call_user_function_with_call_frame_and_array_copy_source(
            function,
            frame,
            this_object,
            class_context,
            called_class_context,
            reference_scope,
            prebound_locals,
        )
        .map(|(value, _)| value)
    }

    fn call_user_function_with_call_frame_and_array_copy_source(
        &mut self,
        function: &FunctionDecl,
        frame: CallFrameArgumentBindings,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_scope: Option<&mut SymbolTable>,
        prebound_locals: Vec<PreboundLocal>,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        self.call_user_function_with_checked_values_and_locals_with_array_copy_source_and_arg_sources(
            function,
            frame.values,
            frame.argument_keys,
            this_object,
            class_context,
            called_class_context,
            frame.reference_bindings,
            reference_scope,
            prebound_locals,
            frame.by_value_array_copy_bindings,
            frame.array_copy_source_bindings,
            None,
        )
    }

    fn call_user_function_with_checked_values_and_locals_with_array_copy_source_and_arg_sources(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        argument_keys: Vec<Option<ArrayKey>>,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        reference_bindings: Vec<ReferenceBinding>,
        mut reference_scope: Option<&mut SymbolTable>,
        prebound_locals: Vec<PreboundLocal>,
        by_value_array_copy_bindings: Vec<(String, String, Vec<ArrayKey>)>,
        by_value_array_copy_source_bindings: Vec<ArrayCopySourceBinding>,
        active_debug_frame: Option<PendingUncaughtCallFrame>,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        if self.exit_signal.is_some() {
            return Ok((Value::Null, None));
        }
        let args =
            self.coerce_call_frame_values(function, args, class_context, called_class_context)?;
        self.function_context
            .push(self.function_context_name(function));
        if let Some(class_context) = class_context {
            self.class_context.push(class_context);
        }
        if let Some(called_class_context) = called_class_context {
            self.called_class_context.push(called_class_context);
        }
        self.emit_deprecated_attribute_call_diagnostic(
            function,
            this_object.as_ref(),
            class_context,
        )?;
        let mut local_scope = SymbolTable::new_child(self.global_symbols.clone());
        let this_object_for_alias_transfer = this_object.clone();
        if let Some(this_object) = this_object.as_ref() {
            local_scope.write_static("this", Value::Object(this_object.clone()));
            if let Some(source_scope) = reference_scope.as_deref() {
                local_scope.import_public_object_property_aliases_for_object_value(
                    "this",
                    this_object,
                    source_scope,
                );
            }
        }
        let mut captured_array_offset_binding_cells = Vec::new();
        let mut by_value_array_copy_alias_writebacks: Vec<(
            String,
            Vec<ArrayKey>,
            Vec<ArrayOffsetAlias>,
        )> = Vec::new();
        let mut array_copy_source_alias_writebacks: Vec<ArrayCopySourceAliasWriteback> = Vec::new();
        for local in prebound_locals {
            match local {
                PreboundLocal::Value { name, value } => local_scope.write_static(&name, value),
                PreboundLocal::ValueWithArrayCopySource {
                    name,
                    value,
                    source,
                    source_scope,
                } => {
                    let source_was_dirty = source_scope.array_copy_source_was_dirtied(&source);
                    local_scope.write_static(&name, value);
                    local_scope.import_array_copy_source_aliases_from_copy(
                        &name,
                        &source,
                        &source_scope,
                    );
                    local_scope.mirror_array_copy_source_aliases_from_copy(&name, &source);
                    local_scope.record_public_object_property_array_copy_source(&name, source);
                    if source_was_dirty {
                        local_scope.mark_public_object_property_array_copy_source_dirty(&name);
                    }
                }
                PreboundLocal::Cell { name, cell } => local_scope.bind_static_to_cell(&name, cell),
                PreboundLocal::CellWithArrayCopySource {
                    name,
                    cell,
                    source,
                    source_scope,
                } => {
                    let source_was_dirty = source_scope.array_copy_source_was_dirtied(&source);
                    local_scope.bind_static_to_cell(&name, cell);
                    local_scope.import_array_copy_source_aliases_from_copy(
                        &name,
                        &source,
                        &source_scope,
                    );
                    local_scope.mirror_array_copy_source_aliases_from_copy(&name, &source);
                    local_scope.record_public_object_property_array_copy_source(&name, source);
                    if source_was_dirty {
                        local_scope.mark_public_object_property_array_copy_source_dirty(&name);
                    }
                }
                PreboundLocal::ArrayOffsets {
                    name,
                    aliases,
                    mut source_scope,
                } => {
                    let cell = if let Some(cell) =
                        source_scope.reference_cell_for_array_offset_alias_group(&aliases)
                    {
                        local_scope.bind_static_to_cell(&name, cell.clone());
                        Some(cell)
                    } else {
                        let value = aliases
                            .first()
                            .and_then(|alias| source_scope.read_array_offset_alias(alias))
                            .unwrap_or(Value::Null);
                        local_scope.write_static(&name, value);
                        local_scope.read_cell(&name)
                    };
                    if let Some(cell) = cell {
                        captured_array_offset_binding_cells.push((
                            name,
                            aliases,
                            cell,
                            source_scope,
                        ));
                    }
                }
            }
        }
        let mut array_offset_binding_cells = Vec::new();
        for (index, param) in function.params.iter().enumerate() {
            if param.is_variadic {
                let mut rest = PhpArray::new();
                for (rest_index, arg) in args.iter().skip(index).enumerate() {
                    match argument_keys
                        .get(index + rest_index)
                        .and_then(|key| key.as_ref())
                    {
                        Some(ArrayKey::String(name)) => {
                            rest.insert(ArrayKey::String(name.clone()), arg.clone());
                        }
                        Some(ArrayKey::Int(_)) | None => {
                            rest.append(arg.clone())
                                .map_err(|error| runtime_error(param.span, error))?;
                        }
                    }
                }
                local_scope.write_static(&param.name, Value::Array(rest));
                if let Some(source_scope) = reference_scope.as_deref() {
                    for (rest_index, arg) in args.iter().skip(index).enumerate() {
                        if !matches!(arg, Value::Array(_)) {
                            continue;
                        }
                        let target_keys = vec![argument_keys
                            .get(index + rest_index)
                            .and_then(|key| key.as_ref())
                            .cloned()
                            .unwrap_or(ArrayKey::Int(rest_index as i64))];
                        let Some((_, _, source)) = by_value_array_copy_source_bindings.iter().find(
                            |(param_name, candidate_keys, _)| {
                                param_name == &param.name && candidate_keys == &target_keys
                            },
                        ) else {
                            continue;
                        };
                        let imported_aliases = local_scope
                            .import_array_copy_source_aliases_from_copy_to_path(
                                &param.name,
                                &target_keys,
                                source,
                                source_scope,
                            );
                        let imported_aliases: Vec<_> = imported_aliases
                            .into_iter()
                            .filter(|alias| {
                                matches!(
                                    &alias.root,
                                    ArrayOffsetAliasRoot::StaticArray { name }
                                        if name == &param.name
                                ) && alias.keys.starts_with(&target_keys)
                                    && alias.keys.len() > target_keys.len()
                            })
                            .collect();
                        local_scope.record_array_literal_copy_source_path(
                            &param.name,
                            target_keys.clone(),
                            source.clone(),
                        );
                        if !imported_aliases.is_empty() {
                            array_copy_source_alias_writebacks.push((
                                param.name.clone(),
                                target_keys,
                                source.clone(),
                                imported_aliases,
                            ));
                        }
                    }
                }
                break;
            }

            if let Some(binding) = reference_bindings
                .iter()
                .find(|binding| binding.param_name == param.name)
            {
                match &binding.target {
                    ReferenceBindingTarget::CallerCell { cell, .. } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                        if let Some(source_scope) = reference_scope.as_deref() {
                            if let ReferenceBindingTarget::CallerCell { name, .. } = &binding.target
                            {
                                if let Some(paths) =
                                    SymbolTable::portable_array_literal_copy_source_paths_from_scope(
                                        name,
                                        source_scope,
                                    )
                                {
                                    local_scope
                                        .import_array_literal_copy_source_paths(&param.name, paths);
                                }
                            }
                        }
                    }
                    ReferenceBindingTarget::ReferenceReturnCell { cell } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                    }
                    ReferenceBindingTarget::CallerCellWithStaticArrayCopySource {
                        cell,
                        source,
                        source_was_dirty,
                        ..
                    }
                    | ReferenceBindingTarget::CallerCellWithArrayCopySource {
                        cell,
                        source,
                        source_was_dirty,
                        ..
                    } => {
                        local_scope.bind_static_to_cell(&param.name, cell.clone());
                        if let Some(source_scope) = reference_scope.as_deref() {
                            let imported_aliases = local_scope
                                .import_array_copy_source_aliases_from_copy(
                                    &param.name,
                                    source,
                                    source_scope,
                                );
                            let imported_aliases: Vec<_> = imported_aliases
                                .into_iter()
                                .filter(|alias| {
                                    matches!(
                                        &alias.root,
                                        ArrayOffsetAliasRoot::StaticArray { name }
                                            if name == &param.name
                                    ) && !alias.keys.is_empty()
                                })
                                .collect();
                            if !imported_aliases.is_empty() {
                                array_copy_source_alias_writebacks.push((
                                    param.name.clone(),
                                    Vec::new(),
                                    source.clone(),
                                    imported_aliases,
                                ));
                            }
                        }
                        local_scope.mirror_array_copy_source_aliases_from_copy(&param.name, source);
                        local_scope.record_public_object_property_array_copy_source(
                            &param.name,
                            source.clone(),
                        );
                        if *source_was_dirty {
                            local_scope
                                .mark_public_object_property_array_copy_source_dirty(&param.name);
                        }
                    }
                    ReferenceBindingTarget::ValueWithArrayCopySource { source } => {
                        if let Some(arg) = args.get(index) {
                            local_scope.write_static(&param.name, arg.clone());
                            if let Some(source_scope) = reference_scope.as_deref() {
                                let imported_aliases = local_scope
                                    .import_array_copy_source_aliases_from_copy(
                                        &param.name,
                                        source,
                                        source_scope,
                                    );
                                let imported_aliases: Vec<_> = imported_aliases
                                    .into_iter()
                                    .filter(|alias| {
                                        matches!(
                                            &alias.root,
                                            ArrayOffsetAliasRoot::StaticArray { name }
                                                if name == &param.name
                                        ) && !alias.keys.is_empty()
                                    })
                                    .collect();
                                if !imported_aliases.is_empty() {
                                    array_copy_source_alias_writebacks.push((
                                        param.name.clone(),
                                        Vec::new(),
                                        source.clone(),
                                        imported_aliases,
                                    ));
                                }
                            }
                            local_scope
                                .mirror_array_copy_source_aliases_from_copy(&param.name, source);
                            local_scope.record_public_object_property_array_copy_source(
                                &param.name,
                                source.clone(),
                            );
                        }
                    }
                    ReferenceBindingTarget::ValueWithArrayCopySourceAtPath { .. } => {}
                    ReferenceBindingTarget::ValueCopy => {
                        if let Some(arg) = args.get(index) {
                            local_scope.write_static(&param.name, arg.clone());
                        }
                    }
                    ReferenceBindingTarget::ArrayOffset(_) => {
                        if let Some(arg) = args.get(index) {
                            let ReferenceBindingTarget::ArrayOffset(alias) = &binding.target else {
                                unreachable!("matched array offset binding");
                            };
                            let aliases = vec![alias.clone()];
                            if let Some((cell, had_existing_reference)) =
                                Self::matching_array_offset_binding_cell(
                                    &array_offset_binding_cells,
                                    &aliases,
                                )
                            {
                                local_scope.bind_static_to_cell(&param.name, cell.clone());
                                array_offset_binding_cells.push((
                                    param.name.clone(),
                                    aliases,
                                    cell,
                                    had_existing_reference,
                                ));
                            } else {
                                let had_existing_reference =
                                    reference_scope.as_deref().is_some_and(|scope| {
                                        scope.has_bound_array_offset_alias_group(&aliases)
                                            || aliases.iter().any(|alias| {
                                                scope
                                                    .read_array_offset_alias_reference_cell(alias)
                                                    .is_some()
                                            })
                                    });
                                let bound_caller_cell =
                                    if let Some(scope) = reference_scope.as_deref_mut() {
                                        scope.reference_cell_for_array_literal_alias_group(&aliases)
                                    } else {
                                        None
                                    };
                                if let Some(cell) = bound_caller_cell {
                                    local_scope.bind_static_to_cell(&param.name, cell.clone());
                                    array_offset_binding_cells.push((
                                        param.name.clone(),
                                        aliases,
                                        cell,
                                        had_existing_reference,
                                    ));
                                } else {
                                    local_scope.write_static(&param.name, arg.clone());
                                    if let Some(cell) = local_scope.read_cell(&param.name) {
                                        array_offset_binding_cells.push((
                                            param.name.clone(),
                                            aliases,
                                            cell,
                                            false,
                                        ));
                                    }
                                }
                            }
                        }
                    }
                    ReferenceBindingTarget::ArrayOffsets(_) => {
                        if let Some(arg) = args.get(index) {
                            let ReferenceBindingTarget::ArrayOffsets(aliases) = &binding.target
                            else {
                                unreachable!("matched array offset binding list");
                            };
                            if let Some((cell, had_existing_reference)) =
                                Self::matching_array_offset_binding_cell(
                                    &array_offset_binding_cells,
                                    aliases,
                                )
                            {
                                local_scope.bind_static_to_cell(&param.name, cell.clone());
                                array_offset_binding_cells.push((
                                    param.name.clone(),
                                    aliases.clone(),
                                    cell,
                                    had_existing_reference,
                                ));
                            } else {
                                let had_existing_reference =
                                    reference_scope.as_deref().is_some_and(|scope| {
                                        scope.has_bound_array_offset_alias_group(aliases)
                                            || aliases.iter().any(|alias| {
                                                scope
                                                    .read_array_offset_alias_reference_cell(alias)
                                                    .is_some()
                                            })
                                    });
                                let bound_caller_cell =
                                    if let Some(scope) = reference_scope.as_deref_mut() {
                                        scope.reference_cell_for_array_literal_alias_group(aliases)
                                    } else {
                                        None
                                    };
                                if let Some(cell) = bound_caller_cell {
                                    local_scope.bind_static_to_cell(&param.name, cell.clone());
                                    array_offset_binding_cells.push((
                                        param.name.clone(),
                                        aliases.clone(),
                                        cell,
                                        had_existing_reference,
                                    ));
                                } else {
                                    local_scope.write_static(&param.name, arg.clone());
                                    if let Some(cell) = local_scope.read_cell(&param.name) {
                                        array_offset_binding_cells.push((
                                            param.name.clone(),
                                            aliases.clone(),
                                            cell,
                                            false,
                                        ));
                                    }
                                }
                            }
                        }
                    }
                }
                if args
                    .get(index)
                    .is_some_and(|arg| matches!(arg, Value::Array(_)))
                {
                    if let Some((_, target_keys, source)) = by_value_array_copy_source_bindings
                        .iter()
                        .find(|(param_name, target_keys, _)| {
                            param_name == &param.name && target_keys.is_empty()
                        })
                    {
                        if let Some(source_scope) = reference_scope.as_deref() {
                            let imported_aliases = local_scope
                                .import_array_copy_source_aliases_from_copy(
                                    &param.name,
                                    source,
                                    source_scope,
                                );
                            let imported_aliases: Vec<_> = imported_aliases
                                .into_iter()
                                .filter(|alias| {
                                    matches!(
                                        &alias.root,
                                        ArrayOffsetAliasRoot::StaticArray { name }
                                            if name == &param.name
                                    ) && !alias.keys.is_empty()
                                })
                                .collect();
                            if !imported_aliases.is_empty() {
                                array_copy_source_alias_writebacks.push((
                                    param.name.clone(),
                                    target_keys.clone(),
                                    source.clone(),
                                    imported_aliases,
                                ));
                            }
                        }
                        local_scope.mirror_array_copy_source_aliases_from_copy(&param.name, source);
                        local_scope.record_public_object_property_array_copy_source(
                            &param.name,
                            source.clone(),
                        );
                    }
                }
                continue;
            }

            let value = if let Some(arg) = args.get(index) {
                arg.clone()
            } else {
                let default = param
                    .default
                    .as_ref()
                    .expect("arity check ensures missing params have defaults");
                let mut default_scope = SymbolTable::new();
                match self.evaluate_constant_like_expr(default, &mut default_scope) {
                    Ok(value) => value,
                    Err(error) => {
                        self.function_context.pop();
                        if class_context.is_some() {
                            self.class_context.pop();
                        }
                        if called_class_context.is_some() {
                            self.called_class_context.pop();
                        }
                        return Err(error);
                    }
                }
            };
            let value = match self.coerce_call_argument_value(
                function,
                index,
                param,
                value,
                class_context,
                called_class_context,
            ) {
                Ok(value) => value,
                Err(error) => {
                    self.function_context.pop();
                    if class_context.is_some() {
                        self.class_context.pop();
                    }
                    if called_class_context.is_some() {
                        self.called_class_context.pop();
                    }
                    return Err(error);
                }
            };
            let direct_copy_source = by_value_array_copy_source_bindings
                .iter()
                .find(|(param_name, target_keys, _)| {
                    param_name == &param.name && target_keys.is_empty()
                })
                .map(|(_, _, source)| source.clone());
            let value_is_array = matches!(value, Value::Array(_));
            let value = if value_is_array {
                if let (Some(source_scope), Some(source)) =
                    (reference_scope.as_deref_mut(), direct_copy_source.as_ref())
                {
                    source_scope.value_with_object_property_aliases_from_array_copy(
                        value,
                        Some(source.clone()),
                        true,
                    )
                } else {
                    value
                }
            } else {
                value
            };
            local_scope.write_static(&param.name, value);
            if value_is_array {
                for (_, target_keys, source) in by_value_array_copy_source_bindings
                    .iter()
                    .filter(|(param_name, _, _)| param_name == &param.name)
                {
                    if target_keys.is_empty() {
                        if let Some(source_scope) = reference_scope.as_deref() {
                            let imported_aliases = local_scope
                                .import_array_copy_source_aliases_from_copy(
                                    &param.name,
                                    source,
                                    source_scope,
                                );
                            let imported_aliases: Vec<_> = imported_aliases
                                .into_iter()
                                .filter(|alias| {
                                    matches!(
                                        &alias.root,
                                        ArrayOffsetAliasRoot::StaticArray { name }
                                            if name == &param.name
                                    ) && !alias.keys.is_empty()
                                })
                                .collect();
                            if !imported_aliases.is_empty() {
                                array_copy_source_alias_writebacks.push((
                                    param.name.clone(),
                                    target_keys.clone(),
                                    source.clone(),
                                    imported_aliases,
                                ));
                            }
                        }
                        local_scope.record_public_object_property_array_copy_source(
                            &param.name,
                            source.clone(),
                        );
                    } else {
                        if let Some(source_scope) = reference_scope.as_deref() {
                            let imported_aliases = local_scope
                                .import_array_copy_source_aliases_from_copy_to_path(
                                    &param.name,
                                    target_keys,
                                    source,
                                    source_scope,
                                );
                            let imported_aliases: Vec<_> = imported_aliases
                                .into_iter()
                                .filter(|alias| {
                                    matches!(
                                        &alias.root,
                                        ArrayOffsetAliasRoot::StaticArray { name }
                                            if name == &param.name
                                    ) && alias.keys.starts_with(target_keys)
                                        && alias.keys.len() > target_keys.len()
                                })
                                .collect();
                            if !imported_aliases.is_empty() {
                                array_copy_source_alias_writebacks.push((
                                    param.name.clone(),
                                    target_keys.clone(),
                                    source.clone(),
                                    imported_aliases,
                                ));
                            }
                        }
                        local_scope.record_array_literal_copy_source_path(
                            &param.name,
                            target_keys.clone(),
                            source.clone(),
                        );
                    }
                }
            }
            if let Some(source_scope) = reference_scope.as_deref() {
                if let Some((_, source_name, source_keys)) = by_value_array_copy_bindings
                    .iter()
                    .find(|(param_name, _, _)| param_name == &param.name)
                {
                    let imported_aliases = local_scope
                        .import_static_array_offset_aliases_from_path_copy(
                            &param.name,
                            source_name,
                            source_keys,
                            source_scope,
                        );
                    let imported_aliases: Vec<_> = imported_aliases
                        .into_iter()
                        .filter(|alias| !alias.keys.is_empty())
                        .collect();
                    if !imported_aliases.is_empty() {
                        by_value_array_copy_alias_writebacks.push((
                            source_name.clone(),
                            source_keys.clone(),
                            imported_aliases,
                        ));
                    }
                }
                if let Some(Value::Object(object)) = local_scope.read_named(&param.name) {
                    local_scope.import_public_object_property_aliases_for_object_value(
                        &param.name,
                        &object,
                        source_scope,
                    );
                }
            }
        }

        let active_function_arguments = Self::active_function_call_arguments_for_func_get(
            function,
            &args,
            &argument_keys,
            &local_scope,
        );

        if function.is_generator {
            let result = self.create_generator_object(
                function,
                local_scope,
                this_object_for_alias_transfer,
                class_context,
                called_class_context,
                active_function_arguments,
                function.span,
            );
            self.function_context.pop();
            if class_context.is_some() {
                self.class_context.pop();
            }
            if called_class_context.is_some() {
                self.called_class_context.pop();
            }
            return result.map(|value| (value, None));
        }

        self.call_depth += 1;
        self.active_static_locals.push(Vec::new());
        self.active_symbol_roots.push(local_scope.symbols.clone());
        self.active_function_call_arguments
            .push(active_function_arguments);
        let pushed_debug_frame = if let Some(frame) = active_debug_frame {
            self.active_debug_backtrace_frames.push(frame);
            true
        } else {
            false
        };
        let flow = self.with_strict_types_scope(function.strict_types, |this| {
            this.execute_statements_with_array_copy_return_source(&function.body, &mut local_scope)
        });
        if pushed_debug_frame {
            self.active_debug_backtrace_frames.pop();
        }
        self.active_function_call_arguments.pop();
        let writeback_result = if matches!(
            &flow,
            Ok((Flow::Normal, _)) | Ok((Flow::Return(_), _)) | Ok((Flow::Exit(_), _))
        ) {
            let reference_writeback = if let Some(reference_scope) = reference_scope.as_deref_mut()
            {
                let result = self.write_back_reference_bindings(
                    &array_offset_binding_cells,
                    &local_scope,
                    reference_scope,
                    function.span,
                );
                if let Err(error) = result {
                    Err(error)
                } else {
                    let result = self.write_back_reference_parameter_object_aliases(
                        &reference_bindings,
                        &local_scope,
                        reference_scope,
                        this_object_for_alias_transfer.as_ref(),
                        function.span,
                    );
                    if let Err(error) = result {
                        Err(error)
                    } else {
                        self.detach_reference_binding_array_copy_source_aliases(
                            &reference_bindings,
                            &by_value_array_copy_source_bindings,
                            &local_scope,
                            reference_scope,
                        );
                        let result = self.write_back_by_value_array_copy_aliases(
                            &by_value_array_copy_alias_writebacks,
                            &local_scope,
                            reference_scope,
                            function.span,
                        );
                        let result = if result.is_ok() {
                            self.write_back_array_copy_source_aliases(
                                &array_copy_source_alias_writebacks,
                                &local_scope,
                                reference_scope,
                                function.span,
                            )
                        } else {
                            result
                        };
                        if result.is_ok() {
                            Self::write_back_detached_object_property_array_offset_aliases(
                                &local_scope,
                                reference_scope,
                            );
                            self.sync_reference_binding_array_copy_source_metadata(
                                &reference_bindings,
                                &by_value_array_copy_source_bindings,
                                &local_scope,
                                reference_scope,
                            );
                            Self::sync_reference_binding_array_literal_copy_source_paths(
                                &reference_bindings,
                                &local_scope,
                                reference_scope,
                            );
                            if let Some(this_object) = this_object_for_alias_transfer.as_ref() {
                                reference_scope.detach_stale_object_aliases_from_local_scope(
                                    &local_scope,
                                    this_object,
                                );
                                reference_scope
                                    .sync_array_offset_aliases_for_object_value(this_object);
                            }
                            reference_scope
                                .sync_dirty_object_property_array_copy_sources_from_scope(
                                    &local_scope,
                                );
                            reference_scope.sync_dirty_array_copy_sources_from_scope(&local_scope);
                        }
                        result
                    }
                }
            } else {
                Ok(())
            };
            if let Err(error) = reference_writeback {
                Err(error)
            } else {
                let mut result = Ok(());
                for (name, aliases, original_cell, source_scope) in
                    &mut captured_array_offset_binding_cells
                {
                    let value = match local_scope.read_cell(name) {
                        Some(local_cell) if local_cell.shares_reference_with(original_cell) => {
                            local_scope.read_named(name).unwrap_or(Value::Null)
                        }
                        _ => original_cell.value_cloned(),
                    };
                    if let Err(error) = self.write_back_array_offset_aliases(
                        aliases,
                        value,
                        source_scope,
                        function.span,
                    ) {
                        result = Err(error);
                        break;
                    }
                }
                result
            }
        } else {
            Ok(())
        };
        let static_names = self.active_static_locals.pop().unwrap_or_default();
        let function_key = function.name.to_ascii_lowercase();
        for name in static_names {
            if let Some(value) = local_scope.read_named(&name) {
                self.static_locals
                    .insert((function_key.clone(), name), value.clone());
            }
        }
        self.active_symbol_roots.pop();
        self.call_depth -= 1;
        self.function_context.pop();
        if class_context.is_some() {
            self.class_context.pop();
        }
        if called_class_context.is_some() {
            self.called_class_context.pop();
        }

        writeback_result?;
        let (flow, array_copy_source) = flow?;
        match flow {
            Flow::Normal => self
                .coerce_call_return_value(
                    function,
                    class_context,
                    called_class_context,
                    Value::Null,
                    true,
                )
                .map(|value| (value, None)),
            Flow::Break { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
            )),
            Flow::Continue { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("continue cannot be used outside a loop"),
            )),
            Flow::Return(value) => {
                let promote_reference_cells = array_copy_source
                    .as_ref()
                    .is_some_and(|source| local_scope.array_copy_source_was_dirtied(source));
                let value = reference_scope
                    .as_deref_mut()
                    .map(|scope| {
                        scope.value_with_object_property_aliases_from_array_copy(
                            value.clone(),
                            array_copy_source.clone(),
                            promote_reference_cells,
                        )
                    })
                    .unwrap_or(value);
                let value = self.coerce_call_return_value(
                    function,
                    class_context,
                    called_class_context,
                    value,
                    false,
                )?;
                let array_copy_source = if matches!(value, Value::Array(_)) {
                    array_copy_source
                } else {
                    None
                };
                Ok((value, array_copy_source))
            }
            Flow::Throw { object, span } => Err(self.uncaught_throw_error(&object, span)),
            Flow::Exit(_) => Ok((Value::Null, None)),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn create_generator_object(
        &mut self,
        function: &FunctionDecl,
        local_scope: SymbolTable,
        this_object: Option<PhpObject>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        active_function_arguments: ActiveFunctionCallArguments,
        span: Span,
    ) -> CompileResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id("Generator")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("Generator")))?;
        let object_id = self.allocate_object_id();
        let object = {
            let class = self
                .classes
                .get(class_id)
                .expect("interpreter Generator class metadata should resolve");
            PhpObject::from_class_with_relationship_metadata_with_id(
                class,
                &[],
                Vec::new(),
                vec!["Iterator".to_string()],
                object_id,
            )
        };
        self.generator_states.insert(
            object.id(),
            GeneratorState {
                function: function.clone(),
                local_scope,
                this_object,
                class_context,
                called_class_context,
                active_function_arguments,
                yields: Vec::new(),
                return_value: None,
                position: 0,
                started: false,
            },
        );
        Ok(Value::Object(object))
    }

    fn call_phpc_yield(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "yield",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }
        let key = if args.len() == 2 {
            Some(self.evaluate(&args[0], scope)?)
        } else {
            None
        };
        let value_expr = if args.len() == 2 { &args[1] } else { &args[0] };
        let value = self.evaluate(value_expr, scope)?;
        let Some(yields) = self.active_generator_yields.last_mut() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "yield",
                    "yield can only execute while a generator is being rewound in the current subset",
                ),
            ));
        };
        yields.push(PendingGeneratorYield {
            key,
            value,
            advances_auto_key: true,
        });
        Ok(Value::Null)
    }

    fn call_phpc_yield_from(
        &mut self,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if args.len() != 1 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "yield from",
                    ArityExpectation::Exactly(1),
                    args.len(),
                ),
            ));
        }

        let iterable = self.evaluate(&args[0], scope)?;
        let mut delegated = Vec::new();
        match iterable {
            Value::Array(array) => {
                for entry in array.entries() {
                    delegated.push(PendingGeneratorYield {
                        key: Some(value_from_array_key(&entry.key)),
                        value: entry.value_cloned(),
                        advances_auto_key: false,
                    });
                }
            }
            Value::Object(object) if object.class_name().eq_ignore_ascii_case("Generator") => {
                if !self
                    .generator_states
                    .get(&object.id())
                    .is_some_and(|state| state.started)
                {
                    self.rewind_generator_object(object.clone(), span)?;
                }
                let state = self.generator_states.get(&object.id()).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "yield from",
                            "generator state is missing in the current subset",
                        ),
                    )
                })?;
                for entry in &state.yields {
                    delegated.push(PendingGeneratorYield {
                        key: Some(entry.key.clone()),
                        value: entry.value.clone(),
                        advances_auto_key: false,
                    });
                }
            }
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "yield from",
                        format!(
                            "Can use \"yield from\" only with arrays and bounded Generator objects in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        }

        let Some(yields) = self.active_generator_yields.last_mut() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "yield from",
                    "yield from can only execute while a generator is being rewound in the current subset",
                ),
            ));
        };
        yields.extend(delegated);
        Ok(Value::Null)
    }

    fn call_generator_method(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: &[Expr],
        span: Span,
        scope: &mut SymbolTable,
    ) -> CompileResult<Value> {
        if method_name.eq_ignore_ascii_case("throw") {
            expect_expr_arity("Generator::throw", args.len(), 1, span)?;
            let thrown = self.throwable_object_from_expr(&args[0], span, scope)?;
            self.abort_generator_object(object, span)?;
            return Err(self.uncaught_throw_error(&thrown, span));
        }
        expect_expr_arity(&format!("Generator::{method_name}"), args.len(), 0, span)?;
        self.call_generator_method_with_values(object, method_name, Vec::new(), span)
    }

    fn call_generator_method_with_values(
        &mut self,
        object: PhpObject,
        method_name: &str,
        args: Vec<Value>,
        span: Span,
    ) -> CompileResult<Value> {
        if !args.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    format!("Generator::{method_name}()"),
                    ArityExpectation::Exactly(0),
                    args.len(),
                ),
            ));
        }
        match method_name.to_ascii_lowercase().as_str() {
            "rewind" => self.rewind_generator_object(object, span),
            "valid" => self.generator_current_state_value(object, span, |state| {
                Value::Bool(state.position < state.yields.len())
            }),
            "current" => self.generator_current_state_value(object, span, |state| {
                state
                    .yields
                    .get(state.position)
                    .map(|entry| entry.value.clone())
                    .unwrap_or(Value::Null)
            }),
            "key" => self.generator_current_state_value(object, span, |state| {
                state
                    .yields
                    .get(state.position)
                    .map(|entry| entry.key.clone())
                    .unwrap_or(Value::Null)
            }),
            "getreturn" => self.generator_return_value(object, span),
            "next" => {
                let object_id = object.id();
                let state = self.generator_states.get_mut(&object_id).ok_or_else(|| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "Generator::next()",
                            "generator state is missing in the current subset",
                        ),
                    )
                })?;
                if !state.started {
                    return self.rewind_generator_object(object, span);
                }
                state.position = state.position.saturating_add(1);
                Ok(Value::Null)
            }
            _ => Err(runtime_error(
                span,
                RuntimeError::undefined_function(format!("Generator::{method_name}()")),
            )),
        }
    }

    fn generator_current_state_value<F>(
        &mut self,
        object: PhpObject,
        span: Span,
        make_value: F,
    ) -> CompileResult<Value>
    where
        F: FnOnce(&GeneratorState) -> Value,
    {
        if !self
            .generator_states
            .get(&object.id())
            .is_some_and(|state| state.started)
        {
            self.rewind_generator_object(object.clone(), span)?;
        }
        let state = self.generator_states.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator",
                    "generator state is missing in the current subset",
                ),
            )
        })?;
        Ok(make_value(state))
    }

    fn generator_return_value(&mut self, object: PhpObject, span: Span) -> CompileResult<Value> {
        if !self
            .generator_states
            .get(&object.id())
            .is_some_and(|state| state.started)
        {
            self.rewind_generator_object(object.clone(), span)?;
        }
        let state = self.generator_states.get(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator::getReturn()",
                    "generator state is missing in the current subset",
                ),
            )
        })?;
        if state.position < state.yields.len() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator::getReturn()",
                    "Cannot get return value of a generator that hasn't returned",
                ),
            ));
        }
        state.return_value.clone().ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator::getReturn()",
                    "Cannot get return value of a generator that hasn't returned",
                ),
            )
        })
    }

    fn abort_generator_object(&mut self, object: PhpObject, span: Span) -> CompileResult<()> {
        let state = self.generator_states.get_mut(&object.id()).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator::throw()",
                    "generator state is missing in the current subset",
                ),
            )
        })?;
        state.started = true;
        state.position = 0;
        state.yields.clear();
        state.return_value = None;
        Ok(())
    }

    fn rewind_generator_object(&mut self, object: PhpObject, span: Span) -> CompileResult<Value> {
        let object_id = object.id();
        let mut state = self.generator_states.remove(&object_id).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "Generator::rewind()",
                    "generator state is missing in the current subset",
                ),
            )
        })?;

        if state.started {
            state.position = 0;
            self.generator_states.insert(object_id, state);
            return Ok(Value::Null);
        }
        state.started = true;
        state.position = 0;
        if let Some(this_object) = state.this_object.as_ref() {
            state
                .local_scope
                .write_static("this", Value::Object(this_object.clone()));
        }

        self.function_context
            .push(self.function_context_name(&state.function));
        if let Some(class_context) = state.class_context {
            self.class_context.push(class_context);
        }
        if let Some(called_class_context) = state.called_class_context {
            self.called_class_context.push(called_class_context);
        }
        self.call_depth += 1;
        self.active_static_locals.push(Vec::new());
        self.active_symbol_roots
            .push(state.local_scope.symbols.clone());
        self.active_function_call_arguments
            .push(state.active_function_arguments.clone());
        self.active_generator_yields.push(Vec::new());

        let strict_types = state.function.strict_types;
        let flow = self.with_strict_types_scope(strict_types, |this| {
            this.execute_statements(&state.function.body, &mut state.local_scope)
        });
        let pending_yields = self.active_generator_yields.pop().unwrap_or_default();
        self.active_function_call_arguments.pop();

        let static_names = self.active_static_locals.pop().unwrap_or_default();
        let function_key = state.function.name.to_ascii_lowercase();
        for name in static_names {
            if let Some(value) = state.local_scope.read_named(&name) {
                self.static_locals
                    .insert((function_key.clone(), name), value.clone());
            }
        }
        self.active_symbol_roots.pop();
        self.call_depth -= 1;
        self.function_context.pop();
        if state.class_context.is_some() {
            self.class_context.pop();
        }
        if state.called_class_context.is_some() {
            self.called_class_context.pop();
        }

        state.yields = materialize_generator_yields(pending_yields, span)?;
        state.return_value = match &flow {
            Ok(Flow::Return(value)) => Some(value.clone()),
            Ok(Flow::Normal | Flow::Exit(_)) => Some(Value::Null),
            _ => None,
        };
        self.generator_states.insert(object_id, state);

        match flow? {
            Flow::Normal | Flow::Return(_) | Flow::Exit(_) => Ok(Value::Null),
            Flow::Break { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("break cannot be used outside a loop"),
            )),
            Flow::Continue { span, .. } => Err(runtime_error(
                span,
                RuntimeError::invalid_loop_control("continue cannot be used outside a loop"),
            )),
            Flow::Throw { object, span } => Err(self.uncaught_throw_error(&object, span)),
            Flow::Goto { label, span } => Err(undefined_goto_label_error(span, &label)),
        }
    }

    fn active_function_call_arguments_for_func_get(
        function: &FunctionDecl,
        args: &[Value],
        argument_keys: &[Option<ArrayKey>],
        local_scope: &SymbolTable,
    ) -> ActiveFunctionCallArguments {
        let mut cells = Vec::new();

        for (index, value) in args.iter().enumerate() {
            let Some((_, param)) = Self::call_argument_param_for_index(function, index) else {
                cells.push(value_cell(value.clone()));
                continue;
            };

            if param.is_variadic {
                if matches!(
                    argument_keys.get(index).and_then(|key| key.as_ref()),
                    Some(ArrayKey::String(_))
                ) {
                    continue;
                }
                cells.push(value_cell(value.clone()));
                continue;
            }

            cells.push(
                local_scope
                    .read_cell(&param.name)
                    .unwrap_or_else(|| value_cell(value.clone())),
            );
        }

        ActiveFunctionCallArguments { cells }
    }

    fn active_func_get_frame(
        &self,
        callable: &str,
        span: Span,
    ) -> CompileResult<&ActiveFunctionCallArguments> {
        self.active_function_call_arguments.last().ok_or_else(|| {
            let message = match callable {
                "func_num_args()" => {
                    "func_num_args() must be called from a function context".to_string()
                }
                "func_get_arg()" | "func_get_args()" => {
                    format!("{callable} cannot be called from the global scope")
                }
                _ => format!("{callable} cannot be called from the global scope"),
            };
            Diagnostic::new(Phase::Runtime, span.line, span.column, message)
        })
    }

    fn call_func_num_args(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("func_num_args", args, 0, span)?;
        let frame = self.active_func_get_frame("func_num_args()", span)?;
        Ok(Value::Int(frame.cells.len() as i64))
    }

    fn call_func_get_args(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("func_get_args", args, 0, span)?;
        let frame = self.active_func_get_frame("func_get_args()", span)?;
        let mut array = PhpArray::new();
        for cell in &frame.cells {
            array
                .append(cell.value_cloned())
                .map_err(|error| runtime_error(span, error))?;
        }
        Ok(Value::Array(array))
    }

    fn call_func_get_arg(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("func_get_arg", args, 1, span)?;
        let position =
            integer_argument_current_subset("func_get_arg()", "position", &args[0], span)?;
        if position < 0 {
            return Err(Diagnostic::new(
                Phase::Runtime,
                span.line,
                span.column,
                "func_get_arg(): Argument #1 ($position) must be greater than or equal to 0",
            ));
        }

        let frame = self.active_func_get_frame("func_get_arg()", span)?;
        frame
            .cells
            .get(position as usize)
            .map(|cell| cell.value_cloned())
            .ok_or_else(|| {
                Diagnostic::new(
                    Phase::Runtime,
                    span.line,
                    span.column,
                    "func_get_arg(): Argument #1 ($position) must be less than the number of the arguments passed to the currently executed function",
                )
            })
    }

    fn call_debug_backtrace(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("debug_backtrace", args, 0, span)?;
        let frames = self.current_structured_trace_frames();
        self.structured_trace_array(&frames, span)
    }

    fn call_debug_print_backtrace(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("debug_print_backtrace", args, 0, span)?;
        let file = self.throwable_display_file();
        let mut output = String::new();
        for (index, frame) in self.active_debug_backtrace_frames.iter().rev().enumerate() {
            output.push_str(&format!(
                "#{index} {file}({}): {}({})\n",
                frame.call_line,
                frame.display_callable(&file),
                format_stack_trace_args(&frame.args)
            ));
        }
        self.append_output_at(&output, span);
        Ok(Value::Null)
    }

    fn call_debug_zval_dump(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch("debug_zval_dump()", ArityExpectation::AtLeast(1), 0),
            ));
        }
        for value in args {
            match value {
                Value::Object(object) if is_sensitive_parameter_value_object(object) => {
                    self.append_output_at(
                        &format!(
                            "object(SensitiveParameterValue)#{} (0) refcount(2){{\n}}\n",
                            object.id()
                        ),
                        span,
                    );
                }
                _ => {
                    if let Some(output) = self.format_var_dump_argument_bytes(value, span)? {
                        self.append_output_bytes_at(&output, span);
                    }
                }
            }
        }
        Ok(Value::Null)
    }

    fn coerce_call_frame_values(
        &mut self,
        function: &FunctionDecl,
        args: Vec<Value>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> CompileResult<Vec<Value>> {
        args.into_iter()
            .enumerate()
            .map(|(index, value)| {
                let Some((param_index, param)) =
                    Self::call_argument_param_for_index(function, index)
                else {
                    return Ok(value);
                };
                self.coerce_call_argument_value(
                    function,
                    param_index,
                    param,
                    value,
                    class_context,
                    called_class_context,
                )
            })
            .collect()
    }

    fn call_argument_param_for_index(
        function: &FunctionDecl,
        index: usize,
    ) -> Option<(usize, &FunctionParam)> {
        if let Some(param) = function.params.get(index) {
            return Some((index, param));
        }
        function
            .params
            .iter()
            .enumerate()
            .next_back()
            .filter(|(_, param)| param.is_variadic)
    }

    fn coerce_call_argument_value(
        &mut self,
        function: &FunctionDecl,
        param_index: usize,
        param: &FunctionParam,
        value: Value,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> CompileResult<Value> {
        let Some(type_decl) = param.type_decl.as_ref() else {
            return Ok(value);
        };
        if type_decl_is_exact(type_decl, "mixed") {
            return Ok(value);
        }
        if matches!(value, Value::Null) && parameter_accepts_implicit_null(param) {
            return Ok(value);
        }
        let strict_scalars = self.current_strict_types();
        let callable = self.call_type_callable_name(function, class_context);
        let value = self.coerce_stringable_object_for_exact_string_type_decl(
            type_decl,
            value,
            strict_scalars,
            function.span,
            &callable,
        )?;
        if type_decl_contains_callable(&type_decl.text) && self.is_callable_value(&value, false) {
            return Ok(value);
        }
        let actual_type = Self::php_type_error_actual_name(&value);
        let expected_type = parameter_type_error_type_text(type_decl, param);
        self.emit_float_string_to_int_deprecation_for_type_decl(
            &type_decl.text,
            &value,
            strict_scalars,
            function.span,
        )?;
        coerce_property_value_with_object_type_resolver(
            &type_decl.text,
            value,
            &function.name,
            &format!("parameter ${}", param.name),
            strict_scalars,
            |object, type_name| {
                self.object_satisfies_call_type(
                    object,
                    type_name,
                    class_context,
                    called_class_context,
                )
            },
        )
        .map_err(|_| {
            runtime_error(
                function.span,
                RuntimeError::unsupported_call(
                    callable,
                    format!(
                        "Argument #{} (${}) must be of type {}, {actual_type} given",
                        param_index + 1,
                        param.name,
                        expected_type
                    ),
                ),
            )
        })
    }

    fn coerce_call_return_value(
        &mut self,
        function: &FunctionDecl,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        value: Value,
        missing_return: bool,
    ) -> CompileResult<Value> {
        let return_span = if missing_return {
            self.last_return_span = None;
            None
        } else {
            self.last_return_span.take()
        };
        let Some(type_decl) = function.return_type.as_ref() else {
            return Ok(value);
        };
        let callable = self.return_type_callable_name(function, class_context);
        let diagnostic_span = return_span.unwrap_or(function.span);
        if type_decl_is_exact(type_decl, "never") {
            let callable_kind = if class_context.is_some() && function.name != "{closure}" {
                "method"
            } else {
                "function"
            };
            if missing_return {
                return Err(Diagnostic::new(
                    Phase::Runtime,
                    function.span.line,
                    function.span.column,
                    format!(
                        "{callable}: never-returning {callable_kind} must not implicitly return"
                    ),
                ));
            }
            return Err(Diagnostic::new(
                Phase::Runtime,
                diagnostic_span.line,
                diagnostic_span.column,
                format!("{callable}: A never-returning {callable_kind} must not return"),
            ));
        }
        if type_decl_is_exact(type_decl, "void") {
            return if matches!(value, Value::Null) {
                Ok(Value::Null)
            } else {
                Err(Diagnostic::new(
                    Phase::Runtime,
                    diagnostic_span.line,
                    diagnostic_span.column,
                    format!("{callable}: A void function must not return a value"),
                ))
            };
        }
        if missing_return {
            let expected_type =
                self.call_type_error_type_text(type_decl, class_context, called_class_context);
            return Err(Diagnostic::new(
                Phase::Runtime,
                function.span.line,
                function.span.column,
                format!(
                    "{callable}: Return value must be of type {}, none returned",
                    expected_type
                ),
            ));
        }
        if type_decl_is_exact(type_decl, "mixed") {
            return Ok(value);
        }
        self.coerce_call_value_for_type_decl(
            function,
            type_decl,
            "return value",
            value.clone(),
            class_context,
            called_class_context,
        )
        .map_err(|_| {
            let expected_type =
                self.call_type_error_type_text(type_decl, class_context, called_class_context);
            Diagnostic::new(
                Phase::Runtime,
                diagnostic_span.line,
                diagnostic_span.column,
                format!(
                    "{callable}: Return value must be of type {}, {} returned",
                    expected_type,
                    Self::returned_type_name(&value, missing_return)
                ),
            )
        })
    }

    fn return_type_callable_name(
        &self,
        function: &FunctionDecl,
        class_context: Option<ClassId>,
    ) -> String {
        if function.name == "{closure}" {
            let callable = function_callable_name(function, self.source_file.as_deref());
            if let Some(class_id) = class_context {
                if let Some(class) = self.classes.get(class_id) {
                    return format!("{}::{callable}", class.name());
                }
            }
            return callable;
        }
        if let Some(class_id) = class_context {
            if let Some(class) = self.classes.get(class_id) {
                return format!("{}::{}()", class.name(), function.name);
            }
        }
        function_callable_name(function, self.source_file.as_deref())
    }

    fn call_type_callable_name(
        &self,
        function: &FunctionDecl,
        class_context: Option<ClassId>,
    ) -> String {
        if function.name == "{closure}" {
            let callable = function_callable_name(function, self.source_file.as_deref());
            if let Some(class_id) = class_context {
                if let Some(class) = self.classes.get(class_id) {
                    return format!("{}::{callable}", class.name());
                }
            }
            return callable;
        }
        if let Some(class_id) = class_context {
            if let Some(class) = self.classes.get(class_id) {
                return format!("{}::{}()", class.name(), function.name);
            }
        }
        function_callable_name(function, self.source_file.as_deref())
    }

    fn returned_type_name(value: &Value, missing_return: bool) -> String {
        if missing_return {
            "none".to_string()
        } else if let Value::Object(object) = value {
            object.class_name().to_string()
        } else {
            value.type_name().to_string()
        }
    }

    fn call_type_error_type_text(
        &self,
        type_decl: &TypeDecl,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> String {
        self.call_type_error_type_text_from_str(
            &type_decl.text,
            class_context,
            called_class_context,
        )
    }

    fn call_type_error_type_text_from_str(
        &self,
        type_text: &str,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> String {
        let trimmed = type_text.trim();
        if trimmed.is_empty() {
            return type_text.to_string();
        }
        if let Some(nullable) = trimmed.strip_prefix('?') {
            return format!(
                "?{}",
                self.call_type_error_type_text_from_str(
                    nullable.trim(),
                    class_context,
                    called_class_context,
                )
            );
        }
        let stripped = strip_wrapping_type_parens(trimmed);
        let union_parts = split_type_decl_top_level(stripped, '|');
        if union_parts.len() > 1 {
            return union_members_in_php_display_order(union_parts)
                .into_iter()
                .map(|member| {
                    self.call_type_error_type_text_from_str(
                        member,
                        class_context,
                        called_class_context,
                    )
                })
                .map(|member| {
                    if member.contains('&') {
                        format!("({member})")
                    } else {
                        member
                    }
                })
                .collect::<Vec<_>>()
                .join("|");
        }

        let intersection_parts = split_type_decl_top_level(stripped, '&');
        if intersection_parts.len() > 1 {
            return intersection_parts
                .into_iter()
                .map(|member| {
                    self.call_type_error_type_text_from_str(
                        member,
                        class_context,
                        called_class_context,
                    )
                })
                .collect::<Vec<_>>()
                .join("&");
        }

        let normalized = stripped
            .strip_prefix('\\')
            .unwrap_or(stripped)
            .to_ascii_lowercase();
        match normalized.as_str() {
            "self" => class_context
                .and_then(|class_id| self.classes.get(class_id))
                .map(|class| class.name().to_string())
                .unwrap_or_else(|| type_text.to_string()),
            "parent" => class_context
                .and_then(|class_id| self.classes.get(class_id))
                .and_then(|class| class.parent_id())
                .and_then(|parent_id| self.classes.get(parent_id))
                .map(|parent| parent.name().to_string())
                .unwrap_or_else(|| type_text.to_string()),
            "static" => called_class_context
                .or(class_context)
                .and_then(|class_id| self.classes.get(class_id))
                .map(|class| class.name().to_string())
                .unwrap_or_else(|| type_text.to_string()),
            "iterable" => "Traversable|array".to_string(),
            _ => stripped.to_string(),
        }
    }

    fn coerce_call_value_for_type_decl(
        &mut self,
        function: &FunctionDecl,
        type_decl: &TypeDecl,
        label: &str,
        value: Value,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> CompileResult<Value> {
        let actual_type = value.type_name();
        let callable = self.return_type_callable_name(function, class_context);
        let value = self.coerce_stringable_object_for_exact_string_type_decl(
            type_decl,
            value,
            function.strict_types,
            function.span,
            &callable,
        )?;
        if type_decl_contains_callable(&type_decl.text) && self.is_callable_value(&value, false) {
            return Ok(value);
        }
        self.emit_float_string_to_int_deprecation_for_type_decl(
            &type_decl.text,
            &value,
            function.strict_types,
            function.span,
        )?;
        coerce_property_value_with_object_type_resolver(
            &type_decl.text,
            value,
            &function.name,
            label,
            function.strict_types,
            |object, type_name| {
                self.object_satisfies_call_type(
                    object,
                    type_name,
                    class_context,
                    called_class_context,
                )
            },
        )
        .map_err(|_| {
            runtime_error(
                function.span,
                RuntimeError::unsupported_call(
                    callable,
                    format!("{label} expects {}, got {actual_type}", type_decl.text),
                ),
            )
        })
    }

    fn coerce_stringable_object_for_exact_string_type_decl(
        &mut self,
        type_decl: &TypeDecl,
        value: Value,
        strict_scalars: bool,
        span: Span,
        callable: &str,
    ) -> CompileResult<Value> {
        if strict_scalars || !type_decl_is_exact(type_decl, "string") {
            return Ok(value);
        }

        let Value::Object(object) = value else {
            return Ok(value);
        };

        match self.object_to_string_with_magic(object.clone(), callable, span)? {
            Some(output) => Ok(Value::String(output)),
            None => Ok(Value::Object(object)),
        }
    }

    fn call_user_function_with_this(
        &mut self,
        function: &FunctionDecl,
        this_object: PhpObject,
        args: Vec<Value>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
    ) -> CompileResult<Value> {
        self.call_user_function_with_checked_values(
            function,
            args,
            Some(this_object),
            class_context,
            called_class_context,
            Vec::new(),
            None,
        )
    }

    fn call_user_function_with_this_and_array_copy_source(
        &mut self,
        function: &FunctionDecl,
        this_object: PhpObject,
        args: Vec<Value>,
        class_context: Option<ClassId>,
        called_class_context: Option<ClassId>,
        caller_scope: &mut SymbolTable,
    ) -> CompileResult<(Value, Option<ArrayCopySource>)> {
        self.call_user_function_with_checked_values_and_locals_with_array_copy_source(
            function,
            args,
            Some(this_object),
            class_context,
            called_class_context,
            Vec::new(),
            Some(caller_scope),
            Vec::new(),
            Vec::new(),
        )
    }

    fn ensure_user_function_call_depth(
        &self,
        function: &FunctionDecl,
        span: Span,
    ) -> CompileResult<()> {
        if self.call_depth >= MAX_USER_FUNCTION_CALL_DEPTH {
            return Err(runtime_error(
                span,
                RuntimeError::call_depth_exceeded(
                    callable_name(&function.name),
                    MAX_USER_FUNCTION_CALL_DEPTH,
                ),
            ));
        }

        Ok(())
    }

    fn class_id_for_member_metadata_string(
        &mut self,
        class_name: &str,
        span: Span,
    ) -> CompileResult<Option<ClassId>> {
        if class_name.is_empty() {
            return Ok(None);
        }
        if self.classes.lookup_class_id(class_name).is_none() {
            self.run_autoload_callbacks(class_name, AutoloadKind::Class, span)?;
        }
        Ok(self.classes.lookup_class_id(class_name))
    }

    fn value_class_id(&self, object_or_class: &Value, allow_string: bool) -> Option<ClassId> {
        match object_or_class {
            Value::Object(object) => Some(object.class_id()),
            Value::String(candidate) if allow_string => self.classes.lookup_class_id(candidate),
            _ => None,
        }
    }

    fn value_is_a(&self, object_or_class: &Value, class_name: &str, allow_string: bool) -> bool {
        let Some(candidate_id) = self.value_class_id(object_or_class, allow_string) else {
            return false;
        };

        if self.class_implements_or_matches_core_interface(candidate_id, class_name) {
            return true;
        }

        let Some(target_class) = self.classes.lookup_class(class_name) else {
            return false;
        };

        candidate_id == target_class.id()
            || self.classes.is_subclass_of(candidate_id, target_class.id())
    }

    fn value_instanceof(&self, value: &Value, class_name: &str) -> bool {
        let Value::Object(object) = value else {
            return false;
        };
        if self.class_implements_or_matches_core_interface(object.class_id(), class_name) {
            return true;
        }
        let Some(target_class) = self.classes.lookup_class(class_name) else {
            return false;
        };

        object.class_id() == target_class.id()
            || self
                .classes
                .is_subclass_of(object.class_id(), target_class.id())
    }

    fn value_is_subclass_of(
        &self,
        object_or_class: &Value,
        class_name: &str,
        allow_string: bool,
    ) -> bool {
        let Some(candidate_id) = self.value_class_id(object_or_class, allow_string) else {
            return false;
        };

        if self.class_implements_or_matches_core_interface(candidate_id, class_name) {
            return true;
        }

        let Some(target_class) = self.classes.lookup_class(class_name) else {
            return false;
        };

        self.classes.is_subclass_of(candidate_id, target_class.id())
    }

    fn value_is_subclass_of_with_autoload(
        &mut self,
        object_or_class: &Value,
        class_name: &str,
        allow_string: bool,
        span: Span,
    ) -> CompileResult<bool> {
        if let Value::String(candidate) = object_or_class {
            if !allow_string {
                return Ok(false);
            }
            if !candidate.is_empty() && self.classes.lookup_class_id(candidate).is_none() {
                self.run_autoload_callbacks(candidate, AutoloadKind::Class, span)?;
            }
        }

        Ok(self.value_is_subclass_of(object_or_class, class_name, allow_string))
    }

    fn class_implements_or_matches_core_interface(
        &self,
        class_id: ClassId,
        interface_name: &str,
    ) -> bool {
        let canonical_interface_name = self
            .interface_lookup
            .get(&interface_name.to_ascii_lowercase())
            .map(|interface| interface.name.as_str())
            .unwrap_or(interface_name);
        self.class_implements_interface_names(class_id)
            .iter()
            .any(|interface| interface.eq_ignore_ascii_case(canonical_interface_name))
            || (canonical_interface_name.eq_ignore_ascii_case("Stringable")
                && self.class_has_public_instance_to_string(class_id))
    }

    fn class_has_public_instance_to_string(&self, class_id: ClassId) -> bool {
        self.resolve_instance_method(class_id, "__toString")
            .is_some_and(|(_, _, _, visibility, is_static)| {
                visibility == Visibility::Public && !is_static
            })
    }

    fn parent_class_name(&self, class_id: ClassId) -> Option<String> {
        let class = self.classes.get(class_id)?;
        let parent_id = class.parent_id()?;
        Some(self.classes.get(parent_id)?.name().to_string())
    }

    fn call_fopen(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "fopen()",
                    ArityExpectation::Between { min: 2, max: 4 },
                    args.len(),
                ),
            ));
        }

        let path = match &args[0] {
            Value::String(path) => path.as_str(),
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "fopen()",
                        format!(
                            "path argument must be string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        let mode = match &args[1] {
            Value::String(mode) => mode.as_str(),
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "fopen()",
                        format!(
                            "mode argument must be string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        let use_include_path = match args.get(2) {
            Some(Value::Bool(flag)) => *flag,
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "fopen()",
                        format!(
                            "use_include_path argument must be bool in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
            None => false,
        };
        if let Some(context) = args.get(3) {
            self.expect_optional_stream_context_resource("fopen", context, span)?;
        }
        if !matches!(args.get(3), Some(Value::Resource(_))) {
            self.ensure_default_stream_context();
        }

        if !self.ensure_stream_wrapper_can_open_path("fopen()", path, span)? {
            return Ok(Value::Bool(false));
        }

        let file_url_path = match bounded_local_file_url_path(path) {
            Some(Ok(path)) => Some(path),
            Some(Err(message)) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call("fopen()", message),
                ));
            }
            None => None,
        };

        let data_url_stream = if stream_path_protocol(path).eq_ignore_ascii_case("data") {
            Some(match parse_data_url_stream(path) {
                Ok(stream) => stream,
                Err(message) => {
                    self.emit_warning(
                        "fopen()",
                        format!("{path}: Failed to open stream: {message}"),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
            })
        } else {
            None
        };

        let is_memory_stream = match path {
            "php://memory" | "php://temp" | "php://input" => true,
            _ if data_url_stream.is_some() => true,
            other if other.contains("://") && file_url_path.is_none() => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "fopen()",
                        "only php://memory, php://temp, php://input, local file:// URLs, and local file paths are supported in the current stream subset",
                    ),
                ));
            }
            _ => false,
        };

        let Some(stream_mode) = parse_stream_mode(mode) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "fopen()",
                    format!("mode {mode:?} is not supported in the current stream subset"),
                ),
            ));
        };

        let id = self.next_resource_id;
        self.next_resource_id += 1;
        if is_memory_stream {
            let metadata_mode = stream_metadata_mode(path, mode);
            let is_input_stream = path == "php://input";
            let data_url_stream = data_url_stream.as_ref();
            self.streams.insert(
                id,
                StreamResource::Memory(MemoryStream {
                    buffer: if let Some(data_url_stream) = data_url_stream {
                        data_url_stream.contents.clone()
                    } else if is_input_stream {
                        self.request_body.clone()
                    } else {
                        String::new()
                    },
                    position: 0,
                    readable: if data_url_stream.is_some() || is_input_stream {
                        true
                    } else {
                        stream_mode.readable
                    },
                    writable: if data_url_stream.is_some() || is_input_stream {
                        false
                    } else {
                        stream_mode.writable
                    },
                    append: if data_url_stream.is_some() || is_input_stream {
                        false
                    } else {
                        stream_mode.append
                    },
                    eof: false,
                    uri: path.to_string(),
                    read_filter_rot13: false,
                    metadata_wrapper_type: data_url_stream
                        .map(|stream| stream.wrapper_type.clone())
                        .unwrap_or_else(|| "PHP".to_string()),
                    metadata_mode,
                    metadata_stream_type: if let Some(data_url_stream) = data_url_stream {
                        data_url_stream.stream_type.clone()
                    } else if path == "php://temp" {
                        "TEMP".to_string()
                    } else if is_input_stream {
                        "Input".to_string()
                    } else {
                        "MEMORY".to_string()
                    },
                    metadata_include_runtime_flags: data_url_stream.is_none(),
                    metadata_extra: data_url_stream
                        .map(|stream| stream.metadata_extra.clone())
                        .unwrap_or_default(),
                }),
            );
        } else {
            let filesystem_path = file_url_path.unwrap_or_else(|| {
                let literal_path = Path::new(path);
                if stream_mode.create && !literal_path.is_absolute() && !literal_path.exists() {
                    PathBuf::from(path)
                } else {
                    self.resolve_file_get_contents_path(path, use_include_path)
                }
            });
            if !self.enforce_bounded_open_basedir("fopen()", path, &filesystem_path, span)? {
                self.emit_stream_open_denied_after_open_basedir("fopen", path, span)?;
                return Ok(Value::Bool(false));
            }
            let realpath_entry = self.bounded_realpath_entry_for_local_path(&filesystem_path);
            let existed_before_open = filesystem_path.exists();
            let file = match fs::OpenOptions::new()
                .read(stream_mode.readable)
                .write(stream_mode.writable)
                .create(stream_mode.create)
                .create_new(stream_mode.create_new)
                .truncate(stream_mode.truncate)
                .open(&filesystem_path)
            {
                Ok(file) => file,
                Err(error) => {
                    self.emit_display_warning(
                        format!(
                            "fopen({path}): Failed to open stream: {}",
                            php_filesystem_open_error_message(&error)
                        ),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
            };
            if let Some((resolved, metadata)) = realpath_entry {
                self.cache_realpath_entry(resolved, &metadata);
            }
            if stream_mode.create && !existed_before_open {
                self.set_bounded_unix_permissions(
                    &filesystem_path,
                    self.effective_umask_mode(0o666),
                    "fopen",
                    span,
                )?;
            }
            if stream_mode.truncate || stream_mode.create || stream_mode.create_new {
                self.clear_stat_cache_filesystem_path_aliases(&filesystem_path);
            }
            let mut stream = FileStream {
                file,
                readable: stream_mode.readable,
                writable: stream_mode.writable,
                append: stream_mode.append,
                eof: false,
                metadata_unread_bytes: 0,
                uri: path.to_string(),
                filesystem_path: filesystem_path.clone(),
                read_filter_rot13: false,
                metadata_mode: mode.to_string(),
            };
            if stream.append {
                stream.file.seek(SeekFrom::Start(0)).map_err(|error| {
                    runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "fopen()",
                            format!("local file stream seek failed: {error}"),
                        ),
                    )
                })?;
            }
            self.streams.insert(id, StreamResource::File(stream));
        }
        Ok(Value::Resource(id))
    }

    fn call_tmpfile(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("tmpfile", args, 0, span)?;
        let id = self.next_resource_id;
        self.next_resource_id += 1;
        self.streams.insert(
            id,
            StreamResource::Memory(MemoryStream {
                buffer: String::new(),
                position: 0,
                readable: true,
                writable: true,
                append: false,
                eof: false,
                uri: "php://temp".to_string(),
                read_filter_rot13: false,
                metadata_wrapper_type: "PHP".to_string(),
                metadata_mode: "r+b".to_string(),
                metadata_stream_type: "TEMP".to_string(),
                metadata_include_runtime_flags: true,
                metadata_extra: Vec::new(),
            }),
        );
        Ok(Value::Resource(id))
    }

    fn call_shell_exec(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("shell_exec", args, 1, span)?;
        let command = match &args[0] {
            Value::String(command) => command.clone(),
            Value::BinaryString(bytes) => {
                tree_walk_binary_string_utf8(bytes, "shell_exec command", span)?.to_string()
            }
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "shell_exec()",
                        format!(
                            "Argument #1 ($command) must be of type string, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        if command.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "shell_exec()",
                    "Argument #1 ($command) must not contain any null bytes",
                ),
            ));
        }

        let output = Command::new("sh")
            .arg("-c")
            .arg(&command)
            .output()
            .map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "shell_exec()",
                        format!("process execution failed: {error}"),
                    ),
                )
            })?;
        if output.stdout.is_empty() {
            Ok(Value::Null)
        } else {
            Ok(interpreter_value_from_php_string_bytes(output.stdout))
        }
    }

    fn filesystem_path_argument(
        &mut self,
        function: &str,
        label: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            Value::String(path) => Ok(path.clone()),
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!(
                        "{label} argument must be string in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn filesystem_filename_argument(
        &mut self,
        function: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        self.filesystem_filename_argument_for_parameter(function, 1, "filename", value, span)
    }

    fn filesystem_filename_argument_for_parameter(
        &mut self,
        function: &str,
        position: usize,
        name: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        let path = match value {
            Value::String(path) => path.clone(),
            Value::BinaryString(bytes) => {
                tree_walk_binary_string_utf8(bytes, "filesystem path", span)?.to_string()
            }
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => value.echo_string(),
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!(
                            "Argument #{position} (${name}) must be of type string, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        if path.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(format!("{function}()"), "Path must not be empty"),
            ));
        }
        if path.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("Argument #{position} (${name}) must not contain any null bytes"),
                ),
            ));
        }
        Ok(path)
    }

    fn use_include_path_argument(
        &self,
        function: &str,
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<bool> {
        match value {
            Some(Value::Null) | None => Ok(false),
            Some(Value::Bool(flag)) => Ok(*flag),
            Some(Value::Int(flag)) => Ok(*flag != 0),
            Some(Value::Float(flag)) => Ok(*flag != 0.0),
            Some(Value::String(flag)) => Ok(Value::String(flag.clone()).is_truthy()),
            Some(Value::BinaryString(bytes)) => {
                let flag = tree_walk_binary_string_utf8(bytes, "use_include_path", span)?;
                Ok(Value::String(flag.to_string()).is_truthy())
            }
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!(
                        "Argument #2 ($use_include_path) must be of type bool, {} given",
                        php_type_error_given(other)
                    ),
                ),
            )),
        }
    }

    fn filesystem_scalar_path_argument(
        &mut self,
        function: &str,
        label: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Option<String>> {
        match value {
            Value::String(path) => Ok(Some(path.clone())),
            Value::BinaryString(bytes) => {
                let path = tree_walk_binary_string_utf8(bytes, "filesystem path", span)?;
                Ok(Some(path.to_string()))
            }
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => {
                Ok(Some(value.echo_string()))
            }
            other => {
                self.emit_filesystem_display_warning(
                    function,
                    format!(
                        "{label} argument must be a valid filesystem path, got {}",
                        other.type_name()
                    ),
                    span,
                )?;
                Ok(None)
            }
        }
    }

    fn filesystem_stringable_object_path_argument(
        &mut self,
        function: &str,
        parameter: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Option<String>> {
        let Value::Object(object) = value else {
            return Ok(None);
        };
        let function_label = format!("{function}()");
        if let Some(path) =
            self.object_to_string_with_magic(object.clone(), &function_label, span)?
        {
            return Ok(Some(path));
        }
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_label,
                format!(
                    "Argument #1 (${parameter}) must be of type string, {} given",
                    php_type_error_given(value)
                ),
            ),
        ))
    }

    fn filesystem_access_scalar_path_argument(
        &mut self,
        function: &str,
        label: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Option<String>> {
        if let Some(path) =
            self.filesystem_stringable_object_path_argument(function, label, value, span)?
        {
            return Ok(Some(path));
        }
        self.filesystem_scalar_path_argument(function, label, value, span)
    }

    fn filesystem_predicate_path_argument(
        &mut self,
        function: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            Value::String(path) => Ok(path.clone()),
            Value::BinaryString(bytes) => {
                let path = tree_walk_binary_string_utf8(bytes, "filesystem path", span)?;
                Ok(path.to_string())
            }
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => {
                Ok(value.echo_string())
            }
            Value::Object(_) => {
                let Some(path) = self.filesystem_stringable_object_path_argument(
                    function, "filename", value, span,
                )?
                else {
                    unreachable!("object path helper returns Some or an error for objects");
                };
                Ok(path)
            }
            other => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!(
                        "path argument must be string in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn filesystem_scalar_metadata_path_argument(
        &mut self,
        function: &str,
        label: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Option<String>> {
        if matches!(
            value,
            Value::Array(_) | Value::Closure(_) | Value::Resource(_)
        ) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!(
                        "Argument #1 (${label}) must be of type string, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        }
        let Some(path) = self.filesystem_scalar_path_argument(function, label, value, span)? else {
            return Ok(None);
        };
        if path.is_empty() {
            return Ok(None);
        }
        if path.contains('\0') {
            self.emit_filesystem_display_warning(function, "Filename contains null byte", span)?;
            return Ok(None);
        }
        Ok(Some(path))
    }

    fn emit_filesystem_metadata_failure_warning(
        &mut self,
        function: &str,
        path: &str,
        follow_links: bool,
        span: Span,
    ) -> CompileResult<()> {
        let operation = if follow_links {
            "stat failed"
        } else {
            "Lstat failed"
        };
        self.emit_filesystem_display_warning(function, format!("{operation} for {path}"), span)
    }

    fn filesystem_tempnam_string_argument(
        &mut self,
        position: usize,
        name: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        let value = match value {
            Value::String(value) => value.clone(),
            Value::BinaryString(bytes) => {
                tree_walk_binary_string_utf8(bytes, name, span)?.to_string()
            }
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => value.echo_string(),
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "tempnam()",
                        format!(
                            "Argument #{position} (${name}) must be of type string, {} given",
                            php_type_error_given(other)
                        ),
                    ),
                ));
            }
        };
        if value.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "tempnam()",
                    format!("Argument #{position} (${name}) must not contain any null bytes"),
                ),
            ));
        }
        Ok(value)
    }

    fn emit_filesystem_display_warning(
        &mut self,
        function: &str,
        message: impl AsRef<str>,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_warning(format!("{function}(): {}", message.as_ref()), span)
    }

    fn filesystem_io_warning_message(error: &std::io::Error) -> String {
        match error.kind() {
            ErrorKind::NotFound => "No such file or directory".to_string(),
            ErrorKind::AlreadyExists => "File exists".to_string(),
            ErrorKind::PermissionDenied => "Permission denied".to_string(),
            ErrorKind::InvalidInput => "Invalid argument".to_string(),
            _ => match error.raw_os_error() {
                Some(1) => "Operation not permitted".to_string(),
                Some(2) => "No such file or directory".to_string(),
                Some(13) => "Permission denied".to_string(),
                Some(17) => "File exists".to_string(),
                Some(20) => "Not a directory".to_string(),
                Some(21) => "Is a directory".to_string(),
                Some(22) => "Invalid argument".to_string(),
                Some(39) => "Directory not empty".to_string(),
                _ => error.to_string(),
            },
        }
    }

    fn filesystem_flags_argument(
        &self,
        function: &str,
        label: &str,
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<i64> {
        match value {
            Some(Value::Int(flags)) => Ok(*flags),
            Some(Value::Null) | None => Ok(0),
            Some(other) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!(
                        "{label} argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            )),
        }
    }

    fn resolve_local_filesystem_operation_path(
        &self,
        function: &str,
        path: &str,
        use_include_path: bool,
        span: Span,
    ) -> CompileResult<PathBuf> {
        if let Some(file_url_path) = bounded_local_file_url_path(path) {
            return file_url_path.map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(format!("{function}()"), message),
                )
            });
        }
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "only local file:// URLs and local filesystem paths are supported in the current filesystem subset",
                ),
            ));
        }
        if use_include_path {
            Ok(self.resolve_file_get_contents_path(path, true))
        } else {
            Ok(local_filesystem_operation_path(path))
        }
    }

    fn resolve_local_filesystem_operation_path_preserving_dot_segments(
        &self,
        function: &str,
        path: &str,
        span: Span,
    ) -> CompileResult<PathBuf> {
        if let Some(file_url_path) = bounded_local_file_url_path(path) {
            return file_url_path.map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(format!("{function}()"), message),
                )
            });
        }
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "only local file:// URLs and local filesystem paths are supported in the current filesystem subset",
                ),
            ));
        }
        let requested_path = PathBuf::from(path);
        if requested_path.is_absolute() || requested_path.exists() {
            return Ok(requested_path);
        }
        Ok(repo_root_relative_path(&requested_path).unwrap_or(requested_path))
    }

    fn resolve_file_put_contents_path(
        &self,
        path: &str,
        use_include_path: bool,
        span: Span,
    ) -> CompileResult<PathBuf> {
        if let Some(file_url_path) = bounded_local_file_url_path(path) {
            return file_url_path.map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call("file_put_contents()", message),
                )
            });
        }
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "file_put_contents()",
                    "only local file:// URLs and local filesystem paths are supported in the current filesystem subset",
                ),
            ));
        }
        let requested_path = Path::new(path);
        if requested_path.is_absolute() || !use_include_path {
            return Ok(PathBuf::from(path));
        }
        for entry in self.include_path.split(INCLUDE_PATH_SEPARATOR) {
            let entry = if entry.is_empty() { "." } else { entry };
            let candidate = PathBuf::from(entry).join(requested_path);
            if candidate.exists() {
                return Ok(candidate);
            }
        }
        Ok(PathBuf::from(path))
    }

    fn clear_stat_cache_filesystem_path(&mut self, path: &Path) {
        self.stat_cache.remove(path);
    }

    fn clear_stat_cache_filesystem_path_aliases(&mut self, path: &Path) {
        self.stat_cache.remove(path);
        let Some(target_metadata) = fs::metadata(path).ok() else {
            return;
        };
        let target_canonical = fs::canonicalize(path).ok();
        let aliases = self
            .stat_cache
            .iter()
            .filter_map(|(cached_path, cached_metadata)| {
                let same_identity = filesystem_metadata_matches(&target_metadata, cached_metadata);
                let same_canonical = target_canonical.as_ref().is_some_and(|target| {
                    fs::canonicalize(cached_path)
                        .map(|cached| cached == *target)
                        .unwrap_or(false)
                });
                (same_identity || same_canonical).then(|| cached_path.clone())
            })
            .collect::<Vec<_>>();
        for alias in aliases {
            self.stat_cache.remove(&alias);
        }
    }

    fn cached_filesystem_metadata(
        &mut self,
        path: &Path,
        follow_links: bool,
    ) -> Option<fs::Metadata> {
        if !follow_links {
            return fs::symlink_metadata(path).ok();
        }
        if let Some(metadata) = self.stat_cache.get(path) {
            return Some(metadata.clone());
        }

        let metadata = fs::metadata(path).ok()?;
        self.stat_cache.insert(path.to_path_buf(), metadata.clone());
        Some(metadata)
    }

    fn call_stat_path_builtin(
        &mut self,
        args: &[Value],
        function: &str,
        follow_links: bool,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function, args, 1, span)?;
        let Some(path) =
            self.filesystem_scalar_metadata_path_argument(function, "filename", &args[0], span)?
        else {
            return Ok(Value::Bool(false));
        };
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            &path,
            &filesystem_path,
            span,
        )? {
            return Ok(Value::Bool(false));
        }
        let Some(metadata) = self.cached_filesystem_metadata(&filesystem_path, follow_links) else {
            self.emit_filesystem_metadata_failure_warning(function, &path, follow_links, span)?;
            return Ok(Value::Bool(false));
        };
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        Ok(Value::Array(local_file_stream_stat_array(&metadata)))
    }

    fn call_fileperms(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("fileperms", args, 1, span)?;
        let Some(path) =
            self.filesystem_scalar_metadata_path_argument("fileperms", "filename", &args[0], span)?
        else {
            return Ok(Value::Bool(false));
        };
        let filesystem_path =
            self.resolve_local_filesystem_operation_path("fileperms", &path, false, span)?;
        if !self.enforce_bounded_open_basedir("fileperms()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        let Some(metadata) = self.cached_filesystem_metadata(&filesystem_path, true) else {
            self.emit_filesystem_metadata_failure_warning("fileperms", &path, true, span)?;
            return Ok(Value::Bool(false));
        };
        if trailing_separator_requires_directory(&path) && !metadata.is_dir() {
            self.emit_filesystem_metadata_failure_warning("fileperms", &path, true, span)?;
            return Ok(Value::Bool(false));
        }
        Ok(Value::Int(filesystem_mode_bits(&metadata)))
    }

    fn call_chmod(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("chmod", args, 2, span)?;
        let path = self.filesystem_path_argument("chmod", "path", &args[0], span)?;
        let mode = match &args[1] {
            Value::Int(mode) => *mode,
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "chmod()",
                        format!(
                            "permissions argument must be int in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        let filesystem_path = self
            .resolve_local_filesystem_operation_path_preserving_dot_segments(
                "chmod", &path, span,
            )?;
        if !self.enforce_bounded_open_basedir("chmod()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        match self.try_set_bounded_unix_permissions(&filesystem_path, mode) {
            Ok(()) => {
                self.clear_stat_cache_filesystem_path(&filesystem_path);
                Ok(Value::Bool(true))
            }
            Err(error) => {
                self.emit_filesystem_display_warning(
                    "chmod",
                    Self::filesystem_io_warning_message(&error),
                    span,
                )?;
                Ok(Value::Bool(false))
            }
        }
    }

    fn call_chown_or_chgrp(
        &mut self,
        args: &[Value],
        function: &str,
        value_label: &str,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function, args, 2, span)?;
        let path = self.filesystem_path_argument(function, "filename", &args[0], span)?;
        match &args[1] {
            Value::Int(_) | Value::String(_) => {}
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!(
                            "{value_label} argument must be int or string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            &path,
            &filesystem_path,
            span,
        )? {
            return Ok(Value::Bool(false));
        }
        match fs::metadata(&filesystem_path) {
            Ok(_) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "ownership mutation is not supported for existing files in the current subset",
                ),
            )),
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "{function}(): {}",
                        Self::filesystem_io_warning_message(&error)
                    ),
                    span,
                )?;
                Ok(Value::Bool(false))
            }
        }
    }

    fn call_lchown_or_lchgrp(
        &mut self,
        args: &[Value],
        function: &str,
        value_label: &str,
        current_identity: fn() -> Option<i64>,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function, args, 2, span)?;
        let path = self.filesystem_path_argument(function, "filename", &args[0], span)?;
        let function_call = format!("{function}()");
        let requested = php_internal_int_argument(&function_call, 2, value_label, &args[1], span)?;
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(&function_call, &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        if let Err(error) = fs::symlink_metadata(&filesystem_path) {
            self.emit_filesystem_display_warning(
                function,
                Self::filesystem_io_warning_message(&error),
                span,
            )?;
            return Ok(Value::Bool(false));
        }

        let Some(current) = current_identity() else {
            self.emit_filesystem_display_warning(function, "Operation not permitted", span)?;
            return Ok(Value::Bool(false));
        };
        if requested >= 0 && requested == current {
            self.clear_stat_cache_filesystem_path(&filesystem_path);
            return Ok(Value::Bool(true));
        }

        self.emit_filesystem_display_warning(function, "Operation not permitted", span)?;
        Ok(Value::Bool(false))
    }

    fn call_file_metadata_int_builtin(
        &mut self,
        args: &[Value],
        function: &str,
        value: fn(&fs::Metadata) -> i64,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function, args, 1, span)?;
        let Some(path) =
            self.filesystem_scalar_metadata_path_argument(function, "filename", &args[0], span)?
        else {
            return Ok(Value::Bool(false));
        };
        if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    "stream wrappers are not supported in the current subset",
                ),
            ));
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path(function, &path, false, span)?;
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            &path,
            &filesystem_path,
            span,
        )? {
            return Ok(Value::Bool(false));
        }
        let Some(metadata) = self.cached_filesystem_metadata(&filesystem_path, true) else {
            self.emit_filesystem_metadata_failure_warning(function, &path, true, span)?;
            return Ok(Value::Bool(false));
        };
        if trailing_separator_requires_directory(&path) && !metadata.is_dir() {
            self.emit_filesystem_metadata_failure_warning(function, &path, true, span)?;
            return Ok(Value::Bool(false));
        }
        Ok(Value::Int(value(&metadata)))
    }

