    fn call_touch(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.is_empty() || args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "touch()",
                    ArityExpectation::Between { min: 1, max: 3 },
                    args.len(),
                ),
            ));
        }
        let Some(path) =
            self.filesystem_scalar_path_argument("touch", "filename", &args[0], span)?
        else {
            return Ok(Value::Bool(false));
        };
        if path.is_empty() {
            return Ok(Value::Bool(false));
        }
        for (index, value) in args.iter().enumerate().skip(1) {
            if !matches!(value, Value::Int(_) | Value::Null) {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "touch()",
                        format!(
                            "timestamp argument {} must be int or null in the current subset, got {}",
                            index,
                            value.type_name()
                        ),
                    ),
                ));
            }
        }
        if matches!(args.get(1), Some(Value::Null)) && matches!(args.get(2), Some(Value::Int(_))) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "touch()",
                    "Argument #2 ($mtime) cannot be null when argument #3 ($atime) is an integer",
                ),
            ));
        }
        let modified = touch_argument_time(args.get(1), SystemTime::now(), span)?;
        let accessed = touch_argument_time(args.get(2), modified, span)?;
        let filesystem_path =
            self.resolve_local_filesystem_operation_path("touch", &path, false, span)?;
        if !self.enforce_bounded_open_basedir("touch()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        let metadata = fs::metadata(&filesystem_path).ok();
        if trailing_separator_requires_directory(&path) {
            match metadata.as_ref() {
                Some(metadata) if metadata.is_dir() => {}
                Some(_) => {
                    self.emit_filesystem_display_warning(
                        "touch",
                        format!("Unable to create file {path} because Not a directory"),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
                None => {
                    self.emit_filesystem_display_warning(
                        "touch",
                        format!("Unable to create file {path} because Is a directory"),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
            }
        }
        let file = match metadata.as_ref().map(|metadata| metadata.is_dir()) {
            Some(true) => fs::File::open(&filesystem_path),
            Some(false) => fs::OpenOptions::new().write(true).open(&filesystem_path),
            None => {
                if trailing_separator_requires_directory(&path) {
                    Err(std::io::Error::from_raw_os_error(21))
                } else {
                    fs::OpenOptions::new()
                        .create(true)
                        .write(true)
                        .open(&filesystem_path)
                }
            }
        };
        let file = match file {
            Ok(file) => file,
            Err(error) => {
                self.emit_filesystem_display_warning(
                    "touch",
                    format!(
                        "Unable to create file {path} because {}",
                        Self::filesystem_io_warning_message(&error)
                    ),
                    span,
                )?;
                return Ok(Value::Bool(false));
            }
        };
        let times = FileTimes::new()
            .set_accessed(accessed)
            .set_modified(modified);
        if let Err(error) = file.set_times(times) {
            self.emit_filesystem_display_warning(
                "touch",
                format!(
                    "Unable to create file {path} because {}",
                    Self::filesystem_io_warning_message(&error)
                ),
                span,
            )?;
            return Ok(Value::Bool(false));
        }
        if metadata.is_none() {
            self.set_bounded_unix_permissions(
                &filesystem_path,
                self.effective_umask_mode(0o666),
                "touch",
                span,
            )?;
        }
        self.clear_stat_cache_filesystem_path_aliases(&filesystem_path);
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        Ok(Value::Bool(true))
    }

    fn call_sys_get_temp_dir(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("sys_get_temp_dir", args, 0, span)?;
        let path = std::env::temp_dir();
        let path = path.into_os_string().into_string().map_err(|_| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "sys_get_temp_dir()",
                    "system temporary directory must be valid UTF-8 in the current subset",
                ),
            )
        })?;
        Ok(Value::String(path))
    }

    fn call_umask(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.len() > 1 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "umask()",
                    ArityExpectation::Between { min: 0, max: 1 },
                    args.len(),
                ),
            ));
        }
        let previous = self.current_umask.unwrap_or(PHP_DEFAULT_REQUEST_UMASK);
        match args.first() {
            None | Some(Value::Null) => {}
            Some(Value::Int(mask)) => {
                self.current_umask = Some(mask & 0o777);
            }
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "umask()",
                        format!(
                            "mask argument must be int or null in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        }
        Ok(Value::Int(previous))
    }

    fn call_tempnam(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("tempnam", args, 2, span)?;
        let directory = self.filesystem_tempnam_string_argument(1, "directory", &args[0], span)?;
        let prefix = self.filesystem_tempnam_string_argument(2, "prefix", &args[1], span)?;

        let (mut directory_path, mut used_system_temp_dir) = if directory.is_empty() {
            (std::env::temp_dir(), false)
        } else {
            let requested_path =
                self.resolve_local_filesystem_operation_path("tempnam", &directory, false, span)?;
            if fs::metadata(&requested_path)
                .map(|metadata| metadata.is_dir())
                .unwrap_or(false)
            {
                (
                    fs::canonicalize(&requested_path).unwrap_or(requested_path),
                    false,
                )
            } else {
                (std::env::temp_dir(), true)
            }
        };

        let prefix = tempnam_filename_prefix(&prefix);
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|_| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "tempnam()",
                        "system time before the Unix epoch is not supported in the current subset",
                    ),
                )
            })?
            .as_nanos();
        let mut fallback_attempted = used_system_temp_dir;
        let mut system_temp_notice_emitted = false;

        loop {
            let directory_display = directory_path.to_string_lossy().into_owned();
            if used_system_temp_dir && !system_temp_notice_emitted {
                self.emit_display_notice(
                    "tempnam(): file created in the system's temporary directory",
                    span,
                )?;
                system_temp_notice_emitted = true;
            }
            if !self.enforce_bounded_open_basedir(
                "tempnam()",
                &directory_display,
                &directory_path,
                span,
            )? {
                return Ok(Value::Bool(false));
            }

            match self.create_tempnam_file_in_directory(
                &directory_path,
                &prefix,
                timestamp,
                span,
            )? {
                TempnamCreateResult::Created(candidate) => {
                    let path = candidate.into_os_string().into_string().map_err(|_| {
                        runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "tempnam()",
                                "created path must be valid UTF-8 in the current subset",
                            ),
                        )
                    })?;
                    return Ok(Value::String(path));
                }
                TempnamCreateResult::RetryExhausted => {
                    self.emit_filesystem_display_warning(
                        "tempnam",
                        "Unable to create a unique temporary file",
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
                TempnamCreateResult::Failed(error)
                    if !fallback_attempted && tempnam_should_fallback_to_system_temp(&error) =>
                {
                    directory_path = std::env::temp_dir();
                    used_system_temp_dir = true;
                    fallback_attempted = true;
                }
                TempnamCreateResult::Failed(error) => {
                    self.emit_filesystem_display_warning(
                        "tempnam",
                        Self::filesystem_io_warning_message(&error),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
            }
        }
    }

    fn create_tempnam_file_in_directory(
        &mut self,
        directory_path: &Path,
        prefix: &str,
        timestamp: u128,
        span: Span,
    ) -> CompileResult<TempnamCreateResult> {
        for attempt in 0..1024u16 {
            let filename = format!(
                "{prefix}{:016x}{:03x}",
                (timestamp & u128::from(u64::MAX)) as u64,
                attempt
            );
            let candidate = directory_path.join(filename);
            match fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&candidate)
            {
                Ok(_) => {
                    self.set_bounded_unix_permissions(&candidate, 0o600, "tempnam", span)?;
                    self.clear_stat_cache_filesystem_path(&candidate);
                    self.cache_bounded_realpath_entry_for_local_path(&candidate);
                    return Ok(TempnamCreateResult::Created(candidate));
                }
                Err(error) if error.kind() == ErrorKind::AlreadyExists => continue,
                Err(error) => return Ok(TempnamCreateResult::Failed(error)),
            }
        }

        Ok(TempnamCreateResult::RetryExhausted)
    }

    fn call_sleep(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("sleep", args, 1, span)?;
        let seconds = match args[0] {
            Value::Int(seconds) if seconds >= 0 => seconds as u64,
            Value::Int(_) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "sleep()",
                        "Argument #1 ($seconds) must be greater than or equal to 0",
                    ),
                ));
            }
            ref other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "sleep()",
                        format!(
                            "seconds argument must be int in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        if seconds > 0 {
            std::thread::sleep(Duration::from_secs(seconds));
        }
        Ok(Value::Int(0))
    }

    fn call_usleep(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("usleep", args, 1, span)?;
        let microseconds =
            php_internal_int_argument("usleep()", 1, "microseconds", &args[0], span)?;
        if microseconds < 0 {
            let error = runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "usleep()",
                    "Argument #1 ($microseconds) must be greater than or equal to 0",
                ),
            );
            self.record_pending_uncaught_internal_call_frame("usleep", span, args, &error);
            return Err(error);
        }

        if microseconds > 0 {
            std::thread::sleep(Duration::from_micros(microseconds as u64));
        }
        Ok(Value::Null)
    }

    fn file_put_contents_data_bytes(
        &mut self,
        value: &Value,
        span: Span,
    ) -> CompileResult<Option<Vec<u8>>> {
        match value {
            Value::Array(array) => {
                let mut bytes = Vec::new();
                for entry in array.entries() {
                    match entry.value() {
                        Value::Array(_) => {
                            self.emit_warning(
                                "file_put_contents()",
                                "Array to string conversion",
                                span,
                            )?;
                            bytes.extend_from_slice(b"Array");
                        }
                        value => bytes.extend(self.value_to_echo_bytes(value.clone(), span)?),
                    }
                }
                Ok(Some(bytes))
            }
            Value::Object(object) => {
                if let Some(output) =
                    self.object_to_string_with_magic(object.clone(), "file_put_contents()", span)?
                {
                    Ok(Some(output.into_bytes()))
                } else {
                    Ok(None)
                }
            }
            Value::Resource(_) => Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "file_put_contents()",
                    "file_put_contents(): supplied resource is not a valid stream resource",
                ),
            )),
            value => self.value_to_echo_bytes(value.clone(), span).map(Some),
        }
    }

    fn call_file_put_contents(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.len() < 2 || args.len() > 4 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "file_put_contents()",
                    ArityExpectation::Between { min: 2, max: 4 },
                    args.len(),
                ),
            ));
        }
        let path = self.filesystem_filename_argument("file_put_contents", &args[0], span)?;
        let Some(data) = self.file_put_contents_data_bytes(&args[1], span)? else {
            return Ok(Value::Bool(false));
        };
        let flags =
            self.filesystem_flags_argument("file_put_contents", "flags", args.get(2), span)?;
        let allowed_flags = PHP_FILE_USE_INCLUDE_PATH | PHP_LOCK_EX | PHP_FILE_APPEND;
        if flags & !allowed_flags != 0 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "file_put_contents()",
                    format!("flags value {flags} contains unsupported bits in the current subset"),
                ),
            ));
        }
        if let Some(context) = args.get(3) {
            self.expect_optional_stream_context_resource("file_put_contents", context, span)?;
        }

        let filesystem_path = self.resolve_file_put_contents_path(
            &path,
            flags & PHP_FILE_USE_INCLUDE_PATH != 0,
            span,
        )?;
        if !self.enforce_bounded_open_basedir(
            "file_put_contents()",
            &path,
            &filesystem_path,
            span,
        )? {
            self.emit_stream_open_denied_after_open_basedir("file_put_contents", &path, span)?;
            return Ok(Value::Bool(false));
        }

        let mut options = fs::OpenOptions::new();
        options.write(true).create(true);
        if flags & PHP_FILE_APPEND != 0 {
            options.append(true);
        } else {
            options.truncate(true);
        }
        let existed_before_open = filesystem_path.exists();
        let mut file = match options.open(&filesystem_path) {
            Ok(file) => file,
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "file_put_contents({path}): Failed to open stream: {}",
                        php_filesystem_open_error_message(&error)
                    ),
                    span,
                )?;
                return Ok(Value::Bool(false));
            }
        };
        if let Err(error) = file.write_all(&data) {
            self.emit_display_warning(
                format!("file_put_contents({path}): Failed to write stream: {error}"),
                span,
            )?;
            return Ok(Value::Bool(false));
        }
        if !existed_before_open {
            self.set_bounded_unix_permissions(
                &filesystem_path,
                self.effective_umask_mode(0o666),
                "file_put_contents",
                span,
            )?;
        }
        self.clear_stat_cache_filesystem_path_aliases(&filesystem_path);
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        Ok(Value::Int(data.len() as i64))
    }

    fn call_highlight_string(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "highlight_string()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let value = self.value_to_echo_bytes(args[0].clone(), span)?;
        let highlighted = php_highlight_source_bytes(&value, &self.php_highlight_colors());
        if args.get(1).is_some_and(Value::is_truthy) {
            return Ok(Value::String(highlighted));
        }

        self.append_output_bytes_at(highlighted.as_bytes(), span);
        Ok(Value::Bool(true))
    }

    fn call_highlight_file(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "highlight_file()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let path = self.filesystem_filename_argument("highlight_file", &args[0], span)?;
        let return_output = args.get(1).is_some_and(Value::is_truthy);
        if path.starts_with("data:") {
            let contents = match parse_data_url_stream(&path) {
                Ok(stream) => stream.contents.into_bytes(),
                Err(message) => {
                    self.emit_display_warning(
                        format!("highlight_file({path}): Failed to open stream: {message}"),
                        span,
                    )?;
                    self.emit_display_warning(
                        format!("highlight_file(): Failed opening '{path}' for highlighting"),
                        span,
                    )?;
                    return Ok(Value::Bool(false));
                }
            };
            let highlighted = php_highlight_source_bytes(&contents, &self.php_highlight_colors());
            if return_output {
                return Ok(Value::String(highlighted));
            }
            self.append_output_bytes_at(highlighted.as_bytes(), span);
            return Ok(Value::Bool(true));
        }

        let filesystem_path =
            self.resolve_local_filesystem_operation_path("highlight_file", &path, false, span)?;
        if !self.enforce_bounded_open_basedir("highlight_file()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }

        let contents = match fs::read(&filesystem_path) {
            Ok(contents) => contents,
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "highlight_file({path}): Failed to open stream: {}",
                        php_filesystem_open_error_message(&error)
                    ),
                    span,
                )?;
                self.emit_display_warning(
                    format!("highlight_file(): Failed opening '{path}' for highlighting"),
                    span,
                )?;
                return Ok(Value::Bool(false));
            }
        };
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);

        let highlighted = php_highlight_source_bytes(&contents, &self.php_highlight_colors());
        if return_output {
            Ok(Value::String(highlighted))
        } else {
            self.append_output_bytes_at(highlighted.as_bytes(), span);
            Ok(Value::Bool(true))
        }
    }

    fn php_highlight_colors(&self) -> PhpHighlightColors {
        PhpHighlightColors {
            html: self
                .ini_value("highlight.html")
                .unwrap_or_else(|| PHP_HIGHLIGHT_HTML.to_string()),
            default: self
                .ini_value("highlight.default")
                .unwrap_or_else(|| PHP_HIGHLIGHT_DEFAULT.to_string()),
            keyword: self
                .ini_value("highlight.keyword")
                .unwrap_or_else(|| PHP_HIGHLIGHT_KEYWORD.to_string()),
            string: self
                .ini_value("highlight.string")
                .unwrap_or_else(|| PHP_HIGHLIGHT_STRING.to_string()),
            comment: self
                .ini_value("highlight.comment")
                .unwrap_or_else(|| PHP_HIGHLIGHT_COMMENT.to_string()),
        }
    }

