    fn call_file_builtin(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.is_empty() || args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "file()",
                    ArityExpectation::Between { min: 1, max: 3 },
                    args.len(),
                ),
            ));
        }

        let path = self.filesystem_path_argument("file", "filename", &args[0], span)?;
        let flags = self.filesystem_flags_argument("file", "flags", args.get(1), span)?;
        let allowed_flags = PHP_FILE_USE_INCLUDE_PATH
            | PHP_FILE_IGNORE_NEW_LINES
            | PHP_FILE_SKIP_EMPTY_LINES
            | PHP_FILE_NO_DEFAULT_CONTEXT;
        if flags & !allowed_flags != 0 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "file()",
                    "Argument #2 ($flags) must be a valid flag value",
                ),
            ));
        }
        if let Some(context) = args.get(2) {
            self.expect_optional_stream_context_resource("file", context, span)?;
        }
        if !self.ensure_stream_wrapper_can_open_path("file()", &path, span)? {
            return Ok(Value::Bool(false));
        }
        let filesystem_path = self.resolve_local_filesystem_operation_path(
            "file",
            &path,
            flags & PHP_FILE_USE_INCLUDE_PATH != 0,
            span,
        )?;
        if !self.enforce_bounded_open_basedir("file()", &path, &filesystem_path, span)? {
            self.emit_stream_open_denied_after_open_basedir("file", &path, span)?;
            return Ok(Value::Bool(false));
        }
        let contents = match fs::read_to_string(&filesystem_path) {
            Ok(contents) => contents,
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "file({path}): Failed to open stream: {}",
                        php_filesystem_open_error_message(&error)
                    ),
                    span,
                )?;
                return Ok(Value::Bool(false));
            }
        };
        self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
        Ok(Value::Array(file_lines_array(&contents, flags, span)?))
    }

    fn call_unlink(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "unlink()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }
        let Some(path) = self.filesystem_scalar_path_argument("unlink", "path", &args[0], span)?
        else {
            return Ok(Value::Bool(false));
        };
        if let Some(context) = args.get(1) {
            self.expect_optional_stream_context_resource("unlink", context, span)?;
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path("unlink", &path, false, span)?;
        if !self.enforce_bounded_open_basedir("unlink()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        if trailing_separator_requires_directory(&path)
            && fs::symlink_metadata(&filesystem_path)
                .map(|metadata| !metadata.is_dir())
                .unwrap_or(false)
        {
            self.emit_display_warning(format!("unlink({path}): Not a directory"), span)?;
            return Ok(Value::Bool(false));
        }
        match fs::remove_file(&filesystem_path) {
            Ok(()) => {
                self.clear_stat_cache_filesystem_path(&filesystem_path);
                Ok(Value::Bool(true))
            }
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "unlink({path}): {}",
                        Self::filesystem_io_warning_message(&error)
                    ),
                    span,
                )?;
                Ok(Value::Bool(false))
            }
        }
    }

    fn call_mkdir(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.is_empty() || args.len() > 4 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "mkdir()",
                    ArityExpectation::Between { min: 1, max: 4 },
                    args.len(),
                ),
            ));
        }
        let path = self.filesystem_path_argument("mkdir", "path", &args[0], span)?;
        if path.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "mkdir()",
                    "Argument #1 ($directory) must not contain any null bytes",
                ),
            ));
        }
        let mode = match args.get(1) {
            Some(Value::Int(mode)) => *mode,
            Some(Value::Null) | None => 0o777,
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mkdir()",
                        format!(
                            "mode argument must be int in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        let recursive = match args.get(2) {
            Some(Value::Bool(flag)) => *flag,
            Some(Value::Null) | None => false,
            Some(other) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mkdir()",
                        format!(
                            "recursive argument must be bool in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        };
        if let Some(context) = args.get(3) {
            self.expect_optional_stream_context_resource("mkdir", context, span)?;
        }
        let filesystem_path =
            self.resolve_local_filesystem_operation_path("mkdir", &path, false, span)?;
        if !self.enforce_bounded_open_basedir("mkdir()", &path, &filesystem_path, span)? {
            return Ok(Value::Bool(false));
        }
        let result = if recursive {
            fs::create_dir_all(&filesystem_path)
        } else {
            fs::create_dir(&filesystem_path)
        };
        match result {
            Ok(()) => {
                self.set_bounded_unix_permissions(
                    &filesystem_path,
                    self.effective_umask_mode(mode),
                    "mkdir",
                    span,
                )?;
                self.clear_stat_cache_filesystem_path(&filesystem_path);
                self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
                Ok(Value::Bool(true))
            }
            Err(error) => {
                let message = Self::filesystem_io_warning_message(&error);
                if error.kind() == ErrorKind::PermissionDenied {
                    self.emit_filesystem_display_warning("mkdir", message, span)?;
                } else {
                    self.emit_warning("mkdir()", format!("{path}: {message}"), span)?;
                }
                Ok(Value::Bool(false))
            }
        }
    }

    fn effective_umask_mode(&self, mode: i64) -> i64 {
        match self.current_umask {
            Some(mask) => mode & !mask,
            None => mode,
        }
    }

    fn set_bounded_unix_permissions(
        &mut self,
        path: &Path,
        mode: i64,
        function: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.try_set_bounded_unix_permissions(path, mode)
            .map_err(|error| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        format!("setting filesystem permissions failed: {error}"),
                    ),
                )
            })?;
        Ok(())
    }

    fn try_set_bounded_unix_permissions(&self, path: &Path, mode: i64) -> std::io::Result<()> {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = (mode as u32) & 0o7777;
            let permissions = fs::Permissions::from_mode(mode);
            fs::set_permissions(path, permissions)?;
        }
        #[cfg(not(unix))]
        {
            let _ = (path, mode);
        }
        Ok(())
    }

