fn reflection_internal_extension_name(name: &str) -> String {
    if name.starts_with("bc") {
        "bcmath".to_string()
    } else if name.starts_with("ctype_") {
        "ctype".to_string()
    } else if name.starts_with("posix_") {
        "posix".to_string()
    } else {
        "standard".to_string()
    }
}

fn reflection_internal_untyped_param(name: &str) -> ReflectionParameterMetadata {
    ReflectionParameterMetadata {
        name: name.to_string(),
        type_decl: None,
        by_reference: false,
        can_be_passed_by_value: true,
        is_variadic: false,
        default: None,
        default_constant_name: None,
        attributes: Vec::new(),
    }
}

fn reflection_internal_untyped_reference_param(name: &str) -> ReflectionParameterMetadata {
    let mut param = reflection_internal_untyped_param(name);
    param.by_reference = true;
    param
}

fn reflection_internal_method_params(
    class_name: &str,
    method_name: &str,
) -> Vec<ReflectionParameterMetadata> {
    if class_name.eq_ignore_ascii_case("ReflectionProperty")
        && method_name.eq_ignore_ascii_case("__construct")
    {
        return vec![
            reflection_internal_param("class", "object|string"),
            reflection_internal_param("property", "string"),
        ];
    }
    if class_name.eq_ignore_ascii_case("DateTime") && method_name.eq_ignore_ascii_case("setTime") {
        return reflection_internal_datetime_set_time_params();
    }
    if class_name.eq_ignore_ascii_case("DateTime")
        && method_name.eq_ignore_ascii_case("createFromFormat")
    {
        return reflection_internal_datetime_create_from_format_params();
    }
    if class_name.eq_ignore_ascii_case("DateTimeImmutable")
        && method_name.eq_ignore_ascii_case("setTime")
    {
        return reflection_internal_datetime_set_time_params();
    }
    if class_name.eq_ignore_ascii_case("DateTimeImmutable")
        && method_name.eq_ignore_ascii_case("createFromFormat")
    {
        return reflection_internal_datetime_create_from_format_params();
    }
    if class_name.eq_ignore_ascii_case("DateTimeZone")
        && method_name.eq_ignore_ascii_case("getTransitions")
    {
        return vec![
            reflection_internal_optional_global_constant_int_param("timestampBegin", "PHP_INT_MIN"),
            reflection_internal_optional_int_param("timestampEnd", 2_147_483_647),
        ];
    }
    if class_name.eq_ignore_ascii_case("DateTimeZone")
        && method_name.eq_ignore_ascii_case("listIdentifiers")
    {
        return vec![
            reflection_internal_optional_class_constant_int_param(
                "timezoneGroup",
                "DateTimeZone",
                "ALL",
            ),
            reflection_internal_optional_null_param("countryCode", "?string"),
        ];
    }
    if class_name.eq_ignore_ascii_case("SplFileObject") {
        if method_name.eq_ignore_ascii_case("fgetcsv")
            || method_name.eq_ignore_ascii_case("setCsvControl")
        {
            return vec![
                reflection_internal_optional_string_param("separator", ","),
                reflection_internal_optional_string_param("enclosure", "\""),
                reflection_internal_optional_string_param("escape", "\\"),
            ];
        }
        if method_name.eq_ignore_ascii_case("fputcsv") {
            return vec![
                reflection_internal_param("fields", "array"),
                reflection_internal_optional_string_param("separator", ","),
                reflection_internal_optional_string_param("enclosure", "\""),
                reflection_internal_optional_string_param("escape", "\\"),
                reflection_internal_optional_string_param("eol", "\n"),
            ];
        }
    }
    Vec::new()
}

fn core_internal_class_method_signature(
    class_name: &str,
    method_name: &str,
) -> Option<MethodSignature> {
    if (class_name.eq_ignore_ascii_case("DateTime")
        || class_name.eq_ignore_ascii_case("DateTimeImmutable"))
        && method_name.eq_ignore_ascii_case("setTime")
    {
        return Some(core_method_signature_from_reflection_params(
            reflection_internal_datetime_set_time_params(),
            Some(class_name),
        ));
    }
    if (class_name.eq_ignore_ascii_case("DateTime")
        || class_name.eq_ignore_ascii_case("DateTimeImmutable"))
        && method_name.eq_ignore_ascii_case("createFromFormat")
    {
        let return_type = if class_name.eq_ignore_ascii_case("DateTimeImmutable") {
            "DateTimeImmutable|false"
        } else {
            "DateTime|false"
        };
        return Some(core_method_signature_from_reflection_params(
            reflection_internal_datetime_create_from_format_params(),
            Some(return_type),
        ));
    }
    if (class_name.eq_ignore_ascii_case("DateTime")
        || class_name.eq_ignore_ascii_case("DateTimeImmutable"))
        && method_name.eq_ignore_ascii_case("diff")
    {
        return Some(core_method_signature_from_reflection_params(
            reflection_internal_datetime_interface_diff_params(),
            Some("DateInterval"),
        ));
    }
    if class_name.eq_ignore_ascii_case("DateTimeZone")
        && method_name.eq_ignore_ascii_case("getTransitions")
    {
        return Some(core_method_signature_from_reflection_params(
            vec![
                reflection_internal_optional_global_constant_int_param(
                    "timestampBegin",
                    "PHP_INT_MIN",
                ),
                reflection_internal_optional_int_param("timestampEnd", 2_147_483_647),
            ],
            Some("array|false"),
        ));
    }
    if class_name.eq_ignore_ascii_case("DateTimeZone")
        && method_name.eq_ignore_ascii_case("listIdentifiers")
    {
        return Some(
            core_method_signature_from_reflection_params_with_tentative_return(
                vec![
                    reflection_internal_optional_class_constant_int_param(
                        "timezoneGroup",
                        "DateTimeZone",
                        "ALL",
                    ),
                    reflection_internal_optional_null_param("countryCode", "?string"),
                ],
                None,
                Some("array"),
            ),
        );
    }
    None
}

fn core_internal_interface_method_signature(
    interface_name: &str,
    method_lookup_name: &str,
) -> Option<(&'static str, MethodSignature)> {
    if interface_name.eq_ignore_ascii_case("DateTimeInterface")
        && method_lookup_name.eq_ignore_ascii_case("diff")
    {
        return Some((
            "diff",
            core_method_signature_from_reflection_params(
                reflection_internal_datetime_interface_diff_params(),
                Some("DateInterval"),
            ),
        ));
    }
    None
}

fn core_method_signature_from_reflection_params(
    params: Vec<ReflectionParameterMetadata>,
    return_type: Option<&str>,
) -> MethodSignature {
    core_method_signature_from_reflection_params_with_tentative_return(params, return_type, None)
}

fn core_method_signature_from_reflection_params_with_tentative_return(
    params: Vec<ReflectionParameterMetadata>,
    return_type: Option<&str>,
    tentative_return_type: Option<&str>,
) -> MethodSignature {
    let params = params
        .into_iter()
        .map(parameter_signature_from_reflection_metadata)
        .collect::<Vec<_>>();
    MethodSignature {
        required_params: required_parameter_signature_count(&params),
        params,
        static_variables: Vec::new(),
        return_type: return_type.map(str::to_string),
        tentative_return_type: tentative_return_type.map(str::to_string),
        returns_by_reference: false,
        file_name: None,
        start_line: 0,
        end_line: 0,
        doc_comment: None,
        attributes: Vec::new(),
        is_deprecated: false,
    }
}

fn parameter_signature_from_reflection_metadata(
    param: ReflectionParameterMetadata,
) -> ParameterSignature {
    ParameterSignature {
        name: param.name,
        type_decl: param.type_decl,
        by_reference: param.by_reference,
        is_variadic: param.is_variadic,
        default: param.default,
        attributes: param.attributes,
    }
}

fn required_parameter_signature_count(params: &[ParameterSignature]) -> usize {
    params
        .iter()
        .take_while(|param| param.default.is_none() && !param.is_variadic)
        .count()
}

