fn reflection_internal_param(name: &str, type_decl: &str) -> ReflectionParameterMetadata {
    ReflectionParameterMetadata {
        name: name.to_string(),
        type_decl: Some(type_decl.to_string()),
        by_reference: false,
        can_be_passed_by_value: true,
        is_variadic: false,
        default: None,
        default_constant_name: None,
        attributes: Vec::new(),
    }
}

