fn reflection_declaring_params(
    declaring: &ReflectionParameterDeclaring,
) -> &[ReflectionParameterMetadata] {
    match declaring {
        ReflectionParameterDeclaring::Function(function) => &function.params,
        ReflectionParameterDeclaring::Method(method) => &method.params,
    }
}

fn reflection_named_type_to_string(state: &ReflectionNamedTypeState) -> String {
    if state.allows_null
        && !state.name.eq_ignore_ascii_case("mixed")
        && !state.name.eq_ignore_ascii_case("null")
    {
        format!("?{}", state.name)
    } else {
        state.name.clone()
    }
}

fn reflection_type_state_to_string(state: &ReflectionTypeState) -> String {
    match state {
        ReflectionTypeState::Named(state) => reflection_named_type_to_string(state),
        ReflectionTypeState::Compound(state) => reflection_compound_type_to_string(state),
    }
}

fn reflection_compound_type_to_string(state: &ReflectionCompoundTypeState) -> String {
    let separator = match state.kind {
        ReflectionCompoundTypeKind::Union => "|",
        ReflectionCompoundTypeKind::Intersection => "&",
    };
    state
        .types
        .iter()
        .map(|type_state| match (state.kind, type_state) {
            (ReflectionCompoundTypeKind::Union, ReflectionTypeState::Compound(compound))
                if compound.kind == ReflectionCompoundTypeKind::Intersection =>
            {
                format!("({})", reflection_compound_type_to_string(compound))
            }
            _ => reflection_type_state_to_string(type_state),
        })
        .collect::<Vec<_>>()
        .join(separator)
}

fn reflection_type_state_allows_null(state: &ReflectionTypeState) -> bool {
    match state {
        ReflectionTypeState::Named(state) => state.allows_null,
        ReflectionTypeState::Compound(state) => {
            state.kind == ReflectionCompoundTypeKind::Union
                && state.types.iter().any(reflection_type_state_allows_null)
        }
    }
}

fn reflection_named_type_state_from_type_decl(
    type_decl: &str,
    default: Option<&Expr>,
) -> Option<ReflectionNamedTypeState> {
    let top_level_union = split_type_decl_top_level(type_decl.trim(), '|');
    if top_level_union.len() > 1 {
        return reflection_nullable_false_true_bc_type(&top_level_union);
    }
    if type_decl.contains('|') || type_decl.contains('&') {
        return None;
    }
    let name = type_decl
        .trim()
        .strip_prefix('?')
        .unwrap_or(type_decl.trim())
        .to_string();
    Some(ReflectionNamedTypeState {
        allows_null: reflection_parameter_allows_null(Some(type_decl), default),
        is_builtin: reflection_type_name_is_builtin(&name),
        name,
    })
}

fn reflection_type_state_from_type_decl(
    type_decl: &str,
    default: Option<&Expr>,
) -> Option<ReflectionTypeState> {
    if let Some(state) = reflection_compound_type_state_from_type_decl(type_decl) {
        return Some(ReflectionTypeState::Compound(state));
    }
    reflection_named_type_state_from_type_decl(type_decl, default).map(ReflectionTypeState::Named)
}

fn reflection_compound_type_state_from_type_decl(
    type_decl: &str,
) -> Option<ReflectionCompoundTypeState> {
    let text = type_decl.trim();
    let text = strip_wrapping_type_parens(text);
    let union_parts = split_type_decl_top_level(text, '|');
    if union_parts.len() > 1 {
        if reflection_nullable_false_true_bc_type(&union_parts).is_some() {
            return None;
        }
        let mut types = Vec::new();
        for part in union_parts {
            let part = strip_wrapping_type_parens(part.trim());
            if part.eq_ignore_ascii_case("iterable") {
                types.push(ReflectionTypeState::Named(ReflectionNamedTypeState {
                    name: "Traversable".to_string(),
                    allows_null: false,
                    is_builtin: false,
                }));
                types.push(ReflectionTypeState::Named(ReflectionNamedTypeState {
                    name: "array".to_string(),
                    allows_null: false,
                    is_builtin: true,
                }));
                continue;
            }
            types.push(reflection_type_state_from_type_decl(part, None)?);
        }
        return Some(ReflectionCompoundTypeState {
            kind: ReflectionCompoundTypeKind::Union,
            types,
        });
    }

    let intersection_parts = split_type_decl_top_level(text, '&');
    if intersection_parts.len() > 1 {
        let mut types = Vec::new();
        for part in intersection_parts {
            let type_state = reflection_named_type_state_from_type_decl(part.trim(), None)?;
            types.push(ReflectionTypeState::Named(type_state));
        }
        Some(ReflectionCompoundTypeState {
            kind: ReflectionCompoundTypeKind::Intersection,
            types,
        })
    } else {
        None
    }
}

fn reflection_nullable_false_true_bc_type(parts: &[&str]) -> Option<ReflectionNamedTypeState> {
    if parts.len() != 2 {
        return None;
    }
    let mut has_null = false;
    let mut false_or_true = None;
    for part in parts {
        let normalized =
            normalize_type_name(strip_wrapping_type_parens(part.trim())).to_ascii_lowercase();
        match normalized.as_str() {
            "null" => has_null = true,
            "false" | "true" => false_or_true = Some(normalized),
            _ => return None,
        }
    }
    if !has_null {
        return None;
    }
    Some(ReflectionNamedTypeState {
        name: false_or_true?,
        allows_null: true,
        is_builtin: true,
    })
}

fn reflection_type_decl_resolve_self(type_decl: &str, class_name: &str) -> String {
    let text = type_decl.trim();
    if let Some(nullable) = text.strip_prefix('?') {
        return format!(
            "?{}",
            reflection_type_decl_resolve_self(nullable.trim(), class_name)
        );
    }

    let stripped = strip_wrapping_type_parens(text);
    if stripped != text {
        return format!(
            "({})",
            reflection_type_decl_resolve_self(stripped, class_name)
        );
    }

    let union_parts = split_type_decl_top_level(text, '|');
    if union_parts.len() > 1 {
        return union_parts
            .into_iter()
            .map(|part| reflection_type_decl_resolve_self(part, class_name))
            .collect::<Vec<_>>()
            .join("|");
    }

    let intersection_parts = split_type_decl_top_level(text, '&');
    if intersection_parts.len() > 1 {
        return intersection_parts
            .into_iter()
            .map(|part| reflection_type_decl_resolve_self(part, class_name))
            .collect::<Vec<_>>()
            .join("&");
    }

    if normalize_type_name(text).eq_ignore_ascii_case("self") {
        class_name.to_string()
    } else {
        text.to_string()
    }
}

fn split_type_decl_top_level(text: &str, separator: char) -> Vec<&str> {
    let mut parts = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (index, ch) in text.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => depth = depth.saturating_sub(1),
            ch if ch == separator && depth == 0 => {
                parts.push(&text[start..index]);
                start = index + ch.len_utf8();
            }
            _ => {}
        }
    }
    parts.push(&text[start..]);
    parts
}

fn strip_wrapping_type_parens(text: &str) -> &str {
    let mut current = text.trim();
    loop {
        let Some(inner) = current
            .strip_prefix('(')
            .and_then(|value| value.strip_suffix(')'))
        else {
            return current;
        };
        if type_decl_outer_parens_wrap_all(current) {
            current = inner.trim();
        } else {
            return current;
        }
    }
}

fn type_decl_outer_parens_wrap_all(text: &str) -> bool {
    let mut depth = 0usize;
    for (index, ch) in text.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => {
                depth = depth.saturating_sub(1);
                if depth == 0 && index < text.len() - 1 {
                    return false;
                }
            }
            _ => {}
        }
    }
    depth == 0
}

fn reflection_parameter_allows_null(type_decl: Option<&str>, default: Option<&Expr>) -> bool {
    let Some(type_decl) = type_decl else {
        return true;
    };
    type_decl.starts_with('?')
        || type_decl
            .split('|')
            .any(|part| part.eq_ignore_ascii_case("null"))
        || type_decl.eq_ignore_ascii_case("mixed")
        || matches!(default, Some(Expr::Null(_)))
}

fn reflection_parameter_has_implicit_nullable_default(param: &ReflectionParameterMetadata) -> bool {
    matches!(param.default, Some(Expr::Null(_))) && param.type_decl.is_some()
}

fn reflection_implicit_nullable_type_text(type_decl: &str) -> String {
    if type_decl.contains('&') && !type_decl.contains('|') {
        return format!("({type_decl})|null");
    }
    if !type_decl.contains('|') {
        return format!("?{type_decl}");
    }
    format!("{type_decl}|null")
}

fn reflection_type_name_is_builtin(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "array"
            | "bool"
            | "callable"
            | "false"
            | "float"
            | "int"
            | "iterable"
            | "mixed"
            | "never"
            | "null"
            | "object"
            | "string"
            | "true"
            | "void"
    )
}

fn reflection_method_modifier_mask(method: &ReflectionMethodState) -> i64 {
    let mut mask = match method.visibility {
        Visibility::Public => REFLECTION_MODIFIER_PUBLIC,
        Visibility::Protected => REFLECTION_MODIFIER_PROTECTED,
        Visibility::Private => REFLECTION_MODIFIER_PRIVATE,
    };
    if method.is_static {
        mask |= REFLECTION_MODIFIER_STATIC;
    }
    if method.is_final {
        mask |= REFLECTION_MODIFIER_FINAL;
    }
    if method.is_abstract {
        mask |= REFLECTION_MODIFIER_EXPLICIT_ABSTRACT;
    }
    mask
}

fn reflection_method_matches_filter(method: &ReflectionMethodState, filter: Option<i64>) -> bool {
    match filter {
        Some(0) => false,
        Some(filter) => reflection_method_modifier_mask(method) & filter != 0,
        None => true,
    }
}

fn reflection_method_filter_argument(value: Value, span: Span) -> CompileResult<i64> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(value)),
        Value::Int(value) => Ok(value),
        Value::Float(value) if value.is_finite() => Ok(value as i64),
        Value::String(value) => parse_sprintf_numeric_string(&value)
            .map(|value| value as i64)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "ReflectionClass::getMethods",
                        "filter argument must be int-like scalar in the current subset",
                    ),
                )
            }),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "ReflectionClass::getMethods",
                format!(
                    "filter argument must be int-like scalar in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn reflection_class_namespace_name(name: &str) -> String {
    name.rsplit_once('\\')
        .map(|(namespace, _)| namespace.to_string())
        .unwrap_or_default()
}

fn reflection_visibility_name(visibility: Visibility) -> &'static str {
    match visibility {
        Visibility::Public => "public",
        Visibility::Protected => "protected",
        Visibility::Private => "private",
    }
}

fn reflection_class_constant_type_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Int(_) => "int",
        Value::Float(_) => "float",
        Value::String(_) | Value::BinaryString(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
        Value::Closure(_) => "Closure",
        Value::Resource(_) => "resource",
    }
}

fn reflection_class_constant_display_value(value: &Value) -> String {
    match value {
        Value::Null | Value::Bool(false) => String::new(),
        Value::Bool(true) => "1".to_string(),
        Value::String(value) => value.clone(),
        Value::BinaryString(bytes) => String::from_utf8(bytes.clone()).unwrap_or_default(),
        Value::Array(_) => "Array".to_string(),
        Value::Object(object) => enum_like_case_name(object)
            .map(|case_name| format!("{}::{case_name}", object.class_name()))
            .unwrap_or_else(|| format!("Object({})", object.class_name())),
        Value::Closure(_) => "Closure".to_string(),
        Value::Resource(id) => format!("Resource id #{id}"),
        _ => value.echo_string(),
    }
}

fn indent_reflection_block(block: &str, prefix: &str) -> String {
    let mut output = String::new();
    for line in block.trim_end_matches('\n').split('\n') {
        if !line.is_empty() {
            output.push_str(prefix);
        }
        output.push_str(line);
        output.push('\n');
    }
    output
}

fn reflection_scalar_name_argument(value: Value, span: Span) -> CompileResult<String> {
    value
        .try_echo_string()
        .map_err(|error| runtime_error(span, error))
}

fn reflection_scalar_string_argument(
    function: &'static str,
    parameter: &'static str,
    value: Value,
    span: Span,
) -> CompileResult<String> {
    match value.php_scalar_string_bytes() {
        Some(bytes) => String::from_utf8(bytes).map_err(|_| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    format!("{function}()"),
                    format!("Argument (${parameter}) must be valid UTF-8 in the current subset"),
                ),
            )
        }),
        None => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{function}()"),
                format!(
                    "Argument (${parameter}) must be scalar string-convertible in the current subset, got {}",
                    value.type_name()
                ),
            ),
        )),
    }
}

fn reflection_int_mask_argument(
    function: &'static str,
    value: Value,
    span: Span,
) -> CompileResult<i64> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(value)),
        Value::Int(value) => Ok(value),
        Value::Float(value) if value.is_finite() => Ok(value as i64),
        Value::String(value) => parse_sprintf_numeric_string(&value)
            .map(|value| value as i64)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        format!("{function}()"),
                        "modifier mask argument must be int-like scalar in the current subset",
                    ),
                )
            }),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                format!("{function}()"),
                format!(
                    "modifier mask argument must be int-like scalar in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn reflection_modifier_names_array(modifiers: i64) -> PhpArray {
    let mut array = PhpArray::new();
    for (bit, name) in [
        (REFLECTION_MODIFIER_EXPLICIT_ABSTRACT, "abstract"),
        (REFLECTION_MODIFIER_FINAL, "final"),
        (REFLECTION_MODIFIER_PUBLIC, "public"),
        (REFLECTION_MODIFIER_PROTECTED, "protected"),
        (REFLECTION_MODIFIER_PRIVATE, "private"),
        (REFLECTION_MODIFIER_STATIC, "static"),
        (REFLECTION_MODIFIER_PROPERTY_READONLY, "readonly"),
        (REFLECTION_MODIFIER_CLASS_READONLY, "readonly"),
        (REFLECTION_MODIFIER_PROPERTY_VIRTUAL, "virtual"),
        (REFLECTION_MODIFIER_PROPERTY_PROTECTED_SET, "protected(set)"),
        (REFLECTION_MODIFIER_PROPERTY_PRIVATE_SET, "private(set)"),
    ] {
        if modifiers & bit != 0 {
            let _ = array.append(Value::String(name.to_string()));
        }
    }
    array
}

fn reflection_object_is_uncloneable_class(class_name: &str) -> bool {
    matches!(
        class_name.to_ascii_lowercase().as_str(),
        "directory"
            | "reflection"
            | "reflectionfunctionabstract"
            | "reflectionfunction"
            | "reflectiongenerator"
            | "reflectionparameter"
            | "reflectiontype"
            | "reflectionnamedtype"
            | "reflectionuniontype"
            | "reflectionintersectiontype"
            | "reflectionmethod"
            | "reflectionclass"
            | "reflectionobject"
            | "reflectionproperty"
            | "reflectionclassconstant"
            | "reflectionextension"
            | "reflectionzendextension"
            | "reflectionreference"
            | "reflectionattribute"
            | "reflectionenum"
            | "reflectionenumunitcase"
            | "reflectionenumbackedcase"
            | "reflectionfiber"
    )
}

fn directory_reflection_class_to_string() -> &'static str {
    concat!(
        "Class [ <internal:standard> final class Directory ] {\n",
        "\n",
        "  - Constants [0] {\n",
        "  }\n",
        "\n",
        "  - Static properties [0] {\n",
        "  }\n",
        "\n",
        "  - Static methods [0] {\n",
        "  }\n",
        "\n",
        "  - Properties [2] {\n",
        "    Property [ public protected(set) readonly string $path ]\n",
        "    Property [ public protected(set) readonly mixed $handle ]\n",
        "  }\n",
        "\n",
        "  - Methods [3] {\n",
        "    Method [ <internal:standard> public method close ] {\n",
        "\n",
        "      - Parameters [0] {\n",
        "      }\n",
        "      - Return [ void ]\n",
        "    }\n",
        "\n",
        "    Method [ <internal:standard> public method rewind ] {\n",
        "\n",
        "      - Parameters [0] {\n",
        "      }\n",
        "      - Return [ void ]\n",
        "    }\n",
        "\n",
        "    Method [ <internal:standard> public method read ] {\n",
        "\n",
        "      - Parameters [0] {\n",
        "      }\n",
        "      - Return [ string|false ]\n",
        "    }\n",
        "  }\n",
        "}\n",
    )
}

fn reflection_class_constant_modifier_mask(constant: &ReflectionClassConstantState) -> i64 {
    let mut mask = match constant.visibility {
        Visibility::Public => REFLECTION_MODIFIER_PUBLIC,
        Visibility::Protected => REFLECTION_MODIFIER_PROTECTED,
        Visibility::Private => REFLECTION_MODIFIER_PRIVATE,
    };
    if constant.is_final {
        mask |= REFLECTION_MODIFIER_FINAL;
    }
    mask
}

fn reflection_class_constant_matches_filter(
    constant: &ReflectionClassConstantState,
    filter: Option<i64>,
) -> bool {
    match filter {
        Some(0) => false,
        Some(filter) => reflection_class_constant_modifier_mask(constant) & filter != 0,
        None => true,
    }
}

fn reflection_method_core_invoke_error(
    state: &ReflectionMethodState,
    span: Span,
) -> Option<Diagnostic> {
    (state
        .declaring_class_name
        .eq_ignore_ascii_case("ReflectionAttribute")
        && state.name.eq_ignore_ascii_case("__construct"))
    .then(|| reflection_exception_error(span, "Cannot directly instantiate ReflectionAttribute"))
}

fn reflection_class_constant_filter_argument(value: Value, span: Span) -> CompileResult<i64> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(value)),
        Value::Int(value) => Ok(value),
        Value::Float(value) if value.is_finite() => Ok(value as i64),
        Value::String(value) => parse_sprintf_numeric_string(&value)
            .map(|value| value as i64)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "ReflectionClass::getConstants",
                        "filter argument must be int-like scalar in the current subset",
                    ),
                )
            }),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "ReflectionClass::getConstants",
                format!(
                    "filter argument must be int-like scalar in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn reflection_property_modifier_mask(property: &ReflectionPropertyState) -> i64 {
    let mut mask = match property.visibility {
        Visibility::Public => REFLECTION_MODIFIER_PUBLIC,
        Visibility::Protected => REFLECTION_MODIFIER_PROTECTED,
        Visibility::Private => REFLECTION_MODIFIER_PRIVATE,
    };
    if property.is_static {
        mask |= REFLECTION_MODIFIER_STATIC;
    }
    mask
}

fn reflection_property_mangled_name(property: &ReflectionPropertyState) -> String {
    match property.visibility {
        Visibility::Public => property.name.clone(),
        Visibility::Protected => format!("\0*\0{}", property.name),
        Visibility::Private => format!("\0{}\0{}", property.declaring_class_name, property.name),
    }
}

fn reflection_value_export_short(value: &Value) -> String {
    match value {
        Value::Null => "NULL".to_string(),
        Value::Bool(true) => "true".to_string(),
        Value::Bool(false) => "false".to_string(),
        Value::Int(value) => value.to_string(),
        Value::Float(value) => Value::Float(*value).echo_string(),
        Value::String(value) => format!("'{}'", reflection_quote_string(value)),
        Value::BinaryString(value) => String::from_utf8(value.clone())
            .map(|value| format!("'{}'", reflection_quote_string(&value)))
            .unwrap_or_else(|_| "''".to_string()),
        Value::Array(_) => "Array".to_string(),
        Value::Object(object) => enum_like_case_name(object)
            .map(|case_name| format!("{}::{case_name}", object.class_name()))
            .unwrap_or_else(|| format!("Object({})", object.class_name())),
        Value::Closure(_) => "Closure".to_string(),
        Value::Resource(id) => format!("Resource id #{id}"),
    }
}

fn reflection_quote_string(value: &str) -> String {
    value.replace('\\', "\\\\").replace('\'', "\\'")
}

fn implemented_interface_names(classes: &PhpClassTable, class_id: ClassId) -> Vec<String> {
    let mut names = Vec::new();
    let mut current = Some(class_id);
    while let Some(current_id) = current {
        let current_class = classes
            .get(current_id)
            .expect("class id should resolve to class metadata");
        names.extend(current_class.interfaces().iter().cloned());
        current = current_class.parent_id();
    }

    names
}

fn signature_type_context_for_class<'a>(
    classes: &'a PhpClassTable,
    final_classes: &HashSet<ClassId>,
    class_id: ClassId,
) -> SignatureTypeContext<'a> {
    let class = classes
        .get(class_id)
        .expect("class id should resolve to class metadata");
    let parent_name = class
        .parent_id()
        .and_then(|parent_id| classes.get(parent_id))
        .map(|parent| parent.name());
    SignatureTypeContext {
        self_name: class.name(),
        parent_name,
        is_final: final_classes.contains(&class_id),
    }
}

fn signature_type_context_for_name(name: &str) -> SignatureTypeContext<'_> {
    SignatureTypeContext {
        self_name: name,
        parent_name: None,
        is_final: false,
    }
}

fn class_implements_signature_interface(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_id: ClassId,
    interface_name: &str,
) -> bool {
    let mut current = Some(class_id);
    while let Some(current_id) = current {
        let class = classes
            .get(current_id)
            .expect("class id should resolve to class metadata");
        for implemented in class.interfaces() {
            if signature_interface_extends_or_matches(interface_lookup, implemented, interface_name)
            {
                return true;
            }
        }
        current = class.parent_id();
    }
    false
}

fn signature_interface_extends_or_matches(
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    supertype: &str,
) -> bool {
    if subtype.eq_ignore_ascii_case(&supertype) {
        return true;
    }
    if interface_extends_interface(interface_lookup, subtype, supertype) {
        return true;
    }
    core_interface_parent_names(subtype)
        .iter()
        .any(|parent| signature_interface_extends_or_matches(interface_lookup, parent, supertype))
}

fn find_public_method<'a>(
    classes: &'a PhpClassTable,
    class_id: ClassId,
    method_lookup_name: &str,
) -> Option<(ClassId, &'a str, &'a PhpMethodMetadata)> {
    find_method(classes, class_id, method_lookup_name)
        .filter(|(_, _, method)| method.visibility() == Visibility::Public)
}

fn find_method<'a>(
    classes: &'a PhpClassTable,
    class_id: ClassId,
    method_lookup_name: &str,
) -> Option<(ClassId, &'a str, &'a PhpMethodMetadata)> {
    let mut current = Some(class_id);
    while let Some(current_id) = current {
        let current_class = classes
            .get(current_id)
            .expect("class id should resolve to class metadata");
        if let Some(method) = current_class.method(method_lookup_name) {
            return Some((current_id, current_class.name(), method));
        }
        current = current_class.parent_id();
    }

    None
}

fn validate_abstract_method_implementation(
    classes: &PhpClassTable,
    abstract_methods: &HashSet<(ClassId, String)>,
    class_id: ClassId,
    class: &ClassDecl,
) -> RuntimeResult<()> {
    if class.is_abstract {
        return Ok(());
    }

    let own_abstract_methods = abstract_method_names_for_class_decl(class);
    let mut missing = Vec::new();
    let mut covered_names = HashSet::new();

    for member in &class.members {
        let ClassMember::Method(method) = member else {
            continue;
        };
        let lookup_name = method.function.name.to_ascii_lowercase();
        if method.is_abstract {
            covered_names.insert(lookup_name);
            missing.push(format!("{}::{}()", class.name, method.function.name));
        } else {
            covered_names.insert(lookup_name);
        }
    }

    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        for method in parent.methods() {
            let lookup_name = method.name().to_ascii_lowercase();
            if !covered_names.insert(lookup_name.clone()) {
                continue;
            }
            if !abstract_methods.contains(&(parent_id, lookup_name.clone())) {
                continue;
            }
            if has_concrete_method_implementation(
                classes,
                abstract_methods,
                class_id,
                &own_abstract_methods,
                &lookup_name,
            ) {
                continue;
            }
            missing.push(format!("{}::{}()", parent.name(), method.name()));
        }

        current = parent.parent_id();
    }

    if missing.is_empty() {
        return Ok(());
    }

    let method_list = missing.join(", ");
    let method_word = if missing.len() == 1 {
        "method"
    } else {
        "methods"
    };
    Err(RuntimeError::unsupported_class_inheritance(
        &class.name,
        format!(
            "concrete class {} must implement abstract {method_word} {method_list}",
            class.name
        ),
    ))
}

fn abstract_method_names_for_class_decl(class: &ClassDecl) -> HashSet<String> {
    class
        .members
        .iter()
        .filter_map(|member| {
            let ClassMember::Method(method) = member else {
                return None;
            };
            method
                .is_abstract
                .then(|| method.function.name.to_ascii_lowercase())
        })
        .collect()
}

fn has_concrete_method_implementation(
    classes: &PhpClassTable,
    abstract_methods: &HashSet<(ClassId, String)>,
    class_id: ClassId,
    own_abstract_methods: &HashSet<String>,
    method_lookup_name: &str,
) -> bool {
    if classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .method(method_lookup_name)
        .is_some()
    {
        return !own_abstract_methods.contains(method_lookup_name);
    }

    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();
    while let Some(current_id) = current {
        let current_class = classes
            .get(current_id)
            .expect("class id should resolve to class metadata");
        if current_class.method(method_lookup_name).is_some() {
            return !abstract_methods.contains(&(current_id, method_lookup_name.to_string()));
        }
        current = current_class.parent_id();
    }

    false
}

fn validate_final_method_override(
    classes: &PhpClassTable,
    class_id: ClassId,
    class_name: &str,
    method: &ClassMethodDecl,
    final_methods: &HashMap<(ClassId, String), String>,
) -> RuntimeResult<()> {
    let method_lookup_name = method.function.name.to_ascii_lowercase();
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        if let Some(parent_method_name) =
            final_methods.get(&(parent_id, method_lookup_name.clone()))
        {
            return Err(RuntimeError::unsupported_class_inheritance(
                class_name,
                format!(
                    "cannot override final method {}::{}()",
                    parent.name(),
                    parent_method_name
                ),
            ));
        }

        current = parent.parent_id();
    }

    Ok(())
}

fn validate_inherited_method_visibility_compatibility(
    classes: &PhpClassTable,
    class_id: ClassId,
    class_name: &str,
    method: &ClassMethodDecl,
) -> RuntimeResult<()> {
    let visibility = runtime_visibility(method.visibility);
    let method_lookup_name = method.function.name.to_ascii_lowercase();
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        if let Some(parent_method) = parent.method(&method_lookup_name) {
            if parent_method.visibility() == Visibility::Private {
                current = parent.parent_id();
                continue;
            }

            if visibility_is_more_restrictive(visibility, parent_method.visibility()) {
                return Err(RuntimeError::unsupported_class_inheritance(
                    class_name,
                    format!(
                        "method {}::{}() cannot reduce visibility of inherited {} method {}::{}()",
                        class_name,
                        method.function.name,
                        visibility_name(parent_method.visibility()),
                        parent.name(),
                        parent_method.name()
                    ),
                ));
            }

            return Ok(());
        }

        current = parent.parent_id();
    }

    Ok(())
}

fn validate_inherited_method_static_compatibility(
    classes: &PhpClassTable,
    class_id: ClassId,
    class_name: &str,
    method: &ClassMethodDecl,
) -> RuntimeResult<()> {
    let method_lookup_name = method.function.name.to_ascii_lowercase();
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        if let Some(parent_method) = parent.method(&method_lookup_name) {
            if parent_method.visibility() == Visibility::Private {
                current = parent.parent_id();
                continue;
            }

            if parent_method.is_static() != method.is_static {
                let parent_static = method_static_name(parent_method.is_static());
                let child_static = method_static_name(method.is_static);
                return Err(RuntimeError::unsupported_class_inheritance(
                    class_name,
                    format!(
                        "cannot redeclare {parent_static} method {}::{}() as {child_static} {}::{}()",
                        parent.name(),
                        parent_method.name(),
                        class_name,
                        method.function.name
                    ),
                ));
            }

            return Ok(());
        }

        current = parent.parent_id();
    }

    Ok(())
}

fn method_static_name(is_static: bool) -> &'static str {
    if is_static {
        "static"
    } else {
        "non static"
    }
}

fn validate_destructor_method_shape(
    class_name: &str,
    method: &ClassMethodDecl,
    visibility: Visibility,
) -> RuntimeResult<()> {
    if !method.function.name.eq_ignore_ascii_case("__destruct") {
        return Ok(());
    }

    if visibility != Visibility::Public {
        return Err(RuntimeError::unsupported_class_inheritance(
            class_name,
            format!(
                "destructor {}::__destruct() must be public in the current subset",
                class_name
            ),
        ));
    }

    if method.is_static {
        return Err(RuntimeError::unsupported_class_inheritance(
            class_name,
            format!(
                "destructor {}::__destruct() must be non-static in the current subset",
                class_name
            ),
        ));
    }

    if !method.function.params.is_empty() {
        return Err(RuntimeError::unsupported_class_inheritance(
            class_name,
            format!(
                "destructor {}::__destruct() cannot declare parameters in the current subset",
                class_name
            ),
        ));
    }

    Ok(())
}

fn validate_inherited_method_signature_compatibility(
    classes: &PhpClassTable,
    final_classes: &HashSet<ClassId>,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    method_signatures: &HashMap<(ClassId, String), MethodSignature>,
    class_id: ClassId,
    class_name: &str,
    method: &ClassMethodDecl,
) -> RuntimeResult<()> {
    let method_lookup_name = method.function.name.to_ascii_lowercase();
    if method_lookup_name == "__construct" {
        return Ok(());
    }

    let child_required = required_param_count(&method.function);
    let child_context = signature_type_context_for_class(classes, final_classes, class_id);
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        if let Some(parent_method) = parent.method(&method_lookup_name) {
            if parent_method.visibility() == Visibility::Private {
                current = parent.parent_id();
                continue;
            }

            let Some(parent_signature) =
                method_signatures.get(&(parent_id, method_lookup_name.clone()))
            else {
                return Ok(());
            };
            let parent_context =
                signature_type_context_for_class(classes, final_classes, parent_id);
            let child_has_variadic = method.function.params.iter().any(|param| param.is_variadic);
            let child_signature = || {
                function_decl_compatibility_signature_with_context(
                    class_name,
                    &method.function,
                    Some(child_context),
                )
            };
            let inherited_signature = || {
                method_signature_compatibility_signature_with_context(
                    parent.name(),
                    parent_method.name(),
                    Some(parent_signature),
                    Some(parent_context),
                )
            };

            if child_required > parent_signature.required_params
                || (method.function.params.len() < parent_signature.params.len()
                    && !child_has_variadic)
            {
                return Err(incompatible_declaration_error(
                    class_name,
                    child_signature(),
                    inherited_signature(),
                ));
            }

            let child_variadic_param = method
                .function
                .params
                .iter()
                .find(|param| param.is_variadic);
            for (index, parent_param) in parent_signature.params.iter().enumerate() {
                let Some(child_param) = method.function.params.get(index).or(child_variadic_param)
                else {
                    continue;
                };

                if parent_param.by_reference != child_param.by_reference {
                    return Err(incompatible_declaration_error(
                        class_name,
                        child_signature(),
                        inherited_signature(),
                    ));
                }

                match (
                    parent_param.type_decl.as_deref(),
                    child_param
                        .type_decl
                        .as_ref()
                        .map(|decl| decl.text.as_str()),
                ) {
                    (None, Some(child_type)) => {
                        let _ = child_type;
                        return Err(incompatible_declaration_error(
                            class_name,
                            child_signature(),
                            inherited_signature(),
                        ));
                    }
                    (Some(parent_type), Some(child_type))
                        if !is_compatible_parameter_type_override_with_context(
                            classes,
                            interface_lookup,
                            parent_type,
                            Some(parent_context),
                            child_type,
                            Some(child_context),
                        ) =>
                    {
                        if let Some(missing_class) =
                            unavailable_class_for_failed_signature_subtype_check(
                                classes,
                                interface_lookup,
                                parent_type,
                                Some(parent_context),
                                child_type,
                                Some(child_context),
                            )
                        {
                            return Err(could_not_check_compatibility_error(
                                class_name,
                                child_signature(),
                                inherited_signature(),
                                missing_class,
                            ));
                        }
                        return Err(incompatible_declaration_error(
                            class_name,
                            child_signature(),
                            inherited_signature(),
                        ));
                    }
                    _ => {}
                }
            }

            let child_return_type = method
                .function
                .return_type
                .as_ref()
                .map(|decl| decl.text.as_str());
            if let Some(parent_type) = parent_signature.return_type.as_deref() {
                match child_return_type {
                    None => {
                        return Err(incompatible_declaration_error(
                            class_name,
                            child_signature(),
                            inherited_signature(),
                        ));
                    }
                    Some(child_type)
                        if !is_compatible_return_type_override_with_context(
                            classes,
                            interface_lookup,
                            parent_type,
                            Some(parent_context),
                            child_type,
                            Some(child_context),
                        ) =>
                    {
                        if let Some(missing_class) =
                            unavailable_class_for_failed_signature_subtype_check(
                                classes,
                                interface_lookup,
                                child_type,
                                Some(child_context),
                                parent_type,
                                Some(parent_context),
                            )
                        {
                            return Err(could_not_check_compatibility_error(
                                class_name,
                                child_signature(),
                                inherited_signature(),
                                missing_class,
                            ));
                        }
                        return Err(incompatible_declaration_error(
                            class_name,
                            child_signature(),
                            inherited_signature(),
                        ));
                    }
                    _ => {}
                }
            } else if let (Some(parent_type), Some(child_type)) = (
                parent_signature.tentative_return_type.as_deref(),
                child_return_type,
            ) {
                if !is_compatible_return_type_override_with_context(
                    classes,
                    interface_lookup,
                    parent_type,
                    Some(parent_context),
                    child_type,
                    Some(child_context),
                ) {
                    if let Some(missing_class) =
                        unavailable_class_for_failed_signature_subtype_check(
                            classes,
                            interface_lookup,
                            child_type,
                            Some(child_context),
                            parent_type,
                            Some(parent_context),
                        )
                    {
                        return Err(could_not_check_compatibility_error(
                            class_name,
                            child_signature(),
                            inherited_signature(),
                            missing_class,
                        ));
                    }
                }
            }

            return Ok(());
        }

        current = parent.parent_id();
    }

    Ok(())
}

fn is_compatible_parameter_type_override_with_context(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    inherited_type: &str,
    inherited_context: Option<SignatureTypeContext<'_>>,
    override_type: &str,
    override_context: Option<SignatureTypeContext<'_>>,
) -> bool {
    type_name_is_subtype_of_with_context(
        classes,
        interface_lookup,
        inherited_type,
        inherited_context,
        override_type,
        override_context,
    )
}

fn is_compatible_return_type_override_with_context(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    inherited_type: &str,
    inherited_context: Option<SignatureTypeContext<'_>>,
    override_type: &str,
    override_context: Option<SignatureTypeContext<'_>>,
) -> bool {
    type_name_is_subtype_of_with_context(
        classes,
        interface_lookup,
        override_type,
        override_context,
        inherited_type,
        inherited_context,
    )
}

fn unavailable_class_for_failed_signature_subtype_check(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    subtype_context: Option<SignatureTypeContext<'_>>,
    supertype: &str,
    supertype_context: Option<SignatureTypeContext<'_>>,
) -> Option<String> {
    if type_name_is_subtype_of_with_context(
        classes,
        interface_lookup,
        subtype,
        subtype_context,
        supertype,
        supertype_context,
    ) {
        return None;
    }

    let subtype = subtype.trim();
    let supertype = supertype.trim();

    if let Some(super_members) = signature_intersection_members(supertype) {
        let mut missing = None;
        for super_member in super_members {
            if type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                super_member,
                supertype_context,
            ) {
                continue;
            }
            let Some(member_missing) = unavailable_class_for_failed_signature_subtype_check(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                super_member,
                supertype_context,
            ) else {
                return None;
            };
            missing.get_or_insert(member_missing);
        }
        return missing;
    }

    if let Some(sub_members) = signature_intersection_members(subtype) {
        return sub_members.into_iter().find_map(|sub_member| {
            unavailable_class_for_failed_signature_subtype_check(
                classes,
                interface_lookup,
                sub_member,
                subtype_context,
                supertype,
                supertype_context,
            )
        });
    }

    if let Some(sub_members) = signature_union_members(subtype) {
        let mut missing = None;
        for sub_member in sub_members {
            if type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                sub_member,
                subtype_context,
                supertype,
                supertype_context,
            ) {
                continue;
            }
            let Some(member_missing) = unavailable_class_for_failed_signature_subtype_check(
                classes,
                interface_lookup,
                sub_member,
                subtype_context,
                supertype,
                supertype_context,
            ) else {
                return None;
            };
            missing.get_or_insert(member_missing);
        }
        return missing;
    }

    if let Some(super_members) = signature_union_members(supertype) {
        return super_members.into_iter().find_map(|super_member| {
            unavailable_class_for_failed_signature_subtype_check(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                super_member,
                supertype_context,
            )
        });
    }

    if signature_type_is_static_keyword(supertype) {
        return None;
    }

    let subtype = resolve_relative_signature_type(subtype, subtype_context);
    let supertype = resolve_relative_signature_type(supertype, supertype_context);

    if subtype.eq_ignore_ascii_case(&supertype) {
        return None;
    }

    if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "mixed") {
        return None;
    }

    if normalized_builtin_signature_type(subtype.as_ref()).is_some_and(|ty| ty == "never") {
        return None;
    }

    if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "iterable") {
        return unavailable_class_for_failed_signature_subtype_check(
            classes,
            interface_lookup,
            subtype.as_ref(),
            subtype_context,
            "array",
            None,
        )
        .or_else(|| {
            unavailable_class_for_failed_signature_subtype_check(
                classes,
                interface_lookup,
                subtype.as_ref(),
                subtype_context,
                "Traversable",
                None,
            )
        });
    }

    if normalized_builtin_signature_type(subtype.as_ref()).is_some()
        && normalized_builtin_signature_type(supertype.as_ref()).is_some()
    {
        return None;
    }

    let Some(subtype_class_like) = simple_class_like_signature_type(subtype.as_ref()) else {
        return None;
    };
    let Some(supertype_class_like) = simple_class_like_signature_type(supertype.as_ref()) else {
        if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "object") {
            return unavailable_resolved_signature_class_name(
                classes,
                interface_lookup,
                subtype_class_like,
            );
        }
        return None;
    };

    unavailable_resolved_signature_class_name(classes, interface_lookup, subtype_class_like)
        .or_else(|| {
            unavailable_resolved_signature_class_name(
                classes,
                interface_lookup,
                supertype_class_like,
            )
        })
}

fn unavailable_resolved_signature_class_name(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_like: &str,
) -> Option<String> {
    let class_like = class_like.strip_prefix('\\').unwrap_or(class_like);
    if classes.lookup_class_id(class_like).is_some()
        || interface_lookup.contains_key(&class_like.to_ascii_lowercase())
        || is_core_interface_name(class_like)
    {
        return None;
    }

    Some(class_like.to_string())
}

fn signature_class_like_type_is_available(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_like: &str,
) -> bool {
    unavailable_resolved_signature_class_name(classes, interface_lookup, class_like).is_none()
}

fn type_name_is_subtype_of(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    supertype: &str,
) -> bool {
    type_name_is_subtype_of_with_context(classes, interface_lookup, subtype, None, supertype, None)
}

fn type_name_is_subtype_of_with_context(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    subtype_context: Option<SignatureTypeContext<'_>>,
    supertype: &str,
    supertype_context: Option<SignatureTypeContext<'_>>,
) -> bool {
    let subtype = subtype.trim();
    let supertype = supertype.trim();

    if let Some(super_members) = signature_intersection_members(supertype) {
        return super_members.iter().all(|supertype| {
            type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                supertype,
                supertype_context,
            )
        });
    }

    if let Some(subtypes) = signature_union_members(subtype) {
        return subtypes.iter().all(|subtype| {
            type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                supertype,
                supertype_context,
            )
        });
    }

    if normalized_builtin_signature_type(subtype).is_some_and(|ty| ty == "iterable") {
        return type_name_is_subtype_of_with_context(
            classes,
            interface_lookup,
            "array",
            None,
            supertype,
            supertype_context,
        ) && type_name_is_subtype_of_with_context(
            classes,
            interface_lookup,
            "Traversable",
            None,
            supertype,
            supertype_context,
        );
    }

    if let Some(supertypes) = signature_union_members(supertype) {
        return supertypes.iter().any(|supertype| {
            type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                supertype,
                supertype_context,
            )
        });
    }

    if let Some(sub_members) = signature_intersection_members(subtype) {
        return sub_members.iter().any(|subtype| {
            type_name_is_subtype_of_with_context(
                classes,
                interface_lookup,
                subtype,
                subtype_context,
                supertype,
                supertype_context,
            )
        });
    }

    if signature_type_is_static_keyword(supertype) {
        return signature_static_supertype_accepts_subtype(classes, subtype, subtype_context);
    }

    let subtype = resolve_relative_signature_type(subtype, subtype_context);
    let supertype = resolve_relative_signature_type(supertype, supertype_context);

    if subtype.eq_ignore_ascii_case(&supertype) {
        return true;
    }

    if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "mixed") {
        return !normalized_builtin_signature_type(subtype.as_ref()).is_some_and(|ty| ty == "void");
    }

    if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "callable") {
        return normalized_builtin_signature_type(subtype.as_ref())
            .is_some_and(|ty| ty == "callable")
            || subtype.eq_ignore_ascii_case("Closure");
    }

    if normalized_builtin_signature_type(subtype.as_ref()).is_some_and(|ty| ty == "never") {
        return true;
    }

    if signature_type_is_static_keyword(supertype.as_ref()) {
        return signature_type_is_static_keyword(subtype.as_ref());
    }

    if normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| ty == "iterable") {
        return type_name_is_subtype_of_with_context(
            classes,
            interface_lookup,
            subtype.as_ref(),
            subtype_context,
            "array",
            None,
        ) || type_name_is_subtype_of_with_context(
            classes,
            interface_lookup,
            subtype.as_ref(),
            subtype_context,
            "Traversable",
            None,
        );
    }

    if let (Some(subtype), Some(supertype)) = (
        normalized_builtin_signature_type(subtype.as_ref()),
        normalized_builtin_signature_type(supertype.as_ref()),
    ) {
        return subtype == supertype
            || (subtype == "false" && supertype == "bool")
            || (subtype == "true" && supertype == "bool");
    }

    let Some(subtype) = simple_class_like_signature_type(subtype.as_ref()) else {
        return false;
    };
    let Some(supertype) = simple_class_like_signature_type(supertype.as_ref()) else {
        return normalized_builtin_signature_type(supertype.as_ref()).is_some_and(|ty| {
            ty == "object"
                && signature_class_like_type_is_available(classes, interface_lookup, subtype)
        });
    };

    let subtype_class_id = classes.lookup_class_id(subtype);
    let supertype_class_id = classes.lookup_class_id(supertype);
    if let (Some(subtype_class_id), Some(supertype_class_id)) =
        (subtype_class_id, supertype_class_id)
    {
        return subtype_class_id == supertype_class_id
            || classes.is_subclass_of(subtype_class_id, supertype_class_id);
    }

    let supertype_interface_key = supertype.to_ascii_lowercase();
    if let Some(subtype_class_id) = subtype_class_id {
        return (interface_lookup.contains_key(&supertype_interface_key)
            || is_core_interface_name(supertype))
            && class_implements_signature_interface(
                classes,
                interface_lookup,
                subtype_class_id,
                supertype,
            );
    }

    if (interface_lookup.contains_key(&subtype.to_ascii_lowercase())
        || is_core_interface_name(subtype))
        && (interface_lookup.contains_key(&supertype_interface_key)
            || is_core_interface_name(supertype))
    {
        return interface_extends_or_matches_interface(interface_lookup, subtype, supertype);
    }

    false
}

fn signature_type_is_static_keyword(type_name: &str) -> bool {
    type_name
        .trim()
        .strip_prefix('\\')
        .unwrap_or_else(|| type_name.trim())
        .eq_ignore_ascii_case("static")
}

fn signature_static_supertype_accepts_subtype(
    classes: &PhpClassTable,
    subtype: &str,
    subtype_context: Option<SignatureTypeContext<'_>>,
) -> bool {
    if normalized_builtin_signature_type(subtype).is_some_and(|ty| ty == "never") {
        return true;
    }
    if signature_type_is_static_keyword(subtype) {
        return true;
    }

    let Some(context) = subtype_context else {
        return false;
    };
    context.is_final && signature_type_resolves_to_context_self(classes, subtype, context)
}

fn signature_type_resolves_to_context_self(
    classes: &PhpClassTable,
    type_name: &str,
    context: SignatureTypeContext<'_>,
) -> bool {
    let trimmed = type_name.trim();
    let candidate = match trimmed
        .strip_prefix('\\')
        .unwrap_or(trimmed)
        .to_ascii_lowercase()
        .as_str()
    {
        "self" => context.self_name,
        "parent" | "static" => return false,
        _ => match simple_class_like_signature_type(trimmed) {
            Some(name) => name,
            None => return false,
        },
    };

    match (
        classes.lookup_class_id(candidate),
        classes.lookup_class_id(context.self_name),
    ) {
        (Some(candidate_id), Some(context_id)) => candidate_id == context_id,
        _ => candidate
            .strip_prefix('\\')
            .unwrap_or(candidate)
            .eq_ignore_ascii_case(
                context
                    .self_name
                    .strip_prefix('\\')
                    .unwrap_or(context.self_name),
            ),
    }
}

fn union_members_in_php_display_order(parts: Vec<&str>) -> Vec<&str> {
    let has_builtin = parts
        .iter()
        .any(|part| signature_union_arm_is_builtin(part));
    let has_non_builtin = parts
        .iter()
        .any(|part| !signature_union_arm_is_builtin(part));
    if !has_builtin || !has_non_builtin {
        return parts;
    }

    let mut ordered = parts
        .iter()
        .copied()
        .filter(|part| !signature_union_arm_is_builtin(part))
        .collect::<Vec<_>>();
    ordered.extend(
        parts
            .iter()
            .copied()
            .filter(|part| signature_union_arm_is_builtin(part)),
    );
    ordered
}

fn signature_union_arm_is_builtin(type_name: &str) -> bool {
    let type_name = strip_wrapping_type_parens(type_name.trim());
    if split_type_decl_top_level(type_name, '&').len() > 1
        || split_type_decl_top_level(type_name, '|').len() > 1
    {
        return false;
    }
    let type_name = type_name.strip_prefix('?').unwrap_or(type_name).trim();
    normalized_builtin_signature_type(type_name).is_some()
}

fn signature_intersection_members(type_name: &str) -> Option<Vec<&str>> {
    let type_name = strip_wrapping_type_parens(type_name.trim());
    if split_type_decl_top_level(type_name, '|').len() > 1 {
        return None;
    }
    let members = split_type_decl_top_level(type_name, '&');
    (members.len() > 1).then(|| members.into_iter().map(str::trim).collect())
}

fn signature_union_members(type_name: &str) -> Option<Vec<&str>> {
    let type_name = strip_wrapping_type_parens(type_name.trim());
    if let Some(nullable) = type_name.strip_prefix('?') {
        return Some(vec![nullable.trim(), "null"]);
    }
    let members = split_type_decl_top_level(type_name, '|');
    (members.len() > 1).then(|| members.into_iter().map(str::trim).collect())
}

fn resolve_relative_signature_type<'a>(
    type_name: &'a str,
    context: Option<SignatureTypeContext<'a>>,
) -> Cow<'a, str> {
    let Some(context) = context else {
        return Cow::Borrowed(type_name);
    };
    match type_name.trim().to_ascii_lowercase().as_str() {
        "self" => Cow::Borrowed(context.self_name),
        "parent" => context
            .parent_name
            .map(Cow::Borrowed)
            .unwrap_or_else(|| Cow::Borrowed(type_name)),
        "static" => Cow::Borrowed(context.self_name),
        _ => Cow::Borrowed(type_name),
    }
}

fn normalized_builtin_signature_type(type_name: &str) -> Option<&'static str> {
    match type_name.trim().to_ascii_lowercase().as_str() {
        "array" => Some("array"),
        "bool" | "boolean" => Some("bool"),
        "callable" => Some("callable"),
        "false" => Some("false"),
        "float" | "double" => Some("float"),
        "int" | "integer" => Some("int"),
        "iterable" => Some("iterable"),
        "mixed" => Some("mixed"),
        "never" => Some("never"),
        "null" => Some("null"),
        "object" => Some("object"),
        "string" => Some("string"),
        "true" => Some("true"),
        "void" => Some("void"),
        _ => None,
    }
}

fn simple_class_like_signature_type(type_name: &str) -> Option<&str> {
    if type_name.starts_with('?')
        || type_name.contains('|')
        || type_name.contains('&')
        || matches!(
            type_name.to_ascii_lowercase().as_str(),
            "array"
                | "bool"
                | "boolean"
                | "callable"
                | "false"
                | "float"
                | "double"
                | "int"
                | "integer"
                | "iterable"
                | "mixed"
                | "never"
                | "null"
                | "object"
                | "parent"
                | "self"
                | "static"
                | "string"
                | "true"
                | "void"
        )
    {
        return None;
    }

    let stripped = type_name.strip_prefix('\\').unwrap_or(type_name);
    (!stripped.is_empty()).then_some(stripped)
}

fn interface_extends_interface(
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    supertype: &str,
) -> bool {
    let Some(interface) = interface_lookup.get(&subtype.to_ascii_lowercase()) else {
        return false;
    };
    let mut parent_keys = HashSet::new();
    collect_parent_interface_keys(interface_lookup, interface, &mut parent_keys);
    parent_keys.contains(&supertype.to_ascii_lowercase())
}

fn interface_extends_or_matches_interface(
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    subtype: &str,
    supertype: &str,
) -> bool {
    if subtype.eq_ignore_ascii_case(supertype) {
        return true;
    }
    if interface_extends_interface(interface_lookup, subtype, supertype) {
        return true;
    }
    core_interface_extends_interface(subtype, supertype)
}

fn core_interface_extends_interface(subtype: &str, supertype: &str) -> bool {
    let mut pending = core_interface_parent_names(subtype)
        .iter()
        .copied()
        .collect::<Vec<_>>();
    let mut visited = HashSet::new();
    while let Some(interface_name) = pending.pop() {
        let key = interface_name.to_ascii_lowercase();
        if !visited.insert(key) {
            continue;
        }
        if interface_name.eq_ignore_ascii_case(supertype) {
            return true;
        }
        pending.extend(core_interface_parent_names(interface_name).iter().copied());
    }
    false
}

fn validate_inherited_property_compatibility(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_id: ClassId,
    class_name: &str,
    property: &ClassPropertyDecl,
) -> RuntimeResult<()> {
    let visibility = runtime_visibility(property.visibility);
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");

        if let Some(parent_property) = parent.property(&property.name) {
            if parent_property.visibility() == Visibility::Private {
                current = parent.parent_id();
                continue;
            }

            if parent_property.is_static() != property.is_static {
                let parent_static = if parent_property.is_static() {
                    "static"
                } else {
                    "non static"
                };
                let child_static = if property.is_static {
                    "static"
                } else {
                    "non static"
                };
                return Err(RuntimeError::unsupported_class_inheritance(
                    class_name,
                    format!(
                        "cannot redeclare {parent_static} property {}::${} as {child_static} {}::${}",
                        parent.name(),
                        property.name,
                        class_name,
                        property.name
                    ),
                ));
            }

            let child_type = property.type_decl.as_ref().map(|decl| decl.text.as_str());
            if !runtime_property_types_are_invariantly_compatible(
                classes,
                interface_lookup,
                parent_property.type_decl(),
                child_type,
            ) {
                return Err(RuntimeError::unsupported_class_inheritance(
                    class_name,
                    format!(
                        "property {}::${} type metadata must match inherited property {}::${}",
                        class_name,
                        property.name,
                        parent.name(),
                        property.name
                    ),
                ));
            }

            if visibility_is_more_restrictive(visibility, parent_property.visibility()) {
                return Err(RuntimeError::unsupported_class_inheritance(
                    class_name,
                    format!(
                        "property {}::${} cannot reduce visibility of inherited {} property {}::${}",
                        class_name,
                        property.name,
                        visibility_name(parent_property.visibility()),
                        parent.name(),
                        property.name
                    ),
                ));
            }

            return Ok(());
        }

        current = parent.parent_id();
    }

    Ok(())
}

fn runtime_property_types_are_invariantly_compatible(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    parent_type: Option<&str>,
    child_type: Option<&str>,
) -> bool {
    match (parent_type, child_type) {
        (None, None) => true,
        (Some(parent_type), Some(child_type)) if parent_type == child_type => true,
        (Some(parent_type), Some(child_type)) => {
            type_name_is_subtype_of(classes, interface_lookup, child_type, parent_type)
                && type_name_is_subtype_of(classes, interface_lookup, parent_type, child_type)
        }
        _ => false,
    }
}

fn validate_property_override_attribute(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_id: ClassId,
    class_name: &str,
    property: &ClassPropertyDecl,
) -> RuntimeResult<()> {
    if !property_has_override_attribute(property) {
        return Ok(());
    }
    if class_has_non_private_parent_property(classes, class_id, &property.name)
        || class_implements_interface_property(classes, interface_lookup, class_id, &property.name)
    {
        return Ok(());
    }
    Err(RuntimeError::attribute_override_missing_property(
        class_name,
        &property.name,
    ))
}

fn class_has_non_private_parent_property(
    classes: &PhpClassTable,
    class_id: ClassId,
    property_name: &str,
) -> bool {
    let mut current = classes
        .get(class_id)
        .expect("class id should resolve to class metadata")
        .parent_id();

    while let Some(parent_id) = current {
        let parent = classes
            .get(parent_id)
            .expect("parent class id should resolve to class metadata");
        if let Some(parent_property) = parent.property(property_name) {
            if parent_property.visibility() != Visibility::Private {
                return true;
            }
        }
        current = parent.parent_id();
    }

    false
}

fn class_implements_interface_property(
    classes: &PhpClassTable,
    interface_lookup: &HashMap<String, Rc<InterfaceDecl>>,
    class_id: ClassId,
    property_name: &str,
) -> bool {
    let mut visited = HashSet::new();
    for interface_name in implemented_interface_names(classes, class_id) {
        let Some(interface) = interface_lookup.get(&interface_name.to_ascii_lowercase()) else {
            continue;
        };
        if interface_has_property(interface_lookup, interface, property_name, &mut visited) {
            return true;
        }
    }
    false
}

fn visibility_is_more_restrictive(child: Visibility, parent: Visibility) -> bool {
    visibility_rank(child) > visibility_rank(parent)
}

fn visibility_rank(visibility: Visibility) -> u8 {
    match visibility {
        Visibility::Public => 0,
        Visibility::Protected => 1,
        Visibility::Private => 2,
    }
}

fn visibility_name(visibility: Visibility) -> &'static str {
    match visibility {
        Visibility::Public => "public",
        Visibility::Protected => "protected",
        Visibility::Private => "private",
    }
}

fn runtime_visibility(visibility: ClassVisibility) -> Visibility {
    match visibility {
        ClassVisibility::Public => Visibility::Public,
        ClassVisibility::Protected => Visibility::Protected,
        ClassVisibility::Private => Visibility::Private,
    }
}

fn reflection_name_short_name(name: &str) -> String {
    name.rsplit('\\').next().unwrap_or(name).to_string()
}

fn reflection_name_namespace_name(name: &str) -> String {
    name.rsplit_once('\\')
        .map(|(namespace, _)| namespace.to_string())
        .unwrap_or_default()
}

fn reflection_name_in_namespace(name: &str) -> bool {
    name.contains('\\')
}

fn reflection_method_name_parts(name: &str, span: Span) -> CompileResult<(String, String)> {
    let Some((class_name, method_name)) = name.split_once("::") else {
        return Err(reflection_exception_error(
            span,
            "ReflectionMethod::createFromMethodName(): Argument #1 ($method) must be a valid method name",
        ));
    };
    if class_name.is_empty() || method_name.is_empty() || method_name.contains("::") {
        return Err(reflection_exception_error(
            span,
            "ReflectionMethod::createFromMethodName(): Argument #1 ($method) must be a valid method name",
        ));
    }
    Ok((class_name.to_string(), method_name.to_string()))
}

fn reflection_class_target_string(value: &Value) -> Option<String> {
    match value {
        Value::String(name) => Some(name.clone()),
        Value::Object(object) => Some(object.class_name().to_string()),
        _ => None,
    }
}

fn reflection_exception_error(span: Span, message: impl Into<String>) -> Diagnostic {
    Diagnostic::new(
        Phase::Runtime,
        span.line,
        span.column,
        format!("ReflectionException: {}", message.into()),
    )
}

fn reflection_method_constructor_argument_count_error(actual: usize, span: Span) -> Diagnostic {
    let message = if actual < 1 {
        format!("ReflectionMethod::__construct() expects at least 1 argument, {actual} given")
    } else {
        format!("ReflectionMethod::__construct() expects at most 2 arguments, {actual} given")
    };
    Diagnostic::new(Phase::Runtime, span.line, span.column, message)
}

fn reflection_method_invoke_argument_count_error(actual: usize, span: Span) -> Diagnostic {
    Diagnostic::new(
        Phase::Runtime,
        span.line,
        span.column,
        format!("ReflectionMethod::invoke() expects at least 1 argument, {actual} given"),
    )
}

fn reflection_method_abstract_invoke_error(
    state: &ReflectionMethodState,
    span: Span,
) -> Diagnostic {
    reflection_exception_error(
        span,
        format!(
            "Trying to invoke abstract method {}::{}()",
            state.declaring_class_name, state.name
        ),
    )
}

fn reflection_method_invoke_object_type_error(value: &Value, span: Span) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(
            "ReflectionMethod::invoke()",
            format!(
                "Argument #1 ($object) must be of type ?object, {} given",
                php_type_error_given(value)
            ),
        ),
    )
}

fn reflection_property_too_many_arguments_error(
    method_name: &'static str,
    max: usize,
    actual: usize,
    span: Span,
) -> Diagnostic {
    let noun = if max == 1 { "argument" } else { "arguments" };
    Diagnostic::new(
        Phase::Runtime,
        span.line,
        span.column,
        format!("{method_name}() expects at most {max} {noun}, {actual} given"),
    )
}

fn reflection_property_missing_instance_error(method_name: &'static str, span: Span) -> Diagnostic {
    Diagnostic::new(
        Phase::Runtime,
        span.line,
        span.column,
        format!("{method_name}(): Argument #1 ($object) must be provided for instance properties"),
    )
}

fn reflection_class_static_property_argument_error(
    method: &'static str,
    message: impl Into<String>,
    span: Span,
) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(format!("{method}()"), message.into()),
    )
}

fn reflection_property_non_instance_error(span: Span) -> Diagnostic {
    reflection_exception_error(
        span,
        "Given object is not an instance of the class this property was declared in",
    )
}

fn reflection_method_invoke_non_instance_error(span: Span) -> Diagnostic {
    reflection_exception_error(
        span,
        "Given object is not an instance of the class this method was declared in",
    )
}

fn reflection_method_invoke_args_array_type_error(value: &Value, span: Span) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(
            "ReflectionMethod::invokeArgs()",
            format!(
                "Argument #2 ($args) must be of type array, {} given",
                php_type_error_given(value)
            ),
        ),
    )
}

fn reflection_method_invoke_args_error_from_call_user_func_array(error: Diagnostic) -> Diagnostic {
    let Some(message) = error
        .message
        .strip_prefix("unsupported call call_user_func_array(): ")
        .map(str::to_string)
    else {
        return error;
    };
    if !message.starts_with("Argument #2 ($args) must be of type array, ") {
        return error;
    }
    Diagnostic {
        message: format!("unsupported call ReflectionMethod::invokeArgs(): {message}"),
        ..error
    }
}

impl PendingUncaughtCallFrame {
    fn display_callable(&self, file: &str) -> String {
        if self.function_name == "{closure}" {
            format!("{{closure:{file}:{}}}", self.function_line)
        } else {
            self.function_name.clone()
        }
    }

    fn is_core_attribute_constructor(&self) -> bool {
        matches!(
            self.function_name.as_str(),
            "Deprecated->__construct" | "NoDiscard->__construct"
        )
    }
}

fn format_stack_trace_args(args: &[Value]) -> String {
    args.iter()
        .map(format_stack_trace_arg)
        .collect::<Vec<_>>()
        .join(", ")
}

fn pending_frame_matches_call_argument_callable(
    frame: &PendingUncaughtCallFrame,
    callable: &str,
) -> bool {
    let callable_name = callable.strip_suffix("()").unwrap_or(callable);
    callable_names_match_pending_frame(callable_name, &frame.function_name)
        || (frame.function_name == "{closure}" && callable_name.starts_with("{closure:"))
}

fn callable_names_match_pending_frame(callable: &str, frame_callable: &str) -> bool {
    callable == frame_callable
        || callable.replace("::", "->") == frame_callable
        || callable.replace("->", "::") == frame_callable
}

fn format_call_trace_callable_with_args(callable: &str, args: &[Value]) -> String {
    let args = format_stack_trace_args(args);
    if let Some(callable) = callable.strip_suffix("()") {
        return format!("{callable}({args})");
    }
    format!("{callable}({args})")
}

fn format_stack_trace_arg(value: &Value) -> String {
    match value {
        Value::Null => "NULL".to_string(),
        Value::Bool(value) => {
            if *value {
                "true".to_string()
            } else {
                "false".to_string()
            }
        }
        Value::Int(value) => value.to_string(),
        Value::Float(value) => value.to_string(),
        Value::String(value) => format_stack_trace_string_arg(value),
        Value::BinaryString(value) => {
            format_stack_trace_string_arg(&String::from_utf8_lossy(value))
        }
        Value::Array(_) => "Array".to_string(),
        Value::Object(object) => enum_like_case_name(object)
            .map(|case_name| format!("{}::{case_name}", object.class_name()))
            .unwrap_or_else(|| format!("Object({})", object.class_name())),
        Value::Closure(_) => "Object(Closure)".to_string(),
        Value::Resource(id) => format!("Resource id #{id}"),
    }
}

fn format_stack_trace_string_arg(value: &str) -> String {
    const STACK_TRACE_STRING_PREVIEW_CHARS: usize = 15;
    let preview = value
        .chars()
        .take(STACK_TRACE_STRING_PREVIEW_CHARS)
        .collect::<String>();
    if value.chars().count() > STACK_TRACE_STRING_PREVIEW_CHARS {
        format!("'{preview}...'")
    } else {
        format!("'{preview}'")
    }
}

fn normalized_attribute_name(name: &str) -> String {
    name.trim_start_matches('\\').to_ascii_lowercase()
}

fn core_class_attributes_for_reflection(name: &str) -> Vec<AttributeDecl> {
    if name.eq_ignore_ascii_case("Attribute") {
        return vec![AttributeDecl::new(
            "Attribute".to_string(),
            Some("(Attribute::TARGET_CLASS)".to_string()),
        )];
    }
    if name.eq_ignore_ascii_case("Deprecated") {
        return vec![AttributeDecl::new(
            "Attribute".to_string(),
            Some("(Attribute::TARGET_ALL)".to_string()),
        )];
    }
    if name.eq_ignore_ascii_case("NoDiscard") {
        return vec![AttributeDecl::new(
            "Attribute".to_string(),
            Some("(Attribute::TARGET_FUNCTION | Attribute::TARGET_METHOD)".to_string()),
        )];
    }
    Vec::new()
}

