fn metadata_exists_class_like_name(
    function_name: &'static str,
    value: &Value,
    span: Span,
) -> CompileResult<Option<String>> {
    match value {
        Value::String(name) => Ok(Some(name.clone())),
        Value::BinaryString(bytes) => Ok(String::from_utf8(bytes.clone()).ok()),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => {
            Ok(Some(value.echo_string()))
        }
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                format!(
                    "class-like name argument must be string-compatible scalar in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn normalize_leading_namespace_separator(name: &str) -> &str {
    name.strip_prefix('\\').unwrap_or(name)
}

fn metadata_exists_autoload_flag(
    function_name: &'static str,
    value: &Value,
    span: Span,
) -> CompileResult<bool> {
    match value {
        Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::String(_) => {
            Ok(value.is_truthy())
        }
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                format!(
                    "autoload argument must be bool-like scalar in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn is_array_callable_syntax_shape(array: &PhpArray) -> bool {
    array_callable_parts(array).is_some()
}

fn callable_name_output(value: &Value) -> String {
    match value {
        Value::Array(array) => array_callable_parts(array)
            .map(|(target, method_name)| match target {
                Value::Object(object) => format!("{}::{method_name}", object.class_name()),
                Value::String(class_name) => format!("{class_name}::{method_name}"),
                _ => "Array".to_string(),
            })
            .unwrap_or_else(|| "Array".to_string()),
        Value::Object(object) => format!("{}::__invoke", object.class_name()),
        Value::Closure(_) => "Closure::__invoke".to_string(),
        Value::Resource(id) => format!("Resource id #{id}"),
        other => other.try_echo_string().unwrap_or_default(),
    }
}

fn is_array_callable_resolved(classes: &PhpClassTable, array: &PhpArray) -> bool {
    let Some((target, method_name)) = array_callable_parts(array) else {
        return false;
    };

    match target {
        Value::Object(object) => classes
            .get(object.class_id())
            .and_then(|class| class.method(method_name))
            .is_some_and(|method| method.visibility() == Visibility::Public),
        Value::String(class_name) => classes
            .lookup_class(class_name)
            .and_then(|class| class.method(method_name))
            .is_some_and(|method| method.visibility() == Visibility::Public && method.is_static()),
        _ => false,
    }
}

fn has_public_non_static_magic_call(classes: &PhpClassTable, class_id: ClassId) -> bool {
    find_method(classes, class_id, "__call").is_some_and(|(_, _, method)| {
        method.visibility() == Visibility::Public && !method.is_static()
    })
}

fn has_public_static_magic_call_static(classes: &PhpClassTable, class_id: ClassId) -> bool {
    find_method(classes, class_id, "__callStatic").is_some_and(|(_, _, method)| {
        method.visibility() == Visibility::Public && method.is_static()
    })
}

fn forbidden_dynamic_builtin_name(name: &str) -> Option<&'static str> {
    let unqualified = name.strip_prefix('\\').unwrap_or(name);
    if unqualified.contains('\\') {
        return None;
    }

    match unqualified.to_ascii_lowercase().as_str() {
        "extract" => Some("extract"),
        "compact" => Some("compact"),
        "get_defined_vars" => Some("get_defined_vars"),
        "func_get_args" => Some("func_get_args"),
        "func_get_arg" => Some("func_get_arg"),
        "func_num_args" => Some("func_num_args"),
        _ => None,
    }
}

fn forbidden_dynamic_builtin_call_error(name: &str, span: Span) -> Option<Diagnostic> {
    forbidden_dynamic_builtin_name(name).map(|canonical| {
        runtime_error(
            span,
            RuntimeError::forbidden_dynamic_call(callable_name(canonical)),
        )
    })
}

fn forbidden_dynamic_builtin_call_user_func_error(
    callback_expr: &Expr,
    name: &str,
    span: Span,
) -> Option<Diagnostic> {
    if call_user_func_literal_scope_frame_builtin(callback_expr, name) {
        return None;
    }
    forbidden_dynamic_builtin_call_error(name, span)
}

fn call_user_func_literal_scope_frame_builtin(callback_expr: &Expr, name: &str) -> bool {
    let Expr::String(literal, _) = callback_expr else {
        return false;
    };
    if literal.contains('\\') || name.contains('\\') {
        return false;
    }
    let literal = literal.to_ascii_lowercase();
    if literal.as_str() != name.to_ascii_lowercase() {
        return false;
    }
    matches!(
        literal.as_str(),
        "func_get_args" | "func_get_arg" | "func_num_args"
    )
}

fn is_forbidden_dynamic_builtin_call_diagnostic(error: &Diagnostic) -> bool {
    error.phase == Phase::Runtime
        && forbidden_dynamic_builtin_name(
            error
                .message
                .strip_prefix("Cannot call ")
                .and_then(|message| message.strip_suffix(" dynamically"))
                .and_then(|callable| callable.strip_suffix("()"))
                .unwrap_or(""),
        )
        .is_some()
}

const DATETIMEZONE_INVALID_SERIALIZATION_MESSAGE: &str =
    "Invalid serialization data for DateTimeZone object";
const DATETIME_INVALID_SERIALIZATION_MESSAGE: &str =
    "Invalid serialization data for DateTime object";
const DATETIMEIMMUTABLE_INVALID_SERIALIZATION_MESSAGE: &str =
    "Invalid serialization data for DateTimeImmutable object";
const DATEPERIOD_INVALID_SERIALIZATION_MESSAGE: &str =
    "Invalid serialization data for DatePeriod object";
const DATEPERIOD_CONSTRUCTOR_TYPE_MESSAGE: &str =
    "DatePeriod::__construct() accepts (DateTimeInterface, DateInterval, int [, int]), or (DateTimeInterface, DateInterval, DateTime [, int]), or (string [, int]) as arguments";
const DATE_OBJECT_ERROR_DIAGNOSTIC_PREFIX: &str = "DateObjectError: ";
const DATE_RANGE_ERROR_DIAGNOSTIC_PREFIX: &str = "DateRangeError: ";
const DATE_EXCEPTION_DIAGNOSTIC_PREFIX: &str = "DateException: ";
const DATE_MALFORMED_STRING_DIAGNOSTIC_PREFIX: &str = "DateMalformedStringException: ";
const DATE_MALFORMED_INTERVAL_DIAGNOSTIC_PREFIX: &str = "DateMalformedIntervalStringException: ";
const DATE_MALFORMED_PERIOD_DIAGNOSTIC_PREFIX: &str = "DateMalformedPeriodStringException: ";

