fn reflection_constructor_argument_count_error_message(error: &Diagnostic) -> Option<String> {
    if error.phase != Phase::Runtime {
        return None;
    }
    let message = error
        .message
        .strip_prefix("unsupported call ")?
        .split_once(": ")
        .map(|(_, message)| message)?;
    for (class_name, expected) in [
        ("ReflectionClass", 1usize),
        ("ReflectionExtension", 1usize),
        ("ReflectionFunction", 1usize),
        ("ReflectionZendExtension", 1usize),
        ("ReflectionParameter", 2usize),
        ("ReflectionProperty", 2usize),
    ] {
        let prefix = format!("{class_name}::__construct() expects exactly {expected} argument");
        if message.starts_with(&prefix) && message.ends_with(" given") {
            return Some(message.to_string());
        }
    }
    None
}

fn user_function_too_few_arguments_message(error: &Diagnostic) -> Option<String> {
    if error.phase != Phase::Runtime {
        return None;
    }

    let rest = error.message.strip_prefix("arity mismatch for ")?;
    let (callable, expectation) = rest.split_once(": expected ")?;
    let (expected, actual) = expectation.split_once(" argument(s), got ")?;
    let expected = expected.parse::<usize>().ok()?;
    let actual = actual.parse::<usize>().ok()?;
    if actual >= expected {
        return None;
    }

    let source = error
        .file
        .as_ref()
        .map(|file| file.display().to_string())
        .unwrap_or_else(|| "Command line code".to_string());
    Some(format!(
        "Too few arguments to function {callable}, {actual} passed in {source} on line {} and exactly {expected} expected",
        error.line
    ))
}

