fn fgetcsv_parameter_index(name: &str) -> Option<usize> {
    match name {
        "stream" | "handle" => Some(0),
        "length" => Some(1),
        "separator" | "delimiter" => Some(2),
        "enclosure" => Some(3),
        "escape" => Some(4),
        _ => None,
    }
}

fn fputcsv_parameter_index(name: &str) -> Option<usize> {
    match name {
        "stream" | "handle" => Some(0),
        "fields" => Some(1),
        "separator" | "delimiter" => Some(2),
        "enclosure" => Some(3),
        "escape" => Some(4),
        "eol" => Some(5),
        _ => None,
    }
}

fn csv_single_character_argument(
    function: &str,
    label: &str,
    value: Option<&Value>,
    default: char,
    allow_empty: bool,
    span: Span,
) -> CompileResult<Option<char>> {
    let Some(value) = value else {
        return Ok(Some(default));
    };
    let Value::String(value) = value else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "{label} argument must be string in the current subset, got {}",
                    value.type_name()
                ),
            ),
        ));
    };
    if allow_empty && value.is_empty() {
        return Ok(None);
    }
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument must contain exactly one character"),
            ),
        ));
    };
    if chars.next().is_some() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument must contain exactly one character"),
            ),
        ));
    }
    Ok(Some(first))
}

fn csv_record_without_line_ending(line: &str) -> &str {
    line.strip_suffix("\r\n")
        .or_else(|| line.strip_suffix('\n'))
        .or_else(|| line.strip_suffix('\r'))
        .unwrap_or(line)
}

fn csv_record_is_complete(
    line: &str,
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
) -> bool {
    !csv_record_enclosure_state(line, delimiter, enclosure, escape)
}

fn csv_record_enclosure_state(
    line: &str,
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
) -> bool {
    let mut chars = line.chars().peekable();
    let mut in_enclosure = false;
    let mut at_field_start = true;

    while let Some(character) = chars.next() {
        if in_enclosure {
            if character == enclosure {
                if chars.peek().is_some_and(|next| *next == enclosure) {
                    let _ = chars.next();
                } else {
                    in_enclosure = false;
                }
            } else if Some(character) == escape {
                let _ = chars.next();
            }
            continue;
        }

        if at_field_start && character == enclosure {
            in_enclosure = true;
            at_field_start = false;
        } else if character == delimiter {
            at_field_start = true;
        } else if at_field_start && matches!(character, ' ' | '\t') {
            continue;
        } else {
            at_field_start = false;
        }
    }

    in_enclosure
}

fn parse_bounded_csv_record(
    line: &str,
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
) -> Vec<String> {
    let record = if csv_record_is_complete(line, delimiter, enclosure, escape) {
        csv_record_without_line_ending(line)
    } else {
        line
    };
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut chars = record.chars().peekable();
    let mut in_enclosure = false;
    let mut at_field_start = true;

    while let Some(character) = chars.next() {
        if in_enclosure {
            if character == enclosure {
                if chars.peek().is_some_and(|next| *next == enclosure) {
                    field.push(enclosure);
                    chars.next();
                } else {
                    in_enclosure = false;
                }
            } else if Some(character) == escape {
                if let Some(next) = chars.next() {
                    field.push(character);
                    field.push(next);
                } else {
                    field.push(character);
                }
            } else {
                field.push(character);
            }
            at_field_start = false;
            continue;
        }

        if at_field_start && character == enclosure {
            field.clear();
            in_enclosure = true;
            at_field_start = false;
        } else if character == delimiter {
            fields.push(std::mem::take(&mut field));
            at_field_start = true;
        } else if at_field_start && matches!(character, ' ' | '\t') {
            field.push(character);
            continue;
        } else {
            field.push(character);
            at_field_start = false;
        }
    }

    if in_enclosure && escape == Some('\0') {
        field.push('\0');
    }
    fields.push(field);
    fields
}

fn format_csv_record(
    fields: &[String],
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
    eol: &str,
) -> String {
    let mut output = String::new();
    for (index, field) in fields.iter().enumerate() {
        if index > 0 {
            output.push(delimiter);
        }
        let should_enclose = field.chars().any(|ch| {
            ch == delimiter
                || ch == enclosure
                || matches!(ch, '\n' | '\r' | '\t' | ' ')
                || Some(ch) == escape
        });
        if should_enclose {
            output.push(enclosure);
            let mut previous_was_escape = false;
            for ch in field.chars() {
                if ch == enclosure && !previous_was_escape {
                    output.push(enclosure);
                    output.push(enclosure);
                } else {
                    output.push(ch);
                }
                previous_was_escape = Some(ch) == escape;
            }
            output.push(enclosure);
        } else {
            output.push_str(field);
        }
    }
    output.push_str(eol);
    output
}

fn file_lines_array(contents: &str, flags: i64, span: Span) -> CompileResult<PhpArray> {
    let ignore_new_lines = flags & PHP_FILE_IGNORE_NEW_LINES != 0;
    let skip_empty_lines = flags & PHP_FILE_SKIP_EMPTY_LINES != 0;
    let mut array = PhpArray::new();

    for raw_line in contents.split_inclusive('\n') {
        let mut line = raw_line.to_string();
        if ignore_new_lines {
            if line.ends_with('\n') {
                line.pop();
                if line.ends_with('\r') {
                    line.pop();
                }
            } else if line.ends_with('\r') {
                line.pop();
            }
        }
        if skip_empty_lines && line.is_empty() {
            continue;
        }
        array
            .append(Value::String(line))
            .map_err(|error| runtime_error(span, error))?;
    }

    Ok(array)
}

fn lexically_normalized_filesystem_path(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => match normalized.components().next_back() {
                Some(std::path::Component::Normal(_)) => {
                    normalized.pop();
                }
                Some(std::path::Component::RootDir) | Some(std::path::Component::Prefix(_)) => {}
                _ => normalized.push(".."),
            },
            std::path::Component::Normal(part) => normalized.push(part),
            std::path::Component::RootDir => normalized.push(component.as_os_str()),
            std::path::Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
        }
    }

    if normalized.as_os_str().is_empty() {
        PathBuf::from(".")
    } else {
        normalized
    }
}

fn trailing_separator_requires_directory(path: &str) -> bool {
    let Some(last) = path.chars().next_back() else {
        return false;
    };
    if last != '/' && last != '\\' {
        return false;
    }

    !path
        .trim_end_matches(|ch| ch == '/' || ch == '\\')
        .is_empty()
}

fn dirname_path(path: &str, levels: i64) -> String {
    let mut current = path.to_string();
    for _ in 0..levels {
        current = dirname_once(&current);
        if matches!(current.as_str(), "" | "." | "/") {
            break;
        }
    }
    current
}

fn dirname_once(path: &str) -> String {
    if path.is_empty() {
        return String::new();
    }

    let bytes = path.as_bytes();
    let mut end = bytes.len();
    while end > 1 && bytes[end - 1] == b'/' {
        end -= 1;
    }

    if end == 1 && bytes[0] == b'/' {
        return "/".to_string();
    }

    let trimmed = &path[..end];
    match trimmed.rfind('/') {
        Some(0) => "/".to_string(),
        Some(position) => {
            let mut parent_end = position;
            let parent_bytes = trimmed.as_bytes();
            while parent_end > 1 && parent_bytes[parent_end - 1] == b'/' {
                parent_end -= 1;
            }
            if parent_end == 0 {
                ".".to_string()
            } else {
                trimmed[..parent_end].to_string()
            }
        }
        None => ".".to_string(),
    }
}

fn basename_path(path: &str, suffix: Option<&str>) -> String {
    if path.is_empty() {
        return String::new();
    }

    let bytes = path.as_bytes();
    let mut end = bytes.len();
    while end > 0 && bytes[end - 1] == b'/' {
        end -= 1;
    }

    if end == 0 {
        return String::new();
    }

    let trimmed = &path[..end];
    let start = trimmed.rfind('/').map_or(0, |position| position + 1);
    let mut name = trimmed[start..].to_string();

    if let Some(suffix) = suffix {
        if !suffix.is_empty() && suffix.len() < name.len() && name.ends_with(suffix) {
            let new_len = name.len() - suffix.len();
            name.truncate(new_len);
        }
    }

    name
}

fn basename_path_bytes(path: &[u8], suffix: Option<&[u8]>) -> Vec<u8> {
    if path.is_empty() {
        return Vec::new();
    }

    let mut end = path.len();
    while end > 0 && path[end - 1] == b'/' {
        end -= 1;
    }
    if end == 0 {
        return Vec::new();
    }

    let trimmed = &path[..end];
    let start = trimmed
        .iter()
        .rposition(|byte| *byte == b'/')
        .map_or(0, |position| position + 1);
    let mut name = trimmed[start..].to_vec();

    if let Some(suffix) = suffix {
        if !suffix.is_empty() && suffix.len() < name.len() && name.ends_with(suffix) {
            name.truncate(name.len() - suffix.len());
        }
    }

    name
}

const PHP_HIGHLIGHT_HTML: &str = "#000000";
const PHP_HIGHLIGHT_DEFAULT: &str = "#0000BB";
const PHP_HIGHLIGHT_KEYWORD: &str = "#007700";
const PHP_HIGHLIGHT_STRING: &str = "#DD0000";
const PHP_HIGHLIGHT_COMMENT: &str = "#FF8000";

struct PhpHighlightColors {
    html: String,
    default: String,
    keyword: String,
    string: String,
    comment: String,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PhpHighlightClass {
    Html,
    Default,
    Keyword,
    String,
    Comment,
}

fn php_highlight_source_bytes(source: &[u8], colors: &PhpHighlightColors) -> String {
    let mut output = format!("<pre><code style=\"color: {}\">", colors.html);
    let mut active = PhpHighlightClass::Html;
    let mut in_double_quoted_string = false;

    for token in php_tokenizer::tokenize(source) {
        let class = php_highlight_token_class(&token, active, &mut in_double_quoted_string);
        php_highlight_emit_token(&mut output, token.text(), class, &mut active, colors);
    }

    if active != PhpHighlightClass::Html {
        output.push_str("</span>");
    }
    output.push_str("</code></pre>");
    output
}

fn php_highlight_emit_token(
    output: &mut String,
    text: &[u8],
    class: PhpHighlightClass,
    active: &mut PhpHighlightClass,
    colors: &PhpHighlightColors,
) {
    if class == PhpHighlightClass::Html {
        if *active != PhpHighlightClass::Html {
            output.push_str("</span>");
            *active = PhpHighlightClass::Html;
        }
        php_highlight_escape_bytes(output, text);
        return;
    }

    if *active != class {
        if *active != PhpHighlightClass::Html {
            output.push_str("</span>");
        }
        output.push_str("<span style=\"color: ");
        output.push_str(php_highlight_class_color(class, colors));
        output.push_str("\">");
        *active = class;
    }
    php_highlight_escape_bytes(output, text);
}

fn php_highlight_escape_bytes(output: &mut String, text: &[u8]) {
    let mut chunk_start = 0;
    for (index, byte) in text.iter().copied().enumerate() {
        let replacement = match byte {
            b'&' => Some("&amp;"),
            b'<' => Some("&lt;"),
            b'>' => Some("&gt;"),
            _ => None,
        };
        let Some(replacement) = replacement else {
            continue;
        };
        if chunk_start < index {
            output.push_str(&String::from_utf8_lossy(&text[chunk_start..index]));
        }
        output.push_str(replacement);
        chunk_start = index + 1;
    }
    if chunk_start < text.len() {
        output.push_str(&String::from_utf8_lossy(&text[chunk_start..]));
    }
}

fn php_highlight_class_color<'a>(
    class: PhpHighlightClass,
    colors: &'a PhpHighlightColors,
) -> &'a str {
    match class {
        PhpHighlightClass::Html => &colors.html,
        PhpHighlightClass::Default => &colors.default,
        PhpHighlightClass::Keyword => &colors.keyword,
        PhpHighlightClass::String => &colors.string,
        PhpHighlightClass::Comment => &colors.comment,
    }
}

fn php_highlight_token_class(
    token: &PhpTokenizerToken,
    active: PhpHighlightClass,
    in_double_quoted_string: &mut bool,
) -> PhpHighlightClass {
    if token.id() == php_tokenizer::T_WHITESPACE {
        return active;
    }

    if !token.is_token_array() {
        if token.text() == b"\"" {
            *in_double_quoted_string = !*in_double_quoted_string;
            return PhpHighlightClass::String;
        }
        return if *in_double_quoted_string {
            PhpHighlightClass::String
        } else {
            PhpHighlightClass::Keyword
        };
    }

    match token.id() {
        php_tokenizer::T_INLINE_HTML => PhpHighlightClass::Html,
        php_tokenizer::T_OPEN_TAG
        | php_tokenizer::T_OPEN_TAG_WITH_ECHO
        | php_tokenizer::T_CLOSE_TAG => PhpHighlightClass::Default,
        php_tokenizer::T_COMMENT | php_tokenizer::T_DOC_COMMENT => PhpHighlightClass::Comment,
        php_tokenizer::T_CONSTANT_ENCAPSED_STRING
        | php_tokenizer::T_ENCAPSED_AND_WHITESPACE
        | php_tokenizer::T_START_HEREDOC => PhpHighlightClass::String,
        id if php_highlight_token_id_is_keyword(id) => PhpHighlightClass::Keyword,
        _ => PhpHighlightClass::Default,
    }
}

