fn php_strip_whitespace_bytes(source: &[u8]) -> Vec<u8> {
    let source = String::from_utf8_lossy(source);
    let mut output = String::new();
    let mut pending_code = String::new();
    let mut in_block_comment = false;
    let mut in_heredoc = false;
    let mut heredoc_marker = String::new();
    let mut pending_space_after_open_tag = false;

    for raw_line in source.lines() {
        if in_heredoc {
            output.push_str(raw_line);
            output.push('\n');
            if raw_line.trim_end().trim_end_matches(';') == heredoc_marker {
                in_heredoc = false;
            }
            continue;
        }

        let mut removed_comment = false;
        let stripped = php_strip_whitespace_remove_comments(
            raw_line,
            &mut in_block_comment,
            &mut removed_comment,
        );
        let compact = php_strip_whitespace_collapse_line(stripped.trim());
        if compact.is_empty() {
            if removed_comment && output.ends_with("<?php\n") && pending_code.is_empty() {
                pending_space_after_open_tag = true;
            }
            continue;
        }

        if compact == "<?php" {
            php_strip_whitespace_flush_pending(&mut output, &mut pending_code);
            output.push_str("<?php\n");
            pending_space_after_open_tag = false;
            continue;
        }

        if compact == "?>" {
            php_strip_whitespace_flush_pending(&mut output, &mut pending_code);
            output.push_str("?>");
            continue;
        }

        if pending_code.is_empty() {
            if pending_space_after_open_tag {
                pending_code.push(' ');
                pending_space_after_open_tag = false;
            }
            pending_code.push_str(&compact);
        } else {
            pending_code.push(' ');
            pending_code.push_str(&compact);
        }

        if let Some(marker) = php_strip_whitespace_heredoc_marker(&compact) {
            php_strip_whitespace_flush_pending(&mut output, &mut pending_code);
            in_heredoc = true;
            heredoc_marker = marker;
        }
    }

    php_strip_whitespace_flush_pending(&mut output, &mut pending_code);
    if output.ends_with('\n') {
        output.pop();
    }
    output.into_bytes()
}

fn php_strip_whitespace_flush_pending(output: &mut String, pending_code: &mut String) {
    if pending_code.is_empty() {
        return;
    }
    output.push_str(pending_code);
    pending_code.clear();
    output.push('\n');
}

fn php_strip_whitespace_remove_comments(
    line: &str,
    in_block_comment: &mut bool,
    removed_comment: &mut bool,
) -> String {
    let bytes = line.as_bytes();
    let mut output = String::new();
    let mut index = 0;
    while index < bytes.len() {
        if *in_block_comment {
            *removed_comment = true;
            if index + 1 < bytes.len() && bytes[index] == b'*' && bytes[index + 1] == b'/' {
                *in_block_comment = false;
                index += 2;
            } else {
                index += 1;
            }
            continue;
        }

        if index + 1 < bytes.len() && bytes[index] == b'/' && bytes[index + 1] == b'*' {
            *removed_comment = true;
            *in_block_comment = true;
            if !output.ends_with(' ') {
                output.push(' ');
            }
            index += 2;
            continue;
        }
        if index + 1 < bytes.len() && bytes[index] == b'/' && bytes[index + 1] == b'/' {
            *removed_comment = true;
            break;
        }
        if bytes[index] == b'#' {
            *removed_comment = true;
            break;
        }

        output.push(bytes[index] as char);
        index += 1;
    }
    output
}

fn php_strip_whitespace_collapse_line(line: &str) -> String {
    let mut output = String::new();
    let mut previous_space = false;
    for ch in line.chars() {
        if ch.is_whitespace() {
            if !previous_space && !output.is_empty() {
                output.push(' ');
                previous_space = true;
            }
        } else {
            output.push(ch);
            previous_space = false;
        }
    }
    if output.ends_with(' ') {
        output.pop();
    }
    output
}

fn php_strip_whitespace_heredoc_marker(line: &str) -> Option<String> {
    let marker = line.split_once("<<<")?.1.trim();
    let marker = marker
        .trim_matches(';')
        .trim_matches('"')
        .trim_matches('\'')
        .trim();
    (!marker.is_empty()).then(|| marker.to_string())
}

struct PathInfoParts {
    dirname: String,
    basename: String,
    extension: String,
    filename: String,
    has_extension_component: bool,
}

fn call_pathinfo(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "pathinfo()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let path = string_builtin_argument("pathinfo()", "path", &args[0], span)?;
    let flags = match args.get(1) {
        Some(value) => php_internal_int_argument("pathinfo()", 2, "flags", value, span)?,
        None => PHP_PATHINFO_ALL,
    };
    validate_pathinfo_flags(flags, span)?;

    let parts = pathinfo_parts(&path);
    match flags {
        PHP_PATHINFO_DIRNAME => Ok(Value::String(parts.dirname)),
        PHP_PATHINFO_BASENAME => Ok(Value::String(parts.basename)),
        PHP_PATHINFO_EXTENSION => Ok(Value::String(parts.extension)),
        PHP_PATHINFO_FILENAME => Ok(Value::String(parts.filename)),
        PHP_PATHINFO_ALL => Ok(Value::Array(pathinfo_array(path.is_empty(), parts))),
        _ => unreachable!("pathinfo flags are validated before dispatch"),
    }
}

fn validate_pathinfo_flags(flags: i64, span: Span) -> CompileResult<()> {
    if matches!(
        flags,
        PHP_PATHINFO_DIRNAME
            | PHP_PATHINFO_BASENAME
            | PHP_PATHINFO_EXTENSION
            | PHP_PATHINFO_FILENAME
            | PHP_PATHINFO_ALL
    ) {
        return Ok(());
    }

    let message = if flags > 0 && flags < PHP_PATHINFO_ALL && (flags & (flags - 1)) != 0 {
        "Argument #2 ($flags) must be only one of the PATHINFO_* constants"
    } else {
        "Argument #2 ($flags) must be one of the PATHINFO_* constants"
    };
    Err(runtime_error(
        span,
        RuntimeError::unsupported_call("pathinfo()", message),
    ))
}

fn pathinfo_parts(path: &str) -> PathInfoParts {
    let dirname = dirname_path(path, 1);
    let basename = basename_path(path, None);
    let (filename, extension, has_extension_component) = if let Some(position) = basename.rfind('.')
    {
        (
            basename[..position].to_string(),
            basename[position + 1..].to_string(),
            true,
        )
    } else {
        (basename.clone(), String::new(), false)
    };

    PathInfoParts {
        dirname,
        basename,
        extension,
        filename,
        has_extension_component,
    }
}

fn pathinfo_array(path_was_empty: bool, parts: PathInfoParts) -> PhpArray {
    let mut array = PhpArray::new();
    if !path_was_empty {
        array.insert("dirname", Value::String(parts.dirname));
    }
    array.insert("basename", Value::String(parts.basename));
    if parts.has_extension_component {
        array.insert("extension", Value::String(parts.extension));
    }
    array.insert("filename", Value::String(parts.filename));
    array
}

