fn php_array_from_strings(values: impl IntoIterator<Item = String>) -> PhpArray {
    let mut array = PhpArray::new();
    for value in values {
        let _ = array.append(Value::String(value));
    }
    array
}

fn glob_pattern_argument(value: &Value, span: Span) -> CompileResult<String> {
    match value {
        Value::String(pattern) => Ok(pattern.clone()),
        Value::BinaryString(bytes) => {
            Ok(tree_walk_binary_string_utf8(bytes, "glob pattern", span)?.to_string())
        }
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => Ok(value.echo_string()),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "glob()",
                format!(
                    "Argument #1 ($pattern) must be of type string, {} given",
                    php_type_error_given(other)
                ),
            ),
        )),
    }
}

fn split_php_glob_pattern(pattern: &str) -> (String, String, String) {
    match pattern.rfind('/') {
        Some(index) => {
            let directory = if index == 0 {
                "/".to_string()
            } else {
                pattern[..index].to_string()
            };
            let prefix = pattern[..=index].to_string();
            let name_pattern = pattern[index + 1..].to_string();
            (directory, prefix, name_pattern)
        }
        None => (".".to_string(), String::new(), pattern.to_string()),
    }
}

fn php_glob_pattern_has_magic(pattern: &str) -> bool {
    let mut escaped = false;
    for ch in pattern.chars() {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        if matches!(ch, '*' | '?' | '[' | '{') {
            return true;
        }
    }
    false
}

fn php_glob_component_matches(pattern: &str, name: &str, flags: i64) -> bool {
    let pattern_chars = pattern.chars().collect::<Vec<_>>();
    let name_chars = name.chars().collect::<Vec<_>>();
    php_glob_component_matches_at(
        &pattern_chars,
        0,
        &name_chars,
        0,
        flags & PHP_GLOB_NOESCAPE != 0,
        flags & PHP_GLOB_BRACE != 0,
    )
}

fn php_glob_component_matches_at(
    pattern: &[char],
    mut pattern_index: usize,
    name: &[char],
    name_index: usize,
    no_escape: bool,
    brace_enabled: bool,
) -> bool {
    if pattern_index == pattern.len() {
        return name_index == name.len();
    }

    match pattern[pattern_index] {
        '*' => {
            while pattern_index + 1 < pattern.len() && pattern[pattern_index + 1] == '*' {
                pattern_index += 1;
            }
            if pattern_index + 1 == pattern.len() {
                return true;
            }
            (name_index..=name.len()).any(|index| {
                php_glob_component_matches_at(
                    pattern,
                    pattern_index + 1,
                    name,
                    index,
                    no_escape,
                    brace_enabled,
                )
            })
        }
        '?' => {
            name_index < name.len()
                && php_glob_component_matches_at(
                    pattern,
                    pattern_index + 1,
                    name,
                    name_index + 1,
                    no_escape,
                    brace_enabled,
                )
        }
        '[' => {
            if let Some((matched, next_pattern_index)) =
                php_glob_bracket_class_matches(pattern, pattern_index, name, name_index)
            {
                matched
                    && php_glob_component_matches_at(
                        pattern,
                        next_pattern_index,
                        name,
                        name_index + 1,
                        no_escape,
                        brace_enabled,
                    )
            } else {
                name_index < name.len()
                    && name[name_index] == '['
                    && php_glob_component_matches_at(
                        pattern,
                        pattern_index + 1,
                        name,
                        name_index + 1,
                        no_escape,
                        brace_enabled,
                    )
            }
        }
        '{' if brace_enabled => {
            if let Some((alternatives, next_pattern_index)) =
                php_glob_brace_alternatives(pattern, pattern_index)
            {
                alternatives.into_iter().any(|alternative| {
                    let mut expanded = alternative;
                    expanded.extend_from_slice(&pattern[next_pattern_index..]);
                    php_glob_component_matches_at(
                        &expanded,
                        0,
                        name,
                        name_index,
                        no_escape,
                        brace_enabled,
                    )
                })
            } else {
                name_index < name.len()
                    && name[name_index] == '{'
                    && php_glob_component_matches_at(
                        pattern,
                        pattern_index + 1,
                        name,
                        name_index + 1,
                        no_escape,
                        brace_enabled,
                    )
            }
        }
        '\\' if !no_escape && pattern_index + 1 < pattern.len() => {
            name_index < name.len()
                && name[name_index] == pattern[pattern_index + 1]
                && php_glob_component_matches_at(
                    pattern,
                    pattern_index + 2,
                    name,
                    name_index + 1,
                    no_escape,
                    brace_enabled,
                )
        }
        literal => {
            name_index < name.len()
                && name[name_index] == literal
                && php_glob_component_matches_at(
                    pattern,
                    pattern_index + 1,
                    name,
                    name_index + 1,
                    no_escape,
                    brace_enabled,
                )
        }
    }
}

fn php_glob_brace_alternatives(pattern: &[char], start: usize) -> Option<(Vec<Vec<char>>, usize)> {
    let mut alternatives = vec![Vec::new()];
    let mut index = start + 1;
    while index < pattern.len() {
        match pattern[index] {
            '}' => return Some((alternatives, index + 1)),
            ',' => alternatives.push(Vec::new()),
            ch => alternatives
                .last_mut()
                .expect("at least one brace alternative is present")
                .push(ch),
        }
        index += 1;
    }
    None
}

fn php_glob_bracket_class_matches(
    pattern: &[char],
    start: usize,
    name: &[char],
    name_index: usize,
) -> Option<(bool, usize)> {
    if name_index >= name.len() || start + 1 >= pattern.len() {
        return None;
    }
    let mut index = start + 1;
    let mut negate = false;
    if matches!(pattern.get(index), Some('!') | Some('^')) {
        negate = true;
        index += 1;
    }

    let mut matched = false;
    let target = name[name_index];
    let mut previous: Option<char> = None;
    let mut saw_member = false;
    while index < pattern.len() {
        let current = pattern[index];
        if current == ']' && saw_member {
            return Some((if negate { !matched } else { matched }, index + 1));
        }
        if current == '-'
            && previous.is_some()
            && index + 1 < pattern.len()
            && pattern[index + 1] != ']'
        {
            let end = pattern[index + 1];
            let start = previous.expect("previous class member is present");
            if start <= target && target <= end {
                matched = true;
            }
            previous = Some(end);
            saw_member = true;
            index += 2;
            continue;
        }
        if current == target {
            matched = true;
        }
        previous = Some(current);
        saw_member = true;
        index += 1;
    }
    None
}

