fn wordpress_dynamic_schema_result_for_query(
    query: &str,
    tables: &HashMap<String, WordPressSchemaTableState>,
    no_backslash_escapes: bool,
) -> Option<MysqliPendingResultState> {
    let query = query.trim().strip_suffix(';').unwrap_or(query.trim());

    if let Some(table_filter) = query
        .strip_prefix("SHOW TABLES LIKE ")
        .and_then(|input| parse_sql_single_quoted_schema_like_filter(input, no_backslash_escapes))
    {
        let mut table_names = tables
            .keys()
            .filter(|table_name| wordpress_schema_name_matches_filter(table_name, &table_filter))
            .cloned()
            .collect::<Vec<_>>();
        table_names.sort();
        if !table_names.is_empty() {
            let field = format!("Tables_in_wordpress ({})", table_filter.pattern());
            return Some(MysqliPendingResultState {
                fields: vec![field.clone()],
                rows: table_names
                    .into_iter()
                    .map(|table_name| vec![(field.clone(), Value::String(table_name))])
                    .collect(),
            });
        }
        return None;
    }

    if let Some(table_names) =
        parse_dynamic_schema_show_table_status_in_query(query, no_backslash_escapes)
    {
        let mut matched_names = tables
            .keys()
            .filter(|table_name| table_names.iter().any(|name| name == *table_name))
            .cloned()
            .collect::<Vec<_>>();
        matched_names.sort();
        let rows = matched_names
            .into_iter()
            .filter_map(|table_name| tables.get(&table_name))
            .map(dynamic_schema_table_status_row)
            .collect();
        return Some(MysqliPendingResultState {
            fields: dynamic_schema_table_status_fields(),
            rows,
        });
    }

    if let Some(table_filter) =
        parse_dynamic_schema_show_table_status_query(query, no_backslash_escapes)
    {
        let mut table_names = tables
            .keys()
            .filter(|table_name| wordpress_schema_name_matches_filter(table_name, &table_filter))
            .cloned()
            .collect::<Vec<_>>();
        table_names.sort();
        let rows = table_names
            .into_iter()
            .filter_map(|table_name| tables.get(&table_name))
            .map(dynamic_schema_table_status_row)
            .collect();
        return Some(MysqliPendingResultState {
            fields: dynamic_schema_table_status_fields(),
            rows,
        });
    }

    let show_create_table = query
        .strip_prefix("SHOW CREATE TABLE ")
        .and_then(parse_schema_table_identifier);
    if let Some(table_name) = show_create_table {
        let table = tables.get(&table_name)?;
        return Some(MysqliPendingResultState {
            fields: vec!["Table".to_string(), "Create Table".to_string()],
            rows: vec![vec![
                ("Table".to_string(), Value::String(table.name.clone())),
                (
                    "Create Table".to_string(),
                    Value::String(dynamic_schema_create_table_sql(table)),
                ),
            ]],
        });
    }

    if let Some(column_query) = parse_dynamic_schema_describe_query(query) {
        let table = tables.get(&column_query.table_name)?;
        return Some(MysqliPendingResultState {
            fields: vec![
                "Field".to_string(),
                "Type".to_string(),
                "Null".to_string(),
                "Key".to_string(),
                "Default".to_string(),
                "Extra".to_string(),
            ],
            rows: table
                .columns
                .iter()
                .filter(|column| schema_column_matches_filter(column, &column_query.column_filter))
                .map(|column| dynamic_schema_describe_row(column, table))
                .collect(),
        });
    }

    if let Some(column_query) = parse_dynamic_schema_show_columns_query(query, no_backslash_escapes)
    {
        let table = tables.get(&column_query.table_name)?;
        return Some(MysqliPendingResultState {
            fields: vec![
                "Field".to_string(),
                "Type".to_string(),
                "Collation".to_string(),
                "Null".to_string(),
                "Key".to_string(),
                "Default".to_string(),
                "Extra".to_string(),
                "Privileges".to_string(),
                "Comment".to_string(),
            ],
            rows: table
                .columns
                .iter()
                .filter(|column| schema_column_matches_filter(column, &column_query.column_filter))
                .map(|column| dynamic_schema_full_column_row(column, table))
                .collect(),
        });
    }

    if let Some(index_query) = parse_dynamic_schema_show_index_query(query, no_backslash_escapes) {
        let table = tables.get(&index_query.table_name)?;
        return Some(MysqliPendingResultState {
            fields: vec![
                "Table".to_string(),
                "Non_unique".to_string(),
                "Key_name".to_string(),
                "Seq_in_index".to_string(),
                "Column_name".to_string(),
                "Collation".to_string(),
                "Cardinality".to_string(),
                "Sub_part".to_string(),
                "Packed".to_string(),
                "Null".to_string(),
                "Index_type".to_string(),
                "Comment".to_string(),
                "Index_comment".to_string(),
                "Visible".to_string(),
                "Expression".to_string(),
            ],
            rows: table
                .indexes
                .iter()
                .filter(|index| schema_index_matches_filter(index, &index_query.key_filter))
                .flat_map(|index| {
                    index.parts.iter().enumerate().map(|(idx, part)| {
                        dynamic_schema_index_row(&table.name, index, part, (idx + 1) as i64)
                    })
                })
                .collect(),
        });
    }

    None
}

fn wordpress_dynamic_prepared_schema_result_for_query(
    query: &str,
    tables: &HashMap<String, WordPressSchemaTableState>,
    no_backslash_escapes: bool,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<MysqliPendingResultState>> {
    let query = query.trim().strip_suffix(';').unwrap_or(query.trim());

    if let Some(input) = query.strip_prefix("SHOW TABLES LIKE ") {
        if let Some(table_filter) = parse_prepared_schema_like_placeholder_filter(
            input,
            params,
            no_backslash_escapes,
            function,
            span,
        )? {
            let mut table_names = tables
                .keys()
                .filter(|table_name| {
                    wordpress_schema_name_matches_filter(table_name, &table_filter)
                })
                .cloned()
                .collect::<Vec<_>>();
            table_names.sort();
            if !table_names.is_empty() {
                let field = format!("Tables_in_wordpress ({})", table_filter.pattern());
                return Ok(Some(MysqliPendingResultState {
                    fields: vec![field.clone()],
                    rows: table_names
                        .into_iter()
                        .map(|table_name| vec![(field.clone(), Value::String(table_name))])
                        .collect(),
                }));
            }
            return Ok(None);
        }
    }

    if let Some(input) = query.strip_prefix("SHOW TABLE STATUS LIKE ") {
        if let Some(table_filter) = parse_prepared_schema_like_placeholder_filter(
            input,
            params,
            no_backslash_escapes,
            function,
            span,
        )? {
            let mut table_names = tables
                .keys()
                .filter(|table_name| {
                    wordpress_schema_name_matches_filter(table_name, &table_filter)
                })
                .cloned()
                .collect::<Vec<_>>();
            table_names.sort();
            let rows = table_names
                .into_iter()
                .filter_map(|table_name| tables.get(&table_name))
                .map(dynamic_schema_table_status_row)
                .collect();
            return Ok(Some(MysqliPendingResultState {
                fields: dynamic_schema_table_status_fields(),
                rows,
            }));
        }
    }

    if let Some(input) = query
        .strip_prefix("SHOW TABLE STATUS WHERE Name = ")
        .or_else(|| query.strip_prefix("SHOW TABLE STATUS WHERE `Name` = "))
    {
        if let Some(table_filter) =
            parse_prepared_schema_exact_placeholder_filter(input, params, function, span)?
        {
            let rows = tables
                .get(table_filter.pattern())
                .map(dynamic_schema_table_status_row)
                .into_iter()
                .collect();
            return Ok(Some(MysqliPendingResultState {
                fields: dynamic_schema_table_status_fields(),
                rows,
            }));
        }
    }

    if let Some(input) = query
        .strip_prefix("SHOW TABLE STATUS WHERE Name IN ")
        .or_else(|| query.strip_prefix("SHOW TABLE STATUS WHERE `Name` IN "))
    {
        if let Some(table_names) =
            parse_prepared_schema_exact_placeholder_list(input, params, function, span)?
        {
            let mut matched_names = tables
                .keys()
                .filter(|table_name| table_names.iter().any(|name| name == *table_name))
                .cloned()
                .collect::<Vec<_>>();
            matched_names.sort();
            let rows = matched_names
                .into_iter()
                .filter_map(|table_name| tables.get(&table_name))
                .map(dynamic_schema_table_status_row)
                .collect();
            return Ok(Some(MysqliPendingResultState {
                fields: dynamic_schema_table_status_fields(),
                rows,
            }));
        }
    }

    if let Some(input) = query
        .strip_prefix("SHOW TABLE STATUS WHERE Name LIKE ")
        .or_else(|| query.strip_prefix("SHOW TABLE STATUS WHERE `Name` LIKE "))
    {
        if let Some(table_filter) = parse_prepared_schema_like_placeholder_filter(
            input,
            params,
            no_backslash_escapes,
            function,
            span,
        )? {
            let mut table_names = tables
                .keys()
                .filter(|table_name| {
                    wordpress_schema_name_matches_filter(table_name, &table_filter)
                })
                .cloned()
                .collect::<Vec<_>>();
            table_names.sort();
            let rows = table_names
                .into_iter()
                .filter_map(|table_name| tables.get(&table_name))
                .map(dynamic_schema_table_status_row)
                .collect();
            return Ok(Some(MysqliPendingResultState {
                fields: dynamic_schema_table_status_fields(),
                rows,
            }));
        }
    }

    if let Some(table_name) =
        parse_prepared_schema_joined_column_index_metadata_query(query, params, function, span)?
    {
        let Some(table) = tables.get(&table_name) else {
            return Ok(None);
        };
        return Ok(Some(joined_schema_column_index_metadata_result(table)));
    }

    if let Some(column_query) = parse_dynamic_prepared_schema_show_columns_query(
        query,
        no_backslash_escapes,
        params,
        function,
        span,
    )? {
        let Some(table) = tables.get(&column_query.table_name) else {
            return Ok(None);
        };
        return Ok(Some(MysqliPendingResultState {
            fields: vec![
                "Field".to_string(),
                "Type".to_string(),
                "Collation".to_string(),
                "Null".to_string(),
                "Key".to_string(),
                "Default".to_string(),
                "Extra".to_string(),
                "Privileges".to_string(),
                "Comment".to_string(),
            ],
            rows: table
                .columns
                .iter()
                .filter(|column| schema_column_matches_filter(column, &column_query.column_filter))
                .map(|column| dynamic_schema_full_column_row(column, table))
                .collect(),
        }));
    }

    if let Some(index_query) = parse_dynamic_prepared_schema_show_index_query(
        query,
        no_backslash_escapes,
        params,
        function,
        span,
    )? {
        let Some(table) = tables.get(&index_query.table_name) else {
            return Ok(None);
        };
        return Ok(Some(MysqliPendingResultState {
            fields: vec![
                "Table".to_string(),
                "Non_unique".to_string(),
                "Key_name".to_string(),
                "Seq_in_index".to_string(),
                "Column_name".to_string(),
                "Collation".to_string(),
                "Cardinality".to_string(),
                "Sub_part".to_string(),
                "Packed".to_string(),
                "Null".to_string(),
                "Index_type".to_string(),
                "Comment".to_string(),
                "Index_comment".to_string(),
                "Visible".to_string(),
                "Expression".to_string(),
            ],
            rows: table
                .indexes
                .iter()
                .filter(|index| schema_index_matches_filter(index, &index_query.key_filter))
                .flat_map(|index| {
                    index.parts.iter().enumerate().map(|(idx, part)| {
                        dynamic_schema_index_row(&table.name, index, part, (idx + 1) as i64)
                    })
                })
                .collect(),
        }));
    }

    Ok(None)
}

fn parse_prepared_schema_joined_column_index_metadata_query(
    query: &str,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<String>> {
    if !matches!(
        query,
        "SELECT c.COLUMN_NAME AS Field, c.COLUMN_TYPE AS Type, c.IS_NULLABLE AS `Null`, c.COLUMN_KEY AS `Key`, s.INDEX_NAME AS Key_name, s.SEQ_IN_INDEX AS Seq_in_index, s.SUB_PART AS Sub_part FROM information_schema.COLUMNS c LEFT JOIN information_schema.STATISTICS s ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.TABLE_SCHEMA = DATABASE() AND c.TABLE_NAME = ? ORDER BY c.ORDINAL_POSITION, s.SEQ_IN_INDEX"
            | "SELECT c.COLUMN_NAME AS Field, c.COLUMN_TYPE AS Type, c.IS_NULLABLE AS `Null`, c.COLUMN_KEY AS `Key`, s.INDEX_NAME AS Key_name, s.SEQ_IN_INDEX AS Seq_in_index, s.SUB_PART AS Sub_part FROM `information_schema`.`COLUMNS` c LEFT JOIN `information_schema`.`STATISTICS` s ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.TABLE_SCHEMA = DATABASE() AND c.TABLE_NAME = ? ORDER BY c.ORDINAL_POSITION, s.SEQ_IN_INDEX"
    ) {
        return Ok(None);
    }

    let value = prepared_schema_string_filter_param_at(function, params, 0, span)?;
    let Some(identifier) = parse_schema_table_identifier(value) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared joined schema metadata requires an identifier-shaped table-name parameter in the current subset",
            ),
        ));
    };
    Ok(Some(identifier))
}

fn parse_dynamic_prepared_schema_show_columns_query(
    query: &str,
    no_backslash_escapes: bool,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<WordPressSchemaColumnQuery>> {
    let Some(rest) = query
        .strip_prefix("SHOW FULL COLUMNS FROM ")
        .or_else(|| query.strip_prefix("SHOW COLUMNS FROM "))
    else {
        return Ok(None);
    };
    let (table_name, rest, next_param) =
        match parse_prepared_schema_identifier_with_optional_suffix(
            rest.trim(),
            params,
            function,
            span,
        )? {
            Some(parsed) => parsed,
            None => return Ok(None),
        };
    let rest = rest.trim();
    let column_filter = if let Some(like) = rest.strip_prefix("LIKE ") {
        if !like.trim().starts_with('?') {
            return Ok(None);
        }
        Some(parse_prepared_schema_like_placeholder_filter_at(
            like,
            params,
            next_param,
            no_backslash_escapes,
            function,
            span,
        )?)
    } else if let Some(field) = rest
        .strip_prefix("WHERE Field = ")
        .or_else(|| rest.strip_prefix("WHERE `Field` = "))
    {
        if !field.trim().starts_with('?') {
            return Ok(None);
        }
        Some(parse_prepared_schema_exact_placeholder_filter_at(
            field, params, next_param, function, span,
        )?)
    } else if let Some(field) = rest
        .strip_prefix("WHERE Field LIKE ")
        .or_else(|| rest.strip_prefix("WHERE `Field` LIKE "))
    {
        if !field.trim().starts_with('?') {
            return Ok(None);
        }
        Some(parse_prepared_schema_like_placeholder_filter_at(
            field,
            params,
            next_param,
            no_backslash_escapes,
            function,
            span,
        )?)
    } else if rest.is_empty() {
        None
    } else {
        return Ok(None);
    };
    Ok(Some(WordPressSchemaColumnQuery {
        table_name,
        column_filter,
    }))
}

fn parse_dynamic_prepared_schema_show_index_query(
    query: &str,
    no_backslash_escapes: bool,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<WordPressSchemaIndexQuery>> {
    let Some(rest) = query
        .strip_prefix("SHOW INDEX FROM ")
        .or_else(|| query.strip_prefix("SHOW INDEXES FROM "))
        .or_else(|| query.strip_prefix("SHOW KEYS FROM "))
    else {
        return Ok(None);
    };
    let (table_name, rest, next_param) =
        match parse_prepared_schema_identifier_with_optional_suffix(
            rest.trim(),
            params,
            function,
            span,
        )? {
            Some(parsed) => parsed,
            None => return Ok(None),
        };
    let rest = rest.trim();
    let key_filter = if let Some(key_name) = rest
        .strip_prefix("WHERE Key_name = ")
        .or_else(|| rest.strip_prefix("WHERE `Key_name` = "))
    {
        if !key_name.trim().starts_with('?') {
            return Ok(None);
        }
        Some(parse_prepared_schema_exact_placeholder_filter_at(
            key_name, params, next_param, function, span,
        )?)
    } else if let Some(key_name) = rest
        .strip_prefix("WHERE Key_name LIKE ")
        .or_else(|| rest.strip_prefix("WHERE `Key_name` LIKE "))
    {
        if !key_name.trim().starts_with('?') {
            return Ok(None);
        }
        Some(parse_prepared_schema_like_placeholder_filter_at(
            key_name,
            params,
            next_param,
            no_backslash_escapes,
            function,
            span,
        )?)
    } else if rest.is_empty() {
        None
    } else {
        return Ok(None);
    };
    Ok(Some(WordPressSchemaIndexQuery {
        table_name,
        key_filter,
    }))
}

fn parse_dynamic_schema_show_index_query(
    query: &str,
    no_backslash_escapes: bool,
) -> Option<WordPressSchemaIndexQuery> {
    let rest = query
        .strip_prefix("SHOW INDEX FROM ")
        .or_else(|| query.strip_prefix("SHOW INDEXES FROM "))
        .or_else(|| query.strip_prefix("SHOW KEYS FROM "))?
        .trim();
    let (table_name, rest) = parse_schema_identifier_with_optional_suffix(rest)?;
    let rest = rest.trim();
    let key_filter = if rest.is_empty() {
        None
    } else if let Some(key_name) = rest
        .strip_prefix("WHERE Key_name = ")
        .or_else(|| rest.strip_prefix("WHERE `Key_name` = "))
    {
        Some(parse_sql_single_quoted_list(key_name).and_then(|values| {
            (values.len() == 1)
                .then(|| values[0].clone())
                .and_then(|value| parse_schema_table_identifier(&value))
                .map(WordPressSchemaNameFilter::Exact)
        })?)
    } else if let Some(key_name) = rest
        .strip_prefix("WHERE Key_name LIKE ")
        .or_else(|| rest.strip_prefix("WHERE `Key_name` LIKE "))
    {
        Some(parse_sql_single_quoted_schema_like_filter(
            key_name,
            no_backslash_escapes,
        )?)
    } else {
        return None;
    };
    Some(WordPressSchemaIndexQuery {
        table_name,
        key_filter,
    })
}

fn parse_dynamic_schema_describe_query(query: &str) -> Option<WordPressSchemaColumnQuery> {
    let rest = query
        .strip_prefix("DESCRIBE ")
        .or_else(|| query.strip_prefix("DESC "))?
        .trim();
    let (table_name, rest) = parse_schema_identifier_with_optional_suffix(rest)?;
    let rest = rest.trim();
    let column_filter = if rest.is_empty() {
        None
    } else {
        Some(WordPressSchemaNameFilter::Exact(
            parse_schema_table_identifier(rest)?,
        ))
    };
    Some(WordPressSchemaColumnQuery {
        table_name,
        column_filter,
    })
}

fn parse_dynamic_schema_show_columns_query(
    query: &str,
    no_backslash_escapes: bool,
) -> Option<WordPressSchemaColumnQuery> {
    let rest = query
        .strip_prefix("SHOW FULL COLUMNS FROM ")
        .or_else(|| query.strip_prefix("SHOW COLUMNS FROM "))?
        .trim();
    let (table_name, rest) = parse_schema_identifier_with_optional_suffix(rest)?;
    let rest = rest.trim();
    let column_filter = if rest.is_empty() {
        None
    } else if let Some(like) = rest.strip_prefix("LIKE ") {
        Some(parse_sql_single_quoted_schema_like_filter(
            like,
            no_backslash_escapes,
        )?)
    } else if let Some(field) = rest
        .strip_prefix("WHERE Field = ")
        .or_else(|| rest.strip_prefix("WHERE `Field` = "))
    {
        Some(parse_sql_single_quoted_list(field).and_then(|values| {
            (values.len() == 1)
                .then(|| values[0].clone())
                .and_then(|value| parse_schema_table_identifier(&value))
                .map(WordPressSchemaNameFilter::Exact)
        })?)
    } else if let Some(field) = rest
        .strip_prefix("WHERE Field LIKE ")
        .or_else(|| rest.strip_prefix("WHERE `Field` LIKE "))
    {
        Some(parse_sql_single_quoted_schema_like_filter(
            field,
            no_backslash_escapes,
        )?)
    } else {
        return None;
    };
    Some(WordPressSchemaColumnQuery {
        table_name,
        column_filter,
    })
}

fn schema_column_matches_filter(
    column: &WordPressSchemaColumnState,
    filter: &Option<WordPressSchemaNameFilter>,
) -> bool {
    filter
        .as_ref()
        .map(|filter| wordpress_schema_name_matches_filter(&column.name, filter))
        .unwrap_or(true)
}

fn schema_index_matches_filter(
    index: &WordPressSchemaIndexState,
    filter: &Option<WordPressSchemaNameFilter>,
) -> bool {
    filter
        .as_ref()
        .map(|filter| wordpress_schema_name_matches_filter(&index.key_name, filter))
        .unwrap_or(true)
}

fn wordpress_schema_name_matches_filter(name: &str, filter: &WordPressSchemaNameFilter) -> bool {
    match filter {
        WordPressSchemaNameFilter::Exact(expected) => name == expected,
        WordPressSchemaNameFilter::Like { tokens, .. } => {
            wordpress_schema_name_matches_like(name, tokens)
        }
    }
}

fn wordpress_schema_name_matches_like(name: &str, tokens: &[WordPressSchemaLikeToken]) -> bool {
    let chars = name.chars().collect::<Vec<_>>();
    let mut matches = vec![vec![false; chars.len() + 1]; tokens.len() + 1];
    matches[0][0] = true;

    for token_index in 0..tokens.len() {
        for char_index in 0..=chars.len() {
            if !matches[token_index][char_index] {
                continue;
            }
            match &tokens[token_index] {
                WordPressSchemaLikeToken::Literal(expected) => {
                    if chars.get(char_index) == Some(expected) {
                        matches[token_index + 1][char_index + 1] = true;
                    }
                }
                WordPressSchemaLikeToken::AnyOne => {
                    if char_index < chars.len() {
                        matches[token_index + 1][char_index + 1] = true;
                    }
                }
                WordPressSchemaLikeToken::AnyMany => {
                    matches[token_index + 1][char_index] = true;
                    if char_index < chars.len() {
                        matches[token_index][char_index + 1] = true;
                    }
                }
            }
        }
    }

    matches[tokens.len()][chars.len()]
}

impl WordPressSchemaNameFilter {
    fn pattern(&self) -> &str {
        match self {
            WordPressSchemaNameFilter::Exact(pattern)
            | WordPressSchemaNameFilter::Like { pattern, .. } => pattern,
        }
    }
}

fn parse_sql_single_quoted_schema_like_filter(
    input: &str,
    no_backslash_escapes: bool,
) -> Option<WordPressSchemaNameFilter> {
    let mut rest = input.trim();
    let (mut filter, next) =
        parse_sql_single_quoted_schema_like_value(rest, '\\', no_backslash_escapes)?;
    rest = next.trim_start();
    if let Some(escape) = rest.strip_prefix("ESCAPE ") {
        let (escape, next) = parse_sql_single_quoted_value(escape.trim_start())?;
        if !next.trim().is_empty() {
            return None;
        }
        let mut escape_chars = escape.chars();
        let escape_char = escape_chars.next()?;
        if escape_chars.next().is_some() {
            return None;
        }
        let like_no_backslash_escapes = no_backslash_escapes && escape_char != '\\';
        let (escaped_filter, escaped_next) = parse_sql_single_quoted_schema_like_value(
            input.trim(),
            escape_char,
            like_no_backslash_escapes,
        )?;
        if !escaped_next.trim_start().starts_with("ESCAPE ") {
            return None;
        }
        filter = escaped_filter;
        rest = "";
    }
    if rest.is_empty() {
        Some(filter)
    } else {
        None
    }
}

fn parse_prepared_schema_like_placeholder_filter(
    input: &str,
    params: &[Value],
    no_backslash_escapes: bool,
    function: &str,
    span: Span,
) -> CompileResult<Option<WordPressSchemaNameFilter>> {
    if !input.trim().starts_with('?') {
        return Ok(None);
    }
    Ok(Some(parse_prepared_schema_like_placeholder_filter_at(
        input,
        params,
        0,
        no_backslash_escapes,
        function,
        span,
    )?))
}

fn parse_prepared_schema_like_placeholder_filter_at(
    input: &str,
    params: &[Value],
    param_index: usize,
    no_backslash_escapes: bool,
    function: &str,
    span: Span,
) -> CompileResult<WordPressSchemaNameFilter> {
    let Some(mut rest) = input.trim().strip_prefix('?') else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata filter placeholder is required in the current subset",
            ),
        ));
    };
    rest = rest.trim_start();
    let escape_char = if let Some(escape) = rest.strip_prefix("ESCAPE ") {
        let Some((escape, next)) = parse_sql_single_quoted_value(escape.trim_start()) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata ESCAPE clause must use one single-quoted character in the current subset",
                ),
            ));
        };
        if !next.trim().is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata ESCAPE clause must end the filter in the current subset",
                ),
            ));
        }
        let mut escape_chars = escape.chars();
        let Some(escape_char) = escape_chars.next() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata ESCAPE clause requires one character in the current subset",
                ),
            ));
        };
        if escape_chars.next().is_some() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata ESCAPE clause requires one character in the current subset",
                ),
            ));
        }
        escape_char
    } else if rest.is_empty() {
        '\\'
    } else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata LIKE filter supports only a placeholder with an optional ESCAPE clause in the current subset",
            ),
        ));
    };

    let pattern = prepared_schema_string_filter_param_at(function, params, param_index, span)?;
    let Some(filter) = parse_schema_like_pattern(pattern, escape_char, no_backslash_escapes) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata LIKE filter contains an unterminated escape sequence in the current subset",
            ),
        ));
    };
    Ok(filter)
}

fn parse_prepared_schema_exact_placeholder_filter(
    input: &str,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<WordPressSchemaNameFilter>> {
    if !input.trim().starts_with('?') {
        return Ok(None);
    }
    Ok(Some(parse_prepared_schema_exact_placeholder_filter_at(
        input, params, 0, function, span,
    )?))
}

fn parse_prepared_schema_exact_placeholder_filter_at(
    input: &str,
    params: &[Value],
    param_index: usize,
    function: &str,
    span: Span,
) -> CompileResult<WordPressSchemaNameFilter> {
    let Some(rest) = input.trim().strip_prefix('?') else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata exact filter placeholder is required in the current subset",
            ),
        ));
    };
    if !rest.trim().is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata exact filter supports only a placeholder in the current subset",
            ),
        ));
    }
    let value = prepared_schema_string_filter_param_at(function, params, param_index, span)?;
    let Some(identifier) = parse_schema_table_identifier(value) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata exact filter requires an identifier-shaped string parameter in the current subset",
            ),
        ));
    };
    Ok(WordPressSchemaNameFilter::Exact(identifier))
}

fn parse_prepared_schema_exact_placeholder_list(
    input: &str,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<Vec<String>>> {
    let input = input.trim();
    let Some(inner) = input
        .strip_prefix('(')
        .and_then(|rest| rest.strip_suffix(')'))
    else {
        return Ok(None);
    };

    let placeholders = inner.split(',').map(str::trim).collect::<Vec<_>>();
    if placeholders.is_empty()
        || placeholders.iter().any(|placeholder| *placeholder != "?")
        || placeholders.len() != params.len()
    {
        return Ok(None);
    }

    let mut names = Vec::with_capacity(params.len());
    for value in params {
        let Value::String(name) = value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata IN filters require string table-name parameters in the current subset",
                ),
            ));
        };
        let Some(identifier) = parse_schema_table_identifier(name) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata IN filters require identifier-shaped string parameters in the current subset",
                ),
            ));
        };
        names.push(identifier);
    }

    Ok(Some(names))
}

fn prepared_schema_string_filter_param_at<'a>(
    function: &str,
    params: &'a [Value],
    param_index: usize,
    span: Span,
) -> CompileResult<&'a str> {
    let Some(value) = params.get(param_index) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata filter is missing a string parameter in the current subset",
            ),
        ));
    };
    let Value::String(pattern) = value else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared schema metadata filters require string parameters in the current subset",
            ),
        ));
    };
    Ok(pattern)
}

fn parse_schema_like_pattern(
    pattern: &str,
    escape_char: char,
    no_backslash_escapes: bool,
) -> Option<WordPressSchemaNameFilter> {
    let mut normalized_pattern = String::new();
    let mut tokens = Vec::new();
    let mut has_wildcard = false;
    let mut chars = pattern.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == escape_char && (!no_backslash_escapes || escape_char != '\\') {
            let escaped = chars.next()?;
            normalized_pattern.push(escaped);
            tokens.push(WordPressSchemaLikeToken::Literal(escaped));
            continue;
        }
        normalized_pattern.push(ch);
        match ch {
            '%' => {
                has_wildcard = true;
                tokens.push(WordPressSchemaLikeToken::AnyMany);
            }
            '_' => {
                has_wildcard = true;
                tokens.push(WordPressSchemaLikeToken::AnyOne);
            }
            literal => tokens.push(WordPressSchemaLikeToken::Literal(literal)),
        }
    }
    Some(if has_wildcard {
        WordPressSchemaNameFilter::Like {
            pattern: normalized_pattern,
            tokens,
        }
    } else {
        WordPressSchemaNameFilter::Exact(normalized_pattern)
    })
}

fn parse_sql_single_quoted_schema_like_value(
    input: &str,
    escape_char: char,
    no_backslash_escapes: bool,
) -> Option<(WordPressSchemaNameFilter, &str)> {
    let rest = input.strip_prefix('\'')?;
    let mut pattern = String::new();
    let mut tokens = Vec::new();
    let mut has_wildcard = false;
    let mut chars = rest.char_indices().peekable();
    while let Some((index, ch)) = chars.next() {
        if ch == '\'' {
            if let Some((_, '\'')) = chars.peek().copied() {
                chars.next();
                pattern.push('\'');
                tokens.push(WordPressSchemaLikeToken::Literal('\''));
                continue;
            }
            let filter = if has_wildcard {
                WordPressSchemaNameFilter::Like { pattern, tokens }
            } else {
                WordPressSchemaNameFilter::Exact(pattern)
            };
            return Some((filter, &rest[index + ch.len_utf8()..]));
        }
        if ch == escape_char && (!no_backslash_escapes || escape_char != '\\') {
            let (_, escaped) = chars.next()?;
            let literal = if escape_char == '\\' {
                match escaped {
                    '0' => '\0',
                    '\'' => '\'',
                    '"' => '"',
                    'b' => '\u{0008}',
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    'Z' => '\u{001A}',
                    '\\' => '\\',
                    '%' => '%',
                    '_' => '_',
                    other => other,
                }
            } else {
                escaped
            };
            pattern.push(literal);
            tokens.push(WordPressSchemaLikeToken::Literal(literal));
            continue;
        }
        if ch == '\\' && !no_backslash_escapes {
            let (_, escaped) = chars.next()?;
            let literal = match escaped {
                '0' => '\0',
                '\'' => '\'',
                '"' => '"',
                'b' => '\u{0008}',
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                'Z' => '\u{001A}',
                '\\' => '\\',
                other => other,
            };
            pattern.push(literal);
            tokens.push(WordPressSchemaLikeToken::Literal(literal));
            continue;
        }
        pattern.push(ch);
        match ch {
            '%' => {
                has_wildcard = true;
                tokens.push(WordPressSchemaLikeToken::AnyMany);
            }
            '_' => {
                has_wildcard = true;
                tokens.push(WordPressSchemaLikeToken::AnyOne);
            }
            literal => tokens.push(WordPressSchemaLikeToken::Literal(literal)),
        }
    }
    None
}

fn parse_schema_identifier_with_optional_suffix(input: &str) -> Option<(String, &str)> {
    let input = input.trim_start();
    if let Some(after_tick) = input.strip_prefix('`') {
        let (identifier, rest) = after_tick.split_once('`')?;
        return Some((
            parse_schema_table_identifier(identifier)?,
            rest.trim_start(),
        ));
    }

    let split_at = input
        .char_indices()
        .find_map(|(idx, ch)| ch.is_whitespace().then_some(idx))
        .unwrap_or(input.len());
    Some((
        parse_schema_table_identifier(&input[..split_at])?,
        input[split_at..].trim_start(),
    ))
}

fn parse_prepared_schema_identifier_with_optional_suffix<'a>(
    input: &'a str,
    params: &[Value],
    function: &str,
    span: Span,
) -> CompileResult<Option<(String, &'a str, usize)>> {
    let input = input.trim_start();
    if let Some(rest) = input.strip_prefix('?') {
        let value = prepared_schema_string_filter_param_at(function, params, 0, span)?;
        let Some(identifier) = parse_schema_table_identifier(value) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared schema metadata identifier placeholders require identifier-shaped string parameters in the current subset",
                ),
            ));
        };
        return Ok(Some((identifier, rest.trim_start(), 1)));
    }

    Ok(parse_schema_identifier_with_optional_suffix(input)
        .map(|(identifier, rest)| (identifier, rest, 0)))
}

fn parse_dynamic_schema_show_table_status_query(
    query: &str,
    no_backslash_escapes: bool,
) -> Option<WordPressSchemaNameFilter> {
    if let Some(table_filter) = query
        .strip_prefix("SHOW TABLE STATUS LIKE ")
        .and_then(|input| parse_sql_single_quoted_schema_like_filter(input, no_backslash_escapes))
    {
        return Some(table_filter);
    }

    let where_clause = query.strip_prefix("SHOW TABLE STATUS WHERE ")?;
    let table_name = where_clause
        .strip_prefix("Name = ")
        .or_else(|| where_clause.strip_prefix("`Name` = "))
        .and_then(parse_sql_single_quoted_list)
        .and_then(|values| (values.len() == 1).then(|| values[0].clone()))?;
    parse_schema_table_identifier(&table_name).map(WordPressSchemaNameFilter::Exact)
}

fn parse_dynamic_schema_show_table_status_in_query(
    query: &str,
    no_backslash_escapes: bool,
) -> Option<Vec<String>> {
    let where_clause = query.strip_prefix("SHOW TABLE STATUS WHERE ")?;
    let input = where_clause
        .strip_prefix("Name IN ")
        .or_else(|| where_clause.strip_prefix("`Name` IN "))?
        .trim();
    let inner = input
        .strip_prefix('(')
        .and_then(|rest| rest.strip_suffix(')'))?;
    let values = parse_sql_single_quoted_list_with_mode(inner, no_backslash_escapes)?;
    if values.is_empty() {
        return None;
    }

    values
        .into_iter()
        .map(|value| parse_schema_table_identifier(&value))
        .collect()
}

fn parse_wordpress_schema_create_table_query(query: &str) -> Option<WordPressSchemaTableState> {
    let query = query.trim().strip_suffix(';').unwrap_or(query.trim());
    let rest = query
        .strip_prefix("CREATE TABLE IF NOT EXISTS ")
        .or_else(|| query.strip_prefix("CREATE TABLE "))?;
    let open = rest.find('(')?;
    let close = rest.rfind(')')?;
    if close <= open {
        return None;
    }
    let table_name = parse_schema_table_identifier(rest[..open].trim())?;
    let body = &rest[open + 1..close];
    let suffix = &rest[close + 1..];
    let mut table = WordPressSchemaTableState {
        name: table_name,
        columns: Vec::new(),
        indexes: Vec::new(),
        collation: parse_schema_collation(suffix),
    };

    for part in split_sql_top_level_commas(body) {
        parse_schema_definition_part(part.trim(), &mut table)?;
    }

    Some(table)
}

fn parse_wordpress_schema_alter_table_query(query: &str) -> Option<WordPressSchemaAlter> {
    let query = query.trim().strip_suffix(';').unwrap_or(query.trim());
    let rest = query.strip_prefix("ALTER TABLE ")?;
    let mut pieces = rest.splitn(2, char::is_whitespace);
    let table_name = parse_schema_table_identifier(pieces.next()?.trim())?;
    let operations = pieces.next()?.trim();
    let mut parsed_operations = Vec::new();

    for part in split_sql_top_level_commas(operations) {
        parsed_operations.extend(parse_schema_alter_operation(part.trim())?);
    }

    Some(WordPressSchemaAlter {
        table_name,
        operations: parsed_operations,
    })
}

fn apply_wordpress_schema_alter(
    table: &mut WordPressSchemaTableState,
    alter: WordPressSchemaAlter,
) {
    for operation in alter.operations {
        match operation {
            WordPressSchemaAlterOperation::AddColumn(column)
            | WordPressSchemaAlterOperation::ModifyColumn(column) => {
                upsert_wordpress_schema_column(table, column);
            }
            WordPressSchemaAlterOperation::AddIndex(index) => {
                upsert_wordpress_schema_index(table, index);
            }
            WordPressSchemaAlterOperation::DropColumn(column_name) => {
                table.columns.retain(|column| column.name != column_name);
                table.indexes.retain(|index| {
                    !index
                        .parts
                        .iter()
                        .any(|part| part.column_name == column_name)
                });
            }
            WordPressSchemaAlterOperation::DropIndex(key_name) => {
                table.indexes.retain(|index| index.key_name != key_name);
            }
            WordPressSchemaAlterOperation::DropPrimaryKey => {
                table.indexes.retain(|index| index.key_name != "PRIMARY");
            }
            WordPressSchemaAlterOperation::ChangeColumn { old_name, column } => {
                let new_name = column.name.clone();
                if let Some(existing) = table
                    .columns
                    .iter_mut()
                    .find(|existing| existing.name == old_name)
                {
                    *existing = column;
                } else {
                    table.columns.push(column);
                }
                for index in &mut table.indexes {
                    for part in &mut index.parts {
                        if part.column_name == old_name {
                            part.column_name = new_name.clone();
                        }
                    }
                }
            }
        }
    }
}

fn apply_wordpress_schema_create_table(
    table: &mut WordPressSchemaTableState,
    create: WordPressSchemaTableState,
) {
    table.collation = create.collation;
    for column in create.columns {
        upsert_wordpress_schema_column(table, column);
    }
    for index in create.indexes {
        upsert_wordpress_schema_index(table, index);
    }
}

fn upsert_wordpress_schema_column(
    table: &mut WordPressSchemaTableState,
    column: WordPressSchemaColumnState,
) {
    if let Some(existing) = table
        .columns
        .iter_mut()
        .find(|existing| existing.name == column.name)
    {
        *existing = column;
    } else {
        table.columns.push(column);
    }
}

fn upsert_wordpress_schema_index(
    table: &mut WordPressSchemaTableState,
    index: WordPressSchemaIndexState,
) {
    if let Some(existing) = table
        .indexes
        .iter_mut()
        .find(|existing| existing.key_name == index.key_name)
    {
        *existing = index;
    } else {
        table.indexes.push(index);
    }
}

fn parse_schema_alter_operation(part: &str) -> Option<Vec<WordPressSchemaAlterOperation>> {
    if let Some(definition) = part
        .strip_prefix("ADD COLUMN ")
        .or_else(|| part.strip_prefix("ADD "))
    {
        let mut scratch = WordPressSchemaTableState {
            name: String::new(),
            columns: Vec::new(),
            indexes: Vec::new(),
            collation: "utf8mb4_unicode_ci".to_string(),
        };
        parse_schema_definition_part(definition.trim(), &mut scratch)?;
        let mut operations = Vec::new();
        operations.extend(
            scratch
                .columns
                .into_iter()
                .map(WordPressSchemaAlterOperation::AddColumn),
        );
        operations.extend(
            scratch
                .indexes
                .into_iter()
                .map(WordPressSchemaAlterOperation::AddIndex),
        );
        return Some(operations);
    }

    if let Some(column_name) = part
        .strip_prefix("DROP COLUMN ")
        .or_else(|| part.strip_prefix("DROP "))
        .and_then(|rest| parse_schema_table_identifier(rest.trim()))
    {
        return Some(vec![WordPressSchemaAlterOperation::DropColumn(column_name)]);
    }

    if let Some(key_name) = part
        .strip_prefix("DROP KEY ")
        .or_else(|| part.strip_prefix("DROP INDEX "))
        .and_then(|rest| parse_schema_table_identifier(rest.trim()))
    {
        return Some(vec![WordPressSchemaAlterOperation::DropIndex(key_name)]);
    }

    if part == "DROP PRIMARY KEY" {
        return Some(vec![WordPressSchemaAlterOperation::DropPrimaryKey]);
    }

    if let Some(definition) = part
        .strip_prefix("MODIFY COLUMN ")
        .or_else(|| part.strip_prefix("MODIFY "))
    {
        let parsed = parse_schema_column_definition(definition.trim())?;
        let mut operations = vec![WordPressSchemaAlterOperation::ModifyColumn(parsed.column)];
        operations.extend(
            parsed
                .indexes
                .into_iter()
                .map(WordPressSchemaAlterOperation::AddIndex),
        );
        return Some(operations);
    }

    if let Some(definition) = part
        .strip_prefix("CHANGE COLUMN ")
        .or_else(|| part.strip_prefix("CHANGE "))
    {
        let (old_name, new_definition) = parse_leading_schema_identifier(definition.trim())?;
        let parsed = parse_schema_column_definition(new_definition.trim())?;
        let mut operations = vec![WordPressSchemaAlterOperation::ChangeColumn {
            old_name,
            column: parsed.column,
        }];
        operations.extend(
            parsed
                .indexes
                .into_iter()
                .map(WordPressSchemaAlterOperation::AddIndex),
        );
        return Some(operations);
    }

    None
}

fn parse_schema_definition_part(part: &str, table: &mut WordPressSchemaTableState) -> Option<()> {
    let upper = part.to_ascii_uppercase();
    if upper.starts_with("PRIMARY KEY") {
        let parts = parse_schema_index_parts(part)?;
        table.indexes.push(WordPressSchemaIndexState {
            key_name: "PRIMARY".to_string(),
            parts,
            non_unique: false,
            index_type: WordPressSchemaIndexType::Btree,
        });
        return Some(());
    }

    if upper.starts_with("FULLTEXT KEY ") || upper.starts_with("FULLTEXT INDEX ") {
        let rest = part
            .strip_prefix("FULLTEXT KEY ")
            .or_else(|| part.strip_prefix("FULLTEXT INDEX "))?;
        let (key_name, parts) = parse_schema_named_index(rest)?;
        table.indexes.push(WordPressSchemaIndexState {
            key_name,
            parts,
            non_unique: true,
            index_type: WordPressSchemaIndexType::Fulltext,
        });
        return Some(());
    }

    if upper.starts_with("SPATIAL KEY ") || upper.starts_with("SPATIAL INDEX ") {
        let rest = part
            .strip_prefix("SPATIAL KEY ")
            .or_else(|| part.strip_prefix("SPATIAL INDEX "))?;
        let (key_name, parts) = parse_schema_named_index(rest)?;
        table.indexes.push(WordPressSchemaIndexState {
            key_name,
            parts,
            non_unique: true,
            index_type: WordPressSchemaIndexType::Spatial,
        });
        return Some(());
    }

    if upper.starts_with("UNIQUE KEY ") || upper.starts_with("UNIQUE INDEX ") {
        let rest = part
            .strip_prefix("UNIQUE KEY ")
            .or_else(|| part.strip_prefix("UNIQUE INDEX "))?;
        let (key_name, parts) = parse_schema_named_index(rest)?;
        table.indexes.push(WordPressSchemaIndexState {
            key_name,
            parts,
            non_unique: false,
            index_type: WordPressSchemaIndexType::Btree,
        });
        return Some(());
    }

    if upper.starts_with("KEY ") || upper.starts_with("INDEX ") {
        let rest = part
            .strip_prefix("KEY ")
            .or_else(|| part.strip_prefix("INDEX "))?;
        let (key_name, parts) = parse_schema_named_index(rest)?;
        table.indexes.push(WordPressSchemaIndexState {
            key_name,
            parts,
            non_unique: true,
            index_type: WordPressSchemaIndexType::Btree,
        });
        return Some(());
    }

    let parsed = parse_schema_column_definition(part)?;
    table.columns.push(parsed.column);
    table.indexes.extend(parsed.indexes);
    Some(())
}

fn parse_schema_column_definition(part: &str) -> Option<ParsedWordPressSchemaColumnDefinition> {
    let mut split = part.splitn(2, char::is_whitespace);
    let name = parse_schema_table_identifier(split.next()?.trim())?;
    let rest = split.next()?.trim();
    let ty_len = rest
        .char_indices()
        .scan(0_i32, |depth, (idx, ch)| {
            match ch {
                '(' => *depth += 1,
                ')' => *depth -= 1,
                _ => {}
            }
            Some((idx, ch, *depth))
        })
        .find_map(|(idx, ch, depth)| (depth == 0 && ch.is_whitespace()).then_some(idx))
        .unwrap_or(rest.len());
    let mut ty = rest[..ty_len].trim().to_string();
    let mut attributes = rest[ty_len..].trim();
    if let Some(after_unsigned) = attributes
        .strip_prefix("unsigned ")
        .or_else(|| attributes.strip_prefix("UNSIGNED "))
    {
        ty.push_str(" unsigned");
        attributes = after_unsigned.trim();
    }
    let upper = attributes.to_ascii_uppercase();
    let nullable = !upper.contains("NOT NULL");
    let auto_increment = upper.contains("AUTO_INCREMENT");
    let column = WordPressSchemaColumnState {
        name: name.clone(),
        ty,
        nullable,
        default: parse_schema_default(attributes),
        auto_increment,
    };
    Some(ParsedWordPressSchemaColumnDefinition {
        column,
        indexes: parse_schema_inline_column_indexes(&name, attributes),
    })
}

fn parse_schema_inline_column_indexes(
    column_name: &str,
    attributes: &str,
) -> Vec<WordPressSchemaIndexState> {
    let upper = attributes.to_ascii_uppercase();
    let part = WordPressSchemaIndexPart {
        column_name: column_name.to_string(),
        sub_part: None,
        order: WordPressSchemaIndexOrder::Asc,
    };

    if upper.contains("PRIMARY KEY") {
        return vec![WordPressSchemaIndexState {
            key_name: "PRIMARY".to_string(),
            parts: vec![part],
            non_unique: false,
            index_type: WordPressSchemaIndexType::Btree,
        }];
    }

    if upper.starts_with("UNIQUE")
        || upper.contains(" UNIQUE")
        || upper.contains("UNIQUE KEY")
        || upper.contains("UNIQUE INDEX")
    {
        return vec![WordPressSchemaIndexState {
            key_name: column_name.to_string(),
            parts: vec![part],
            non_unique: false,
            index_type: WordPressSchemaIndexType::Btree,
        }];
    }

    if upper.starts_with("KEY")
        || upper.starts_with("INDEX")
        || upper.contains(" KEY")
        || upper.contains(" INDEX")
    {
        return vec![WordPressSchemaIndexState {
            key_name: column_name.to_string(),
            parts: vec![part],
            non_unique: true,
            index_type: WordPressSchemaIndexType::Btree,
        }];
    }

    Vec::new()
}

fn parse_schema_named_index(rest: &str) -> Option<(String, Vec<WordPressSchemaIndexPart>)> {
    let open = rest.find('(')?;
    let key_name = parse_schema_table_identifier(rest[..open].trim())?;
    let parts = parse_schema_index_parts(rest)?;
    Some((key_name, parts))
}

fn parse_schema_index_parts(part: &str) -> Option<Vec<WordPressSchemaIndexPart>> {
    let open = part.find('(')?;
    let close = part.rfind(')')?;
    if close <= open {
        return None;
    }
    let mut parts = Vec::new();
    for raw_part in split_sql_top_level_commas(&part[open + 1..close]) {
        parts.push(parse_schema_index_part(raw_part.trim())?);
    }
    (!parts.is_empty()).then_some(parts)
}

fn parse_schema_index_part(part: &str) -> Option<WordPressSchemaIndexPart> {
    let (identifier, rest) = if let Some(after_tick) = part.strip_prefix('`') {
        let (identifier, rest) = after_tick.split_once('`')?;
        (identifier, rest.trim())
    } else {
        let split_at = part
            .char_indices()
            .find_map(|(idx, ch)| (ch.is_whitespace() || ch == '(').then_some(idx))
            .unwrap_or(part.len());
        (&part[..split_at], part[split_at..].trim())
    };
    let column_name = parse_schema_table_identifier(identifier)?;
    let sub_part = rest
        .strip_prefix('(')
        .and_then(|value| value.split_once(')'))
        .and_then(|(value, _)| value.trim().parse::<i64>().ok());
    let order_rest = if rest.starts_with('(') {
        rest.split_once(')')
            .map(|(_, after)| after.trim())
            .unwrap_or(rest)
    } else {
        rest
    };
    let order = match order_rest.to_ascii_uppercase().as_str() {
        "" | "ASC" => WordPressSchemaIndexOrder::Asc,
        "DESC" => WordPressSchemaIndexOrder::Desc,
        _ => return None,
    };
    Some(WordPressSchemaIndexPart {
        column_name,
        sub_part,
        order,
    })
}

fn parse_leading_schema_identifier(input: &str) -> Option<(String, &str)> {
    let input = input.trim_start();
    if let Some(after_tick) = input.strip_prefix('`') {
        let (identifier, rest) = after_tick.split_once('`')?;
        return Some((
            parse_schema_table_identifier(identifier)?,
            rest.trim_start(),
        ));
    }

    let split_at = input
        .char_indices()
        .find_map(|(idx, ch)| ch.is_whitespace().then_some(idx))?;
    Some((
        parse_schema_table_identifier(&input[..split_at])?,
        input[split_at..].trim_start(),
    ))
}

fn parse_schema_table_identifier(identifier: &str) -> Option<String> {
    let identifier = identifier.trim();
    if identifier.is_empty() {
        return None;
    }
    let identifier = identifier
        .strip_prefix('`')
        .and_then(|value| value.strip_suffix('`'))
        .unwrap_or(identifier);
    if identifier.is_empty()
        || !identifier
            .chars()
            .all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
    {
        return None;
    }
    Some(identifier.to_string())
}

fn parse_schema_collation(suffix: &str) -> String {
    suffix
        .split_whitespace()
        .find_map(|part| {
            part.strip_prefix("COLLATE=")
                .or_else(|| part.strip_prefix("COLLATE "))
        })
        .map(str::to_string)
        .unwrap_or_else(|| "utf8mb4_unicode_ci".to_string())
}

fn parse_schema_default(attributes: &str) -> Option<WordPressSchemaColumnDefault> {
    let default_index = find_schema_default_keyword(attributes)?;
    let default_sql = attributes[default_index + "DEFAULT".len()..].trim_start();
    if default_sql.is_empty() {
        return None;
    }

    if default_sql
        .get(..4)
        .is_some_and(|value| value.eq_ignore_ascii_case("NULL"))
        && default_sql
            .get(4..)
            .and_then(|rest| rest.chars().next())
            .map(|ch| ch.is_whitespace() || ch == ',' || ch == ')')
            .unwrap_or(true)
    {
        return Some(WordPressSchemaColumnDefault::Null);
    }

    if let Some(value) = parse_schema_single_quoted_value(default_sql) {
        return Some(WordPressSchemaColumnDefault::Value(value));
    }

    parse_schema_unquoted_default_value(default_sql).map(WordPressSchemaColumnDefault::Value)
}

fn find_schema_default_keyword(attributes: &str) -> Option<usize> {
    let mut in_string = false;
    let mut escaped = false;
    for (idx, ch) in attributes.char_indices() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '\'' {
                in_string = false;
            }
            continue;
        }
        if ch == '\'' {
            in_string = true;
            continue;
        }
        if attributes[idx..]
            .get(.."DEFAULT".len())
            .is_some_and(|value| value.eq_ignore_ascii_case("DEFAULT"))
        {
            let before_ok = attributes[..idx]
                .chars()
                .next_back()
                .map(|before| !is_schema_identifier_char(before))
                .unwrap_or(true);
            let after_ok = attributes[idx + "DEFAULT".len()..]
                .chars()
                .next()
                .map(|after| !is_schema_identifier_char(after))
                .unwrap_or(true);
            if before_ok && after_ok {
                return Some(idx);
            }
        }
    }
    None
}

fn is_schema_identifier_char(ch: char) -> bool {
    ch == '_' || ch.is_ascii_alphanumeric()
}

fn parse_schema_single_quoted_value(input: &str) -> Option<String> {
    let mut chars = input.strip_prefix('\'')?.char_indices().peekable();
    let mut value = String::new();
    while let Some((idx, ch)) = chars.next() {
        match ch {
            '\'' => {
                if let Some((_, '\'')) = chars.peek().copied() {
                    chars.next();
                    value.push('\'');
                    continue;
                }
                let rest = &input[idx + 1 + '\''.len_utf8()..];
                let terminates = rest
                    .chars()
                    .next()
                    .map(|after| after.is_whitespace() || after == ',' || after == ')')
                    .unwrap_or(true);
                return terminates.then_some(value);
            }
            '\\' => {
                if let Some((_, escaped)) = chars.next() {
                    value.push(match escaped {
                        '0' => '\0',
                        '\'' => '\'',
                        '"' => '"',
                        'b' => '\u{0008}',
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        'Z' => '\u{001A}',
                        '\\' => '\\',
                        other => other,
                    });
                } else {
                    value.push(ch);
                }
            }
            other => value.push(other),
        }
    }
    None
}

fn parse_schema_unquoted_default_value(input: &str) -> Option<String> {
    let mut end = input.len();
    let mut depth = 0_i32;
    for (idx, ch) in input.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' if depth > 0 => depth -= 1,
            ')' | ',' if depth == 0 => {
                end = idx;
                break;
            }
            ch if depth == 0 && ch.is_whitespace() => {
                end = idx;
                break;
            }
            _ => {}
        }
    }
    let value = input[..end].trim();
    (!value.is_empty()).then(|| value.to_string())
}

fn split_sql_top_level_commas(input: &str) -> Vec<&str> {
    let mut parts = Vec::new();
    let mut start = 0;
    let mut depth = 0_i32;
    let mut in_string = false;
    let mut escaped = false;
    for (idx, ch) in input.char_indices() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '\'' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '\'' => in_string = true,
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                parts.push(input[start..idx].trim());
                start = idx + ch.len_utf8();
            }
            _ => {}
        }
    }
    parts.push(input[start..].trim());
    parts
}

fn dynamic_schema_describe_row(
    column: &WordPressSchemaColumnState,
    table: &WordPressSchemaTableState,
) -> Vec<(String, Value)> {
    vec![
        ("Field".to_string(), Value::String(column.name.clone())),
        ("Type".to_string(), Value::String(column.ty.clone())),
        (
            "Null".to_string(),
            Value::String(if column.nullable { "YES" } else { "NO" }.to_string()),
        ),
        (
            "Key".to_string(),
            Value::String(dynamic_schema_column_key(column, table).to_string()),
        ),
        (
            "Default".to_string(),
            column
                .default
                .as_ref()
                .and_then(|default| match default {
                    WordPressSchemaColumnDefault::Value(value) => {
                        Some(Value::String(value.clone()))
                    }
                    WordPressSchemaColumnDefault::Null => None,
                })
                .unwrap_or(Value::Null),
        ),
        (
            "Extra".to_string(),
            Value::String(
                if column.auto_increment {
                    "auto_increment"
                } else {
                    ""
                }
                .to_string(),
            ),
        ),
    ]
}

fn dynamic_schema_full_column_row(
    column: &WordPressSchemaColumnState,
    table: &WordPressSchemaTableState,
) -> Vec<(String, Value)> {
    let mut row = dynamic_schema_describe_row(column, table);
    row.insert(
        2,
        (
            "Collation".to_string(),
            if dynamic_schema_column_has_collation(column) {
                Value::String(table.collation.clone())
            } else {
                Value::Null
            },
        ),
    );
    row.push((
        "Privileges".to_string(),
        Value::String("select,insert,update,references".to_string()),
    ));
    row.push(("Comment".to_string(), Value::String(String::new())));
    row
}

fn dynamic_schema_column_key(
    column: &WordPressSchemaColumnState,
    table: &WordPressSchemaTableState,
) -> &'static str {
    table
        .indexes
        .iter()
        .find(|index| {
            index
                .parts
                .iter()
                .any(|part| part.column_name == column.name)
        })
        .map(|index| {
            if index.key_name == "PRIMARY" {
                "PRI"
            } else if !index.non_unique && index.parts.len() == 1 {
                "UNI"
            } else if index.non_unique {
                "MUL"
            } else {
                "MUL"
            }
        })
        .unwrap_or("")
}

fn dynamic_schema_column_has_collation(column: &WordPressSchemaColumnState) -> bool {
    let ty = column.ty.to_ascii_lowercase();
    ty.contains("char") || ty.contains("text")
}

fn dynamic_schema_index_row(
    table_name: &str,
    index: &WordPressSchemaIndexState,
    part: &WordPressSchemaIndexPart,
    seq_in_index: i64,
) -> Vec<(String, Value)> {
    vec![
        ("Table".to_string(), Value::String(table_name.to_string())),
        (
            "Non_unique".to_string(),
            Value::Int(if index.non_unique { 1 } else { 0 }),
        ),
        (
            "Key_name".to_string(),
            Value::String(index.key_name.clone()),
        ),
        ("Seq_in_index".to_string(), Value::Int(seq_in_index)),
        (
            "Column_name".to_string(),
            Value::String(part.column_name.clone()),
        ),
        (
            "Collation".to_string(),
            Value::String(
                match part.order {
                    WordPressSchemaIndexOrder::Asc => "A",
                    WordPressSchemaIndexOrder::Desc => "D",
                }
                .to_string(),
            ),
        ),
        ("Cardinality".to_string(), Value::Int(0)),
        (
            "Sub_part".to_string(),
            part.sub_part.map(Value::Int).unwrap_or(Value::Null),
        ),
        ("Packed".to_string(), Value::Null),
        ("Null".to_string(), Value::String(String::new())),
        (
            "Index_type".to_string(),
            Value::String(dynamic_schema_index_type_sql(index).to_string()),
        ),
        ("Comment".to_string(), Value::String(String::new())),
        ("Index_comment".to_string(), Value::String(String::new())),
        ("Visible".to_string(), Value::String("YES".to_string())),
        ("Expression".to_string(), Value::Null),
    ]
}

