fn joined_schema_column_index_metadata_result(
    table: &WordPressSchemaTableState,
) -> MysqliPendingResultState {
    let fields = vec![
        "Field".to_string(),
        "Type".to_string(),
        "Null".to_string(),
        "Key".to_string(),
        "Key_name".to_string(),
        "Seq_in_index".to_string(),
        "Sub_part".to_string(),
    ];
    let mut rows = Vec::new();
    for column in &table.columns {
        let matched_parts = table
            .indexes
            .iter()
            .flat_map(|index| {
                index
                    .parts
                    .iter()
                    .enumerate()
                    .map(move |(part_index, part)| (index, part_index, part))
            })
            .filter(|(_, _, part)| part.column_name == column.name)
            .collect::<Vec<_>>();
        if matched_parts.is_empty() {
            rows.push(joined_schema_column_index_metadata_row(table, column, None));
            continue;
        }
        for (index, part_index, part) in matched_parts {
            rows.push(joined_schema_column_index_metadata_row(
                table,
                column,
                Some((index, part_index, part)),
            ));
        }
    }
    MysqliPendingResultState { fields, rows }
}

fn joined_schema_column_index_metadata_row(
    table: &WordPressSchemaTableState,
    column: &WordPressSchemaColumnState,
    index_part: Option<(&WordPressSchemaIndexState, usize, &WordPressSchemaIndexPart)>,
) -> Vec<(String, Value)> {
    let (key_name, seq_in_index, sub_part) = index_part
        .map(|(index, part_index, part)| {
            (
                Value::String(index.key_name.clone()),
                Value::Int((part_index + 1) as i64),
                part.sub_part.map(Value::Int).unwrap_or(Value::Null),
            )
        })
        .unwrap_or((Value::Null, Value::Null, Value::Null));
    vec![
        ("Field".to_string(), Value::String(column.name.clone())),
        ("Type".to_string(), Value::String(column.ty.clone())),
        (
            "Null".to_string(),
            Value::String(if column.nullable { "YES" } else { "NO" }.to_string()),
        ),
        (
            "Key".to_string(),
            Value::String(dynamic_schema_column_key(column, table).to_string()),
        ),
        ("Key_name".to_string(), key_name),
        ("Seq_in_index".to_string(), seq_in_index),
        ("Sub_part".to_string(), sub_part),
    ]
}

fn dynamic_schema_create_table_sql(table: &WordPressSchemaTableState) -> String {
    let mut lines = Vec::new();
    for column in &table.columns {
        lines.push(format!(
            "  {} {}",
            quote_schema_identifier(&column.name),
            dynamic_schema_column_sql(column)
        ));
    }
    for index in &table.indexes {
        lines.push(format!("  {}", dynamic_schema_index_sql(index)));
    }

    format!(
        "CREATE TABLE {} (\n{}\n) DEFAULT CHARSET=utf8mb4 COLLATE={}",
        quote_schema_identifier(&table.name),
        lines.join(",\n"),
        table.collation
    )
}

fn dynamic_schema_column_sql(column: &WordPressSchemaColumnState) -> String {
    let mut sql = column.ty.clone();
    if column.nullable {
        sql.push_str(" NULL");
    } else {
        sql.push_str(" NOT NULL");
    }
    if let Some(default) = &column.default {
        sql.push_str(" DEFAULT ");
        match default {
            WordPressSchemaColumnDefault::Value(value) => sql.push_str(&quote_schema_string(value)),
            WordPressSchemaColumnDefault::Null => sql.push_str("NULL"),
        }
    }
    if column.auto_increment {
        sql.push_str(" auto_increment");
    }
    sql
}

fn dynamic_schema_index_sql(index: &WordPressSchemaIndexState) -> String {
    let parts = index
        .parts
        .iter()
        .map(|part| {
            let mut sql = quote_schema_identifier(&part.column_name);
            if let Some(sub_part) = part.sub_part {
                sql.push('(');
                sql.push_str(&sub_part.to_string());
                sql.push(')');
            }
            if matches!(part.order, WordPressSchemaIndexOrder::Desc) {
                sql.push_str(" DESC");
            }
            sql
        })
        .collect::<Vec<_>>()
        .join(",");

    if index.key_name == "PRIMARY" {
        format!("PRIMARY KEY ({parts})")
    } else if matches!(index.index_type, WordPressSchemaIndexType::Fulltext) {
        format!(
            "FULLTEXT KEY {} ({parts})",
            quote_schema_identifier(&index.key_name)
        )
    } else if matches!(index.index_type, WordPressSchemaIndexType::Spatial) {
        format!(
            "SPATIAL KEY {} ({parts})",
            quote_schema_identifier(&index.key_name)
        )
    } else if index.non_unique {
        format!("KEY {} ({parts})", quote_schema_identifier(&index.key_name))
    } else {
        format!(
            "UNIQUE KEY {} ({parts})",
            quote_schema_identifier(&index.key_name)
        )
    }
}

fn dynamic_schema_index_type_sql(index: &WordPressSchemaIndexState) -> &'static str {
    match index.index_type {
        WordPressSchemaIndexType::Btree => "BTREE",
        WordPressSchemaIndexType::Fulltext => "FULLTEXT",
        WordPressSchemaIndexType::Spatial => "SPATIAL",
    }
}

fn quote_schema_identifier(identifier: &str) -> String {
    format!("`{}`", identifier.replace('`', "``"))
}

fn quote_schema_string(value: &str) -> String {
    format!("'{}'", value.replace('\\', "\\\\").replace('\'', "\\'"))
}

fn wordpress_options_schema_result_for_query(query: &str) -> Option<MysqliPendingResultState> {
    let query = query.trim().strip_suffix(';').unwrap_or(query.trim());
    if matches!(
        query,
        "DESCRIBE wp_options" | "DESCRIBE `wp_options`" | "DESC wp_options" | "DESC `wp_options`"
    ) {
        return Some(MysqliPendingResultState {
            fields: vec![
                "Field".to_string(),
                "Type".to_string(),
                "Null".to_string(),
                "Key".to_string(),
                "Default".to_string(),
                "Extra".to_string(),
            ],
            rows: wordpress_options_describe_rows(),
        });
    }

    if matches!(
        query,
        "SHOW FULL COLUMNS FROM wp_options"
            | "SHOW FULL COLUMNS FROM `wp_options`"
            | "SHOW COLUMNS FROM wp_options"
            | "SHOW COLUMNS FROM `wp_options`"
    ) {
        return Some(MysqliPendingResultState {
            fields: vec![
                "Field".to_string(),
                "Type".to_string(),
                "Collation".to_string(),
                "Null".to_string(),
                "Key".to_string(),
                "Default".to_string(),
                "Extra".to_string(),
                "Privileges".to_string(),
                "Comment".to_string(),
            ],
            rows: wordpress_options_full_column_rows(),
        });
    }

    if matches!(
        query,
        "SHOW INDEX FROM wp_options"
            | "SHOW INDEX FROM `wp_options`"
            | "SHOW INDEXES FROM wp_options"
            | "SHOW INDEXES FROM `wp_options`"
            | "SHOW KEYS FROM wp_options"
            | "SHOW KEYS FROM `wp_options`"
    ) {
        return Some(MysqliPendingResultState {
            fields: vec![
                "Table".to_string(),
                "Non_unique".to_string(),
                "Key_name".to_string(),
                "Seq_in_index".to_string(),
                "Column_name".to_string(),
                "Collation".to_string(),
                "Cardinality".to_string(),
                "Sub_part".to_string(),
                "Packed".to_string(),
                "Null".to_string(),
                "Index_type".to_string(),
                "Comment".to_string(),
                "Index_comment".to_string(),
                "Visible".to_string(),
                "Expression".to_string(),
            ],
            rows: wordpress_options_index_rows(),
        });
    }

    let table_like = query
        .strip_prefix("SHOW TABLES LIKE ")
        .and_then(parse_sql_single_quoted_list)
        .and_then(|values| {
            if values.len() == 1 {
                Some(values[0].clone())
            } else {
                None
            }
        })?;
    if table_like == "wp_options" {
        return Some(MysqliPendingResultState {
            fields: vec!["Tables_in_wordpress (wp_options)".to_string()],
            rows: vec![vec![(
                "Tables_in_wordpress (wp_options)".to_string(),
                Value::String("wp_options".to_string()),
            )]],
        });
    }

    None
}

