fn uuencode_char(value: u8) -> u8 {
    let value = value & 0x3f;
    if value == 0 {
        b'`'
    } else {
        value + 32
    }
}

fn uudecode_char(byte: u8) -> Option<u8> {
    match byte {
        b'`' | b' ' => Some(0),
        33..=96 => Some((byte - 32) & 0x3f),
        _ => None,
    }
}

fn uuencode_bytes(value: &[u8]) -> Vec<u8> {
    let mut output = Vec::new();
    for chunk in value.chunks(45) {
        output.push(uuencode_char(chunk.len() as u8));
        for triple in chunk.chunks(3) {
            let a = triple.first().copied().unwrap_or(0);
            let b = triple.get(1).copied().unwrap_or(0);
            let c = triple.get(2).copied().unwrap_or(0);
            output.push(uuencode_char(a >> 2));
            output.push(uuencode_char(((a << 4) | (b >> 4)) & 0x3f));
            output.push(uuencode_char(((b << 2) | (c >> 6)) & 0x3f));
            output.push(uuencode_char(c & 0x3f));
        }
        output.push(b'\n');
    }
    output.extend_from_slice(b"`\n");
    output
}

fn uudecode_bytes(value: &[u8]) -> Option<Vec<u8>> {
    if value.is_empty() {
        return None;
    }

    let mut output = Vec::new();
    let mut saw_terminator = false;
    for raw_line in value.split(|byte| *byte == b'\n') {
        let line = raw_line.strip_suffix(b"\r").unwrap_or(raw_line);
        if line.is_empty() {
            continue;
        }
        let expected_len = uudecode_char(line[0])? as usize;
        if expected_len == 0 {
            saw_terminator = true;
            break;
        }

        let mut line_output = Vec::new();
        for encoded in line[1..].chunks(4) {
            if encoded.len() < 4 {
                break;
            }
            let a = uudecode_char(encoded[0])?;
            let b = uudecode_char(encoded[1])?;
            let c = uudecode_char(encoded[2])?;
            let d = uudecode_char(encoded[3])?;
            line_output.push((a << 2) | (b >> 4));
            line_output.push((b << 4) | (c >> 2));
            line_output.push((c << 6) | d);
        }
        if line_output.len() < expected_len {
            return None;
        }
        output.extend_from_slice(&line_output[..expected_len]);
    }

    (saw_terminator || !output.is_empty()).then_some(output)
}

fn base64_decode_ignored_whitespace(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | b'\r')
}

impl Interpreter {
    fn call_hex2bin(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("hex2bin", args, 1, span)?;

        let value = string_compare_argument_bytes("hex2bin()", "string", &args[0], span)?;
        if value.len() % 2 != 0 {
            self.emit_display_warning(
                "hex2bin(): Hexadecimal input string must have an even length",
                span,
            )?;
            return Ok(Value::Bool(false));
        }

        let mut output = Vec::with_capacity(value.len() / 2);
        for pair in value.chunks_exact(2) {
            let (Some(high), Some(low)) = (hex_digit_value(pair[0]), hex_digit_value(pair[1]))
            else {
                self.emit_display_warning(
                    "hex2bin(): Input string must be hexadecimal string",
                    span,
                )?;
                return Ok(Value::Bool(false));
            };
            output.push((high << 4) | low);
        }

        Ok(interpreter_value_from_php_string_bytes(output))
    }

    fn call_ord(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("ord", args, 1, span)?;

        let value = string_compare_argument_bytes("ord()", "character", &args[0], span)?;
        if value.is_empty() {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "ord(): Providing an empty string is deprecated",
                span,
            )?;
            return Ok(Value::Int(0));
        }

        if value.len() != 1 {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "ord(): Providing a string that is not one byte long is deprecated. Use ord($str[0]) instead",
                span,
            )?;
        }

        Ok(Value::Int(i64::from(value[0])))
    }

    fn call_int_base_string_builtin(
        &mut self,
        function: &'static str,
        args: &[Value],
        base: u32,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function.trim_end_matches("()"), args, 1, span)?;
        let value = self.php_base_conversion_int_argument(function, &args[0], span)?;
        Ok(Value::String(format_unsigned_radix(value as u64, base)))
    }

    fn php_base_conversion_int_argument(
        &mut self,
        function: &'static str,
        arg: &Value,
        span: Span,
    ) -> CompileResult<i64> {
        match arg {
            Value::Null => Ok(0),
            Value::Bool(value) => Ok(i64::from(*value)),
            Value::Int(value) => Ok(*value),
            Value::Float(value) => {
                if let Some(parsed) = php_base_conversion_float_to_i64(*value) {
                    if value.trunc() != *value {
                        self.emit_display_diagnostic(
                            "Deprecated",
                            PHP_E_DEPRECATED,
                            format!(
                                "Implicit conversion from float {} to int loses precision",
                                format_php_float_to_int_deprecation_value(*value)
                            ),
                            span,
                        )?;
                    }
                    Ok(parsed)
                } else {
                    Err(php_internal_int_type_error(function, 1, "num", arg, span))
                }
            }
            Value::String(value) => {
                if let Some(parsed) = parse_base_conversion_integer_string(value, self, span)? {
                    Ok(parsed)
                } else {
                    Err(php_internal_int_type_error(function, 1, "num", arg, span))
                }
            }
            Value::BinaryString(bytes) => {
                if let Ok(value) = std::str::from_utf8(bytes) {
                    if let Some(parsed) = parse_base_conversion_integer_string(value, self, span)? {
                        return Ok(parsed);
                    }
                }
                Err(php_internal_int_type_error(function, 1, "num", arg, span))
            }
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
                Err(php_internal_int_type_error(function, 1, "num", arg, span))
            }
        }
    }

    fn call_hexdec(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("hexdec", args, 1, span)?;
        let input = self.php_hexdec_string_argument(&args[0], span)?;
        let (value, ignored_invalid) = parse_php_base_string(&input, 16);
        if ignored_invalid {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Invalid characters passed for attempted conversion, these have been ignored",
                span,
            )?;
        }

        if value <= i64::MAX as u128 {
            Ok(Value::Int(value as i64))
        } else {
            Ok(Value::Float(value as f64))
        }
    }

    fn call_string_base_int_builtin(
        &mut self,
        function: &'static str,
        parameter: &'static str,
        args: &[Value],
        base: u32,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function.trim_end_matches("()"), args, 1, span)?;
        let input = self.php_basedec_string_argument(function, parameter, &args[0], span)?;
        let (value, ignored_invalid) = parse_php_base_string(&input, base);
        if ignored_invalid {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Invalid characters passed for attempted conversion, these have been ignored",
                span,
            )?;
        }

        if value <= i64::MAX as u128 {
            Ok(Value::Int(value as i64))
        } else {
            Ok(Value::Float(value as f64))
        }
    }

    fn php_hexdec_string_argument(&mut self, value: &Value, span: Span) -> CompileResult<String> {
        self.php_basedec_string_argument("hexdec()", "hex_string", value, span)
    }

    fn php_basedec_string_argument(
        &mut self,
        function: &'static str,
        parameter: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            Value::String(value) => Ok(value.clone()),
            Value::BinaryString(bytes) => Ok(String::from_utf8_lossy(bytes).into_owned()),
            Value::Float(float) => Ok(format_php_precision_float(
                *float,
                self.php_scalar_precision(),
            )),
            Value::Null | Value::Bool(_) | Value::Int(_) => Ok(value.echo_string()),
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        format!(
                            "Argument #1 (${parameter}) must be of type string, {} given",
                            php_type_error_given(value)
                        ),
                    ),
                ))
            }
        }
    }

    fn call_base_convert(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("base_convert", args, 3, span)?;
        let input = self.php_base_convert_string_argument(&args[0], span)?;
        let from_base =
            php_internal_int_argument("base_convert()", 2, "from_base", &args[1], span)?;
        let to_base = php_internal_int_argument("base_convert()", 3, "to_base", &args[2], span)?;
        if !(2..=36).contains(&from_base) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "base_convert()",
                    "Argument #2 ($from_base) must be between 2 and 36 (inclusive)",
                ),
            ));
        }
        if !(2..=36).contains(&to_base) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "base_convert()",
                    "Argument #3 ($to_base) must be between 2 and 36 (inclusive)",
                ),
            ));
        }

        let (value, ignored_invalid) = parse_php_base_string(&input, from_base as u32);
        if ignored_invalid {
            self.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "Invalid characters passed for attempted conversion, these have been ignored",
                span,
            )?;
        }
        Ok(Value::String(format_unsigned_radix_any(
            value,
            to_base as u32,
        )))
    }

    fn php_base_convert_string_argument(
        &mut self,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        match value {
            Value::String(value) => Ok(value.clone()),
            Value::BinaryString(bytes) => Ok(String::from_utf8_lossy(bytes).into_owned()),
            Value::Float(float) => Ok(format_php_precision_float(
                *float,
                self.php_scalar_precision(),
            )),
            Value::Null | Value::Bool(_) | Value::Int(_) => Ok(value.echo_string()),
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
                Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "base_convert()",
                        format!(
                            "Argument #1 ($num) must be of type string, {} given",
                            php_type_error_given(value)
                        ),
                    ),
                ))
            }
        }
    }

    fn php_scalar_precision(&self) -> usize {
        self.ini_value("precision")
            .as_deref()
            .and_then(parse_ini_i64_prefix)
            .filter(|precision| *precision > 0)
            .and_then(|precision| usize::try_from(precision).ok())
            .unwrap_or(14)
            .min(100)
    }

    fn php_scalar_float_string(&self, value: f64) -> String {
        match self
            .ini_value("precision")
            .as_deref()
            .and_then(parse_ini_i64_prefix)
        {
            Some(-1) => format_php_shortest_float(value),
            Some(precision) if precision > 0 => {
                let precision = usize::try_from(precision).unwrap_or(100).min(100);
                format_php_precision_float(value, precision)
            }
            _ => php_default_precision_float_string(value),
        }
    }

    fn php_serialize_precision(&self) -> Option<usize> {
        self.ini_value("serialize_precision")
            .as_deref()
            .and_then(parse_ini_i64_prefix)
            .filter(|precision| *precision > 0)
            .and_then(|precision| usize::try_from(precision).ok())
            .map(|precision| precision.min(100))
    }
}

fn parse_base_conversion_integer_string(
    value: &str,
    interpreter: &mut Interpreter,
    span: Span,
) -> CompileResult<Option<i64>> {
    if let Ok(parsed) = value.parse::<i64>() {
        return Ok(Some(parsed));
    }

    let Ok(parsed) = value.parse::<f64>() else {
        return Ok(None);
    };
    let Some(integer) = php_base_conversion_float_to_i64(parsed) else {
        return Ok(None);
    };
    if parsed.trunc() != parsed {
        interpreter.emit_display_diagnostic(
            "Deprecated",
            PHP_E_DEPRECATED,
            format!("Implicit conversion from float-string \"{value}\" to int loses precision"),
            span,
        )?;
    }
    Ok(Some(integer))
}

fn php_base_conversion_float_to_i64(value: f64) -> Option<i64> {
    if !value.is_finite() {
        return None;
    }
    let truncated = value.trunc();
    if truncated < i64::MIN as f64 || truncated >= 9_223_372_036_854_775_808.0 {
        return None;
    }
    Some(truncated as i64)
}

fn format_unsigned_radix(mut value: u64, base: u32) -> String {
    debug_assert!((2..=16).contains(&base));
    if value == 0 {
        return "0".to_string();
    }

    let mut digits = Vec::new();
    while value != 0 {
        let digit = (value % u64::from(base)) as u8;
        let ch = match digit {
            0..=9 => b'0' + digit,
            _ => b'a' + (digit - 10),
        };
        digits.push(ch);
        value /= u64::from(base);
    }
    digits.reverse();
    String::from_utf8(digits).expect("radix digits are ASCII")
}

fn format_unsigned_radix_any(mut value: u128, base: u32) -> String {
    debug_assert!((2..=36).contains(&base));
    if value == 0 {
        return "0".to_string();
    }

    let mut digits = Vec::new();
    while value != 0 {
        let digit = (value % u128::from(base)) as u8;
        let ch = match digit {
            0..=9 => b'0' + digit,
            _ => b'a' + (digit - 10),
        };
        digits.push(ch);
        value /= u128::from(base);
    }
    digits.reverse();
    String::from_utf8(digits).expect("radix digits are ASCII")
}

fn parse_php_base_string(input: &str, base: u32) -> (u128, bool) {
    let trimmed = input.trim();
    let body = match base {
        2 => trimmed
            .strip_prefix("0b")
            .or_else(|| trimmed.strip_prefix("0B"))
            .unwrap_or(trimmed),
        8 => trimmed
            .strip_prefix("0o")
            .or_else(|| trimmed.strip_prefix("0O"))
            .unwrap_or(trimmed),
        16 => trimmed
            .strip_prefix("0x")
            .or_else(|| trimmed.strip_prefix("0X"))
            .unwrap_or(trimmed),
        _ => trimmed,
    };

    let mut value = 0_u128;
    let mut ignored_invalid = false;
    for byte in body.bytes() {
        let Some(digit) = base36_digit_value(byte) else {
            ignored_invalid = true;
            continue;
        };
        if digit >= base {
            ignored_invalid = true;
            continue;
        }
        value = value
            .saturating_mul(u128::from(base))
            .saturating_add(u128::from(digit));
    }
    (value, ignored_invalid)
}

fn base36_digit_value(byte: u8) -> Option<u32> {
    match byte {
        b'0'..=b'9' => Some(u32::from(byte - b'0')),
        b'a'..=b'z' => Some(u32::from(byte - b'a' + 10)),
        b'A'..=b'Z' => Some(u32::from(byte - b'A' + 10)),
        _ => None,
    }
}

fn format_php_precision_float(value: f64, precision: usize) -> String {
    let precision = precision.max(1).min(100);
    if value.is_nan() {
        return "NAN".to_string();
    }
    if value.is_infinite() {
        return if value.is_sign_positive() {
            "INF".to_string()
        } else {
            "-INF".to_string()
        };
    }
    if value == 0.0 {
        return "0".to_string();
    }

    let abs = value.abs();
    let exponent = abs.log10().floor() as i32;
    if !(-4..precision as i32).contains(&exponent) {
        let fractional = precision.saturating_sub(1);
        return normalize_php_scientific_float(format!("{value:.fractional$E}"));
    }

    let decimals = (precision as i32 - 1 - exponent).max(0) as usize;
    trim_decimal_suffix(&format!("{value:.decimals$}"))
}

fn format_php_shortest_float(value: f64) -> String {
    if value.is_nan() {
        return "NAN".to_string();
    }
    if value.is_infinite() {
        return if value.is_sign_positive() {
            "INF".to_string()
        } else {
            "-INF".to_string()
        };
    }
    if value == 0.0 {
        return "0".to_string();
    }

    value.to_string()
}

fn format_php_float_to_int_deprecation_value(value: f64) -> String {
    let abs = value.abs();
    if value != 0.0 && !(1e-4..1e14).contains(&abs) {
        normalize_php_scientific_float(format!("{value:.15E}"))
    } else {
        value.to_string()
    }
}

fn normalize_php_scientific_float(mut value: String) -> String {
    let Some(exponent_index) = value.find('E') else {
        return value;
    };

    let mut mantissa = value[..exponent_index].to_string();
    if mantissa.contains('.') {
        while mantissa.ends_with('0') {
            mantissa.pop();
        }
        if mantissa.ends_with('.') {
            mantissa.push('0');
        }
    }

    let exponent = value.split_off(exponent_index + 1);
    let (sign, digits) = if let Some(digits) = exponent.strip_prefix('-') {
        ("-", digits)
    } else {
        ("", &exponent[..])
    };
    let digits = digits.trim_start_matches(|ch| matches!(ch, '+' | '0'));
    let digits = if digits.is_empty() { "0" } else { digits };
    format!("{mantissa}E{sign}{digits}")
}

impl Interpreter {
    fn call_ctype(
        &mut self,
        function: &'static str,
        args: &[Value],
        predicate: fn(u8) -> bool,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function.trim_end_matches("()"), args, 1, span)?;

        let bytes = self.ctype_argument_bytes(function, &args[0], span)?;
        Ok(Value::Bool(
            !bytes.is_empty() && bytes.into_iter().all(predicate),
        ))
    }

    fn ctype_argument_bytes(
        &mut self,
        function: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Vec<u8>> {
        match value {
            Value::String(value) => Ok(value.as_bytes().to_vec()),
            Value::BinaryString(value) => Ok(value.clone()),
            Value::Int(value) => {
                self.emit_ctype_scalar_deprecation(function, "int", span)?;
                if (0..=255).contains(value) {
                    Ok(vec![*value as u8])
                } else {
                    Ok(value.to_string().into_bytes())
                }
            }
            other => {
                self.emit_ctype_scalar_deprecation(
                    function,
                    &ctype_deprecated_type_label(other),
                    span,
                )?;
                Ok(Vec::new())
            }
        }
    }

    fn emit_ctype_scalar_deprecation(
        &mut self,
        function: &'static str,
        type_label: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_diagnostic(
            "Deprecated",
            PHP_E_DEPRECATED,
            format!(
                "{function}: Argument of type {type_label} will be interpreted as string in the future"
            ),
            span,
        )
    }
}

fn ctype_deprecated_type_label(value: &Value) -> String {
    match value {
        Value::Object(object) => object.class_name().to_string(),
        other => other.type_name().to_string(),
    }
}

fn ctype_byte_is_alnum(byte: u8) -> bool {
    byte.is_ascii_alphanumeric()
}

fn ctype_byte_is_alpha(byte: u8) -> bool {
    byte.is_ascii_alphabetic()
}

fn ctype_byte_is_cntrl(byte: u8) -> bool {
    byte <= 0x1f || byte == 0x7f
}

fn ctype_byte_is_digit(byte: u8) -> bool {
    byte.is_ascii_digit()
}

fn ctype_byte_is_graph(byte: u8) -> bool {
    (0x21..=0x7e).contains(&byte)
}

fn ctype_byte_is_lower(byte: u8) -> bool {
    byte.is_ascii_lowercase()
}

fn ctype_byte_is_print(byte: u8) -> bool {
    (0x20..=0x7e).contains(&byte)
}

fn ctype_byte_is_punct(byte: u8) -> bool {
    ctype_byte_is_graph(byte) && !ctype_byte_is_alnum(byte)
}

fn ctype_byte_is_space(byte: u8) -> bool {
    matches!(byte, b'\t' | b'\n' | 0x0b | 0x0c | b'\r' | b' ')
}

fn ctype_byte_is_upper(byte: u8) -> bool {
    byte.is_ascii_uppercase()
}

fn ctype_byte_is_xdigit(byte: u8) -> bool {
    byte.is_ascii_hexdigit()
}

fn call_strrev(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("strrev", args, 1, span)?;

    let mut value = interpreter
        .php_string_argument_bytes_with_magic("strrev()", 1, "string", &args[0], span)?;
    value.reverse();
    Ok(interpreter_value_from_php_string_bytes(value))
}

static STR_SHUFFLE_COUNTER: AtomicU64 = AtomicU64::new(0);

fn call_str_shuffle(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    expect_arity("str_shuffle", args, 1, span)?;

    let value = interpreter.php_string_argument_bytes_with_magic(
        "str_shuffle()",
        1,
        "string",
        &args[0],
        span,
    )?;
    Ok(interpreter_value_from_php_string_bytes(shuffle_bytes(
        value,
    )))
}

fn shuffle_bytes(mut value: Vec<u8>) -> Vec<u8> {
    let len = value.len();
    if len <= 1 {
        return value;
    }

    let counter = STR_SHUFFLE_COUNTER.fetch_add(1, AtomicOrdering::Relaxed);
    if len <= 8 {
        let mut factorial = 1_u64;
        for n in 2..=len as u64 {
            factorial *= n;
        }

        let mut rank = counter % factorial;
        let mut remaining = value;
        let mut output = Vec::with_capacity(len);
        for divisor in (1..=len).rev() {
            let fact = (1..divisor as u64).product::<u64>().max(1);
            let index = (rank / fact) as usize;
            rank %= fact;
            output.push(remaining.remove(index));
        }
        return output;
    }

    let mut state = counter ^ ((len as u64) << 32) ^ 0x9e37_79b9_7f4a_7c15;
    for index in (1..len).rev() {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        let swap_with = (state as usize) % (index + 1);
        value.swap(index, swap_with);
    }
    value
}

fn call_str_rot13(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    expect_arity("str_rot13", args, 1, span)?;

    let mut value = interpreter.php_string_argument_bytes_with_magic(
        "str_rot13()",
        1,
        "string",
        &args[0],
        span,
    )?;
    for byte in &mut value {
        *byte = match *byte {
            b'a'..=b'm' | b'A'..=b'M' => *byte + 13,
            b'n'..=b'z' | b'N'..=b'Z' => *byte - 13,
            _ => *byte,
        };
    }
    Ok(interpreter_value_from_php_string_bytes(value))
}

fn call_escapeshellarg(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("escapeshellarg", args, 1, span)?;

    let value = string_compare_argument_bytes("escapeshellarg()", "arg", &args[0], span)?;
    let mut output = Vec::with_capacity(value.len() + 2);
    output.push(b'\'');
    for byte in value {
        if byte == b'\'' {
            output.extend_from_slice(b"'\\''");
        } else {
            output.push(byte);
        }
    }
    output.push(b'\'');
    Ok(interpreter_value_from_php_string_bytes(output))
}

impl Interpreter {
    fn call_crc32(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("crc32", args, 1, span)?;

        let value =
            self.php_string_argument_bytes_with_magic("crc32()", 1, "string", &args[0], span)?;
        Ok(Value::Int(php_crc32_bytes(&value)))
    }
}

fn call_md5(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "md5()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("md5()", "string", &args[0], span)?;
    let raw_output = digest_binary_argument("md5()", args.get(1), span)?;

    Ok(md5_output_value(&value, raw_output))
}

fn md5_output_value(value: &[u8], raw_output: bool) -> Value {
    let digest = Md5::digest(value);
    if raw_output {
        Value::BinaryString(digest.to_vec())
    } else {
        Value::String(hex_bytes(&digest))
    }
}

fn call_sha1(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "sha1()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("sha1()", "string", &args[0], span)?;
    let raw_output = digest_binary_argument("sha1()", args.get(1), span)?;
    Ok(sha1_output_value(&value, raw_output))
}

fn digest_binary_argument(
    function: &str,
    value: Option<&Value>,
    span: Span,
) -> CompileResult<bool> {
    match value {
        Some(value) => php_internal_bool_argument(function, 2, "binary", value, span),
        None => Ok(false),
    }
}

fn sha1_output_value(value: &[u8], raw_output: bool) -> Value {
    let digest = sha1_digest_bytes(value);
    if raw_output {
        Value::BinaryString(digest.to_vec())
    } else {
        Value::String(hex_bytes(&digest))
    }
}

fn sha1_digest_bytes(value: &[u8]) -> [u8; 20] {
    let bit_len = (value.len() as u64).wrapping_mul(8);
    let mut message = Vec::with_capacity((value.len() + 9).div_ceil(64) * 64);
    message.extend_from_slice(value);
    message.push(0x80);
    while message.len() % 64 != 56 {
        message.push(0);
    }
    message.extend_from_slice(&bit_len.to_be_bytes());

    let mut h0 = 0x6745_2301u32;
    let mut h1 = 0xefcd_ab89u32;
    let mut h2 = 0x98ba_dcfeu32;
    let mut h3 = 0x1032_5476u32;
    let mut h4 = 0xc3d2_e1f0u32;

    for chunk in message.chunks_exact(64) {
        let mut words = [0u32; 80];
        for (index, word) in words.iter_mut().take(16).enumerate() {
            let offset = index * 4;
            *word = u32::from_be_bytes([
                chunk[offset],
                chunk[offset + 1],
                chunk[offset + 2],
                chunk[offset + 3],
            ]);
        }
        for index in 16..80 {
            words[index] =
                (words[index - 3] ^ words[index - 8] ^ words[index - 14] ^ words[index - 16])
                    .rotate_left(1);
        }

        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;

        for (index, word) in words.iter().enumerate() {
            let (f, k) = match index {
                0..=19 => ((b & c) | ((!b) & d), 0x5a82_7999),
                20..=39 => (b ^ c ^ d, 0x6ed9_eba1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8f1b_bcdc),
                _ => (b ^ c ^ d, 0xca62_c1d6),
            };
            let temp = a
                .rotate_left(5)
                .wrapping_add(f)
                .wrapping_add(e)
                .wrapping_add(k)
                .wrapping_add(*word);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }

        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }

    let mut digest = [0u8; 20];
    digest[0..4].copy_from_slice(&h0.to_be_bytes());
    digest[4..8].copy_from_slice(&h1.to_be_bytes());
    digest[8..12].copy_from_slice(&h2.to_be_bytes());
    digest[12..16].copy_from_slice(&h3.to_be_bytes());
    digest[16..20].copy_from_slice(&h4.to_be_bytes());
    digest
}

fn php_crc32_bytes(bytes: &[u8]) -> i64 {
    let mut crc = 0xffff_ffffu32;
    for byte in bytes {
        crc ^= u32::from(*byte);
        for _ in 0..8 {
            crc = if crc & 1 == 0 {
                crc >> 1
            } else {
                (crc >> 1) ^ 0xedb8_8320
            };
        }
    }
    i64::from(!crc)
}

fn php_hash_adler32_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    const MOD_ADLER: u32 = 65_521;

    let mut low = 1u32;
    let mut high = 0u32;
    for byte in bytes {
        low = (low + u32::from(*byte)) % MOD_ADLER;
        high = (high + low) % MOD_ADLER;
    }
    ((high << 16) | low).to_be_bytes()
}

fn php_hash_crc32_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut crc = 0xffff_ffffu32;
    for byte in bytes {
        crc ^= u32::from(*byte) << 24;
        for _ in 0..8 {
            crc = if crc & 0x8000_0000 == 0 {
                crc << 1
            } else {
                (crc << 1) ^ 0x04c1_1db7
            };
        }
    }
    (!crc).to_le_bytes()
}

fn php_hash_crc32b_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut crc = 0xffff_ffffu32;
    for byte in bytes {
        crc ^= u32::from(*byte);
        for _ in 0..8 {
            crc = if crc & 1 == 0 {
                crc >> 1
            } else {
                (crc >> 1) ^ 0xedb8_8320
            };
        }
    }
    (!crc).to_be_bytes()
}

fn php_hash_crc32c_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut crc = 0xffff_ffffu32;
    for byte in bytes {
        crc ^= u32::from(*byte);
        for _ in 0..8 {
            crc = if crc & 1 == 0 {
                crc >> 1
            } else {
                (crc >> 1) ^ 0x82f6_3b78
            };
        }
    }
    (!crc).to_be_bytes()
}

fn php_hash_fnv132_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut hash = 0x811c_9dc5u32;
    for byte in bytes {
        hash = hash.wrapping_mul(0x0100_0193);
        hash ^= u32::from(*byte);
    }
    hash.to_be_bytes()
}

fn php_hash_fnv1a32_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut hash = 0x811c_9dc5u32;
    for byte in bytes {
        hash ^= u32::from(*byte);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    hash.to_be_bytes()
}

fn php_hash_fnv164_digest_bytes(bytes: &[u8]) -> [u8; 8] {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in bytes {
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        hash ^= u64::from(*byte);
    }
    hash.to_be_bytes()
}

fn php_hash_fnv1a64_digest_bytes(bytes: &[u8]) -> [u8; 8] {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash.to_be_bytes()
}

fn php_hash_joaat_digest_bytes(bytes: &[u8]) -> [u8; 4] {
    let mut hash = 0u32;
    for byte in bytes {
        hash = hash.wrapping_add(u32::from(*byte));
        hash = hash.wrapping_add(hash << 10);
        hash ^= hash >> 6;
    }
    hash = hash.wrapping_add(hash << 3);
    hash ^= hash >> 11;
    hash = hash.wrapping_add(hash << 15);
    hash.to_be_bytes()
}

impl Interpreter {
    fn call_levenshtein(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=5).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "levenshtein()",
                    ArityExpectation::Between { min: 2, max: 5 },
                    args.len(),
                ),
            ));
        }

        let left = self.php_string_argument_bytes_with_magic(
            "levenshtein()",
            1,
            "string1",
            &args[0],
            span,
        )?;
        let right = self.php_string_argument_bytes_with_magic(
            "levenshtein()",
            2,
            "string2",
            &args[1],
            span,
        )?;
        let insertion_cost = match args.get(2) {
            Some(value) => {
                php_internal_int_argument("levenshtein()", 3, "insertion_cost", value, span)?
            }
            None => 1,
        };
        let replacement_cost = match args.get(3) {
            Some(value) => {
                php_internal_int_argument("levenshtein()", 4, "replacement_cost", value, span)?
            }
            None => 1,
        };
        let deletion_cost = match args.get(4) {
            Some(value) => {
                php_internal_int_argument("levenshtein()", 5, "deletion_cost", value, span)?
            }
            None => 1,
        };

        let distance = php_levenshtein_bytes(
            &left,
            &right,
            insertion_cost,
            replacement_cost,
            deletion_cost,
            span,
        )?;
        Ok(Value::Int(distance))
    }
}

fn php_levenshtein_bytes(
    left: &[u8],
    right: &[u8],
    insertion_cost: i64,
    replacement_cost: i64,
    deletion_cost: i64,
    span: Span,
) -> CompileResult<i64> {
    let insertion_cost = i128::from(insertion_cost);
    let replacement_cost = i128::from(replacement_cost);
    let deletion_cost = i128::from(deletion_cost);

    let mut previous = Vec::with_capacity(right.len() + 1);
    let mut current = Vec::with_capacity(right.len() + 1);
    previous.push(0_i128);
    for index in 1..=right.len() {
        previous.push(checked_levenshtein_add(
            previous[index - 1],
            insertion_cost,
            span,
        )?);
    }

    for (left_index, left_byte) in left.iter().enumerate() {
        current.clear();
        current.push(checked_levenshtein_mul(
            i128::try_from(left_index + 1).unwrap_or(i128::MAX),
            deletion_cost,
            span,
        )?);

        for (right_index, right_byte) in right.iter().enumerate() {
            let insert = checked_levenshtein_add(current[right_index], insertion_cost, span)?;
            let delete = checked_levenshtein_add(previous[right_index + 1], deletion_cost, span)?;
            let replace = checked_levenshtein_add(
                previous[right_index],
                if left_byte == right_byte {
                    0
                } else {
                    replacement_cost
                },
                span,
            )?;
            current.push(insert.min(delete).min(replace));
        }

        std::mem::swap(&mut previous, &mut current);
    }

    i64::try_from(previous[right.len()]).map_err(|_| levenshtein_overflow(span))
}

fn checked_levenshtein_add(left: i128, right: i128, span: Span) -> CompileResult<i128> {
    left.checked_add(right)
        .ok_or_else(|| levenshtein_overflow(span))
}

fn checked_levenshtein_mul(left: i128, right: i128, span: Span) -> CompileResult<i128> {
    left.checked_mul(right)
        .ok_or_else(|| levenshtein_overflow(span))
}

fn levenshtein_overflow(span: Span) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(
            "levenshtein()",
            "distance overflowed the current integer subset",
        ),
    )
}

impl Interpreter {
    fn call_similar_text(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "similar_text()",
                    ArityExpectation::Between { min: 2, max: 3 },
                    args.len(),
                ),
            ));
        }

        if args.len() == 3 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "similar_text()",
                    "percent output requires a direct similar_text() call with a direct variable in the current subset",
                ),
            ));
        }

        let (similarity, _) = self.similar_text_result(&args[0], &args[1], span)?;
        Ok(Value::Int(similarity as i64))
    }

    fn similar_text_result(
        &mut self,
        first: &Value,
        second: &Value,
        span: Span,
    ) -> CompileResult<(usize, f64)> {
        let first =
            self.php_string_argument_bytes_with_magic("similar_text()", 1, "string1", first, span)?;
        let second = self.php_string_argument_bytes_with_magic(
            "similar_text()",
            2,
            "string2",
            second,
            span,
        )?;
        let similarity = php_similar_text_bytes(&first, &second);
        let combined_len = first.len() + second.len();
        let percent = if combined_len == 0 {
            0.0
        } else {
            (similarity as f64) * 200.0 / (combined_len as f64)
        };
        Ok((similarity, percent))
    }
}

fn php_similar_text_bytes(first: &[u8], second: &[u8]) -> usize {
    let mut best_len = 0_usize;
    let mut best_first = 0_usize;
    let mut best_second = 0_usize;

    for first_index in 0..first.len() {
        for second_index in 0..second.len() {
            let mut len = 0_usize;
            while first_index + len < first.len()
                && second_index + len < second.len()
                && first[first_index + len] == second[second_index + len]
            {
                len += 1;
            }

            if len > best_len {
                best_len = len;
                best_first = first_index;
                best_second = second_index;
            }
        }
    }

    if best_len == 0 {
        return 0;
    }

    let mut similarity = best_len;
    if best_first > 0 && best_second > 0 {
        similarity += php_similar_text_bytes(&first[..best_first], &second[..best_second]);
    }

    let first_tail = best_first + best_len;
    let second_tail = best_second + best_len;
    if first_tail < first.len() && second_tail < second.len() {
        similarity += php_similar_text_bytes(&first[first_tail..], &second[second_tail..]);
    }

    similarity
}

impl Interpreter {
    fn call_soundex(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("soundex", args, 1, span)?;

        let value =
            self.php_string_argument_bytes_with_magic("soundex()", 1, "string", &args[0], span)?;
        Ok(Value::String(php_soundex_bytes(&value)))
    }
}

fn php_soundex_bytes(bytes: &[u8]) -> String {
    let mut letters = bytes.iter().copied().filter(u8::is_ascii_alphabetic);
    let Some(first) = letters.next() else {
        return "0000".to_string();
    };

    let first = first.to_ascii_uppercase();
    let mut output = String::with_capacity(4);
    output.push(first as char);
    let mut previous = php_soundex_code(first);

    for byte in letters {
        let code = php_soundex_code(byte.to_ascii_uppercase());
        match code {
            0 => previous = 0,
            7 => {}
            value if value != previous => {
                output.push((b'0' + value) as char);
                previous = value;
                if output.len() == 4 {
                    return output;
                }
            }
            value => previous = value,
        }
    }

    while output.len() < 4 {
        output.push('0');
    }
    output
}

fn php_soundex_code(byte: u8) -> u8 {
    match byte {
        b'B' | b'F' | b'P' | b'V' => 1,
        b'C' | b'G' | b'J' | b'K' | b'Q' | b'S' | b'X' | b'Z' => 2,
        b'D' | b'T' => 3,
        b'L' => 4,
        b'M' | b'N' => 5,
        b'R' => 6,
        b'H' | b'W' => 7,
        _ => 0,
    }
}

impl Interpreter {
    fn call_metaphone(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "metaphone()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let value =
            self.php_string_argument_bytes_with_magic("metaphone()", 1, "string", &args[0], span)?;
        let max_phonemes = match args.get(1) {
            Some(value) => {
                php_internal_int_argument("metaphone()", 2, "max_phonemes", value, span)?
            }
            None => 0,
        };
        if max_phonemes < 0 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "metaphone()",
                    "Argument #2 ($max_phonemes) must be greater than or equal to 0",
                ),
            ));
        }

        Ok(Value::String(php_metaphone_bytes(
            &value,
            usize::try_from(max_phonemes).unwrap_or(usize::MAX),
        )))
    }
}

fn php_metaphone_bytes(bytes: &[u8], max_phonemes: usize) -> String {
    let mut word_index = 0_usize;
    let mut output = String::new();

    while !metaphone_is_alpha(metaphone_raw_at(bytes, word_index)) {
        if metaphone_raw_at(bytes, word_index) == 0 {
            return output;
        }
        word_index += 1;
    }

    let first = metaphone_upper_at(bytes, word_index);
    match first {
        b'A' => {
            if metaphone_next(bytes, word_index) == b'E' {
                output.push('E');
                word_index += 2;
            } else {
                output.push('A');
                word_index += 1;
            }
        }
        b'G' | b'K' | b'P' => {
            if metaphone_next(bytes, word_index) == b'N' {
                output.push('N');
                word_index += 2;
            }
        }
        b'W' => {
            let next = metaphone_next(bytes, word_index);
            if next == b'R' {
                output.push('R');
                word_index += 2;
            } else if next == b'H' || metaphone_is_vowel(next) {
                output.push('W');
                word_index += 2;
            }
        }
        b'X' => {
            output.push('S');
            word_index += 1;
        }
        b'E' | b'I' | b'O' | b'U' => {
            output.push(first as char);
            word_index += 1;
        }
        _ => {}
    }

    while metaphone_raw_at(bytes, word_index) != 0
        && (max_phonemes == 0 || output.len() < max_phonemes)
    {
        let raw = metaphone_raw_at(bytes, word_index);
        if !metaphone_is_alpha(raw) {
            word_index += 1;
            continue;
        }

        let current = raw.to_ascii_uppercase();
        let previous = metaphone_look_back(bytes, word_index, 1);
        if current == previous && current != b'C' {
            word_index += 1;
            continue;
        }

        let mut skip = 0_usize;
        match current {
            b'B' => {
                if previous != b'M' {
                    output.push('B');
                }
            }
            b'C' => {
                let next = metaphone_next(bytes, word_index);
                if metaphone_makes_soft(next) {
                    if next == b'I' && metaphone_after_next(bytes, word_index) == b'A' {
                        output.push('X');
                    } else if previous == b'S' {
                        // SC[IEY] is handled by S.
                    } else {
                        output.push('S');
                    }
                } else if next == b'H' {
                    output.push('X');
                    skip += 1;
                } else {
                    output.push('K');
                }
            }
            b'D' => {
                if metaphone_next(bytes, word_index) == b'G'
                    && metaphone_makes_soft(metaphone_after_next(bytes, word_index))
                {
                    output.push('J');
                    skip += 1;
                } else {
                    output.push('T');
                }
            }
            b'G' => {
                let next = metaphone_next(bytes, word_index);
                if next == b'H' {
                    if !(metaphone_no_gh_to_f(metaphone_look_back(bytes, word_index, 3))
                        || metaphone_look_back(bytes, word_index, 4) == b'H')
                    {
                        output.push('F');
                        skip += 1;
                    }
                } else if next == b'N' {
                    let after_next = metaphone_after_next(bytes, word_index);
                    if metaphone_is_break(after_next)
                        || (after_next == b'E'
                            && metaphone_look_ahead(bytes, word_index, 3) == b'D')
                    {
                        // Silent GN/GNED.
                    } else {
                        output.push('K');
                    }
                } else if metaphone_makes_soft(next) && previous != b'G' {
                    output.push('J');
                } else {
                    output.push('K');
                }
            }
            b'H' => {
                if metaphone_is_vowel(metaphone_next(bytes, word_index))
                    && !metaphone_affects_h(previous)
                {
                    output.push('H');
                }
            }
            b'K' => {
                if previous != b'C' {
                    output.push('K');
                }
            }
            b'P' => {
                if metaphone_next(bytes, word_index) == b'H' {
                    output.push('F');
                } else {
                    output.push('P');
                }
            }
            b'Q' => output.push('K'),
            b'S' => {
                let next = metaphone_next(bytes, word_index);
                let after_next = metaphone_after_next(bytes, word_index);
                if next == b'I' && (after_next == b'O' || after_next == b'A') {
                    output.push('X');
                } else if next == b'H' {
                    output.push('X');
                    skip += 1;
                } else {
                    output.push('S');
                }
            }
            b'T' => {
                let next = metaphone_next(bytes, word_index);
                let after_next = metaphone_after_next(bytes, word_index);
                if next == b'I' && (after_next == b'O' || after_next == b'A') {
                    output.push('X');
                } else if next == b'H' {
                    output.push('0');
                    skip += 1;
                } else if !(next == b'C' && after_next == b'H') {
                    output.push('T');
                }
            }
            b'V' => output.push('F'),
            b'W' => {
                if metaphone_is_vowel(metaphone_next(bytes, word_index)) {
                    output.push('W');
                }
            }
            b'X' => {
                output.push('K');
                output.push('S');
            }
            b'Y' => {
                if metaphone_is_vowel(metaphone_next(bytes, word_index)) {
                    output.push('Y');
                }
            }
            b'Z' => output.push('S'),
            b'F' | b'J' | b'L' | b'M' | b'N' | b'R' => output.push(current as char),
            _ => {}
        }

        word_index += skip + 1;
    }

    output
}

fn metaphone_raw_at(bytes: &[u8], index: usize) -> u8 {
    bytes.get(index).copied().unwrap_or(0)
}

fn metaphone_upper_at(bytes: &[u8], index: usize) -> u8 {
    metaphone_raw_at(bytes, index).to_ascii_uppercase()
}

fn metaphone_next(bytes: &[u8], index: usize) -> u8 {
    metaphone_upper_at(bytes, index + 1)
}

fn metaphone_after_next(bytes: &[u8], index: usize) -> u8 {
    if metaphone_raw_at(bytes, index + 1) == 0 {
        0
    } else {
        metaphone_upper_at(bytes, index + 2)
    }
}

fn metaphone_look_back(bytes: &[u8], index: usize, count: usize) -> u8 {
    if index >= count {
        metaphone_upper_at(bytes, index - count)
    } else {
        0
    }
}

fn metaphone_look_ahead(bytes: &[u8], index: usize, count: usize) -> u8 {
    let mut offset = 0_usize;
    while metaphone_raw_at(bytes, index + offset) != 0 && offset < count {
        offset += 1;
    }
    metaphone_upper_at(bytes, index + offset)
}

fn metaphone_code(byte: u8) -> u8 {
    match byte {
        b'A' | b'O' | b'U' => 1,
        b'E' | b'I' => 9,
        b'F' | b'J' | b'L' | b'M' | b'N' | b'R' => 2,
        b'C' | b'G' | b'P' | b'S' | b'T' => 4,
        b'Y' => 8,
        b'B' | b'D' | b'H' => 16,
        _ => 0,
    }
}

fn metaphone_is_alpha(byte: u8) -> bool {
    byte.is_ascii_alphabetic()
}

fn metaphone_is_vowel(byte: u8) -> bool {
    metaphone_code(byte) & 1 != 0
}

fn metaphone_affects_h(byte: u8) -> bool {
    metaphone_code(byte) & 4 != 0
}

fn metaphone_makes_soft(byte: u8) -> bool {
    metaphone_code(byte) & 8 != 0
}

fn metaphone_no_gh_to_f(byte: u8) -> bool {
    metaphone_code(byte) & 16 != 0
}

fn metaphone_is_break(byte: u8) -> bool {
    !metaphone_is_alpha(byte)
}

impl Interpreter {
    fn call_count_chars(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "count_chars()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let value = self.php_string_argument_bytes_with_magic(
            "count_chars()",
            1,
            "string",
            &args[0],
            span,
        )?;
        let mode = match args.get(1) {
            Some(value) => php_internal_int_argument("count_chars()", 2, "mode", value, span)?,
            None => 0,
        };
        if !(0..=4).contains(&mode) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "count_chars()",
                    "Argument #2 ($mode) must be between 0 and 4 (inclusive)",
                ),
            ));
        }

        let mut counts = [0_i64; 256];
        for byte in value {
            counts[byte as usize] += 1;
        }

        match mode {
            0 | 1 | 2 => {
                let mut array = PhpArray::new();
                for (index, count) in counts.iter().copied().enumerate() {
                    if mode == 1 && count == 0 {
                        continue;
                    }
                    if mode == 2 && count != 0 {
                        continue;
                    }
                    array.insert(ArrayKey::Int(index as i64), Value::Int(count));
                }
                Ok(Value::Array(array))
            }
            3 | 4 => {
                let mut output = Vec::new();
                for (index, count) in counts.iter().copied().enumerate() {
                    if (mode == 3 && count != 0) || (mode == 4 && count == 0) {
                        output.push(index as u8);
                    }
                }
                Ok(interpreter_value_from_php_string_bytes(output))
            }
            _ => unreachable!("count_chars mode already validated"),
        }
    }
}

fn call_ucfirst(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("ucfirst", args, 1, span)?;

    let mut value = interpreter.php_string_argument_bytes_with_magic(
        "ucfirst()",
        1,
        "string",
        &args[0],
        span,
    )?;
    if let Some(first) = value.first_mut() {
        *first = (*first).to_ascii_uppercase();
    }
    Ok(interpreter_value_from_php_string_bytes(value))
}

fn call_lcfirst(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("lcfirst", args, 1, span)?;

    let mut value = interpreter.php_string_argument_bytes_with_magic(
        "lcfirst()",
        1,
        "string",
        &args[0],
        span,
    )?;
    if let Some(first) = value.first_mut() {
        *first = (*first).to_ascii_lowercase();
    }
    Ok(interpreter_value_from_php_string_bytes(value))
}

const PHP_UCWORDS_DEFAULT_DELIMITERS: &[u8] = b" \t\r\n\x0b\x0c";

const PHP_HTML_SPECIALCHARS: i64 = 0;
const PHP_HTML_ENTITIES: i64 = 1;
const PHP_ENT_NOQUOTES: i64 = 0;
const PHP_ENT_COMPAT: i64 = 2;
const PHP_ENT_QUOTES: i64 = 3;
const PHP_ENT_IGNORE: i64 = 4;
const PHP_ENT_SUBSTITUTE: i64 = 8;
const PHP_ENT_HTML401: i64 = 0;
const PHP_ENT_XML1: i64 = 16;
const PHP_ENT_XHTML: i64 = 32;
const PHP_ENT_HTML5: i64 = 48;
const PHP_ENT_DISALLOWED: i64 = 128;
const PHP_ENT_DEFAULT: i64 = PHP_ENT_QUOTES | PHP_ENT_SUBSTITUTE | PHP_ENT_HTML401;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HtmlQuoteMode {
    None,
    Double,
    Both,
}

fn html_quote_mode(flags: i64) -> HtmlQuoteMode {
    if flags & PHP_ENT_QUOTES == PHP_ENT_QUOTES {
        HtmlQuoteMode::Both
    } else if flags & PHP_ENT_COMPAT == PHP_ENT_COMPAT {
        HtmlQuoteMode::Double
    } else {
        HtmlQuoteMode::None
    }
}

fn html_document_type(flags: i64) -> i64 {
    flags & PHP_ENT_HTML5
}

fn html_single_quote_entity(flags: i64) -> &'static [u8] {
    match html_document_type(flags) {
        PHP_ENT_XML1 | PHP_ENT_XHTML | PHP_ENT_HTML5 => b"&apos;",
        _ => b"&#039;",
    }
}

fn html_decode_apostrophe_entity(flags: i64) -> bool {
    matches!(
        html_document_type(flags),
        PHP_ENT_XML1 | PHP_ENT_XHTML | PHP_ENT_HTML5
    )
}

fn html_default_flags(
    args: &[Value],
    index: usize,
    function: &str,
    span: Span,
) -> CompileResult<i64> {
    match args.get(index) {
        Some(value) => php_internal_int_argument(function, index + 1, "flags", value, span),
        None => Ok(PHP_ENT_DEFAULT),
    }
}

fn html_validate_encoding_arg(
    interpreter: &mut Interpreter,
    args: &[Value],
    index: usize,
    function: &str,
    span: Span,
) -> CompileResult<()> {
    if let Some(value) = args.get(index) {
        if !matches!(value, Value::Null) {
            let bytes = string_compare_argument_bytes(function, "encoding", value, span)?;
            if !html_charset_is_supported(&bytes) {
                interpreter.emit_display_warning(
                    format!(
                        "{function}: Charset \"{}\" is not supported, assuming UTF-8",
                        String::from_utf8_lossy(&bytes)
                    ),
                    span,
                )?;
            }
        }
    }
    Ok(())
}

fn html_charset_is_supported(bytes: &[u8]) -> bool {
    let normalized: String = bytes
        .iter()
        .filter_map(|byte| match *byte {
            b'-' | b'_' | b' ' => None,
            byte => Some(byte.to_ascii_uppercase() as char),
        })
        .collect();

    matches!(
        normalized.as_str(),
        "" | "UTF8"
            | "ISO88591"
            | "ISO885915"
            | "SJIS"
            | "SHIFTJIS"
            | "KOI8R"
            | "EUCJP"
            | "1251"
            | "CP1251"
            | "WINDOWS1251"
            | "1252"
            | "CP1252"
            | "WINDOWS1252"
            | "866"
            | "CP866"
            | "IBM866"
    )
}

fn call_htmlspecialchars(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    if !(1..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "htmlspecialchars()",
                ArityExpectation::Between { min: 1, max: 4 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("htmlspecialchars()", "string", &args[0], span)?;
    let flags = html_default_flags(args, 1, "htmlspecialchars()", span)?;
    html_validate_encoding_arg(interpreter, args, 2, "htmlspecialchars()", span)?;
    let double_encode = args.get(3).map(Value::is_truthy).unwrap_or(true);
    Ok(interpreter_value_from_php_string_bytes(
        htmlspecialchars_encode_bytes(&value, flags, double_encode),
    ))
}

