fn call_htmlspecialchars_decode(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "htmlspecialchars_decode()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value =
        string_compare_argument_bytes("htmlspecialchars_decode()", "string", &args[0], span)?;
    let flags = html_default_flags(args, 1, "htmlspecialchars_decode()", span)?;
    Ok(interpreter_value_from_php_string_bytes(html_decode_bytes(
        &value, flags, false,
    )))
}

fn call_html_entity_decode(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    if !(1..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "html_entity_decode()",
                ArityExpectation::Between { min: 1, max: 3 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("html_entity_decode()", "string", &args[0], span)?;
    let flags = html_default_flags(args, 1, "html_entity_decode()", span)?;
    html_validate_encoding_arg(interpreter, args, 2, "html_entity_decode()", span)?;
    Ok(interpreter_value_from_php_string_bytes(html_decode_bytes(
        &value, flags, true,
    )))
}

fn call_get_html_translation_table(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    if args.len() > 3 {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "get_html_translation_table()",
                ArityExpectation::Between { min: 0, max: 3 },
                args.len(),
            ),
        ));
    }

    let table = match args.get(0) {
        Some(value) => {
            php_internal_int_argument("get_html_translation_table()", 1, "table", value, span)?
        }
        None => PHP_HTML_SPECIALCHARS,
    };
    let flags = html_default_flags(args, 1, "get_html_translation_table()", span)?;
    html_validate_encoding_arg(interpreter, args, 2, "get_html_translation_table()", span)?;
    if table != PHP_HTML_SPECIALCHARS && table != PHP_HTML_ENTITIES {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "get_html_translation_table()",
                "Argument #1 ($table) must be HTML_SPECIALCHARS or HTML_ENTITIES",
            ),
        ));
    }

    let mut array = PhpArray::new();
    html_insert_translation(&mut array, b"&", b"&amp;");
    html_insert_translation(&mut array, b">", b"&gt;");
    html_insert_translation(&mut array, b"<", b"&lt;");
    match html_quote_mode(flags) {
        HtmlQuoteMode::Both => {
            html_insert_translation(&mut array, b"\"", b"&quot;");
            html_insert_translation(&mut array, b"'", html_single_quote_entity(flags));
        }
        HtmlQuoteMode::Double => html_insert_translation(&mut array, b"\"", b"&quot;"),
        HtmlQuoteMode::None => {}
    }
    if table == PHP_HTML_ENTITIES {
        for (bytes, entity) in HTML_ENTITY_EXTRA_TRANSLATIONS {
            html_insert_translation(&mut array, bytes, entity.as_bytes());
        }
    }
    Ok(Value::Array(array))
}

fn html_insert_translation(array: &mut PhpArray, bytes: &[u8], entity: &[u8]) {
    let key = String::from_utf8_lossy(bytes).into_owned();
    let value = interpreter_value_from_php_string_bytes(entity.to_vec());
    array.insert(ArrayKey::String(key), value);
}

fn call_strip_tags(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "strip_tags()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("strip_tags()", "string", &args[0], span)?;
    let allowed = match args.get(1) {
        None | Some(Value::Null) => HashSet::new(),
        Some(Value::Array(array)) => strip_tags_allowed_tags_from_array(array, span)?,
        Some(Value::Resource(_)) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "strip_tags()",
                    "Argument #2 ($allowed_tags) must be of type array|string|null, resource given",
                ),
            ));
        }
        Some(Value::Object(_)) | Some(Value::Closure(_)) => HashSet::new(),
        Some(value) => {
            let bytes = value
                .try_echo_bytes()
                .map_err(|error| runtime_error(span, error))?;
            strip_tags_allowed_tags_from_string_bytes(&bytes)
        }
    };

    Ok(interpreter_value_from_php_string_bytes(strip_tags_bytes(
        &value, &allowed,
    )))
}

fn strip_tags_allowed_tags_from_array(
    array: &PhpArray,
    span: Span,
) -> CompileResult<HashSet<String>> {
    let mut allowed = HashSet::new();
    for entry in array.entries() {
        match entry.value() {
            Value::Resource(_) => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "strip_tags()",
                        "Argument #2 ($allowed_tags) must be of type array|string|null, resource given",
                    ),
                ));
            }
            Value::Array(_) | Value::Object(_) | Value::Closure(_) => {}
            value => {
                let bytes = value
                    .try_echo_bytes()
                    .map_err(|error| runtime_error(span, error))?;
                if let Some(name) = strip_tags_plain_allowed_tag_name(&bytes) {
                    allowed.insert(name);
                } else {
                    allowed.extend(strip_tags_allowed_tags_from_string_bytes(&bytes));
                }
            }
        }
    }
    Ok(allowed)
}

fn strip_tags_plain_allowed_tag_name(bytes: &[u8]) -> Option<String> {
    if bytes.is_empty() || !bytes.iter().all(|byte| byte.is_ascii_alphanumeric()) {
        return None;
    }
    bytes
        .first()
        .filter(|byte| byte.is_ascii_alphabetic())
        .map(|_| {
            bytes
                .iter()
                .map(|byte| byte.to_ascii_lowercase() as char)
                .collect()
        })
}

fn strip_tags_allowed_tags_from_string_bytes(bytes: &[u8]) -> HashSet<String> {
    let mut allowed = HashSet::new();
    for index in 0..bytes.len() {
        if bytes[index] != b'<' {
            continue;
        }
        if let Some((name, _, _)) = strip_tags_html_tag_name(bytes, index + 1) {
            allowed.insert(name);
        }
    }
    allowed
}

struct StripTagSpan {
    end: usize,
    keep: bool,
}

fn strip_tags_bytes(value: &[u8], allowed: &HashSet<String>) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        if value[index] == b'\0' {
            index += 1;
            continue;
        }

        if value[index] != b'<' {
            output.push(value[index]);
            index += 1;
            continue;
        }

        if value.get(index + 1) == Some(&b'<') {
            if let Some(span) = strip_tags_span(value, index + 1, allowed) {
                if span.keep {
                    output.extend_from_slice(&value[index + 1..span.end]);
                }
                index = span.end;
                if value.get(index) == Some(&b'>') {
                    index += 1;
                }
                continue;
            }
        }

        let Some(span) = strip_tags_span(value, index, allowed) else {
            output.push(value[index]);
            index += 1;
            continue;
        };

        if span.keep {
            output.extend_from_slice(&value[index..span.end]);
        }
        index = span.end;
    }

    output
}

fn strip_tags_span(value: &[u8], start: usize, allowed: &HashSet<String>) -> Option<StripTagSpan> {
    let next = *value.get(start + 1)?;
    if next == b'?' {
        let end = if strip_tags_is_xml_processing_instruction(value, start) {
            strip_tags_find_xml_processing_instruction_end(value, start + 2)
                .or_else(|| strip_tags_find_tag_end(value, start + 1, false))
                .unwrap_or(value.len())
        } else {
            strip_tags_find_terminator(value, start + 2, b'?', b'>').unwrap_or(value.len())
        };
        return Some(StripTagSpan { end, keep: false });
    }
    if next == b'%' {
        return Some(StripTagSpan {
            end: strip_tags_find_terminator(value, start + 2, b'%', b'>').unwrap_or(value.len()),
            keep: false,
        });
    }
    if value.get(start + 1..start + 4) == Some(b"!--") {
        return Some(StripTagSpan {
            end: strip_tags_find_comment_end(value, start + 4).unwrap_or(value.len()),
            keep: false,
        });
    }

    let tag_like = next == b'!' || next == b'/' || next.is_ascii_alphabetic();
    if !tag_like {
        return None;
    }

    let count_nested_lt = next == b'/' || next.is_ascii_alphabetic();
    let end = strip_tags_find_tag_end(value, start + 1, count_nested_lt)?;
    let keep = strip_tags_html_tag_name(value, start + 1).is_some_and(
        |(name, name_end, boundary_valid)| {
            boundary_valid && name_end < end && allowed.contains(&name)
        },
    );
    Some(StripTagSpan { end, keep })
}

fn strip_tags_is_xml_processing_instruction(value: &[u8], start: usize) -> bool {
    value
        .get(start + 2..start + 5)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case(b"xml"))
}

fn strip_tags_find_xml_processing_instruction_end(value: &[u8], mut index: usize) -> Option<usize> {
    while index + 1 < value.len() {
        if (value[index] == b'?' || value[index] == b'/') && value[index + 1] == b'>' {
            return Some(index + 2);
        }
        index += 1;
    }
    None
}

fn strip_tags_find_terminator(
    value: &[u8],
    mut index: usize,
    first: u8,
    second: u8,
) -> Option<usize> {
    while index + 1 < value.len() {
        if value[index] == first && value[index + 1] == second {
            return Some(index + 2);
        }
        index += 1;
    }
    None
}

fn strip_tags_find_comment_end(value: &[u8], mut index: usize) -> Option<usize> {
    while index + 2 < value.len() {
        if &value[index..index + 3] == b"-->" {
            return Some(index + 3);
        }
        index += 1;
    }
    None
}

fn strip_tags_find_tag_end(value: &[u8], mut index: usize, count_nested_lt: bool) -> Option<usize> {
    let mut quote = None;
    let mut depth = 0usize;
    while index < value.len() {
        let byte = value[index];
        if let Some(current_quote) = quote {
            if byte == current_quote {
                quote = None;
            }
        } else if byte == b'\'' || byte == b'"' {
            quote = Some(byte);
        } else if count_nested_lt
            && byte == b'<'
            && !matches!(value.get(index + 1), Some(next) if next.is_ascii_whitespace())
        {
            depth += 1;
        } else if byte == b'>' {
            if depth > 0 {
                depth -= 1;
                index += 1;
                continue;
            }
            return Some(index + 1);
        }
        index += 1;
    }
    None
}

fn strip_tags_html_tag_name(value: &[u8], mut index: usize) -> Option<(String, usize, bool)> {
    if value.get(index) == Some(&b'/') {
        index += 1;
    }
    let start = index;
    while value
        .get(index)
        .is_some_and(|byte| byte.is_ascii_alphanumeric())
    {
        index += 1;
    }
    if start == index || !value[start].is_ascii_alphabetic() {
        return None;
    }
    let boundary_valid = value
        .get(index)
        .is_some_and(|byte| byte.is_ascii_whitespace() || matches!(*byte, b'/' | b'>'));
    let name = value[start..index]
        .iter()
        .map(|byte| byte.to_ascii_lowercase() as char)
        .collect();
    Some((name, index, boundary_valid))
}

fn htmlspecialchars_encode_bytes(value: &[u8], flags: i64, double_encode: bool) -> Vec<u8> {
    html_encode_bytes(value, flags, double_encode, false)
}

fn htmlentities_encode_bytes(value: &[u8], flags: i64, double_encode: bool) -> Vec<u8> {
    html_encode_bytes(value, flags, double_encode, true)
}

fn html_encode_bytes(value: &[u8], flags: i64, double_encode: bool, all_entities: bool) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    let quote_mode = html_quote_mode(flags);
    let mut index = 0;
    while index < value.len() {
        let byte = value[index];
        match byte {
            b'&' if !double_encode && html_entity_like_end(value, index).is_some() => {
                output.push(byte);
                index += 1;
            }
            b'&' => {
                output.extend_from_slice(b"&amp;");
                index += 1;
            }
            b'<' => {
                output.extend_from_slice(b"&lt;");
                index += 1;
            }
            b'>' => {
                output.extend_from_slice(b"&gt;");
                index += 1;
            }
            b'\"' if matches!(quote_mode, HtmlQuoteMode::Double | HtmlQuoteMode::Both) => {
                output.extend_from_slice(b"&quot;");
                index += 1;
            }
            b'\'' if matches!(quote_mode, HtmlQuoteMode::Both) => {
                output.extend_from_slice(html_single_quote_entity(flags));
                index += 1;
            }
            _ if all_entities => {
                if let Some((consumed, entity)) = html_extra_entity_at(value, index) {
                    output.extend_from_slice(entity.as_bytes());
                    index += consumed;
                } else {
                    output.push(byte);
                    index += 1;
                }
            }
            _ => {
                output.push(byte);
                index += 1;
            }
        }
    }
    output
}

fn html_entity_like_end(value: &[u8], amp_index: usize) -> Option<usize> {
    let mut index = amp_index + 1;
    if value.get(index) == Some(&b'#') {
        index += 1;
        if matches!(value.get(index).copied(), Some(b'x' | b'X')) {
            index += 1;
            let start = index;
            while matches!(value.get(index), Some(byte) if byte.is_ascii_hexdigit()) {
                index += 1;
            }
            return (index > start && value.get(index) == Some(&b';')).then_some(index);
        }
        let start = index;
        while matches!(value.get(index), Some(byte) if byte.is_ascii_digit()) {
            index += 1;
        }
        return (index > start && value.get(index) == Some(&b';')).then_some(index);
    }

    let start = index;
    while matches!(value.get(index), Some(byte) if byte.is_ascii_alphanumeric()) {
        index += 1;
    }
    (index > start && value.get(index) == Some(&b';')).then_some(index)
}

fn html_decode_bytes(value: &[u8], flags: i64, all_entities: bool) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    let quote_mode = html_quote_mode(flags);
    let mut index = 0;
    while index < value.len() {
        if value[index] != b'&' {
            output.push(value[index]);
            index += 1;
            continue;
        }

        if let Some((consumed, decoded)) =
            html_decode_entity_at(value, index, flags, quote_mode, all_entities)
        {
            output.extend_from_slice(&decoded);
            index += consumed;
        } else {
            output.push(value[index]);
            index += 1;
        }
    }
    output
}

fn html_decode_entity_at(
    value: &[u8],
    amp_index: usize,
    flags: i64,
    quote_mode: HtmlQuoteMode,
    all_entities: bool,
) -> Option<(usize, Vec<u8>)> {
    let rest = &value[amp_index..];
    for (entity, decoded) in HTML_BASIC_DECODE_ENTITIES {
        if rest.starts_with(entity.as_bytes()) {
            let allowed = match *entity {
                "&quot;" => matches!(quote_mode, HtmlQuoteMode::Double | HtmlQuoteMode::Both),
                "&#039;" => matches!(quote_mode, HtmlQuoteMode::Both),
                "&apos;" => {
                    matches!(quote_mode, HtmlQuoteMode::Both)
                        && html_decode_apostrophe_entity(flags)
                }
                _ => true,
            };
            if allowed {
                return Some((entity.len(), decoded.as_bytes().to_vec()));
            }
        }
    }

    if all_entities {
        for (decoded, entity) in HTML_ENTITY_EXTRA_TRANSLATIONS {
            if rest.starts_with(entity.as_bytes()) {
                return Some((entity.len(), decoded.to_vec()));
            }
        }
    }

    html_numeric_entity_at(value, amp_index).and_then(|(consumed, codepoint)| {
        if html_numeric_decode_allowed(codepoint, quote_mode, all_entities) {
            let mut buffer = [0_u8; 4];
            char::from_u32(codepoint).map(|character| {
                (
                    consumed,
                    character.encode_utf8(&mut buffer).as_bytes().to_vec(),
                )
            })
        } else {
            None
        }
    })
}

fn html_numeric_entity_at(value: &[u8], amp_index: usize) -> Option<(usize, u32)> {
    let mut index = amp_index + 1;
    if value.get(index) != Some(&b'#') {
        return None;
    }
    index += 1;
    let radix = if matches!(value.get(index).copied(), Some(b'x' | b'X')) {
        index += 1;
        16
    } else {
        10
    };
    let start = index;
    while matches!(value.get(index), Some(byte) if byte.is_ascii_hexdigit()) {
        index += 1;
    }
    if start == index || value.get(index) != Some(&b';') {
        return None;
    }
    let digits = std::str::from_utf8(&value[start..index]).ok()?;
    let codepoint = u32::from_str_radix(digits, radix).ok()?;
    Some((index + 1 - amp_index, codepoint))
}

fn html_numeric_decode_allowed(
    codepoint: u32,
    quote_mode: HtmlQuoteMode,
    all_entities: bool,
) -> bool {
    match codepoint {
        34 => matches!(quote_mode, HtmlQuoteMode::Double | HtmlQuoteMode::Both),
        39 => matches!(quote_mode, HtmlQuoteMode::Both),
        38 | 60 | 62 => true,
        _ => {
            all_entities
                && (codepoint == 9 || codepoint == 10 || codepoint == 13 || codepoint >= 32)
        }
    }
}

static HTML_BASIC_DECODE_ENTITIES: &[(&str, &str)] = &[
    ("&quot;", "\""),
    ("&#039;", "'"),
    ("&apos;", "'"),
    ("&amp;", "&"),
    ("&lt;", "<"),
    ("&gt;", ">"),
];

static HTML_ENTITY_EXTRA_TRANSLATIONS: &[(&[u8], &str)] = &[
    ("\u{00a0}".as_bytes(), "&nbsp;"),
    ("\u{00a1}".as_bytes(), "&iexcl;"),
    ("\u{00a2}".as_bytes(), "&cent;"),
    ("\u{00a3}".as_bytes(), "&pound;"),
    ("\u{00a4}".as_bytes(), "&curren;"),
    ("\u{00a5}".as_bytes(), "&yen;"),
    ("\u{00a9}".as_bytes(), "&copy;"),
    ("\u{00ae}".as_bytes(), "&reg;"),
    ("\u{00c4}".as_bytes(), "&Auml;"),
    ("\u{00c5}".as_bytes(), "&Aring;"),
    ("\u{00e5}".as_bytes(), "&aring;"),
    ("\u{00e9}".as_bytes(), "&eacute;"),
    ("\u{0152}".as_bytes(), "&OElig;"),
    ("\u{0153}".as_bytes(), "&oelig;"),
    ("\u{0178}".as_bytes(), "&Yuml;"),
    (&[0xa0], "&nbsp;"),
    (&[0xa1], "&iexcl;"),
    (&[0xa2], "&cent;"),
    (&[0xa3], "&pound;"),
    (&[0xa4], "&curren;"),
    (&[0xa5], "&yen;"),
    (&[0xa9], "&copy;"),
    (&[0xae], "&reg;"),
    (&[0xc4], "&Auml;"),
    (&[0xc5], "&Aring;"),
    (&[0xe5], "&aring;"),
    (&[0xe9], "&eacute;"),
];

fn html_extra_entity_at(value: &[u8], index: usize) -> Option<(usize, &'static str)> {
    for (bytes, entity) in HTML_ENTITY_EXTRA_TRANSLATIONS {
        if value[index..].starts_with(bytes) {
            return Some((bytes.len(), *entity));
        }
    }
    None
}

fn call_ucwords(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "ucwords()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let mut value = interpreter.php_string_argument_bytes_with_magic(
        "ucwords()",
        1,
        "string",
        &args[0],
        span,
    )?;
    let delimiters = match args.get(1) {
        Some(delimiters) => interpreter.php_string_argument_bytes_with_magic(
            "ucwords()",
            2,
            "separators",
            delimiters,
            span,
        )?,
        None => PHP_UCWORDS_DEFAULT_DELIMITERS.to_vec(),
    };

    let mut uppercase_next = true;
    for byte in &mut value {
        if uppercase_next {
            *byte = (*byte).to_ascii_uppercase();
        }
        uppercase_next = delimiters.contains(&*byte);
    }

    Ok(interpreter_value_from_php_string_bytes(value))
}

fn call_quotemeta(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("quotemeta", args, 1, span)?;

    let value = string_compare_argument_bytes("quotemeta()", "string", &args[0], span)?;
    let mut output = Vec::with_capacity(value.len());
    for byte in value {
        if matches!(
            byte,
            b'.' | b'\\' | b'+' | b'*' | b'?' | b'[' | b'^' | b']' | b'(' | b'$' | b')'
        ) {
            output.push(b'\\');
        }
        output.push(byte);
    }

    Ok(interpreter_value_from_php_string_bytes(output))
}

fn call_preg_quote(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "preg_quote()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("preg_quote()", "str", &args[0], span)?;
    let delimiter = match args.get(1) {
        Some(delimiter) if !matches!(delimiter, Value::Null) => {
            string_compare_argument_bytes("preg_quote()", "delimiter", delimiter, span)?
        }
        _ => Vec::new(),
    };

    let mut output = Vec::with_capacity(value.len());
    for byte in value {
        if byte == 0 {
            output.extend_from_slice(b"\\000");
            continue;
        }
        if matches!(
            byte,
            b'.' | b'\\'
                | b'+'
                | b'*'
                | b'?'
                | b'['
                | b'^'
                | b']'
                | b'$'
                | b'('
                | b')'
                | b'{'
                | b'}'
                | b'='
                | b'!'
                | b'<'
                | b'>'
                | b'|'
                | b':'
                | b'-'
                | b'#'
        ) || delimiter.contains(&byte)
        {
            output.push(b'\\');
        }
        output.push(byte);
    }

    Ok(interpreter_value_from_php_string_bytes(output))
}

fn call_nl2br(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "nl2br()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("nl2br()", "string", &args[0], span)?;
    let tag: &[u8] = match args.get(1) {
        Some(use_xhtml) if !use_xhtml.is_truthy() => b"<br>",
        _ => b"<br />",
    };

    let mut output = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        match value[index] {
            b'\r' if value.get(index + 1) == Some(&b'\n') => {
                output.extend_from_slice(tag);
                output.extend_from_slice(b"\r\n");
                index += 2;
            }
            b'\n' if value.get(index + 1) == Some(&b'\r') => {
                output.extend_from_slice(tag);
                output.extend_from_slice(b"\n\r");
                index += 2;
            }
            b'\r' | b'\n' => {
                output.extend_from_slice(tag);
                output.push(value[index]);
                index += 1;
            }
            byte => {
                output.push(byte);
                index += 1;
            }
        }
    }

    Ok(interpreter_value_from_php_string_bytes(output))
}

fn call_str_repeat(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
    memory_limit_bytes: usize,
) -> CompileResult<Value> {
    expect_arity("str_repeat", args, 2, span)?;

    let value = interpreter.php_string_argument_bytes_with_magic(
        "str_repeat()",
        1,
        "string",
        &args[0],
        span,
    )?;
    let times = php_internal_int_argument("str_repeat()", 2, "times", &args[1], span)?;

    if times < 0 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_repeat()",
                "Argument #2 ($times) must be greater than or equal to 0",
            ),
        ));
    }

    let times = times as usize;
    let output_len = value.len().checked_mul(times).ok_or_else(|| {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_repeat()",
                "result length overflows the current subset",
            ),
        )
    })?;
    if output_len > memory_limit_bytes {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_repeat()",
                format!(
                    "Allowed memory size of {} bytes exhausted (tried to allocate {} bytes)",
                    memory_limit_bytes, output_len
                ),
            ),
        ));
    }

    let mut repeated = Vec::with_capacity(output_len);
    for _ in 0..times {
        repeated.extend_from_slice(&value);
    }

    Ok(interpreter_value_from_php_string_bytes(repeated))
}

fn repeated_pad_bytes(pad: &[u8], len: usize) -> Vec<u8> {
    let mut output = Vec::with_capacity(len);
    while output.len() < len {
        let remaining = len - output.len();
        let take = remaining.min(pad.len());
        output.extend_from_slice(&pad[..take]);
    }
    output
}

fn str_pad_memory_exhausted_message(target_len: usize) -> String {
    format!(
        "Allowed memory size of {} bytes exhausted (tried to allocate {} bytes)",
        PHP_STR_PAD_MEMORY_LIMIT_BYTES, target_len
    )
}

fn call_str_pad(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(2..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "str_pad()",
                ArityExpectation::Between { min: 2, max: 4 },
                args.len(),
            ),
        ));
    }

    if matches!(args[0], Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call("str_pad()", "string argument arrays are not supported"),
        ));
    }

    let value = args[0]
        .try_echo_bytes()
        .map_err(|error| runtime_error(span, error))?;
    let length = php_internal_int_argument("str_pad()", 2, "length", &args[1], span)?;
    if length <= value.len() as i64 {
        return Ok(interpreter_value_from_php_string_bytes(value));
    }

    let pad = if let Some(pad) = args.get(2) {
        if matches!(pad, Value::Array(_)) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "str_pad()",
                    "pad_string argument arrays are not supported",
                ),
            ));
        }
        pad.try_echo_bytes()
            .map_err(|error| runtime_error(span, error))?
    } else {
        b" ".to_vec()
    };

    if pad.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_pad()",
                "Argument #3 ($pad_string) must not be empty",
            ),
        ));
    }

    let pad_type = match args.get(3) {
        Some(value) => php_internal_int_argument("str_pad()", 4, "pad_type", value, span)?,
        None => PHP_STR_PAD_RIGHT,
    };

    let target_len = length as usize;
    if target_len > 16 * 1024 * 1024 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_pad()",
                str_pad_memory_exhausted_message(target_len),
            ),
        ));
    }
    let needed = target_len - value.len();
    let (left_len, right_len) = match pad_type {
        PHP_STR_PAD_RIGHT => (0, needed),
        PHP_STR_PAD_LEFT => (needed, 0),
        PHP_STR_PAD_BOTH => (needed / 2, needed - (needed / 2)),
        _ => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "str_pad()",
                    "Argument #4 ($pad_type) must be STR_PAD_LEFT, STR_PAD_RIGHT, or STR_PAD_BOTH",
                ),
            ));
        }
    };

    let mut output = Vec::with_capacity(target_len);
    output.extend_from_slice(&repeated_pad_bytes(&pad, left_len));
    output.extend_from_slice(&value);
    output.extend_from_slice(&repeated_pad_bytes(&pad, right_len));

    Ok(interpreter_value_from_php_string_bytes(output))
}

fn call_wordwrap(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "wordwrap()",
                ArityExpectation::Between { min: 1, max: 4 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("wordwrap()", "string", &args[0], span)?;
    let width = match args.get(1) {
        Some(width) => php_internal_int_argument("wordwrap()", 2, "width", width, span)?,
        None => 75,
    };
    let break_string = match args.get(2) {
        Some(value) => string_compare_argument_bytes("wordwrap()", "break", value, span)?,
        None => b"\n".to_vec(),
    };
    if break_string.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call("wordwrap()", "Argument #3 ($break) must not be empty"),
        ));
    }
    let cut = args.get(3).is_some_and(Value::is_truthy);
    if width == 0 && cut {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "wordwrap()",
                "Argument #4 ($cut_long_words) cannot be true when argument #2 ($width) is 0",
            ),
        ));
    }

    let output = if width <= 0 {
        wordwrap_zero_or_negative_width(&value, &break_string, cut)
    } else {
        wordwrap_positive_width(&value, width as usize, &break_string, cut)
    };
    Ok(interpreter_value_from_php_string_bytes(output))
}

fn wordwrap_zero_or_negative_width(value: &[u8], break_string: &[u8], cut: bool) -> Vec<u8> {
    if cut {
        let mut output = Vec::new();
        for &byte in value {
            output.extend_from_slice(break_string);
            if byte != b' ' {
                output.push(byte);
            }
        }
        return output;
    }

    let mut output = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        if value[index] == b' ' {
            while index < value.len() && value[index] == b' ' {
                index += 1;
            }
            if !output.is_empty() && index < value.len() {
                output.extend_from_slice(break_string);
            }
        } else {
            output.push(value[index]);
            index += 1;
        }
    }
    output
}

fn wordwrap_positive_width(value: &[u8], width: usize, break_string: &[u8], cut: bool) -> Vec<u8> {
    let mut output = Vec::new();
    let mut start = 0;

    while value.len().saturating_sub(start) > width {
        let limit = start + width;
        if let Some(existing_break) =
            wordwrap_existing_break_at_or_before_limit(value, start, limit, break_string)
        {
            output.extend_from_slice(&value[start..existing_break]);
            output.extend_from_slice(break_string);
            start = existing_break + break_string.len();
            continue;
        }

        if let Some(space) = wordwrap_last_space_after_start(value, start, limit) {
            output.extend_from_slice(&value[start..space]);
            output.extend_from_slice(break_string);
            start = space + 1;
            continue;
        }

        if cut {
            output.extend_from_slice(&value[start..limit]);
            output.extend_from_slice(break_string);
            start = limit;
            continue;
        }

        let Some(space) = value[limit..]
            .iter()
            .position(|byte| *byte == b' ')
            .map(|offset| limit + offset)
        else {
            break;
        };
        output.extend_from_slice(&value[start..space]);
        output.extend_from_slice(break_string);
        start = space + 1;
    }

    output.extend_from_slice(&value[start..]);
    output
}

fn wordwrap_existing_break_at_or_before_limit(
    value: &[u8],
    start: usize,
    limit: usize,
    break_string: &[u8],
) -> Option<usize> {
    (start..=limit).find(|index| value[*index..].starts_with(break_string))
}

fn wordwrap_last_space_after_start(value: &[u8], start: usize, limit: usize) -> Option<usize> {
    value[start + 1..=limit]
        .iter()
        .rposition(|byte| *byte == b' ')
        .map(|offset| start + 1 + offset)
}

fn call_str_word_count(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "str_word_count()",
                ArityExpectation::Between { min: 1, max: 3 },
                args.len(),
            ),
        ));
    }

    let value = string_compare_argument_bytes("str_word_count()", "string", &args[0], span)?;
    let format = match args.get(1) {
        Some(value) => php_internal_int_argument("str_word_count()", 2, "format", value, span)?,
        None => 0,
    };
    if !matches!(format, 0..=2) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_word_count()",
                "Argument #2 ($format) must be a valid format value",
            ),
        ));
    }
    let charlist = match args.get(2) {
        Some(value) => {
            string_compare_argument_bytes("str_word_count()", "characters", value, span)?
        }
        None => Vec::new(),
    };

    let words = str_word_count_words(&value, &charlist);
    match format {
        0 => Ok(Value::Int(words.len() as i64)),
        1 => {
            let mut array = PhpArray::new();
            for (_, word) in words {
                array
                    .append(interpreter_value_from_php_string_bytes(word))
                    .map_err(|error| runtime_error(span, error))?;
            }
            Ok(Value::Array(array))
        }
        2 => {
            let mut array = PhpArray::new();
            for (offset, word) in words {
                array.insert(offset as i64, interpreter_value_from_php_string_bytes(word));
            }
            Ok(Value::Array(array))
        }
        _ => unreachable!("str_word_count format was validated"),
    }
}

fn str_word_count_words(value: &[u8], charlist: &[u8]) -> Vec<(usize, Vec<u8>)> {
    let mut words = Vec::new();
    if value.is_empty() {
        return words;
    }

    let mut index = 0;
    let mut end = value.len();
    if (value[index] == b'\'' || value[index] == b'-')
        && !str_word_count_charlist_contains(charlist, value[index])
    {
        index += 1;
    }
    if index < end && value[end - 1] == b'-' && !str_word_count_charlist_contains(charlist, b'-') {
        end -= 1;
    }

    while index < end {
        let start = index;
        while index < end && str_word_count_is_word_byte(value[index], charlist) {
            index += 1;
        }
        if index > start {
            words.push((start, value[start..index].to_vec()));
        }
        index += 1;
    }

    words
}

fn str_word_count_is_word_byte(byte: u8, charlist: &[u8]) -> bool {
    str_word_count_is_base_word_byte(byte)
        || str_word_count_charlist_contains(charlist, byte)
        || byte == b'\''
        || byte == b'-'
}

fn str_word_count_is_base_word_byte(byte: u8) -> bool {
    byte.is_ascii_alphabetic()
}

fn str_word_count_charlist_contains(charlist: &[u8], byte: u8) -> bool {
    charlist.contains(&byte)
}

impl Interpreter {
    fn call_trim_family(
        &mut self,
        args: &[Value],
        span: Span,
        function: &'static str,
        mode: TrimMode,
    ) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    function,
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let value =
            self.php_string_argument_bytes_with_magic(function, 1, "string", &args[0], span)?;
        let mask = if let Some(mask) = args.get(1) {
            let mask =
                self.php_string_argument_bytes_with_magic(function, 2, "characters", mask, span)?;
            match expanded_trim_mask(&mask) {
                TrimMaskExpansion::Expanded(mask) => mask,
                TrimMaskExpansion::Invalid(message) => {
                    self.emit_display_warning(format!("{function}: {message}"), span)?;
                    return Ok(interpreter_value_from_php_string_bytes(value));
                }
            }
        } else {
            PHP_DEFAULT_TRIM_MASK_BYTES.to_vec()
        };

        Ok(interpreter_value_from_php_string_bytes(
            trim_bytes_with_mask(&value, &mask, mode),
        ))
    }

    fn call_strnatcmp(
        &mut self,
        args: &[Value],
        function: &'static str,
        case_insensitive: bool,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(function.trim_end_matches("()"), args, 2, span)?;
        let left = self.value_to_echo_bytes(args[0].clone(), span)?;
        let right = self.value_to_echo_bytes(args[1].clone(), span)?;
        Ok(Value::Int(i64::from(natural_compare_bytes(
            &left,
            &right,
            case_insensitive,
        ))))
    }
}

fn natural_compare_bytes(left: &[u8], right: &[u8], case_insensitive: bool) -> i32 {
    let mut left_index = natural_skip_initial_leading_zeroes(left);
    let mut right_index = natural_skip_initial_leading_zeroes(right);

    loop {
        if left_index == left.len() || right_index == right.len() {
            return compare_usize(left.len() - left_index, right.len() - right_index);
        }

        while left_index < left.len() && left[left_index].is_ascii_whitespace() {
            left_index += 1;
        }
        while right_index < right.len() && right[right_index].is_ascii_whitespace() {
            right_index += 1;
        }

        if left_index == left.len() || right_index == right.len() {
            return compare_usize(left.len() - left_index, right.len() - right_index);
        }

        let left_byte = left[left_index];
        let right_byte = right[right_index];
        if left_byte.is_ascii_digit() && right_byte.is_ascii_digit() {
            let sign = if left_byte == b'0' || right_byte == b'0' {
                natural_compare_left_aligned_number(left, right, &mut left_index, &mut right_index)
            } else {
                natural_compare_right_aligned_number(left, right, &mut left_index, &mut right_index)
            };
            if sign != 0 {
                return sign;
            }
            if left_index == left.len() && right_index == right.len() {
                return 0;
            }
            if left_index == left.len() {
                return -1;
            }
            if right_index == right.len() {
                return 1;
            }
        }

        let left_cmp = natural_compare_fold_byte(left[left_index], case_insensitive);
        let right_cmp = natural_compare_fold_byte(right[right_index], case_insensitive);
        if left_cmp != right_cmp {
            return compare_u8(left_cmp, right_cmp);
        }

        left_index += 1;
        right_index += 1;
    }
}

fn natural_compare_left_aligned_number(
    left: &[u8],
    right: &[u8],
    left_index: &mut usize,
    right_index: &mut usize,
) -> i32 {
    loop {
        let left_digit = left.get(*left_index).copied().filter(u8::is_ascii_digit);
        let right_digit = right.get(*right_index).copied().filter(u8::is_ascii_digit);

        match (left_digit, right_digit) {
            (None, None) => return 0,
            (None, Some(_)) => return -1,
            (Some(_), None) => return 1,
            (Some(left_digit), Some(right_digit)) => {
                if left_digit != right_digit {
                    return compare_u8(left_digit, right_digit);
                }
                *left_index += 1;
                *right_index += 1;
            }
        }
    }
}

fn natural_compare_right_aligned_number(
    left: &[u8],
    right: &[u8],
    left_index: &mut usize,
    right_index: &mut usize,
) -> i32 {
    let mut bias = 0;

    loop {
        let left_digit = left.get(*left_index).copied().filter(u8::is_ascii_digit);
        let right_digit = right.get(*right_index).copied().filter(u8::is_ascii_digit);

        match (left_digit, right_digit) {
            (None, None) => return bias,
            (None, Some(_)) => return -1,
            (Some(_), None) => return 1,
            (Some(left_digit), Some(right_digit)) => {
                if bias == 0 && left_digit != right_digit {
                    bias = compare_u8(left_digit, right_digit);
                }
                *left_index += 1;
                *right_index += 1;
            }
        }
    }
}

fn natural_skip_initial_leading_zeroes(value: &[u8]) -> usize {
    let mut index = 0;
    while index + 1 < value.len() && value[index] == b'0' && value[index + 1].is_ascii_digit() {
        index += 1;
    }
    index
}

fn natural_compare_fold_byte(byte: u8, case_insensitive: bool) -> u8 {
    if case_insensitive {
        byte.to_ascii_lowercase()
    } else {
        byte
    }
}

fn compare_u8(left: u8, right: u8) -> i32 {
    match left.cmp(&right) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

fn compare_usize(left: usize, right: usize) -> i32 {
    match left.cmp(&right) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

fn call_chunk_split(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    if !(1..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "chunk_split()",
                ArityExpectation::Between { min: 1, max: 3 },
                args.len(),
            ),
        ));
    }

    let value = interpreter.php_string_argument_bytes_with_magic(
        "chunk_split()",
        1,
        "string",
        &args[0],
        span,
    )?;
    let chunk_len = match args.get(1) {
        Some(length) => php_internal_int_argument("chunk_split()", 2, "length", length, span)?,
        None => 76,
    };
    if chunk_len < 1 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "chunk_split()",
                "Argument #2 ($length) must be greater than 0",
            ),
        ));
    }

    let separator = if let Some(separator) = args.get(2) {
        interpreter.php_string_argument_bytes_with_magic(
            "chunk_split()",
            3,
            "separator",
            separator,
            span,
        )?
    } else {
        b"\r\n".to_vec()
    };

    let chunk_len = chunk_len as usize;
    let chunk_count = if value.is_empty() {
        1
    } else {
        value.len().div_ceil(chunk_len)
    };
    let separator_bytes = separator.len().checked_mul(chunk_count).ok_or_else(|| {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "chunk_split()",
                "result length overflows the current subset",
            ),
        )
    })?;
    let output_len = value.len().checked_add(separator_bytes).ok_or_else(|| {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "chunk_split()",
                "result length overflows the current subset",
            ),
        )
    })?;
    if output_len > PHP_STANDARD_STRING_MEMORY_LIMIT_BYTES {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "chunk_split()",
                format!(
                    "Allowed memory size of {} bytes exhausted (tried to allocate {} bytes)",
                    PHP_STANDARD_STRING_MEMORY_LIMIT_BYTES, output_len
                ),
            ),
        ));
    }

    let mut output = Vec::with_capacity(output_len);
    if value.is_empty() {
        output.extend_from_slice(&separator);
    } else {
        for chunk in value.chunks(chunk_len) {
            output.extend_from_slice(chunk);
            output.extend_from_slice(&separator);
        }
    }

    Ok(interpreter_value_from_php_string_bytes(output))
}

fn call_str_split(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "str_split()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    if matches!(args[0], Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_split()",
                "string argument arrays are not supported",
            ),
        ));
    }

    let value = args[0]
        .try_echo_bytes()
        .map_err(|error| runtime_error(span, error))?;
    let split_len = match args.get(1) {
        Some(length) => php_internal_int_argument("str_split()", 2, "length", length, span)?,
        None => 1,
    };
    if split_len < 1 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_split()",
                "Argument #2 ($length) must be greater than 0",
            ),
        ));
    }

    let split_len = split_len as usize;
    let mut array = PhpArray::new();
    for chunk in value.chunks(split_len) {
        array
            .append(interpreter_value_from_php_string_bytes(chunk.to_vec()))
            .map_err(|error| runtime_error(span, error))?;
    }

    Ok(Value::Array(array))
}

impl Interpreter {
    fn call_addslashes(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("addslashes", args, 1, span)?;
        let value =
            self.cslashes_string_argument_bytes("addslashes()", 1, "string", &args[0], span)?;
        Ok(interpreter_value_from_php_string_bytes(addslashes_bytes(
            &value,
        )))
    }

    fn call_stripslashes(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("stripslashes", args, 1, span)?;
        let value =
            self.cslashes_string_argument_bytes("stripslashes()", 1, "string", &args[0], span)?;
        Ok(interpreter_value_from_php_string_bytes(stripslashes_bytes(
            &value,
        )))
    }

    fn call_addcslashes(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("addcslashes", args, 2, span)?;
        let value =
            self.cslashes_string_argument_bytes("addcslashes()", 1, "string", &args[0], span)?;
        let characters =
            self.cslashes_string_argument_bytes("addcslashes()", 2, "characters", &args[1], span)?;
        let mask = self.addcslashes_mask(&characters, span)?;
        Ok(interpreter_value_from_php_string_bytes(addcslashes_bytes(
            &value, &mask,
        )))
    }

    fn call_stripcslashes(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("stripcslashes", args, 1, span)?;
        let value =
            self.cslashes_string_argument_bytes("stripcslashes()", 1, "string", &args[0], span)?;
        Ok(interpreter_value_from_php_string_bytes(
            stripcslashes_bytes(&value),
        ))
    }

    fn cslashes_string_argument_bytes(
        &mut self,
        function: &str,
        position: usize,
        name: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Vec<u8>> {
        if matches!(value, Value::Array(_)) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!("Argument #{position} (${name}) must be of type string, array given"),
                ),
            ));
        }

        if let Value::Object(object) = value {
            if let Some(value) = self.object_to_string_with_magic(object.clone(), function, span)? {
                return Ok(value.into_bytes());
            }
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #{position} (${name}) must be of type string, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        }

        if matches!(value, Value::Closure(_) | Value::Resource(_)) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #{position} (${name}) must be of type string, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        }

        value
            .try_echo_bytes()
            .map_err(|error| runtime_error(span, error))
    }

    fn addcslashes_mask(&mut self, characters: &[u8], span: Span) -> CompileResult<[bool; 256]> {
        let mut mask = [false; 256];
        let mut index = 0;

        while index < characters.len() {
            if characters.get(index + 1) == Some(&b'.')
                && characters.get(index + 2) == Some(&b'.')
                && characters.get(index + 3).is_some()
            {
                let start = characters[index];
                let end = characters[index + 3];
                if start <= end {
                    for byte in start..=end {
                        mask[byte as usize] = true;
                    }
                    index += 4;
                    continue;
                }

                self.emit_display_warning(
                    "addcslashes(): Invalid '..'-range, '..'-range needs to be incrementing",
                    span,
                )?;
            }

            mask[characters[index] as usize] = true;
            index += 1;
        }

        Ok(mask)
    }
}

fn addslashes_bytes(value: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    for &byte in value {
        match byte {
            b'\0' => output.extend_from_slice(br"\0"),
            b'\'' | b'"' | b'\\' => {
                output.push(b'\\');
                output.push(byte);
            }
            _ => output.push(byte),
        }
    }
    output
}

fn stripslashes_bytes(value: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        let byte = value[index];
        if byte != b'\\' {
            output.push(byte);
            index += 1;
            continue;
        }

        let Some(&next) = value.get(index + 1) else {
            break;
        };
        output.push(if next == b'0' { b'\0' } else { next });
        index += 2;
    }
    output
}

fn addcslashes_bytes(value: &[u8], mask: &[bool; 256]) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    for &byte in value {
        if !mask[byte as usize] {
            output.push(byte);
            continue;
        }

        match byte {
            b'\0' => output.extend_from_slice(br"\000"),
            b'\n' => output.extend_from_slice(br"\n"),
            b'\r' => output.extend_from_slice(br"\r"),
            b'\t' => output.extend_from_slice(br"\t"),
            0x0b => output.extend_from_slice(br"\v"),
            0x0c => output.extend_from_slice(br"\f"),
            0x07 => output.extend_from_slice(br"\a"),
            0x08 => output.extend_from_slice(br"\b"),
            0x01..=0x1f | 0x7f..=0xff => {
                output.push(b'\\');
                output.push(b'0' + ((byte >> 6) & 0x07));
                output.push(b'0' + ((byte >> 3) & 0x07));
                output.push(b'0' + (byte & 0x07));
            }
            _ => {
                output.push(b'\\');
                output.push(byte);
            }
        }
    }
    output
}

fn stripcslashes_bytes(value: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        let byte = value[index];
        if byte != b'\\' {
            output.push(byte);
            index += 1;
            continue;
        }

        let Some(&next) = value.get(index + 1) else {
            break;
        };
        match next {
            b'n' => {
                output.push(b'\n');
                index += 2;
            }
            b'r' => {
                output.push(b'\r');
                index += 2;
            }
            b't' => {
                output.push(b'\t');
                index += 2;
            }
            b'v' => {
                output.push(0x0b);
                index += 2;
            }
            b'f' => {
                output.push(0x0c);
                index += 2;
            }
            b'a' => {
                output.push(0x07);
                index += 2;
            }
            b'b' => {
                output.push(0x08);
                index += 2;
            }
            b'x' | b'X' => {
                let mut parsed = 0u8;
                let mut digits = 0usize;
                let mut cursor = index + 2;
                while digits < 2 {
                    let Some(&digit) = value.get(cursor) else {
                        break;
                    };
                    let Some(value) = hex_digit_value(digit) else {
                        break;
                    };
                    parsed = (parsed << 4) | value;
                    digits += 1;
                    cursor += 1;
                }
                if digits == 0 {
                    output.push(next);
                    index += 2;
                } else {
                    output.push(parsed);
                    index = cursor;
                }
            }
            b'0'..=b'7' => {
                let mut parsed = 0u8;
                let mut digits = 0usize;
                let mut cursor = index + 1;
                while digits < 3 {
                    let Some(&digit @ b'0'..=b'7') = value.get(cursor) else {
                        break;
                    };
                    parsed = (parsed << 3) | (digit - b'0');
                    digits += 1;
                    cursor += 1;
                }
                output.push(parsed);
                index = cursor;
            }
            _ => {
                output.push(next);
                index += 2;
            }
        }
    }
    output
}

