enum FileGetContentsRead {
    Contents(Vec<u8>),
    WarningFalse(String),
}

fn bounded_file_get_contents_slice(
    contents: &[u8],
    offset: Option<i64>,
    max_length: Option<i64>,
) -> FileGetContentsRead {
    let len = contents.len() as i64;
    let raw_start = match offset {
        Some(offset) if offset < 0 && offset.saturating_abs() > len => {
            return FileGetContentsRead::WarningFalse(format!(
                "Failed to seek to position {offset} in the stream"
            ));
        }
        Some(offset) if offset < 0 => len + offset,
        Some(offset) => offset.min(len),
        None => 0,
    };
    let raw_end = match max_length {
        Some(max_length) => raw_start.saturating_add(max_length).min(len),
        None => len,
    };
    FileGetContentsRead::Contents(contents[raw_start as usize..raw_end as usize].to_vec())
}

impl Interpreter {
    fn call_headers_sent_values(&self, args: &[Value], span: Span) -> CompileResult<Value> {
        if args.len() > 2 {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "headers_sent()",
                    ArityExpectation::Between { min: 0, max: 2 },
                    args.len(),
                ),
            ));
        }

        if !args.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "headers_sent()",
                    "filename and line output arguments require direct variable call arguments in the current subset",
                ),
            ));
        }

        Ok(Value::Bool(self.output_start.is_some()))
    }
}

