impl Interpreter {
    fn call_getprotobyname(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("getprotobyname", args, 1, span)?;
        let protocol = self.network_database_string_argument(
            "getprotobyname()",
            1,
            "protocol",
            &args[0],
            span,
        )?;
        Ok(bounded_protocol_number(&protocol)
            .map(Value::Int)
            .unwrap_or(Value::Bool(false)))
    }

    fn call_getservbyname(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("getservbyname", args, 2, span)?;
        let service =
            self.network_database_string_argument("getservbyname()", 1, "service", &args[0], span)?;
        let protocol = self.network_database_string_argument(
            "getservbyname()",
            2,
            "protocol",
            &args[1],
            span,
        )?;

        Ok(bounded_service_port(&service, &protocol)
            .map(Value::Int)
            .unwrap_or(Value::Bool(false)))
    }

    fn call_getservbyport(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("getservbyport", args, 2, span)?;
        let port = php_internal_int_argument("getservbyport()", 1, "port", &args[0], span)?;
        let protocol = self.network_database_string_argument(
            "getservbyport()",
            2,
            "protocol",
            &args[1],
            span,
        )?;

        if !(0..=65535).contains(&port) {
            return Ok(Value::Bool(false));
        }

        Ok(bounded_service_name(port, &protocol)
            .map(|service| Value::String(service.to_string()))
            .unwrap_or(Value::Bool(false)))
    }

    fn network_database_string_argument(
        &mut self,
        function: &'static str,
        position: usize,
        name: &str,
        value: &Value,
        span: Span,
    ) -> CompileResult<String> {
        let value = match value {
            Value::Null => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "{function}: Passing null to parameter #{position} (${name}) of type string is deprecated"
                    ),
                    span,
                )?;
                String::new()
            }
            Value::Object(object) => {
                if let Some(value) =
                    self.object_to_string_with_magic(object.clone(), function, span)?
                {
                    value
                } else {
                    return Err(Self::network_database_string_type_error(
                        function, position, name, value, span,
                    ));
                }
            }
            Value::Array(_) | Value::Closure(_) | Value::Resource(_) => {
                return Err(Self::network_database_string_type_error(
                    function, position, name, value, span,
                ));
            }
            _ => value
                .try_echo_string()
                .map_err(|error| runtime_error(span, error))?,
        };

        if value.contains('\0') {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!("Argument #{position} (${name}) must not contain any null bytes"),
                ),
            ));
        }
        Ok(value)
    }

    fn network_database_string_type_error(
        function: &'static str,
        position: usize,
        name: &str,
        value: &Value,
        span: Span,
    ) -> Diagnostic {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "Argument #{position} (${name}) must be of type string, {} given",
                    php_type_error_given(value)
                ),
            ),
        )
    }
}

fn bounded_protocol_number(protocol: &str) -> Option<i64> {
    match protocol.to_ascii_lowercase().as_str() {
        "icmp" => Some(1),
        "tcp" => Some(6),
        "udp" => Some(17),
        _ => None,
    }
}

fn bounded_protocol_name(protocol: i64) -> Option<&'static str> {
    match protocol {
        1 => Some("icmp"),
        6 => Some("tcp"),
        17 => Some("udp"),
        _ => None,
    }
}

fn bounded_service_port(service: &str, protocol: &str) -> Option<i64> {
    if protocol != "tcp" {
        return None;
    }

    match service {
        "ftp" => Some(21),
        "ssh" => Some(22),
        "telnet" => Some(23),
        "smtp" => Some(25),
        "nicname" => Some(43),
        "gopher" => Some(70),
        "finger" => Some(79),
        "http" | "www" => Some(80),
        "pop3" => Some(110),
        "imap" => Some(143),
        _ => None,
    }
}

fn bounded_service_name(port: i64, protocol: &str) -> Option<&'static str> {
    if protocol != "tcp" {
        return None;
    }

    match port {
        21 => Some("ftp"),
        22 => Some("ssh"),
        23 => Some("telnet"),
        25 => Some("smtp"),
        43 => Some("nicname"),
        70 => Some("gopher"),
        79 => Some("finger"),
        80 => Some("http"),
        110 => Some("pop3"),
        143 => Some("imap"),
        _ => None,
    }
}

fn call_php_uname(args: &[Value], span: Span) -> CompileResult<Value> {
    if args.len() > 1 {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "php_uname()",
                ArityExpectation::Between { min: 0, max: 1 },
                args.len(),
            ),
        ));
    }

    let mode = match args.first() {
        Some(value) => value
            .try_echo_string()
            .map_err(|error| runtime_error(span, error))?,
        None => "a".to_string(),
    };
    let mut chars = mode.chars();
    let Some(mode) = chars.next() else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "php_uname()",
                "Argument #1 ($mode) must be a single character",
            ),
        ));
    };
    if chars.next().is_some() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "php_uname()",
                "Argument #1 ($mode) must be a single character",
            ),
        ));
    }

    let system = "Linux";
    let node = "phpc";
    let release = "0.0.0";
    let version = "#1 phpc";
    let machine = std::env::consts::ARCH;
    let value = match mode {
        'a' => format!("{system} {node} {release} {version} {machine}"),
        's' => system.to_string(),
        'n' => node.to_string(),
        'r' => release.to_string(),
        'v' => version.to_string(),
        'm' => machine.to_string(),
        _ => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "php_uname()",
                    "Argument #1 ($mode) must be one of \"a\", \"m\", \"n\", \"r\", \"s\", or \"v\"",
                ),
            ));
        }
    };
    Ok(Value::String(value))
}

fn call_get_current_user(
    args: &[Value],
    main_source_file: Option<&str>,
    span: Span,
) -> CompileResult<Value> {
    expect_arity("get_current_user", args, 0, span)?;
    Ok(Value::String(current_user_name(main_source_file)))
}

fn current_user_name(main_source_file: Option<&str>) -> String {
    if let Some(source_file) = main_source_file {
        let path = local_filesystem_metadata_path(source_file);
        if let Ok(metadata) = fs::metadata(path) {
            if let Some(name) = username_for_file_metadata(&metadata) {
                return name;
            }
        }
    }

    std::env::var("USER")
        .ok()
        .filter(|value| !value.is_empty())
        .or_else(|| {
            std::env::var("LOGNAME")
                .ok()
                .filter(|value| !value.is_empty())
        })
        .unwrap_or_default()
}

