fn call_intdiv(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("intdiv", args, 2, span)?;
    let left = php_internal_int_argument("intdiv()", 1, "num1", &args[0], span)?;
    let right = php_internal_int_argument("intdiv()", 2, "num2", &args[1], span)?;
    if right == 0 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call("intdiv()", "Division by zero"),
        ));
    }
    if left == i64::MIN && right == -1 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "intdiv()",
                "Division of PHP_INT_MIN by -1 is not an integer",
            ),
        ));
    }
    Ok(Value::Int(left / right))
}

fn call_round(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "round()",
                ArityExpectation::Between { min: 1, max: 3 },
                args.len(),
            ),
        ));
    }

    let number =
        php_math_int_or_float_argument(interpreter, "round()", "int|float", &args[0], span)?;
    let precision = match args.get(1) {
        Some(value) => round_precision_argument(interpreter, value, span)?,
        None => 0,
    };
    let mode = match args.get(2) {
        Some(value) => round_mode_argument(value, span)?,
        None => BcRoundingMode::HalfAwayFromZero,
    };

    Ok(Value::Float(round_math_number_value(
        number, precision, mode,
    )))
}

fn round_precision_argument(
    interpreter: &mut Interpreter,
    value: &Value,
    span: Span,
) -> CompileResult<i64> {
    match value {
        Value::Float(float) => {
            if float.is_finite() && float.trunc() != *float {
                interpreter.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "Implicit conversion from float {} to int loses precision",
                        format_php_float_to_int_deprecation_value(*float)
                    ),
                    span,
                )?;
            }
            php_float_to_internal_i64(*float)
                .ok_or_else(|| php_internal_int_type_error("round()", 2, "precision", value, span))
        }
        Value::String(text) => {
            if let Ok(parsed) = text.trim().parse::<f64>() {
                if parsed.is_finite() && parsed.trunc() != parsed {
                    interpreter.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        format!(
                            "Implicit conversion from float-string \"{text}\" to int loses precision"
                        ),
                        span,
                    )?;
                }
            }
            php_internal_int_argument("round()", 2, "precision", value, span)
        }
        Value::BinaryString(bytes) => {
            if let Ok(text) = std::str::from_utf8(bytes) {
                if let Ok(parsed) = text.trim().parse::<f64>() {
                    if parsed.is_finite() && parsed.trunc() != parsed {
                        interpreter.emit_display_diagnostic(
                            "Deprecated",
                            PHP_E_DEPRECATED,
                            format!(
                                "Implicit conversion from float-string \"{text}\" to int loses precision"
                            ),
                            span,
                        )?;
                    }
                }
            }
            php_internal_int_argument("round()", 2, "precision", value, span)
        }
        _ => php_internal_int_argument("round()", 2, "precision", value, span),
    }
}

fn round_mode_argument(value: &Value, span: Span) -> CompileResult<BcRoundingMode> {
    match value {
        Value::Int(PHP_ROUND_HALF_UP) => Ok(BcRoundingMode::HalfAwayFromZero),
        Value::Int(PHP_ROUND_HALF_DOWN) => Ok(BcRoundingMode::HalfTowardsZero),
        Value::Int(PHP_ROUND_HALF_EVEN) => Ok(BcRoundingMode::HalfEven),
        Value::Int(PHP_ROUND_HALF_ODD) => Ok(BcRoundingMode::HalfOdd),
        Value::Int(_) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "round()",
                "Argument #3 ($mode) must be a valid rounding mode (RoundingMode::*)",
            ),
        )),
        Value::Object(object) if object.class_name().eq_ignore_ascii_case("RoundingMode") => {
            let name = object
                .read_public_property("name")
                .map_err(|error| runtime_error(span, error))?;
            let Value::String(name) = name else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "round()",
                        "Argument #3 ($mode) must be a valid rounding mode (RoundingMode::*)",
                    ),
                ));
            };
            BcRoundingMode::from_case_name(&name).ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "round()",
                        "Argument #3 ($mode) must be a valid rounding mode (RoundingMode::*)",
                    ),
                )
            })
        }
        Value::Object(object) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "round()",
                format!(
                    "Argument #3 ($mode) must be of type RoundingMode|int, {} given",
                    object.class_name()
                ),
            ),
        )),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "round()",
                format!(
                    "Argument #3 ($mode) must be of type RoundingMode|int, {} given",
                    php_type_error_given(other)
                ),
            ),
        )),
    }
}

fn round_math_number_value(value: MathIntOrFloat, precision: i64, mode: BcRoundingMode) -> f64 {
    match value {
        MathIntOrFloat::Int(value) => round_int_value(value, precision, mode),
        MathIntOrFloat::Float(value) => round_float_value(value, precision, mode),
    }
}

fn round_int_value(value: i64, precision: i64, mode: BcRoundingMode) -> f64 {
    let Some(decimal) = BcDecimal::parse(&value.to_string()) else {
        return value as f64;
    };
    round_decimal_to_float(&decimal, value.is_negative(), value as f64, precision, mode)
}

fn round_float_value(value: f64, precision: i64, mode: BcRoundingMode) -> f64 {
    if !value.is_finite() || value == 0.0 {
        return value;
    }

    let Some(decimal) = bc_decimal_from_float_shortest(value) else {
        return value;
    };
    round_decimal_to_float(&decimal, value.is_sign_negative(), value, precision, mode)
}

fn round_decimal_to_float(
    decimal: &BcDecimal,
    source_negative: bool,
    fallback: f64,
    precision: i64,
    mode: BcRoundingMode,
) -> f64 {
    let precision = precision.clamp(-308, 308) as i32;
    let rounded = decimal.round(precision, mode);
    let output_scale = precision.max(0) as usize;
    let Ok(result) = rounded.format_with_scale(output_scale).parse::<f64>() else {
        return fallback;
    };
    if result == 0.0 && source_negative {
        -0.0
    } else {
        result
    }
}

fn bc_decimal_from_float_shortest(value: f64) -> Option<BcDecimal> {
    let text = value.to_string();
    let decimal = expand_scientific_decimal_text(&text)?;
    BcDecimal::parse(&decimal)
}

fn expand_scientific_decimal_text(text: &str) -> Option<String> {
    let Some(exponent_index) = text.find(['e', 'E']) else {
        return Some(text.to_string());
    };
    let (mantissa, exponent) = text.split_at(exponent_index);
    let exponent = exponent[1..].parse::<i32>().ok()?;
    let (sign, mantissa) = match mantissa.as_bytes().first().copied() {
        Some(b'-') | Some(b'+') => (&mantissa[..1], &mantissa[1..]),
        _ => ("", mantissa),
    };

    let mut scale = 0i64;
    let mut digits = String::new();
    let mut saw_dot = false;
    for byte in mantissa.bytes() {
        match byte {
            b'0'..=b'9' => {
                digits.push(char::from(byte));
                if saw_dot {
                    scale += 1;
                }
            }
            b'.' if !saw_dot => saw_dot = true,
            _ => return None,
        }
    }
    if digits.is_empty() {
        return None;
    }

    let decimal_point = i64::try_from(digits.len()).ok()? - scale + i64::from(exponent);
    let mut output = String::new();
    output.push_str(sign);
    if decimal_point <= 0 {
        output.push_str("0.");
        output.extend(std::iter::repeat('0').take(decimal_point.unsigned_abs() as usize));
        output.push_str(&digits);
    } else if usize::try_from(decimal_point).ok()? >= digits.len() {
        output.push_str(&digits);
        output.extend(
            std::iter::repeat('0').take(usize::try_from(decimal_point).ok()? - digits.len()),
        );
    } else {
        let split = usize::try_from(decimal_point).ok()?;
        output.push_str(&digits[..split]);
        output.push('.');
        output.push_str(&digits[split..]);
    }
    Some(output)
}

fn call_clamp(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("clamp", args, 3, span)?;
    let value = &args[0];
    let min = &args[1];
    let max = &args[2];

    if matches!(min, Value::Float(float) if float.is_nan()) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call("clamp()", "Argument #2 ($min) must not be NAN"),
        ));
    }
    if matches!(max, Value::Float(float) if float.is_nan()) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call("clamp()", "Argument #3 ($max) must not be NAN"),
        ));
    }
    if php_value_compare(min, max, Comparison::Gt, span)? {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "clamp()",
                "Argument #2 ($min) must be smaller than or equal to argument #3 ($max)",
            ),
        ));
    }
    if matches!(value, Value::Null) && !matches!(min, Value::Null) {
        return Ok(min.clone());
    }
    if matches!(value, Value::Float(float) if float.is_nan()) {
        return Ok(value.clone());
    }
    if php_value_compare(value, min, Comparison::Lt, span)? {
        return Ok(min.clone());
    }
    if php_value_compare(value, max, Comparison::Gt, span)? {
        return Ok(max.clone());
    }
    Ok(value.clone())
}

fn php_value_compare(
    left: &Value,
    right: &Value,
    comparison: Comparison,
    span: Span,
) -> CompileResult<bool> {
    left.php_cmp_checked(right, comparison)
        .map_err(|error| runtime_error(span, error))
}

#[derive(Clone, Copy, Debug)]
enum MathIntOrFloat {
    Int(i64),
    Float(f64),
}

impl MathIntOrFloat {
    fn as_float(self) -> f64 {
        match self {
            Self::Int(value) => value as f64,
            Self::Float(value) => value,
        }
    }
}

fn php_math_int_or_float_argument(
    interpreter: &mut Interpreter,
    function: &'static str,
    parameter_type: &'static str,
    value: &Value,
    span: Span,
) -> CompileResult<MathIntOrFloat> {
    match value {
        Value::Null => {
            interpreter.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                format!(
                    "{function}: Passing null to parameter #1 ($num) of type {parameter_type} is deprecated"
                ),
                span,
            )?;
            Ok(MathIntOrFloat::Int(0))
        }
        Value::Bool(value) => Ok(MathIntOrFloat::Int(i64::from(u8::from(*value)))),
        Value::Int(value) => Ok(MathIntOrFloat::Int(*value)),
        Value::Float(value) => Ok(MathIntOrFloat::Float(*value)),
        Value::String(value) => math_numeric_string_value(value)
            .ok_or_else(|| php_math_argument_type_error(function, parameter_type, "string", span)),
        Value::BinaryString(value) => std::str::from_utf8(value)
            .ok()
            .and_then(math_numeric_string_value)
            .ok_or_else(|| php_math_argument_type_error(function, parameter_type, "string", span)),
        Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
            Err(php_math_argument_type_error(
                function,
                parameter_type,
                php_type_error_given(value),
                span,
            ))
        }
    }
}

fn math_numeric_string_value(value: &str) -> Option<MathIntOrFloat> {
    match classify_php_numeric_string(value) {
        PhpNumericStringClassification::Integer(value) => Some(MathIntOrFloat::Int(value)),
        PhpNumericStringClassification::Float(value) => Some(MathIntOrFloat::Float(value)),
        PhpNumericStringClassification::LeadingNumeric
        | PhpNumericStringClassification::NonNumeric => None,
    }
}

impl Interpreter {
    fn call_number_format(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "number_format()",
                    ArityExpectation::Between { min: 1, max: 4 },
                    args.len(),
                ),
            ));
        }

        let number = self.php_number_format_argument(&args[0], span)?;
        let decimals = match args.get(1) {
            Some(value) => {
                php_internal_int_argument("number_format()", 2, "decimals", value, span)?
            }
            None => 0,
        };
        let decimal_separator = match args.get(2) {
            Some(Value::Null) | None => ".".to_string(),
            Some(value) => {
                string_builtin_argument("number_format()", "decimal_separator", value, span)?
            }
        };
        let thousands_separator = match args.get(3) {
            Some(Value::Null) | None => ",".to_string(),
            Some(value) => {
                string_builtin_argument("number_format()", "thousands_separator", value, span)?
            }
        };

        Ok(Value::String(format_number_format_value(
            number,
            decimals,
            &decimal_separator,
            &thousands_separator,
        )))
    }

    fn php_number_format_argument(
        &mut self,
        value: &Value,
        span: Span,
    ) -> CompileResult<NumberFormatValue> {
        match value {
            Value::Null => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    "number_format(): Passing null to parameter #1 ($num) of type float is deprecated",
                    span,
                )?;
                Ok(NumberFormatValue::Integer(0))
            }
            Value::Bool(value) => Ok(NumberFormatValue::Integer(i64::from(u8::from(*value)))),
            Value::Int(value) => Ok(NumberFormatValue::Integer(*value)),
            Value::Float(value) if value.is_finite() => Ok(NumberFormatValue::Float(*value)),
            Value::Float(_) => Err(php_math_argument_type_error(
                "number_format()",
                "float",
                "float",
                span,
            )),
            Value::String(value) => parse_number_format_integer_string(value)
                .map(NumberFormatValue::Integer)
                .or_else(|| parse_number_format_float_string(value).map(NumberFormatValue::Float))
                .ok_or_else(|| {
                    php_math_argument_type_error("number_format()", "float", "string", span)
                }),
            Value::BinaryString(value) => std::str::from_utf8(value)
                .ok()
                .and_then(|value| {
                    parse_number_format_integer_string(value)
                        .map(NumberFormatValue::Integer)
                        .or_else(|| {
                            parse_number_format_float_string(value).map(NumberFormatValue::Float)
                        })
                })
                .ok_or_else(|| {
                    php_math_argument_type_error("number_format()", "float", "string", span)
                }),
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
                Err(php_math_argument_type_error(
                    "number_format()",
                    "float",
                    php_type_error_given(value),
                    span,
                ))
            }
        }
    }

    fn call_php_unary_float_math(
        &mut self,
        arity_name: &'static str,
        function: &'static str,
        args: &[Value],
        operation: fn(f64) -> f64,
        span: Span,
    ) -> CompileResult<Value> {
        self.call_php_unary_float_math_with_param_type(
            arity_name, function, "float", args, operation, span,
        )
    }

    fn call_php_unary_float_math_with_param_type(
        &mut self,
        arity_name: &'static str,
        function: &'static str,
        parameter_type: &'static str,
        args: &[Value],
        operation: fn(f64) -> f64,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(arity_name, args, 1, span)?;
        let number = self.php_math_float_argument(function, parameter_type, &args[0], span)?;
        Ok(Value::Float(operation(number)))
    }

    fn call_php_binary_float_math(
        &mut self,
        arity_name: &'static str,
        function: &'static str,
        args: &[Value],
        operation: fn(f64, f64) -> f64,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(arity_name, args, 2, span)?;
        let left = self.php_math_float_argument(function, "float", &args[0], span)?;
        let right = self.php_math_float_argument(function, "float", &args[1], span)?;
        Ok(Value::Float(operation(left, right)))
    }

    fn call_log(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "log()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }

        let number = self.php_math_float_argument("log()", "float", &args[0], span)?;
        let result = match args.get(1) {
            Some(base_value) => {
                let base = self.php_math_float_argument("log()", "float", base_value, span)?;
                if base <= 0.0 || base.is_nan() {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "log()",
                            "Argument #2 ($base) must be greater than 0",
                        ),
                    ));
                }
                number.log(base)
            }
            None => number.ln(),
        };

        Ok(Value::Float(result))
    }

    fn call_php_float_predicate(
        &mut self,
        arity_name: &'static str,
        function: &'static str,
        args: &[Value],
        predicate: fn(f64) -> bool,
        span: Span,
    ) -> CompileResult<Value> {
        expect_arity(arity_name, args, 1, span)?;
        let number = self.php_math_float_argument(function, "float", &args[0], span)?;
        Ok(Value::Bool(predicate(number)))
    }

    fn php_math_float_argument(
        &mut self,
        function: &'static str,
        parameter_type: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<f64> {
        match value {
            Value::Null => {
                self.emit_display_diagnostic(
                    "Deprecated",
                    PHP_E_DEPRECATED,
                    format!(
                        "{function}: Passing null to parameter #1 ($num) of type {parameter_type} is deprecated"
                    ),
                    span,
                )?;
                Ok(0.0)
            }
            Value::Bool(value) => Ok(f64::from(u8::from(*value))),
            Value::Int(value) => Ok(*value as f64),
            Value::Float(value) => Ok(*value),
            Value::String(value) => math_numeric_string_value(value)
                .map(MathIntOrFloat::as_float)
                .ok_or_else(|| {
                    php_math_argument_type_error(function, parameter_type, "string", span)
                }),
            Value::BinaryString(value) => std::str::from_utf8(value)
                .ok()
                .and_then(math_numeric_string_value)
                .map(MathIntOrFloat::as_float)
                .ok_or_else(|| {
                    php_math_argument_type_error(function, parameter_type, "string", span)
                }),
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => {
                Err(php_math_argument_type_error(
                    function,
                    parameter_type,
                    php_type_error_given(value),
                    span,
                ))
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum NumberFormatValue {
    Integer(i64),
    Float(f64),
}

fn format_number_format_value(
    number: NumberFormatValue,
    decimals: i64,
    decimal_separator: &str,
    thousands_separator: &str,
) -> String {
    match number {
        NumberFormatValue::Integer(number) => {
            format_number_format_integer(number, decimals, decimal_separator, thousands_separator)
        }
        NumberFormatValue::Float(number) => {
            format_number_format_float(number, decimals, decimal_separator, thousands_separator)
        }
    }
}

fn format_number_format_integer(
    number: i64,
    decimals: i64,
    decimal_separator: &str,
    thousands_separator: &str,
) -> String {
    let decimals = decimals.clamp(i32::MIN as i64, 100);
    let mut abs = u128::from(number.unsigned_abs());
    if decimals < 0 {
        abs = round_number_format_integer_abs(abs, decimals.saturating_neg() as u32);
    }

    let negative = number < 0 && abs != 0;
    let integer = number_format_group_integer(&abs.to_string(), thousands_separator);
    let sign = if negative { "-" } else { "" };
    if decimals <= 0 {
        return format!("{sign}{integer}");
    }

    format!(
        "{sign}{integer}{decimal_separator}{fraction:0width$}",
        fraction = 0,
        width = decimals as usize
    )
}

fn round_number_format_integer_abs(number: u128, places: u32) -> u128 {
    if number == 0 {
        return 0;
    }

    let digits = number_format_decimal_digit_count(number);
    if places > digits {
        return 0;
    }

    let Some(scale) = 10_u128.checked_pow(places) else {
        return 0;
    };
    let quotient = number / scale;
    let remainder = number % scale;
    let rounded = quotient + u128::from(remainder >= (scale + 1) / 2);
    rounded.saturating_mul(scale)
}

fn number_format_decimal_digit_count(mut number: u128) -> u32 {
    let mut digits = 1;
    while number >= 10 {
        number /= 10;
        digits += 1;
    }
    digits
}

fn format_number_format_float(
    number: f64,
    decimals: i64,
    decimal_separator: &str,
    thousands_separator: &str,
) -> String {
    let decimals = decimals.clamp(i32::MIN as i64, 100) as i32;
    let abs = number.abs();
    let integer_like_abs = abs.trunc() as u128;
    let signed_long_abs_limit = if number.is_sign_negative() {
        (i64::MAX as u128) + 1
    } else {
        i64::MAX as u128
    };
    if decimals < 0 && abs >= 9_007_199_254_740_992.0 && integer_like_abs <= signed_long_abs_limit {
        let abs =
            round_number_format_integer_abs(integer_like_abs, decimals.saturating_neg() as u32);
        let negative = number.is_sign_negative() && abs != 0;
        let integer = number_format_group_integer(&abs.to_string(), thousands_separator);
        let sign = if negative { "-" } else { "" };
        return format!("{sign}{integer}");
    }

    let rounded = round_number_format_value(number, decimals);
    let negative = rounded.is_sign_negative() && rounded != 0.0;
    let abs = rounded.abs();
    let integer = abs.trunc() as u128;
    let integer = number_format_group_integer(&integer.to_string(), thousands_separator);

    let sign = if negative { "-" } else { "" };
    if decimals <= 0 {
        return format!("{sign}{integer}");
    }

    let scale = 10_f64.powi(decimals);
    let fraction = ((abs - abs.trunc()) * scale).round() as u128;
    format!(
        "{sign}{integer}{decimal_separator}{fraction:0width$}",
        width = decimals as usize
    )
}

fn parse_number_format_integer_string(value: &str) -> Option<i64> {
    let value = value.trim_matches(|character: char| character.is_ascii_whitespace());
    let (negative, digits) = match value.as_bytes().first().copied() {
        Some(b'-') => (true, &value[1..]),
        Some(b'+') => (false, &value[1..]),
        Some(_) => (false, value),
        None => return None,
    };
    if digits.is_empty() || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }

    let magnitude = digits.parse::<u128>().ok()?;
    if negative {
        if magnitude == (i64::MAX as u128) + 1 {
            Some(i64::MIN)
        } else {
            i64::try_from(magnitude).ok().map(|value| -value)
        }
    } else {
        i64::try_from(magnitude).ok()
    }
}

fn parse_number_format_float_string(value: &str) -> Option<f64> {
    let value = value.trim_matches(|character: char| character.is_ascii_whitespace());
    if value.is_empty() {
        return None;
    }

    let parsed = value.parse::<f64>().ok()?;
    parsed.is_finite().then_some(parsed)
}

fn round_number_format_value(number: f64, decimals: i32) -> f64 {
    if decimals >= 0 {
        let scale = 10_f64.powi(decimals);
        if !scale.is_finite() {
            return 0.0;
        }
        (number * scale).round() / scale
    } else {
        let scale = 10_f64.powi(decimals.saturating_neg());
        if !scale.is_finite() {
            return 0.0;
        }
        (number / scale).round() * scale
    }
}

fn number_format_group_integer(digits: &str, separator: &str) -> String {
    if digits.len() <= 3 || separator.is_empty() {
        return digits.to_string();
    }

    let first_group_len = match digits.len() % 3 {
        0 => 3,
        len => len,
    };
    let mut output = String::new();
    output.push_str(&digits[..first_group_len]);
    let mut index = first_group_len;
    while index < digits.len() {
        output.push_str(separator);
        output.push_str(&digits[index..index + 3]);
        index += 3;
    }
    output
}

fn php_math_argument_type_error(
    function: &str,
    parameter_type: &str,
    given: impl Into<String>,
    span: Span,
) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(
            function,
            format!(
                "Argument #1 ($num) must be of type {parameter_type}, {} given",
                given.into()
            ),
        ),
    )
}

fn call_pow(interpreter: &mut Interpreter, args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("pow", args, 2, span)?;
    php_pow_result(interpreter, &args[0], &args[1], span)
}

fn php_pow_result(
    interpreter: &mut Interpreter,
    base_value: &Value,
    exponent_value: &Value,
    span: Span,
) -> CompileResult<Value> {
    let base = pow_number_arg(base_value)
        .ok_or_else(|| pow_unsupported_operand_types(base_value, exponent_value, span))?;
    let exponent = pow_number_arg(exponent_value)
        .ok_or_else(|| pow_unsupported_operand_types(base_value, exponent_value, span))?;

    let base_float = base.as_f64();
    let exponent_float = exponent.as_f64();
    if base_float == 0.0 && exponent_float < 0.0 {
        interpreter.emit_display_diagnostic(
            "Deprecated",
            PHP_E_DEPRECATED,
            "Power of base 0 and negative exponent is deprecated",
            span,
        )?;
    }

    match (base.as_i64(), exponent.as_i64()) {
        (Some(base), Some(exponent)) => Ok(pow_integral_result(base, exponent)),
        _ => Ok(Value::Float(base_float.powf(exponent_float))),
    }
}

#[derive(Clone, Copy, Debug)]
struct PowNumber(MathIntOrFloat);

impl PowNumber {
    fn as_f64(self) -> f64 {
        match self.0 {
            MathIntOrFloat::Int(value) => value as f64,
            MathIntOrFloat::Float(value) => value,
        }
    }

    fn as_i64(self) -> Option<i64> {
        match self.0 {
            MathIntOrFloat::Int(value) => Some(value),
            MathIntOrFloat::Float(_) => None,
        }
    }
}

fn pow_number_arg(value: &Value) -> Option<PowNumber> {
    match value {
        Value::Null => Some(PowNumber(MathIntOrFloat::Int(0))),
        Value::Bool(value) => Some(PowNumber(MathIntOrFloat::Int(i64::from(u8::from(*value))))),
        Value::Int(value) => Some(PowNumber(MathIntOrFloat::Int(*value))),
        Value::Float(value) => Some(PowNumber(MathIntOrFloat::Float(*value))),
        Value::String(value) => math_numeric_string_value(value).map(PowNumber),
        Value::BinaryString(value) => std::str::from_utf8(value)
            .ok()
            .and_then(math_numeric_string_value)
            .map(PowNumber),
        Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => None,
    }
}

fn pow_integral_result(base: i64, exponent: i64) -> Value {
    if exponent >= 0 {
        if let Ok(exponent) = u32::try_from(exponent) {
            if let Some(value) = base.checked_pow(exponent) {
                return Value::Int(value);
            }
        }

        if matches!(base, -1 | 0 | 1) {
            return Value::Int(match base {
                -1 if exponent % 2 != 0 => -1,
                0 if exponent != 0 => 0,
                _ => 1,
            });
        }
    }

    Value::Float(pow_integral_float_result(base, exponent))
}

fn pow_integral_float_result(base: i64, exponent: i64) -> f64 {
    let magnitude = (base as f64).abs().powf(exponent as f64);
    if base < 0 && exponent % 2 != 0 {
        -magnitude
    } else {
        magnitude
    }
}

fn pow_unsupported_operand_types(left: &Value, right: &Value, span: Span) -> Diagnostic {
    Diagnostic::new(
        Phase::Runtime,
        span.line,
        span.column,
        format!(
            "Unsupported operand types: {} ** {}",
            php_type_error_given(left),
            php_type_error_given(right)
        ),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MinMaxOperation {
    Min,
    Max,
}

fn call_min_max(
    callable: &'static str,
    operation: MinMaxOperation,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    let values = match args {
        [Value::Array(array)] => {
            if array.is_empty() {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        callable,
                        "empty array argument forms are not implemented in the current subset",
                    ),
                ));
            }
            array
                .entries()
                .iter()
                .map(ArrayEntry::value_cloned)
                .collect::<Vec<_>>()
        }
        [_] => {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(callable, ArityExpectation::AtLeast(2), args.len()),
            ));
        }
        [] => {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(callable, ArityExpectation::AtLeast(1), args.len()),
            ));
        }
        _ => args.to_vec(),
    };

    let mut selected = values
        .first()
        .cloned()
        .expect("min/max input has at least one value after validation");

    for value in values.iter().skip(1) {
        let prefer_candidate = match operation {
            MinMaxOperation::Min => min_max_value_is_less(value, &selected, span)?,
            MinMaxOperation::Max => min_max_value_is_greater(value, &selected, span)?,
        };
        if prefer_candidate {
            selected = value.clone();
        }
    }

    Ok(selected)
}

fn min_max_value_is_less(left: &Value, right: &Value, span: Span) -> CompileResult<bool> {
    min_max_compare_values(left, right, span).map(|ordering| ordering == Ordering::Less)
}

fn min_max_value_is_greater(left: &Value, right: &Value, span: Span) -> CompileResult<bool> {
    min_max_compare_values(left, right, span).map(|ordering| ordering == Ordering::Greater)
}

fn min_max_compare_values(left: &Value, right: &Value, span: Span) -> CompileResult<Ordering> {
    match (left, right) {
        (Value::Array(_), Value::Array(_)) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "min()/max()",
                "array-to-array ordering is not implemented in the current subset",
            ),
        )),
        (Value::Array(_), _) => Ok(Ordering::Greater),
        (_, Value::Array(_)) => Ok(Ordering::Less),
        _ => {
            if left
                .php_cmp_checked(right, Comparison::Lt)
                .map_err(|error| runtime_error(span, error))?
            {
                Ok(Ordering::Less)
            } else if left
                .php_cmp_checked(right, Comparison::Gt)
                .map_err(|error| runtime_error(span, error))?
            {
                Ok(Ordering::Greater)
            } else {
                Ok(Ordering::Equal)
            }
        }
    }
}

#[derive(Clone, Copy)]
enum RandomRangeOrder {
    SwapInverted,
    RejectInverted,
}

fn call_rand(
    function: &str,
    range_order: RandomRangeOrder,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    match args.len() {
        0 => return Ok(Value::Int(123456789)),
        2 => {}
        actual => {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    function.to_string(),
                    ArityExpectation::Between { min: 0, max: 2 },
                    actual,
                ),
            ));
        }
    }

    let mut min = php_internal_int_argument(function, 1, "min", &args[0], span)?;
    let mut max = php_internal_int_argument(function, 2, "max", &args[1], span)?;
    if min > max {
        match range_order {
            RandomRangeOrder::SwapInverted => std::mem::swap(&mut min, &mut max),
            RandomRangeOrder::RejectInverted => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "Argument #2 ($max) must be greater than or equal to argument #1 ($min)",
                    ),
                ));
            }
        }
    }

    Ok(Value::Int(deterministic_random_int_inclusive(min, max)))
}

fn call_srand_like(function: &str, args: &[Value], span: Span) -> CompileResult<Value> {
    if args.len() > 2 {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                function.to_string(),
                ArityExpectation::Between { min: 0, max: 2 },
                args.len(),
            ),
        ));
    }
    if let Some(seed) = args.first() {
        let _ = php_internal_nullable_int_argument(function, 1, "seed", seed, span)?;
    }
    if let Some(mode) = args.get(1) {
        let _ = php_internal_int_argument(function, 2, "mode", mode, span)?;
    }
    Ok(Value::Null)
}

fn call_random_int(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("random_int", args, 2, span)?;
    let min = php_internal_int_argument("random_int()", 1, "min", &args[0], span)?;
    let max = php_internal_int_argument("random_int()", 2, "max", &args[1], span)?;
    if min > max {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "random_int()",
                "Argument #1 ($min) must be less than or equal to argument #2 ($max)",
            ),
        ));
    }
    Ok(Value::Int(deterministic_random_int_inclusive(min, max)))
}

fn call_random_bytes(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("random_bytes", args, 1, span)?;
    let length = php_internal_int_argument("random_bytes()", 1, "length", &args[0], span)?;
    if length <= 0 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "random_bytes()",
                "Argument #1 ($length) must be greater than 0",
            ),
        ));
    }
    let length = usize::try_from(length).map_err(|_| {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "random_bytes()",
                "Argument #1 ($length) is too large for the current subset",
            ),
        )
    })?;
    let bytes: Vec<u8> = (0..length).map(|index| b'A' + (index % 26) as u8).collect();
    let value = String::from_utf8(bytes).expect("deterministic random bytes are ASCII");
    Ok(Value::String(value))
}

fn deterministic_random_int_inclusive(min: i64, max: i64) -> i64 {
    let span = i128::from(max) - i128::from(min);
    (i128::from(min) + span / 2) as i64
}

fn call_uniqid(args: &[Value], span: Span) -> CompileResult<Value> {
    if args.len() > 2 {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "uniqid()",
                ArityExpectation::Between { min: 0, max: 2 },
                args.len(),
            ),
        ));
    }

    let prefix = match args.first() {
        Some(value) => string_builtin_argument("uniqid()", "prefix", value, span)?,
        None => String::new(),
    };

    let more_entropy = match args.get(1) {
        Some(Value::Bool(value)) => *value,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "uniqid()",
                    format!(
                        "more_entropy argument must be bool in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => false,
    };

    let mut value = format!("{prefix}0000000000000");
    if more_entropy {
        value.push_str(".000000000");
    }
    Ok(Value::String(value))
}

