impl Interpreter {
    fn call_hash(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash()",
                    ArityExpectation::Between { min: 2, max: 4 },
                    args.len(),
                ),
            ));
        }

        let algorithm = string_builtin_argument("hash()", "algo", &args[0], span)?;
        let Some(algorithm) = php_hash_algorithm(&algorithm) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "hash()",
                    "Argument #1 ($algo) must be a valid hashing algorithm",
                ),
            ));
        };
        let data = string_compare_argument_bytes("hash()", "data", &args[1], span)?;
        let raw_output = hash_raw_output_argument(args.get(2), span)?;
        let options = self.hash_options_argument("hash()", 4, algorithm, args.get(3), span)?;

        let digest = php_hash_digest_bytes_with_options(algorithm, &data, &options);
        if raw_output {
            Ok(Value::BinaryString(digest))
        } else {
            Ok(Value::String(hex_bytes(&digest)))
        }
    }
}

fn call_hash_algos(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("hash_algos", args, 0, span)?;
    let mut algorithms = PhpArray::new();
    for algorithm in PHP_HASH_ALGORITHM_NAMES {
        algorithms
            .append(Value::String((*algorithm).to_string()))
            .map_err(|error| runtime_error(span, error))?;
    }
    Ok(Value::Array(algorithms))
}

fn call_hash_hmac_algos(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("hash_hmac_algos", args, 0, span)?;
    let mut algorithms = PhpArray::new();
    for algorithm in PHP_HASH_HMAC_ALGORITHM_NAMES {
        algorithms
            .append(Value::String((*algorithm).to_string()))
            .map_err(|error| runtime_error(span, error))?;
    }
    Ok(Value::Array(algorithms))
}

fn call_hash_init(
    interpreter: &mut Interpreter,
    args: &[Value],
    span: Span,
) -> CompileResult<Value> {
    if !(1..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "hash_init()",
                ArityExpectation::Between { min: 1, max: 4 },
                args.len(),
            ),
        ));
    }

    let algorithm = string_builtin_argument("hash_init()", "algo", &args[0], span)?;
    if !is_php_hash_algorithm_name(&algorithm) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "hash_init()",
                "Argument #1 ($algo) must be a valid hashing algorithm",
            ),
        ));
    }

    let flags = match args.get(1) {
        Some(value) => php_internal_int_argument("hash_init()", 2, "flags", value, span)?,
        None => 0,
    };
    let hmac_requested = flags & PHP_HASH_HMAC != 0;

    let key = match args.get(2) {
        Some(Value::Null) => {
            interpreter.emit_display_diagnostic(
                "Deprecated",
                PHP_E_DEPRECATED,
                "hash_init(): Passing null to parameter #3 ($key) of type string is deprecated",
                span,
            )?;
            Vec::new()
        }
        Some(value) => string_compare_argument_bytes("hash_init()", "key", value, span)?,
        None => Vec::new(),
    };

    if hmac_requested {
        if !is_php_hash_hmac_cryptographic_algorithm_name(&algorithm) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "hash_init()",
                    "Argument #1 ($algo) must be a cryptographic hashing algorithm if HMAC is requested",
                ),
            ));
        }
        if key.is_empty() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "hash_init()",
                    "Argument #3 ($key) must not be empty when HMAC is requested",
                ),
            ));
        }
    }

    let Some(algorithm_kind) = php_hash_algorithm(&algorithm) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "hash_init()",
                format!(
                    "algorithm {} is not implemented in the current hash context subset",
                    algorithm.to_ascii_lowercase()
                ),
            ),
        ));
    };
    if hmac_requested && php_hash_hmac_block_size(algorithm_kind).is_none() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "hash_init()",
                format!(
                    "algorithm {} is not implemented in the current HMAC HashContext subset",
                    algorithm.to_ascii_lowercase()
                ),
            ),
        ));
    }
    let options = if hmac_requested {
        validate_hash_options_argument("hash_init()", 4, args.get(3), span)?;
        HashComputationOptions::default()
    } else {
        interpreter.hash_options_argument("hash_init()", 4, algorithm_kind, args.get(3), span)?
    };

    let state = BoundedHashContextState {
        algorithm: algorithm_kind,
        hmac_key: hmac_requested.then_some(key),
        options,
        data: Vec::new(),
        finalized: false,
    };
    interpreter
        .create_hash_context_object(state, span)
        .map(Value::Object)
}

impl Interpreter {
    fn create_hash_context_object(
        &mut self,
        state: BoundedHashContextState,
        span: Span,
    ) -> CompileResult<PhpObject> {
        let class_id = self
            .classes
            .lookup_class_id("HashContext")
            .ok_or_else(|| runtime_error(span, RuntimeError::undefined_class("HashContext")))?;
        let object_id = self.allocate_object_id();
        let inherited_properties = self.inherited_instance_properties(class_id);
        let mut ancestor_class_names = self.inherited_class_names(class_id);
        ancestor_class_names.extend(self.class_alias_names(class_id));
        let interface_names = self.class_implements_interface_names(class_id);
        let class = self
            .classes
            .get(class_id)
            .expect("HashContext class id should resolve");
        let object = PhpObject::from_class_with_relationship_metadata_with_id(
            class,
            &inherited_properties,
            ancestor_class_names,
            interface_names,
            object_id,
        );
        self.apply_instance_property_defaults(&object, class_id, span)?;
        self.hash_contexts.insert(object.id(), state);
        self.track_allocated_object(&object);
        Ok(object)
    }

    fn hash_context_object_id(
        &self,
        function: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<i64> {
        let Value::Object(object) = value else {
            return Err(hash_context_invalid_error(function, span));
        };
        if !object.is_instance_of_class_name("HashContext") {
            return Err(hash_context_invalid_error(function, span));
        }
        let Some(state) = self.hash_contexts.get(&object.id()) else {
            return Err(hash_context_invalid_error(function, span));
        };
        if state.finalized {
            return Err(hash_context_invalid_error(function, span));
        }
        Ok(object.id())
    }

    fn hash_context_state_mut(
        &mut self,
        function: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<&mut BoundedHashContextState> {
        let id = self.hash_context_object_id(function, value, span)?;
        self.hash_contexts
            .get_mut(&id)
            .ok_or_else(|| hash_context_invalid_error(function, span))
    }

    fn call_hash_update(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("hash_update", args, 2, span)?;
        let data = string_compare_argument_bytes("hash_update()", "data", &args[1], span)?;
        let state = self.hash_context_state_mut("hash_update()", &args[0], span)?;
        state.data.extend(data);
        Ok(Value::Bool(true))
    }

    fn call_hash_final(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(1..=2).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash_final()",
                    ArityExpectation::Between { min: 1, max: 2 },
                    args.len(),
                ),
            ));
        }
        let raw_output = match args.get(1) {
            Some(value) => php_internal_bool_argument("hash_final()", 2, "binary", value, span)?,
            None => false,
        };
        let state = self.hash_context_state_mut("hash_final()", &args[0], span)?;
        let digest = if let Some(key) = state.hmac_key.as_deref() {
            php_hash_hmac_digest_bytes("hash_final()", state.algorithm, &state.data, key, span)?
        } else {
            php_hash_digest_bytes_with_options(state.algorithm, &state.data, &state.options)
        };
        state.finalized = true;
        if raw_output {
            Ok(Value::BinaryString(digest))
        } else {
            Ok(Value::String(hex_bytes(&digest)))
        }
    }

    fn call_hash_copy(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        expect_arity("hash_copy", args, 1, span)?;
        let state = self
            .hash_contexts
            .get(&self.hash_context_object_id("hash_copy()", &args[0], span)?)
            .cloned()
            .ok_or_else(|| hash_context_invalid_error("hash_copy()", span))?;
        self.create_hash_context_object(state, span)
            .map(Value::Object)
    }

    fn call_hash_file(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash_file()",
                    ArityExpectation::Between { min: 2, max: 4 },
                    args.len(),
                ),
            ));
        }
        let algorithm = string_builtin_argument("hash_file()", "algo", &args[0], span)?;
        if !is_php_hash_algorithm_name(&algorithm) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "hash_file()",
                    "Argument #1 ($algo) must be a valid hashing algorithm",
                ),
            ));
        }
        let Some(algorithm_kind) = php_hash_algorithm(&algorithm) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "hash_file()",
                    format!(
                        "algorithm {} is not implemented in the current hash file subset",
                        algorithm.to_ascii_lowercase()
                    ),
                ),
            ));
        };
        let path = self.filesystem_filename_argument_for_parameter(
            "hash_file",
            2,
            "filename",
            &args[1],
            span,
        )?;
        let raw_output = match args.get(2) {
            Some(value) => php_internal_bool_argument("hash_file()", 3, "binary", value, span)?,
            None => false,
        };
        let options =
            self.hash_options_argument("hash_file()", 4, algorithm_kind, args.get(3), span)?;
        let Some(contents) = self.hash_file_contents("hash_file", &path, span)? else {
            return Ok(Value::Bool(false));
        };
        let digest = php_hash_digest_bytes_with_options(algorithm_kind, &contents, &options);
        if raw_output {
            Ok(Value::BinaryString(digest))
        } else {
            Ok(Value::String(hex_bytes(&digest)))
        }
    }

    fn call_hash_hmac_file(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(3..=4).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash_hmac_file()",
                    ArityExpectation::Between { min: 3, max: 4 },
                    args.len(),
                ),
            ));
        }
        let algorithm = string_builtin_argument("hash_hmac_file()", "algo", &args[0], span)?;
        let algorithm_kind =
            php_hash_hmac_supported_algorithm("hash_hmac_file()", &algorithm, span)?;
        let path = self.filesystem_filename_argument_for_parameter(
            "hash_hmac_file",
            2,
            "filename",
            &args[1],
            span,
        )?;
        let key = string_compare_argument_bytes("hash_hmac_file()", "key", &args[2], span)?;
        let raw_output = match args.get(3) {
            Some(value) => {
                php_internal_bool_argument("hash_hmac_file()", 4, "binary", value, span)?
            }
            None => false,
        };
        let Some(contents) = self.hash_file_contents("hash_hmac_file", &path, span)? else {
            return Ok(Value::Bool(false));
        };
        let digest =
            php_hash_hmac_digest_bytes("hash_hmac_file()", algorithm_kind, &contents, &key, span)?;
        if raw_output {
            Ok(Value::BinaryString(digest))
        } else {
            Ok(Value::String(hex_bytes(&digest)))
        }
    }

    fn call_hash_update_file(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash_update_file()",
                    ArityExpectation::Between { min: 2, max: 3 },
                    args.len(),
                ),
            ));
        }
        let context_id = self.hash_context_object_id("hash_update_file()", &args[0], span)?;
        let path = self.filesystem_filename_argument_for_parameter(
            "hash_update_file",
            2,
            "filename",
            &args[1],
            span,
        )?;
        validate_hash_options_argument("hash_update_file()", 3, args.get(2), span)?;
        let Some(contents) = self.hash_file_contents("hash_update_file", &path, span)? else {
            return Ok(Value::Bool(false));
        };
        let state = self
            .hash_contexts
            .get_mut(&context_id)
            .ok_or_else(|| hash_context_invalid_error("hash_update_file()", span))?;
        state.data.extend(contents);
        Ok(Value::Bool(true))
    }

    fn call_hash_update_stream(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "hash_update_stream()",
                    ArityExpectation::Between { min: 2, max: 3 },
                    args.len(),
                ),
            ));
        }
        let context_id = self.hash_context_object_id("hash_update_stream()", &args[0], span)?;
        let length = match args.get(2) {
            Some(value) => {
                let length =
                    php_internal_int_argument("hash_update_stream()", 3, "length", value, span)?;
                if length < -1 {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "hash_update_stream()",
                            "Argument #3 ($length) must be greater than or equal to -1",
                        ),
                    ));
                }
                (length >= 0).then_some(length as usize)
            }
            None => None,
        };
        let contents = self.stream_read_to_string("hash_update_stream", &args[1], length, span)?;
        let byte_count = contents.len();
        let state = self
            .hash_contexts
            .get_mut(&context_id)
            .ok_or_else(|| hash_context_invalid_error("hash_update_stream()", span))?;
        state.data.extend(contents.into_bytes());
        Ok(Value::Int(byte_count as i64))
    }

    fn hash_options_argument(
        &mut self,
        function: &'static str,
        position: usize,
        algorithm: PhpHashAlgorithm,
        value: Option<&Value>,
        span: Span,
    ) -> CompileResult<HashComputationOptions> {
        let Some(value) = value else {
            return Ok(HashComputationOptions::default());
        };
        let Value::Array(array) = value else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "Argument #{position} ($options) must be of type array, {} given",
                        php_type_error_given(value)
                    ),
                ),
            ));
        };
        if array.is_empty() {
            return Ok(HashComputationOptions::default());
        }
        if !php_hash_algorithm_supports_options(algorithm) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "non-empty options arrays are not implemented in the current hash subset",
                ),
            ));
        }

        let mut options = HashComputationOptions::default();
        if let Some(seed) = array.get("seed") {
            match seed {
                Value::Int(seed) => {
                    options.seed = *seed as u64;
                    options.seed_supplied = true;
                }
                _ => {
                    self.emit_display_diagnostic(
                        "Deprecated",
                        PHP_E_DEPRECATED,
                        format!(
                            "{function}: Passing a seed of a type other than int is deprecated because it {}",
                            php_hash_seed_deprecation_suffix(algorithm)
                        ),
                        span,
                    )?;
                    if php_hash_non_int_seed_maps_to_zero(algorithm) {
                        options.seed = 0;
                        options.seed_supplied = true;
                    }
                }
            }
        }

        if php_hash_algorithm_supports_secret(algorithm) {
            if let Some(secret) = array.get("secret") {
                if options.seed_supplied {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            function,
                            format!(
                                "{}: Only one of seed or secret is to be passed for initialization",
                                php_hash_algorithm_name(algorithm)
                            ),
                        ),
                    ));
                }
                let secret = self.hash_secret_option_bytes(function, secret, span)?;
                if secret.len() < PHP_XXH3_MIN_SECRET_LENGTH {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            function,
                            format!(
                                "{}: Secret length must be >= {PHP_XXH3_MIN_SECRET_LENGTH} bytes, {} bytes passed",
                                php_hash_algorithm_name(algorithm),
                                secret.len()
                            ),
                        ),
                    ));
                }
                options.secret = Some(secret);
            }
        }

        Ok(options)
    }

    fn hash_secret_option_bytes(
        &mut self,
        function: &'static str,
        value: &Value,
        span: Span,
    ) -> CompileResult<Vec<u8>> {
        match value {
            Value::String(value) => Ok(value.as_bytes().to_vec()),
            Value::BinaryString(value) => Ok(value.clone()),
            Value::Object(object) => {
                self.emit_hash_secret_type_deprecated(function, span)?;
                if let Some(value) =
                    self.object_to_string_with_magic(object.clone(), function, span)?
                {
                    Ok(value.into_bytes())
                } else {
                    Err(runtime_error(
                        span,
                        RuntimeError::invalid_string_conversion(format!(
                            "object of class {} cannot be converted to string",
                            object.class_name()
                        )),
                    ))
                }
            }
            other => {
                self.emit_hash_secret_type_deprecated(function, span)?;
                other
                    .try_echo_bytes()
                    .map_err(|error| runtime_error(span, error))
            }
        }
    }

    fn emit_hash_secret_type_deprecated(
        &mut self,
        function: &'static str,
        span: Span,
    ) -> CompileResult<()> {
        self.emit_display_diagnostic(
            "Deprecated",
            PHP_E_DEPRECATED,
            format!("{function}: Passing a secret of a type other than string is deprecated because it implicitly converts to a string, potentially hiding bugs"),
            span,
        )
    }

    fn hash_file_contents(
        &mut self,
        function: &str,
        path: &str,
        span: Span,
    ) -> CompileResult<Option<Vec<u8>>> {
        let callable = format!("{function}()");
        if !self.ensure_stream_wrapper_can_open_path(&callable, path, span)? {
            return Ok(None);
        }
        let filesystem_path = if let Some(file_url_path) = bounded_local_file_url_path(path) {
            file_url_path.map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(callable.clone(), message),
                )
            })?
        } else if path.contains("://") {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable,
                    "only local file:// URLs and local file paths are supported in the current stream-wrapper subset",
                ),
            ));
        } else {
            self.resolve_file_get_contents_path(path, false)
        };
        if !self.enforce_bounded_open_basedir(
            &format!("{function}()"),
            path,
            &filesystem_path,
            span,
        )? {
            return Ok(None);
        }
        match fs::read(&filesystem_path) {
            Ok(contents) => {
                self.cache_bounded_realpath_entry_for_local_path(&filesystem_path);
                Ok(Some(contents))
            }
            Err(error) => {
                self.emit_display_warning(
                    format!(
                        "{function}({path}): Failed to open stream: {}",
                        php_filesystem_open_error_message(&error)
                    ),
                    span,
                )?;
                Ok(None)
            }
        }
    }
}

fn call_crypt(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("crypt", args, 2, span)?;

    let _string = string_builtin_argument("crypt()", "string", &args[0], span)?;
    let salt = string_builtin_argument("crypt()", "salt", &args[1], span)?;
    if let Some(marker) = crypt_invalid_salt_fallback_marker(&salt) {
        return Ok(Value::String(marker.to_string()));
    }

    Err(runtime_error(
        span,
        RuntimeError::unsupported_call(
            "crypt()",
            "only invalid salt fallback markers are implemented in the current subset",
        ),
    ))
}

fn crypt_invalid_salt_fallback_marker(salt: &str) -> Option<&'static str> {
    if salt == "*0" {
        return Some("*1");
    }
    if salt.starts_with('*') || salt.as_bytes().contains(&0) {
        return Some("*0");
    }

    if let Some(rest) = salt.strip_prefix("$2") {
        return crypt_bcrypt_invalid_salt_fallback_marker(rest);
    }

    if salt.starts_with('$') && !crypt_has_supported_modular_prefix(salt) {
        return Some("*0");
    }

    if let Some(marker) = crypt_des_invalid_salt_fallback_marker(salt) {
        return Some(marker);
    }

    None
}

fn crypt_bcrypt_invalid_salt_fallback_marker(rest: &str) -> Option<&'static str> {
    let bytes = rest.as_bytes();
    let Some((&variant, after_variant)) = bytes.split_first() else {
        return Some("*0");
    };
    if !matches!(variant, b'a' | b'b' | b'x' | b'y') {
        return Some("*0");
    }
    if after_variant.first() != Some(&b'$') {
        return Some("*0");
    }
    if after_variant.len() < 4 {
        return Some("*0");
    }
    let cost_tens = after_variant[1];
    let cost_ones = after_variant[2];
    if after_variant[3] != b'$' || !cost_tens.is_ascii_digit() || !cost_ones.is_ascii_digit() {
        return Some("*0");
    }
    let cost = (cost_tens - b'0') * 10 + (cost_ones - b'0');
    if !(4..=31).contains(&cost) {
        return Some("*0");
    }
    let salt_body = &after_variant[4..];
    if salt_body.len() < 22 || salt_body[..22].contains(&b'$') {
        return Some("*0");
    }
    None
}

fn crypt_has_supported_modular_prefix(salt: &str) -> bool {
    salt.starts_with("$1$")
        || salt.starts_with("$5$")
        || salt.starts_with("$6$")
        || salt.starts_with("$2a$")
        || salt.starts_with("$2b$")
        || salt.starts_with("$2x$")
        || salt.starts_with("$2y$")
}

fn crypt_des_invalid_salt_fallback_marker(salt: &str) -> Option<&'static str> {
    let bytes = salt.as_bytes();
    if bytes.first() == Some(&b'_') {
        if bytes.len() < 9 || bytes[..9].iter().any(|byte| !is_crypt_salt64(*byte)) {
            return Some("*0");
        }
        return None;
    }

    if bytes.len() < 2 || bytes[..2].iter().any(|byte| !is_crypt_salt64(*byte)) {
        return Some("*0");
    }

    None
}

fn is_crypt_salt64(byte: u8) -> bool {
    matches!(byte, b'.' | b'/' | b'0'..=b'9' | b'A'..=b'Z' | b'a'..=b'z')
}

fn hash_raw_output_argument(value: Option<&Value>, span: Span) -> CompileResult<bool> {
    match value {
        Some(Value::Array(_)) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "hash()",
                "Argument #3 ($binary) must be of type bool, array given",
            ),
        )),
        Some(value) => Ok(value.is_truthy()),
        None => Ok(false),
    }
}

fn validate_hash_options_argument(
    function: &'static str,
    position: usize,
    value: Option<&Value>,
    span: Span,
) -> CompileResult<()> {
    match value {
        Some(Value::Array(array)) if array.is_empty() => Ok(()),
        Some(Value::Array(_)) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "non-empty options arrays are not implemented in the current hash subset",
            ),
        )),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "Argument #{position} ($options) must be of type array, {} given",
                    php_type_error_given(other)
                ),
            ),
        )),
        None => Ok(()),
    }
}

fn hash_context_invalid_error(function: &'static str, span: Span) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call(
            function,
            "Argument #1 ($context) must be a valid, non-finalized HashContext",
        ),
    )
}

fn hash_context_serialize_error_message(state: &BoundedHashContextState) -> Option<String> {
    if state.hmac_key.is_some() {
        return Some("HashContext with HASH_HMAC option cannot be serialized".to_string());
    }
    if state.finalized {
        return Some(format!(
            "HashContext for algorithm \"{}\" cannot be serialized",
            php_hash_algorithm_name(state.algorithm)
        ));
    }
    None
}

