fn is_php_hash_algorithm_name(name: &str) -> bool {
    let normalized = name.to_ascii_lowercase();
    PHP_HASH_ALGORITHM_NAMES
        .iter()
        .any(|algorithm| *algorithm == normalized)
        || matches!(normalized.as_str(), "sha512-224" | "sha512-256")
}

