fn bounded_timezone_object_parts(name: &str) -> Option<(i64, String)> {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return None;
    }
    let upper = trimmed.to_ascii_uppercase();
    if let Some(offset_token) = upper.strip_prefix("GMT") {
        if !offset_token.is_empty() {
            if let Some(offset) = parse_timezone_offset_token(offset_token) {
                return Some((1, format_timezone_offset_name(offset)));
            }
        }
    }
    match upper.as_str() {
        "A" | "B" | "C" | "D" | "E" | "F" | "G" | "H" | "I" | "K" | "L" | "M" | "N" | "O" | "P"
        | "Q" | "R" | "S" | "T" | "U" | "V" | "W" | "X" | "Y" | "Z" | "GMT" | "CET" | "CEST"
        | "EST" | "EDT" | "PST" | "PDT" => {
            return Some((2, upper));
        }
        "UTC" => return Some((3, "UTC".to_string())),
        _ => {}
    }
    if matches!(trimmed.as_bytes().first(), Some(b'+') | Some(b'-')) {
        if let Some(offset) = parse_timezone_offset_token(trimmed) {
            return Some((1, format_timezone_offset_name(offset)));
        }
    }
    bounded_timezone_from_name(trimmed).map(|timezone| (3, timezone.name))
}

fn normalized_datetimezone_serialization_state(
    timezone_type: i64,
    timezone_name: &str,
) -> Option<String> {
    if timezone_name.contains('\0') {
        return None;
    }
    let (expected_type, canonical_name) = bounded_timezone_object_parts(timezone_name)?;
    if timezone_type != expected_type {
        return None;
    }
    Some(canonical_name)
}

fn datetimezone_serialization_state(state: &PhpArray, span: Span) -> CompileResult<(i64, String)> {
    let timezone_type = match state.get_cloned("timezone_type") {
        Some(Value::Int(value)) => value,
        _ => return Err(datetimezone_invalid_serialization_error(span)),
    };
    let timezone_name = match state.get_cloned("timezone") {
        Some(Value::String(value)) => value,
        _ => return Err(datetimezone_invalid_serialization_error(span)),
    };
    let Some(canonical_name) =
        normalized_datetimezone_serialization_state(timezone_type, &timezone_name)
    else {
        return Err(datetimezone_invalid_serialization_error(span));
    };
    Ok((timezone_type, canonical_name))
}

fn datetimezone_serialization_state_array_from_properties<I>(
    properties: I,
    span: Span,
) -> CompileResult<PhpArray>
where
    I: IntoIterator<Item = (String, Value)>,
{
    let mut state = PhpArray::new();
    for (name, value) in properties {
        match name.as_str() {
            "timezone_type" | "timezone" => {
                state.insert(name, value);
            }
            _ => return Err(datetimezone_invalid_serialization_error(span)),
        }
    }
    let (timezone_type, timezone_name) = datetimezone_serialization_state(&state, span)?;
    let mut canonical = PhpArray::new();
    canonical.insert("timezone_type", Value::Int(timezone_type));
    canonical.insert("timezone", Value::String(timezone_name));
    Ok(canonical)
}

fn datetime_serialization_state_array_from_properties<I>(
    properties: I,
    span: Span,
) -> CompileResult<PhpArray>
where
    I: IntoIterator<Item = (String, Value)>,
{
    let mut state = PhpArray::new();
    for (name, value) in properties {
        match name.as_str() {
            "date" | "timezone_type" | "timezone" => {
                state.insert(name, value);
            }
            _ => return Err(datetime_invalid_serialization_error(span)),
        }
    }
    let _ = bounded_datetime_timestamp_from_state_array(&state, span)?;
    Ok(state)
}

fn datetimeimmutable_serialization_state_array_from_properties<I>(
    properties: I,
    span: Span,
) -> CompileResult<(PhpArray, Vec<(String, Value)>)>
where
    I: IntoIterator<Item = (String, Value)>,
{
    let mut state = PhpArray::new();
    let mut public_properties = Vec::new();
    for (name, value) in properties {
        match name.as_str() {
            "date" | "timezone_type" | "timezone" => {
                state.insert(name, value);
            }
            _ => public_properties.push((name, value)),
        }
    }
    map_datetime_invalid_serialization_to_datetimeimmutable(
        bounded_datetime_timestamp_from_state_array(&state, span),
        span,
    )?;
    Ok((state, public_properties))
}

fn bounded_dateinterval_state_from_state_array(
    state: &PhpArray,
    span: Span,
) -> CompileResult<BoundedDateIntervalState> {
    fn interval_int(state: &PhpArray, key: &str, span: Span) -> CompileResult<i64> {
        match state.get_cloned(key) {
            Some(Value::Int(value)) => Ok(value),
            _ => Err(dateinterval_malformed_error(
                span,
                "Invalid serialization data for DateInterval object".to_string(),
            )),
        }
    }

    fn interval_float(state: &PhpArray, key: &str, span: Span) -> CompileResult<f64> {
        match state.get_cloned(key) {
            Some(Value::Float(value)) => Ok(value),
            Some(Value::Int(value)) => Ok(value as f64),
            _ => Err(dateinterval_malformed_error(
                span,
                "Invalid serialization data for DateInterval object".to_string(),
            )),
        }
    }

    let total_days = match state.get_cloned("days") {
        Some(Value::Int(value)) => Some(value),
        Some(Value::Bool(false)) => None,
        _ => {
            return Err(dateinterval_malformed_error(
                span,
                "Invalid serialization data for DateInterval object".to_string(),
            ));
        }
    };
    let from_string = match state.get_cloned("from_string") {
        Some(Value::Bool(value)) => value,
        _ => {
            return Err(dateinterval_malformed_error(
                span,
                "Invalid serialization data for DateInterval object".to_string(),
            ));
        }
    };
    let date_string = match state.get_cloned("date_string") {
        Some(Value::String(value)) => Some(value),
        Some(Value::Null) | None => None,
        _ => {
            return Err(dateinterval_malformed_error(
                span,
                "Invalid serialization data for DateInterval object".to_string(),
            ));
        }
    };

    Ok(BoundedDateIntervalState {
        years: interval_int(state, "y", span)?,
        months: interval_int(state, "m", span)?,
        days: interval_int(state, "d", span)?,
        hours: interval_int(state, "h", span)?,
        minutes: interval_int(state, "i", span)?,
        seconds: interval_int(state, "s", span)?,
        fraction: interval_float(state, "f", span)?,
        invert: interval_int(state, "invert", span)?,
        total_days,
        from_string,
        date_string,
    })
}

fn dateperiod_state_to_array(state: &BoundedDatePeriodState) -> PhpArray {
    let mut array = PhpArray::new();
    array.insert("start", state.start.clone());
    array.insert("current", state.current.clone());
    array.insert("end", state.end.clone());
    array.insert("interval", Value::Object(state.interval.clone()));
    array.insert("recurrences", Value::Int(state.recurrences));
    array.insert("include_start_date", Value::Bool(state.include_start_date));
    array.insert("include_end_date", Value::Bool(state.include_end_date));
    array
}

fn dateperiod_state_from_object_properties(
    object: &PhpObject,
    span: Span,
) -> CompileResult<BoundedDatePeriodState> {
    let value = |name: &str| {
        object
            .read_public_property(name)
            .map_err(|_| dateperiod_invalid_serialization_error(span))
    };
    dateperiod_state_from_values(
        value("start")?,
        value("current")?,
        value("end")?,
        value("interval")?,
        value("recurrences")?,
        value("include_start_date")?,
        value("include_end_date")?,
        span,
    )
}

fn dateperiod_state_from_state_array_with_extras(
    state: &PhpArray,
    span: Span,
) -> CompileResult<(BoundedDatePeriodState, Vec<(String, Value)>)> {
    let mut core = PhpArray::new();
    let mut public_properties = Vec::new();
    for entry in state.entries() {
        let ArrayKey::String(name) = &entry.key else {
            return Err(dateperiod_invalid_serialization_error(span));
        };
        if dateperiod_core_property_name(name) {
            core.insert(name.clone(), entry.value_cloned());
        } else {
            public_properties.push((name.clone(), entry.value_cloned()));
        }
    }
    let state = dateperiod_state_from_state_array(&core, span)?;
    Ok((state, public_properties))
}

fn dateperiod_state_from_state_array(
    state: &PhpArray,
    span: Span,
) -> CompileResult<BoundedDatePeriodState> {
    let value = |name: &str| {
        state
            .get_cloned(name)
            .ok_or_else(|| dateperiod_invalid_serialization_error(span))
    };
    dateperiod_state_from_values(
        value("start")?,
        value("current")?,
        value("end")?,
        value("interval")?,
        value("recurrences")?,
        value("include_start_date")?,
        value("include_end_date")?,
        span,
    )
}

fn dateperiod_state_from_values(
    start: Value,
    current: Value,
    end: Value,
    interval: Value,
    recurrences: Value,
    include_start_date: Value,
    include_end_date: Value,
    span: Span,
) -> CompileResult<BoundedDatePeriodState> {
    let start = dateperiod_datetime_or_null_value(start, span)?;
    let current = dateperiod_datetime_or_null_value(current, span)?;
    let end = dateperiod_datetime_or_null_value(end, span)?;
    let interval = match interval {
        Value::Object(object) if object.is_instance_of_class_name("DateInterval") => object,
        _ => return Err(dateperiod_invalid_serialization_error(span)),
    };
    let recurrences = match recurrences {
        Value::Int(value) if value >= 0 => value,
        _ => return Err(dateperiod_invalid_serialization_error(span)),
    };
    let include_start_date = match include_start_date {
        Value::Bool(value) => value,
        _ => return Err(dateperiod_invalid_serialization_error(span)),
    };
    let include_end_date = match include_end_date {
        Value::Bool(value) => value,
        _ => return Err(dateperiod_invalid_serialization_error(span)),
    };
    Ok(BoundedDatePeriodState {
        start,
        current,
        end,
        interval,
        recurrences,
        include_start_date,
        include_end_date,
    })
}

fn dateperiod_datetime_or_null_value(value: Value, span: Span) -> CompileResult<Value> {
    match value {
        Value::Null => Ok(Value::Null),
        Value::Object(object) if dateperiod_is_datetime_interface_object(&object) => {
            Ok(Value::Object(object))
        }
        _ => Err(dateperiod_invalid_serialization_error(span)),
    }
}

fn dateperiod_is_datetime_interface_object(object: &PhpObject) -> bool {
    object.is_instance_of_class_name("DateTime")
        || object.is_instance_of_class_name("DateTimeImmutable")
}

fn dateperiod_core_property_name(name: &str) -> bool {
    matches!(
        name,
        "start"
            | "current"
            | "end"
            | "interval"
            | "recurrences"
            | "include_start_date"
            | "include_end_date"
    )
}

fn bounded_datetime_state_string(state: &PhpArray, key: &str, span: Span) -> CompileResult<String> {
    match state.get_cloned(key) {
        Some(Value::String(value)) => Ok(value),
        Some(_) | None => Err(datetime_invalid_serialization_error(span)),
    }
}

fn bounded_datetime_state_int(state: &PhpArray, key: &str, span: Span) -> CompileResult<i64> {
    match state.get_cloned(key) {
        Some(Value::Int(value)) => Ok(value),
        Some(_) | None => Err(datetime_invalid_serialization_error(span)),
    }
}

fn bounded_timezone_from_state_name(name: &str) -> Option<BoundedTimezone> {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some(offset) = parse_timezone_offset_token(trimmed) {
        return Some(BoundedTimezone {
            name: trimmed.to_string(),
            fixed_offset: Some(offset),
        });
    }
    bounded_timezone_from_name(trimmed)
}

fn bounded_timezone_from_state_array(
    state: &PhpArray,
    span: Span,
) -> CompileResult<BoundedTimezone> {
    let timezone_type = bounded_datetime_state_int(state, "timezone_type", span)?;
    if !matches!(timezone_type, 1..=3) {
        return Err(datetime_invalid_serialization_error(span));
    }
    let timezone_name = bounded_datetime_state_string(state, "timezone", span)?;
    let Some(canonical_name) =
        normalized_datetimezone_serialization_state(timezone_type, &timezone_name)
    else {
        return Err(datetime_invalid_serialization_error(span));
    };
    bounded_timezone_from_state_name(&canonical_name)
        .ok_or_else(|| datetime_invalid_serialization_error(span))
}

fn bounded_datetime_timestamp_from_state_array(state: &PhpArray, span: Span) -> CompileResult<i64> {
    bounded_datetime_state_from_state_array(state, span).map(|state| state.timestamp)
}

fn bounded_datetime_state_from_state_array(
    state: &PhpArray,
    span: Span,
) -> CompileResult<BoundedParsedDateTime> {
    let timezone = bounded_timezone_from_state_array(state, span)?;
    let date = bounded_datetime_state_string(state, "date", span)?;
    let (timestamp, microsecond) = parse_bounded_datetime_state_date(&date, &timezone)
        .ok_or_else(|| datetime_invalid_serialization_error(span))?;
    Ok(BoundedParsedDateTime {
        timestamp,
        microsecond,
        timezone,
    })
}

fn parse_bounded_datetime_state_date(date: &str, timezone: &BoundedTimezone) -> Option<(i64, i64)> {
    parse_bounded_datetime_with_microsecond(date, timezone)
}

fn bounded_datetime_timezone_hint(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> BoundedTimezone {
    let trimmed = input.trim();
    if parse_bounded_at_timestamp(trimmed).is_some() {
        return BoundedTimezone::numeric_fixed_offset(0);
    }
    if let Some(zone) = bounded_timezone_from_name(trimmed) {
        return zone;
    }
    if let Some((_, token)) = trimmed.rsplit_once(' ') {
        if let Some(zone) = bounded_timezone_from_name(token) {
            return zone;
        }
    }
    for suffix_len in [9_usize, 7, 6, 5] {
        if trimmed.len() > suffix_len {
            let suffix = &trimmed[trimmed.len() - suffix_len..];
            if matches!(suffix.as_bytes().first(), Some(b'+') | Some(b'-')) {
                if let Some(zone) = bounded_timezone_from_name(suffix) {
                    return zone;
                }
            }
        }
    }
    for suffix_len in [4_usize, 3] {
        if trimmed.len() > suffix_len {
            let suffix = &trimmed[trimmed.len() - suffix_len..];
            if suffix.chars().all(|ch| ch.is_ascii_alphabetic()) {
                if let Some(zone) = bounded_timezone_from_name(suffix) {
                    return zone;
                }
            }
        }
    }
    default_timezone.clone()
}

fn bounded_timezone_transition_entry(
    timestamp: i64,
    offset: i64,
    is_dst: bool,
    abbreviation: &str,
) -> PhpArray {
    let mut entry = PhpArray::new();
    entry.insert("ts", Value::Int(timestamp));
    entry.insert(
        "time",
        Value::String(format_bounded_date(
            "Y-m-d\\TH:i:sP",
            timestamp,
            &BoundedTimezone::utc(),
        )),
    );
    entry.insert("offset", Value::Int(offset));
    entry.insert("isdst", Value::Bool(is_dst));
    entry.insert("abbr", Value::String(abbreviation.to_string()));
    entry
}

fn bounded_timezone_transitions_array(name: &str, start: i64, end: i64) -> PhpArray {
    const EUROPE_LONDON_TRANSITIONS: &[(i64, i64, bool, &str)] = &[
        (-306_972_000, 3_600, true, "BST"),
        (-291_852_000, 0, false, "GMT"),
        (-276_732_000, 3_600, true, "BST"),
        (-257_983_200, 0, false, "GMT"),
        (-245_282_400, 3_600, true, "BST"),
        (-226_533_600, 0, false, "GMT"),
        (-213_228_000, 3_600, true, "BST"),
        (-195_084_000, 0, false, "GMT"),
        (-182_383_200, 3_600, true, "BST"),
        (-163_634_400, 0, false, "GMT"),
        (-150_933_600, 3_600, true, "BST"),
        (-132_184_800, 0, false, "GMT"),
        (-119_484_000, 3_600, true, "BST"),
        (-100_735_200, 0, false, "GMT"),
        (-88_034_400, 3_600, true, "BST"),
        (-68_680_800, 0, false, "GMT"),
        (-59_004_000, 3_600, true, "BST"),
        (-37_242_000, 3_600, true, "BST"),
    ];

    let mut array = PhpArray::new();
    let Some(timezone) = bounded_timezone_from_name(name) else {
        return array;
    };
    if timezone.name != "Europe/London" {
        let offset = timezone.offset_at_timestamp(start.max(0));
        let abbreviation = timezone.abbreviation(&bounded_datetime_parts(start.max(0), offset));
        array
            .append(Value::Array(bounded_timezone_transition_entry(
                start.max(0),
                offset,
                false,
                &abbreviation,
            )))
            .expect("bounded timezone transition append should not exhaust integer keys");
        return array;
    }
    for (timestamp, offset, is_dst, abbreviation) in EUROPE_LONDON_TRANSITIONS {
        if *timestamp < start || *timestamp > end {
            continue;
        }
        array
            .append(Value::Array(bounded_timezone_transition_entry(
                *timestamp,
                *offset,
                *is_dst,
                abbreviation,
            )))
            .expect("bounded timezone transition append should not exhaust integer keys");
    }
    array
}

