fn bounded_timezone_metadata_name(name: &str) -> Option<&'static str> {
    for (_, _, _, zone_id) in BOUNDED_TIMEZONE_ABBREVIATION_FIRST_ROWS {
        if let Some(zone_id) = zone_id {
            if *zone_id == name {
                return Some(*zone_id);
            }
        }
    }
    for zone_id in BOUNDED_ACST_TIMEZONE_IDS {
        if *zone_id == name {
            return Some(*zone_id);
        }
    }
    for (zone_id, _, _, _, _) in BOUNDED_TIMEZONE_LOCATIONS {
        if *zone_id == name {
            return Some(*zone_id);
        }
    }
    None
}

fn bounded_timezone_abbreviations_array() -> PhpArray {
    let mut array = PhpArray::new();
    for (abbr, dst, offset, zone_id) in BOUNDED_TIMEZONE_ABBREVIATION_FIRST_ROWS {
        let mut rows = PhpArray::new();
        if *abbr == "acst" {
            for zone_id in BOUNDED_ACST_TIMEZONE_IDS {
                append_bounded_timezone_abbreviation_row(&mut rows, false, 34_200, Some(zone_id));
            }
        } else {
            append_bounded_timezone_abbreviation_row(&mut rows, *dst, *offset, *zone_id);
        }
        array.insert(*abbr, Value::Array(rows));
    }
    array
}

fn append_bounded_timezone_abbreviation_row(
    rows: &mut PhpArray,
    dst: bool,
    offset: i64,
    zone_id: Option<&str>,
) {
    let mut row = PhpArray::new();
    row.insert("dst", Value::Bool(dst));
    row.insert("offset", Value::Int(offset));
    match zone_id {
        Some(zone_id) => row.insert("timezone_id", Value::String(zone_id.to_string())),
        None => row.insert("timezone_id", Value::Null),
    };
    rows.append(Value::Array(row))
        .expect("bounded timezone abbreviation row append should not exhaust integer keys");
}

fn bounded_timezone_location_array(
    country_code: &str,
    latitude: f64,
    longitude: f64,
    comments: &str,
) -> PhpArray {
    let mut array = PhpArray::new();
    array.insert("country_code", Value::String(country_code.to_string()));
    array.insert("latitude", Value::Float(latitude));
    array.insert("longitude", Value::Float(longitude));
    array.insert("comments", Value::String(comments.to_string()));
    array
}

fn bounded_timezone_location_value(name: &str, timezone_type: i64) -> Value {
    if timezone_type != 3 {
        return Value::Bool(false);
    }
    BOUNDED_TIMEZONE_LOCATIONS
        .iter()
        .find(|(zone_id, _, _, _, _)| *zone_id == name)
        .map(|(_, country_code, latitude, longitude, comments)| {
            Value::Array(bounded_timezone_location_array(
                country_code,
                *latitude,
                *longitude,
                comments,
            ))
        })
        .unwrap_or(Value::Bool(false))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SolarEventState {
    Normal,
    AlwaysBelow,
    AlwaysAbove,
}

#[derive(Debug, Clone, Copy)]
struct SolarEvent {
    state: SolarEventState,
    rise: i64,
    set: i64,
    transit: i64,
    rise_hour: f64,
    set_hour: f64,
}

fn insert_solar_pair(array: &mut PhpArray, rise_key: &str, set_key: &str, event: &SolarEvent) {
    match event.state {
        SolarEventState::AlwaysBelow => {
            array.insert(rise_key, Value::Bool(false));
            array.insert(set_key, Value::Bool(false));
        }
        SolarEventState::AlwaysAbove => {
            array.insert(rise_key, Value::Bool(true));
            array.insert(set_key, Value::Bool(true));
        }
        SolarEventState::Normal => {
            array.insert(rise_key, Value::Int(event.rise));
            array.insert(set_key, Value::Int(event.set));
        }
    }
}

fn bounded_solar_event(
    timestamp: i64,
    timezone: &BoundedTimezone,
    longitude: f64,
    latitude: f64,
    mut altitude: f64,
    upper_limb: bool,
) -> SolarEvent {
    let local_offset = timezone.offset_at_timestamp(timestamp);
    let local = bounded_datetime_parts(timestamp, local_offset);
    let utc_midnight = timestamp_from_local_parts(local.year, local.month, local.day, 0, 0, 0, 0);
    let local_noon = timestamp_from_local_parts(
        local.year,
        local.month,
        local.day,
        12,
        0,
        0,
        timezone.offset_for_local_date(local.year, local.month, local.day),
    );
    let days_since_j2000 = timestamp_to_j2000_days(utc_midnight) + 2.0 - longitude / 360.0;
    let sidereal_time = astro_revolution(astro_gmst0(days_since_j2000) + 180.0 + longitude);
    let (sun_right_ascension, sun_declination, solar_distance) =
        astro_sun_right_ascension_declination(days_since_j2000);
    let south_hour = 12.0 - astro_rev180(sidereal_time - sun_right_ascension) / 15.0;
    if upper_limb {
        altitude -= 0.2666 / solar_distance;
    }

    let cost = (sind(altitude) - sind(latitude) * sind(sun_declination))
        / (cosd(latitude) * cosd(sun_declination));
    let transit = (utc_midnight as f64 + south_hour * 3600.0) as i64;
    if cost >= 1.0 {
        return SolarEvent {
            state: SolarEventState::AlwaysBelow,
            rise: transit,
            set: transit,
            transit,
            rise_hour: south_hour,
            set_hour: south_hour,
        };
    }
    if cost <= -1.0 {
        return SolarEvent {
            state: SolarEventState::AlwaysAbove,
            rise: local_noon - 12 * 3600,
            set: local_noon + 12 * 3600,
            transit,
            rise_hour: south_hour - 12.0,
            set_hour: south_hour + 12.0,
        };
    }

    let diurnal_arc = acosd(cost) / 15.0;
    let rise_hour = south_hour - diurnal_arc;
    let set_hour = south_hour + diurnal_arc;
    SolarEvent {
        state: SolarEventState::Normal,
        rise: (utc_midnight as f64 + rise_hour * 3600.0) as i64,
        set: (utc_midnight as f64 + set_hour * 3600.0) as i64,
        transit,
        rise_hour,
        set_hour,
    }
}

fn timestamp_to_j2000_days(timestamp: i64) -> f64 {
    timestamp as f64 / 86_400.0 + 2_440_587.5 - 2_451_545.0
}

fn astro_gmst0(days_since_j2000: f64) -> f64 {
    astro_revolution((180.0 + 356.0470 + 282.9404) + (0.9856002585 + 4.70935E-5) * days_since_j2000)
}

fn astro_sun_position(days_since_j2000: f64) -> (f64, f64) {
    let mean_anomaly = astro_revolution(356.0470 + 0.9856002585 * days_since_j2000);
    let perihelion = 282.9404 + 4.70935E-5 * days_since_j2000;
    let eccentricity = 0.016709 - 1.151E-9 * days_since_j2000;
    let eccentric_anomaly = mean_anomaly
        + eccentricity * 180.0 / std::f64::consts::PI
            * sind(mean_anomaly)
            * (1.0 + eccentricity * cosd(mean_anomaly));
    let x = cosd(eccentric_anomaly) - eccentricity;
    let y = (1.0 - eccentricity * eccentricity).sqrt() * sind(eccentric_anomaly);
    let distance = (x * x + y * y).sqrt();
    let true_anomaly = atan2d(y, x);
    let mut longitude = true_anomaly + perihelion;
    if longitude >= 360.0 {
        longitude -= 360.0;
    }
    (longitude, distance)
}

fn astro_sun_right_ascension_declination(days_since_j2000: f64) -> (f64, f64, f64) {
    let (longitude, distance) = astro_sun_position(days_since_j2000);
    let x = distance * cosd(longitude);
    let mut y = distance * sind(longitude);
    let obliquity = 23.4393 - 3.563E-7 * days_since_j2000;
    let z = y * sind(obliquity);
    y *= cosd(obliquity);
    (atan2d(y, x), atan2d(z, (x * x + y * y).sqrt()), distance)
}

fn astro_revolution(value: f64) -> f64 {
    value - 360.0 * (value / 360.0).floor()
}

fn astro_rev180(value: f64) -> f64 {
    value - 360.0 * (value / 360.0 + 0.5).floor()
}

fn sind(degrees: f64) -> f64 {
    degrees.to_radians().sin()
}

fn cosd(degrees: f64) -> f64 {
    degrees.to_radians().cos()
}

fn atan2d(y: f64, x: f64) -> f64 {
    y.atan2(x).to_degrees()
}

fn acosd(value: f64) -> f64 {
    value.acos().to_degrees()
}

fn required_sun_float_arg(
    function: &str,
    value: &Value,
    label: &str,
    span: Span,
) -> CompileResult<f64> {
    match value {
        Value::Int(value) => Ok(*value as f64),
        Value::Float(value) => Ok(*value),
        Value::String(value) => value.parse::<f64>().map_err(|_| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!("{label} argument must be float-compatible in the current subset"),
                ),
            )
        }),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "{label} argument must be int, float, numeric string, or null in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn optional_sun_float_arg(
    function: &str,
    value: Option<&Value>,
    label: &str,
    span: Span,
) -> CompileResult<Option<f64>> {
    match value {
        Some(Value::Null) | None => Ok(None),
        Some(value) => required_sun_float_arg(function, value, label, span).map(Some),
    }
}

fn parse_bounded_strtotime(
    input: &str,
    default_timezone: &BoundedTimezone,
    base_timestamp: i64,
) -> Option<i64> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return None;
    }
    if trimmed.eq_ignore_ascii_case("now") {
        return Some(base_timestamp);
    }
    if let Some(timestamp) =
        parse_bounded_strtotime_absolute(trimmed, default_timezone, base_timestamp)
    {
        return Some(timestamp);
    }
    if let Some((timestamp, _)) =
        apply_bounded_datetime_modifier(base_timestamp, 0, default_timezone, trimmed)
    {
        return Some(timestamp);
    }
    parse_bounded_strtotime_weekday(trimmed, default_timezone, base_timestamp)
}

fn parse_bounded_strtotime_absolute(
    input: &str,
    default_timezone: &BoundedTimezone,
    base_timestamp: i64,
) -> Option<i64> {
    if let Some((timestamp, _)) = parse_bounded_datetime_with_microsecond(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_compact_datetime_with_timezone(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_compact_utc_datetime(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_flexible_numeric_datetime(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_slash_date(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_iso_week(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_rfc_datetime(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_weekday_ymd(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_year_month(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_time_ymd(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) = parse_bounded_strtotime_ymd_named_time(input, default_timezone) {
        return Some(timestamp);
    }
    if let Some(timestamp) =
        parse_bounded_strtotime_compact_textual_date(input, default_timezone, base_timestamp)
    {
        return Some(timestamp);
    }
    if let Some(timestamp) =
        parse_bounded_strtotime_textual_date(input, default_timezone, base_timestamp)
    {
        return Some(timestamp);
    }
    None
}

fn parse_bounded_compact_utc_datetime(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    if input.len() != 16
        || !matches!(input.as_bytes().get(8), Some(b't') | Some(b'T'))
        || !matches!(input.as_bytes().get(15), Some(b'z') | Some(b'Z'))
    {
        return None;
    }
    if !input[..8].chars().all(|ch| ch.is_ascii_digit())
        || !input[9..15].chars().all(|ch| ch.is_ascii_digit())
    {
        return None;
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let month = parse_ascii_i64(&input[4..6])?;
    let day = parse_ascii_i64(&input[6..8])?;
    let hour = parse_ascii_i64(&input[9..11])?;
    let minute = parse_ascii_i64(&input[11..13])?;
    let second = parse_ascii_i64(&input[13..15])?;
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        Some(0),
        default_timezone,
    )
}

fn parse_bounded_compact_datetime_with_timezone(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let (body, explicit_offset) = split_bounded_datetime_timezone(input);
    if body.len() != 14 || !body.chars().all(|ch| ch.is_ascii_digit()) {
        return None;
    }
    let year = parse_ascii_i64(&body[0..4])?;
    let month = parse_ascii_i64(&body[4..6])?;
    let day = parse_ascii_i64(&body[6..8])?;
    let hour = parse_ascii_i64(&body[8..10])?;
    let minute = parse_ascii_i64(&body[10..12])?;
    let second = parse_ascii_i64(&body[12..14])?;
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
}

fn parse_bounded_flexible_numeric_datetime(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let (body, explicit_timezone) = split_bounded_datetime_timezone_or_name(input);
    let separator_index = body.find(' ').or_else(|| body.find('T'))?;
    let date = &body[..separator_index];
    let time = body[separator_index + 1..].trim();
    let (year, month, day) = parse_strtotime_ymd_token(date)?;
    let (hour, minute, second, _) = parse_strtotime_time_token_parts(time, None)?;
    let explicit_offset = explicit_timezone_offset(
        explicit_timezone.as_ref(),
        year,
        month,
        day,
        hour,
        minute,
        second,
    );
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
}

fn parse_bounded_strtotime_slash_date(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.is_empty() || tokens.len() > 3 {
        return None;
    }
    let (year, month, day) = parse_strtotime_slash_date_token(tokens[0])?;
    let (hour, minute, second) = match tokens.len() {
        1 => (0, 0, 0),
        2 => parse_strtotime_slash_time_token(tokens[1], None)?,
        3 => parse_strtotime_slash_time_token(tokens[1], Some(tokens[2]))?,
        _ => unreachable!(),
    };
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        None,
        default_timezone,
    )
}

fn parse_strtotime_slash_date_token(token: &str) -> Option<(i64, i64, i64)> {
    let parts: Vec<&str> = token.split('/').collect();
    if parts.len() != 3 {
        return None;
    }
    if parts[0].len() == 4 {
        return Some((
            parse_ascii_i64(parts[0])?,
            parse_ascii_i64(parts[1])?,
            parse_ascii_i64(parts[2])?,
        ));
    }
    Some((
        normalize_mktime_year(parse_ascii_i64(parts[2])?, true),
        parse_ascii_i64(parts[0])?,
        parse_ascii_i64(parts[1])?,
    ))
}

fn parse_strtotime_slash_time_token(
    token: &str,
    following: Option<&str>,
) -> Option<(i64, i64, i64)> {
    if token.len() == 4 && token.chars().all(|ch| ch.is_ascii_digit()) {
        return Some((
            parse_ascii_i64(&token[0..2])?,
            parse_ascii_i64(&token[2..4])?,
            0,
        ));
    }
    let (hour, minute, second, _) = parse_strtotime_time_token_parts(token, following)?;
    Some((hour, minute, second))
}

fn parse_bounded_strtotime_iso_week(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    if input.len() != 7 || &input[4..5] != "W" {
        return None;
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let week = parse_ascii_i64(&input[5..7])?;
    let (year, month, day) = iso_week_date_to_civil(year, week, 1)?;
    timestamp_for_bounded_parts(year, month, day, 0, 0, 0, None, default_timezone)
}

fn parse_bounded_strtotime_rfc_datetime(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() < 5 {
        return None;
    }
    let start = if weekday_number_from_name(clean_strtotime_token(tokens[0])).is_some() {
        1
    } else {
        0
    };
    if tokens.len() < start + 5 {
        return None;
    }
    let day = parse_strtotime_day_token(tokens[start])?;
    let month = parse_strtotime_month_token(tokens[start + 1])?;
    let year = parse_four_digit_year(tokens[start + 2])?;
    let (hour, minute, second, _) = parse_strtotime_time_token_parts(tokens[start + 3], None)?;
    let offset = parse_timezone_offset_token(clean_strtotime_token(tokens[start + 4]))?;
    if tokens.len() > start + 5
        && !matches!(
            clean_rfc_timezone_comment_token(tokens[start + 5])
                .to_ascii_uppercase()
                .as_str(),
            "GMT" | "UTC" | "PST" | "PDT" | "CST" | "CDT" | "EST" | "EDT"
        )
    {
        return None;
    }
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        Some(offset),
        default_timezone,
    )
}

fn parse_bounded_strtotime_weekday_ymd(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() != 2 || weekday_number_from_name(tokens[0]).is_none() {
        return None;
    }
    let (year, month, day) = parse_strtotime_ymd_token(tokens[1])?;
    timestamp_for_bounded_parts(year, month, day, 0, 0, 0, None, default_timezone)
}

fn parse_bounded_strtotime_year_month(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    if let Some((year, month, day)) = parse_strtotime_ymd_token(input) {
        return timestamp_for_bounded_parts(year, month, day, 0, 0, 0, None, default_timezone);
    }

    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() != 2 {
        return None;
    }
    let (year, month) = if let Some(year) = parse_four_digit_year(tokens[0]) {
        (year, parse_strtotime_month_token(tokens[1])?)
    } else if let Some(year) = parse_four_digit_year(tokens[1]) {
        (year, parse_strtotime_month_token(tokens[0])?)
    } else {
        return None;
    };
    timestamp_for_bounded_parts(year, month, 1, 0, 0, 0, None, default_timezone)
}

fn parse_bounded_strtotime_time_ymd(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() != 2 {
        return None;
    }
    let (hour, minute, second) = parse_strtotime_time_token(tokens[0])?;
    let (year, month, day) = parse_strtotime_ymd_token(tokens[1])?;
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        None,
        default_timezone,
    )
}

fn parse_bounded_strtotime_ymd_named_time(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() != 2 {
        return None;
    }
    let (year, month, day) = parse_strtotime_ymd_token(tokens[0])?;
    let (hour, minute, second) = parse_strtotime_named_time_token(tokens[1])?;
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        None,
        default_timezone,
    )
}

fn parse_bounded_strtotime_textual_date(
    input: &str,
    default_timezone: &BoundedTimezone,
    base_timestamp: i64,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.is_empty() {
        return None;
    }
    if tokens.len() == 4 {
        if let Some((hour, minute, second)) = parse_strtotime_time_token(tokens[0]) {
            let month = parse_strtotime_month_token(tokens[1])?;
            let day = parse_strtotime_day_token(tokens[2])?;
            let year = parse_four_digit_year(tokens[3])?;
            return timestamp_for_bounded_parts(
                year,
                month,
                day,
                hour,
                minute,
                second,
                None,
                default_timezone,
            );
        }
        if let Some(month) = parse_strtotime_month_token(tokens[0]) {
            let day = parse_strtotime_day_token(tokens[1])?;
            if let Some(year) = parse_four_digit_year(tokens[2]) {
                let (hour, minute, second, _) = parse_strtotime_time_token_parts(tokens[3], None)?;
                return timestamp_for_bounded_parts(
                    year,
                    month,
                    day,
                    hour,
                    minute,
                    second,
                    None,
                    default_timezone,
                );
            }
            if let (Some((hour, minute, second, _)), Some(year)) = (
                parse_strtotime_time_token_parts(tokens[2], None),
                parse_four_digit_year(tokens[3]),
            ) {
                return timestamp_for_bounded_parts(
                    year,
                    month,
                    day,
                    hour,
                    minute,
                    second,
                    None,
                    default_timezone,
                );
            }
        }
    }

    let mut start = 0;
    if weekday_number_from_name(tokens[0]).is_some() {
        start = 1;
    }
    let rest = &tokens[start..];
    if rest.len() < 2 {
        return None;
    }

    let base_offset = default_timezone.offset_at_timestamp(base_timestamp);
    let base_parts = bounded_datetime_parts(base_timestamp, base_offset);

    let (month, day, mut index) = if let Some(day) = parse_strtotime_day_token(rest[0]) {
        (parse_strtotime_month_token(rest[1])?, day, 2)
    } else {
        (
            parse_strtotime_month_token(rest[0])?,
            parse_strtotime_day_token(rest[1])?,
            2,
        )
    };
    let mut year = base_parts.year;
    if let Some(token) = rest.get(index) {
        if let Some(parsed_year) = parse_four_digit_year(token) {
            year = parsed_year;
            index += 1;
        }
    }
    let (hour, minute, second) = if let Some(token) = rest.get(index) {
        let (hour, minute, second, consumed_next) =
            parse_strtotime_time_token_parts(token, rest.get(index + 1).copied())?;
        index += 1 + usize::from(consumed_next);
        (hour, minute, second)
    } else {
        (0, 0, 0)
    };
    let explicit_offset = if let Some(token) = rest.get(index) {
        let offset = parse_timezone_offset_token(clean_strtotime_token(token))?;
        index += 1;
        Some(offset)
    } else {
        None
    };
    if index != rest.len() {
        return None;
    }
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
}

fn parse_bounded_strtotime_compact_textual_date(
    input: &str,
    default_timezone: &BoundedTimezone,
    base_timestamp: i64,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.is_empty() || tokens.len() > 2 {
        return None;
    }
    let (month, day, embedded_year) = parse_compact_textual_month_day(tokens[0])?;
    let year = match (embedded_year, tokens.get(1)) {
        (Some(year), None) => year,
        (None, Some(token)) => parse_four_digit_year(token)?,
        (None, None) => {
            let offset = default_timezone.offset_at_timestamp(base_timestamp);
            bounded_datetime_parts(base_timestamp, offset).year
        }
        (Some(_), Some(_)) => return None,
    };
    timestamp_for_bounded_parts(year, month, day, 0, 0, 0, None, default_timezone)
}

fn parse_compact_textual_month_day(token: &str) -> Option<(i64, i64, Option<i64>)> {
    let clean = clean_strtotime_token(token);
    let chars: Vec<(usize, char)> = clean.char_indices().collect();
    if chars.is_empty() {
        return None;
    }
    let first_digit = chars.iter().position(|(_, ch)| ch.is_ascii_digit());
    let first_alpha = chars.iter().position(|(_, ch)| ch.is_ascii_alphabetic());
    match (first_digit, first_alpha) {
        (Some(0), Some(alpha_index)) if alpha_index > 0 => {
            let alpha_start = chars[alpha_index].0;
            let alpha_end = chars
                .iter()
                .skip(alpha_index)
                .take_while(|(_, ch)| ch.is_ascii_alphabetic())
                .last()
                .map(|(index, ch)| index + ch.len_utf8())?;
            let day = parse_ascii_i64(&clean[..alpha_start])?;
            let month = parse_strtotime_month_token(&clean[alpha_start..alpha_end])?;
            let year = if alpha_end < clean.len() {
                Some(parse_four_digit_year(&clean[alpha_end..])?)
            } else {
                None
            };
            Some((month, day, year))
        }
        (Some(digit_index), Some(0)) if digit_index > 0 => {
            let digit_start = chars[digit_index].0;
            let month = parse_strtotime_month_token(&clean[..digit_start])?;
            let digits = &clean[digit_start..];
            let (day_digits, year) = if digits.len() > 2 {
                (&digits[..2], Some(parse_four_digit_year(&digits[2..])?))
            } else {
                (digits, None)
            };
            Some((month, parse_ascii_i64(day_digits)?, year))
        }
        _ => None,
    }
}

fn parse_bounded_strtotime_weekday(
    input: &str,
    default_timezone: &BoundedTimezone,
    base_timestamp: i64,
) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    let weekday = match tokens.as_slice() {
        [weekday] => weekday_number_from_name(weekday)?,
        ["first", weekday] => weekday_number_from_name(weekday)?,
        _ => return None,
    };
    let offset = default_timezone.offset_at_timestamp(base_timestamp);
    let parts = bounded_datetime_parts(base_timestamp, offset);
    let mut delta_days = weekday - parts.weekday;
    if delta_days <= 0 {
        delta_days += 7;
    }
    timestamp_from_overflowing_local_parts(
        parts.year,
        parts.month,
        parts.day + delta_days,
        0,
        0,
        0,
        default_timezone,
    )
}

fn parse_strtotime_ymd_token(token: &str) -> Option<(i64, i64, i64)> {
    let separator = if token.contains('-') {
        '-'
    } else if token.contains('/') {
        '/'
    } else {
        return None;
    };
    let parts: Vec<&str> = token.split(separator).collect();
    if !(2..=3).contains(&parts.len()) {
        return None;
    }
    let year = parse_four_digit_year(parts[0])?;
    let month = parse_ascii_i64(parts[1])?;
    let day = if let Some(day) = parts.get(2) {
        parse_ascii_i64(day)?
    } else {
        1
    };
    Some((year, month, day))
}

fn parse_four_digit_year(token: &str) -> Option<i64> {
    let token = clean_strtotime_token(token);
    if token.len() == 4 && token.chars().all(|ch| ch.is_ascii_digit()) {
        parse_ascii_i64(token)
    } else {
        None
    }
}

fn parse_strtotime_month_token(token: &str) -> Option<i64> {
    let clean = clean_strtotime_token(token);
    month_number_from_name(clean).or_else(|| roman_month_number(clean))
}

fn roman_month_number(token: &str) -> Option<i64> {
    match token.to_ascii_lowercase().as_str() {
        "i" => Some(1),
        "ii" => Some(2),
        "iii" => Some(3),
        "iv" => Some(4),
        "v" => Some(5),
        "vi" => Some(6),
        "vii" => Some(7),
        "viii" => Some(8),
        "ix" => Some(9),
        "x" => Some(10),
        "xi" => Some(11),
        "xii" => Some(12),
        _ => None,
    }
}

fn parse_strtotime_day_token(token: &str) -> Option<i64> {
    let clean = clean_strtotime_token(token).to_ascii_lowercase();
    let digits = clean
        .strip_suffix("st")
        .or_else(|| clean.strip_suffix("nd"))
        .or_else(|| clean.strip_suffix("rd"))
        .or_else(|| clean.strip_suffix("th"))
        .unwrap_or(&clean);
    parse_ascii_i64(digits)
}

fn parse_strtotime_time_token(token: &str) -> Option<(i64, i64, i64)> {
    let (hour, minute, second, _) = parse_strtotime_time_token_parts(token, None)?;
    Some((hour, minute, second))
}

fn parse_strtotime_time_token_parts(
    token: &str,
    following: Option<&str>,
) -> Option<(i64, i64, i64, bool)> {
    let clean = clean_strtotime_token(token);
    let (time, inline_meridiem) = split_strtotime_meridiem_suffix(clean);
    let following_meridiem = following.and_then(parse_strtotime_meridiem_token);
    let meridiem = inline_meridiem.or(following_meridiem);
    let consumed_following = inline_meridiem.is_none() && following_meridiem.is_some();
    let (time, _) = time
        .split_once('.')
        .map(|(left, fraction)| {
            if fraction.chars().all(|ch| ch.is_ascii_digit()) {
                (left, Some(fraction))
            } else {
                (time, None)
            }
        })
        .unwrap_or((time, None));
    let (mut hour, minute, second) = if time.contains(':') {
        let parts: Vec<&str> = time.split(':').collect();
        if !(2..=3).contains(&parts.len()) {
            return None;
        }
        let minute = parse_ascii_i64(parts[1])?;
        let second = if let Some(second) = parts.get(2) {
            parse_ascii_i64(second)?
        } else {
            0
        };
        (parse_ascii_i64(parts[0])?, minute, second)
    } else if meridiem.is_some() && time.chars().all(|ch| ch.is_ascii_digit()) {
        (parse_ascii_i64(time)?, 0, 0)
    } else {
        return None;
    };
    if let Some(is_pm) = meridiem {
        if !(1..=12).contains(&hour) {
            return None;
        }
        if hour == 12 {
            hour = 0;
        }
        if is_pm {
            hour += 12;
        }
    }
    Some((hour, minute, second, consumed_following))
}

fn split_strtotime_meridiem_suffix(token: &str) -> (&str, Option<bool>) {
    let lower = token.to_ascii_lowercase();
    for (suffix, is_pm) in [
        ("a.m.", false),
        ("p.m.", true),
        ("a.m", false),
        ("p.m", true),
        ("am", false),
        ("pm", true),
    ] {
        if lower.ends_with(suffix) {
            return (&token[..token.len() - suffix.len()], Some(is_pm));
        }
    }
    (token, None)
}

fn parse_strtotime_meridiem_token(token: &str) -> Option<bool> {
    match clean_strtotime_token(token).to_ascii_lowercase().as_str() {
        "am" | "a.m" | "a.m." => Some(false),
        "pm" | "p.m" | "p.m." => Some(true),
        _ => None,
    }
}

fn parse_strtotime_named_time_token(token: &str) -> Option<(i64, i64, i64)> {
    match clean_strtotime_token(token).to_ascii_lowercase().as_str() {
        "noon" => Some((12, 0, 0)),
        "midnight" => Some((0, 0, 0)),
        _ => None,
    }
}

fn clean_strtotime_token(token: &str) -> &str {
    token
        .trim_matches(',')
        .trim_end_matches(',')
        .trim_end_matches('.')
}

fn parse_bounded_datetime_with_microsecond(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<(i64, i64)> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some((timestamp, microsecond)) = parse_bounded_at_timestamp_with_microsecond(trimmed) {
        return Some((timestamp, microsecond));
    }

    if trimmed.len() == 14 && trimmed.chars().all(|ch| ch.is_ascii_digit()) {
        let year = parse_ascii_i64(&trimmed[0..4])?;
        let month = parse_ascii_i64(&trimmed[4..6])?;
        let day = parse_ascii_i64(&trimmed[6..8])?;
        let hour = parse_ascii_i64(&trimmed[8..10])?;
        let minute = parse_ascii_i64(&trimmed[10..12])?;
        let second = parse_ascii_i64(&trimmed[12..14])?;
        return timestamp_for_bounded_parts(
            year,
            month,
            day,
            hour,
            minute,
            second,
            None,
            default_timezone,
        )
        .map(|timestamp| (timestamp, 0));
    }

    if trimmed.len() == 10 && &trimmed[4..5] == "-" && &trimmed[7..8] == "-" {
        let year = parse_ascii_i64(&trimmed[0..4])?;
        let month = parse_ascii_i64(&trimmed[5..7])?;
        let day = parse_ascii_i64(&trimmed[8..10])?;
        return timestamp_for_bounded_parts(year, month, day, 0, 0, 0, None, default_timezone)
            .map(|timestamp| (timestamp, 0));
    }

    if let Some((timestamp, microsecond)) =
        parse_bounded_numeric_datetime_with_microsecond(trimmed, default_timezone)
    {
        return Some((timestamp, microsecond));
    }
    if let Some((timestamp, microsecond)) =
        parse_bounded_dmy_datetime_with_microsecond(trimmed, default_timezone)
    {
        return Some((timestamp, microsecond));
    }

    parse_bounded_textual_datetime(trimmed, default_timezone).map(|timestamp| (timestamp, 0))
}

fn bounded_date_parse_array(input: &str) -> PhpArray {
    let trimmed = input.trim();
    if !input.is_empty() && trimmed.is_empty() {
        return bounded_date_parse_result_array(date_parse_result_with_errors(vec![]));
    }
    if trimmed.eq_ignore_ascii_case("a") {
        let mut array = bounded_date_parse_result_array(BoundedDateParseResult {
            year: None,
            month: None,
            day: None,
            hour: None,
            minute: None,
            second: None,
            fraction: Value::Bool(false),
            warnings: vec![],
            errors: vec![],
            is_localtime: true,
            zone_type: Some(2),
            zone: Some(3_600),
            is_dst: Some(false),
        });
        array.insert("tz_abbr", Value::String("A".to_string()));
        return array;
    }
    if let Some(relative) = bounded_date_parse_relative_metadata(input) {
        let mut array = bounded_date_parse_result_array(date_parse_result_with_errors(vec![]));
        array.insert("relative", Value::Array(relative));
        return array;
    }
    bounded_date_parse_result_array(bounded_date_parse_result(input))
}

fn bounded_date_parse_result_array(result: BoundedDateParseResult) -> PhpArray {
    let mut array = PhpArray::new();
    array.insert("year", optional_int_or_false(result.year));
    array.insert("month", optional_int_or_false(result.month));
    array.insert("day", optional_int_or_false(result.day));
    array.insert("hour", optional_int_or_false(result.hour));
    array.insert("minute", optional_int_or_false(result.minute));
    array.insert("second", optional_int_or_false(result.second));
    array.insert("fraction", result.fraction);
    array.insert("warning_count", Value::Int(result.warnings.len() as i64));
    array.insert(
        "warnings",
        Value::Array(date_parse_diagnostics_array(&result.warnings)),
    );
    array.insert("error_count", Value::Int(result.errors.len() as i64));
    array.insert(
        "errors",
        Value::Array(date_parse_diagnostics_array(&result.errors)),
    );
    array.insert("is_localtime", Value::Bool(result.is_localtime));
    if let Some(zone_type) = result.zone_type {
        array.insert("zone_type", Value::Int(zone_type));
    }
    if let Some(zone) = result.zone {
        array.insert("zone", Value::Int(zone));
    }
    if let Some(is_dst) = result.is_dst {
        array.insert("is_dst", Value::Bool(is_dst));
    }
    array
}

fn date_parse_last_errors_array(diagnostics: &BoundedDateParseDiagnostics) -> PhpArray {
    let mut array = PhpArray::new();
    array.insert(
        "warning_count",
        Value::Int(diagnostics.warnings.len() as i64),
    );
    array.insert(
        "warnings",
        Value::Array(date_parse_diagnostics_array(&diagnostics.warnings)),
    );
    array.insert("error_count", Value::Int(diagnostics.errors.len() as i64));
    array.insert(
        "errors",
        Value::Array(date_parse_diagnostics_array(&diagnostics.errors)),
    );
    array
}

fn optional_int_or_false(value: Option<i64>) -> Value {
    value.map(Value::Int).unwrap_or(Value::Bool(false))
}

fn date_parse_diagnostics_array(entries: &[(i64, &'static str)]) -> PhpArray {
    let mut array = PhpArray::new();
    for (offset, message) in entries {
        array.insert(*offset, Value::String((*message).to_string()));
    }
    array
}

fn bounded_date_parse_relative_metadata(input: &str) -> Option<PhpArray> {
    let (month, day, first_day, last_day) = match input.trim().to_ascii_lowercase().as_str() {
        "first day" => (0, 1, false, false),
        "last day" => (0, -1, false, false),
        "next month" => (1, 0, false, false),
        "first day next month" => (1, 1, false, false),
        "last day next month" => (1, -1, false, false),
        "first day of next month" => (1, 0, true, false),
        "last day of next month" => (1, 0, false, true),
        _ => return None,
    };
    let mut relative = PhpArray::new();
    relative.insert("year", Value::Int(0));
    relative.insert("month", Value::Int(month));
    relative.insert("day", Value::Int(day));
    relative.insert("hour", Value::Int(0));
    relative.insert("minute", Value::Int(0));
    relative.insert("second", Value::Int(0));
    if first_day {
        relative.insert("first_day_of_month", Value::Bool(true));
    }
    if last_day {
        relative.insert("last_day_of_month", Value::Bool(true));
    }
    Some(relative)
}

fn bounded_date_parse_result(input: &str) -> BoundedDateParseResult {
    if input.is_empty() {
        return date_parse_result_with_errors(vec![(0, "Empty string")]);
    }
    if let Some(result) = bounded_date_parse_full_datetime(input) {
        return result;
    }
    if let Some(result) = bounded_date_parse_time_only(input) {
        return result;
    }
    if let Some(result) = bounded_date_parse_date_only(input) {
        return result;
    }
    if let Some(result) = bounded_date_parse_double_dash_timezone(input) {
        return result;
    }
    if let Some(result) = bounded_date_parse_numeric_timezone_only(input) {
        return result;
    }
    if let Some(result) = bounded_date_parse_malformed_numeric_datetime(input) {
        return result;
    }
    date_parse_result_with_errors(vec![(0, "Unexpected character")])
}

fn bounded_date_parse_full_datetime(input: &str) -> Option<BoundedDateParseResult> {
    if !input.is_ascii()
        || input.len() < 21
        || &input[4..5] != "-"
        || &input[7..8] != "-"
        || &input[10..11] != " "
        || &input[13..14] != ":"
        || &input[16..17] != ":"
        || &input[19..20] != "."
    {
        return None;
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let month = parse_ascii_i64(&input[5..7])?;
    let day = parse_ascii_i64(&input[8..10])?;
    let hour = parse_ascii_i64(&input[11..13])?;
    let minute = parse_ascii_i64(&input[14..16])?;
    let second = parse_ascii_i64(&input[17..19])?;
    let fraction = parse_decimal_fraction_value(&input[20..])?;
    Some(BoundedDateParseResult {
        year: Some(year),
        month: Some(month),
        day: Some(day),
        hour: Some(hour),
        minute: Some(minute),
        second: Some(second),
        fraction: Value::Float(fraction),
        warnings: date_parse_date_warnings(year, month, day),
        errors: vec![],
        is_localtime: false,
        zone_type: None,
        zone: None,
        is_dst: None,
    })
}

fn bounded_date_parse_time_only(input: &str) -> Option<BoundedDateParseResult> {
    if !input.is_ascii()
        || input.len() < 9
        || &input[2..3] != ":"
        || &input[5..6] != ":"
        || &input[8..9] != "."
    {
        return None;
    }
    let hour = parse_ascii_i64(&input[0..2])?;
    let minute = parse_ascii_i64(&input[3..5])?;
    let second = parse_ascii_i64(&input[6..8])?;
    let fraction = parse_decimal_fraction_value(&input[9..])?;
    Some(BoundedDateParseResult {
        year: None,
        month: None,
        day: None,
        hour: Some(hour),
        minute: Some(minute),
        second: Some(second),
        fraction: Value::Float(fraction),
        warnings: vec![],
        errors: vec![],
        is_localtime: false,
        zone_type: None,
        zone: None,
        is_dst: None,
    })
}

fn bounded_date_parse_date_only(input: &str) -> Option<BoundedDateParseResult> {
    if !input.is_ascii() || input.len() < 7 || &input[4..5] != "-" {
        return None;
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let month = parse_ascii_i64(&input[5..7])?;
    let day = if input.len() == 7 {
        1
    } else if input.len() == 10 && &input[7..8] == "-" {
        parse_ascii_i64(&input[8..10])?
    } else {
        return None;
    };
    Some(BoundedDateParseResult {
        year: Some(year),
        month: Some(month),
        day: Some(day),
        hour: None,
        minute: None,
        second: None,
        fraction: Value::Bool(false),
        warnings: date_parse_date_warnings(year, month, day),
        errors: vec![],
        is_localtime: false,
        zone_type: None,
        zone: None,
        is_dst: None,
    })
}

fn bounded_date_parse_double_dash_timezone(input: &str) -> Option<BoundedDateParseResult> {
    if !input.is_ascii() || input.len() != 11 || &input[4..5] != "-" || &input[7..9] != "--" {
        return None;
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let month = parse_ascii_i64(&input[5..7])?;
    let zone_hour = parse_ascii_i64(&input[9..11])?;
    Some(BoundedDateParseResult {
        year: Some(year),
        month: Some(month),
        day: Some(1),
        hour: None,
        minute: None,
        second: None,
        fraction: Value::Bool(false),
        warnings: vec![],
        errors: vec![(7, "Unexpected character")],
        is_localtime: true,
        zone_type: Some(1),
        zone: Some(-zone_hour * 3_600),
        is_dst: Some(false),
    })
}

fn bounded_date_parse_numeric_timezone_only(input: &str) -> Option<BoundedDateParseResult> {
    let (left, right) = input.split_once('-')?;
    if left.is_empty()
        || right.is_empty()
        || !left.chars().all(|ch| ch.is_ascii_digit())
        || !right.chars().all(|ch| ch.is_ascii_digit())
    {
        return None;
    }
    let zone_hour = parse_ascii_i64(right)?;
    let errors = (0..left.len() as i64)
        .map(|offset| (offset, "Unexpected character"))
        .collect();
    Some(BoundedDateParseResult {
        year: None,
        month: None,
        day: None,
        hour: None,
        minute: None,
        second: None,
        fraction: Value::Bool(false),
        warnings: vec![],
        errors,
        is_localtime: true,
        zone_type: Some(1),
        zone: Some(-zone_hour * 3_600),
        is_dst: Some(false),
    })
}

fn bounded_date_parse_malformed_numeric_datetime(input: &str) -> Option<BoundedDateParseResult> {
    if !input.is_ascii() || !input.contains("--") || !input.contains('?') {
        return None;
    }
    let time_start = input.find(' ')? + 1;
    let hour = parse_ascii_i64(input.get(time_start..time_start + 2)?)?;
    let minute = parse_ascii_i64(input.get(time_start + 3..time_start + 5)?)?;
    let second = parse_ascii_i64(input.get(time_start + 6..time_start + 8)?)?;
    Some(BoundedDateParseResult {
        year: None,
        month: None,
        day: None,
        hour: Some(hour),
        minute: Some(minute),
        second: Some(second),
        fraction: Value::Float(0.0),
        warnings: vec![(4, "Double timezone specification")],
        errors: vec![
            (0, "Unexpected character"),
            (1, "The timezone could not be found in the database"),
            (3, "Unexpected character"),
            (7, "Unexpected character"),
            (8, "Double timezone specification"),
            (17, "Unexpected character"),
            (18, "Double time specification"),
        ],
        is_localtime: true,
        zone_type: Some(0),
        zone: None,
        is_dst: None,
    })
}

fn date_parse_result_with_errors(errors: Vec<(i64, &'static str)>) -> BoundedDateParseResult {
    BoundedDateParseResult {
        year: None,
        month: None,
        day: None,
        hour: None,
        minute: None,
        second: None,
        fraction: Value::Bool(false),
        warnings: vec![],
        errors,
        is_localtime: false,
        zone_type: None,
        zone: None,
        is_dst: None,
    }
}

fn date_parse_date_warnings(year: i64, month: i64, day: i64) -> Vec<(i64, &'static str)> {
    if (1..=12).contains(&month) && (1..=days_in_month(year, month)).contains(&day) {
        vec![]
    } else {
        vec![(11, "The parsed date was invalid")]
    }
}

fn parse_decimal_fraction_value(fraction: &str) -> Option<f64> {
    if fraction.is_empty() || !fraction.chars().all(|ch| ch.is_ascii_digit()) {
        return None;
    }
    format!("0.{fraction}").parse::<f64>().ok()
}

fn parse_bounded_format_datetime_attempt(
    format: &str,
    input: &str,
    default_timezone: &BoundedTimezone,
) -> BoundedFormatParseAttempt {
    if !format.is_ascii() || !input.is_ascii() {
        return bounded_format_parse_error(0, "Data missing");
    }
    let mut cursor = BoundedFormatCursor { input, position: 0 };
    let mut parts = BoundedFormatParts {
        year: 1970,
        month: 1,
        day: 1,
        hour: 0,
        minute: 0,
        second: 0,
        microsecond: 0,
        timezone: default_timezone.clone(),
        twelve_hour: false,
        meridiem: None,
        year_seen: false,
        month_seen: false,
        day_seen: false,
        hour_seen: false,
        minute_seen: false,
        second_seen: false,
        fraction_seen: false,
        timezone_seen: false,
        day_of_year: None,
        unix_timestamp: None,
        lenient_trailing_data: false,
    };
    let mut escaped = false;
    for token in format.chars() {
        if escaped {
            if cursor.consume_literal(token).is_none() {
                return bounded_format_parse_error(cursor.position as i64, "Data missing");
            }
            escaped = false;
            continue;
        }
        match token {
            '\\' => escaped = true,
            '+' => parts.lenient_trailing_data = true,
            '|' => {}
            '!' => {
                parts.year = 1970;
                parts.month = 1;
                parts.day = 1;
                parts.hour = 0;
                parts.minute = 0;
                parts.second = 0;
                parts.microsecond = 0;
                parts.timezone = default_timezone.clone();
                parts.year_seen = false;
                parts.month_seen = false;
                parts.day_seen = false;
                parts.hour_seen = false;
                parts.minute_seen = false;
                parts.second_seen = false;
                parts.fraction_seen = false;
                parts.timezone_seen = false;
                parts.day_of_year = None;
                parts.unix_timestamp = None;
            }
            'Y' => {
                let Some(value) = cursor.consume_fixed_digits(4) else {
                    return bounded_format_parse_error(
                        cursor.position as i64,
                        "A four digit year could not be found",
                    );
                };
                parts.year = value;
                parts.year_seen = true;
            }
            'X' => {
                let Some(value) = cursor.consume_signed_fixed_year(4) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.year = value;
                parts.year_seen = true;
            }
            'U' => {
                let Some(timestamp) = cursor.consume_signed_digit_run(1, 19) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.unix_timestamp = Some(timestamp);
                parts.timezone = BoundedTimezone::numeric_fixed_offset(0);
            }
            'y' => {
                let Some(year) = cursor.consume_fixed_digits(2) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.year = if year <= 69 { 2000 + year } else { 1900 + year };
                parts.year_seen = true;
            }
            'm' | 'd' | 'H' => {
                let Some(value) = cursor.consume_digit_component(1, 2) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                match token {
                    'm' => {
                        parts.month = value;
                        parts.month_seen = true;
                    }
                    'd' => {
                        parts.day = value;
                        parts.day_seen = true;
                    }
                    'H' => {
                        parts.hour = value;
                        parts.hour_seen = true;
                    }
                    _ => {}
                }
            }
            'i' | 's' => {
                let Some(value) = cursor.consume_fixed_digits(2) else {
                    let message = if token == 's' {
                        "A two digit second could not be found"
                    } else {
                        "Data missing"
                    };
                    return bounded_format_parse_error(cursor.position as i64, message);
                };
                match token {
                    'H' => parts.hour = value,
                    'i' => {
                        parts.minute = value;
                        parts.minute_seen = true;
                    }
                    's' => {
                        parts.second = value;
                        parts.second_seen = true;
                    }
                    _ => {}
                }
            }
            'j' => {
                let Some(value) = cursor.consume_variable_digits(1, 2) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.day = value;
                parts.day_seen = true;
            }
            'z' => {
                if !parts.year_seen {
                    return bounded_format_parse_error(
                        cursor.position as i64,
                        "A 'day of year' can only come after a year has been found",
                    );
                }
                let Some(value) = cursor.consume_variable_digits(1, 3) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.day_of_year = Some(value);
            }
            'g' => {
                let Some(value) = cursor.consume_variable_digits(1, 2) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.hour = value;
                parts.hour_seen = true;
                parts.twelve_hour = true;
            }
            'u' => {
                let Some(digits) = cursor.consume_digit_run(1, 6) else {
                    return bounded_format_parse_error(
                        cursor.position as i64,
                        "Not enough data available to satisfy format",
                    );
                };
                let Some(microsecond) = parse_microsecond_fraction(digits) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.microsecond = microsecond;
                parts.fraction_seen = true;
            }
            'v' => {
                let Some(digits) = cursor.consume_digit_run(3, 3) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                let Some(microsecond) = parse_microsecond_fraction(digits) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.microsecond = microsecond;
                parts.fraction_seen = true;
            }
            'M' => {
                let Some(month) = cursor.consume_month_name(false) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.month = month;
                parts.month_seen = true;
            }
            'F' => {
                let Some(month) = cursor.consume_month_name(true) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.month = month;
                parts.month_seen = true;
            }
            'D' => {
                if cursor.consume_weekday_name(false).is_none() {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                }
            }
            'l' => {
                if cursor.consume_weekday_name(true).is_none() {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                }
            }
            'A' | 'a' => {
                let Some(meridiem) = cursor.consume_meridiem() else {
                    return bounded_format_parse_error(
                        cursor.position as i64,
                        "A meridian could not be found",
                    );
                };
                parts.meridiem = Some(meridiem);
            }
            'O' => {
                let Some(offset) = cursor.consume_timezone_offset(false) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.timezone = BoundedTimezone::numeric_fixed_offset(offset);
                parts.timezone_seen = true;
            }
            'P' => {
                let Some(offset) = cursor.consume_timezone_offset(true) else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.timezone = BoundedTimezone::numeric_fixed_offset(offset);
                parts.timezone_seen = true;
            }
            'T' => {
                let Some(timezone) = cursor.consume_timezone_abbreviation() else {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                };
                parts.timezone = timezone;
                parts.timezone_seen = true;
            }
            '#' | '*' => {
                if cursor.consume_one_separator().is_none() {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                }
            }
            other => {
                if cursor.consume_literal(other).is_none() {
                    return bounded_format_parse_error(cursor.position as i64, "Data missing");
                }
            }
        }
    }
    if escaped || !cursor.is_finished() {
        let diagnostics = if parts.lenient_trailing_data {
            BoundedDateParseDiagnostics {
                warnings: vec![(cursor.position as i64, "Trailing data")],
                errors: vec![],
            }
        } else {
            BoundedDateParseDiagnostics {
                warnings: vec![],
                errors: vec![(cursor.position as i64, "Trailing data")],
            }
        };
        return bounded_format_parse_success(parts, default_timezone, diagnostics);
    }
    if parts.twelve_hour {
        if !(1..=12).contains(&parts.hour) {
            return bounded_format_parse_error(0, "Data missing");
        }
        if parts.hour == 12 {
            parts.hour = 0;
        }
        if matches!(parts.meridiem, Some(true)) {
            parts.hour += 12;
        }
    }
    bounded_format_parse_success(
        parts,
        default_timezone,
        BoundedDateParseDiagnostics {
            warnings: vec![],
            errors: vec![],
        },
    )
}

fn bounded_format_parse_error(offset: i64, message: &'static str) -> BoundedFormatParseAttempt {
    let diagnostics = BoundedDateParseDiagnostics {
        warnings: vec![],
        errors: vec![(offset, message)],
    };
    BoundedFormatParseAttempt {
        parsed: None,
        fields: BoundedDateParseResult {
            year: None,
            month: None,
            day: None,
            hour: None,
            minute: None,
            second: None,
            fraction: Value::Bool(false),
            warnings: diagnostics.warnings.clone(),
            errors: diagnostics.errors.clone(),
            is_localtime: false,
            zone_type: None,
            zone: None,
            is_dst: None,
        },
        diagnostics,
    }
}

fn bounded_format_parse_success(
    mut parts: BoundedFormatParts,
    default_timezone: &BoundedTimezone,
    diagnostics: BoundedDateParseDiagnostics,
) -> BoundedFormatParseAttempt {
    if let Some(day_of_year) = parts.day_of_year {
        if let Some((month, day)) = month_day_from_day_of_year(parts.year, day_of_year) {
            parts.month = month;
            parts.day = day;
            parts.month_seen = true;
            parts.day_seen = true;
        } else {
            return bounded_format_parse_error(0, "Data missing");
        }
    }

    let (parsed, parsed_timezone) = if let Some(timestamp) = parts.unix_timestamp {
        (
            Some(BoundedParsedDateTime {
                timestamp,
                microsecond: parts.microsecond,
                timezone: BoundedTimezone::numeric_fixed_offset(0),
            }),
            BoundedTimezone::numeric_fixed_offset(0),
        )
    } else {
        let explicit_offset = parts.timezone.fixed_offset;
        let parsed = timestamp_for_bounded_parts(
            parts.year,
            parts.month,
            parts.day,
            parts.hour,
            parts.minute,
            parts.second,
            explicit_offset,
            default_timezone,
        )
        .map(|timestamp| BoundedParsedDateTime {
            timestamp,
            microsecond: parts.microsecond,
            timezone: parts.timezone.clone(),
        });
        (parsed, parts.timezone.clone())
    };

    let (zone_type, zone, is_dst) = if parts.timezone_seen {
        bounded_date_parse_timezone_metadata(&parsed_timezone.name).unwrap_or((None, None, None))
    } else {
        (None, None, None)
    };
    let fields = BoundedDateParseResult {
        year: parts.year_seen.then_some(parts.year),
        month: parts.month_seen.then_some(parts.month),
        day: parts.day_seen.then_some(parts.day),
        hour: parts.hour_seen.then_some(parts.hour),
        minute: parts.minute_seen.then_some(parts.minute),
        second: parts.second_seen.then_some(parts.second),
        fraction: if parts.fraction_seen {
            Value::Float(parts.microsecond as f64 / 1_000_000.0)
        } else {
            Value::Bool(false)
        },
        warnings: diagnostics.warnings.clone(),
        errors: diagnostics.errors.clone(),
        is_localtime: zone_type.is_some(),
        zone_type,
        zone,
        is_dst,
    };
    BoundedFormatParseAttempt {
        parsed,
        fields,
        diagnostics,
    }
}

fn bounded_date_parse_timezone_metadata(
    timezone_name: &str,
) -> Option<(Option<i64>, Option<i64>, Option<bool>)> {
    let (timezone_type, canonical) = bounded_timezone_object_parts(timezone_name)?;
    let zone = match timezone_type {
        1 => parse_timezone_offset_token(&canonical),
        2 => bounded_timezone_from_name(&canonical)
            .map(|timezone| timezone.fixed_offset.unwrap_or(0)),
        _ => None,
    };
    Some((Some(timezone_type), zone, Some(false)))
}

fn month_day_from_day_of_year(year: i64, day_of_year: i64) -> Option<(i64, i64)> {
    if day_of_year < 0 {
        return None;
    }
    let mut remaining = day_of_year;
    for month in 1..=12 {
        let days = days_in_month(year, month);
        if remaining < days {
            return Some((month, remaining + 1));
        }
        remaining -= days;
    }
    None
}

struct BoundedFormatParts {
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
    microsecond: i64,
    timezone: BoundedTimezone,
    twelve_hour: bool,
    meridiem: Option<bool>,
    year_seen: bool,
    month_seen: bool,
    day_seen: bool,
    hour_seen: bool,
    minute_seen: bool,
    second_seen: bool,
    fraction_seen: bool,
    timezone_seen: bool,
    day_of_year: Option<i64>,
    unix_timestamp: Option<i64>,
    lenient_trailing_data: bool,
}

struct BoundedFormatCursor<'a> {
    input: &'a str,
    position: usize,
}

impl<'a> BoundedFormatCursor<'a> {
    fn is_finished(&self) -> bool {
        self.position == self.input.len()
    }

    fn rest(&self) -> &'a str {
        &self.input[self.position..]
    }

    fn consume_literal(&mut self, expected: char) -> Option<()> {
        let rest = self.rest();
        let mut chars = rest.chars();
        let actual = chars.next()?;
        if actual != expected {
            return None;
        }
        self.position += actual.len_utf8();
        Some(())
    }

    fn consume_fixed_digits(&mut self, width: usize) -> Option<i64> {
        let digits = self.consume_digit_run(width, width)?;
        parse_ascii_i64(digits)
    }

    fn consume_signed_fixed_year(&mut self, width: usize) -> Option<i64> {
        let sign = self.rest().chars().next()?;
        if sign != '+' && sign != '-' {
            return None;
        }
        self.position += 1;
        let value = self.consume_fixed_digits(width)?;
        if sign == '-' {
            value.checked_neg()
        } else {
            Some(value)
        }
    }

    fn consume_variable_digits(&mut self, min: usize, max: usize) -> Option<i64> {
        let digits = self.consume_digit_run(min, max)?;
        parse_ascii_i64(digits)
    }

    fn consume_digit_component(&mut self, min: usize, max: usize) -> Option<i64> {
        self.consume_variable_digits(min, max)
    }

    fn consume_signed_digit_run(&mut self, min: usize, max: usize) -> Option<i64> {
        let start = self.position;
        if matches!(
            self.rest().as_bytes().first().copied(),
            Some(b'+') | Some(b'-')
        ) {
            self.position += 1;
        }
        let bytes = self.input.as_bytes();
        let mut len = 0;
        while self.position + len < bytes.len()
            && len < max
            && bytes[self.position + len].is_ascii_digit()
        {
            len += 1;
        }
        if len < min {
            self.position = start;
            return None;
        }
        self.position += len;
        parse_signed_ascii_i64(&self.input[start..self.position]).or_else(|| {
            self.position = start;
            None
        })
    }

    fn consume_digit_run(&mut self, min: usize, max: usize) -> Option<&'a str> {
        let bytes = self.input.as_bytes();
        let start = self.position;
        let mut len = 0;
        while self.position + len < bytes.len()
            && len < max
            && bytes[self.position + len].is_ascii_digit()
        {
            len += 1;
        }
        if len < min {
            return None;
        }
        self.position += len;
        Some(&self.input[start..self.position])
    }

    fn consume_month_name(&mut self, full: bool) -> Option<i64> {
        let candidates: &[(&str, i64)] = if full {
            &[
                ("January", 1),
                ("February", 2),
                ("March", 3),
                ("April", 4),
                ("May", 5),
                ("June", 6),
                ("July", 7),
                ("August", 8),
                ("September", 9),
                ("October", 10),
                ("November", 11),
                ("December", 12),
            ]
        } else {
            &[
                ("Jan", 1),
                ("Feb", 2),
                ("Mar", 3),
                ("Apr", 4),
                ("May", 5),
                ("Jun", 6),
                ("Jul", 7),
                ("Aug", 8),
                ("Sep", 9),
                ("Oct", 10),
                ("Nov", 11),
                ("Dec", 12),
            ]
        };
        for (name, month) in candidates {
            if self.rest().len() >= name.len()
                && self.rest()[..name.len()].eq_ignore_ascii_case(name)
            {
                self.position += name.len();
                return Some(*month);
            }
        }
        None
    }

    fn consume_weekday_name(&mut self, full: bool) -> Option<()> {
        let candidates: &[&str] = if full {
            &[
                "Sunday",
                "Monday",
                "Tuesday",
                "Wednesday",
                "Thursday",
                "Friday",
                "Saturday",
            ]
        } else {
            &["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
        };
        for name in candidates {
            if self.rest().len() >= name.len()
                && self.rest()[..name.len()].eq_ignore_ascii_case(name)
            {
                self.position += name.len();
                return Some(());
            }
        }
        if full {
            return self.consume_weekday_name(false);
        }
        None
    }

    fn consume_meridiem(&mut self) -> Option<bool> {
        let rest = self.rest();
        if rest.len() >= 2 && rest[..2].eq_ignore_ascii_case("AM") {
            self.position += 2;
            Some(false)
        } else if rest.len() >= 2 && rest[..2].eq_ignore_ascii_case("PM") {
            self.position += 2;
            Some(true)
        } else {
            None
        }
    }

    fn consume_timezone_offset(&mut self, colon: bool) -> Option<i64> {
        let gmt_prefix = self.rest().get(..3).is_some_and(|value| value == "GMT");
        if gmt_prefix {
            self.position += 3;
        }
        let widths: &[usize] = if colon { &[9, 6] } else { &[9, 7, 5] };
        for width in widths {
            let Some(end) = self.position.checked_add(*width) else {
                continue;
            };
            let Some(token) = self.input.get(self.position..end) else {
                continue;
            };
            let offset = if colon || token.contains(':') {
                parse_timezone_offset_token(token)
            } else {
                parse_timezone_offset_without_colon(token)
            };
            if let Some(offset) = offset {
                self.position = end;
                return Some(offset);
            }
        }
        if gmt_prefix {
            self.position -= 3;
        }
        None
    }

    fn consume_timezone_abbreviation(&mut self) -> Option<BoundedTimezone> {
        if self.rest().starts_with("GMT") {
            self.position += 3;
            if self.is_finished() {
                return Some(BoundedTimezone {
                    name: "GMT".to_string(),
                    fixed_offset: Some(0),
                });
            }
            let offset = self.consume_timezone_offset(false)?;
            return Some(BoundedTimezone::numeric_fixed_offset(offset));
        }
        if self.rest().starts_with("UTC") {
            self.position += 3;
            return bounded_timezone_from_name("UTC");
        }
        None
    }

    fn consume_one_separator(&mut self) -> Option<()> {
        let ch = self.rest().chars().next()?;
        if ch.is_ascii_alphanumeric() {
            return None;
        }
        self.position += ch.len_utf8();
        Some(())
    }
}

fn parse_timezone_offset_without_colon(token: &str) -> Option<i64> {
    if !matches!(token.len(), 5 | 7) {
        return None;
    }
    let sign = &token[0..1];
    if sign != "+" && sign != "-" {
        return None;
    }
    let hours = parse_ascii_i64(&token[1..3])?;
    let minutes = parse_ascii_i64(&token[3..5])?;
    let seconds = if token.len() == 7 {
        parse_ascii_i64(&token[5..7])?
    } else {
        0
    };
    if hours > 23 || minutes > 59 || seconds > 59 {
        return None;
    }
    let offset = hours
        .checked_mul(3_600)?
        .checked_add(minutes * 60)?
        .checked_add(seconds)?;
    if sign == "-" {
        offset.checked_neg()
    } else {
        Some(offset)
    }
}

fn apply_bounded_datetime_modifier(
    timestamp: i64,
    microsecond: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<(i64, i64)> {
    let trimmed = modifier.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some(timestamp) = apply_bounded_named_time_modifier(timestamp, timezone, trimmed) {
        return Some((timestamp, 0));
    }
    if let Some((timestamp, microsecond)) =
        apply_bounded_relative_calendar_modifier(timestamp, microsecond, timezone, trimmed)
    {
        return Some((timestamp, microsecond));
    }
    if let Some(timestamp) = apply_bounded_weekday_modifier(timestamp, timezone, trimmed) {
        return Some((timestamp, microsecond));
    }
    if let Some(timestamp) = apply_bounded_n_weekday_modifier(timestamp, timezone, trimmed) {
        return Some((timestamp, microsecond));
    }
    apply_bounded_unit_modifier(timestamp, microsecond, timezone, trimmed)
}

fn apply_bounded_named_time_modifier(
    timestamp: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    match modifier.to_ascii_lowercase().as_str() {
        "yesterday" => timestamp_from_overflowing_local_parts(
            parts.year,
            parts.month,
            parts.day - 1,
            0,
            0,
            0,
            timezone,
        ),
        "noon" => timestamp_from_overflowing_local_parts(
            parts.year,
            parts.month,
            parts.day,
            12,
            0,
            0,
            timezone,
        ),
        _ => None,
    }
}

fn apply_bounded_weekday_modifier(
    timestamp: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<i64> {
    let mut tokens = modifier.split_whitespace();
    let direction = tokens.next()?.to_ascii_lowercase();
    let weekday = tokens.next()?;
    if tokens.next().is_some() {
        return None;
    }
    let target = weekday_number_from_name(weekday)?;
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let delta_days = match direction.as_str() {
        "next" => {
            let mut delta = target - parts.weekday;
            if delta <= 0 {
                delta += 7;
            }
            delta
        }
        "last" => {
            let mut delta = target - parts.weekday;
            if delta >= 0 {
                delta -= 7;
            }
            delta
        }
        _ => return None,
    };
    apply_bounded_local_seconds(timestamp, timezone, delta_days * 86_400)
}

fn apply_bounded_n_weekday_modifier(
    timestamp: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<i64> {
    let mut tokens = modifier.split_whitespace();
    let count = parse_signed_ascii_i64(tokens.next()?)?;
    let unit = tokens.next()?.to_ascii_lowercase();
    if tokens.next().is_some() || !matches!(unit.as_str(), "weekday" | "weekdays") {
        return None;
    }
    if count == 0 {
        return Some(timestamp);
    }
    let direction = count.signum();
    let mut remaining = count.abs();
    let mut delta_days = 0_i64;
    while remaining > 0 {
        delta_days = delta_days.checked_add(direction)?;
        let candidate = apply_bounded_local_seconds(timestamp, timezone, delta_days * 86_400)?;
        let parts = bounded_datetime_parts(candidate, timezone.offset_at_timestamp(candidate));
        if (1..=5).contains(&parts.weekday) {
            remaining -= 1;
        }
    }
    apply_bounded_local_seconds(timestamp, timezone, delta_days * 86_400)
}

fn apply_bounded_relative_calendar_modifier(
    timestamp: i64,
    microsecond: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<(i64, i64)> {
    let lower = modifier.to_ascii_lowercase();
    let tokens: Vec<&str> = lower.split_whitespace().collect();
    if tokens.is_empty() {
        return None;
    }

    if tokens.len() >= 2 && tokens[0] == "this" && tokens[1] == "week" {
        let base = bounded_this_week_base(timestamp, timezone)?;
        return apply_bounded_modifier_tail(base, microsecond, timezone, &tokens[2..]);
    }

    if tokens.len() >= 3 && tokens[1] == "this" && tokens[2] == "week" {
        let weekday = weekday_number_from_name(tokens[0])?;
        let base = bounded_this_week_base(timestamp, timezone)?;
        let delta_days = if weekday == 0 { 6 } else { weekday - 1 };
        let base = timestamp_with_local_day_delta(base, timezone, delta_days)?;
        return apply_bounded_modifier_tail(base, microsecond, timezone, &tokens[3..]);
    }

    let timestamp = match tokens.as_slice() {
        ["first", "day"] => timestamp_with_local_month_day_delta(timestamp, timezone, 0, 1)?,
        ["last", "day"] => timestamp_with_local_month_day_delta(timestamp, timezone, 0, -1)?,
        ["next", "month"] => timestamp_with_local_month_day_delta(timestamp, timezone, 1, 0)?,
        ["first", "day", "next", "month"] => {
            timestamp_with_local_month_day_delta(timestamp, timezone, 1, 1)?
        }
        ["last", "day", "next", "month"] => {
            timestamp_with_local_month_day_delta(timestamp, timezone, 1, -1)?
        }
        ["first", "day", "of", "next", "month"] => {
            timestamp_with_local_first_day_of_next_month(timestamp, timezone)?
        }
        ["last", "day", "of", "next", "month"] => {
            timestamp_with_local_last_day_of_next_month(timestamp, timezone)?
        }
        _ => return None,
    };
    Some((timestamp, microsecond))
}

fn apply_bounded_modifier_tail(
    timestamp: i64,
    microsecond: i64,
    timezone: &BoundedTimezone,
    tokens: &[&str],
) -> Option<(i64, i64)> {
    if tokens.is_empty() {
        return Some((timestamp, microsecond));
    }
    apply_bounded_unit_modifier(timestamp, microsecond, timezone, &tokens.join(" "))
}

fn bounded_this_week_base(timestamp: i64, timezone: &BoundedTimezone) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let delta_days = if parts.weekday == 0 {
        -6
    } else {
        1 - parts.weekday
    };
    timestamp_with_local_day_delta(timestamp, timezone, delta_days)
}

fn timestamp_with_local_day_delta(
    timestamp: i64,
    timezone: &BoundedTimezone,
    day_delta: i64,
) -> Option<i64> {
    timestamp_with_local_month_day_delta(timestamp, timezone, 0, day_delta)
}

fn timestamp_with_local_month_day_delta(
    timestamp: i64,
    timezone: &BoundedTimezone,
    month_delta: i64,
    day_delta: i64,
) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    timestamp_from_overflowing_local_parts(
        parts.year,
        parts.month.checked_add(month_delta)?,
        parts.day.checked_add(day_delta)?,
        parts.hour,
        parts.minute,
        parts.second,
        timezone,
    )
}

fn timestamp_with_local_first_day_of_next_month(
    timestamp: i64,
    timezone: &BoundedTimezone,
) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    timestamp_from_overflowing_local_parts(
        parts.year,
        parts.month.checked_add(1)?,
        1,
        parts.hour,
        parts.minute,
        parts.second,
        timezone,
    )
}

fn timestamp_with_local_last_day_of_next_month(
    timestamp: i64,
    timezone: &BoundedTimezone,
) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    timestamp_from_overflowing_local_parts(
        parts.year,
        parts.month.checked_add(2)?,
        0,
        parts.hour,
        parts.minute,
        parts.second,
        timezone,
    )
}

fn apply_bounded_unit_modifier(
    timestamp: i64,
    microsecond: i64,
    timezone: &BoundedTimezone,
    modifier: &str,
) -> Option<(i64, i64)> {
    let mut tokens = modifier.split_whitespace().peekable();
    let mut years = 0_i64;
    let mut months = 0_i64;
    let mut days = 0_i64;
    let mut total_seconds = 0_i64;
    let mut total_microseconds = 0_i64;
    while let Some(token) = tokens.next() {
        let (count, unit_token) = if token == "+" || token == "-" {
            let sign = if token == "-" { -1 } else { 1 };
            let number = parse_ascii_i64(tokens.next()?)?;
            (sign * number, tokens.next()?)
        } else if let Some((count, unit_token)) = parse_joined_count_unit_token(token) {
            (count, unit_token)
        } else {
            let (sign, digits) = match token.as_bytes().first()? {
                b'+' => (1, &token[1..]),
                b'-' => (-1, &token[1..]),
                _ => (1, token),
            };
            let number = parse_ascii_i64(digits)?;
            (sign * number, tokens.next()?)
        };
        match unit_token.to_ascii_lowercase().as_str() {
            "year" | "years" => years = years.checked_add(count)?,
            "month" | "months" => months = months.checked_add(count)?,
            "week" | "weeks" => days = days.checked_add(count.checked_mul(7)?)?,
            "day" | "days" => days = days.checked_add(count)?,
            "hour" | "hours" => {
                total_seconds = total_seconds.checked_add(count.checked_mul(3_600)?)?;
            }
            "minute" | "minutes" => {
                total_seconds = total_seconds.checked_add(count.checked_mul(60)?)?;
            }
            "sec" | "secs" | "second" | "seconds" => {
                total_seconds = total_seconds.checked_add(count)?;
            }
            "s" => {}
            "ms" | "msec" | "msecs" | "millisecond" | "milliseconds" => {
                total_microseconds = total_microseconds.checked_add(count.checked_mul(1_000)?)?;
            }
            "usec" | "usecs" | "microsecond" | "microseconds" | "µs" | "µsec" | "µsecs" => {
                total_microseconds = total_microseconds.checked_add(count)?;
            }
            _ => return None,
        };
    }
    let mut timestamp = if years != 0 || months != 0 || days != 0 {
        let offset = timezone.offset_at_timestamp(timestamp);
        let parts = bounded_datetime_parts(timestamp, offset);
        timestamp_from_overflowing_local_parts(
            parts.year.checked_add(years)?,
            parts.month.checked_add(months)?,
            parts.day.checked_add(days)?,
            parts.hour,
            parts.minute,
            parts.second,
            timezone,
        )?
    } else {
        timestamp
    };
    if total_seconds != 0 {
        timestamp = apply_bounded_local_seconds(timestamp, timezone, total_seconds)?;
    }
    if total_microseconds != 0 {
        return Some(normalize_timestamp_microsecond(
            timestamp,
            microsecond.checked_add(total_microseconds)?,
        ));
    }
    Some((timestamp, microsecond))
}

fn parse_joined_count_unit_token(token: &str) -> Option<(i64, &str)> {
    let (sign, rest) = match token.as_bytes().first()? {
        b'+' => (1, &token[1..]),
        b'-' => (-1, &token[1..]),
        _ => (1, token),
    };
    let digit_end = rest
        .char_indices()
        .take_while(|(_, ch)| ch.is_ascii_digit())
        .last()
        .map(|(index, ch)| index + ch.len_utf8())?;
    if digit_end == 0 || digit_end == rest.len() {
        return None;
    }
    let unit = &rest[digit_end..];
    if !unit.chars().all(|ch| ch.is_ascii_alphabetic()) {
        return None;
    }
    Some((sign * parse_ascii_i64(&rest[..digit_end])?, unit))
}

fn apply_bounded_local_seconds(
    timestamp: i64,
    timezone: &BoundedTimezone,
    seconds: i64,
) -> Option<i64> {
    let local = timestamp
        .checked_add(timezone.offset_at_timestamp(timestamp))?
        .checked_add(seconds)?;
    let parts = bounded_datetime_parts(local, 0);
    let offset = timezone.offset_for_local_parts(
        parts.year,
        parts.month,
        parts.day,
        parts.hour,
        parts.minute,
        parts.second,
    );
    local.checked_sub(offset)
}

fn parse_bounded_at_timestamp(input: &str) -> Option<i64> {
    parse_bounded_at_timestamp_with_microsecond(input).map(|(timestamp, _)| timestamp)
}

fn parse_bounded_at_timestamp_with_microsecond(input: &str) -> Option<(i64, i64)> {
    let rest = input.strip_prefix('@')?;
    let mut end = 0;
    for (index, ch) in rest.char_indices() {
        if index == 0 && (ch == '-' || ch == '+') {
            end = ch.len_utf8();
            continue;
        }
        if ch.is_ascii_digit() {
            end = index + ch.len_utf8();
            continue;
        }
        break;
    }
    if end == 0 || rest[..end].chars().all(|ch| ch == '-' || ch == '+') {
        return None;
    }
    let integer = rest[..end].parse::<i64>().ok()?;
    let mut microsecond = 0_i64;
    if let Some(fraction) = rest[end..].strip_prefix('.') {
        let fraction_end = fraction
            .char_indices()
            .take_while(|(_, ch)| ch.is_ascii_digit())
            .last()
            .map(|(index, ch)| index + ch.len_utf8())
            .unwrap_or(0);
        if fraction_end == 0 {
            return None;
        }
        microsecond = parse_microsecond_fraction(&fraction[..fraction_end])?;
    }
    let microsecond_delta = if rest.starts_with('-') {
        -microsecond
    } else {
        microsecond
    };
    Some(normalize_timestamp_microsecond(integer, microsecond_delta))
}

fn parse_bounded_numeric_datetime_with_microsecond(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<(i64, i64)> {
    let (body, explicit_timezone) = split_bounded_datetime_timezone_or_name(input);
    let separator_index = body.find(' ').or_else(|| body.find('T'))?;
    let date = &body[..separator_index];
    let time = &body[separator_index + 1..];
    let (time, microsecond) = if let Some((time, fraction)) = time.split_once('.') {
        (time, parse_microsecond_fraction(fraction)?)
    } else {
        (time, 0)
    };
    let has_seconds = time.len() == 8;
    if date.len() != 10 || !(time.len() == 5 || has_seconds) {
        return None;
    }
    if &date[4..5] != "-"
        || &date[7..8] != "-"
        || &time[2..3] != ":"
        || (has_seconds && &time[5..6] != ":")
    {
        return None;
    }
    let year = parse_ascii_i64(&date[0..4])?;
    let month = parse_ascii_i64(&date[5..7])?;
    let day = parse_ascii_i64(&date[8..10])?;
    let hour = parse_ascii_i64(&time[0..2])?;
    let minute = parse_ascii_i64(&time[3..5])?;
    let second = if has_seconds {
        parse_ascii_i64(&time[6..8])?
    } else {
        0
    };
    let explicit_offset = explicit_timezone_offset(
        explicit_timezone.as_ref(),
        year,
        month,
        day,
        hour,
        minute,
        second,
    );
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
    .map(|timestamp| (timestamp, microsecond))
}

fn parse_bounded_dmy_datetime_with_microsecond(
    input: &str,
    default_timezone: &BoundedTimezone,
) -> Option<(i64, i64)> {
    let (body, explicit_timezone) = split_bounded_datetime_timezone_or_name(input);
    let (date, time) = body.split_once(' ')?;
    if date.len() != 10 || &date[2..3] != "-" || &date[5..6] != "-" {
        return None;
    }
    let day = parse_ascii_i64(&date[0..2])?;
    let month = parse_ascii_i64(&date[3..5])?;
    let year = normalize_mktime_year(parse_ascii_i64(&date[6..10])?, true);
    let (hour, minute, second, microsecond) = parse_bounded_time_with_microsecond(time)?;
    let explicit_offset = explicit_timezone_offset(
        explicit_timezone.as_ref(),
        year,
        month,
        day,
        hour,
        minute,
        second,
    );
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
    .map(|timestamp| (timestamp, microsecond))
}

fn parse_bounded_time_with_microsecond(input: &str) -> Option<(i64, i64, i64, i64)> {
    let (time, microsecond) = if let Some((time, fraction)) = input.split_once('.') {
        (time, parse_microsecond_fraction(fraction)?)
    } else {
        (input, 0)
    };
    let has_seconds = time.len() == 8;
    if !(time.len() == 5 || has_seconds)
        || &time[2..3] != ":"
        || (has_seconds && &time[5..6] != ":")
    {
        return None;
    }
    let hour = parse_ascii_i64(&time[0..2])?;
    let minute = parse_ascii_i64(&time[3..5])?;
    let second = if has_seconds {
        parse_ascii_i64(&time[6..8])?
    } else {
        0
    };
    Some((hour, minute, second, microsecond))
}

fn parse_microsecond_fraction(fraction: &str) -> Option<i64> {
    if fraction.is_empty() || fraction.len() > 6 || !fraction.chars().all(|ch| ch.is_ascii_digit())
    {
        return None;
    }
    let mut padded = fraction.to_string();
    while padded.len() < 6 {
        padded.push('0');
    }
    parse_ascii_i64(&padded)
}

fn normalize_timestamp_microsecond(timestamp: i64, microsecond_delta: i64) -> (i64, i64) {
    let total = (timestamp as i128)
        .saturating_mul(1_000_000)
        .saturating_add(microsecond_delta as i128);
    let seconds = total.div_euclid(1_000_000);
    let micros = total.rem_euclid(1_000_000);
    (
        seconds.clamp(i64::MIN as i128, i64::MAX as i128) as i64,
        micros as i64,
    )
}

fn parse_bounded_textual_datetime(input: &str, default_timezone: &BoundedTimezone) -> Option<i64> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.len() < 4 {
        return None;
    }
    let (day, month, year, hour, minute, second, timezone_token) =
        if weekday_number_from_name(tokens[0]).is_some() && tokens.len() >= 5 {
            let month = month_number_from_name(tokens[1])?;
            let day = parse_ascii_i64(tokens[2])?;
            if let Some((hour, minute, second)) = parse_hms_token(tokens[3]) {
                (
                    day,
                    month,
                    normalize_mktime_year(parse_ascii_i64(tokens[4])?, true),
                    hour,
                    minute,
                    second,
                    tokens.get(5).copied(),
                )
            } else {
                let year = normalize_mktime_year(parse_ascii_i64(tokens[3])?, true);
                let (hour, minute, second) = parse_hms_token(tokens[4])?;
                (
                    day,
                    month,
                    year,
                    hour,
                    minute,
                    second,
                    tokens.get(5).copied(),
                )
            }
        } else {
            let day = parse_ascii_i64(tokens[0])?;
            let month = month_number_from_name(tokens[1])?;
            let year = normalize_mktime_year(parse_ascii_i64(tokens[2])?, true);
            let (hour, minute, second) = parse_hms_token(tokens[3])?;
            (
                day,
                month,
                year,
                hour,
                minute,
                second,
                tokens.get(4).copied(),
            )
        };
    let explicit_offset = timezone_token.and_then(parse_timezone_offset_token);
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        explicit_offset,
        default_timezone,
    )
}

fn split_bounded_datetime_timezone(input: &str) -> (&str, Option<i64>) {
    let (body, timezone) = split_bounded_datetime_timezone_or_name(input);
    (body, timezone.and_then(|timezone| timezone.fixed_offset))
}

fn split_bounded_datetime_timezone_or_name(input: &str) -> (&str, Option<BoundedTimezone>) {
    if let Some((body, token)) = input.rsplit_once(' ') {
        if let Some(offset) = parse_timezone_offset_token(token) {
            return (body, Some(BoundedTimezone::numeric_fixed_offset(offset)));
        }
        if let Some(timezone) = bounded_timezone_from_name(token) {
            return (body, Some(timezone));
        }
    }
    for suffix_len in [9_usize, 6] {
        if input.len() > suffix_len {
            let suffix = &input[input.len() - suffix_len..];
            if !matches!(suffix.as_bytes().first(), Some(b'+') | Some(b'-')) {
                continue;
            }
            if let Some(offset) = parse_timezone_offset_token(suffix) {
                return (
                    &input[..input.len() - suffix_len],
                    Some(BoundedTimezone::numeric_fixed_offset(offset)),
                );
            }
        }
    }
    for suffix_len in [4_usize, 3, 1] {
        if input.len() > suffix_len {
            let suffix = &input[input.len() - suffix_len..];
            if suffix_len == 1
                && input[..input.len() - suffix_len]
                    .chars()
                    .last()
                    .is_some_and(|ch| ch.is_ascii_alphabetic())
            {
                continue;
            }
            if suffix.chars().all(|ch| ch.is_ascii_alphabetic()) {
                if let Some(offset) = parse_timezone_offset_token(suffix) {
                    return (
                        &input[..input.len() - suffix_len],
                        Some(BoundedTimezone::numeric_fixed_offset(offset)),
                    );
                }
            }
        }
    }
    for suffix_len in [7_usize, 6, 5, 4, 3] {
        if input.len() > suffix_len {
            let suffix = &input[input.len() - suffix_len..];
            if !matches!(suffix.as_bytes().first(), Some(b'+') | Some(b'-')) {
                continue;
            }
            if let Some(offset) = parse_timezone_offset_token(suffix) {
                return (
                    &input[..input.len() - suffix_len],
                    Some(BoundedTimezone::numeric_fixed_offset(offset)),
                );
            }
        }
    }
    (input, None)
}

fn explicit_timezone_offset(
    timezone: Option<&BoundedTimezone>,
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
) -> Option<i64> {
    timezone.map(|timezone| timezone.offset_for_local_parts(year, month, day, hour, minute, second))
}

fn parse_timezone_offset_token(token: &str) -> Option<i64> {
    match token.to_ascii_uppercase().as_str() {
        "UTC" | "GMT" | "Z" => return Some(0),
        "A" => return Some(3_600),
        "B" => return Some(7_200),
        "C" => return Some(10_800),
        "D" => return Some(14_400),
        "E" => return Some(18_000),
        "F" => return Some(21_600),
        "G" => return Some(25_200),
        "H" => return Some(28_800),
        "I" => return Some(32_400),
        "K" => return Some(36_000),
        "L" => return Some(39_600),
        "M" => return Some(43_200),
        "N" => return Some(-3_600),
        "O" => return Some(-7_200),
        "P" => return Some(-10_800),
        "Q" => return Some(-14_400),
        "R" => return Some(-18_000),
        "S" => return Some(-21_600),
        "T" => return Some(-25_200),
        "U" => return Some(-28_800),
        "V" => return Some(-32_400),
        "W" => return Some(-36_000),
        "X" => return Some(-39_600),
        "Y" => return Some(-43_200),
        "CEST" => return Some(7_200),
        "CET" => return Some(3_600),
        "EDT" => return Some(-14_400),
        "EST" => return Some(-18_000),
        "ADT" => return Some(-10_800),
        "AST" => return Some(-14_400),
        _ => {}
    }

    let sign = match token.as_bytes().first()? {
        b'+' => 1,
        b'-' => -1,
        _ => return None,
    };
    let (hours, minutes, seconds) = if token[1..].contains(':') {
        let parts = token[1..].split(':').collect::<Vec<_>>();
        if !(2..=3).contains(&parts.len())
            || parts.iter().any(|part| {
                part.is_empty() || part.len() > 2 || !part.chars().all(|ch| ch.is_ascii_digit())
            })
        {
            return None;
        }
        (
            parse_ascii_i64(parts[0])?,
            parse_ascii_i64(parts[1])?,
            if let Some(part) = parts.get(2) {
                parse_ascii_i64(part)?
            } else {
                0
            },
        )
    } else {
        let digits = &token[1..];
        if !matches!(digits.len(), 2 | 4 | 6) || !digits.chars().all(|ch| ch.is_ascii_digit()) {
            return None;
        }
        if digits.len() == 2 {
            (parse_ascii_i64(digits)?, 0, 0)
        } else if digits.len() == 4 {
            (
                parse_ascii_i64(&digits[0..2])?,
                parse_ascii_i64(&digits[2..4])?,
                0,
            )
        } else {
            (
                parse_ascii_i64(&digits[0..2])?,
                parse_ascii_i64(&digits[2..4])?,
                parse_ascii_i64(&digits[4..6])?,
            )
        }
    };
    if hours > 23 || minutes > 59 || seconds > 59 {
        return None;
    }
    Some(sign * (hours * 3_600 + minutes * 60 + seconds))
}

fn clean_rfc_timezone_comment_token(token: &str) -> &str {
    clean_strtotime_token(token)
        .strip_prefix('(')
        .and_then(|token| token.strip_suffix(')'))
        .unwrap_or_else(|| clean_strtotime_token(token))
}

fn timestamp_for_bounded_parts(
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
    explicit_offset: Option<i64>,
    default_timezone: &BoundedTimezone,
) -> Option<i64> {
    if !(1..=12).contains(&month)
        || day < 1
        || day > days_in_month(year, month)
        || !(0..=23).contains(&hour)
        || !(0..=59).contains(&minute)
        || !(0..=59).contains(&second)
    {
        return None;
    }
    let offset = explicit_offset.unwrap_or_else(|| {
        default_timezone.offset_for_local_parts(year, month, day, hour, minute, second)
    });
    Some(timestamp_from_local_parts(
        year, month, day, hour, minute, second, offset,
    ))
}

fn parse_hms_token(token: &str) -> Option<(i64, i64, i64)> {
    if token.len() != 8 || &token[2..3] != ":" || &token[5..6] != ":" {
        return None;
    }
    Some((
        parse_ascii_i64(&token[0..2])?,
        parse_ascii_i64(&token[3..5])?,
        parse_ascii_i64(&token[6..8])?,
    ))
}

fn parse_ascii_i64(value: &str) -> Option<i64> {
    if value.is_empty() || !value.chars().all(|ch| ch.is_ascii_digit()) {
        return None;
    }
    value.parse::<i64>().ok()
}

fn month_number_from_name(name: &str) -> Option<i64> {
    match name.to_ascii_lowercase().as_str() {
        "jan" | "january" => Some(1),
        "feb" | "february" => Some(2),
        "mar" | "march" => Some(3),
        "apr" | "april" => Some(4),
        "may" => Some(5),
        "jun" | "june" => Some(6),
        "jul" | "july" => Some(7),
        "aug" | "august" => Some(8),
        "sep" | "september" => Some(9),
        "oct" | "october" => Some(10),
        "nov" | "november" => Some(11),
        "dec" | "december" => Some(12),
        _ => None,
    }
}

fn weekday_number_from_name(name: &str) -> Option<i64> {
    match name.to_ascii_lowercase().as_str() {
        "sun" | "sunday" => Some(0),
        "mon" | "monday" => Some(1),
        "tue" | "tuesday" => Some(2),
        "wed" | "wednesday" => Some(3),
        "thu" | "thursday" => Some(4),
        "fri" | "friday" => Some(5),
        "sat" | "saturday" => Some(6),
        _ => None,
    }
}

fn bounded_month_is_in_dst_window(
    month: i64,
    day: i64,
    start_month: i64,
    start_day: i64,
    end_month: i64,
    end_day: i64,
) -> bool {
    (month > start_month || (month == start_month && day >= start_day))
        && (month < end_month || (month == end_month && day < end_day))
}

fn us_eastern_transition_days(year: i64) -> (i64, i64) {
    (
        nth_weekday_day_of_month(year, 3, 0, 2),
        nth_weekday_day_of_month(year, 11, 0, 1),
    )
}

fn us_eastern_legacy_transition_days(year: i64) -> (i64, i64) {
    (
        nth_weekday_day_of_month(year, 4, 0, 1),
        last_weekday_day_of_month(year, 10, 0),
    )
}

fn europe_transition_days(year: i64) -> (i64, i64) {
    (
        last_weekday_day_of_month(year, 3, 0),
        last_weekday_day_of_month(year, 10, 0),
    )
}

fn us_eastern_transition_utc_timestamps(year: i64) -> (i64, i64) {
    let (spring_day, fall_day) = us_eastern_transition_days(year);
    (
        timestamp_from_local_parts(year, 3, spring_day, 2, 0, 0, -18_000),
        timestamp_from_local_parts(year, 11, fall_day, 2, 0, 0, -14_400),
    )
}

fn us_eastern_legacy_transition_utc_timestamps(year: i64) -> (i64, i64) {
    let (spring_day, fall_day) = us_eastern_legacy_transition_days(year);
    (
        timestamp_from_local_parts(year, 4, spring_day, 2, 0, 0, -18_000),
        timestamp_from_local_parts(year, 10, fall_day, 2, 0, 0, -14_400),
    )
}

fn nth_weekday_day_of_month(year: i64, month: i64, weekday: i64, nth: i64) -> i64 {
    let first_weekday = positive_mod(days_from_civil(year, month, 1) + 4, 7);
    1 + positive_mod(weekday - first_weekday, 7) + (nth - 1) * 7
}

fn last_weekday_day_of_month(year: i64, month: i64, weekday: i64) -> i64 {
    let last_day = days_in_month(year, month);
    let last_weekday = positive_mod(days_from_civil(year, month, last_day) + 4, 7);
    last_day - positive_mod(last_weekday - weekday, 7)
}

fn optional_date_int_arg(
    function: &str,
    value: Option<&Value>,
    label: &str,
    span: Span,
) -> CompileResult<Option<i64>> {
    match value {
        Some(value) => integer_argument_current_subset(function, label, value, span).map(Some),
        None => Ok(None),
    }
}

fn validate_datetime_microsecond(
    function: &str,
    position: usize,
    microsecond: i64,
    span: Span,
) -> CompileResult<()> {
    if (0..=999_999).contains(&microsecond) {
        return Ok(());
    }
    Err(date_range_error(
        span,
        format!(
            "{function}: Argument #{position} ($microsecond) must be between 0 and 999999, {microsecond} given"
        ),
    ))
}

fn optional_timestamp_arg(
    function: &str,
    value: Option<&Value>,
    span: Span,
) -> CompileResult<Option<i64>> {
    match value {
        Some(Value::Int(value)) => Ok(Some(*value)),
        Some(Value::Null) | None => Ok(None),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "timestamp argument must be int or null in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn normalize_mktime_year(year: i64, explicit: bool) -> i64 {
    if !explicit {
        return year;
    }
    match year {
        0..=69 => 2000 + year,
        70..=100 => 1900 + year,
        _ => year,
    }
}

fn timestamp_from_local_parts(
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
    offset: i64,
) -> i64 {
    let (normalized_year, normalized_month) = normalize_year_month(year, month);
    let days = days_from_civil(normalized_year, normalized_month, 1) + day - 1;
    days * 86_400 + hour * 3_600 + minute * 60 + second - offset
}

fn timestamp_from_overflowing_local_parts(
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
    timezone: &BoundedTimezone,
) -> Option<i64> {
    let (normalized_year, normalized_month) = normalize_year_month_checked(year, month)?;
    let base_days = checked_days_from_civil(normalized_year, normalized_month, 1)?
        .checked_add(day.checked_sub(1)?)?;
    let total_seconds = hour
        .checked_mul(3_600)?
        .checked_add(minute.checked_mul(60)?)?
        .checked_add(second)?;
    let day_delta = div_floor(total_seconds, 86_400);
    let seconds_of_day = total_seconds.checked_sub(day_delta.checked_mul(86_400)?)?;
    let local_days = base_days.checked_add(day_delta)?;
    let local_day_seconds = local_days.checked_mul(86_400)?;
    let (offset_year, offset_month, offset_day) = civil_from_days(local_days);
    let offset_hour = seconds_of_day / 3_600;
    let offset_minute = (seconds_of_day % 3_600) / 60;
    let offset_second = seconds_of_day % 60;
    let offset = timezone.offset_for_local_parts(
        offset_year,
        offset_month,
        offset_day,
        offset_hour,
        offset_minute,
        offset_second,
    );
    local_day_seconds
        .checked_add(seconds_of_day)?
        .checked_sub(offset)
}

fn iso_week_date_to_civil(year: i64, week: i64, day_of_week: i64) -> Option<(i64, i64, i64)> {
    let jan4_days = checked_days_from_civil(year, 1, 4)?;
    let jan4_weekday = positive_mod(jan4_days.checked_add(4)?, 7);
    let jan4_iso_weekday = if jan4_weekday == 0 { 7 } else { jan4_weekday };
    let week_delta_days = week.checked_sub(1)?.checked_mul(7)?;
    let day_delta = day_of_week.checked_sub(1)?;
    let target_days = jan4_days
        .checked_sub(jan4_iso_weekday - 1)?
        .checked_add(week_delta_days)?
        .checked_add(day_delta)?;
    target_days.checked_mul(86_400)?;
    Some(civil_from_days(target_days))
}

fn normalize_year_month(year: i64, month: i64) -> (i64, i64) {
    let zero_based = month - 1;
    let year_delta = div_floor(zero_based, 12);
    let normalized_month = zero_based - year_delta * 12 + 1;
    (year + year_delta, normalized_month)
}

fn normalize_year_month_checked(year: i64, month: i64) -> Option<(i64, i64)> {
    let zero_based = month.checked_sub(1)?;
    let year_delta = div_floor(zero_based, 12);
    let normalized_month = zero_based
        .checked_sub(year_delta.checked_mul(12)?)?
        .checked_add(1)?;
    Some((year.checked_add(year_delta)?, normalized_month))
}

fn div_floor(value: i64, divisor: i64) -> i64 {
    let mut quotient = value / divisor;
    let remainder = value % divisor;
    if remainder != 0 && ((remainder > 0) != (divisor > 0)) {
        quotient -= 1;
    }
    quotient
}

fn div_mod_floor(value: i64, divisor: i64) -> (i64, i64) {
    let quotient = div_floor(value, divisor);
    (quotient, value - quotient * divisor)
}

fn days_from_civil(mut year: i64, month: i64, day: i64) -> i64 {
    year -= i64::from(month <= 2);
    let era = div_floor(year, 400);
    let yoe = year - era * 400;
    let month_prime = month + if month > 2 { -3 } else { 9 };
    let doy = (153 * month_prime + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

fn checked_days_from_civil(year: i64, month: i64, day: i64) -> Option<i64> {
    let year = year.checked_sub(i64::from(month <= 2))?;
    let era = div_floor(year, 400);
    let yoe = year.checked_sub(era.checked_mul(400)?)?;
    let month_prime = month.checked_add(if month > 2 { -3 } else { 9 })?;
    let doy = month_prime
        .checked_mul(153)?
        .checked_add(2)?
        .checked_div(5)?
        .checked_add(day)?
        .checked_sub(1)?;
    let doe = yoe
        .checked_mul(365)?
        .checked_add(yoe / 4)?
        .checked_sub(yoe / 100)?
        .checked_add(doy)?;
    era.checked_mul(146_097)?
        .checked_add(doe)?
        .checked_sub(719_468)
}

fn bounded_datetime_parts(timestamp: i64, offset: i64) -> BoundedDateTimeParts {
    let local = timestamp + offset;
    let (days, seconds_of_day) = div_mod_floor(local, 86_400);
    let (year, month, day) = civil_from_days(days);
    let hour = seconds_of_day / 3_600;
    let minute = (seconds_of_day % 3_600) / 60;
    let second = seconds_of_day % 60;
    let weekday = positive_mod(days + 4, 7);
    let yday = days - days_from_civil(year, 1, 1);
    BoundedDateTimeParts {
        year,
        month,
        day,
        hour,
        minute,
        second,
        weekday,
        yday,
        offset,
    }
}

fn positive_mod(value: i64, modulus: i64) -> i64 {
    let result = value % modulus;
    if result < 0 {
        result + modulus
    } else {
        result
    }
}

fn format_bounded_strftime(format: &str, timestamp: i64, timezone: &BoundedTimezone) -> String {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let mut output = String::new();
    let mut chars = format.chars();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            output.push(ch);
            continue;
        }
        let Some(token) = chars.next() else {
            output.push('%');
            break;
        };
        output.push_str(&format_bounded_strftime_token(
            token, timestamp, timezone, &parts,
        ));
    }
    output
}

fn format_bounded_strftime_token(
    token: char,
    timestamp: i64,
    timezone: &BoundedTimezone,
    parts: &BoundedDateTimeParts,
) -> String {
    match token {
        '%' => "%".to_string(),
        'a' => weekday_name(parts.weekday, false).to_string(),
        'A' => weekday_name(parts.weekday, true).to_string(),
        'b' | 'h' => month_name(parts.month, false).to_string(),
        'B' => month_name(parts.month, true).to_string(),
        'C' => zero_pad(div_floor(parts.year, 100), 2),
        'c' => format!(
            "{} {} {:>2} {}:{}:{} {}",
            weekday_name(parts.weekday, false),
            month_name(parts.month, false),
            parts.day,
            zero_pad(parts.hour, 2),
            zero_pad(parts.minute, 2),
            zero_pad(parts.second, 2),
            zero_pad(parts.year, 4)
        ),
        'D' => format!(
            "{}/{}/{}",
            zero_pad(parts.month, 2),
            zero_pad(parts.day, 2),
            zero_pad(positive_mod(parts.year, 100), 2)
        ),
        'd' => zero_pad(parts.day, 2),
        'e' => format!("{:>2}", parts.day),
        'F' => format!(
            "{}-{}-{}",
            zero_pad(parts.year, 4),
            zero_pad(parts.month, 2),
            zero_pad(parts.day, 2)
        ),
        'G' => iso_year_week(*parts).0.to_string(),
        'g' => zero_pad(positive_mod(iso_year_week(*parts).0, 100), 2),
        'H' => zero_pad(parts.hour, 2),
        'I' => zero_pad(twelve_hour(parts.hour), 2),
        'j' => zero_pad(parts.yday + 1, 3),
        'k' => format!("{:>2}", parts.hour),
        'l' => format!("{:>2}", twelve_hour(parts.hour)),
        'm' => zero_pad(parts.month, 2),
        'M' => zero_pad(parts.minute, 2),
        'n' => "\n".to_string(),
        'p' => {
            if parts.hour < 12 {
                "AM".to_string()
            } else {
                "PM".to_string()
            }
        }
        'P' => {
            if parts.hour < 12 {
                "am".to_string()
            } else {
                "pm".to_string()
            }
        }
        'R' => format!("{}:{}", zero_pad(parts.hour, 2), zero_pad(parts.minute, 2)),
        'r' => format!(
            "{}:{}:{} {}",
            zero_pad(twelve_hour(parts.hour), 2),
            zero_pad(parts.minute, 2),
            zero_pad(parts.second, 2),
            if parts.hour < 12 { "AM" } else { "PM" }
        ),
        'S' => zero_pad(parts.second, 2),
        's' => timestamp.to_string(),
        'T' | 'X' => format!(
            "{}:{}:{}",
            zero_pad(parts.hour, 2),
            zero_pad(parts.minute, 2),
            zero_pad(parts.second, 2)
        ),
        't' => "\t".to_string(),
        'u' => {
            if parts.weekday == 0 {
                "7".to_string()
            } else {
                parts.weekday.to_string()
            }
        }
        'U' => zero_pad(strftime_week_number(*parts, false), 2),
        'V' => zero_pad(iso_year_week(*parts).1, 2),
        'w' => parts.weekday.to_string(),
        'W' => zero_pad(strftime_week_number(*parts, true), 2),
        'x' => format!(
            "{}/{}/{}",
            zero_pad(parts.month, 2),
            zero_pad(parts.day, 2),
            zero_pad(positive_mod(parts.year, 100), 2)
        ),
        'y' => zero_pad(positive_mod(parts.year, 100), 2),
        'Y' => zero_pad(parts.year, 4),
        'z' => format_timezone_offset(parts.offset, false),
        'Z' => timezone.abbreviation(parts),
        other => format!("%{other}"),
    }
}

fn strftime_week_number(parts: BoundedDateTimeParts, monday_first: bool) -> i64 {
    let first_day = if monday_first {
        positive_mod(parts.weekday + 6, 7)
    } else {
        parts.weekday
    };
    (parts.yday + 7 - first_day) / 7
}

fn format_bounded_date(format: &str, timestamp: i64, timezone: &BoundedTimezone) -> String {
    format_bounded_date_with_microsecond(format, timestamp, timezone, 0)
}

fn format_bounded_date_with_microsecond(
    format: &str,
    timestamp: i64,
    timezone: &BoundedTimezone,
    microsecond: i64,
) -> String {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let mut output = String::new();
    let mut escaped = false;
    for ch in format.chars() {
        if escaped {
            output.push(ch);
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        output.push_str(&format_bounded_date_token(
            ch,
            timestamp,
            timezone,
            &parts,
            microsecond,
        ));
    }
    if escaped {
        output.push('\\');
    }
    output
}

fn format_bounded_date_token(
    token: char,
    timestamp: i64,
    timezone: &BoundedTimezone,
    parts: &BoundedDateTimeParts,
    microsecond: i64,
) -> String {
    match token {
        'd' => zero_pad(parts.day, 2),
        'D' => weekday_name(parts.weekday, false).to_string(),
        'j' => parts.day.to_string(),
        'l' => weekday_name(parts.weekday, true).to_string(),
        'N' => {
            if parts.weekday == 0 {
                "7".to_string()
            } else {
                parts.weekday.to_string()
            }
        }
        'S' => ordinal_suffix(parts.day).to_string(),
        'w' => parts.weekday.to_string(),
        'z' => parts.yday.to_string(),
        'W' => zero_pad(iso_year_week(*parts).1, 2),
        'F' => month_name(parts.month, true).to_string(),
        'm' => zero_pad(parts.month, 2),
        'M' => month_name(parts.month, false).to_string(),
        'n' => parts.month.to_string(),
        't' => days_in_month(parts.year, parts.month).to_string(),
        'L' => {
            if is_leap_year(parts.year) {
                "1".to_string()
            } else {
                "0".to_string()
            }
        }
        'o' => iso_year_week(*parts).0.to_string(),
        'Y' => zero_pad(parts.year, 4),
        'X' => {
            if parts.year >= 0 {
                format!("+{}", zero_pad(parts.year, 4))
            } else {
                zero_pad(parts.year, 4)
            }
        }
        'y' => zero_pad(positive_mod(parts.year, 100), 2),
        'a' => {
            if parts.hour < 12 {
                "am".to_string()
            } else {
                "pm".to_string()
            }
        }
        'A' => {
            if parts.hour < 12 {
                "AM".to_string()
            } else {
                "PM".to_string()
            }
        }
        'B' => swatch_internet_time(timestamp).to_string(),
        'g' => twelve_hour(parts.hour).to_string(),
        'G' => parts.hour.to_string(),
        'h' => zero_pad(twelve_hour(parts.hour), 2),
        'H' => zero_pad(parts.hour, 2),
        'i' => zero_pad(parts.minute, 2),
        's' => zero_pad(parts.second, 2),
        'u' => zero_pad(microsecond, 6),
        'v' => zero_pad(microsecond / 1_000, 3),
        'e' => timezone.name.clone(),
        'I' => {
            if timezone.is_dst(parts) {
                "1".to_string()
            } else {
                "0".to_string()
            }
        }
        'O' => format_timezone_offset(parts.offset, false),
        'P' => format_timezone_offset(parts.offset, true),
        'T' => timezone.abbreviation(parts),
        'Z' => parts.offset.to_string(),
        'c' => format!(
            "{}-{}-{}T{}:{}:{}{}",
            zero_pad(parts.year, 4),
            zero_pad(parts.month, 2),
            zero_pad(parts.day, 2),
            zero_pad(parts.hour, 2),
            zero_pad(parts.minute, 2),
            zero_pad(parts.second, 2),
            format_timezone_offset(parts.offset, true)
        ),
        'r' => format!(
            "{}, {} {} {} {}:{}:{} {}",
            weekday_name(parts.weekday, false),
            zero_pad(parts.day, 2),
            month_name(parts.month, false),
            zero_pad(parts.year, 4),
            zero_pad(parts.hour, 2),
            zero_pad(parts.minute, 2),
            zero_pad(parts.second, 2),
            format_timezone_offset(parts.offset, false)
        ),
        'U' => timestamp.to_string(),
        other => other.to_string(),
    }
}

fn parse_bounded_dateinterval_iso(input: &str) -> Result<BoundedDateIntervalState, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(format!("Unknown or bad format ({input})"));
    }
    if trimmed.contains('/') {
        return Err(format!("Failed to parse interval ({input})"));
    }
    let chars = trimmed.chars().collect::<Vec<_>>();
    if chars.first() != Some(&'P') {
        return Err(format!("Unknown or bad format ({input})"));
    }

    let mut state = empty_bounded_dateinterval_state();
    let mut index = 1_usize;
    let mut in_time = false;
    let mut saw_component = false;
    while index < chars.len() {
        if chars[index] == 'T' {
            if in_time {
                return Err(format!("Unknown or bad format ({input})"));
            }
            in_time = true;
            index += 1;
            continue;
        }
        let start = index;
        while chars.get(index).is_some_and(|ch| ch.is_ascii_digit()) {
            index += 1;
        }
        if start == index {
            return Err(format!("Unknown or bad format ({input})"));
        }
        let number = chars[start..index]
            .iter()
            .collect::<String>()
            .parse::<i64>()
            .map_err(|_| format!("Unknown or bad format ({input})"))?;
        let Some(unit) = chars.get(index).copied() else {
            return Err(format!("Unknown or bad format ({input})"));
        };
        index += 1;
        match (unit, in_time) {
            ('Y', false) => state.years = number,
            ('M', false) => state.months = number,
            ('D', false) => state.days = number,
            ('H', true) => state.hours = number,
            ('M', true) => state.minutes = number,
            ('S', true) => state.seconds = number,
            _ => return Err(format!("Unknown or bad format ({input})")),
        }
        saw_component = true;
    }

    if !saw_component {
        return Err(format!("Unknown or bad format ({input})"));
    }
    Ok(state)
}

fn parse_bounded_dateperiod_iso(
    input: &str,
    function: &str,
) -> Result<ParsedBoundedDatePeriodIso, String> {
    let trimmed = input.trim();
    let parts = trimmed.split('/').collect::<Vec<_>>();
    if parts.len() == 1 {
        return Err(format!(
            "{function}: ISO interval must contain a start date, \"{trimmed}\" given"
        ));
    }
    if parts.len() == 2 {
        if !parts[0].starts_with('R') {
            return Err(format!(
                "{function}: Recurrence count must be greater or equal to 1 and lower than {}",
                i64::MAX
            ));
        }
        return Err(format!(
            "{function}: ISO interval must contain an interval, \"{trimmed}\" given"
        ));
    }
    if parts.len() != 3 {
        return Err(format!("Unknown or bad format ({trimmed})"));
    }
    let recurrence_token = parts[0];
    let Some(recurrence_digits) = recurrence_token.strip_prefix('R') else {
        return Err(format!(
            "{function}: Recurrence count must be greater or equal to 1 and lower than {}",
            i64::MAX
        ));
    };
    let recurrences = parse_ascii_i64(recurrence_digits).unwrap_or(0);
    if recurrences <= 0 {
        return Err(format!(
            "{function}: Recurrence count must be greater or equal to 1 and lower than {}",
            i64::MAX
        ));
    }
    let start_timestamp = parse_bounded_dateperiod_iso_start(parts[1])
        .ok_or_else(|| format!("Unknown or bad format ({trimmed})"))?;
    let interval = parse_bounded_dateinterval_iso(parts[2])
        .map_err(|_| format!("Unknown or bad format ({trimmed})"))?;
    Ok(ParsedBoundedDatePeriodIso {
        recurrences,
        start_timestamp,
        interval,
    })
}

fn parse_bounded_dateperiod_iso_start(input: &str) -> Option<i64> {
    let bytes = input.as_bytes();
    if bytes.len() != 20
        || bytes[4] != b'-'
        || bytes[7] != b'-'
        || bytes[10] != b'T'
        || bytes[13] != b':'
        || bytes[16] != b':'
        || bytes[19] != b'Z'
    {
        return None;
    }
    for range in [0..4, 5..7, 8..10, 11..13, 14..16, 17..19] {
        if !bytes[range].iter().all(u8::is_ascii_digit) {
            return None;
        }
    }
    let year = parse_ascii_i64(&input[0..4])?;
    let month = parse_ascii_i64(&input[5..7])?;
    let day = parse_ascii_i64(&input[8..10])?;
    let hour = parse_ascii_i64(&input[11..13])?;
    let minute = parse_ascii_i64(&input[14..16])?;
    let second = parse_ascii_i64(&input[17..19])?;
    timestamp_for_bounded_parts(
        year,
        month,
        day,
        hour,
        minute,
        second,
        Some(0),
        &BoundedTimezone::numeric_fixed_offset(0),
    )
}

fn parse_bounded_dateinterval_relative(input: &str) -> Result<BoundedDateIntervalState, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(bounded_dateinterval_relative_error(input));
    }
    if trimmed.eq_ignore_ascii_case("tomorrow") {
        let mut state = empty_bounded_dateinterval_state();
        state.days = 1;
        state.from_string = true;
        state.date_string = Some(trimmed.to_string());
        return Ok(state);
    }
    if bounded_dateinterval_contains_non_relative_element(trimmed) {
        return Err(format!("String '{trimmed}' contains non-relative elements"));
    }
    let mut tokens = trimmed.split_whitespace().filter(|token| *token != "+");
    let mut state = empty_bounded_dateinterval_state();
    state.from_string = true;
    state.date_string = Some(trimmed.to_string());
    let mut saw_component = false;

    while let Some(number_token) = tokens.next() {
        let number = parse_signed_ascii_i64(number_token)
            .ok_or_else(|| bounded_dateinterval_relative_error(input))?;
        let unit = tokens
            .next()
            .ok_or_else(|| bounded_dateinterval_relative_error(input))?;
        match unit.to_ascii_lowercase().as_str() {
            "year" | "years" => state.years += number,
            "month" | "months" => state.months += number,
            "week" | "weeks" => state.days += number * 7,
            "day" | "days" => state.days += number,
            "hour" | "hours" => state.hours += number,
            "minute" | "minutes" => state.minutes += number,
            "second" | "seconds" => state.seconds += number,
            _ => return Err(bounded_dateinterval_relative_error(input)),
        }
        saw_component = true;
    }

    if saw_component {
        Ok(state)
    } else {
        Err(bounded_dateinterval_relative_error(input))
    }
}

fn bounded_dateinterval_relative_error(input: &str) -> String {
    let first = input.chars().next().unwrap_or(' ');
    if input.is_empty() {
        format!("Unknown or bad format ({input}) at position 0 ({first}): Empty string")
    } else {
        format!(
            "Unknown or bad format ({input}) at position 0 ({first}): The timezone could not be found in the database"
        )
    }
}

fn bounded_dateinterval_contains_non_relative_element(input: &str) -> bool {
    input
        .split_whitespace()
        .any(|token| bounded_dateinterval_non_relative_token(token))
}

fn bounded_dateinterval_non_relative_token(token: &str) -> bool {
    if token.contains(':') {
        return true;
    }
    matches!(
        token.to_ascii_lowercase().as_str(),
        "january"
            | "jan"
            | "february"
            | "feb"
            | "march"
            | "mar"
            | "april"
            | "apr"
            | "may"
            | "june"
            | "jun"
            | "july"
            | "jul"
            | "august"
            | "aug"
            | "september"
            | "sep"
            | "october"
            | "oct"
            | "november"
            | "nov"
            | "december"
            | "dec"
            | "noon"
            | "midnight"
            | "utc"
            | "gmt"
    )
}

fn empty_bounded_dateinterval_state() -> BoundedDateIntervalState {
    BoundedDateIntervalState {
        years: 0,
        months: 0,
        days: 0,
        hours: 0,
        minutes: 0,
        seconds: 0,
        fraction: 0.0,
        invert: 0,
        total_days: None,
        from_string: false,
        date_string: None,
    }
}

fn format_bounded_dateinterval(format: &str, interval: &BoundedDateIntervalState) -> String {
    let mut output = String::new();
    let mut chars = format.chars();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            output.push(ch);
            continue;
        }
        let Some(token) = chars.next() else {
            output.push('%');
            break;
        };
        output.push_str(&format_bounded_dateinterval_token(token, interval));
    }
    output
}

fn format_bounded_dateinterval_token(token: char, interval: &BoundedDateIntervalState) -> String {
    match token {
        '%' => "%".to_string(),
        'Y' => zero_pad(interval.years, 2),
        'M' => zero_pad(interval.months, 2),
        'D' => zero_pad(interval.days, 2),
        'H' => zero_pad(interval.hours, 2),
        'I' => zero_pad(interval.minutes, 2),
        'S' => zero_pad(interval.seconds, 2),
        'y' => interval.years.to_string(),
        'm' => interval.months.to_string(),
        'd' => interval.days.to_string(),
        'h' => interval.hours.to_string(),
        'i' => interval.minutes.to_string(),
        's' => interval.seconds.to_string(),
        'R' => {
            if interval.invert != 0 {
                "-".to_string()
            } else {
                "+".to_string()
            }
        }
        'r' => {
            if interval.invert != 0 {
                "-".to_string()
            } else {
                String::new()
            }
        }
        'a' => interval
            .total_days
            .map(|days| days.to_string())
            .unwrap_or_else(|| "(unknown)".to_string()),
        other => format!("%{other}"),
    }
}

fn apply_bounded_dateinterval_to_datetime(
    state: &BoundedDateTimeObjectState,
    interval: &BoundedDateIntervalState,
    subtract: bool,
) -> Option<(i64, i64)> {
    let sign = if (interval.invert != 0) ^ subtract {
        -1
    } else {
        1
    };
    let offset = state.timezone.offset_at_timestamp(state.timestamp);
    let parts = bounded_datetime_parts(state.timestamp, offset);

    let has_calendar_delta = interval.years != 0 || interval.months != 0 || interval.days != 0;
    let mut timestamp = if has_calendar_delta {
        let year = parts.year.checked_add(interval.years.checked_mul(sign)?)?;
        let month = parts
            .month
            .checked_add(interval.months.checked_mul(sign)?)?;
        let day = parts.day.checked_add(interval.days.checked_mul(sign)?)?;
        timestamp_from_overflowing_local_parts(
            year,
            month,
            day,
            parts.hour,
            parts.minute,
            parts.second,
            &state.timezone,
        )?
    } else {
        state.timestamp
    };

    let time_delta = interval
        .hours
        .checked_mul(3_600)?
        .checked_add(interval.minutes.checked_mul(60)?)?
        .checked_add(interval.seconds)?
        .checked_mul(sign)?;
    timestamp = timestamp.checked_add(time_delta)?;
    if interval.fraction == 0.0 {
        return Some((timestamp, state.microsecond));
    }

    let fraction_microseconds = dateinterval_fraction_microseconds(interval.fraction)?;
    let signed_fraction = fraction_microseconds.checked_mul(sign)?;
    let microsecond_delta = state.microsecond.checked_add(signed_fraction)?;
    Some(normalize_timestamp_microsecond(
        timestamp,
        microsecond_delta,
    ))
}

fn dateinterval_fraction_microseconds(fraction: f64) -> Option<i64> {
    if !fraction.is_finite() || !(0.0..1.0).contains(&fraction) {
        return None;
    }
    Some((fraction * 1_000_000.0).round() as i64)
}

fn bounded_datetime_diff_interval(
    source: &BoundedDateTimeObjectState,
    target: &BoundedDateTimeObjectState,
    absolute: bool,
) -> BoundedDateIntervalState {
    if source.microsecond == 0 && target.microsecond == 0 {
        return bounded_datetime_diff_interval_without_fraction(source, target, absolute);
    }

    let source_total = datetime_total_microseconds(source);
    let target_total = datetime_total_microseconds(target);
    let source_before_target = source_total <= target_total;
    let source_parts = bounded_datetime_parts(
        source.timestamp,
        source.timezone.offset_at_timestamp(source.timestamp),
    );
    let target_parts = bounded_datetime_parts(
        target.timestamp,
        target.timezone.offset_at_timestamp(target.timestamp),
    );

    let (years, months, days, hours, minutes, seconds) = bounded_datetime_diff_components(
        source,
        target,
        source_parts,
        target_parts,
        source_before_target,
    );
    let total_days = bounded_datetime_diff_total_days(
        source_parts,
        target_parts,
        years,
        months,
        days,
        source_before_target,
    );
    let (years, months, days, hours, minutes, seconds, fraction) =
        bounded_diff_components_with_fraction(
            years,
            months,
            days,
            hours,
            minutes,
            seconds,
            source.microsecond,
            target.microsecond,
            source_before_target,
        );

    BoundedDateIntervalState {
        years,
        months,
        days,
        hours,
        minutes,
        seconds,
        fraction,
        invert: if absolute || source_before_target {
            0
        } else {
            1
        },
        total_days: Some(total_days),
        from_string: false,
        date_string: None,
    }
}

fn bounded_datetime_diff_interval_without_fraction(
    source: &BoundedDateTimeObjectState,
    target: &BoundedDateTimeObjectState,
    absolute: bool,
) -> BoundedDateIntervalState {
    let source_before_target = source.timestamp <= target.timestamp;
    let source_parts = bounded_datetime_parts(
        source.timestamp,
        source.timezone.offset_at_timestamp(source.timestamp),
    );
    let target_parts = bounded_datetime_parts(
        target.timestamp,
        target.timezone.offset_at_timestamp(target.timestamp),
    );

    let (years, months, days, hours, minutes, seconds) = bounded_datetime_diff_components(
        source,
        target,
        source_parts,
        target_parts,
        source_before_target,
    );
    let total_days = bounded_datetime_diff_total_days(
        source_parts,
        target_parts,
        years,
        months,
        days,
        source_before_target,
    );

    BoundedDateIntervalState {
        years,
        months,
        days,
        hours,
        minutes,
        seconds,
        fraction: 0.0,
        invert: if absolute || source_before_target {
            0
        } else {
            1
        },
        total_days: Some(total_days),
        from_string: false,
        date_string: None,
    }
}

fn datetime_total_microseconds(state: &BoundedDateTimeObjectState) -> i128 {
    (state.timestamp as i128) * 1_000_000 + state.microsecond as i128
}

#[allow(clippy::too_many_arguments)]
fn bounded_diff_components_with_fraction(
    mut years: i64,
    mut months: i64,
    mut days: i64,
    mut hours: i64,
    mut minutes: i64,
    mut seconds: i64,
    source_microsecond: i64,
    target_microsecond: i64,
    source_before_target: bool,
) -> (i64, i64, i64, i64, i64, i64, f64) {
    let mut microseconds = if source_before_target {
        target_microsecond - source_microsecond
    } else {
        source_microsecond - target_microsecond
    };
    if microseconds < 0 {
        microseconds += 1_000_000;
        borrow_one_second_from_diff_components(
            &mut years,
            &mut months,
            &mut days,
            &mut hours,
            &mut minutes,
            &mut seconds,
        );
    }
    (
        years,
        months,
        days,
        hours,
        minutes,
        seconds,
        microseconds as f64 / 1_000_000.0,
    )
}

fn borrow_one_second_from_diff_components(
    _years: &mut i64,
    _months: &mut i64,
    days: &mut i64,
    hours: &mut i64,
    minutes: &mut i64,
    seconds: &mut i64,
) {
    if *seconds > 0 {
        *seconds -= 1;
    } else if *minutes > 0 {
        *minutes -= 1;
        *seconds = 59;
    } else if *hours > 0 {
        *hours -= 1;
        *minutes = 59;
        *seconds = 59;
    } else if *days > 0 {
        *days -= 1;
        *hours = 23;
        *minutes = 59;
        *seconds = 59;
    }
}

fn bounded_datetime_diff_components(
    source: &BoundedDateTimeObjectState,
    target: &BoundedDateTimeObjectState,
    source_parts: BoundedDateTimeParts,
    target_parts: BoundedDateTimeParts,
    source_before_target: bool,
) -> (i64, i64, i64, i64, i64, i64) {
    if let Some(components) = bounded_same_civil_day_transition_diff_components(
        source,
        target,
        source_parts,
        target_parts,
        source_before_target,
    ) {
        return components;
    }

    let components = if source_before_target {
        bounded_datetime_forward_diff_components(source_parts, target_parts)
    } else {
        bounded_datetime_backward_diff_components(source_parts, target_parts)
    };
    adjust_datetime_diff_components_for_offset_delta(
        components,
        source_parts.offset,
        target_parts.offset,
        source_before_target,
        source.timezone.fixed_offset.is_none() && target.timezone.fixed_offset.is_none(),
    )
    .unwrap_or(components)
}

fn adjust_datetime_diff_components_for_offset_delta(
    components: (i64, i64, i64, i64, i64, i64),
    source_offset: i64,
    target_offset: i64,
    source_before_target: bool,
    both_named_zones: bool,
) -> Option<(i64, i64, i64, i64, i64, i64)> {
    let (years, months, days, hours, minutes, seconds) = components;
    let offset_delta = if source_before_target {
        target_offset.checked_sub(source_offset)?
    } else {
        source_offset.checked_sub(target_offset)?
    };
    if offset_delta == 0 {
        return Some(components);
    }
    if both_named_zones && (years != 0 || months != 0 || days != 0) {
        return Some(components);
    }

    let total_seconds = days
        .checked_mul(86_400)?
        .checked_add(hours.checked_mul(3_600)?)?
        .checked_add(minutes.checked_mul(60)?)?
        .checked_add(seconds)?
        .checked_sub(offset_delta)?;
    if total_seconds < 0 {
        return None;
    }

    let days = total_seconds / 86_400;
    let remainder = total_seconds % 86_400;
    let hours = remainder / 3_600;
    let minutes = (remainder % 3_600) / 60;
    let seconds = remainder % 60;
    Some((years, months, days, hours, minutes, seconds))
}

fn bounded_same_civil_day_transition_diff_components(
    source: &BoundedDateTimeObjectState,
    target: &BoundedDateTimeObjectState,
    source_parts: BoundedDateTimeParts,
    target_parts: BoundedDateTimeParts,
    source_before_target: bool,
) -> Option<(i64, i64, i64, i64, i64, i64)> {
    if source.timestamp == target.timestamp
        || source_parts.year != target_parts.year
        || source_parts.month != target_parts.month
        || source_parts.day != target_parts.day
    {
        return None;
    }

    let source_second = local_second_of_day(source_parts);
    let target_second = local_second_of_day(target_parts);
    let wall_order_crosses_timestamp_order = if source_before_target {
        target_second <= source_second
    } else {
        source_second <= target_second
    };
    if !wall_order_crosses_timestamp_order {
        return None;
    }

    let delta = bounded_timestamp_delta_seconds(source.timestamp, target.timestamp);
    let days = delta / 86_400;
    let remainder = delta % 86_400;
    let hours = remainder / 3_600;
    let minutes = (remainder % 3_600) / 60;
    let seconds = remainder % 60;
    Some((0, 0, days, hours, minutes, seconds))
}

fn local_second_of_day(parts: BoundedDateTimeParts) -> i64 {
    parts.hour * 3_600 + parts.minute * 60 + parts.second
}

fn bounded_timestamp_delta_seconds(left: i64, right: i64) -> i64 {
    (left as i128 - right as i128).abs().min(i64::MAX as i128) as i64
}

fn bounded_datetime_diff_total_days(
    source: BoundedDateTimeParts,
    target: BoundedDateTimeParts,
    years: i64,
    months: i64,
    days: i64,
    source_before_target: bool,
) -> i64 {
    let source_days = days_from_civil(source.year, source.month, source.day);
    let fallback_target_days = days_from_civil(target.year, target.month, target.day);
    let sign = if source_before_target { 1 } else { -1 };
    let component_target_days = years
        .checked_mul(sign)
        .and_then(|year_delta| source.year.checked_add(year_delta))
        .zip(
            months
                .checked_mul(sign)
                .and_then(|month_delta| source.month.checked_add(month_delta)),
        )
        .zip(
            days.checked_mul(sign)
                .and_then(|day_delta| source.day.checked_add(day_delta)),
        )
        .and_then(|((year, month), day)| overflowing_civil_day_ordinal(year, month, day))
        .unwrap_or(fallback_target_days);
    bounded_day_delta(source_days, component_target_days)
}

fn overflowing_civil_day_ordinal(year: i64, month: i64, day: i64) -> Option<i64> {
    let (year, month) = normalize_year_month_checked(year, month)?;
    checked_days_from_civil(year, month, 1)?.checked_add(day.checked_sub(1)?)
}

fn bounded_day_delta(left: i64, right: i64) -> i64 {
    (left as i128 - right as i128).abs().min(i64::MAX as i128) as i64
}

fn bounded_datetime_forward_diff_components(
    start: BoundedDateTimeParts,
    end: BoundedDateTimeParts,
) -> (i64, i64, i64, i64, i64, i64) {
    let mut years = end.year - start.year;
    let mut months = end.month - start.month;
    let mut days = end.day - start.day;
    let mut hours = end.hour - start.hour;
    let mut minutes = end.minute - start.minute;
    let mut seconds = end.second - start.second;

    if seconds < 0 {
        seconds += 60;
        minutes -= 1;
    }
    if minutes < 0 {
        minutes += 60;
        hours -= 1;
    }
    if hours < 0 {
        hours += 24;
        days -= 1;
    }

    let mut borrow_year = end.year;
    let mut borrow_month = end.month;
    while days < 0 {
        months -= 1;
        let (year, month) = normalize_year_month(borrow_year, borrow_month - 1);
        days += days_in_month(year, month);
        borrow_year = year;
        borrow_month = month;
    }
    while months < 0 {
        months += 12;
        years -= 1;
    }

    (years, months, days, hours, minutes, seconds)
}

fn bounded_datetime_backward_diff_components(
    start: BoundedDateTimeParts,
    end: BoundedDateTimeParts,
) -> (i64, i64, i64, i64, i64, i64) {
    let mut years = start.year - end.year;
    let mut months = start.month - end.month;
    let mut days = start.day - end.day;
    let mut hours = start.hour - end.hour;
    let mut minutes = start.minute - end.minute;
    let mut seconds = start.second - end.second;

    if seconds < 0 {
        seconds += 60;
        minutes -= 1;
    }
    if minutes < 0 {
        minutes += 60;
        hours -= 1;
    }
    if hours < 0 {
        hours += 24;
        days -= 1;
    }

    let mut borrow_year = end.year;
    let mut borrow_month = end.month;
    while days < 0 {
        months -= 1;
        days += days_in_month(borrow_year, borrow_month);
        let (year, month) = normalize_year_month(borrow_year, borrow_month + 1);
        borrow_year = year;
        borrow_month = month;
    }
    while months < 0 {
        months += 12;
        years -= 1;
    }

    (years, months, days, hours, minutes, seconds)
}

fn parse_signed_ascii_i64(value: &str) -> Option<i64> {
    if let Some(rest) = value.strip_prefix('+') {
        parse_ascii_i64(rest)
    } else if let Some(rest) = value.strip_prefix('-') {
        parse_ascii_i64(rest)?.checked_neg()
    } else {
        parse_ascii_i64(value)
    }
}

fn bounded_idate_token(token: char, timestamp: i64, timezone: &BoundedTimezone) -> Option<i64> {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    match token {
        'B' => Some(swatch_internet_time_value(timestamp)),
        'd' => Some(parts.day),
        'h' => Some(twelve_hour(parts.hour)),
        'H' => Some(parts.hour),
        'i' => Some(parts.minute),
        'I' => Some(i64::from(timezone.is_dst(&parts))),
        'L' => Some(i64::from(is_leap_year(parts.year))),
        'm' => Some(parts.month),
        's' => Some(parts.second),
        't' => Some(days_in_month(parts.year, parts.month)),
        'U' => Some(timestamp),
        'N' => Some(if parts.weekday == 0 { 7 } else { parts.weekday }),
        'w' => Some(parts.weekday),
        'W' => Some(iso_year_week(parts).1),
        'o' => Some(iso_year_week(parts).0),
        'y' => Some(positive_mod(parts.year, 100)),
        'Y' => Some(parts.year),
        'z' => Some(parts.yday),
        'Z' => Some(parts.offset),
        _ => None,
    }
}

fn getdate_array(timestamp: i64, timezone: &BoundedTimezone) -> PhpArray {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let mut array = PhpArray::new();
    array.insert("seconds", Value::Int(parts.second));
    array.insert("minutes", Value::Int(parts.minute));
    array.insert("hours", Value::Int(parts.hour));
    array.insert("mday", Value::Int(parts.day));
    array.insert("wday", Value::Int(parts.weekday));
    array.insert("mon", Value::Int(parts.month));
    array.insert("year", Value::Int(parts.year));
    array.insert("yday", Value::Int(parts.yday));
    array.insert(
        "weekday",
        Value::String(weekday_name(parts.weekday, true).to_string()),
    );
    array.insert(
        "month",
        Value::String(month_name(parts.month, true).to_string()),
    );
    array.insert(0_i64, Value::Int(timestamp));
    array
}

fn localtime_array(timestamp: i64, timezone: &BoundedTimezone, associative: bool) -> PhpArray {
    let offset = timezone.offset_at_timestamp(timestamp);
    let parts = bounded_datetime_parts(timestamp, offset);
    let values = [
        ("tm_sec", parts.second),
        ("tm_min", parts.minute),
        ("tm_hour", parts.hour),
        ("tm_mday", parts.day),
        ("tm_mon", parts.month - 1),
        ("tm_year", parts.year - 1900),
        ("tm_wday", parts.weekday),
        ("tm_yday", parts.yday),
        ("tm_isdst", i64::from(timezone.is_dst(&parts))),
    ];
    let mut array = PhpArray::new();
    for (name, value) in values {
        if associative {
            array.insert(name, Value::Int(value));
        } else {
            array
                .append(Value::Int(value))
                .expect("bounded localtime array append should not exhaust integer keys");
        }
    }
    array
}

fn call_checkdate(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("checkdate", args, 3, span)?;
    let month = required_date_int_arg("checkdate()", &args[0], "month", span)?;
    let day = required_date_int_arg("checkdate()", &args[1], "day", span)?;
    let year = required_date_int_arg("checkdate()", &args[2], "year", span)?;
    Ok(Value::Bool(
        (1..=32767).contains(&year)
            && (1..=12).contains(&month)
            && day >= 1
            && day <= days_in_month(year, month),
    ))
}

fn calendar_gregorian_to_jd(month: i64, day: i64, year: i64) -> i64 {
    if !(1..=12).contains(&month) || day < 1 || day > days_in_month(year, month) {
        return 0;
    }
    let astronomical_year = php_calendar_year_to_astronomical(year);
    let a = (14 - month) / 12;
    let y = astronomical_year + 4800 - a;
    let m = month + 12 * a - 3;
    let jd = day + (153 * m + 2) / 5 + 365 * y + y / 4 - y / 100 + y / 400 - 32_045;
    if jd < 1 {
        0
    } else {
        jd
    }
}

fn calendar_jd_to_gregorian(jd: i64) -> (i64, i64, i64) {
    if jd < 1 {
        return (0, 0, 0);
    }
    let mut l = jd + 68_569;
    let n = 4 * l / 146_097;
    l -= (146_097 * n + 3) / 4;
    let i = 4_000 * (l + 1) / 1_461_001;
    l = l - 1_461 * i / 4 + 31;
    let j = 80 * l / 2_447;
    let day = l - 2_447 * j / 80;
    l = j / 11;
    let month = j + 2 - 12 * l;
    let astronomical_year = 100 * (n - 49) + i + l;
    (
        month,
        day,
        astronomical_calendar_year_to_php(astronomical_year),
    )
}

fn calendar_julian_to_jd(month: i64, day: i64, year: i64) -> i64 {
    if !(1..=12).contains(&month) || day < 1 || day > julian_days_in_month(year, month) {
        return 0;
    }
    let astronomical_year = php_calendar_year_to_astronomical(year);
    let a = (14 - month) / 12;
    let y = astronomical_year + 4800 - a;
    let m = month + 12 * a - 3;
    let jd = day + (153 * m + 2) / 5 + 365 * y + y / 4 - 32_083;
    if jd < 1 {
        0
    } else {
        jd
    }
}

fn calendar_jd_to_julian(jd: i64) -> (i64, i64, i64) {
    if jd < 1 {
        return (0, 0, 0);
    }
    let c = jd + 32_082;
    let d = (4 * c + 3) / 1_461;
    let e = c - 1_461 * d / 4;
    let m = (5 * e + 2) / 153;
    let day = e - (153 * m + 2) / 5 + 1;
    let month = m + 3 - 12 * (m / 10);
    let astronomical_year = d - 4_800 + (m / 10);
    (
        month,
        day,
        astronomical_calendar_year_to_php(astronomical_year),
    )
}

fn php_calendar_year_to_astronomical(year: i64) -> i64 {
    if year < 0 {
        year + 1
    } else {
        year
    }
}

fn astronomical_calendar_year_to_php(year: i64) -> i64 {
    if year <= 0 {
        year - 1
    } else {
        year
    }
}

fn julian_days_in_month(year: i64, month: i64) -> i64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if julian_is_leap_year(year) => 29,
        2 => 28,
        _ => 0,
    }
}

fn julian_is_leap_year(year: i64) -> bool {
    php_calendar_year_to_astronomical(year).rem_euclid(4) == 0
}

fn unix_timestamp_to_jd(timestamp: i64) -> i64 {
    div_floor(timestamp, 86_400) + 2_440_588
}

fn jd_to_unix_timestamp(jd: i64) -> Option<i64> {
    jd.checked_sub(2_440_588)?.checked_mul(86_400)
}

fn calendar_day_of_week(jd: i64) -> i64 {
    positive_mod(jd + 1, 7)
}

fn required_date_int_arg(
    function: &str,
    value: &Value,
    label: &str,
    span: Span,
) -> CompileResult<i64> {
    integer_argument_current_subset(function, label, value, span)
}

fn weekday_name(weekday: i64, full: bool) -> &'static str {
    const FULL: [&str; 7] = [
        "Sunday",
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
    ];
    const SHORT: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let index = usize::try_from(positive_mod(weekday, 7)).unwrap_or(0);
    if full {
        FULL[index]
    } else {
        SHORT[index]
    }
}

fn month_name(month: i64, full: bool) -> &'static str {
    const FULL: [&str; 12] = [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
    ];
    const SHORT: [&str; 12] = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    let index = usize::try_from((month - 1).clamp(0, 11)).unwrap_or(0);
    if full {
        FULL[index]
    } else {
        SHORT[index]
    }
}

fn ordinal_suffix(day: i64) -> &'static str {
    match day % 100 {
        11..=13 => "th",
        _ => match day % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    }
}

fn twelve_hour(hour: i64) -> i64 {
    let value = hour % 12;
    if value == 0 {
        12
    } else {
        value
    }
}

fn zero_pad(value: i64, width: usize) -> String {
    if value < 0 {
        format!("-{:0width$}", value.abs(), width = width)
    } else {
        format!("{:0width$}", value, width = width)
    }
}

fn format_timezone_offset(offset: i64, colon: bool) -> String {
    let sign = if offset < 0 { '-' } else { '+' };
    let absolute = offset.abs();
    let hours = absolute / 3_600;
    let minutes = (absolute % 3_600) / 60;
    if colon {
        format!("{sign}{hours:02}:{minutes:02}")
    } else {
        format!("{sign}{hours:02}{minutes:02}")
    }
}

fn format_timezone_offset_name(offset: i64) -> String {
    let sign = if offset < 0 { '-' } else { '+' };
    let absolute = offset.abs();
    let hours = absolute / 3_600;
    let minutes = (absolute % 3_600) / 60;
    let seconds = absolute % 60;
    if seconds == 0 {
        format!("{sign}{hours:02}:{minutes:02}")
    } else {
        format!("{sign}{hours:02}:{minutes:02}:{seconds:02}")
    }
}

fn swatch_internet_time(timestamp: i64) -> String {
    zero_pad(swatch_internet_time_value(timestamp), 3)
}

fn swatch_internet_time_value(timestamp: i64) -> i64 {
    let seconds = positive_mod(timestamp + 3_600, 86_400);
    seconds * 1_000 / 86_400
}

fn is_leap_year(year: i64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn days_in_month(year: i64, month: i64) -> i64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if is_leap_year(year) => 29,
        2 => 28,
        _ => 0,
    }
}

fn iso_year_week(parts: BoundedDateTimeParts) -> (i64, i64) {
    let iso_weekday = if parts.weekday == 0 { 7 } else { parts.weekday };
    let mut week = (parts.yday + 10 - iso_weekday) / 7;
    let mut year = parts.year;
    if week < 1 {
        year -= 1;
        week = iso_weeks_in_year(year);
    } else {
        let weeks_in_year = iso_weeks_in_year(year);
        if week > weeks_in_year {
            year += 1;
            week = 1;
        }
    }
    (year, week)
}

fn iso_weeks_in_year(year: i64) -> i64 {
    let jan1_weekday = positive_mod(days_from_civil(year, 1, 1) + 4, 7);
    if jan1_weekday == 4 || (jan1_weekday == 3 && is_leap_year(year)) {
        53
    } else {
        52
    }
}

