fn php_ini_truthy(value: &str) -> bool {
    let value = value.trim();
    !value.is_empty()
        && !matches!(
            value.to_ascii_lowercase().as_str(),
            "0" | "off" | "false" | "no" | "none" | "disable" | "disabled"
        )
}

fn request_parse_body_option_key_is_supported(key: &str) -> bool {
    matches!(
        key.to_ascii_lowercase().as_str(),
        "max_file_uploads"
            | "max_input_vars"
            | "max_multipart_body_parts"
            | "post_max_size"
            | "upload_max_filesize"
    )
}

fn request_parse_body_option_value_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Float(_) => "float",
        Value::Array(_) => "array",
        Value::Object(_) | Value::Closure(_) => "object",
        Value::Resource(_) => "resource",
        Value::Int(_) => "int",
        Value::String(_) | Value::BinaryString(_) => "string",
    }
}

fn request_parse_body_value_error(span: Span, message: impl Into<String>) -> Diagnostic {
    runtime_error(
        span,
        RuntimeError::unsupported_call("request_parse_body()", message.into()),
    )
}

fn mysqli_default_port_ini_value_is_valid(value: &str) -> bool {
    match value.trim().parse::<i64>() {
        Ok(port) => (0..=65535).contains(&port),
        Err(_) => false,
    }
}

fn parse_ini_i64_prefix(value: &str) -> Option<i64> {
    parse_ini_numeric_prefix(value).and_then(|value| {
        if value.is_finite() && value >= i64::MIN as f64 && value <= i64::MAX as f64 {
            Some(value.trunc() as i64)
        } else {
            None
        }
    })
}

fn parse_ini_f64_prefix(value: &str) -> Option<f64> {
    parse_ini_numeric_prefix(value).filter(|value| value.is_finite())
}

fn parse_ini_numeric_prefix(value: &str) -> Option<f64> {
    let value = value.trim();
    if value.is_empty() {
        return None;
    }

    let mut end = 0;
    let mut saw_digit = false;
    for (index, ch) in value.char_indices() {
        if ch.is_ascii_digit() {
            saw_digit = true;
            end = index + ch.len_utf8();
            continue;
        }
        if matches!(ch, '+' | '-') && index == 0 {
            end = index + ch.len_utf8();
            continue;
        }
        if ch == '.' {
            end = index + ch.len_utf8();
            continue;
        }
        break;
    }

    if !saw_digit {
        return None;
    }
    value[..end].parse::<f64>().ok()
}

fn parse_ini_size_bytes(value: &str) -> Option<i64> {
    let trimmed = value.trim();
    let number = parse_ini_i64_prefix(trimmed)?;
    let suffix = trimmed
        .chars()
        .rev()
        .find(|ch| ch.is_ascii_alphabetic())
        .map(|ch| ch.to_ascii_lowercase());
    let multiplier = match suffix {
        Some('g') => 1024_i64 * 1024 * 1024,
        Some('m') => 1024_i64 * 1024,
        Some('k') => 1024_i64,
        _ => 1024_i64 * 1024,
    };
    number.checked_mul(multiplier)
}

struct IniQuantityValue {
    value: i64,
    warning: Option<String>,
}

struct IniQuantityNumber {
    value: i64,
    raw: u64,
    text: String,
    end: usize,
    overflow: bool,
}

fn parse_ini_quantity_value(value: &str) -> IniQuantityValue {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return IniQuantityValue {
            value: 0,
            warning: None,
        };
    }

    let Some(number) = parse_ini_quantity_integer_prefix(trimmed) else {
        let reason = if is_ini_quantity_bare_base_prefix(trimmed) {
            "no digits after base prefix"
        } else {
            "no valid leading digits"
        };
        return IniQuantityValue {
            value: 0,
            warning: Some(format!(
                "Invalid quantity \"{value}\": {reason}, interpreting as \"0\" for backwards compatibility"
            )),
        };
    };

    let suffix = trimmed[number.end..]
        .char_indices()
        .rev()
        .find(|(_, ch)| !ch.is_whitespace())
        .map(|(index, ch)| (number.end + index, ch));

    let Some((suffix_index, suffix)) = suffix else {
        return IniQuantityValue {
            value: number.value,
            warning: number.overflow.then(|| {
                format!(
                    "Invalid quantity \"{value}\": value is out of range, using overflow result for backwards compatibility"
                )
            }),
        };
    };

    let suffix_lower = suffix.to_ascii_lowercase();
    let multiplier = match suffix_lower {
        'g' => Some(1024_u64 * 1024 * 1024),
        'm' => Some(1024_u64 * 1024),
        'k' => Some(1024_u64),
        _ => None,
    };

    let Some(multiplier) = multiplier else {
        return IniQuantityValue {
            value: number.value,
            warning: Some(format!(
                "Invalid quantity \"{value}\": unknown multiplier \"{suffix}\", interpreting as \"{}\" for backwards compatibility",
                number.text
            )),
        };
    };

    let between = &trimmed[number.end..suffix_index];
    let malformed_suffix_warning = between.chars().any(|ch| !ch.is_whitespace()).then(|| {
        let whitespace_before_suffix = between
            .char_indices()
            .rev()
            .take_while(|(_, ch)| ch.is_whitespace())
            .map(|(_, ch)| ch)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect::<String>();
        format!(
            "Invalid quantity \"{value}\", interpreting as \"{}{whitespace_before_suffix}{suffix_lower}\" for backwards compatibility",
            number.text
        )
    });

    let multiplier_i64 = multiplier as i64;
    let multiplier_overflow = if number.value > 0 {
        number.value > i64::MAX / multiplier_i64
    } else {
        number.value < i64::MIN / multiplier_i64
    };
    let overflow = number.overflow || multiplier_overflow;
    let multiplied = number.raw.wrapping_mul(multiplier) as i64;

    IniQuantityValue {
        value: multiplied,
        warning: malformed_suffix_warning.or_else(|| {
            overflow.then(|| {
                format!(
                    "Invalid quantity \"{value}\": value is out of range, using overflow result for backwards compatibility"
                )
            })
        }),
    }
}

fn is_ini_quantity_bare_base_prefix(value: &str) -> bool {
    let value = value.trim();
    let value = value
        .strip_prefix('+')
        .or_else(|| value.strip_prefix('-'))
        .unwrap_or(value);
    matches!(value, "0x" | "0X")
}

fn parse_ini_quantity_integer_prefix(value: &str) -> Option<IniQuantityNumber> {
    let bytes = value.as_bytes();
    if bytes.is_empty() {
        return None;
    }

    let mut index = 0;
    let mut negative = false;
    if matches!(bytes.get(index), Some(b'+') | Some(b'-')) {
        negative = bytes[index] == b'-';
        index += 1;
    }

    if bytes.get(index) == Some(&b'0') && matches!(bytes.get(index + 1), Some(b'x') | Some(b'X')) {
        let digits_start = index + 2;
        let mut end = digits_start;
        while matches!(bytes.get(end), Some(byte) if byte.is_ascii_hexdigit()) {
            end += 1;
        }
        if end == digits_start {
            return None;
        }
        let (magnitude, magnitude_overflow) =
            parse_ini_quantity_unsigned_digits(&bytes[digits_start..end], 16);
        return Some(ini_quantity_signed_number(
            value[..end].to_string(),
            end,
            negative,
            magnitude,
            magnitude_overflow,
        ));
    }

    let digits_start = index;
    while matches!(bytes.get(index), Some(byte) if byte.is_ascii_digit()) {
        index += 1;
    }
    if index == digits_start {
        return None;
    }
    let (magnitude, magnitude_overflow) =
        parse_ini_quantity_unsigned_digits(&bytes[digits_start..index], 10);
    Some(ini_quantity_signed_number(
        value[..index].to_string(),
        index,
        negative,
        magnitude,
        magnitude_overflow,
    ))
}

fn parse_ini_quantity_unsigned_digits(digits: &[u8], base: u64) -> (u64, bool) {
    let mut value = 0_u64;
    let mut overflow = false;
    for byte in digits {
        let digit = match *byte {
            b'0'..=b'9' => u64::from(*byte - b'0'),
            b'a'..=b'f' => u64::from(*byte - b'a' + 10),
            b'A'..=b'F' => u64::from(*byte - b'A' + 10),
            _ => return (value, overflow),
        };
        match value
            .checked_mul(base)
            .and_then(|next| next.checked_add(digit))
        {
            Some(next) => value = next,
            None => {
                value = u64::MAX;
                overflow = true;
            }
        }
    }
    (value, overflow)
}

fn ini_quantity_signed_number(
    text: String,
    end: usize,
    negative: bool,
    magnitude: u64,
    magnitude_overflow: bool,
) -> IniQuantityNumber {
    let mut raw = magnitude;
    let mut overflow = magnitude_overflow;
    if negative {
        if !overflow && raw == (i64::MAX as u64) + 1 {
            raw = 0_u64.wrapping_sub(raw);
        } else if (raw as i64) < 0 {
            overflow = true;
        } else {
            raw = 0_u64.wrapping_sub(raw);
        }
    } else if (raw as i64) < 0 {
        overflow = true;
    }

    IniQuantityNumber {
        value: raw as i64,
        raw,
        text,
        end,
        overflow,
    }
}

fn opcache_default_i64(name: &str) -> i64 {
    opcache_default_ini_value(name)
        .and_then(parse_ini_i64_prefix)
        .unwrap_or(0)
}

fn opcache_default_f64(name: &str) -> f64 {
    opcache_default_ini_value(name)
        .and_then(parse_ini_f64_prefix)
        .unwrap_or(0.0)
}

fn opcache_path_key(path: &str) -> String {
    let path = local_filesystem_metadata_path(path);
    fs::canonicalize(&path)
        .unwrap_or(path)
        .to_string_lossy()
        .into_owned()
}

fn opcache_script_status_entry(path: &str) -> Value {
    let mut entry = PhpArray::new();
    entry.insert("full_path".to_string(), Value::String(path.to_string()));
    entry.insert("hits".to_string(), Value::Int(0));
    entry.insert("memory_consumption".to_string(), Value::Int(0));
    entry.insert("last_used".to_string(), Value::String(String::new()));
    entry.insert("last_used_timestamp".to_string(), Value::Int(0));
    entry.insert("timestamp".to_string(), Value::Int(0));
    Value::Array(entry)
}

fn normalize_ini_name(name: &str) -> String {
    name.to_ascii_lowercase()
}

fn parse_ini_process_sections_argument(value: Option<&Value>, span: Span) -> CompileResult<bool> {
    match value {
        Some(Value::Bool(value)) => Ok(*value),
        Some(Value::Null) | None => Ok(false),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "parse_ini_*()",
                format!(
                    "process_sections argument must be bool in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn parse_ini_scanner_mode_argument(value: Option<&Value>, span: Span) -> CompileResult<i64> {
    match value {
        Some(Value::Int(mode))
            if matches!(
                *mode,
                PHP_INI_SCANNER_NORMAL | PHP_INI_SCANNER_RAW | PHP_INI_SCANNER_TYPED
            ) =>
        {
            Ok(*mode)
        }
        Some(Value::Null) | None => Ok(PHP_INI_SCANNER_NORMAL),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "parse_ini_*()",
                format!(
                    "scanner_mode argument must be a supported INI_SCANNER_* int in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

struct BoundedIniScalar {
    value: String,
    quoted: bool,
}

fn parse_bounded_ini(
    contents: &str,
    process_sections: bool,
    scanner_mode: i64,
) -> Result<PhpArray, String> {
    let mut root = PhpArray::new();
    let mut current_section: Option<(String, PhpArray)> = None;

    for (index, raw_line) in contents.lines().enumerate() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }

        validate_bounded_ini_interpolation(
            strip_bounded_ini_inline_comment(line).trim(),
            index + 1,
        )?;

        if line.starts_with('[') && line.ends_with(']') {
            if process_sections {
                if let Some((section, values)) = current_section.take() {
                    root.insert(section, Value::Array(values));
                }
                current_section =
                    Some((line[1..line.len() - 1].trim().to_string(), PhpArray::new()));
            }
            continue;
        }

        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let key = key.trim().to_string();
        let value = parse_bounded_ini_value(value.trim(), index + 1, scanner_mode)?;
        if process_sections {
            if let Some((_, values)) = current_section.as_mut() {
                values.insert(key, value);
            } else {
                root.insert(key, value);
            }
        } else {
            root.insert(key, value);
        }
    }

    if let Some((section, values)) = current_section {
        root.insert(section, Value::Array(values));
    }

    Ok(root)
}

fn parse_bounded_ini_value(value: &str, line: usize, scanner_mode: i64) -> Result<Value, String> {
    let scalar = parse_bounded_ini_scalar(value, line)?;
    if scanner_mode == PHP_INI_SCANNER_TYPED && !scalar.quoted {
        Ok(parse_bounded_ini_typed_scalar(&scalar.value))
    } else {
        Ok(Value::String(scalar.value))
    }
}

fn parse_bounded_ini_scalar(value: &str, line: usize) -> Result<BoundedIniScalar, String> {
    if let Some(rest) = value.strip_prefix('"') {
        if let Some(end) = rest.find('"') {
            return Ok(BoundedIniScalar {
                value: rest[..end].to_string(),
                quoted: true,
            });
        }
        return Err(format!(
            "syntax error, unexpected end of file, expecting TC_DOLLAR_CURLY or TC_QUOTED_STRING or '\"' in Unknown on line {line}\n"
        ));
    }

    if let Some(rest) = value.strip_prefix('\'') {
        if let Some(end) = rest.find('\'') {
            return Ok(BoundedIniScalar {
                value: rest[..end].to_string(),
                quoted: true,
            });
        }
    }

    let value = strip_bounded_ini_inline_comment(value).trim();
    validate_bounded_ini_interpolation(value, line)?;
    Ok(BoundedIniScalar {
        value: value.trim_matches('\'').to_string(),
        quoted: false,
    })
}

fn validate_bounded_ini_interpolation(value: &str, line: usize) -> Result<(), String> {
    if let Some(open) = value.find("${") {
        let interpolation = &value[open + 2..];
        if interpolation.contains(":-") {
            return Err(format!(
                "syntax error, unexpected TC_FALLBACK, expecting TC_VARNAME in Unknown on line {line}\n"
            ));
        }
        if !interpolation.contains('}') {
            return Err(format!(
                "syntax error, unexpected end of file, expecting TC_FALLBACK or '}}' in Unknown on line {line}\n"
            ));
        }
    }
    Ok(())
}

fn strip_bounded_ini_inline_comment(value: &str) -> &str {
    let mut escaped = false;
    for (index, ch) in value.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        if matches!(ch, ';' | '#') {
            return &value[..index];
        }
    }
    value
}

fn parse_bounded_ini_typed_scalar(value: &str) -> Value {
    match value.to_ascii_lowercase().as_str() {
        "true" | "on" | "yes" => return Value::Bool(true),
        "false" | "off" | "no" | "none" => return Value::Bool(false),
        "null" => return Value::Null,
        _ => {}
    }

    if is_ini_typed_int_literal(value) {
        if let Ok(parsed) = value.parse::<i64>() {
            return Value::Int(parsed);
        }
    }

    if is_ini_typed_float_literal(value) {
        if let Ok(parsed) = value.parse::<f64>() {
            if parsed.is_finite() {
                return Value::Float(parsed);
            }
        }
    }

    Value::String(value.to_string())
}

fn is_ini_typed_int_literal(value: &str) -> bool {
    let digits = value.strip_prefix('-').unwrap_or(value);
    !digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit())
}

fn is_ini_typed_float_literal(value: &str) -> bool {
    if value.starts_with('-') || value.starts_with('+') {
        return false;
    }

    let Some((left, right)) = value.split_once('.') else {
        return false;
    };
    if value.matches('.').count() != 1 {
        return false;
    }

    let left_digits = left.bytes().all(|byte| byte.is_ascii_digit());
    let right_digits = right.bytes().all(|byte| byte.is_ascii_digit());
    left_digits && right_digits && (!left.is_empty() || !right.is_empty())
}

fn ini_get_all_entry(
    global_value: String,
    local_value: String,
    builtin_default_value: Option<String>,
    details: bool,
) -> Value {
    if !details {
        return Value::String(local_value);
    }

    let mut entry = PhpArray::new();
    entry.insert("global_value".to_string(), Value::String(global_value));
    entry.insert("local_value".to_string(), Value::String(local_value));
    entry.insert("access".to_string(), Value::Int(7));
    entry.insert(
        "builtin_default_value".to_string(),
        builtin_default_value
            .map(Value::String)
            .unwrap_or(Value::Null),
    );
    Value::Array(entry)
}

fn compat_ini_builtin_default_value(normalized_name: &str) -> Option<&'static str> {
    match normalized_name {
        "error_append_string" | "error_prepend_string" => None,
        _ => compat_ini_value(normalized_name),
    }
}

fn parse_ini_error_reporting_mask(value: &str) -> Option<i64> {
    if value.trim_start().starts_with('~') {
        return Some(0);
    }

    let mut mask = None;
    let mut operator = '&';
    let mut start = 0;

    for (index, ch) in value.char_indices() {
        if !matches!(ch, '&' | '^' | '|') {
            continue;
        }

        let term = parse_error_reporting_mask_term(value[start..index].trim())?;
        mask = Some(match (mask, operator) {
            (None, _) => term,
            (Some(current), '&') => current & term,
            (Some(current), '^') => current ^ term,
            (Some(current), '|') => current | term,
            _ => return None,
        });
        operator = ch;
        start = index + ch.len_utf8();
    }

    let term = parse_error_reporting_mask_term(value[start..].trim())?;
    let mask = match (mask, operator) {
        (None, _) => term,
        (Some(current), '&') => current & term,
        (Some(current), '^') => current ^ term,
        (Some(current), '|') => current | term,
        _ => return None,
    };
    Some(mask)
}

fn normalize_initial_error_reporting_mask(mask: i64) -> i64 {
    if mask == (PHP_E_ALL | PHP_E_STRICT) {
        PHP_E_ALL
    } else {
        mask
    }
}

fn parse_error_reporting_mask_term(value: &str) -> Option<i64> {
    if let Some(rest) = value.strip_prefix('~') {
        return Some(!parse_error_reporting_term(rest.trim())?);
    }
    parse_error_reporting_term(value)
}

fn parse_error_reporting_term(value: &str) -> Option<i64> {
    match value {
        "E_ALL" => Some(PHP_E_ALL),
        "E_ERROR" => Some(PHP_E_ERROR),
        "E_WARNING" => Some(PHP_E_WARNING),
        "E_PARSE" => Some(PHP_E_PARSE),
        "E_NOTICE" => Some(PHP_E_NOTICE),
        "E_CORE_ERROR" => Some(PHP_E_CORE_ERROR),
        "E_CORE_WARNING" => Some(PHP_E_CORE_WARNING),
        "E_COMPILE_ERROR" => Some(PHP_E_COMPILE_ERROR),
        "E_COMPILE_WARNING" => Some(PHP_E_COMPILE_WARNING),
        "E_USER_ERROR" => Some(PHP_E_USER_ERROR),
        "E_USER_WARNING" => Some(PHP_E_USER_WARNING),
        "E_USER_NOTICE" => Some(PHP_E_USER_NOTICE),
        "E_STRICT" => Some(PHP_E_STRICT),
        "E_RECOVERABLE_ERROR" => Some(PHP_E_RECOVERABLE_ERROR),
        "E_DEPRECATED" => Some(PHP_E_DEPRECATED),
        "E_USER_DEPRECATED" => Some(PHP_E_USER_DEPRECATED),
        _ => value.parse::<i64>().ok(),
    }
}

