    #[test]
    fn array_copy_source_property_detach_checks_use_runtime_lvalue_handles() {
        let mut scope = SymbolTable::new();
        let leaf_key = ArrayKey::String("leaf".to_string());

        let leaf_cell = PhpReferenceCell::new(Value::String("shared".to_string()));
        let mut source_items = PhpArray::new();
        source_items.insert_reference(leaf_key.clone(), leaf_cell.clone());
        let source_cell = PhpReferenceCell::new(Value::Array(source_items));

        let mut classes = PhpClassTable::new();
        let class_id = classes.declare_class("Box").unwrap();
        let class = classes.get_mut(class_id).unwrap();
        class
            .add_property(PhpPropertyMetadata::instance("items", Visibility::Public))
            .unwrap();
        let object = PhpObject::from_class(class);
        object
            .bind_public_property_reference_cell("items", source_cell.clone())
            .unwrap();
        scope.write_static("box", Value::Object(object.clone()));

        let source = ArrayCopySource::runtime_cell(source_cell, Vec::new(), true);

        assert_eq!(
            scope.array_copy_source_mutation_impact_for_object_property_write(
                &source,
                &object,
                "items",
                &[]
            ),
            Some(ArrayCopySourceMutationImpact::ReplacesSourceOrAncestor)
        );
        scope.record_detached_object_property_array_offset_cell(
            &object,
            "items",
            std::slice::from_ref(&leaf_key),
            leaf_cell.clone(),
        );
        assert!(scope.array_copy_source_path_was_detached(&source, std::slice::from_ref(&leaf_key)));

        let detached = vec![(vec![leaf_key.clone()], leaf_cell.clone())];
        scope.mark_array_copy_source_dirty(source);
        let boundary =
            scope.holder_storage_mutation_boundary_for_object_property(&object, "items", &[]);
        let rehydrated = scope
            .array_copy_source_records_rehydrated_by_holder_storage_boundary(&boundary, &detached);
        let paths = rehydrated
            .iter()
            .find_map(|(record, paths)| {
                matches!(record.location, ArrayCopySourceRecordLocation::DirtySource)
                    .then_some(paths)
            })
            .expect("expected detached source paths through holder boundary");
        assert!(paths.iter().any(|(keys, cell)| {
            keys == std::slice::from_ref(&leaf_key) && cell.shares_reference_with(&leaf_cell)
        }));
    }

    #[test]
    fn array_copy_source_mutation_impact_distinguishes_source_and_child_paths() {
        let mut scope = SymbolTable::new();
        let outer_key = ArrayKey::String("outer".to_string());
        let leaf_key = ArrayKey::String("leaf".to_string());

        let source_cell = PhpReferenceCell::new(Value::Array(PhpArray::new()));
        let mut classes = PhpClassTable::new();
        let class_id = classes.declare_class("Box").unwrap();
        let class = classes.get_mut(class_id).unwrap();
        class
            .add_property(PhpPropertyMetadata::instance("items", Visibility::Public))
            .unwrap();
        let object = PhpObject::from_class(class);
        object
            .bind_public_property_reference_cell("items", source_cell.clone())
            .unwrap();
        scope.write_static("box", Value::Object(object.clone()));

        let source = ArrayCopySource::runtime_cell(
            source_cell,
            std::slice::from_ref(&outer_key).to_vec(),
            true,
        );

        assert_eq!(
            scope.array_copy_source_mutation_impact_for_object_property_write(
                &source,
                &object,
                "items",
                &[]
            ),
            Some(ArrayCopySourceMutationImpact::ReplacesSourceOrAncestor)
        );
        assert_eq!(
            scope.array_copy_source_mutation_impact_for_object_property_write(
                &source,
                &object,
                "items",
                &[outer_key.clone(), leaf_key]
            ),
            Some(ArrayCopySourceMutationImpact::ReplacesSelectedChildPath)
        );
        assert_eq!(
            scope.array_copy_source_mutation_impact_for_object_property_write(
                &source,
                &object,
                "items",
                &[ArrayKey::String("other".to_string())]
            ),
            None
        );
    }

